local function path_index_key(path)
  if not path or path == "" then
    return ""
  end
  path = tostring(path):gsub("\\", "/"):gsub("/+$", "")
  return string.lower(path)
end

local function rebuild_samples_path_index()
  samples_by_path = {}
  for _, s in ipairs(state.samples) do
    if s.path then
      samples_by_path[s.path] = s
      -- Also index forward-slash normalized form for analyzer path lookups
      local norm = tostring(s.path):gsub("\\", "/"):gsub("/+$", "")
      if norm ~= s.path then
        samples_by_path[norm] = s
      end
      -- External volumes (ExFAT/HFS) often change spelling/case on remount.
      local key = path_index_key(s.path)
      if key ~= "" and key ~= s.path and key ~= norm then
        samples_by_path[key] = s
      end
    end
  end
end

function lookup_sample_by_path(path)
  if not path or path == "" then
    return nil
  end
  local sample = samples_by_path[path]
  if sample then
    return sample
  end
  local norm = tostring(path):gsub("\\", "/"):gsub("/+$", "")
  sample = samples_by_path[norm]
  if sample then
    return sample
  end
  return samples_by_path[path_index_key(path)]
end


-- --- Helper functions ---------------------------------------------------------
local function log(msg)
end

local function add_scan_log(msg)
  local timestamp = os.date("%H:%M:%S")
  local line = string.format("[%s] %s", timestamp, tostring(msg))
  table.insert(state.scan_logs, line)
  if #state.scan_logs > 500 then
    table.remove(state.scan_logs, 1)
  end
end

local function get_scan_logs_text()
  return table.concat(state.scan_logs, "\n")
end


local function shell_escape(str)
  return '"' .. tostring(str):gsub('"', '\\"') .. '"'
end


-- Normalize path separators for macOS (ensure forward slashes)
local function normalize_path(path)
  if not path or path == "" then
    return path
  end
  -- Replace backslashes with forward slashes
  path = path:gsub("\\", "/")
  -- Remove trailing slash
  path = path:gsub("/+$", "")
  return path
end

-- Removable / external volume root for a path.
-- macOS: /Volumes/DriveName/...  Windows: E:/...
-- Internal paths (/Users/..., C:/Users/...) return nil — always treated as local.
local function volume_root_from_path(path)
  path = normalize_path(path or "")
  if path == "" then
    return nil
  end
  local vol = path:match("^(/Volumes/[^/]+)")
  if vol then
    return vol
  end
  -- Windows drive letters other than C: are commonly removable/external.
  local drive = path:match("^([A-Za-z]):")
  if drive and drive:upper() ~= "C" then
    return drive:upper() .. ":/"
  end
  return nil
end

local function volume_is_mounted(vol_root)
  vol_root = normalize_path(vol_root or "")
  if vol_root == "" then
    return true
  end

  local vol_name = vol_root:match("^/Volumes/(.+)$")
  if vol_name then
    local i = 0
    while true do
      local name = r.EnumerateSubdirectories("/Volumes", i)
      if not name then
        break
      end
      if name == vol_name then
        return true
      end
      i = i + 1
    end
    return false
  end

  -- Windows drive root (e.g. "E:/"): present if we can see any entry or rename succeeds.
  local drive = vol_root:match("^([A-Za-z]:)/?$")
  if drive then
    local root = drive:upper() .. ":/"
    if r.file_exists(root) then
      return true
    end
    if r.EnumerateFiles(root, 0) ~= nil or r.EnumerateSubdirectories(root, 0) ~= nil then
      return true
    end
    local ok, _, code = os.rename(root, root)
    if ok or code == 13 then
      return true
    end
    return false
  end

  return true
end

-- True when a folder path is present. Avoids the old pcall(Enumerate*) bug that
-- treated missing paths as existing (Enumerate returns nil, it does not throw).
local function scan_folder_path_exists(path)
  if not path or path == "" then
    return false
  end
  path = normalize_path(path)

  local vol = volume_root_from_path(path)
  if vol and not volume_is_mounted(vol) then
    return false
  end

  if r.file_exists(path) then
    return true
  end
  if r.EnumerateFiles(path, 0) ~= nil or r.EnumerateSubdirectories(path, 0) ~= nil then
    return true
  end

  -- Empty-but-present directories: rename-to-self is a portable exists probe.
  local ok, _, code = os.rename(path, path)
  if ok or code == 13 then
    return true
  end
  return false
end

local function sample_under_scan_folder(sample_path, folder_path)
  local norm_sample = normalize_path(sample_path or "")
  local norm_folder = normalize_path(folder_path or "")
  if norm_sample == "" or norm_folder == "" then
    return false
  end
  if norm_sample == norm_folder then
    return true
  end
  return norm_sample:sub(1, #norm_folder + 1) == norm_folder .. "/"
end

local function get_sample_scan_root(sample_path)
  local best_root = nil
  local best_len = 0
  for _, folder in ipairs(state.folders) do
    local norm_folder = normalize_path(folder)
    if sample_under_scan_folder(sample_path, norm_folder) and #norm_folder > best_len then
      best_root = norm_folder
      best_len = #norm_folder
    end
  end
  return best_root
end

local function availability_signature(missing_folders, missing_volumes)
  local parts = {}
  for folder in pairs(missing_folders or {}) do
    parts[#parts + 1] = "f:" .. folder
  end
  for vol in pairs(missing_volumes or {}) do
    parts[#parts + 1] = "v:" .. vol
  end
  table.sort(parts)
  return table.concat(parts, "|")
end

local function refresh_scan_folder_availability()
  local missing_folders = {}
  local missing_volumes = {}
  local volumes = {}

  for _, folder in ipairs(state.folders) do
    local norm_folder = normalize_path(folder)
    local vol = volume_root_from_path(norm_folder)
    if vol then
      volumes[vol] = true
    end
    if not scan_folder_path_exists(norm_folder) then
      missing_folders[norm_folder] = true
    end
  end

  for vol in pairs(volumes) do
    if not volume_is_mounted(vol) then
      missing_volumes[vol] = true
    end
  end

  local prev_sig = availability_signature(state.missing_scan_folders, state.missing_volumes)
  local new_sig = availability_signature(missing_folders, missing_volumes)
  state.missing_scan_folders = missing_folders
  state.missing_volumes = missing_volumes
  state.last_volume_check_time = r.time_precise()

  if new_sig ~= prev_sig then
    seq_path_exists_cache = {}
    state.map_availability_epoch = (state.map_availability_epoch or 0) + 1
    local missing_names = {}
    for folder in pairs(missing_folders) do
      missing_names[#missing_names + 1] = folder
    end
    table.sort(missing_names)
    local vol_names = {}
    for vol in pairs(missing_volumes) do
      vol_names[#vol_names + 1] = vol
    end
    table.sort(vol_names)
    if #vol_names > 0 then
      log(string.format(
        "Removable drive(s) offline (%d): %s — graying out dots",
        #vol_names,
        table.concat(vol_names, ", ")
      ))
    elseif #missing_names > 0 then
      log(string.format(
        "Unavailable scan folder(s) (%d): %s",
        #missing_names,
        table.concat(missing_names, ", ")
      ))
    else
      log("All scan folders / removable drives are available again")
    end
    state._clear_vary_rank_cache = true
    return true
  end
  return false
end

local function sample_scan_folder_unavailable(sample)
  if not sample or not sample.path then
    return false
  end
  local vol = volume_root_from_path(sample.path)
  if vol and state.missing_volumes[vol] then
    return true
  end
  local root = get_sample_scan_root(sample.path)
  if root and state.missing_scan_folders[root] then
    return true
  end
  return false
end

-- Map X-axis / sequencer cap: audible length when analyzed, else full file length.
local function sample_map_duration(sample)
  if sample and type(sample.effective_duration) == "number" and sample.effective_duration > 0 then
    return sample.effective_duration
  end
  if sample and type(sample.duration) == "number" and sample.duration > 0 then
    return sample.duration
  end
  return 0
end

-- Get filename without path
local function basename(path)
  if not path then return "" end
  local norm = normalize_path(path)
  return norm:match("([^/]+)$") or norm
end

-- Set media take name with logging (preferred) and fallback to item name
local function set_item_name(item, take, sample_path)
  if (not item and not take) or not sample_path then
    log("set_item_name: missing item/take or path")
    return
  end
  local name = basename(sample_path)
  local ok_take = nil
  if take then
    ok_take = r.GetSetMediaItemTakeInfo_String(take, "P_NAME", name, true)
  end
  local ok_item = nil
  if item then
    ok_item = r.GetSetMediaItemInfo_String(item, "P_NAME", name, true)
  end
  log(string.format("Naming to '%s' take_result=%s item_result=%s", name, tostring(ok_take), tostring(ok_item)))
end


-- Build ARGB color from RGB components (0-255)
local function build_color(r, g, b, a)
  a = a or 255
  return 0xFF000000 | (math.floor(r) << 16) | (math.floor(g) << 8) | math.floor(b)
end

-- Extract RGB components from RRGGBBAA format color
local function extract_rgb_rrgbbaa(color)
  if not color then return 0, 0, 0 end
  local r = math.floor((color / 16777216) % 256)   -- Extract red (first byte)
  local g = math.floor((color / 65536) % 256)     -- Extract green
  local b = math.floor((color / 256) % 256)       -- Extract blue
  return r, g, b
end

-- Build RRGGBBAA color from RGB components (0-255) and alpha (0-255, default 255)
local function build_color_rrgbbaa(r, g, b, a)
  a = a or 255
  return (math.floor(r) * 16777216) + (math.floor(g) * 65536) + (math.floor(b) * 256) + math.floor(a)
end

-- Extract RGB from RRGGBB color (24-bit)
local function extract_rgb(color)
  if not color then return 0, 0, 0 end
  local r = math.floor((color / 65536) % 256)
  local g = math.floor((color / 256) % 256)
  local b = math.floor(color % 256)
  return r, g, b
end

-- Build RRGGBB color from RGB components (0-255)
local function build_rgb(r, g, b)
  return (math.floor(r) * 65536) + (math.floor(g) * 256) + math.floor(b)
end



local function pick_number(ret, default)
  default = default or 0.0
  if type(ret) == "number" then
    return ret
  elseif type(ret) == "table" then
    for _, v in ipairs(ret) do
      if type(v) == "number" then
        return v
      end
    end
  end
  return default
end


local function pick_bool(ret, default)
  default = default or false
  if type(ret) == "boolean" then
    return ret
  elseif type(ret) == "table" then
    for _, v in ipairs(ret) do
      if type(v) == "boolean" then
        return v
      end
    end
  end
  return default
end


-- Detect loop vs one-shot. Strong filename keywords beat audio; audio beats
-- folder names. playback_type is analyzer output: "oneshot"|"loop"|"unknown"|nil.
-- nil = not analyzed yet (folder hints allowed); "unknown" = analyzed, leave untagged.
function detect_loop_or_oneshot(path, folder, playback_type)
  local path_lower = (path or ""):lower()
  local folder_lower = (folder or ""):lower()
  local filename = path_lower:match("([^/\\]+)$") or path_lower

  local function has_oneshot_keyword(s)
    if not s or s == "" then return false end
    return s:find("oneshot", 1, true)
      or s:find("one%-shot")
      or s:find("one_shot", 1, true)
      or s:find("1shot", 1, true)
      or s:find("one shot", 1, true)
  end

  local function filename_has_explicit_loop(name)
    if not name or name == "" then return false end
    if name:find("looped", 1, true) or name:find("lpd", 1, true) then
      return true
    end
    if name:find("[_%-]loop") or name:find("loop[_%-]") then
      return true
    end
    if name:find("%Wloop%W") or name:find("^loop%W") or name:find("%Wloop%.") or name:find("^loop%.") then
      return true
    end
    return false
  end

  if has_oneshot_keyword(filename) or has_oneshot_keyword(folder_lower) then
    return "One shot"
  end
  if filename_has_explicit_loop(filename) then
    return "loop"
  end

  if playback_type == "oneshot" then
    return "One shot"
  elseif playback_type == "loop" then
    return "loop"
  elseif playback_type == "unknown" then
    return nil
  end

  -- Weak filename hints only (not folders) while waiting for audio.
  if filename:find("%d+bpm") or filename:find("%d+_bpm") or filename:find("%d+%-bpm") then
    return "loop"
  end
  if filename:find("%d+bar") or filename:find("%d+_bar") or filename:find("%d+%-bar") then
    return "loop"
  end

  -- Folder "loop" / BPM packs: last-resort before analysis, never after.
  if folder_lower:find("loop") or folder_lower:find("looped") then
    return "loop"
  end
  if folder_lower:find("construction kit") then
    return "loop"
  end
  if folder_lower:find("%d+%s+bpm") or folder_lower:find("%d+%-bpm") then
    return "loop"
  end

  return nil
end

-- Replace loop/one-shot tags. kind is "loop", "One shot", or nil (strip only).
function apply_loop_oneshot_tag(sample, kind)
  if not sample then
    return false
  end
  sample.tags = sample.tags or {}
  local out = {}
  local changed = false
  for _, tag in ipairs(sample.tags) do
    local lower = string.lower(tostring(tag))
    if lower == "loop" or lower == "one shot" or lower == "oneshot" then
      changed = true
    else
      out[#out + 1] = tag
    end
  end
  if kind then
    local exists = false
    for _, tag in ipairs(out) do
      if tag == kind then
        exists = true
        break
      end
    end
    if not exists and not (tag_is_suppressed and tag_is_suppressed(kind)) then
      out[#out + 1] = kind
      changed = true
    end
  end
  sample.tags = out
  return changed
end


-- Extract meaningful tags from filename and folder tokens
local function infer_tags_from_path(path, folder)
  local tokens = {}
  local function collect(str)
    if not str or str == "" then return end
    for token in tostring(str):lower():gmatch("%w+") do
      tokens[token] = true
    end
  end
  collect(path or "")
  collect(folder or "")

  local scored = {}
  for _, entry in ipairs(TAG_KEYWORDS) do
    for _, key in ipairs(entry.keys) do
      if tokens[key] then
        local current = scored[entry.tag] or 0
        if entry.weight > current then
          scored[entry.tag] = entry.weight
        end
        break
      end
    end
  end

  local sorted = {}
  for tag, weight in pairs(scored) do
    table.insert(sorted, {tag = tag, weight = weight})
  end
  table.sort(sorted, function(a, b)
    if a.weight == b.weight then
      return a.tag < b.tag
    end
    return a.weight > b.weight
  end)

  local tags = {}
  for _, entry in ipairs(sorted) do
    if not (tag_is_suppressed and tag_is_suppressed(entry.tag)) then
      tags[#tags + 1] = entry.tag
      if #tags >= 6 then break end -- Keep cache lean
    end
  end

  return tags
end


-- Match a genre key against a lowercased path/folder string using word-ish
-- boundaries so "house" does not match "warehouse".
-- Multi-word keys accept any punctuation/separator between parts:
--   deep house, deep.house, deep_house, deep-house, deep/house, deephouse
local function genre_key_matches(haystack, key)
  if not haystack or not key or key == "" then
    return false
  end
  local parts = {}
  for part in tostring(key):lower():gmatch("%w+") do
    parts[#parts + 1] = part
  end
  if #parts == 0 then
    return false
  end

  local function bounded(pat)
    -- Plain substring with alphanumeric word boundaries (works at string ends too)
    local i = 1
    while true do
      local s, e = haystack:find(pat, i)
      if not s then
        return false
      end
      local before = (s == 1) and "" or haystack:sub(s - 1, s - 1)
      local after = (e == #haystack) and "" or haystack:sub(e + 1, e + 1)
      local before_ok = before == "" or not before:match("%w")
      local after_ok = after == "" or not after:match("%w")
      if before_ok and after_ok then
        return true
      end
      i = s + 1
    end
  end

  -- Separated form: deep house / deep.house / deep_house / deep-house / etc.
  -- [^%w]+ matches any run of non-alphanumeric chars (space, ., _, -, /, +, ...)
  if bounded(table.concat(parts, "[^%w]+")) then
    return true
  end

  -- Concatenated form: deephouse, futurebass, jerseyclub
  if #parts > 1 and bounded(table.concat(parts)) then
    return true
  end

  return false
end


-- Detect genre tags from pack/folder names (library-driven).
-- Uses directory context only — not the bare filename — so material words
-- like "metal" / "drill" in foley one-shots don't pollute the Library list.
-- Results are cached per directory path (many samples share the same folder).
local _genre_tags_by_dir = {}

local function clear_genre_tag_dir_cache()
  _genre_tags_by_dir = {}
end

local function infer_genre_tags_from_path(path, folder)
  local dir = folder or ""
  if dir == "" and path and path ~= "" then
    dir = path:match("(.+)/[^/]+$") or ""
  end
  -- Include parent path directories when folder is only the leaf directory
  if path and path ~= "" then
    local parent = path:match("(.+)/[^/]+$")
    if parent and parent ~= "" then
      dir = parent
    end
  end
  local haystack = dir:lower()
  local cached = _genre_tags_by_dir[haystack]
  if cached then
    local copy = {}
    for i = 1, #cached do
      copy[i] = cached[i]
    end
    return copy
  end
  local tags = {}
  local seen = {}
  for _, entry in ipairs(GENRE_KEYWORDS) do
    for _, key in ipairs(entry.keys) do
      if genre_key_matches(haystack, key) then
        if not seen[entry.tag] and not (tag_is_suppressed and tag_is_suppressed(entry.tag)) then
          seen[entry.tag] = true
          tags[#tags + 1] = entry.tag
        end
        break
      end
    end
  end
  _genre_tags_by_dir[haystack] = tags
  local copy = {}
  for i = 1, #tags do
    copy[i] = tags[i]
  end
  return copy
end


-- Append tags that are not already present.
local function append_unique_tags(tags, extra)
  if not tags then tags = {} end
  if not extra or #extra == 0 then return tags end
  local existing = {}
  for _, tag in ipairs(tags) do
    existing[tag] = true
  end
  for _, tag in ipairs(extra) do
    if tag and not existing[tag] and not (tag_is_suppressed and tag_is_suppressed(tag)) then
      tags[#tags + 1] = tag
      existing[tag] = true
    end
  end
  return tags
end


-- Recurring pack/vendor/folder tokens from the scanned library.
-- Curated GENRE_KEYWORDS still tag samples directly; this pass adds extra
-- Library chips (company names, pack folders, etc.) without feeding them
-- into sequencer kit-genre matching.
function apply_discovered_library_tags()
  local samples = state.samples
  if type(samples) ~= "table" or #samples == 0 then
    state.discovered_library_tag_set = {}
    return
  end

  local skip = {
    pack = true, packs = true, kit = true, kits = true, bundle = true, bundles = true,
    collection = true, collections = true, sample = true, samples = true, sampler = true,
    sound = true, sounds = true, audio = true, wav = true, wave = true, aiff = true,
    flac = true, mp3 = true, ogg = true, loop = true, loops = true, looping = true,
    oneshot = true, oneshots = true, one = true, shot = true, shots = true,
    drum = true, drums = true, drumkit = true, perc = true, percussion = true,
    fx = true, sfx = true, vocal = true, vocals = true, vox = true, voice = true,
    kick = true, kicks = true, snare = true, snares = true, clap = true, claps = true,
    snap = true, snaps = true, hat = true, hats = true, hihat = true, hihats = true,
    tom = true, toms = true, ride = true, rides = true, crash = true, crashes = true,
    cymbal = true, cymbals = true, rim = true, rims = true, bass = true, basses = true,
    lead = true, leads = true, pad = true, pads = true, pluck = true, plucks = true,
    key = true, keys = true, piano = true, pianos = true, guitar = true, guitars = true,
    inst = true, instrument = true, instruments = true, folder = true, folders = true,
    file = true, files = true, library = true, libraries = true, lib = true,
    download = true, downloads = true, new = true, final = true, demo = true, demos = true,
    bonus = true, extra = true, extras = true, preview = true, previews = true,
    stem = true, stems = true, midi = true, preset = true, presets = true,
    vol = true, volume = true, pt = true, part = true, version = true, ver = true,
    stereo = true, mono = true, multi = true, bpm = true, hz = true, khz = true,
    bit = true, bits = true, rate = true, the = true, ["and"] = true, ["for"] = true,
    from = true, with = true, you = true, your = true,
    this = true, that = true, all = true, any = true, untitled = true, copy = true,
    backup = true, old = true, temp = true, tmp = true, misc = true, other = true,
    various = true, users = true, user = true, documents = true, desktop = true,
    music = true, volumes = true, applications = true, application = true,
    support = true, reaper = true, scripts = true, home = true, content = true,
    contents = true, media = true, imported = true, import = true, export = true,
    project = true, projects = true, session = true, sessions = true,
    swell = true, ones = true, wavs = true, audiofiles = true,
    scene = true, discover = true,
  }
  for _, entry in ipairs(TAG_KEYWORDS) do
    skip[string.lower(entry.tag)] = true
    for _, key in ipairs(entry.keys) do
      skip[string.lower(key)] = true
    end
  end
  for _, entry in ipairs(GENRE_KEYWORDS) do
    skip[string.lower(entry.tag)] = true
    for _, key in ipairs(entry.keys) do
      if #key >= 3 then
        skip[string.lower(key)] = true
      end
    end
  end
  for tag, on in pairs(state.deleted_tags or {}) do
    if on then
      skip[string.lower(tostring(tag))] = true
    end
  end

  local core_keep = {
    loop = true, oneshot = true, ["one shot"] = true, drum = true, swell = true,
  }
  for _, entry in ipairs(TAG_KEYWORDS) do
    core_keep[string.lower(entry.tag)] = true
  end
  for tag, _ in pairs(GENRE_TAG_SET) do
    core_keep[tag] = true
  end

  local function is_junk_token(token)
    if not token or token == "" or skip[token] or core_keep[token] then
      return true
    end
    if #token < 3 or #token > 64 then
      return true
    end
    if token:match("^%d+$") or token:match("^v%d+$") or token:match("^vol%d+$") then
      return true
    end
    if token:match("^%d+bpm$") or token:match("^%d+k$") or token:match("^%d+hz$") or token:match("^%d+bit$") then
      return true
    end
    if token:match("^[a-g][#b]?min$") or token:match("^[a-g][#b]?maj$")
        or token:match("^[a-g]minor$") or token:match("^[a-g]major$") then
      return true
    end
    return false
  end

  local function scan_root_and_relative(path)
    path = normalize_path(path or "")
    local dir = path:match("(.+)/[^/]+$") or ""
    local best = ""
    for _, folder in ipairs(state.folders or {}) do
      local root = normalize_path(folder)
      if root ~= "" and (dir == root or dir:sub(1, #root + 1) == root .. "/") then
        if #root > #best then
          best = root
        end
      end
    end
    if best == "" then
      return "", dir
    end
    if dir == best then
      return best, ""
    end
    return best, dir:sub(#best + 2)
  end

  local function tokens_from_library_path(rel, root)
    local found = {}
    local function consider(token)
      token = tostring(token or ""):lower():gsub("^%s+", ""):gsub("%s+$", ""):gsub("%s+", " ")
      if is_junk_token(token) or found[token] then
        return
      end
      found[token] = true
    end
    local function add_segment(segment)
      local phrase = tostring(segment or ""):lower():gsub("[^%w]+", " "):gsub("^%s+", ""):gsub("%s+$", ""):gsub("%s+", " ")
      if phrase == "" then
        return
      end
      local kept_words = {}
      for word in phrase:gmatch("%w+") do
        consider(word)
        if not is_junk_token(word) then
          kept_words[#kept_words + 1] = word
        end
      end
      -- Keep the original folder name when it has a distinctive word, so
      -- "Cymatics Lofi Pack" stays one chip instead of a stitched fragment.
      if phrase:find(" ", 1, true) and #kept_words >= 1 then
        consider(phrase)
      end
    end
    if root and root ~= "" then
      add_segment(root:match("([^/]+)$") or "")
    end
    for segment in tostring(rel or ""):gmatch("[^/]+") do
      add_segment(segment)
    end
    return found
  end

  local function library_haystack(rel, root)
    local leaf = ""
    if root and root ~= "" then
      leaf = root:match("([^/]+)$") or ""
    end
    return (leaf .. " " .. tostring(rel or "")):lower():gsub("[^%w]+", " ")
  end

  local dir_counts = {}
  local dir_tokens = {}
  local dir_meta = {}
  local n = #samples
  for i = 1, n do
    local sample = samples[i]
    local root, rel = scan_root_and_relative(sample and sample.path)
    local key = (root .. "\t" .. rel):lower()
    dir_counts[key] = (dir_counts[key] or 0) + 1
    if not dir_tokens[key] then
      dir_tokens[key] = tokens_from_library_path(rel, root)
      dir_meta[key] = { root = root, rel = rel }
    end
  end

  local function pack_id_for(root, rel)
    local first = tostring(rel or ""):match("^([^/]+)")
    if first and first ~= "" then
      return tostring(root or "") .. "\t" .. first:lower()
    end
    local leaf = tostring(root or ""):match("([^/]+)$") or ""
    return tostring(root or "") .. "\t" .. leaf:lower()
  end

  local token_counts = {}
  local token_packs = {}
  for key, count in pairs(dir_counts) do
    local meta = dir_meta[key] or {}
    local pack = pack_id_for(meta.root, meta.rel)
    for token, _ in pairs(dir_tokens[key] or {}) do
      token_counts[token] = (token_counts[token] or 0) + count
      local packs = token_packs[token]
      if not packs then
        packs = {}
        token_packs[token] = packs
      end
      packs[pack] = true
    end
  end

  local min_count = 5
  if n >= 40 then
    min_count = math.max(8, math.min(24, math.floor(n * 0.012)))
  end

  local function pack_count(token)
    local packs = token_packs[token]
    if not packs then
      return 0
    end
    local c = 0
    for _ in pairs(packs) do
      c = c + 1
    end
    return c
  end

  local ranked = {}
  for token, count in pairs(token_counts) do
    if count >= min_count and pack_count(token) >= 2 then
      ranked[#ranked + 1] = { tag = token, count = count }
    end
  end
  table.sort(ranked, function(a, b)
    if a.count == b.count then
      return a.tag < b.tag
    end
    return a.count > b.count
  end)
  local cap = 50
  if #ranked > cap then
    for i = cap + 1, #ranked do
      ranked[i] = nil
    end
  end

  local new_set = {}
  for i = 1, #ranked do
    new_set[ranked[i].tag] = true
  end

  local dir_match_cache = {}
  local function matching_tags_for_path(path)
    local root, rel = scan_root_and_relative(path)
    local hay = library_haystack(rel, root)
    local cached = dir_match_cache[hay]
    if cached then
      return cached
    end
    local extra = {}
    for i = 1, #ranked do
      local tag = ranked[i].tag
      if genre_key_matches(hay, tag) then
        extra[#extra + 1] = tag
      end
    end
    dir_match_cache[hay] = extra
    return extra
  end

  for i = 1, n do
    local sample = samples[i]
    if sample then
      local custom = {}
      local path = sample.path or ""
      local custom_list = state.custom_tags and (state.custom_tags[path] or state.custom_tags[normalize_path(path)])
      if type(custom_list) == "table" then
        for _, tag in ipairs(custom_list) do
          custom[tostring(tag):lower()] = true
        end
      end
      local kept = {}
      for _, tag in ipairs(sample.tags or {}) do
        local low = tostring(tag):lower()
        if (core_keep[low] or custom[low]) and not (tag_is_suppressed and tag_is_suppressed(low)) then
          kept[#kept + 1] = tag
        end
      end
      sample.tags = append_unique_tags(kept, matching_tags_for_path(path))
    end
  end

  state.discovered_library_tag_set = new_set
end


-- Build tag list, counts, and inverted tag → samples index for fast filtering
local function rebuild_tag_index()
  local counts = {}
  local by_tag = {}
  for _, s in ipairs(state.samples) do
    s._render_color = nil
    local set = {}
    if s.tags and type(s.tags) == "table" then
      local tags, seen = {}, {}
      for _, tag in ipairs(s.tags) do
        if tag == "808" then
          tag = "808s"
        end
        if tag and not seen[tag] then
          seen[tag] = true
          tags[#tags + 1] = tag
        end
      end
      s.tags = tags
      for _, tag in ipairs(tags) do
        if not (tag_is_suppressed and tag_is_suppressed(tag)) then
          set[tag] = true
          counts[tag] = (counts[tag] or 0) + 1
          local list = by_tag[tag]
          if not list then
            list = {}
            by_tag[tag] = list
          end
          list[#list + 1] = s
        end
      end
    end
    s._tag_set = set
  end

  state.samples_by_tag = by_tag
  state.tag_counts = counts
  state.tag_index_epoch = (state.tag_index_epoch or 0) + 1
  state.tag_list = {}
  for tag, count in pairs(counts) do
    table.insert(state.tag_list, {tag = tag, count = count})
  end
  table.sort(state.tag_list, function(a, b)
    if a.count == b.count then
      return a.tag < b.tag
    end
    return a.count > b.count
  end)
end


-- --- JSON helpers (improved) ----------------------------------------------------
local function json_encode_string(s)
  -- Escape special characters in strings
  s = s:gsub('\\', '\\\\')
  s = s:gsub('"', '\\"')
  s = s:gsub('\n', '\\n')
  s = s:gsub('\r', '\\r')
  s = s:gsub('\t', '\\t')
  return '"' .. s .. '"'
end

local function json_encode(val)
  if type(val) == "table" then
    local parts = {}
    local is_array = true
    local max_idx = 0
    for k, v in pairs(val) do
      if type(k) ~= "number" or k ~= math.floor(k) or k < 1 then
        is_array = false
        break
      end
      max_idx = math.max(max_idx, k)
    end
    
    if is_array then
      for i = 1, max_idx do
        table.insert(parts, json_encode(val[i]))
      end
      return "[" .. table.concat(parts, ",") .. "]"
    else
      for k, v in pairs(val) do
        table.insert(parts, json_encode_string(tostring(k)) .. ":" .. json_encode(v))
      end
      return "{" .. table.concat(parts, ",") .. "}"
    end
  elseif type(val) == "string" then
    return json_encode_string(val)
  elseif type(val) == "number" then
    return tostring(val)
  elseif type(val) == "boolean" then
    return val and "true" or "false"
  else
    return "null"
  end
end


local function json_decode(str)
  -- Improved JSON decoder that handles strings with commas and special chars
  str = str:match("%s*(.*)")
  if str:sub(1, 1) == "{" then
    local obj = {}
    str = str:sub(2, -2) -- remove {}
    
    -- Parse key-value pairs, handling quoted strings properly
    local pos = 1
    while pos <= #str do
      -- Skip whitespace
      while pos <= #str and str:sub(pos, pos):match("%s") do
        pos = pos + 1
      end
      if pos > #str then break end
      
      -- Find key (quoted string)
      if str:sub(pos, pos) ~= '"' then break end
      local key_start = pos + 1
      local key_end = key_start
      while key_end <= #str do
        if str:sub(key_end, key_end) == '"' and str:sub(key_end - 1, key_end - 1) ~= '\\' then
          break
        end
        key_end = key_end + 1
      end
      local key = str:sub(key_start, key_end - 1):gsub('\\"', '"'):gsub('\\\\', '\\')
      
      -- Skip to colon
      pos = key_end + 1
      while pos <= #str and str:sub(pos, pos) ~= ':' do pos = pos + 1 end
      pos = pos + 1
      
      -- Skip whitespace
      while pos <= #str and str:sub(pos, pos):match("%s") do pos = pos + 1 end
      
      -- Parse value
      if str:sub(pos, pos) == '"' then
        -- String value
        local val_start = pos + 1
        local val_end = val_start
        while val_end <= #str do
          if str:sub(val_end, val_end) == '"' and str:sub(val_end - 1, val_end - 1) ~= '\\' then
            break
          end
          val_end = val_end + 1
        end
        obj[key] = str:sub(val_start, val_end - 1):gsub('\\"', '"'):gsub('\\\\', '\\'):gsub('\\n', '\n'):gsub('\\r', '\r'):gsub('\\t', '\t')
        pos = val_end + 1
      elseif str:sub(pos, pos) == '[' then
        -- Array value - find matching bracket
        local depth = 1
        local arr_start = pos
        pos = pos + 1
        while pos <= #str and depth > 0 do
          if str:sub(pos, pos) == '[' then depth = depth + 1
          elseif str:sub(pos, pos) == ']' then depth = depth - 1 end
          pos = pos + 1
        end
        local arr_str = str:sub(arr_start, pos - 1)
        obj[key] = json_decode(arr_str)
      elseif str:sub(pos, pos) == '{' then
        -- Object value - find matching brace
        local depth = 1
        local obj_start = pos
        pos = pos + 1
        while pos <= #str and depth > 0 do
          if str:sub(pos, pos) == '{' then depth = depth + 1
          elseif str:sub(pos, pos) == '}' then depth = depth - 1 end
          pos = pos + 1
        end
        local obj_str = str:sub(obj_start, pos - 1)
        obj[key] = json_decode(obj_str)
      else
        -- Number or boolean
        local val_end = pos
        while val_end <= #str and str:sub(val_end, val_end) ~= ',' and str:sub(val_end, val_end) ~= '}' do
          val_end = val_end + 1
        end
        local val_str = str:sub(pos, val_end - 1):match("^%s*(.-)%s*$")
        if val_str == "true" then
          obj[key] = true
        elseif val_str == "false" then
          obj[key] = false
        elseif tonumber(val_str) then
          obj[key] = tonumber(val_str)
        end
        pos = val_end
      end
      
      -- Skip comma
      while pos <= #str and (str:sub(pos, pos) == ',' or str:sub(pos, pos):match("%s")) do
        pos = pos + 1
      end
    end
    return obj
  elseif str:sub(1, 1) == "[" then
    local arr = {}
    str = str:sub(2, -2) -- remove []
    
    -- Handle empty array
    if str:match("^%s*$") then
      return arr
    end
    
    -- Parse array items, handling strings with commas, nested objects, and nested arrays
    local pos = 1
    while pos <= #str do
      -- Skip whitespace
      while pos <= #str and str:sub(pos, pos):match("%s") do pos = pos + 1 end
      if pos > #str then break end
      
      if str:sub(pos, pos) == '"' then
        -- String item
        local item_start = pos + 1
        local item_end = item_start
        while item_end <= #str do
          if str:sub(item_end, item_end) == '"' and str:sub(item_end - 1, item_end - 1) ~= '\\' then
            break
          end
          item_end = item_end + 1
        end
        if item_end <= #str then
          local item_str = str:sub(item_start, item_end - 1)
          item_str = item_str:gsub('\\"', '"'):gsub('\\\\', '\\')
          table.insert(arr, item_str)
        end
        pos = item_end + 1
      elseif str:sub(pos, pos) == '{' then
        -- Nested object - find matching brace
        local depth = 1
        local obj_start = pos
        pos = pos + 1
        while pos <= #str and depth > 0 do
          if str:sub(pos, pos) == '{' then depth = depth + 1
          elseif str:sub(pos, pos) == '}' then depth = depth - 1 end
          pos = pos + 1
        end
        local obj_str = str:sub(obj_start, pos - 1)
        table.insert(arr, json_decode(obj_str))
      elseif str:sub(pos, pos) == '[' then
        -- Nested array - find matching bracket
        local depth = 1
        local arr_start = pos
        pos = pos + 1
        while pos <= #str and depth > 0 do
          if str:sub(pos, pos) == '[' then depth = depth + 1
          elseif str:sub(pos, pos) == ']' then depth = depth - 1 end
          pos = pos + 1
        end
        local arr_str = str:sub(arr_start, pos - 1)
        table.insert(arr, json_decode(arr_str))
      elseif tonumber(str:sub(pos, pos)) or str:sub(pos, pos) == '-' then
        -- Number item
        local item_end = pos
        while item_end <= #str and str:sub(item_end, item_end) ~= ',' and str:sub(item_end, item_end) ~= ']' do
          item_end = item_end + 1
        end
        local num_str = str:sub(pos, item_end - 1):match("^%s*(.-)%s*$")
        local num = tonumber(num_str)
        if num then 
          table.insert(arr, num) 
        end
        pos = item_end
      elseif str:sub(pos, pos) == 't' or str:sub(pos, pos) == 'f' then
        -- Boolean or null
        local item_end = pos
        while item_end <= #str and str:sub(item_end, item_end) ~= ',' and str:sub(item_end, item_end) ~= ']' do
          item_end = item_end + 1
        end
        local val_str = str:sub(pos, item_end - 1):match("^%s*(.-)%s*$")
        if val_str == "true" then
          table.insert(arr, true)
        elseif val_str == "false" then
          table.insert(arr, false)
        elseif val_str == "null" then
          table.insert(arr, nil)
        end
        pos = item_end
      else
        -- Skip unknown character (shouldn't happen in valid JSON)
        log("Warning: Unexpected character in array at position " .. pos .. ": " .. str:sub(pos, pos))
        pos = pos + 1
      end
      
      -- Skip comma
      while pos <= #str and (str:sub(pos, pos) == ',' or str:sub(pos, pos):match("%s")) do
        pos = pos + 1
      end
    end
    return arr
  end
  return nil
end


-- Compact Lua value serializer for SampleMapData.cache.lua (loadfile-friendly).
local function lua_is_array(t)
  local n = #t
  for k in pairs(t) do
    if type(k) ~= "number" or k < 1 or k > n or k ~= math.floor(k) then
      return false
    end
  end
  return true
end

local function serialize_lua_value(val, out)
  local tv = type(val)
  if tv == "nil" then
    out[#out + 1] = "nil"
  elseif tv == "boolean" then
    out[#out + 1] = val and "true" or "false"
  elseif tv == "number" then
    if val ~= val then
      out[#out + 1] = "0"
    elseif val == math.huge then
      out[#out + 1] = "math.huge"
    elseif val == -math.huge then
      out[#out + 1] = "-math.huge"
    elseif val == math.floor(val) and math.abs(val) < 9007199254740992 then
      out[#out + 1] = string.format("%d", val)
    elseif math.abs(val) < 1000000 then
      out[#out + 1] = string.format("%.6g", val)
    else
      out[#out + 1] = string.format("%.17g", val)
    end
  elseif tv == "string" then
    out[#out + 1] = string.format("%q", val)
  elseif tv == "table" then
    out[#out + 1] = "{"
    if lua_is_array(val) then
      for i = 1, #val do
        if i > 1 then out[#out + 1] = "," end
        serialize_lua_value(val[i], out)
      end
    else
      local first = true
      for k, v in pairs(val) do
        if not first then out[#out + 1] = "," end
        first = false
        if type(k) == "string" and k:match("^[%a_][%w_]*$") then
          out[#out + 1] = k
          out[#out + 1] = "="
        else
          out[#out + 1] = "["
          serialize_lua_value(k, out)
          out[#out + 1] = "]="
        end
        serialize_lua_value(v, out)
      end
    end
    out[#out + 1] = "}"
  else
    out[#out + 1] = "nil"
  end
end

local function encode_lua_cache(payload)
  local out = {"return "}
  serialize_lua_value(payload, out)
  out[#out + 1] = "\n"
  return table.concat(out)
end

-- Compact on-disk sample cache (v2).
-- Dirs and tags are interned once; each sample is a short array:
-- [dir_idx, name, tag_idxs, x, y, dur, ed, ch, rms, freq, pt, bps, onset, te, extra]
-- In-memory samples stay as full {path, folder, name, ...} tables.
SampleCacheCodec = {
  VERSION = 2,
  PT = { oneshot = 1, loop = 2, unknown = 0 },
  PT_NAME = { [0] = "unknown", [1] = "oneshot", [2] = "loop" },
}

function SampleCacheCodec.round(n, places)
  if type(n) ~= "number" or n ~= n then
    return nil
  end
  if n == math.huge or n == -math.huge then
    return nil
  end
  local f = 10 ^ (places or 5)
  return math.floor(n * f + (n >= 0 and 0.5 or -0.5)) / f
end

function SampleCacheCodec.split_dir_name(path)
  path = normalize_path(path or "")
  if path == "" then
    return "", ""
  end
  local name = path:match("([^/]+)$") or path
  local dir = path:match("(.+)/[^/]+$") or ""
  return dir, name
end

function SampleCacheCodec.join_dir_name(dir, name)
  name = name or ""
  if not dir or dir == "" then
    return name
  end
  if name == "" then
    return dir
  end
  return dir .. "/" .. name
end

function SampleCacheCodec.interner()
  local list, index = {}, {}
  local function intern(s)
    if s == nil then
      return 0
    end
    s = tostring(s)
    local i = index[s]
    if i then
      return i
    end
    i = #list + 1
    list[i] = s
    index[s] = i
    return i
  end
  return list, intern
end

function SampleCacheCodec.compact_sample(sample, intern_dir, intern_tag)
  if type(sample) ~= "table" then
    return nil
  end
  local path = sample.path or SampleCacheCodec.join_dir_name(sample.folder, sample.name)
  local dir, name = SampleCacheCodec.split_dir_name(path)
  if name == "" then
    return nil
  end
  local tag_idxs = {}
  if type(sample.tags) == "table" then
    for i = 1, #sample.tags do
      local tag = sample.tags[i]
      if tag and tag ~= "" then
        tag_idxs[#tag_idxs + 1] = intern_tag(tag)
      end
    end
  end
  local pt = false
  if sample.playback_type ~= nil then
    pt = SampleCacheCodec.PT[sample.playback_type] or 0
  end
  local extra
  if sample.sample_type ~= nil or sample.snap_offset ~= nil
      or sample.start_pos ~= nil or sample.gain ~= nil
      or sample.brightness ~= nil or sample.sub_weight ~= nil
      or sample.mtime ~= nil or sample.file_id_size ~= nil then
    extra = {}
    if sample.sample_type ~= nil then extra.st = sample.sample_type end
    if type(sample.snap_offset) == "number" then extra.so = SampleCacheCodec.round(sample.snap_offset, 5) end
    if type(sample.start_pos) == "number" then extra.sp = SampleCacheCodec.round(sample.start_pos, 5) end
    if type(sample.gain) == "number" then extra.g = SampleCacheCodec.round(sample.gain, 5) end
    if type(sample.brightness) == "number" then extra.br = SampleCacheCodec.round(sample.brightness, 2) end
    if type(sample.sub_weight) == "number" then extra.sw = SampleCacheCodec.round(sample.sub_weight, 5) end
    if sample.mtime ~= nil and tostring(sample.mtime) ~= "" then
      extra.mt = tostring(sample.mtime)
    end
    if type(sample.file_id_size) == "number" then
      extra.fs = math.floor(sample.file_id_size + 0.5)
    end
  end
  local row = {
    intern_dir(dir),
    name,
    tag_idxs,
    SampleCacheCodec.round(sample.x or 0.5, 5) or 0.5,
    SampleCacheCodec.round(sample.y or 0.5, 5) or 0.5,
    SampleCacheCodec.round(sample.duration, 5) or false,
    SampleCacheCodec.round(sample.effective_duration, 5) or false,
    sample.channels or false,
    SampleCacheCodec.round(sample.rms_energy, 5) or false,
    SampleCacheCodec.round(sample.dominant_freq, 2) or false,
    pt,
    (type(sample.bps) == "number" and math.floor(sample.bps + 0.5)) or false,
    SampleCacheCodec.round(sample.onset, 5) or false,
    SampleCacheCodec.round(sample.transient_end, 5) or false,
    extra or false,
  }
  while #row > 6 and row[#row] == false do
    row[#row] = nil
  end
  return row
end

function SampleCacheCodec.expand_sample(row, dirs, tag_dict)
  if type(row) ~= "table" then
    return nil
  end
  if type(row.path) == "string" and row.path ~= "" then
    return row
  end
  local dir_idx, name = row[1], row[2]
  if type(name) ~= "string" or name == "" then
    return nil
  end
  local dir = ""
  if type(dir_idx) == "number" and dirs then
    dir = dirs[dir_idx] or ""
  end
  local path = SampleCacheCodec.join_dir_name(dir, name)
  local tags = {}
  local tag_idxs = row[3]
  if type(tag_idxs) == "table" and tag_dict then
    for i = 1, #tag_idxs do
      local tag = tag_dict[tag_idxs[i]]
      if tag and tag ~= "" then
        tags[#tags + 1] = tag
      end
    end
  end
  local function num(v)
    if type(v) == "number" then return v end
    return nil
  end
  local pt = row[11]
  local playback_type = nil
  if type(pt) == "number" then
    playback_type = SampleCacheCodec.PT_NAME[pt] or "unknown"
  end
  local extra = row[15]
  local sample = {
    path = path,
    name = name,
    folder = dir,
    tags = tags,
    x = num(row[4]) or 0.5,
    y = num(row[5]) or 0.5,
    duration = num(row[6]),
    effective_duration = num(row[7]),
    channels = num(row[8]),
    rms_energy = num(row[9]),
    dominant_freq = num(row[10]),
    playback_type = playback_type,
    bps = num(row[12]),
    onset = num(row[13]),
    transient_end = num(row[14]),
  }
  if type(extra) == "table" then
    if extra.st ~= nil then sample.sample_type = extra.st end
    if type(extra.so) == "number" then sample.snap_offset = extra.so end
    if type(extra.sp) == "number" then sample.start_pos = extra.sp end
    if type(extra.g) == "number" then sample.gain = extra.g end
    if type(extra.br) == "number" then sample.brightness = extra.br end
    if type(extra.sw) == "number" then sample.sub_weight = extra.sw end
    if extra.mt ~= nil then sample.mtime = tostring(extra.mt) end
    if type(extra.fs) == "number" then
      sample.file_id_size = extra.fs
      sample.file_size = extra.fs
    end
  end
  return sample
end

function SampleCacheCodec.compact_path(path, intern_dir)
  local dir, name = SampleCacheCodec.split_dir_name(path)
  if name == "" then
    return nil
  end
  return { intern_dir(dir), name }
end

function SampleCacheCodec.expand_path(ref, dirs)
  if type(ref) == "string" then
    return normalize_path(ref)
  end
  if type(ref) ~= "table" then
    return nil
  end
  local dir = ""
  if type(ref[1]) == "number" and dirs then
    dir = dirs[ref[1]] or ""
  end
  local name = ref[2]
  if type(name) ~= "string" or name == "" then
    return nil
  end
  return SampleCacheCodec.join_dir_name(dir, name)
end

function SampleCacheCodec.compact_path_list(list, intern_dir)
  local out = {}
  if type(list) ~= "table" then
    return out
  end
  for i = 1, #list do
    local ref = SampleCacheCodec.compact_path(list[i], intern_dir)
    if ref then
      out[#out + 1] = ref
    end
  end
  return out
end

function SampleCacheCodec.expand_path_list(list, dirs)
  local out = {}
  if type(list) ~= "table" then
    return out
  end
  for i = 1, #list do
    local path = SampleCacheCodec.expand_path(list[i], dirs)
    if path and path ~= "" then
      out[#out + 1] = path
    end
  end
  return out
end

function SampleCacheCodec.build_payload(state_tbl, folders, samples)
  local dirs, intern_dir = SampleCacheCodec.interner()
  local tag_dict, intern_tag = SampleCacheCodec.interner()
  local compact_samples = {}
  for i = 1, #samples do
    local row = SampleCacheCodec.compact_sample(samples[i], intern_dir, intern_tag)
    if row then
      compact_samples[#compact_samples + 1] = row
    end
  end
  return {
    v = SampleCacheCodec.VERSION,
    tag_schema_version = TAG_SCHEMA_VERSION,
    folders = folders,
    dirs = dirs,
    tag_dict = tag_dict,
    map_seed = state_tbl.map_seed,
    samples = compact_samples,
    scan_queue = SampleCacheCodec.compact_path_list(state_tbl.scan_queue, intern_dir),
    scan_total = state_tbl.scan_total,
    scan_started = state_tbl.scan_started,
    analyzer_queue = SampleCacheCodec.compact_path_list(state_tbl.analyzer_queue, intern_dir),
    analyzer_pending = state_tbl.active_processes and #state_tbl.active_processes > 0,
    analyzer_results = state_tbl.analyzer_results,
    analyzer_mode = state_tbl.analyzer_mode,
  }
end

function SampleCacheCodec.extract_json_array(content, key)
  if type(content) ~= "string" or not key then
    return nil
  end
  local key_pos = content:find('"' .. key .. '"%s*:', 1)
  if not key_pos then
    return nil
  end
  local colon = content:find(":", key_pos, true)
  if not colon then
    return nil
  end
  local i = colon + 1
  local n = #content
  local byte = string.byte
  while i <= n do
    local b = byte(content, i)
    if b ~= 32 and b ~= 9 and b ~= 10 and b ~= 13 then
      break
    end
    i = i + 1
  end
  if byte(content, i) ~= 91 then
    return nil
  end
  local start = i
  local depth = 1
  i = i + 1
  local in_str, esc = false, false
  while i <= n and depth > 0 do
    local ch = byte(content, i)
    if in_str then
      if esc then
        esc = false
      elseif ch == 92 then
        esc = true
      elseif ch == 34 then
        in_str = false
      end
    else
      if ch == 34 then
        in_str = true
      elseif ch == 91 then
        depth = depth + 1
      elseif ch == 93 then
        depth = depth - 1
      end
    end
    i = i + 1
  end
  return content:sub(start, i - 1)
end

function SampleCacheCodec.encode_row_json(row)
  local parts = {}
  for i = 1, #row do
    local v = row[i]
    local tv = type(v)
    if tv == "number" then
      if v == math.floor(v) and math.abs(v) < 1e15 then
        parts[i] = string.format("%d", v)
      else
        parts[i] = string.format("%.5f", v):gsub("(%..-)0+$", "%1"):gsub("%.$", "")
      end
    elseif tv == "string" then
      parts[i] = json_encode_string(v)
    elseif tv == "boolean" then
      parts[i] = v and "true" or "false"
    elseif tv == "table" then
      parts[i] = json_encode(v)
    else
      parts[i] = "false"
    end
  end
  return "[" .. table.concat(parts, ",") .. "]"
end

-- Fast path for SampleMapData.json: decode each sample object individually instead of
-- handing the entire multi‑MB samples array to the recursive json_decode.
local function json_decode_sample_cache(content)
  if type(content) ~= "string" or content == "" then
    return nil
  end
  local data = {}

  local folders_json = SampleCacheCodec.extract_json_array(content, "folders")
  if folders_json then
    local ok, folders = pcall(json_decode, folders_json)
    if ok and type(folders) == "table" then
      data.folders = folders
    end
  end

  local map_seed = content:match('"map_seed"%s*:%s*([%-%d%.eE+]+)')
  if map_seed then
    data.map_seed = tonumber(map_seed)
  end

  local schema = content:match('"tag_schema_version"%s*:%s*([%-%d]+)')
  if schema then
    data.tag_schema_version = tonumber(schema)
  end

  local cache_v = content:match('"v"%s*:%s*([%-%d]+)')
  if cache_v then
    data.v = tonumber(cache_v)
  end

  local scan_total = content:match('"scan_total"%s*:%s*([%-%d%.eE+]+)')
  if scan_total then
    data.scan_total = tonumber(scan_total)
  end

  local scan_started = content:match('"scan_started"%s*:%s*([%-%d%.eE+]+)')
  if scan_started then
    data.scan_started = tonumber(scan_started)
  end

  local pending = content:match('"analyzer_pending"%s*:%s*(true|false)')
  if pending == "true" then
    data.analyzer_pending = true
  elseif pending == "false" then
    data.analyzer_pending = false
  end

  local function decode_field_array(key)
    local json = SampleCacheCodec.extract_json_array(content, key)
    if not json then return nil end
    local ok, decoded = pcall(json_decode, json)
    if ok and type(decoded) == "table" then
      return decoded
    end
    return nil
  end

  local function decode_field_object(key)
    local pattern = '"' .. key .. '"%s*:%s*(%b{})'
    local json = content:match(pattern)
    if not json then return nil end
    local ok, decoded = pcall(json_decode, json)
    if ok and type(decoded) == "table" then
      return decoded
    end
    return nil
  end

  data.dirs = decode_field_array("dirs") or {}
  data.tag_dict = decode_field_array("tag_dict") or {}
  data.scan_queue = decode_field_array("scan_queue") or {}
  data.analyzer_queue = decode_field_array("analyzer_queue") or {}
  data.analyzer_results = decode_field_object("analyzer_results") or {}
  local analyzer_mode = content:match('"analyzer_mode"%s*:%s*"([^"]*)"')
  if analyzer_mode and analyzer_mode ~= "" then
    data.analyzer_mode = analyzer_mode
  end

  local key_pos = content:find('"samples"%s*:', 1)
  if not key_pos then
    return nil
  end
  local arr_pos = content:find("%[", key_pos, true)
  if not arr_pos then
    return nil
  end
  -- Samples are decoded incrementally by the library loader (see next_json_sample).
  data._samples_pos = arr_pos + 1
  data._samples_content = content
  data.samples = {} -- filled during sliced process phase for JSON
  return data
end

-- Extract the next sample value from a SampleMapData.json samples array.
-- Supports v1 objects and v2 compact arrays. Returns table, next_pos; or nil when finished.
local function next_json_sample(content, pos)
  if not content or not pos then
    return nil, pos
  end
  local n = #content
  local byte = string.byte
  local sub = string.sub
  local i = pos
  while i <= n do
    local b = byte(content, i)
    if b ~= 32 and b ~= 9 and b ~= 10 and b ~= 13 and b ~= 44 then
      break
    end
    i = i + 1
  end
  if i > n then
    return nil, i
  end
  local b = byte(content, i)
  if b == 93 then -- ]
    return nil, i + 1
  end
  local open_b, close_b
  if b == 123 then -- {
    open_b, close_b = 123, 125
  elseif b == 91 then -- [
    open_b, close_b = 91, 93
  else
    return nil, i
  end
  local start = i
  local depth = 1
  i = i + 1
  local in_str = false
  local esc = false
  while i <= n and depth > 0 do
    local ch = byte(content, i)
    if in_str then
      if esc then
        esc = false
      elseif ch == 92 then
        esc = true
      elseif ch == 34 then
        in_str = false
      end
    else
      if ch == 34 then
        in_str = true
      elseif ch == open_b then
        depth = depth + 1
      elseif ch == close_b then
        depth = depth - 1
      end
    end
    i = i + 1
  end
  local ok, obj = pcall(json_decode, sub(content, start, i - 1))
  if ok and type(obj) == "table" then
    return obj, i
  end
  return nil, i
end


-- --- Preview helpers (track only) ----------------------------------------------
local function ensure_preview_track()
  if preview_track then
    local valid = false
    if r.ValidatePtr2 then
      valid = r.ValidatePtr2(0, preview_track, "MediaTrack*") and true or false
    elseif r.ValidatePtr then
      valid = r.ValidatePtr(preview_track, "MediaTrack*") and true or false
    end
    if valid then
      return preview_track
    end
    preview_track = nil
  end

  -- Try to find existing preview track
  for i = 0, r.CountTracks(0) - 1 do
    local tr = r.GetTrack(0, i)
    local _, name = r.GetTrackName(tr, "")
    if name == PREVIEW_TRACK_NAME then
      preview_track = tr
      break
    end
  end

  -- Create if missing
  if not preview_track then
    r.InsertTrackAtIndex(r.CountTracks(0), true)
    preview_track = r.GetTrack(0, r.CountTracks(0) - 1)
    r.GetSetMediaTrackInfo_String(preview_track, "P_NAME", PREVIEW_TRACK_NAME, true)
    -- Hide from TCP/mixer to avoid clutter
    r.SetMediaTrackInfo_Value(preview_track, "B_SHOWINTCP", 0)
    r.SetMediaTrackInfo_Value(preview_track, "B_SHOWINMIXER", 0)
    -- Keep normal routing (main send on)
    r.SetMediaTrackInfo_Value(preview_track, "B_MAINSEND", 1)
  end

  return preview_track
end


-- --- Persistence -------------------------------------------------------------
function is_valid_project(proj)
  if proj == nil or proj == false then
    return false
  end
  if r.ValidatePtr2 then
    local ok, valid = pcall(r.ValidatePtr2, 0, proj, "ReaProject*")
    if ok then
      return valid and true or false
    end
  end
  if r.ValidatePtr then
    local ok, valid = pcall(r.ValidatePtr, proj, "ReaProject*")
    if ok then
      return valid and true or false
    end
  end
  return type(proj) == "userdata"
end

function get_current_project()
  if r.EnumProjects then
    local proj = r.EnumProjects(-1, "")
    if is_valid_project(proj) then
      return proj
    end
  end
  return nil
end

function reset_seq_project_state()
  if state.seq_swap_saved_active_tags ~= nil then
    state.active_tags = {}
    for tag, active in pairs(state.seq_swap_saved_active_tags) do
      if active then
        state.active_tags[tag] = true
      end
    end
  end
  state.seq_tracks = {}
  state.selected_seq_track = nil
  state.seq_folder_guid = nil
  state.seq_swap_track_idx = nil
