SHORTCUT_KEY_LABELS = {
  LeftArrow = "Left",
  RightArrow = "Right",
  UpArrow = "Up",
  DownArrow = "Down",
  PageUp = "Page Up",
  PageDown = "Page Down",
  Backspace = "Backspace",
  Delete = "Delete",
  Space = "Space",
  Escape = "Esc",
  Enter = "Enter",
  Tab = "Tab",
  Insert = "Insert",
  Home = "Home",
  End = "End",
  Minus = "-",
  Equal = "=",
  LeftBracket = "[",
  RightBracket = "]",
  Backslash = "\\",
  Semicolon = ";",
  Apostrophe = "'",
  Comma = ",",
  Period = ".",
  Slash = "/",
  GraveAccent = "`",
  KeypadDecimal = "Num .",
  KeypadDivide = "Num /",
  KeypadMultiply = "Num *",
  KeypadSubtract = "Num -",
  KeypadAdd = "Num +",
  KeypadEnter = "Num Enter",
  KeypadEqual = "Num =",
}

SHORTCUT_CAPTURE_KEY_IDS = nil

function shortcut_capture_key_ids()
  if SHORTCUT_CAPTURE_KEY_IDS then
    return SHORTCUT_CAPTURE_KEY_IDS
  end
  local keys = {
    "Tab", "LeftArrow", "RightArrow", "UpArrow", "DownArrow",
    "PageUp", "PageDown", "Home", "End", "Insert", "Delete",
    "Backspace", "Space", "Enter", "Escape",
    "Minus", "Equal", "LeftBracket", "RightBracket", "Backslash",
    "Semicolon", "Apostrophe", "Comma", "Period", "Slash", "GraveAccent",
    "KeypadDecimal", "KeypadDivide", "KeypadMultiply", "KeypadSubtract",
    "KeypadAdd", "KeypadEnter", "KeypadEqual",
  }
  local i
  for i = 0, 9 do
    keys[#keys + 1] = tostring(i)
  end
  for i = 0, 9 do
    keys[#keys + 1] = "Keypad" .. tostring(i)
  end
  for i = 1, 12 do
    keys[#keys + 1] = "F" .. tostring(i)
  end
  for i = 65, 90 do
    keys[#keys + 1] = string.char(i)
  end
  SHORTCUT_CAPTURE_KEY_IDS = keys
  return keys
end

function shortcut_key_label(key)
  if not key or key == "" then
    return "None"
  end
  if SHORTCUT_KEY_LABELS[key] then
    return SHORTCUT_KEY_LABELS[key]
  end
  local kp = string.match(key, "^Keypad(%d)$")
  if kp then
    return "Num " .. kp
  end
  return key
end

function clone_shortcut_spec(spec)
  if type(spec) ~= "table" then
    return nil
  end
  return {
    key = spec.key,
    shift = spec.shift and true or nil,
    alt = spec.alt and true or nil,
    ctrl = spec.ctrl and true or nil,
    cmd = spec.cmd and true or nil,
    cmdctrl = spec.cmdctrl and true or nil,
  }
end

function get_shortcut(action)
  local custom = state.keyboard_shortcuts and state.keyboard_shortcuts[action]
  if type(custom) == "table" then
    if type(custom.key) ~= "string" or custom.key == "" then
      return nil
    end
    return custom
  end
  return KEYBOARD_SHORTCUT_DEFAULTS[action]
end

function shortcut_would_fire(spec, shift, alt, ctrl, cmd)
  if not spec or not spec.key or spec.key == "" then
    return false
  end
  if (spec.shift and true or false) ~= (shift and true or false) then
    return false
  end
  if (spec.alt and true or false) ~= (alt and true or false) then
    return false
  end
  if spec.cmdctrl then
    return (ctrl and true or false) or (cmd and true or false)
  end
  if (spec.ctrl and true or false) ~= (ctrl and true or false) then
    return false
  end
  if (spec.cmd and true or false) ~= (cmd and true or false) then
    return false
  end
  return true
end

function shortcuts_conflict(a, b)
  if not a or not b or a.key == "" or b.key == "" or a.key ~= b.key then
    return false
  end
  local si, ai, ci, mi
  for si = 0, 1 do
    for ai = 0, 1 do
      for ci = 0, 1 do
        for mi = 0, 1 do
          if shortcut_would_fire(a, si == 1, ai == 1, ci == 1, mi == 1)
              and shortcut_would_fire(b, si == 1, ai == 1, ci == 1, mi == 1) then
            return true
          end
        end
      end
    end
  end
  return false
end

function shortcut_display(action_or_spec)
  local spec = action_or_spec
  if type(action_or_spec) == "string" then
    spec = get_shortcut(action_or_spec)
  end
  if not spec or not spec.key or spec.key == "" then
    return "None"
  end
  local parts = {}
  if spec.cmdctrl then
    parts[#parts + 1] = "Ctrl/Cmd"
  else
    if spec.ctrl then
      parts[#parts + 1] = "Ctrl"
    end
    if spec.cmd then
      parts[#parts + 1] = "Cmd"
    end
  end
  if spec.alt then
    parts[#parts + 1] = "Alt"
  end
  if spec.shift then
    parts[#parts + 1] = "Shift"
  end
  parts[#parts + 1] = shortcut_key_label(spec.key)
  return table.concat(parts, "+")
end

function shortcut_conflict_label(action)
  local spec = get_shortcut(action)
  if not spec then
    return nil
  end
  local i
  for i = 1, #KEYBOARD_SHORTCUT_ACTIONS do
    local other = KEYBOARD_SHORTCUT_ACTIONS[i]
    if other.id ~= action and shortcuts_conflict(spec, get_shortcut(other.id)) then
      return other.label
    end
  end
  return nil
end

function shortcut_key_pressed(key_id)
  if not key_id or key_id == "" or not r.ImGui_IsKeyPressed then
    return false
  end
  local fn = r["ImGui_Key_" .. key_id]
  if not fn then
    return false
  end
  return r.ImGui_IsKeyPressed(ctx, fn(), false)
end

function shortcut_pressed(action)
  if state.shortcut_capture_id then
    return false
  end
  if imgui_text_input_active and imgui_text_input_active() then
    return false
  end
  local spec = get_shortcut(action)
  if not spec then
    return false
  end
  if not shortcut_would_fire(spec, is_shift_down(), is_alt_down(), is_ctrl_down(), is_cmd_down()) then
    return false
  end
  return shortcut_key_pressed(spec.key)
end

function shortcut_poll_pressed_key()
  if not r.ImGui_IsKeyPressed then
    return nil
  end
  local keys = shortcut_capture_key_ids()
  local i
  for i = 1, #keys do
    if shortcut_key_pressed(keys[i]) then
      return keys[i]
    end
  end
  return nil
end

function shortcut_spec_from_press(key)
  local spec = { key = key }
  if is_shift_down() then
    spec.shift = true
  end
  if is_alt_down() then
    spec.alt = true
  end
  if is_ctrl_down() then
    spec.ctrl = true
  end
  if is_cmd_down() then
    spec.cmd = true
  end
  return spec
end

function shortcut_assign(action, spec)
  state.keyboard_shortcuts = state.keyboard_shortcuts or {}
  spec = clone_shortcut_spec(spec) or { key = "" }
  local i
  for i = 1, #KEYBOARD_SHORTCUT_ACTIONS do
    local other = KEYBOARD_SHORTCUT_ACTIONS[i]
    if other.id ~= action and shortcuts_conflict(spec, get_shortcut(other.id)) then
      state.keyboard_shortcuts[other.id] = { key = "" }
    end
  end
  state.keyboard_shortcuts[action] = spec
  save_config()
end

function shortcut_reset_one(action)
  state.keyboard_shortcuts = state.keyboard_shortcuts or {}
  state.keyboard_shortcuts[action] = nil
  save_config()
end

function shortcut_reset_all()
  state.keyboard_shortcuts = {}
  state.shortcut_capture_id = nil
  save_config()
end

local function update_pending_drop_tracking()
  if not state.pending_waveform_drop then
    return
  end
  local time_pos, track = get_drop_position()
  if time_pos then
    state.last_mouse_time_pos = time_pos
    state.last_mouse_track = track
  end
end

local function clamp_effective_duration(sample, seconds)
  local file_dur = (sample and type(sample.duration) == "number" and sample.duration > 0) and sample.duration or nil
  seconds = tonumber(seconds) or 0
  if file_dur then
    return math.max(0.001, math.min(file_dur, seconds))
  end
  return math.max(0.001, seconds)
end

local function render_waveform_overlay_tags(x0, y0, width, height, layout_x, layout_y)
  local consumed = false
  local path = preview_sample_obj and preview_sample_obj.path
  local tags = (preview_sample_obj and type(preview_sample_obj.tags) == "table") and preview_sample_obj.tags or {}
  local pad = 4
  local gap = 3
  local plus_w, plus_h = 22, 22

  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 3, 2)
  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FramePadding(), 3, 1)
  local pad_x, pad_y = r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())
  pad_x = pad_x or 3
  pad_y = pad_y or 1

  local chips = {}
  for _, tag in ipairs(tags) do
    local text_w, text_h = r.ImGui_CalcTextSize(ctx, tag)
    chips[#chips + 1] = {
      kind = "tag",
      tag = tag,
      w = (text_w or 0) + pad_x * 2,
      h = (text_h or 14) + pad_y * 2,
    }
  end
  if path and path ~= "" then
    chips[#chips + 1] = { kind = "plus", w = plus_w, h = plus_h }
  end

  local max_w = math.max(plus_w, (width or 0) - pad * 2)
  local rows = {}
  local cur = { items = {}, w = 0, h = 0 }
  local function flush_row()
    if #cur.items > 0 then
      rows[#rows + 1] = cur
      cur = { items = {}, w = 0, h = 0 }
    end
  end
  for _, chip in ipairs(chips) do
    local need = chip.w + ((#cur.items > 0) and gap or 0)
    if #cur.items > 0 and cur.w + need > max_w then
      flush_row()
    end
    cur.items[#cur.items + 1] = chip
    cur.w = cur.w + need
    cur.h = math.max(cur.h, chip.h)
  end
  flush_row()

  local total_h = 0
  for i, row in ipairs(rows) do
    if i > 1 then
      total_h = total_h + 2
    end
    total_h = total_h + row.h
  end
  local y = math.max(y0 + pad, y0 + (height or 0) - pad - total_h)
  for _, row in ipairs(rows) do
    local x = x0 + (width or 0) - pad - row.w
    for _, chip in ipairs(row.items) do
      r.ImGui_SetCursorScreenPos(ctx, x, y + math.max(0, (row.h - chip.h) * 0.5))
      if chip.kind == "tag" then
        local active = state.active_tags[chip.tag] or false
        if draw_tag_button(ctx, chip.tag, active, chip.tag, "waveform_") then
          if active then
            state.active_tags[chip.tag] = nil
          else
            toggle_sample_map_tag_filter(chip.tag)
          end
        end
      else
        if draw_ui_button("wave_add_tag", "+", plus_w, plus_h, { compact = true, pill = true }) then
          tag_add_open_for(path)
          r.ImGui_OpenPopup(ctx, "##tag_add_popup")
        end
        if r.ImGui_IsItemHovered(ctx) and r.ImGui_SetTooltip then
          r.ImGui_SetTooltip(ctx, "Add a tag")
        end
      end
      if r.ImGui_IsItemHovered(ctx) then
        consumed = true
      end
      x = x + chip.w + gap
    end
    y = y + row.h + 2
  end

  r.ImGui_PopStyleVar(ctx, 2)
  render_tag_add_popup()
  r.ImGui_SetCursorPos(ctx, layout_x, layout_y)
  r.ImGui_Dummy(ctx, 0, 0)
  return consumed
end

function path_explorer_button_width()
  local tw = select(1, r.ImGui_CalcTextSize(ctx, "Explorer"))
  return tw + 18
end

function render_path_explorer_button(x, y)
  local label = "Explorer"
  local btn_w = path_explorer_button_width()
  local btn_h = 22
  if x and y then
    r.ImGui_SetCursorScreenPos(ctx, x, y)
  end
  if draw_ui_button("path_open_explorer", label, btn_w, btn_h, {
    style = state.explorer_open and "primary" or "default",
    compact = true,
    selected = state.explorer_open,
  }) then
    state.explorer_open = not state.explorer_open
    save_config()
  end
  if r.ImGui_IsItemHovered(ctx) then
    r.ImGui_SetTooltip(ctx, "Browse scan folders and set custom tags.\nDock the window on the right of the sample map, or leave it floating.")
  end
end

function render_sample_path_line()
  local wx, wy = r.ImGui_GetWindowPos(ctx)
  local ww, wh = r.ImGui_GetWindowSize(ctx)
  local pad = 4
  local ox, oy = wx + pad, wy + pad
  local avail_w = math.max(1, (ww or 1) - pad * 2)
  local avail_h = math.max(1, (wh or 1) - pad * 2)
  local explorer_w = path_explorer_button_width()
  local explorer_gap = 8
  local inner_w = math.max(40, avail_w - explorer_w - explorer_gap)
  local wrap = avail_h >= 46

  render_path_explorer_button(ox + avail_w - explorer_w, oy)

  local crumb_flags = 0
  local extra_pop = 0
  if not wrap then
    crumb_flags = r.ImGui_WindowFlags_HorizontalScrollbar() | r.ImGui_WindowFlags_NoScrollWithMouse()
    if r.ImGui_StyleVar_ScrollbarSize then
      r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ScrollbarSize(), 0.01)
      extra_pop = 1
    end
  end
  r.ImGui_SetCursorScreenPos(ctx, ox, oy)
  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), 0, 0)
  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 2, 2)
  local crumbs_open = r.ImGui_BeginChild(ctx, "path_crumbs", inner_w, wrap and avail_h or math.max(avail_h, 22), 0, crumb_flags)
  if crumbs_open then
    local function path_advance(needed_w, first)
      if first then
        return
      end
      if wrap then
        imgui_same_line_if_fits(needed_w, 2)
      else
        r.ImGui_SameLine(ctx, 0, 2)
      end
    end

    if not preview_sample_obj then
      r.ImGui_Text(ctx, "(No sample selected)")
    else
      local full_path = preview_sample_obj.path or ""
      local path_segments = {}
      local filename = preview_sample_obj.name or "Unknown"
      if full_path ~= "" then
        local normalized_path = normalize_path(full_path)
        local scanned_root = nil
        for _, scanned_folder in ipairs(state.folders) do
          local norm_scanned = normalize_path(scanned_folder)
          if normalized_path:sub(1, #norm_scanned) == norm_scanned then
            if not scanned_root or #norm_scanned > #scanned_root then
              scanned_root = norm_scanned
            end
          end
        end
        local dir_path = normalized_path:match("(.+)/[^/]+$") or ""
        if scanned_root and dir_path ~= "" then
          local root_name = scanned_root:match("([^/]+)/?$") or scanned_root
          table.insert(path_segments, { name = root_name, path = scanned_root })
          local relative_path = dir_path
          if dir_path:sub(1, #scanned_root) == scanned_root then
            relative_path = dir_path:sub(#scanned_root + 1)
            if relative_path:sub(1, 1) == "/" then
              relative_path = relative_path:sub(2)
            end
          end
          if relative_path ~= "" then
            local current_path = scanned_root
            for segment in relative_path:gmatch("([^/]+)") do
              current_path = current_path .. "/" .. segment
              table.insert(path_segments, { name = segment, path = current_path })
            end
          end
        elseif dir_path ~= "" then
          local is_absolute = dir_path:sub(1, 1) == "/"
          local current_path = is_absolute and "/" or ""
          for segment in dir_path:gmatch("([^/]+)") do
            if is_absolute then
              current_path = current_path .. segment
            else
              current_path = current_path .. (current_path == "" and "" or "/") .. segment
            end
            table.insert(path_segments, { name = segment, path = current_path })
            if is_absolute then
              current_path = current_path .. "/"
            end
          end
        end
      end

      for i, seg in ipairs(path_segments) do
        local text_size = { r.ImGui_CalcTextSize(ctx, seg.name) }
        local frame_padding = 6.0
        local button_width = text_size[1] + frame_padding * 2
        local button_height = text_size[2] + 6.0
        local chevron_w = 10
        if i > 1 then
          path_advance(chevron_w + 2 + button_width, false)
          local cx, cy = r.ImGui_GetCursorScreenPos(ctx)
          local sep_h = 18
          r.ImGui_Dummy(ctx, chevron_w, sep_h)
          ui_button_draw_icon(r.ImGui_GetWindowDrawList(ctx), "chev_right", cx + 5, cy + sep_h * 0.5, 12, UI_THEME.text_mute)
          path_advance(button_width, false)
        end

        local is_filtered = folder_filter_has(seg.path)
        local clicked = r.ImGui_InvisibleButton(ctx, "##path_btn_" .. i .. "_" .. seg.name, button_width, button_height)
        local hovered = r.ImGui_IsItemHovered(ctx)
        local pressed = r.ImGui_IsItemActive(ctx)
        local x0, y0 = r.ImGui_GetItemRectMin(ctx)
        local x1, y1 = r.ImGui_GetItemRectMax(ctx)
        local bg, border, text_col
        if is_filtered then
          bg = hovered and UI_THEME.accent_fill_h or UI_THEME.accent_fill
          border = UI_THEME.accent
          text_col = 0xFFFFFFFF
        elseif hovered then
          bg = UI_THEME.surface_hvr
          border = UI_THEME.border_hvr
          text_col = UI_THEME.text
        else
          bg = UI_THEME.surface
          border = UI_THEME.border
          text_col = UI_THEME.text_dim
        end
        local dl = r.ImGui_GetWindowDrawList(ctx)
        ui_draw_panel(dl, x0, y0, x1, y1, button_height * 0.5, bg, border, hovered, pressed)
        local text_x = x0 + frame_padding
        local text_y = y0 + (button_height - text_size[2]) * 0.5 + (pressed and 1.0 or 0.0)
        r.ImGui_DrawList_AddText(dl, text_x, text_y, text_col, seg.name)
        if clicked then
          folder_filter_toggle(seg.path)
        end
      end

      local slash = " / "
      local name_w = (select(1, r.ImGui_CalcTextSize(ctx, slash)) or 8)
        + (select(1, r.ImGui_CalcTextSize(ctx, filename)) or 40)
      path_advance(name_w, #path_segments == 0)
      if #path_segments > 0 then
        r.ImGui_Text(ctx, slash)
        path_advance(select(1, r.ImGui_CalcTextSize(ctx, filename)) or 40, false)
      end
      r.ImGui_TextColored(ctx, 0xFFCCCCCC, filename)
    end

    if not wrap and r.ImGui_SetScrollX and r.ImGui_IsWindowHovered and r.ImGui_IsWindowHovered(ctx) then
      local wheel, wheel_h = 0, 0
      if r.ImGui_GetMouseWheel then
        wheel, wheel_h = r.ImGui_GetMouseWheel(ctx)
      end
      local dx = (wheel_h or 0) - (wheel or 0)
      if dx ~= 0 then
        r.ImGui_SetScrollX(ctx, (r.ImGui_GetScrollX(ctx) or 0) - dx * 48)
      end
    end
    r.ImGui_Dummy(ctx, 0, 0)
  end
  imgui_end_child(crumbs_open)
  r.ImGui_PopStyleVar(ctx, 2 + extra_pop)
  r.ImGui_Dummy(ctx, 0, 0)
end

local function map_waveform_handle_preview_click(sample, hovered, clicked, left_down, mx, x0, width, view0, view1, blocked)
  if blocked or not sample or not sample.path then
    if blocked then
      state.map_wave_press = nil
      state.map_wave_press_t = nil
    end
    return
  end
  local dbl = hovered and clicked and r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0)
  local playing_now = preview_proc ~= nil and preview_sample_obj ~= nil
      and preview_sample_obj.path == sample.path
  if hovered and clicked and not dbl then
    if playing_now then
      stop_preview()
      state.preview_paused = false
      state.map_wave_press = nil
      state.map_wave_press_t = nil
    else
      state.map_wave_press = sample
      state.map_wave_press_t = wave_x_to_time(mx, x0, width, view0, view1)
    end
  end
  if state.waveform_eff_drag or state.wave_view_pan or state.pending_waveform_drop then
    state.map_wave_press = nil
    state.map_wave_press_t = nil
  end
  if state.map_wave_press and not left_down then
    local press_sample = state.map_wave_press
    local press_t = state.map_wave_press_t
    state.map_wave_press = nil
    state.map_wave_press_t = nil
    if press_sample and press_sample.path then
      preview_sample(press_sample, press_t)
    end
  end
end

local function render_waveform()
  local wh = select(2, r.ImGui_GetWindowSize(ctx))
  local height = math.max(48, (wh or 80) - 8)
  if preview_sample_obj then
    if not waveform_data or waveform_data.sample_path ~= preview_sample_obj.path then
      ensure_waveform_for_sample(preview_sample_obj)
    end
  end

  local width = r.ImGui_GetContentRegionAvail(ctx)
  local pos_x, pos_y = r.ImGui_GetCursorScreenPos(ctx)
  local x0, y0 = pos_x, pos_y

  r.ImGui_InvisibleButton(ctx, "waveform_area", width, height)
  local layout_x, layout_y = r.ImGui_GetCursorPos(ctx)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local dl = r.ImGui_GetWindowDrawList(ctx)

  if state.pending_waveform_drop then
    if hovered then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
    update_pending_drop_tracking()
  end

  ui_draw_panel(dl, x0, y0, x0 + width, y0 + height, 6.0, UI_THEME.bg_panel, UI_THEME.border, false, false)

  if not preview_sample_obj or not waveform_data then
    local msg = preview_sample_obj and "Loading waveform…" or "No sample selected"
    local tw = select(1, r.ImGui_CalcTextSize(ctx, msg)) or 0
    r.ImGui_DrawList_AddText(dl, x0 + (width - tw) * 0.5, y0 + height * 0.5 - 7, UI_THEME.text_mute, msg)
    render_waveform_overlay_tags(x0, y0, width, height, layout_x, layout_y)
    return
  end

  local waveform = waveform_data.data
  local file_dur = (waveform_data.duration or (preview_sample_obj and preview_sample_obj.duration) or 0.0)
  local view0, view1 = wave_view_ensure(preview_sample_obj, file_dur)
  local view_span = math.max(0.001, view1 - view0)
  local function map_x(t)
    return x0 + (((t or 0) - view0) / view_span) * width
  end
  if not waveform or #waveform == 0 then
    -- Show message if no waveform data
    r.ImGui_DrawList_AddText(dl, x0 + width * 0.5 - 50, y0 + height * 0.5, 0xFFFFFFFF, "No waveform data")
    local mx, my = r.ImGui_GetMousePos(ctx)
    local ctl = draw_sample_wave_controls(
      dl, preview_sample_obj, x0, y0, width, height, file_dur, view0, view1,
      mx, my, r.ImGui_IsMouseDown(ctx, 0), clicked, "map", { show_name = false }
    )
    local tags_hit = render_waveform_overlay_tags(x0, y0, width, height, layout_x, layout_y)
    local blocked = tags_hit or (ctl and ctl.consumed) or state.wave_view_pan or state.pending_waveform_drop
    if preview_sample_obj and preview_sample_obj.path
        and not blocked
        and waveform_drag_should_start(hovered) then
      begin_waveform_sample_drag(preview_sample_obj)
      state.map_wave_press = nil
      state.map_wave_press_t = nil
    end
    if sample_is_waveform_drag_source(preview_sample_obj) then
      draw_waveform_drag_source_cue(dl, x0, y0, width, height)
    end
    map_waveform_handle_preview_click(
      preview_sample_obj, hovered, clicked, r.ImGui_IsMouseDown(ctx, 0),
      mx, x0, width, view0, view1, blocked
    )
    return
  end
  
  if waveform and #waveform > 0 then
    if r.ImGui_DrawList_PushClipRect then
      r.ImGui_DrawList_PushClipRect(dl, x0, y0, x0 + width, y0 + height, true)
    end
    local channels = waveform_data.channels or 1
    local channel_data = waveform_data.channel_data
    local frequency_data = waveform_data.frequency_data
    local frequency_channel_data = waveform_data.frequency_channel_data
    
    -- For mono: draw centered waveform (backward compatible)
    -- For stereo+: draw separate waveforms per channel
    if channels == 1 or not channel_data then
      -- Mono waveform: centered display
      local center_y = y0 + height * 0.5
      local half_height = height * 0.4
      
      -- Draw center line
      r.ImGui_DrawList_AddLine(dl, x0, center_y, x0 + width, center_y, 0x444444FF, 1.0)
      
      -- Draw waveform
      local n = #waveform
      local i0 = math.max(1, math.floor((view0 / math.max(file_dur, 0.0001)) * n) - 1)
      local i1 = math.min(n, math.ceil((view1 / math.max(file_dur, 0.0001)) * n) + 1)
      local prev_x = nil
      local prev_y_top = center_y
      local prev_y_bot = center_y
      local prev_color = nil
      
      for i = i0, i1 do
        local x = map_x(((i - 1) / n) * file_dur)
        local value = waveform[i] or 0.0
        local y_top = center_y - value * half_height
        local y_bot = center_y + value * half_height
        
        -- Get frequency-based color for this pixel
        local freq = frequency_data and frequency_data[i]
        local color = frequency_to_color(freq)
        
        -- Draw vertical line for this sample
        r.ImGui_DrawList_AddLine(dl, x, y_top, x, y_bot, color, 1.5)
        
        -- Draw connecting line to previous sample (use average color for smooth transition)
        if prev_x then
          local prev_freq = frequency_data and frequency_data[i - 1]
          local prev_color_val = frequency_to_color(prev_freq)
          -- Blend colors for smooth transition
          local avg_color = color
          if prev_color_val ~= color then
            -- Simple average of RGB components
            local r1 = (color >> 16) & 0xFF
            local g1 = (color >> 8) & 0xFF
            local b1 = color & 0xFF
            local r2 = (prev_color_val >> 16) & 0xFF
            local g2 = (prev_color_val >> 8) & 0xFF
            local b2 = prev_color_val & 0xFF
            local r_avg = math.floor((r1 + r2) / 2)
            local g_avg = math.floor((g1 + g2) / 2)
            local b_avg = math.floor((b1 + b2) / 2)
            avg_color = (0xFF << 24) | (r_avg << 16) | (g_avg << 8) | b_avg
          end
          r.ImGui_DrawList_AddLine(dl, prev_x, prev_y_top, x, y_top, avg_color, 1.0)
          r.ImGui_DrawList_AddLine(dl, prev_x, prev_y_bot, x, y_bot, avg_color, 1.0)
        end
        
        prev_x = x
        prev_y_top = y_top
        prev_y_bot = y_bot
        prev_color = color
      end
    else
      -- Multi-channel waveform: draw separate waveforms per channel
      -- For stereo: left channel on top half, right channel on bottom half
      local channel_height = height / channels
      
      for ch = 0, channels - 1 do
        local ch_data = channel_data[ch]
        local ch_freq_data = frequency_channel_data and frequency_channel_data[ch]
        if ch_data and #ch_data > 0 then
          -- Calculate channel-specific parameters
          local ch_y0 = y0 + ch * channel_height
          local ch_y1 = y0 + (ch + 1) * channel_height
          local ch_center_y = (ch_y0 + ch_y1) * 0.5
          local ch_half_height = channel_height * 0.4
          
          -- Draw center line for this channel
          r.ImGui_DrawList_AddLine(dl, x0, ch_center_y, x0 + width, ch_center_y, 0x444444FF, 1.0)
          
          -- Draw waveform for this channel
          local n = #ch_data
          local i0 = math.max(1, math.floor((view0 / math.max(file_dur, 0.0001)) * n) - 1)
          local i1 = math.min(n, math.ceil((view1 / math.max(file_dur, 0.0001)) * n) + 1)
          local prev_x = nil
          local prev_y_top = ch_center_y
          local prev_y_bot = ch_center_y
          
          for i = i0, i1 do
            local x = map_x(((i - 1) / n) * file_dur)
            local value = ch_data[i] or 0.0
            local y_top = ch_center_y - value * ch_half_height
            local y_bot = ch_center_y + value * ch_half_height
            
            -- Get frequency-based color for this pixel/channel
            local freq = ch_freq_data and ch_freq_data[i]
            local color = frequency_to_color(freq)
            
            -- Draw vertical line for this sample
            r.ImGui_DrawList_AddLine(dl, x, y_top, x, y_bot, color, 1.5)
            
            -- Draw connecting line to previous sample (use average color for smooth transition)
            if prev_x then
              local prev_freq = ch_freq_data and ch_freq_data[i - 1]
              local prev_color_val = frequency_to_color(prev_freq)
              -- Blend colors for smooth transition
              local avg_color = color
              if prev_color_val ~= color then
                -- Simple average of RGB components
                local r1 = (color >> 16) & 0xFF
                local g1 = (color >> 8) & 0xFF
                local b1 = color & 0xFF
                local r2 = (prev_color_val >> 16) & 0xFF
                local g2 = (prev_color_val >> 8) & 0xFF
                local b2 = prev_color_val & 0xFF
                local r_avg = math.floor((r1 + r2) / 2)
                local g_avg = math.floor((g1 + g2) / 2)
                local b_avg = math.floor((b1 + b2) / 2)
                avg_color = (0xFF << 24) | (r_avg << 16) | (g_avg << 8) | b_avg
              end
              r.ImGui_DrawList_AddLine(dl, prev_x, prev_y_top, x, y_top, avg_color, 1.0)
              r.ImGui_DrawList_AddLine(dl, prev_x, prev_y_bot, x, y_bot, avg_color, 1.0)
            end
            
            prev_x = x
            prev_y_top = y_top
            prev_y_bot = y_bot
          end
          
          -- Draw separator line between channels (except after last channel)
          if ch < channels - 1 then
            r.ImGui_DrawList_AddLine(dl, x0, ch_y1, x0 + width, ch_y1, 0x333333FF, 1.0)
          end
        end
      end
    end
    
    -- Effective length marker (draggable) + dim cropped tail
    if preview_sample_obj and file_dur > 0 and width > 1 then
      if state.waveform_eff_drag and state.waveform_eff_drag_path
          and state.waveform_eff_drag_path ~= preview_sample_obj.path then
        state.waveform_eff_drag = false
        state.waveform_eff_drag_path = nil
      end

      local eff = sample_map_duration(preview_sample_obj)
      if eff <= 0 then
        eff = file_dur
      end
      local eff_x = math.max(x0, math.min(x0 + width, map_x(eff)))

      if eff < file_dur - 0.0005 then
        r.ImGui_DrawList_AddRectFilled(dl, eff_x, y0, x0 + width, y0 + height, 0x00000099, 0)
      end

      local handle_color = 0xFF9A3CFF  -- Orange (RRGGBBAA)
      local handle_hover = 0xFFC070FF
      local mx, my = r.ImGui_GetMousePos(ctx)
      local handle_hit = 8.0
      local near_handle = math.abs(mx - eff_x) <= handle_hit and my >= y0 - 4 and my <= y0 + height + 4
      local color = (near_handle or state.waveform_eff_drag) and handle_hover or handle_color

      r.ImGui_DrawList_AddLine(dl, eff_x, y0, eff_x, y0 + height, color, 2.0)
      local tri = 7.0
      r.ImGui_DrawList_AddTriangleFilled(dl,
        eff_x, y0 + 1,
        eff_x - tri, y0 + tri + 1,
        eff_x + tri, y0 + tri + 1,
        color)
      r.ImGui_DrawList_AddTriangleFilled(dl,
        eff_x, y0 + height - 1,
        eff_x - tri, y0 + height - tri - 1,
        eff_x + tri, y0 + height - tri - 1,
        color)

      local label = string.format("%.2fs", eff)
      local label_w = select(1, r.ImGui_CalcTextSize(ctx, label)) or 36
      local label_x = math.min(eff_x + 6, x0 + width - label_w - 4)
      if label_x < x0 + 4 then
        label_x = x0 + 4
      end
      r.ImGui_DrawList_AddText(dl, label_x + 1, y0 + 8, 0x000000AA, label)
      r.ImGui_DrawList_AddText(dl, label_x, y0 + 7, color, label)

      if (hovered and near_handle) or state.waveform_eff_drag then
        if r.ImGui_MouseCursor_ResizeEW then
          r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeEW())
        else
          r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
        end
      end

      if hovered and near_handle and not state.waveform_eff_drag then
        r.ImGui_BeginTooltip(ctx)
        r.ImGui_Text(ctx, "Effective length")
        r.ImGui_Text(ctx, "Drag to crop trailing silence")
        r.ImGui_TextColored(ctx, 0xAAAAAAFF, "Double-click to reset to full file")
        r.ImGui_EndTooltip(ctx)
      end

      if hovered and near_handle and r.ImGui_IsMouseDoubleClicked(ctx, 0) then
        preview_sample_obj.effective_duration = file_dur
        state.waveform_eff_drag = false
        state.waveform_eff_drag_path = nil
        save_samples()
        layout_samples()
        clicked = false
      elseif (clicked and near_handle) or state.waveform_eff_drag then
        if r.ImGui_IsMouseDown(ctx, 0) then
          state.waveform_eff_drag = true
          state.waveform_eff_drag_path = preview_sample_obj.path
          preview_sample_obj.effective_duration = clamp_effective_duration(
            preview_sample_obj, wave_x_to_time(mx, x0, width, view0, view1)
          )
          clicked = false
        elseif state.waveform_eff_drag then
          state.waveform_eff_drag = false
          state.waveform_eff_drag_path = nil
          save_samples()
          layout_samples()
          clicked = false
        end
      end
    end

    -- Transient / sustain split (drum one-shots)
    if preview_sample_obj and type(preview_sample_obj.transient_end) == "number"
        and preview_sample_obj.transient_end > 0 and width > 1 then
      local ts_dur = waveform_data.duration or preview_sample_obj.duration or 0.0
      if ts_dur > 0 then
        local function time_to_x(t)
          return math.max(x0, math.min(x0 + width, map_x(t)))
        end
        local onset_t = preview_sample_obj.onset
        if type(onset_t) ~= "number" or onset_t < 0 then
          onset_t = 0.0
        end
        local trans_t = preview_sample_obj.transient_end
        local sustain_t = sample_map_duration(preview_sample_obj)
        if sustain_t <= 0 then
          sustain_t = ts_dur
        end
        local onset_x = time_to_x(onset_t)
        local trans_x = time_to_x(trans_t)
        local sustain_x = time_to_x(sustain_t)

        if trans_x > onset_x + 0.5 then
          r.ImGui_DrawList_AddRectFilled(dl, onset_x, y0, trans_x, y0 + height, 0xFF6B3C33, 0)
        end
        if sustain_x > trans_x + 0.5 then
          r.ImGui_DrawList_AddRectFilled(dl, trans_x, y0, sustain_x, y0 + height, 0x4A9CFF28, 0)
        end

        local ts_color = 0x7CFF4AFF  -- Lime (RRGGBBAA)
        r.ImGui_DrawList_AddLine(dl, trans_x, y0, trans_x, y0 + height, ts_color, 2.0)
        local tri = 5.5
        r.ImGui_DrawList_AddTriangleFilled(dl,
          trans_x, y0,
          trans_x - tri, y0 + tri,
          trans_x + tri, y0 + tri,
          ts_color)
        r.ImGui_DrawList_AddTriangleFilled(dl,
          trans_x, y0 + height,
          trans_x - tri, y0 + height - tri,
          trans_x + tri, y0 + height - tri,
          ts_color)
        if (trans_x - onset_x) >= 10.0 then
          r.ImGui_DrawList_AddText(dl, onset_x + 3, y0 + 2, ts_color, "T")
        end
        if (sustain_x - trans_x) >= 10.0 then
          r.ImGui_DrawList_AddText(dl, trans_x + 4, y0 + 2, 0xA8D4FFFF, "S")
        end
      end
    end

    -- Draw snap offset marker if available
    if preview_sample_obj and preview_sample_obj.snap_offset then
      local snap_time = preview_sample_obj.snap_offset
      local duration = waveform_data.duration or preview_sample_obj.duration or 1.0
      if duration > 0 and snap_time >= 0 and snap_time <= duration then
        local snap_x = math.max(x0, math.min(x0 + width, map_x(snap_time)))
        
        -- Draw snap offset line (bright yellow/green, distinct from playhead)
        local snap_color = 0x00FFFFFF  -- Cyan (RRGGBBAA format)
        local snap_thickness = 2.5
        r.ImGui_DrawList_AddLine(dl, snap_x, y0, snap_x, y0 + height, snap_color, snap_thickness)
        
        -- Draw snap offset indicators at top and bottom (triangles pointing down/up)
        local triangle_size = 6.0
        -- Top triangle (pointing down)
        r.ImGui_DrawList_AddTriangleFilled(dl, 
          snap_x, y0, 
          snap_x - triangle_size, y0 + triangle_size, 
          snap_x + triangle_size, y0 + triangle_size, 
          snap_color)
        -- Bottom triangle (pointing up)
        r.ImGui_DrawList_AddTriangleFilled(dl, 
          snap_x, y0 + height, 
          snap_x - triangle_size, y0 + height - triangle_size, 
          snap_x + triangle_size, y0 + height - triangle_size, 
          snap_color)
      end
    end
    
    -- Draw playhead when playing or paused
    local current_pos = get_preview_position()
    local duration = waveform_data.duration or 1.0
    if (preview_proc ~= nil or state.preview_paused) and current_pos ~= nil and duration > 0
        and current_pos >= view0 and current_pos <= view1 then
      local playhead_x = math.max(x0, math.min(x0 + width, map_x(current_pos)))
      
      -- Draw playhead line (bright yellow, thicker for visibility)
      local playhead_color = 0xFFFF88FF  -- Yellow (RRGGBBAA format)
      local playhead_thickness = 2.0
      r.ImGui_DrawList_AddLine(dl, playhead_x, y0, playhead_x, y0 + height, playhead_color, playhead_thickness)
      
      -- Draw playhead indicators at top and bottom (filled circles for better visibility)
      local indicator_radius = 5.0
      r.ImGui_DrawList_AddCircleFilled(dl, playhead_x, y0, indicator_radius, playhead_color, 16)
    end
    if r.ImGui_DrawList_PopClipRect then
      r.ImGui_DrawList_PopClipRect(dl)
    end
  end
  
  local mx, my = r.ImGui_GetMousePos(ctx)
  local left_down = r.ImGui_IsMouseDown(ctx, 0)
  local ctl = draw_sample_wave_controls(
    dl, preview_sample_obj, x0, y0, width, height, file_dur, view0, view1,
    mx, my, left_down, clicked, "map", { show_name = false }
  )
  local tags_hit = render_waveform_overlay_tags(x0, y0, width, height, layout_x, layout_y)

  local alt = false
  if r.ImGui_IsKeyDown and r.ImGui_Key_LeftAlt then
    alt = r.ImGui_IsKeyDown(ctx, r.ImGui_Key_LeftAlt())
        or (r.ImGui_Key_RightAlt and r.ImGui_IsKeyDown(ctx, r.ImGui_Key_RightAlt()))
  end
  local mid_down = r.ImGui_IsMouseDown and r.ImGui_IsMouseDown(ctx, 2)
  if hovered and not tags_hit and not (ctl and ctl.over_vol) then
    local wheel = r.ImGui_GetMouseWheel and select(1, r.ImGui_GetMouseWheel(ctx)) or 0
    if wheel and wheel ~= 0 then
      wave_view_zoom(preview_sample_obj, file_dur, mx, x0, width, wheel)
    end
  end
  if hovered and not tags_hit and (mid_down or (alt and left_down)) and not (ctl and ctl.consumed) and not state.waveform_eff_drag then
    local dx = select(1, r.ImGui_GetMouseDelta(ctx)) or 0
    state.wave_view_pan = true
    wave_view_pan(preview_sample_obj, file_dur, dx, width)
    clicked = false
  elseif state.wave_view_pan and not mid_down and not (alt and left_down) then
    state.wave_view_pan = nil
  end
  if hovered and clicked and r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0)
      and not tags_hit and not (ctl and ctl.consumed) and not state.waveform_eff_drag then
    wave_view_reset(preview_sample_obj, file_dur)
    clicked = false
  end

  -- Handle click to play / click-again to stop (same as sequencer header preview)
  local blocked = tags_hit or state.waveform_eff_drag or (ctl and ctl.consumed)
      or state.wave_view_pan or state.pending_waveform_drop
  if preview_sample_obj and preview_sample_obj.path
      and not blocked
      and waveform_drag_should_start(hovered) then
    begin_waveform_sample_drag(preview_sample_obj)
    state.map_wave_press = nil
    state.map_wave_press_t = nil
  end
  if sample_is_waveform_drag_source(preview_sample_obj) then
    draw_waveform_drag_source_cue(dl, x0, y0, width, height)
  end
  map_waveform_handle_preview_click(
    preview_sample_obj, hovered, clicked, left_down,
    mx, x0, width, view0, view1, blocked
  )
end


-- --- Sequencer track helpers -------------------------------------------------
local function get_track_by_guid(track_guid)
  if not track_guid or track_guid == "" then
    return nil
  end
  local n = r.CountTracks(0)
  for i = 0, n - 1 do
    local tr = r.GetTrack(0, i)
    if r.GetTrackGUID(tr) == track_guid then
      return tr
    end
  end
  return nil
end

local function get_project_tracks_list()
  local tracks = {}
  local n = r.CountTracks(0)
  for i = 0, n - 1 do
    local tr = r.GetTrack(0, i)
    local _, name = r.GetTrackName(tr)
    tracks[#tracks + 1] = {
      track = tr,
      guid = r.GetTrackGUID(tr),
      name = name ~= "" and name or ("Track " .. (i + 1)),
    }
  end
  return tracks
end

local function get_reaper_track_display_name(track_guid)
  if not track_guid then
    return nil
  end
  local tr = get_track_by_guid(track_guid)
  if not tr then
    return "(missing track)"
  end
  local _, name = r.GetTrackName(tr)
  if name and name ~= "" then
    return name
  end
  return "(unnamed track)"
end

local function find_sample_by_path(path)
  if not path or path == "" then
    return nil
  end
  local hit = samples_by_path[path]
  if hit then
    return hit
  end
  local norm = normalize_path(path)
  if norm ~= path then
    hit = samples_by_path[norm]
    if hit then
      samples_by_path[path] = hit
      return hit
    end
  end
  local key = path_index_key(norm)
  if key ~= "" and key ~= norm then
    hit = samples_by_path[key]
    if hit then
      samples_by_path[path] = hit
      samples_by_path[norm] = hit
      return hit
    end
  end
  -- Fallback once if index is stale (then cache). Case-insensitive for
  -- external volumes whose enumeration casing does not match the cache.
  for _, s in ipairs(state.samples) do
    if s.path == path or s.path == norm then
      samples_by_path[path] = s
      return s
    end
    if s.path and key ~= "" and path_index_key(s.path) == key then
      samples_by_path[path] = s
      samples_by_path[norm] = s
      samples_by_path[key] = s
      return s
    end
  end
  return nil
end

function sample_drag_active()
  return state.pending_waveform_drop ~= nil
    or (state.is_left_dragging and state.last_dragged_sample_path ~= nil)
end

function get_active_dragged_sample()
  if state.pending_waveform_drop then
    return state.pending_waveform_drop
  end
  if state.last_dragged_sample_path then
    return find_sample_by_path(state.last_dragged_sample_path)
  end
  return nil
end

function begin_waveform_sample_drag(sample)
  if not sample or not sample.path or state.pending_waveform_drop then
    return false
  end
  state.pending_waveform_drop = sample
  state.waveform_drag_armed = nil
  state.is_left_dragging = false
  state.last_dragged_sample_path = nil
  if r.ImGui_SetMouseCursor then
    r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
  end
  return true
end

function waveform_drag_should_start(hovered)
  if state.map_ui_edit or state.map_ui_drag then
    return false
  end
  if state.pending_waveform_drop then
    return false
  end
  if hovered and r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 0) then
    state.waveform_drag_armed = true
  end
  if not (r.ImGui_IsMouseDown and r.ImGui_IsMouseDown(ctx, 0)) then
    state.waveform_drag_armed = nil
    return false
  end
  if not (hovered or state.waveform_drag_armed) then
    return false
  end
  if r.ImGui_IsMouseDragging then
    return r.ImGui_IsMouseDragging(ctx, 0, 6.0)
  end
  return false
end

local function seq_track_has_guid(guid)
  if not guid then
    return false
  end
  for _, slot in ipairs(state.seq_tracks) do
    if slot.reaper_track_guid == guid then
      return true
    end
  end
  return false
end

local function clamp_selected_seq_track()
  if state.selected_seq_track and state.selected_seq_track > #state.seq_tracks then
    state.selected_seq_track = #state.seq_tracks > 0 and #state.seq_tracks or nil
  end
  if state.selected_seq_track and state.selected_seq_track < 1 then
    state.selected_seq_track = nil
  end
  if state.seq_swap_track_idx and state.seq_swap_track_idx > #state.seq_tracks then
    state.seq_swap_track_idx = nil
  end
end

local function add_seq_track_from_reaper_track(tr)
  if not tr then
    return nil
  end
  local guid = r.GetTrackGUID(tr)
  if seq_track_has_guid(guid) then
    return nil
  end
  local _, name = r.GetTrackName(tr)
  local slot = {
    id = state.seq_track_next_id,
    name = name ~= "" and name or ("Track " .. (#state.seq_tracks + 1)),
    reaper_track_guid = guid,
    sample_path = nil,
    sample_name = nil,
  }
  seq_normalize_slot_mix(slot)
  state.seq_track_next_id = state.seq_track_next_id + 1
  table.insert(state.seq_tracks, slot)
  state.selected_seq_track = #state.seq_tracks
  return slot
end

local function add_empty_seq_track()
  local slot = {
    id = state.seq_track_next_id,
    name = "Track " .. (#state.seq_tracks + 1),
    reaper_track_guid = nil,
    sample_path = nil,
    sample_name = nil,
  }
  seq_normalize_slot_mix(slot)
  state.seq_track_next_id = state.seq_track_next_id + 1
  table.insert(state.seq_tracks, slot)
  state.selected_seq_track = #state.seq_tracks
  return slot
end

function seq_clear_track_document_data(track_id)
  if track_id == nil then
    return
  end
  local key = tostring(track_id)

  for _, pattern in pairs(state.seq_patterns or {}) do
    if type(pattern) == "table" then
      if type(pattern.notes) == "table" then
        pattern.notes[key] = nil
      end
      if type(pattern.track_settings) == "table" then
        pattern.track_settings[key] = nil
      end
    end
  end

  for _, region in ipairs(state.seq_regions or {}) do
    if type(region.track_samples) == "table" then
      region.track_samples[key] = nil
      if next(region.track_samples) == nil then
        region.track_samples = nil
      end
    end
  end

  if state.seq_expanded_tracks then
    state.seq_expanded_tracks[key] = nil
  end
  if state.seq_track_play_anims then
    state.seq_track_play_anims[key] = nil
  end
  if state.seq_candidate_slide then
    state.seq_candidate_slide[track_id] = nil
  end
  if state.seq_nav_anchors then
    state.seq_nav_anchors[track_id] = nil
  end
  if state.seq_note_anims then
    for anim_key, anim in pairs(state.seq_note_anims) do
      if anim and anim.track_id == track_id then
        state.seq_note_anims[anim_key] = nil
      end
    end
  end

  if state.seq_razors then
    local kept = {}
    for _, razor in ipairs(state.seq_razors) do
      if type(razor) == "table" and type(razor.track_ids) == "table" then
        local ids = {}
        for _, id in ipairs(razor.track_ids) do
          if id ~= track_id then
            ids[#ids + 1] = id
          end
        end
        razor.track_ids = ids
        if #ids > 0 then
          kept[#kept + 1] = razor
        end
      else
        kept[#kept + 1] = razor
      end
    end
    state.seq_razors = kept
  end

  if state.seq_random_sync_pending and state.seq_random_sync_pending.track_ids then
    state.seq_random_sync_pending.track_ids[track_id] = nil
  end
  if state.seq_layering_slot_id == track_id then
    state.seq_layering_slot_id = nil
  end
  if state.seq_midi_popup_slot_id == track_id then
    state.seq_midi_popup_slot_id = nil
  end
  if state.seq_midi_learn_slot_id == track_id then
    state.seq_midi_learn_slot_id = nil
  end
  if state.seq_env_popup_slot_id == track_id then
    state.seq_env_popup_slot_id = nil
  end
  if state.map_hover_track_id == track_id then
    state.map_hover_track_id = nil
  end
  if state.seq_track_menu_id == track_id then
    state.seq_track_menu_id = nil
    state.seq_track_menu_want_open = nil
  end
  if state.seq_grid_hover and state.seq_grid_hover.slot_id == track_id then
    state.seq_grid_hover = nil
  end
  if state.seq_lane_h_drag and state.seq_lane_h_drag.slot_id == track_id then
    state.seq_lane_h_drag = nil
  end
  if state.seq_track_reorder_drag and state.seq_track_reorder_drag.slot_id == track_id then
    state.seq_track_reorder_drag = nil
  end
end

-- Remove a sequencer slot from the document. Does not touch REAPER tracks or undo.
function seq_remove_seq_track_slot(idx)
  if not idx or idx < 1 or idx > #(state.seq_tracks or {}) then
    return nil
  end
  local removed_slot = state.seq_tracks[idx]
  local removed_id = removed_slot and removed_slot.id
  table.remove(state.seq_tracks, idx)
  if removed_id then
    seq_clear_track_document_data(removed_id)
  end
  if state.seq_swap_track_id and removed_id and state.seq_swap_track_id == removed_id then
    if seq_clear_swap_mode_if_track then
      seq_clear_swap_mode_if_track(removed_id)
    else
      state.seq_swap_track_idx = nil
      state.seq_swap_track_id = nil
    end
  elseif state.seq_swap_track_idx then
    if state.seq_swap_track_idx == idx then
      state.seq_swap_track_idx = nil
    elseif state.seq_swap_track_idx > idx then
      state.seq_swap_track_idx = state.seq_swap_track_idx - 1
    end
  end
  if state.selected_seq_track then
    if #state.seq_tracks == 0 then
      state.selected_seq_track = nil
    elseif state.selected_seq_track == idx then
      state.selected_seq_track = math.min(idx, #state.seq_tracks)
    elseif state.selected_seq_track > idx then
      state.selected_seq_track = state.selected_seq_track - 1
    end
  end
  clamp_selected_seq_track()
  return removed_slot
end

function seq_delete_reaper_track_for_slot(slot)
  if not slot or not slot.reaper_track_guid or slot.reaper_track_guid == "" then
    return false
  end
  local tr = get_track_by_guid(slot.reaper_track_guid)
  if not tr or not r.DeleteTrack then
    return false
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  r.DeleteTrack(tr)
  if r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  if r.TrackList_AdjustWindows then
    r.TrackList_AdjustWindows(false)
  end
  r.UpdateArrange()
  seq_mark_self_arrange_write()
  return true
end

-- User-facing delete: drop the sequencer slot, its notes, and the linked arrange track.
function seq_delete_seq_track_at(idx, opts)
  opts = opts or {}
  local slot = state.seq_tracks and state.seq_tracks[idx]
  if not slot then
    return false
  end
  local own = false
  if opts.undo ~= false then
    own = seq_undo_own_begin("Delete sequencer track")
  end
  local delete_reaper = opts.delete_reaper ~= false
  if delete_reaper then
    seq_delete_reaper_track_for_slot(slot)
  end
  seq_remove_seq_track_slot(idx)
  if opts.persist ~= false then
    save_config()
    if save_seq_project_state then
      save_seq_project_state()
    end
  end
  if own then
    end_seq_undo("Delete sequencer track")
  end
  return true
end

local function remove_selected_seq_track()
  if not state.selected_seq_track then
    return
  end
  seq_delete_seq_track_at(state.selected_seq_track)
end

SEQ_SAMPLE_CANDIDATES_MIN = 3
SEQ_SAMPLE_CANDIDATES_MAX = 12

function seq_candidate_entry_taken(entry)
  return type(entry) == "table" and type(entry.path) == "string" and entry.path ~= ""
end

function seq_compact_sample_candidates(slot)
  local src = slot and slot.sample_candidates
  if type(src) ~= "table" then
    return false
  end
  local old_idx = tonumber(slot.sample_candidate_idx)
  local dense = {}
  local mapped = nil
  local had_hole = false
  local seen_empty = false
  for i = 1, SEQ_SAMPLE_CANDIDATES_MAX do
    local entry = src[i]
    if seq_candidate_entry_taken(entry) then
      if seen_empty then
        had_hole = true
      end
      dense[#dense + 1] = entry
      if old_idx and i == old_idx then
        mapped = #dense
      end
    elseif #dense > 0 then
      seen_empty = true
    end
  end
  if not had_hole then
    return false
  end
  slot.sample_candidates = dense
  if mapped then
    slot.sample_candidate_idx = mapped
  else
    local idx = old_idx or 1
    if idx < 1 then
      idx = 1
    end
    slot.sample_candidate_idx = math.max(1, math.min(idx, math.max(1, #dense)))
  end
  return true
end

function seq_normalize_slot_candidates(slot)
  if not slot then
    return
  end
  if slot._cand_norm and type(slot.sample_candidates) == "table" then
    seq_compact_sample_candidates(slot)
    return
  end
  local src = slot.sample_candidates
  local list = {}
  local old_idx = tonumber(slot.sample_candidate_idx)
  local mapped = nil
  if type(src) == "table" then
    for i = 1, SEQ_SAMPLE_CANDIDATES_MAX do
      local entry = src[i]
      if type(entry) == "table" and type(entry.path) == "string" and entry.path ~= "" then
        list[#list + 1] = {
          path = entry.path,
          name = (type(entry.name) == "string" and entry.name ~= "" and entry.name) or basename(entry.path),
          x = tonumber(entry.x) or 0.5,
          y = tonumber(entry.y) or 0.5,
          dominant_freq = tonumber(entry.dominant_freq),
          brightness = tonumber(entry.brightness),
          sub_weight = tonumber(entry.sub_weight),
          effective_duration = tonumber(entry.effective_duration),
        }
        if old_idx and i == old_idx then
          mapped = #list
        end
      end
    end
  end
  slot.sample_candidates = list
  local idx = mapped
  if not idx then
    idx = old_idx
    if not idx or idx < 1 or idx > SEQ_SAMPLE_CANDIDATES_MAX then
      idx = 1
    end
    idx = math.max(1, math.min(idx, math.max(1, #list)))
  end
  slot.sample_candidate_idx = idx
  if not seq_candidate_entry_taken(list[1]) and type(slot.sample_path) == "string" and slot.sample_path ~= "" then
    local sample = find_sample_by_path(slot.sample_path) or {
      path = slot.sample_path,
      name = slot.sample_name,
    }
    list[1] = seq_candidate_entry_from_sample(sample)
  end
  slot._cand_norm = true
end

function seq_candidate_highest_taken(slot)
  local list = slot and slot.sample_candidates
  local high = 0
  if type(list) == "table" then
    for i = 1, SEQ_SAMPLE_CANDIDATES_MAX do
      if seq_candidate_entry_taken(list[i]) then
        high = i
      end
    end
  end
  return high
end

function seq_candidate_visible_count(slot)
  local visible = SEQ_SAMPLE_CANDIDATES_MIN
  local high = seq_candidate_highest_taken(slot)
  visible = math.max(visible, high)
  local list = slot and slot.sample_candidates
  local all_taken = high > 0
  if all_taken then
    for i = 1, visible do
      if not seq_candidate_entry_taken(list and list[i]) then
        all_taken = false
        break
      end
    end
  end
  if all_taken then
    visible = math.min(SEQ_SAMPLE_CANDIDATES_MAX, visible + 1)
  end
  return visible
end

function seq_candidate_entry_from_sample(sample)
  if not sample or not sample.path or sample.path == "" then
    return nil
  end
  local live = find_sample_by_path(sample.path) or sample
  local dur = nil
  if sample_map_duration then
    dur = sample_map_duration(live)
  end
  if type(dur) ~= "number" or dur <= 0 then
    dur = tonumber(live.effective_duration) or tonumber(live.duration)
  end
  return {
    path = live.path or sample.path,
    name = live.name or sample.name or basename(sample.path),
    x = tonumber(live.x) or 0.5,
    y = tonumber(live.y) or 0.5,
    dominant_freq = tonumber(live.dominant_freq),
    brightness = tonumber(live.brightness),
    sub_weight = tonumber(live.sub_weight),
    effective_duration = dur,
  }
end

function seq_candidate_sample_from_entry(entry)
  if not seq_candidate_entry_taken(entry) then
    return nil
  end
  return find_sample_by_path(entry.path) or {
    path = entry.path,
    name = entry.name,
    x = entry.x,
    y = entry.y,
    dominant_freq = entry.dominant_freq,
    brightness = entry.brightness,
    sub_weight = entry.sub_weight,
    effective_duration = entry.effective_duration,
    duration = entry.duration,
  }
end

function seq_drag_is_from_candidate()
  return state.seq_candidate_drag_source ~= nil
end

function seq_candidate_drag_from_slot(slot)
  local src = state.seq_candidate_drag_source
  return src ~= nil and slot ~= nil and src.slot_id == slot.id
end

function seq_candidate_is_drag_source(slot, idx)
  local src = state.seq_candidate_drag_source
  return src ~= nil and slot ~= nil
    and src.slot_id == slot.id
    and src.idx == idx
end

function seq_clear_candidate_drag_state()
  state.seq_candidate_press = nil
  state.seq_candidate_drag_source = nil
end

function seq_remember_sample_candidate(slot, sample)
  if not slot then
    return nil
  end
  seq_normalize_slot_candidates(slot)
  local idx = tonumber(slot.sample_candidate_idx)
  if not idx or idx < 1 or idx > SEQ_SAMPLE_CANDIDATES_MAX then
    return nil
  end
  local entry = seq_candidate_entry_from_sample(sample)
  if not entry then
    return nil
  end
  slot.sample_candidates[idx] = entry
  return idx
end

function seq_begin_candidate_slide(slot, deleted_idx, boxes)
  if not slot or not slot.id or type(boxes) ~= "table" then
    return
  end
  deleted_idx = tonumber(deleted_idx)
  if not deleted_idx then
    return
  end
  local fade = nil
  local db = boxes[deleted_idx]
  local fade_entry = slot.sample_candidates and slot.sample_candidates[deleted_idx]
  if db and seq_candidate_entry_taken(fade_entry) then
    fade = {
      x = db.x, y = db.y, w = db.w, h = db.h,
      entry = fade_entry,
    }
  end
  local moves = {}
  for old_i = 1, #boxes do
    local box = boxes[old_i]
    if box and old_i ~= deleted_idx then
      local new_i = old_i > deleted_idx and (old_i - 1) or old_i
      moves[new_i] = { from_x = box.x, from_y = box.y }
    end
  end
  state.seq_candidate_slide = state.seq_candidate_slide or {}
  state.seq_candidate_slide[slot.id] = {
    start = r.time_precise(),
    duration = 0.28,
    moves = moves,
    fade = fade,
  }
end

function seq_candidate_slide_anim(slot)
  local anims = state.seq_candidate_slide
  if not anims or not slot or not slot.id then
    return nil
  end
  local anim = anims[slot.id]
  if not anim then
    return nil
  end
  local dur = anim.duration or 0.28
  if dur <= 0 then
    anims[slot.id] = nil
    return nil
  end
  local t = (r.time_precise() - (anim.start or r.time_precise())) / dur
  if t >= 1 then
    anims[slot.id] = nil
    return nil
  end
  t = math.max(0.0, t)
  local ease = 1.0 - (1.0 - t) ^ 3
  return anim, t, ease
end

function seq_remove_sample_candidate(slot, idx)
  if not slot then
    return false
  end
  seq_normalize_slot_candidates(slot)
  idx = tonumber(idx)
  if not idx or idx < 1 or idx > SEQ_SAMPLE_CANDIDATES_MAX then
    return false
  end
  if not seq_candidate_entry_taken(slot.sample_candidates[idx]) then
    return false
  end
  table.remove(slot.sample_candidates, idx)
  local sel = tonumber(slot.sample_candidate_idx) or 1
  if sel > idx then
    slot.sample_candidate_idx = sel - 1
  elseif sel == idx then
    if not seq_candidate_entry_taken(slot.sample_candidates[idx]) then
      slot.sample_candidate_idx = math.max(1, idx - 1)
    end
  end
  return true
end

local function assign_sample_to_seq_track(slot, sample, persist)
  if not slot or not sample or not sample.path then
    return false
  end
  local old_path = slot.sample_path
  local path_changed = old_path ~= sample.path
  slot.sample_path = sample.path
  slot.sample_name = sample.name or basename(sample.path)
  if slot.sample_candidate_idx then
    seq_remember_sample_candidate(slot, sample)
  end
  if path_changed and seq_layering_follow_track_sample then
    seq_layering_follow_track_sample(slot, old_path, sample)
  end
  local should_persist = persist == nil or persist
  if path_changed and update_seq_track_sample_assignments then
    local force_rebuild = seq_layering_geometry_active
      and seq_layering_geometry_active(slot)
    if not force_rebuild and slot.layers and slot.layers.output then
      force_rebuild = true
    end
    -- update_seq_track_sample_assignments persists when asked, so skip a second save_config.
    update_seq_track_sample_assignments(slot, sample.path, slot.sample_name, should_persist, {
      force_rebuild = force_rebuild,
    })
    if seq_player_sync_slot then
      seq_player_sync_slot(slot)
    end
    return true
  end
  if should_persist then
    save_config()
  end
  if seq_player_sync_slot then
    seq_player_sync_slot(slot)
  end
  return true
end

local function seq_slot_in_swap_mode(slot)
  if not state.seq_swap_track_id or not slot then
    return false
  end
  return slot.id == state.seq_swap_track_id
end

local function find_seq_track_by_id(track_id)
  if not track_id then
    return nil, nil
  end
  for idx, slot in ipairs(state.seq_tracks) do
    if slot.id == track_id then
      return slot, idx
    end
  end
  return nil, nil
end

function seq_region_sample_edit_region()
  local id = state.seq_random_edit_region_id
  if not id then
    return nil
  end
  return get_seq_region_by_id(id)
end

function seq_sample_assign_region()
  if state.seq_swap_track_id and state.seq_swap_region_id then
    return get_seq_region_by_id(state.seq_swap_region_id)
  end
  return seq_region_sample_edit_region()
end

function seq_region_own_track_sample(region, track_id)
  if not region or track_id == nil then
    return nil
  end
  local map = region.track_samples
  if type(map) ~= "table" then
    return nil
  end
  local rec = map[tostring(track_id)]
  if type(rec) ~= "table" or type(rec.path) ~= "string" or rec.path == "" then
    return nil
  end
  return rec
end

function seq_linked_regions(region)
  local out = {}
  if not region then
    return out
  end
  for _, reg in ipairs(state.seq_regions or {}) do
    if reg.id == region.id
        or (seq_region_in_link_group and seq_region_in_link_group(reg, region)) then
      out[#out + 1] = reg
    end
  end
  if #out == 0 then
    out[1] = region
  end
  return out
end

function seq_get_region_track_sample(region, track_id)
  local rec = seq_region_own_track_sample(region, track_id)
  if rec then
    return rec
  end
  if not region then
    return nil
  end
  for _, reg in ipairs(state.seq_regions or {}) do
    if reg.id ~= region.id
        and seq_region_in_link_group
        and seq_region_in_link_group(reg, region) then
      rec = seq_region_own_track_sample(reg, track_id)
      if rec then
        return rec
      end
    end
  end
  return nil
end

function seq_clone_region_track_samples(src)
  if not src or type(src.track_samples) ~= "table" then
    return nil
  end
  return clone_table_deep(src.track_samples)
end

function seq_effective_slot_sample_path(slot, region)
  local rec = seq_get_region_track_sample(region, slot and slot.id)
  if rec then
    return rec.path, rec.name
  end
  if slot then
    return slot.sample_path, slot.sample_name
  end
  return nil, nil
end

function seq_effective_slot_sample(slot, region)
  local path, name = seq_effective_slot_sample_path(slot, region)
  if not path or path == "" then
    return nil
  end
  return find_sample_by_path(path) or { path = path, name = name or basename(path) }
end

function seq_slot_has_region_sample(slot, region)
  return seq_get_region_track_sample(region, slot and slot.id) ~= nil
end

function seq_slot_region_sample_cue(slot)
  local focus = seq_region_sample_edit_region() or get_seq_region_by_id(state.selected_seq_region_id)
  if seq_get_region_track_sample(focus, slot and slot.id) then
    return focus, true
  end
  return focus, false
end

function seq_set_region_own_track_sample(region, slot, rec)
  if not region or not slot then
    return
  end
  local key = tostring(slot.id)
  if not rec or not rec.path or rec.path == "" then
    if type(region.track_samples) == "table" then
      region.track_samples[key] = nil
      if next(region.track_samples) == nil then
        region.track_samples = nil
      end
    end
    return
  end
  region.track_samples = region.track_samples or {}
  region.track_samples[key] = {
    path = rec.path,
    name = rec.name or basename(rec.path),
  }
end

function seq_assign_region_track_sample(region, slot, sample, persist)
  if not region or not slot then
    return false
  end
  local rec = nil
  if sample and sample.path and sample.path ~= ""
      and not (slot.sample_path and seq_paths_same and seq_paths_same(sample.path, slot.sample_path)) then
    rec = {
      path = sample.path,
      name = sample.name or basename(sample.path),
    }
  end
  local targets = seq_linked_regions(region)
  for i = 1, #targets do
    seq_set_region_own_track_sample(targets[i], slot, rec)
  end
  if clear_seq_vary_rank_cache then
    clear_seq_vary_rank_cache()
  end
  if sync_seq_region_track then
    seq_pcm_take_src_begin()
    if r.PreventUIRefresh then
      r.PreventUIRefresh(1)
    end
    for i = 1, #targets do
      sync_seq_region_track(targets[i], slot, { skip_arrange = true })
    end
    if r.PreventUIRefresh then
      r.PreventUIRefresh(-1)
    end
    seq_pcm_take_src_end()
    r.UpdateArrange()
  end
  if persist ~= false then
    save_config()
  end
  return true
end

function seq_assign_sample_for_context(slot, sample, persist)
  local region = seq_sample_assign_region()
  if region then
    return seq_assign_region_track_sample(region, slot, sample, persist)
  end
  return assign_sample_to_seq_track(slot, sample, persist)
end

function seq_swap_restore_slot(slot)
  if not slot then
    return
  end
  local region = state.seq_swap_region_id and get_seq_region_by_id(state.seq_swap_region_id) or nil
  if region then
    if state.seq_swap_backup_was_override and state.seq_swap_backup_path then
      seq_assign_region_track_sample(region, slot, {
        path = state.seq_swap_backup_path,
        name = state.seq_swap_backup_name or basename(state.seq_swap_backup_path),
      }, true)
    else
      seq_assign_region_track_sample(region, slot, nil, true)
    end
    return
  end
  if state.seq_swap_backup_path then
    assign_sample_to_seq_track(slot, {
      path = state.seq_swap_backup_path,
      name = state.seq_swap_backup_name or basename(state.seq_swap_backup_path),
    }, true)
  else
    slot.sample_path = nil
    slot.sample_name = nil
    save_config()
  end
end

local function clone_active_tags(tags)
  local copy = {}
  if type(tags) ~= "table" then
    return copy
  end
  for tag, active in pairs(tags) do
    if active then
      copy[tag] = true
    end
  end
  return copy
end

local function clone_string_list(list)
  local copy = {}
  if type(list) ~= "table" then
    return copy
  end
  for _, value in ipairs(list) do
    if type(value) == "string" and value ~= "" then
      copy[#copy + 1] = value
    end
  end
  return copy
end

MAP_TAB_MAX = 12

function sample_map_is_open()
  return state.sample_map_floating or state.active_view == "sample_map"
end

function sequencer_is_open()
  return state.sequencer_floating or state.active_view == "sequencer"
end

function map_view_center_from_pan(w, h, zoom, pan_x, pan_y)
  zoom = tonumber(zoom) or 1.0
  if zoom < 1e-6 then
    zoom = 1.0
  end
  local cx, cy = 0.5, 0.5
  if type(w) == "number" and w > 1 then
    cx = 0.5 - (tonumber(pan_x) or 0.0) / (w * zoom)
  end
  if type(h) == "number" and h > 1 then
    cy = 0.5 - (tonumber(pan_y) or 0.0) / (h * zoom)
  end
  return cx, cy
end

function map_pan_from_view_center(w, h, zoom, cx, cy)
  zoom = tonumber(zoom) or 1.0
  local pan_x, pan_y = 0.0, 0.0
  if type(w) == "number" and w > 1 and type(cx) == "number" then
    pan_x = (0.5 - cx) * w * zoom
  end
  if type(h) == "number" and h > 1 and type(cy) == "number" then
    pan_y = (0.5 - cy) * h * zoom
  end
  return pan_x, pan_y
end

function capture_map_tab_view()
  local parents = {}
  if type(state.selected_tag_parents) == "table" then
    for key, on in pairs(state.selected_tag_parents) do
      if on then
        parents[key] = true
      end
    end
  end
  local cx, cy = map_view_center_from_pan(
    state.map_view_w, state.map_view_h, state.zoom, state.pan_x, state.pan_y
  )
  return {
    filter = state.filter or "",
    active_tags = clone_active_tags(state.active_tags),
    folder_filter_paths = clone_string_list(state.folder_filter_paths),
    zoom = state.zoom or 1.0,
    pan_x = state.pan_x or 0.0,
    pan_y = state.pan_y or 0.0,
    view_cx = cx,
    view_cy = cy,
    map_y_axis = map_y_axis_id(),
    selected_tag_parents = parents,
  }
end

function apply_map_tab_view(tab)
  if type(tab) ~= "table" then
    return
  end
  state.filter = type(tab.filter) == "string" and tab.filter or ""
  state.active_tags = clone_active_tags(tab.active_tags)
  state.folder_filter_paths = clone_string_list(tab.folder_filter_paths)
  state.zoom = math.max(MAP_ZOOM_MIN, math.min(MAP_ZOOM_MAX, tonumber(tab.zoom) or 1.0))
  map_zoom_snap_target()
  local view_cx = tonumber(tab.view_cx)
  local view_cy = tonumber(tab.view_cy)
  if view_cx and view_cy then
    state.map_restore_view_cx = view_cx
    state.map_restore_view_cy = view_cy
    if (state.map_view_w or 0) > 1 and (state.map_view_h or 0) > 1 then
      state.pan_x, state.pan_y = map_pan_from_view_center(
        state.map_view_w, state.map_view_h, state.zoom, view_cx, view_cy
      )
    else
      state.pan_x = tonumber(tab.pan_x) or 0.0
      state.pan_y = tonumber(tab.pan_y) or 0.0
    end
  else
    state.map_restore_view_cx = nil
    state.map_restore_view_cy = nil
    state.pan_x = tonumber(tab.pan_x) or 0.0
    state.pan_y = tonumber(tab.pan_y) or 0.0
  end
  state.selected_tag_parents = clone_active_tags(tab.selected_tag_parents)
  local axis = tab.map_y_axis
  if axis == "brightness" or axis == "dominant_freq" or axis == "weight" then
    if state.map_y_axis ~= axis then
      state.map_y_axis = axis
      if #state.samples > 0 then
        layout_samples()
      end
    end
  end
end

function map_tab_label(tab)
  if type(tab) ~= "table" then
    return "All"
  end
  if type(tab.title) == "string" and tab.title ~= "" then
    return tab.title
  end
  local parts = {}
  if type(tab.filter) == "string" and tab.filter ~= "" then
    parts[#parts + 1] = tab.filter
  end
  local tags = {}
  for tag, on in pairs(tab.active_tags or {}) do
    if on and type(tag) == "string" then
      tags[#tags + 1] = tag
    end
  end
  table.sort(tags, function(a, b)
    return string.lower(a) < string.lower(b)
  end)
  for _, tag in ipairs(tags) do
    parts[#parts + 1] = tag
  end
  for _, path in ipairs(tab.folder_filter_paths or {}) do
    if folder_filter_chip_label then
      parts[#parts + 1] = folder_filter_chip_label(path)
    else
      parts[#parts + 1] = path:match("([^/]+)$") or path
    end
  end
  if #parts == 0 then
    return "All"
  end
  local label = table.concat(parts, " · ")
  if #label > 22 then
    return label:sub(1, 20) .. "…"
  end
  return label
end

function find_map_tab(id)
  id = tonumber(id)
  if not id then
    return nil, nil
  end
  for i, tab in ipairs(state.map_tabs or {}) do
    if tab.id == id then
      return tab, i
    end
  end
  return nil, nil
end

function snapshot_active_map_tab()
  local tab = find_map_tab(state.map_tab_active_id)
  if not tab then
    return
  end
  local view = capture_map_tab_view()
  if state.seq_swap_saved_active_tags ~= nil then
    view.active_tags = clone_active_tags(state.seq_swap_saved_active_tags)
  end
  tab.filter = view.filter
  tab.active_tags = view.active_tags
  tab.folder_filter_paths = view.folder_filter_paths
  tab.zoom = view.zoom
  tab.pan_x = view.pan_x
  tab.pan_y = view.pan_y
  tab.view_cx = view.view_cx
  tab.view_cy = view.view_cy
  tab.map_y_axis = view.map_y_axis
  tab.selected_tag_parents = view.selected_tag_parents
end

function ensure_map_tabs()
  state.map_tabs = state.map_tabs or {}
  if #state.map_tabs == 0 then
    local tab = capture_map_tab_view()
    tab.id = 1
    state.map_tabs[1] = tab
    state.map_tab_active_id = 1
    state.map_tab_next_id = 2
    return
  end
  if not find_map_tab(state.map_tab_active_id) then
    state.map_tab_active_id = state.map_tabs[1].id
  end
  local max_id = 0
  for _, tab in ipairs(state.map_tabs) do
    if type(tab.id) == "number" and tab.id > max_id then
      max_id = tab.id
    end
  end
  state.map_tab_next_id = math.max(state.map_tab_next_id or 1, max_id + 1)
end

function switch_map_tab(id)
  if id == state.map_tab_active_id then
    return
  end
  local tab = find_map_tab(id)
  if not tab then
    return
  end
  snapshot_active_map_tab()
  state.map_tab_active_id = id
  apply_map_tab_view(tab)
  save_config()
end

function add_map_tab()
  ensure_map_tabs()
  if #(state.map_tabs or {}) >= MAP_TAB_MAX then
    return
  end
  snapshot_active_map_tab()
  local tab = {
    id = state.map_tab_next_id or 1,
    filter = "",
    active_tags = {},
    folder_filter_paths = {},
    zoom = 1.0,
    pan_x = 0.0,
    pan_y = 0.0,
    view_cx = 0.5,
    view_cy = 0.5,
    map_y_axis = map_y_axis_id(),
    selected_tag_parents = {},
  }
  state.map_tab_next_id = tab.id + 1
  state.map_tabs[#state.map_tabs + 1] = tab
  state.map_tab_active_id = tab.id
  apply_map_tab_view(tab)
  save_config()
end

function close_map_tab(id)
  ensure_map_tabs()
  if #(state.map_tabs or {}) <= 1 then
    return
  end
  local tab, idx = find_map_tab(id)
  if not tab then
    return
  end
  if id == state.map_tab_active_id then
    snapshot_active_map_tab()
  end
  table.remove(state.map_tabs, idx)
  if id == state.map_tab_active_id then
    local next_tab = state.map_tabs[math.min(idx, #state.map_tabs)]
    state.map_tab_active_id = next_tab.id
    apply_map_tab_view(next_tab)
  end
  save_config()
end

function map_tab_display_label(tab)
  if not tab then
    return "All"
  end
  if tab.id == state.map_tab_active_id then
    local live = capture_map_tab_view()
    live.title = tab.title
    if state.seq_swap_saved_active_tags ~= nil then
      live.active_tags = clone_active_tags(state.seq_swap_saved_active_tags)
    end
    return map_tab_label(live)
  end
  return map_tab_label(tab)
end

function pop_out_active_view()
  if state.active_view == "sample_map" then
    if state.sample_map_floating then
      return
    end
    snapshot_active_map_tab()
    state.sample_map_floating = true
    if not state.sequencer_floating then
      state.active_view = "sequencer"
    end
  elseif state.active_view == "sequencer" then
    if state.sequencer_floating then
      return
    end
    state.sequencer_floating = true
    if not state.sample_map_floating then
      state.active_view = "sample_map"
    end
  else
    return
  end
  save_config()
end

function dock_floating_view(view)
  if view == "sample_map" then
    if not state.sample_map_floating then
      return
    end
    state.sample_map_floating = false
    state.active_view = "sample_map"
  elseif view == "sequencer" then
    if not state.sequencer_floating then
      return
    end
    state.sequencer_floating = false
    state.active_view = "sequencer"
  else
    return
  end
  save_config()
end

local function find_library_tag(tag)
  local needle = seq_trim_text(tag)
  if needle == "" or not state.tag_list then
    return nil
  end
  needle = needle:lower()
  for _, entry in ipairs(state.tag_list) do
    local lib_tag = tostring(entry.tag or "")
    if lib_tag:lower() == needle then
      return lib_tag
    end
  end
  return nil
end

local function resolve_seq_swap_filter_tag(slot)
  if not slot then
    return nil
  end
  local tag = slot.sample_tag and seq_trim_text(slot.sample_tag) or ""
  if tag ~= "" then
    return tag
  end
  local role = infer_seq_track_role(slot)
  if role and role ~= "other" and SEQ_ROLE_TAG_CANDIDATES[role] then
    return SEQ_ROLE_TAG_CANDIDATES[role][1]
  end
  return nil
end

local function restore_seq_swap_map_filter()
  if state.seq_swap_saved_active_tags ~= nil then
    state.active_tags = clone_active_tags(state.seq_swap_saved_active_tags)
    state.seq_swap_saved_active_tags = nil
  end
end

local function apply_seq_swap_map_filter(slot)
  local tag = find_library_tag(resolve_seq_swap_filter_tag(slot))
  if not tag then
    restore_seq_swap_map_filter()
    return
  end
  if state.seq_swap_saved_active_tags == nil then
    state.seq_swap_saved_active_tags = clone_active_tags(state.active_tags)
  end
  state.active_tags = { [tag] = true }
end

local function clear_seq_swap_mode_state()
  restore_seq_swap_map_filter()
  local return_view = state.seq_swap_return_view
  state.seq_swap_track_idx = nil
  state.seq_swap_track_id = nil
  state.seq_swap_backup_path = nil
  state.seq_swap_backup_name = nil
  state.seq_swap_region_id = nil
  state.seq_swap_backup_was_override = false
  state.seq_swap_return_view = nil
  if return_view == "sequencer" and not sequencer_is_open() then
    state.active_view = "sequencer"
    save_config()
  end
end

function seq_clear_swap_mode_if_track(track_id)
  if state.seq_swap_track_id and track_id and state.seq_swap_track_id == track_id then
    clear_seq_swap_mode_state()
  end
end

local function begin_seq_swap_mode(idx)
  local slot = state.seq_tracks[idx]
  if not slot then
    return
  end
  if state.seq_swap_track_id == slot.id then
    state.seq_swap_track_idx = idx
    return
  end
  if state.seq_swap_track_id and state.seq_swap_track_id ~= slot.id then
    local prev_slot = find_seq_track_by_id(state.seq_swap_track_id)
    if prev_slot then
      seq_swap_restore_slot(prev_slot)
    end
    state.seq_swap_track_idx = nil
    state.seq_swap_track_id = nil
    state.seq_swap_backup_path = nil
    state.seq_swap_backup_name = nil
    state.seq_swap_region_id = nil
    state.seq_swap_backup_was_override = false
    if seq_undo_is_open() then
      end_seq_undo("Swap sequencer sample")
    end
  end
  begin_seq_undo("Swap sequencer sample")
  state.seq_swap_track_idx = idx
  state.seq_swap_track_id = slot.id
  state.selected_seq_track = idx
  local region = seq_region_sample_edit_region()
  local rec = region and seq_get_region_track_sample(region, slot.id)
  state.seq_swap_region_id = region and region.id or nil
  state.seq_swap_backup_was_override = rec ~= nil
  if rec then
    state.seq_swap_backup_path = rec.path
    state.seq_swap_backup_name = rec.name
  else
    state.seq_swap_backup_path = slot.sample_path
    state.seq_swap_backup_name = slot.sample_name
  end
  if not state.seq_swap_return_view then
    state.seq_swap_return_view = state.active_view
  end
  apply_seq_swap_map_filter(slot)
  if not state.sample_map_floating then
    state.active_view = "sample_map"
  end
  save_config()
end

local function end_seq_swap_mode(confirmed)
  local slot, idx = find_seq_track_by_id(state.seq_swap_track_id)
  if not slot then
    clear_seq_swap_mode_state()
    return
  end
  state.seq_swap_track_idx = idx
  if confirmed then
    -- Arrange items were already retargeted while browsing candidates.
    save_config()
  else
    seq_swap_restore_slot(slot)
    local region = state.seq_swap_region_id and get_seq_region_by_id(state.seq_swap_region_id) or nil
    local restored = seq_effective_slot_sample(slot, region)
    if restored then
      preview_sample(restored)
    end
  end
  if seq_undo_is_open() then
    end_seq_undo("Swap sequencer sample")
  end
  clear_seq_swap_mode_state()
end

local function get_active_swap_slot()
  local slot, idx = find_seq_track_by_id(state.seq_swap_track_id)
  if not slot then
    return nil, nil
  end
  state.seq_swap_track_idx = idx
  return slot, idx
end

local function complete_pending_sample_drop()
  local sample = get_active_dragged_sample()
  local mouse_down = r.ImGui_IsMouseDown(ctx, 0)

  if mouse_down then
    if state.pending_waveform_drop then
      -- Escape during the drag cancels everything (no insert, no undo point).
      if r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
          and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false) then
        remove_provisional_drop()
        clear_drag_tooltip()
        state.pending_waveform_drop = nil
        state.waveform_drag_armed = nil
        state.last_mouse_time_pos = nil
        state.last_mouse_track = nil
        state.seq_drop_target_idx = nil
        state.seq_candidate_drop = nil
        state.seq_drum_drop = nil
        state.seq_timeline_drop_track_idx = nil
        state.seq_timeline_drop_time = nil
        state.is_left_dragging = false
        state.last_dragged_sample_path = nil
        state.map_press_x = nil
        state.map_press_y = nil
        state.map_press_pending = false
        state.map_audition_rearm = false
        if seq_clear_candidate_drag_state then
          seq_clear_candidate_drag_state()
        end
        log("Drag cancelled via Escape")
        return
      end
      update_provisional_drop(sample)
    end
    return
  end

  if state.seq_candidate_press then
    local press = state.seq_candidate_press
    state.seq_candidate_press = nil
    if not state.pending_waveform_drop then
      local pslot = seq_find_slot_by_id and seq_find_slot_by_id(press.slot_id)
      if pslot and seq_apply_sample_candidate then
        seq_apply_sample_candidate(pslot, press.idx)
      end
    end
  end

  if not sample and not state.pending_waveform_drop and not state.is_left_dragging then
    return
  end

  if sample then
    log("Mouse released globally, completing drag operation")

    if seq_layering_resolve_drop_vert then
      seq_layering_resolve_drop_vert()
    end
    if state.seq_layering_drop_vert and state.seq_layering_slot_id then
      local layer_slot = find_seq_track_by_id(state.seq_layering_slot_id)
      if layer_slot then
        local vert_sample = sample
        if sample.is_layering_mix then
          vert_sample = find_sample_by_path(sample.path) or sample
        end
        seq_layering_set_vert(layer_slot, state.seq_layering_drop_vert.side, state.seq_layering_drop_vert.idx, vert_sample)
        preview_sample(vert_sample)
        save_config()
        if save_seq_project_state then save_seq_project_state() end
        seq_layering_sync_arrange(layer_slot)
      end
      state.seq_layering_drop_vert = nil
      state.pending_waveform_drop = nil
      state.waveform_drag_armed = nil
      state.seq_drop_target_idx = nil
      state.seq_candidate_drop = nil
      state.seq_drum_drop = nil
      state.seq_timeline_drop_track_idx = nil
      state.seq_timeline_drop_time = nil
      state.is_left_dragging = false
      state.last_dragged_sample_path = nil
      state.map_press_x = nil
      state.map_press_y = nil
      state.map_press_pending = false
      state.map_audition_rearm = false
      if seq_clear_candidate_drag_state then
        seq_clear_candidate_drag_state()
      end
      remove_provisional_drop()
      clear_drag_tooltip()
      return
    end

    if seq_layering_pointer_over_window and seq_layering_pointer_over_window() then
      state.seq_layering_drop_vert = nil
      state.pending_waveform_drop = nil
      state.waveform_drag_armed = nil
      state.seq_drop_target_idx = nil
      state.seq_candidate_drop = nil
      state.seq_drum_drop = nil
      state.seq_timeline_drop_track_idx = nil
      state.seq_timeline_drop_time = nil
      state.is_left_dragging = false
      state.last_dragged_sample_path = nil
      state.map_press_x = nil
      state.map_press_y = nil
      state.map_press_pending = false
      state.map_audition_rearm = false
      if seq_clear_candidate_drag_state then
        seq_clear_candidate_drag_state()
      end
      remove_provisional_drop()
      clear_drag_tooltip()
      return
    end

    if state.seq_drum_drop then
      remove_provisional_drop()
      local drop = state.seq_drum_drop
      local slot = seq_find_slot_by_id and seq_find_slot_by_id(drop.slot_id)
      if not slot and find_seq_track_by_id then
        slot = select(1, find_seq_track_by_id(drop.slot_id))
      end
      local region = seq_region_sample_edit_region and seq_region_sample_edit_region()
      if slot and sample.path and region and not sample.is_layering_mix
          and not seq_candidate_drag_from_slot(slot) then
        local own = seq_undo_own_begin("Set region sample")
        seq_assign_region_track_sample(region, slot, sample, true)
        for ti, s in ipairs(state.seq_tracks or {}) do
          if s.id == slot.id then
            state.selected_seq_track = ti
            break
          end
        end
        preview_sample(sample)
        preview_seq_track_sample(slot)
        log("Set '" .. (sample.name or sample.path) .. "' as region sample on " .. (slot.name or "track"))
        if own then
          end_seq_undo("Set region sample")
        end
      end
    elseif state.seq_candidate_drop then
      remove_provisional_drop()
      local drop = state.seq_candidate_drop
      local src = state.seq_candidate_drag_source
      local slot = seq_find_slot_by_id and seq_find_slot_by_id(drop.slot_id)
      if not slot then
        slot = seq_find_track_slot_by_id and seq_find_track_slot_by_id(drop.slot_id)
      end
      if src and src.slot_id == drop.slot_id and src.idx == drop.idx then
        log("Candidate drag released on source")
      elseif slot and sample.path and seq_drop_sample_on_candidate then
        local in_swap = state.seq_swap_track_id and slot.id == state.seq_swap_track_id
        local own = (not in_swap) and seq_undo_own_begin("Assign sample candidate")
        seq_drop_sample_on_candidate(slot, drop.idx, sample, not in_swap)
        if own then
          end_seq_undo("Assign sample candidate")
        end
        for ti, s in ipairs(state.seq_tracks or {}) do
          if s.id == slot.id then
            state.selected_seq_track = ti
            break
          end
        end
        if sample.is_layering_mix and seq_layering_preview_layered then
          seq_layering_preview_layered(slot, 0)
        else
          preview_sample(sample)
        end
        log("Dropped '" .. (sample.name or sample.path) .. "' onto candidate " .. tostring(drop.idx) .. " of " .. (slot.name or "track"))
      end
    elseif state.seq_drop_target_idx and not seq_drag_is_from_candidate() then
      remove_provisional_drop()
      local slot = state.seq_tracks[state.seq_drop_target_idx]
      if slot and sample.path then
        local in_swap = state.seq_swap_track_id and slot.id == state.seq_swap_track_id
        local own = (not in_swap) and seq_undo_own_begin("Assign sequencer sample")
        if apply_dragged_sample_to_seq_track then
          apply_dragged_sample_to_seq_track(slot, sample, not in_swap)
        else
          seq_assign_sample_for_context(slot, sample, not in_swap)
        end
        if own then
          end_seq_undo("Assign sequencer sample")
        end
        state.selected_seq_track = state.seq_drop_target_idx
        if sample.is_layering_mix and seq_layering_preview_layered then
          seq_layering_preview_layered(slot, 0)
        else
          preview_sample(sample)
        end
        log("Swapped '" .. (sample.name or sample.path) .. "' onto " .. slot.name)
      end
    elseif state.pending_waveform_drop then
      local sample_label = sample.name or basename(sample.path or "") or "sample"
      if state.seq_timeline_drop_track_idx and state.seq_timeline_drop_time then
        remove_provisional_drop()
        local slot = state.seq_tracks[state.seq_timeline_drop_track_idx]
        local target_track = nil
        if slot and slot.reaper_track_guid then
          local n = r.CountTracks(0)
          for i = 0, n - 1 do
            local tr = r.GetTrack(0, i)
            if r.GetTrackGUID(tr) == slot.reaper_track_guid then
              target_track = tr
              break
            end
          end
        end
        arrange_undo_begin()
        local success = insert_sample_at_position(sample, state.seq_timeline_drop_time, target_track)
        arrange_undo_end("Insert sample: " .. sample_label)
        if success then
          state.selected_seq_track = state.seq_timeline_drop_track_idx
          log("Inserted '" .. sample_label .. "' via sequencer timeline")
        else
          log("Failed sequencer timeline insertion")
        end
      else
        -- Arrange drop: commit the provisional preview position as one undo point.
        local commit_time, commit_track
        local p = state.provisional_drop
        if p and p.item and r.ValidatePtr(p.item, "MediaItem*") then
          commit_time = p.time or state.last_mouse_time_pos
          if p.track and r.ValidatePtr(p.track, "MediaTrack*") then
            commit_track = p.track
          end
        end
        if not commit_time then
          local dt, dtr = get_drop_position()
          if dt then
            commit_time = maybe_snap_drop_time(dt)
            commit_track = commit_track or dtr
          end
        end
        if not commit_time and state.last_mouse_time_pos then
          commit_time = state.last_mouse_time_pos
          commit_track = commit_track or state.last_mouse_track
        end

        -- Clear the preview before committing so the undo block captures exactly
        -- one media item creation (project returns to clean state first).
        remove_provisional_drop()

        if commit_time then
          arrange_undo_begin()
          local success = insert_sample_at_position(sample, commit_time, commit_track)
          arrange_undo_end("Insert sample: " .. sample_label)
          if success then
            log(string.format("Committed arrange insert at %.3f", commit_time))
          else
            log("Failed to commit arrange insert")
          end
        else
          log("Drag released away from the arrange; insert cancelled")
        end
      end
    end
  end

  remove_provisional_drop()
  clear_drag_tooltip()
  state.pending_waveform_drop = nil
  state.waveform_drag_armed = nil
  state.last_mouse_time_pos = nil
  state.last_mouse_track = nil
  state.seq_drop_target_idx = nil
  state.seq_candidate_drop = nil
  state.seq_drum_drop = nil
  state.seq_timeline_drop_track_idx = nil
  state.seq_timeline_drop_time = nil
  state.is_left_dragging = false
  state.last_dragged_sample_path = nil
  state.map_press_x = nil
  state.map_press_y = nil
  state.map_press_pending = false
  state.map_audition_rearm = false
  if seq_clear_candidate_drag_state then
    seq_clear_candidate_drag_state()
  end
end

function clear_seq_track_sample(slot)
  if not slot then
    return
  end
  slot.sample_path = nil
  slot.sample_name = nil
  save_config()
end

function add_seq_tracks_from_selection()
  local own = seq_undo_own_begin("Add sequencer track")
  local count = r.CountSelectedTracks(0)
  if count == 0 then
    add_empty_seq_track()
    save_config()
    if own then
      end_seq_undo("Add sequencer track")
    end
    return
  end
  local added = 0
  for i = 0, count - 1 do
    local tr = r.GetSelectedTrack(0, i)
    if add_seq_track_from_reaper_track(tr) then
      added = added + 1
    end
  end
  if added == 0 then
    log("Selected project tracks are already in the sequencer track list")
  else
    save_config()
  end
  if own then
    end_seq_undo("Add sequencer track")
  end
end

function seq_trim_text(value)
  local text = tostring(value or "")
  text = text:gsub("^%s+", "")
  text = text:gsub("%s+$", "")
  return text
end

function find_sample_for_tag(tag_name)
  local needle = seq_trim_text(tag_name):lower()
  if needle == "" then
    return nil
  end
  for _, sample in ipairs(state.samples) do
    if sample_has_tag(sample, needle) and not sample_scan_folder_unavailable(sample) then
      return sample
    end
  end
  return nil
end

function sample_has_tag(sample, tag_name)
  if not sample or not sample.tags or type(sample.tags) ~= "table" then
    return false
  end
  local needle = seq_trim_text(tag_name):lower()
  if needle == "" then
    return false
  end
  for _, sample_tag in ipairs(sample.tags) do
    if tostring(sample_tag):lower() == needle then
      return true
    end
  end
  return false
end

function seq_get_media_track_index(tr)
  if not tr then
    return nil
  end
  local num = r.GetMediaTrackInfo_Value(tr, "IP_TRACKNUMBER")
  if num and num > 0 then
    return math.floor(num + 0.5) - 1
  end
  return nil
end

function seq_slot_arrange_index(slot)
  if not slot or not slot.reaper_track_guid then
    return nil
  end
  return seq_get_media_track_index(get_track_by_guid(slot.reaper_track_guid))
end

function seq_remap_track_index_after_move(idx, from_idx, to_idx)
  if not idx then
    return idx
  end
  if idx == from_idx then
    return to_idx
  end
  if from_idx < to_idx then
    if idx > from_idx and idx <= to_idx then
      return idx - 1
    end
  elseif to_idx < from_idx then
    if idx >= to_idx and idx < from_idx then
      return idx + 1
    end
  end
  return idx
end

function seq_move_slot_index(from_idx, to_idx)
  local tracks = state.seq_tracks
  if not tracks then
    return false
  end
  local n = #tracks
  if from_idx == to_idx or from_idx < 1 or to_idx < 1 or from_idx > n or to_idx > n then
    return false
  end
  local slot = table.remove(tracks, from_idx)
  table.insert(tracks, to_idx, slot)
  state.selected_seq_track = seq_remap_track_index_after_move(state.selected_seq_track, from_idx, to_idx)
  state.seq_swap_track_idx = seq_remap_track_index_after_move(state.seq_swap_track_idx, from_idx, to_idx)
  return true
end

function seq_reaper_track_guid_set()
  local set = {}
  local n = r.CountTracks(0)
  for i = 0, n - 1 do
    local tr = r.GetTrack(0, i)
    if tr then
      set[r.GetTrackGUID(tr)] = true
    end
  end
  return set
end

-- Drop sequencer slots whose linked arrange tracks were deleted.
function seq_prune_missing_reaper_tracks()
  if seq_undo_applying or state.seq_track_reorder_drag then
    return false
  end
  if seq_undo_is_open and seq_undo_is_open() then
    return false
  end
  if seq_ingest_busy and seq_ingest_busy() then
    return false
  end
  local tracks = state.seq_tracks
  if not tracks or #tracks == 0 then
    return false
  end
  local live = seq_reaper_track_guid_set()
  local removed = false
  for i = #tracks, 1, -1 do
    local slot = tracks[i]
    local guid = slot and slot.reaper_track_guid
    if guid and guid ~= "" and not live[guid] then
      seq_remove_seq_track_slot(i)
      removed = true
    end
  end
  if not removed then
    return false
  end
  save_config()
  if save_seq_project_state then
    save_seq_project_state()
  end
  if find_seq_parent_folder_track then
    find_seq_parent_folder_track()
  end
  return true
end

function seq_sync_track_order_from_arrange()
  if state.seq_track_reorder_drag or seq_undo_applying then
    return false
  end
  seq_prune_missing_reaper_tracks()
  if state.seq_skip_order_sync then
    state.seq_skip_order_sync = nil
    return false
  end
  local tracks = state.seq_tracks
  if not tracks or #tracks < 2 then
    return false
  end
  local linked = {}
  for i = 1, #tracks do
    local arr = seq_slot_arrange_index(tracks[i])
    if arr then
      linked[#linked + 1] = { pos = i, slot = tracks[i], arr = arr }
    end
  end
  if #linked < 2 then
    return false
  end
  local by_pos = {}
  for i = 1, #linked do
    by_pos[i] = linked[i]
  end
  table.sort(by_pos, function(a, b) return a.pos < b.pos end)
  table.sort(linked, function(a, b)
    if a.arr ~= b.arr then
      return a.arr < b.arr
    end
    return a.pos < b.pos
  end)
  local changed = false
  for i = 1, #linked do
    if by_pos[i].slot.id ~= linked[i].slot.id then
      changed = true
      break
    end
  end
  if not changed then
    return false
  end
  local selected_id = state.selected_seq_track and tracks[state.selected_seq_track] and tracks[state.selected_seq_track].id
  local swap_id = state.seq_swap_track_id
  for i = 1, #linked do
    tracks[by_pos[i].pos] = linked[i].slot
  end
  if selected_id then
    local _, idx = find_seq_track_by_id(selected_id)
    state.selected_seq_track = idx
  end
  if swap_id then
    local _, idx = find_seq_track_by_id(swap_id)
    state.seq_swap_track_idx = idx
  end
  save_config()
  return true
end

function seq_capture_selected_track_guids()
  local guids = {}
  local n = r.CountSelectedTracks(0)
  for i = 0, n - 1 do
    local tr = r.GetSelectedTrack(0, i)
    if tr then
      guids[#guids + 1] = r.GetTrackGUID(tr)
    end
  end
  return guids
end

function seq_restore_selected_track_guids(guids)
  local n = r.CountTracks(0)
  for i = 0, n - 1 do
    r.SetTrackSelected(r.GetTrack(0, i), false)
  end
  for i = 1, #(guids or {}) do
    local tr = get_track_by_guid(guids[i])
    if tr then
      r.SetTrackSelected(tr, true)
    end
  end
end

function seq_select_reaper_track_block(tr)
  if not tr then
    return nil, 0
  end
  r.SetOnlyTrackSelected(tr)
  local idx = seq_get_media_track_index(tr)
  if not idx then
    return nil, 0
  end
  local depth = r.GetMediaTrackInfo_Value(tr, "I_FOLDERDEPTH") or 0
  local count = 1
  if depth >= 1 then
    local d = 1
    local n = r.CountTracks(0)
    for i = idx + 1, n - 1 do
      local child = r.GetTrack(0, i)
      r.SetTrackSelected(child, true)
      count = count + 1
      d = d + (r.GetMediaTrackInfo_Value(child, "I_FOLDERDEPTH") or 0)
      if d <= 0 then
        break
      end
    end
  end
  return idx, count
end

function seq_reaper_track_span_end(tr)
  local idx = seq_get_media_track_index(tr)
  if not idx then
    return nil
  end
  local depth = r.GetMediaTrackInfo_Value(tr, "I_FOLDERDEPTH") or 0
  if depth < 1 then
    return idx
  end
  return seq_folder_last_child_index(tr) or idx
end

function seq_move_reaper_track_block_to(tr, dest_idx)
  if not tr or not dest_idx or not r.ReorderSelectedTracks then
    return false
  end
  local src, count = seq_select_reaper_track_block(tr)
  if not src or count < 1 or src == dest_idx then
    return false
  end
  if src < dest_idx then
    r.ReorderSelectedTracks(dest_idx + count, 0)
  else
    r.ReorderSelectedTracks(dest_idx, 0)
  end
  return true
end

function seq_apply_seq_order_to_arrange()
  if not r.ReorderSelectedTracks then
    return false
  end
  local ordered = {}
  for i = 1, #(state.seq_tracks or {}) do
    local slot = state.seq_tracks[i]
    local tr = slot and slot.reaper_track_guid and get_track_by_guid(slot.reaper_track_guid)
    if tr then
      ordered[#ordered + 1] = tr
    end
  end
  if #ordered < 2 then
    return false
  end
  local saved = seq_capture_selected_track_guids()
  if r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  local moved = false
  local guard = 0
  local limit = #ordered * #ordered + 4
  while guard < limit do
    guard = guard + 1
    local prev_tr = nil
    local inversion = nil
    for i = 1, #ordered do
      local tr = ordered[i]
      local idx = seq_get_media_track_index(tr)
      if idx then
        if prev_tr then
          local prev_idx = seq_get_media_track_index(prev_tr)
          if prev_idx and idx < prev_idx then
            inversion = tr
            break
          end
        end
        prev_tr = tr
      end
    end
    if not inversion or not prev_tr then
      break
    end
    local want = (seq_reaper_track_span_end(prev_tr) or seq_get_media_track_index(prev_tr) or 0) + 1
    local have = seq_get_media_track_index(inversion)
    if have and have ~= want then
      if seq_move_reaper_track_block_to(inversion, want) then
        moved = true
      else
        break
      end
    else
      break
    end
  end
  seq_restore_selected_track_guids(saved)
  if r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  if moved then
    r.UpdateArrange()
    state.seq_skip_order_sync = true
    seq_mark_self_arrange_write()
  end
  return moved
end

function find_seq_parent_folder_track()
  if state.seq_folder_guid and state.seq_folder_guid ~= "" then
    local tr = get_track_by_guid(state.seq_folder_guid)
    if tr then
      return tr
    end
    state.seq_folder_guid = nil
  end
  local n = r.CountTracks(0)
  for i = 0, n - 1 do
    local tr = r.GetTrack(0, i)
    local _, name = r.GetTrackName(tr)
    if name == SEQ_TRACK_FOLDER_NAME then
      local depth = r.GetMediaTrackInfo_Value(tr, "I_FOLDERDEPTH") or 0
      if depth >= 1 then
        state.seq_folder_guid = r.GetTrackGUID(tr)
        return tr
      end
    end
  end
  return nil
end

function create_seq_parent_folder_track()
  local insert_idx = r.CountTracks(0)
  r.InsertTrackAtIndex(insert_idx, true)
  local tr = r.GetTrack(0, insert_idx)
  if not tr then
    return nil
  end
  r.GetSetMediaTrackInfo_String(tr, "P_NAME", SEQ_TRACK_FOLDER_NAME, true)
  r.SetMediaTrackInfo_Value(tr, "I_FOLDERDEPTH", 0)
  state.seq_folder_guid = r.GetTrackGUID(tr)
  return tr
end

function seq_folder_last_child_index(folder_tr)
  local folder_idx = seq_get_media_track_index(folder_tr)
  if not folder_idx then
    return nil, false
  end
  local folder_depth = r.GetMediaTrackInfo_Value(folder_tr, "I_FOLDERDEPTH") or 0
  if folder_depth < 1 then
    return folder_idx, false
  end
  local depth = 1
  local last_idx = folder_idx
  local n = r.CountTracks(0)
  for i = folder_idx + 1, n - 1 do
    last_idx = i
    depth = depth + (r.GetMediaTrackInfo_Value(r.GetTrack(0, i), "I_FOLDERDEPTH") or 0)
    if depth <= 0 then
      return last_idx, true
    end
  end
  return last_idx, last_idx > folder_idx
end

function insert_reaper_track_in_seq_folder()
  local folder = find_seq_parent_folder_track() or create_seq_parent_folder_track()
  if not folder then
    local idx = r.CountTracks(0)
    r.InsertTrackAtIndex(idx, true)
    return r.GetTrack(0, idx)
  end

  local last_idx, has_children = seq_folder_last_child_index(folder)
  if not last_idx then
    local idx = r.CountTracks(0)
    r.InsertTrackAtIndex(idx, true)
    return r.GetTrack(0, idx)
  end

  local insert_idx = last_idx + 1
  r.InsertTrackAtIndex(insert_idx, true)
  local new_tr = r.GetTrack(0, insert_idx)
  if not new_tr then
    return nil
  end

  if not has_children then
    r.SetMediaTrackInfo_Value(folder, "I_FOLDERDEPTH", 1)
    r.SetMediaTrackInfo_Value(new_tr, "I_FOLDERDEPTH", -1)
  else
    local prev = r.GetTrack(0, last_idx)
    local prev_d = r.GetMediaTrackInfo_Value(prev, "I_FOLDERDEPTH") or 0
    if prev_d < 0 then
      r.SetMediaTrackInfo_Value(prev, "I_FOLDERDEPTH", prev_d + 1)
    else
      r.SetMediaTrackInfo_Value(prev, "I_FOLDERDEPTH", 0)
    end
    r.SetMediaTrackInfo_Value(new_tr, "I_FOLDERDEPTH", -1)
  end
  return new_tr
end

function create_seq_track_with_name(track_name)
  local final_name = seq_trim_text(track_name)
  if final_name == "" then
    final_name = "Track " .. tostring(#state.seq_tracks + 1)
  end

  local tr
  if state.group_seq_tracks_in_folder ~= false then
    tr = insert_reaper_track_in_seq_folder()
  else
    local insert_idx = r.CountTracks(0)
    r.InsertTrackAtIndex(insert_idx, true)
    tr = r.GetTrack(0, insert_idx)
  end
  if not tr then
    return nil
  end

  r.GetSetMediaTrackInfo_String(tr, "P_NAME", final_name, true)
  local slot = add_seq_track_from_reaper_track(tr)
  if not slot then
    return nil
  end

  slot.name = final_name
  return slot
end

-- Recreate arrange tracks for sequencer slots whose GUIDs no longer resolve
-- (sequencer undo after a track delete).
function seq_ensure_slot_reaper_tracks()
  local changed = false
  for _, slot in ipairs(state.seq_tracks or {}) do
    local guid = slot.reaper_track_guid
    local tr = (guid and guid ~= "") and get_track_by_guid(guid) or nil
    if not tr then
      if state.group_seq_tracks_in_folder ~= false and insert_reaper_track_in_seq_folder then
        tr = insert_reaper_track_in_seq_folder()
      else
        local insert_idx = r.CountTracks(0)
        r.InsertTrackAtIndex(insert_idx, true)
        tr = r.GetTrack(0, insert_idx)
      end
      if tr then
        r.GetSetMediaTrackInfo_String(tr, "P_NAME", slot.name or "Track", true)
        slot.reaper_track_guid = r.GetTrackGUID(tr)
        changed = true
      end
    end
  end
  if changed then
    if seq_apply_seq_order_to_arrange then
      seq_apply_seq_order_to_arrange()
    end
    if seq_mark_self_arrange_write then
      seq_mark_self_arrange_write()
    end
  end
  return changed
end

function create_seq_track_from_popup(track_name, tag_name)
  local own = seq_undo_own_begin("Add sequencer track")
  local slot = create_seq_track_with_name(track_name)
  if not slot then
    if own then
      end_seq_undo("Add sequencer track")
    end
    return false
  end

  local chosen_tag = seq_trim_text(tag_name)
  if chosen_tag ~= "" then
    slot.sample_tag = chosen_tag
    local sample = find_sample_for_tag(chosen_tag)
    if sample then
      assign_sample_to_seq_track(slot, sample, false)
    else
      log("No sample found for tag '" .. chosen_tag .. "'")
    end
  end

  save_config()
  if r.TrackList_AdjustWindows then
    r.TrackList_AdjustWindows(false)
  end
  r.UpdateArrange()
  if own then
    end_seq_undo("Add sequencer track")
  end
  return true
end

function seq_add_popup_tag_width(tag_label)
  local text_w = r.ImGui_CalcTextSize(ctx, tag_label)
  local pad_x = r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())
  return text_w + pad_x * 2
end

function seq_add_popup_count_rows(query_lower, content_w)
  content_w = math.max(120.0, content_w or 480.0)
  local rows = 0
  local row_w = 0.0
  local gap = 6.0
  for _, entry in ipairs(state.tag_list or {}) do
    local tag = tostring(entry.tag or "")
    if query_lower == "" or tag:lower():find(query_lower, 1, true) then
      local tw = seq_add_popup_tag_width(tag)
      if rows == 0 then
        rows = 1
        row_w = tw
      elseif row_w + gap + tw > content_w then
        rows = rows + 1
        row_w = tw
      else
        row_w = row_w + gap + tw
      end
    end
  end
  return math.max(1, rows)
end

function seq_add_popup_window_height(trimmed_query)
  local popup_w = 520.0
  local content_w = popup_w - 32.0
  local query_lower = seq_trim_text(trimmed_query):lower()
  local rows = seq_add_popup_count_rows(query_lower, content_w)
  local tag_row_h = 28.0
  return math.max(220.0, 118.0 + rows * tag_row_h + 12.0)
end

function open_seq_add_track_popup()
  state.seq_new_track_query = ""
  if (not state.tag_list or #state.tag_list == 0) and #state.samples > 0 then
    rebuild_tag_index()
  end
  if r.ImGui_SetNextWindowSize then
    local cond = r.ImGui_Cond_Appearing and r.ImGui_Cond_Appearing() or 0
    r.ImGui_SetNextWindowSize(ctx, 520, seq_add_popup_window_height(""), cond)
  end
  r.ImGui_OpenPopup(ctx, "seq_add_track_popup")
end

function render_seq_add_track_full_width_button(button_id, button_h)
  if draw_ui_button(tostring(button_id or "seq_add_track_popup_open"), nil, nil, button_h or 28, { icon = "plus", full_width = true, style = "primary" }) then
    open_seq_add_track_popup()
  end
end

function render_seq_add_popup_tag_list(trimmed_query)
  local wrap_w = r.ImGui_GetContentRegionAvail(ctx)
  local query_lower = seq_trim_text(trimmed_query):lower()
  local row_w = 0.0
  local gap = 6.0
  local shown_tags = 0
  local first_tag = true

  for idx, entry in ipairs(state.tag_list or {}) do
    local tag = tostring(entry.tag or "")
    if query_lower == "" or tag:lower():find(query_lower, 1, true) then
      local tw = seq_add_popup_tag_width(tag)
      if not first_tag then
        if row_w + gap + tw > wrap_w then
          row_w = 0.0
        else
          r.ImGui_SameLine(ctx, 0, gap)
          row_w = row_w + gap
        end
      end
      first_tag = false
      shown_tags = shown_tags + 1
      if draw_tag_button(ctx, tag, false, tag, "seq_add_popup_" .. tostring(idx) .. "_") then
        if create_seq_track_from_popup(tag, tag) then
          state.seq_new_track_query = ""
          r.ImGui_CloseCurrentPopup(ctx)
        end
      end
      row_w = row_w + tw
    end
  end

  if shown_tags == 0 then
    r.ImGui_TextColored(ctx, 0xFF888888, "No tags match filter")
  end
  return shown_tags
end

function render_seq_add_track_popup()
  local trimmed_query = seq_trim_text(state.seq_new_track_query)
  if r.ImGui_IsPopupOpen and r.ImGui_IsPopupOpen(ctx, "seq_add_track_popup") and r.ImGui_SetNextWindowSize then
    local cond = r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0
    r.ImGui_SetNextWindowSize(ctx, 520, seq_add_popup_window_height(trimmed_query), cond)
  end

  if not r.ImGui_BeginPopup(ctx, "seq_add_track_popup") then
    return
  end

  if (not state.tag_list or #state.tag_list == 0) and #state.samples > 0 then
    rebuild_tag_index()
  end

  r.ImGui_Text(ctx, "Track Name / Tag Search")
  local changed, query = r.ImGui_InputText(ctx, "##seq_new_track_query", state.seq_new_track_query or "", 128)
  seq_mark_text_input_item()
  if changed then
    state.seq_new_track_query = query
    trimmed_query = seq_trim_text(query)
  end

  local create_label = (trimmed_query ~= "") and ('Create "' .. trimmed_query .. '"') or "Create Track"
  if draw_ui_button("seq_create_custom", create_label, nil, nil, { full_width = true, style = "primary" }) then
    if create_seq_track_from_popup(trimmed_query, nil) then
      state.seq_new_track_query = ""
      r.ImGui_CloseCurrentPopup(ctx)
    end
  end

  r.ImGui_Separator(ctx)
  r.ImGui_Text(ctx, "Available Tags")
  r.ImGui_Dummy(ctx, 0, 4)
  render_seq_add_popup_tag_list(trimmed_query)
  r.ImGui_EndPopup(ctx)
end

function get_selected_seq_track()
  clamp_selected_seq_track()
  if not state.selected_seq_track then
    return nil
  end
  return state.seq_tracks[state.selected_seq_track]
end

function preview_seq_track_sample(slot)
  if not slot then
    return false
  end
  local region = seq_sample_assign_region and seq_sample_assign_region() or nil
  local sample = seq_effective_slot_sample and seq_effective_slot_sample(slot, region)
    or (slot.sample_path and find_sample_by_path(slot.sample_path))
  if not sample then
    return false
  end
  preview_sample(sample)
  state.seq_track_play_anims = state.seq_track_play_anims or {}
  state.seq_track_play_anims[tostring(slot.id)] = {
    start_time = r.time_precise(),
    duration = 0.35,
  }
  return true
end

function seq_resolve_hover_note(active, hovered_qn, start_qn, col, step_qn)
  if not active then
    return nil
  end
  if seq_active_cell_is_playable
      and not seq_active_cell_is_playable(active, start_qn, col, step_qn) then
    return nil
  end
  if seq_pick_packed_note then
    return seq_pick_packed_note(active, hovered_qn, start_qn, col, step_qn)
  end
  return active
end

function seq_set_grid_hover(slot, col, active_cells, start_qn, step_qn, hovered_qn)
  if not slot then
    state.seq_grid_hover = nil
    return
  end
  local active = active_cells and col and active_cells[slot.id] and active_cells[slot.id][col]
  local picked = hovered_qn and seq_resolve_hover_note(active, hovered_qn, start_qn, col, step_qn) or nil
  state.seq_grid_hover = {
    slot_id = slot.id,
    step_key = picked and picked.key or nil,
    region_id = picked and picked.region_id or nil,
    note = picked and picked.note or nil,
    hovered_qn = hovered_qn,
    step_qn = step_qn,
  }
end

function select_seq_track(idx, opts)
  opts = opts or {}
  if not idx or idx < 1 or idx > #state.seq_tracks then
    return false
  end
  state.selected_seq_track = idx
  save_config()
  if opts.preview ~= false then
    preview_seq_track_sample(state.seq_tracks[idx])
  end
  return true
end

-- Exposed for the upcoming sequencer UI
function SampleMapBrowser_GetSeqTracks()
  return state.seq_tracks
end

function SampleMapBrowser_GetSelectedSeqTrack()
  return get_selected_seq_track()
end

function SampleMapBrowser_GetSeqTrackSample(slot)
  if not slot or not slot.sample_path then
    return nil
  end
  return find_sample_by_path(slot.sample_path)
end

-- Eased 0..1 pulse used for animated drag/drop feedback.
function drag_pulse()
  return 0.5 + 0.5 * math.sin(r.time_precise() * 6.0)
end

-- Highlight a rectangular drop target while a sample is being dragged onto it.
function draw_drop_target_highlight(dl, x0, y0, x1, y1, radius)
  radius = radius or 4.0
  local pulse = drag_pulse()
  local fill = build_color_rrgbbaa(30, 255, 94, math.floor(28 + 40 * pulse))
  local border = build_color_rrgbbaa(30, 255, 94, math.floor(160 + 80 * pulse))
  local accent = build_color_rrgbbaa(30, 255, 94, 255)
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, fill, radius)
  r.ImGui_DrawList_AddRect(dl, x0, y0, x1, y1, border, radius, 0, 2.0)
  -- Bright accent bar on the left edge so the active target reads at a glance.
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x0 + 3.0, y1, accent, radius)
end

function cursor_over_script_ui()
  local mx, my = r.ImGui_GetMousePos and r.ImGui_GetMousePos(ctx)
  mx, my = tonumber(mx), tonumber(my)
  if not mx or not my then
    return false
  end
  local function in_rect(rect)
    return rect
      and mx >= (rect.x or 0) and my >= (rect.y or 0)
      and mx <= (rect.x or 0) + (rect.w or 0)
      and my <= (rect.y or 0) + (rect.h or 0)
  end
  return in_rect(state.main_window_rect)
    or in_rect(state.sample_map_window_rect)
    or in_rect(state.sequencer_window_rect)
    or in_rect(state.seq_layering_rect)
end

function sample_is_waveform_drag_source(sample)
  local drag = state.pending_waveform_drop
  if not drag or not sample then
    return false
  end
  if drag.is_layering_mix or sample.is_layering_mix then
    return drag.is_layering_mix == true
      and sample.is_layering_mix == true
      and drag.layering_slot_id == sample.layering_slot_id
  end
  local a = drag.path and normalize_path(drag.path)
  local b = sample.path and normalize_path(sample.path)
  return a ~= nil and a == b
end

function draw_waveform_drag_source_cue(dl, x, y, w, h)
  if not dl or not state.pending_waveform_drop then
    return
  end
  local pulse = drag_pulse()
  local fill = build_color_rrgbbaa(30, 255, 94, math.floor(20 + 32 * pulse))
  local border = build_color_rrgbbaa(30, 255, 94, math.floor(170 + 70 * pulse))
  r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, fill, 4.0)
  r.ImGui_DrawList_AddRect(dl, x, y, x + w, y + h, border, 4.0, 0, 2.0)
end

-- Floating feedback that follows the cursor while a sample is being dragged.
function draw_sample_drag_ghost()
  local sample = get_active_dragged_sample()
  if not sample then
    clear_drag_tooltip()
    return
  end

  -- Normal map-dot audition drag: no tooltip unless the cursor is over a
  -- layering corner. Alt+drag and waveform drags keep the sequencer/arrange hints.
  if not state.pending_waveform_drop and not state.seq_layering_drop_vert then
    clear_drag_tooltip()
    return
  end

  local name = sample.name or basename(sample.path or "") or "sample"
  if #name > 40 then
    name = name:sub(1, 39) .. "..."
  end

  local over_seq = state.seq_drop_target_idx ~= nil or state.seq_candidate_drop ~= nil
    or state.seq_drum_drop ~= nil
  local over_timeline = state.seq_timeline_drop_time ~= nil
  local over_layer = state.seq_layering_drop_vert ~= nil
  local over_arrange = state.provisional_drop ~= nil
  local outside = not cursor_over_script_ui()

  -- Native tooltip when the cursor leaves the script (arrange drop).
  if over_arrange or (outside and not over_seq and not over_timeline and not over_layer) then
    local hint
    if state.seq_drum_drop then
      hint = "Release to set this region's sample"
    elseif state.seq_candidate_drop then
      hint = "Release to save in this slot"
    elseif over_seq then
      hint = sample.is_layering_mix
        and "Release to apply layered mix"
        or "Release to swap track sample"
    elseif over_timeline then
      hint = "Release to insert on this track"
    elseif over_arrange then
      hint = "Drop to insert on the arrange"
    else
      hint = "Drag over the arrange to insert  (Esc to cancel)"
    end
    if r.TrackCtl_SetToolTip and r.GetMousePosition then
      local sx, sy = r.GetMousePosition()
      r.TrackCtl_SetToolTip(name .. "\n" .. hint, math.floor((sx or 0) + 22), math.floor((sy or 0) + 22), true)
      state.drag_tooltip_active = true
    end
    return
  end

  clear_drag_tooltip()

  local mx, my = r.ImGui_GetMousePos(ctx)
  if not mx or mx ~= mx then
    return
  end

  local dl = (r.APIExists and r.APIExists("ImGui_GetForegroundDrawList"))
    and r.ImGui_GetForegroundDrawList(ctx)
    or r.ImGui_GetWindowDrawList(ctx)

  if #name > 30 then
    name = name:sub(1, 29) .. "..."
  end

  local over_target = state.seq_drop_target_idx ~= nil
  local hint
  if state.seq_drum_drop then
    hint = "Release to set this region's sample"
  elseif state.seq_candidate_drop then
    hint = "Release to save in this slot"
  elseif over_layer then
    local idx = state.seq_layering_drop_vert and state.seq_layering_drop_vert.idx
    hint = (idx == 1) and "Release to set the original sample" or "Release to set this layer"
  elseif over_target then
    hint = sample.is_layering_mix
      and "Release to apply layered mix"
      or "Release to swap track sample"
  elseif seq_drag_is_from_candidate() then
    hint = seq_region_sample_edit_region()
      and "Drop on the drum icon to set this region's sample"
      or "Drop on a candidate slot or the arrange"
  elseif state.seq_timeline_drop_time then
    hint = "Release to insert on this track"
  else
    hint = "Drag onto a sequencer track"
  end

  local dot_color = get_sample_dot_color(sample)
  local pulse = drag_pulse()

  local name_w, name_h = r.ImGui_CalcTextSize(ctx, name)
  local hint_w, hint_h = r.ImGui_CalcTextSize(ctx, hint)
  local dot_r = 5.0
  local pad = 8.0
  local gap = 7.0
  local line_gap = 3.0
  local text_block_w = math.max(name_w, hint_w)
  local chip_w = pad + dot_r * 2 + gap + text_block_w + pad
  local chip_h = pad + name_h + line_gap + hint_h + pad

  local x0 = mx + 18.0
  local y0 = my + 12.0
  local x1 = x0 + chip_w
  local y1 = y0 + chip_h

  r.ImGui_DrawList_AddRectFilled(dl, x0 + 2, y0 + 3, x1 + 2, y1 + 3, 0x00000070, 7.0)
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, 0x1E2620F5, 7.0)

  local cr, cg, cb = extract_rgb_rrgbbaa(dot_color)
  local border = build_color_rrgbbaa(cr, cg, cb, math.floor(140 + 115 * pulse))
  r.ImGui_DrawList_AddRect(dl, x0, y0, x1, y1, border, 7.0, 0, 1.5)

  local cx = x0 + pad + dot_r
  local cy = y0 + pad + name_h * 0.5
  local ghost_role = seq_icon_role_for_sample(sample)
  if not draw_seq_role_icon(dl, cx, cy, dot_r + 2.0, sample, dot_color, ghost_role) then
    r.ImGui_DrawList_AddCircleFilled(dl, cx, cy, dot_r, dot_color, 16)
  end
  r.ImGui_DrawList_AddCircle(dl, cx, cy, dot_r + 1.5, border, 16, 1.0)

  local tx = x0 + pad + dot_r * 2 + gap
  r.ImGui_DrawList_AddText(dl, tx, y0 + pad, 0xFFFFFFFF, name)
  local hint_color = (over_target or over_layer) and 0x8FE0A6FF or 0x9FB2CCFF
  r.ImGui_DrawList_AddText(dl, tx, y0 + pad + name_h + line_gap, hint_color, hint)
end

function find_map_neighbor_sample(current, direction, required_tag)
  if not current or not current.path then
    return nil
  end

  local cx = current.x or 0.5
  local cy = current.y or 0.5
  local best = nil
  local best_dist = math.huge
  local tag_filter = required_tag and seq_trim_text(required_tag) or ""

  for _, s in ipairs(state.samples) do
    if s.path and s.path ~= current.path and s.x and s.y
      and not sample_scan_folder_unavailable(s)
      and (tag_filter == "" or sample_has_tag(s, tag_filter)) then
      if direction < 0 then
        local dx = cx - s.x
        if dx > 1e-5 then
          local dist = dx * dx + (cy - s.y) * (cy - s.y)
          if dist < best_dist then
            best_dist = dist
            best = s
          end
        end
      else
        local dx = s.x - cx
        if dx > 1e-5 then
          local dist = dx * dx + (cy - s.y) * (cy - s.y)
          if dist < best_dist then
            best_dist = dist
            best = s
          end
        end
      end
    end
  end

  return best
end

function seq_vary_role_is_specific(role)
  return role and role ~= "" and role ~= "default" and role ~= "other"
end

function seq_sample_matches_vary_role(sample, required_role)
  if not seq_vary_role_is_specific(required_role) then
    return true
  end
  if seq_icon_role_for_sample(sample) == required_role then
    return true
  end
  return sample_has_tag(sample, required_role)
end

function seq_normalize_vary_filter(text)
  return seq_trim_text(text):lower()
end

function seq_sample_matches_vary_filter_token(sample, needle)
  if not sample or not needle or needle == "" then
    return true
  end
  local name = string.lower(sample.name or "")
  if name ~= "" and string.find(name, needle, 1, true) then
    return true
  end
  if type(sample.tags) == "table" then
    for _, tag in ipairs(sample.tags) do
      if string.find(string.lower(tostring(tag or "")), needle, 1, true) then
        return true
      end
    end
  end
  local path = sample.path or ""
  local base = path:match("([^/\\]+)$") or path
  if base ~= "" and string.find(string.lower(base), needle, 1, true) then
    return true
  end
  local parent = path:match("([^/\\]+)[/\\][^/\\]+$")
  if parent and string.find(string.lower(parent), needle, 1, true) then
    return true
  end
  return false
end

function seq_sample_matches_vary_filter(sample, filter_text)
  local needle = seq_normalize_vary_filter(filter_text)
  if needle == "" then
    return true
  end
  for token in needle:gmatch("%S+") do
    if not seq_sample_matches_vary_filter_token(sample, token) then
      return false
    end
  end
  return true
end

function collect_map_samples_by_distance(origin, required_role, filter_text)
  local ranked = {}
  if not origin or not origin.path then
    return ranked
  end

  local cx = origin.x or 0.5
  local cy = origin.y or 0.5
  for _, s in ipairs(state.samples) do
    if s.path and s.path ~= origin.path and s.x and s.y
      and not sample_scan_folder_unavailable(s)
      and seq_sample_matches_vary_role(s, required_role)
      and seq_sample_matches_vary_filter(s, filter_text) then
      local dx = s.x - cx
      local dy = s.y - cy
      ranked[#ranked + 1] = { sample = s, dist = math.sqrt(dx * dx + dy * dy) }
    end
  end

  table.sort(ranked, function(a, b)
    if math.abs(a.dist - b.dist) < 1e-9 then
      return (a.sample.path or "") < (b.sample.path or "")
    end
    return a.dist < b.dist
  end)
  return ranked
end

seq_vary_rank_cache = {}
seq_vary_filter_hit_cache = {}

function clear_seq_vary_rank_cache()
  seq_vary_rank_cache = {}
  seq_vary_filter_hit_cache = {}
end

function seq_vary_filter_library_hits(filter_text)
  local needle = seq_normalize_vary_filter(filter_text)
  if needle == "" then
    return nil
  end
  seq_vary_filter_hit_cache = seq_vary_filter_hit_cache or {}
  local cached = seq_vary_filter_hit_cache[needle]
  if cached ~= nil then
    return cached
  end
  local n = 0
  for _, s in ipairs(state.samples or {}) do
    if s and s.path and not sample_scan_folder_unavailable(s)
        and seq_sample_matches_vary_filter(s, needle) then
      n = n + 1
    end
  end
  seq_vary_filter_hit_cache[needle] = n
  return n
end

function seq_vary_filter_has_no_hits(filter_text)
  return seq_vary_filter_library_hits(filter_text) == 0
end

function get_map_samples_ranked_from_path(base_path, required_role, filter_text)
  if state._clear_vary_rank_cache then
    clear_seq_vary_rank_cache()
    state._clear_vary_rank_cache = false
  end
  if not base_path then
    return {}
  end
  if not seq_vary_role_is_specific(required_role) then
    required_role = nil
  end
  filter_text = seq_normalize_vary_filter(filter_text)
  if filter_text == "" then
    filter_text = nil
  end
  local cache_key = base_path
  if required_role then
    cache_key = cache_key .. "\0" .. required_role
  end
  if filter_text then
    cache_key = cache_key .. "\0f:" .. filter_text
  end
  if seq_vary_rank_cache[cache_key] then
    return seq_vary_rank_cache[cache_key]
  end
  local origin = find_sample_by_path(base_path)
  local ranked = origin and collect_map_samples_by_distance(origin, required_role, filter_text) or {}
  seq_vary_rank_cache[cache_key] = ranked
  return ranked
end

function seq_vary_role_for_origin(slot, origin)
  local role = infer_seq_track_role(slot)
  if seq_vary_role_is_specific(role) then
    return role
  end
  role = seq_icon_role_for_sample(origin)
  if seq_vary_role_is_specific(role) then
    return role
  end
  return nil
end

function resolve_seq_note_sample(note, slot, vary_override, filter_text, origin_path)
  -- Locked, copied, or Shift+V-picked notes keep a pinned file. A live vary
  -- filter is a new constraint, so drop an unlocked auto-pin and re-pick.
  if note and type(note.frozen_sample_path) == "string" and note.frozen_sample_path ~= "" then
    if seq_path_exists(note.frozen_sample_path) then
      if seq_note_is_locked(note) or note.picked_sample
          or seq_normalize_vary_filter(filter_text) == "" then
        return note.frozen_sample_path, find_sample_by_path(note.frozen_sample_path)
      end
      seq_clear_frozen_sample(note)
    end
  end
  -- Track slot sample (or region override) is the vary origin.
  local base_path = origin_path or (slot and slot.sample_path) or (note and note.sample_path)
  if not base_path then
    return nil, nil
  end

  local vary = (type(vary_override) == "number") and vary_override or (note and note.sample_vary or 0.0)
  if vary <= 0.000001 then
    return base_path, find_sample_by_path(base_path)
  end

  local origin = find_sample_by_path(base_path)
  if not origin or origin.x == nil or origin.y == nil then
    return base_path, origin
  end

  -- Stay in the same drum/instrument category when possible, but a typed
  -- filter is the real constraint (perc + "bell" should still find bells).
  local role = seq_vary_role_for_origin(slot, origin)
  local ranked = get_map_samples_ranked_from_path(base_path, role, filter_text)
  if #ranked == 0 and seq_normalize_vary_filter(filter_text) ~= "" then
    ranked = get_map_samples_ranked_from_path(base_path, nil, filter_text)
  end
  if #ranked == 0 then
    return base_path, origin
  end

  local t = math.max(0.0, math.min(1.0, vary))
  local idx = math.max(1, math.min(#ranked, math.ceil(t * #ranked)))
  local picked = ranked[idx].sample
  return picked.path, picked
end

function seq_resolve_note_sample(note, slot, vary_override, region, track_id, step_key)
  local filter = seq_cell_vary_filter(region, track_id or (slot and slot.id), step_key, note)
  local origin_path = seq_effective_slot_sample_path and select(1, seq_effective_slot_sample_path(slot, region)) or nil
  return resolve_seq_note_sample(note, slot, vary_override, filter, origin_path)
end

function resolve_seq_hovered_grid_sample()
  local hover = state.seq_grid_hover
  if not hover or not hover.slot_id or not hover.note then
    return nil, nil
  end
  local slot = nil
  for _, s in ipairs(state.seq_tracks) do
    if s.id == hover.slot_id then
      slot = s
      break
    end
  end
  if not slot then
    return nil, nil
  end
  local region = hover.region_id and get_seq_region_by_id(hover.region_id) or nil
  local vary = seq_random_vary_amount(hover.note, region, slot.id, hover.step_key, 1)
  local _, sample = seq_resolve_note_sample(hover.note, slot, vary, region, slot.id, hover.step_key)
  return sample, slot
end

function preview_seq_hovered_grid()
  local hover = state.seq_grid_hover
  if not hover or not hover.slot_id then
    return false
  end
  local slot = nil
  for _, s in ipairs(state.seq_tracks) do
    if s.id == hover.slot_id then
      slot = s
      break
    end
  end
  if not slot then
    return false
  end
  local region = hover.region_id and get_seq_region_by_id(hover.region_id) or nil
  local vary = seq_random_vary_amount(hover.note, region, slot.id, hover.step_key, 1)
  local _, sample = seq_resolve_note_sample(hover.note, slot, vary, region, slot.id, hover.step_key)
  if sample then
    preview_sample(sample)
    state.seq_track_play_anims = state.seq_track_play_anims or {}
    state.seq_track_play_anims[tostring(slot.id)] = {
      start_time = r.time_precise(),
      duration = 0.35,
    }
    return true
  end
  return preview_seq_track_sample(slot)
end

function swap_seq_track_sample_neighbor(slot, direction)
  if not slot then
    return false
  end
  local region = seq_sample_assign_region and seq_sample_assign_region() or nil
  local current_path = seq_effective_slot_sample_path and select(1, seq_effective_slot_sample_path(slot, region))
    or slot.sample_path
  if not current_path then
    return false
  end

  local current = find_sample_by_path(current_path)
  if not current then
    return false
  end

  local neighbor = find_map_neighbor_sample(current, direction, slot.sample_tag)
  if not neighbor then
    if slot.sample_tag and seq_trim_text(slot.sample_tag) ~= "" then
      log("No more samples with tag '" .. slot.sample_tag .. "' " .. (direction < 0 and "to the left" or "to the right") .. " on the map")
    else
      log("No similar sample " .. (direction < 0 and "to the left" or "to the right") .. " on the map")
    end
    return false
  end

  local persist = not seq_slot_in_swap_mode(slot)
  local own = persist and seq_undo_own_begin("Swap sequencer sample")
  seq_assign_sample_for_context(slot, neighbor, persist)
  preview_seq_track_sample(slot)
  if own then
    end_seq_undo("Swap sequencer sample")
  end
  return true
end

function handle_map_arrow_keys()
  if not sample_map_is_open() then
    return
  end
  if imgui_any_popup_open and imgui_any_popup_open() then
    return
  end
  local left = shortcut_pressed("map_prev_sample")
  local right = shortcut_pressed("map_next_sample")
  if not left and not right then
    return
  end
  local direction = left and -1 or 1
  local slot = get_active_swap_slot()
  if not slot and state.selected_seq_track then
    slot = state.seq_tracks[state.selected_seq_track]
  end
  if slot then
    swap_seq_track_sample_neighbor(slot, direction)
    seq_open_minimap_popup(slot, true)
    return
  end
  local current = preview_sample_obj
  if current and current.path then
    local neighbor = find_map_neighbor_sample(current, direction)
    if neighbor then
      preview_sample(neighbor)
    end
  end
end

SEQ_NEIGHBOR_POPUP_COUNT = 10
SEQ_NEIGHBOR_POPUP_CENTER = 5
SEQ_NEIGHBOR_POPUP_PAD = 8

function seq_neighbor_popup_push_closest(arr, limit, sample, dist)
  local count = arr.n or 0
  if count < limit then
    count = count + 1
    arr.n = count
    arr[count] = { sample, dist }
    return
  end
  local worst_i, worst_d = 1, arr[1][2]
  for i = 2, count do
    local d = arr[i][2]
    if d > worst_d then
      worst_i, worst_d = i, d
    end
  end
  if dist < worst_d then
    arr[worst_i] = { sample, dist }
  end
end

function seq_neighbor_popup_take_sorted(arr)
  local count = arr.n or 0
  if count > 1 then
    table.sort(arr, function(a, b)
      return a[2] < b[2]
    end)
  end
  local out = {}
  for i = 1, count do
    out[i] = arr[i][1]
  end
  return out
end

function seq_neighbor_popup_build_items(origin, required_tag)
  local left_n = (SEQ_NEIGHBOR_POPUP_CENTER - 1) + SEQ_NEIGHBOR_POPUP_PAD
  local right_n = (SEQ_NEIGHBOR_POPUP_COUNT - SEQ_NEIGHBOR_POPUP_CENTER) + SEQ_NEIGHBOR_POPUP_PAD
  local items = {}
  local n = 0
  for _ = 1, left_n do
    n = n + 1
    items[n] = nil
  end
  n = n + 1
  items[n] = origin
  local center_idx = n
  for _ = 1, right_n do
    n = n + 1
    items[n] = nil
  end
  if not origin or not origin.path then
    return items, center_idx, n
  end

  local cx = origin.x or 0.5
  local cy = origin.y or 0.5
  local origin_path = origin.path
  local tag_filter = required_tag and seq_trim_text(required_tag) or ""
  local lefts, rights = { n = 0 }, { n = 0 }

  for _, s in ipairs(state.samples) do
    if s.path and s.path ~= origin_path and s.x and s.y
      and not sample_scan_folder_unavailable(s)
      and (tag_filter == "" or sample_has_tag(s, tag_filter)) then
      local dx = s.x - cx
      if dx < -1e-5 then
        local dy = s.y - cy
        seq_neighbor_popup_push_closest(lefts, left_n, s, dx * dx + dy * dy)
      elseif dx > 1e-5 then
        local dy = s.y - cy
        seq_neighbor_popup_push_closest(rights, right_n, s, dx * dx + dy * dy)
      end
    end
  end

  lefts = seq_neighbor_popup_take_sorted(lefts)
  rights = seq_neighbor_popup_take_sorted(rights)
  for i = 1, left_n do
    items[center_idx - i] = lefts[i]
  end
  for i = 1, right_n do
    items[center_idx + i] = rights[i]
  end
  return items, center_idx, n
end

function seq_neighbor_popup_prepare(items, count)
  local entries = {}
  local taken = 0
  local b_lo, b_hi = 1e9, -1e9
  local w_lo, w_hi = 1e9, -1e9
  local d_lo, d_hi = 1e9, -1e9
  for i = 1, count do
    local sample = items[i]
    local entry = sample and seq_candidate_entry_from_sample(sample) or nil
    entries[i] = entry
    if entry then
      local p = seq_candidate_chip_props(entry)
      local bright = p.brightness or p.freq
      taken = taken + 1
      if type(bright) == "number" then
        b_lo = math.min(b_lo, bright)
        b_hi = math.max(b_hi, bright)
      end
      w_lo = math.min(w_lo, p.weight)
      w_hi = math.max(w_hi, p.weight)
      if type(p.duration) == "number" and p.duration > 0 then
        d_lo = math.min(d_lo, p.duration)
        d_hi = math.max(d_hi, p.duration)
      end
    end
  end
  local scale = nil
  if taken >= 2 then
    scale = {
      bright_lo = b_lo, bright_hi = b_hi,
      weight_lo = w_lo, weight_hi = w_hi,
      dur_lo = d_lo, dur_hi = d_hi,
    }
  end
  return entries, scale
end

function seq_open_neighbor_popup(slot, rel)
  if not slot then
    return
  end
  local region = seq_sample_assign_region and seq_sample_assign_region() or nil
  local origin = seq_effective_slot_sample and seq_effective_slot_sample(slot, region)
    or (slot.sample_path and find_sample_by_path(slot.sample_path))
  if not origin then
    return
  end
  rel = tonumber(rel) or 0
  local items, center_idx, item_count = seq_neighbor_popup_build_items(origin, slot.sample_tag)
  local entries, scale = seq_neighbor_popup_prepare(items, item_count)
  local now = r.time_precise()
  local prev = state.seq_neighbor_popup
  local same_slot = prev and prev.slot_id == slot.id
  local anchors = state.seq_nav_anchors
  local anchor = (anchors and anchors[slot.id]) or (same_slot and prev.anchor) or nil
  state.seq_neighbor_popup = {
    slot_id = slot.id,
    items = items,
    entries = entries,
    scale = scale,
    center_idx = center_idx,
    item_count = item_count,
    anchor = anchor,
    idle_since = now,
    hovered = same_slot and prev.hovered or false,
    scroll_from = (rel ~= 0) and -rel or 0,
    scroll_t0 = now,
    scroll_dur = 0.22,
  }
end

function seq_neighbor_popup_choose(slot, sample, rel)
  if not slot or not sample then
    return
  end
  local persist = not seq_slot_in_swap_mode(slot)
  local own = persist and seq_undo_own_begin("Swap sequencer sample")
  seq_assign_sample_for_context(slot, sample, persist)
  preview_seq_track_sample(slot)
  if own then
    end_seq_undo("Swap sequencer sample")
  end
  seq_open_neighbor_popup(slot, rel)
end

function render_seq_neighbor_popup()
  local pop = state.seq_neighbor_popup
  if not pop then
    return
  end
  local slot = find_seq_track_by_id(pop.slot_id)
  if not slot then
    state.seq_neighbor_popup = nil
    return
  end

  local now = r.time_precise()
  if pop.hovered then
    pop.idle_since = now
  end
  local age = now - (pop.idle_since or now)
  if (not pop.hovered) and age >= 1.0 then
    state.seq_neighbor_popup = nil
    return
  end
  local alpha = pop.hovered and 1.0 or math.max(0.0, 1.0 - age)

  local scroll = 0.0
  if pop.scroll_from and pop.scroll_from ~= 0 and pop.scroll_t0 then
    local t = (now - pop.scroll_t0) / (pop.scroll_dur or 0.22)
    if t >= 1.0 then
      pop.scroll_from = 0
      scroll = 0.0
    else
      t = math.max(0.0, t)
      local ease = 1.0 - (1.0 - t) * (1.0 - t)
      scroll = pop.scroll_from * (1.0 - ease)
    end
  end

  local anchors = state.seq_nav_anchors
  if anchors and anchors[pop.slot_id] then
    pop.anchor = anchors[pop.slot_id]
  end
  local anchor = pop.anchor
  if not anchor then
    return
  end

  local sq, gap, pad = 28.0, 4.0, 8.0
  local count = SEQ_NEIGHBOR_POPUP_COUNT
  local view_w = count * sq + (count - 1) * gap
  local win_w = view_w + pad * 2
  local win_h = sq + pad * 2
  local wx = (anchor.x or 0) + (anchor.w or 0) * 0.5 - win_w * 0.5
  local wy = (anchor.y or 0) + (anchor.h or 0) + 8.0
  local wr = state.main_window_rect
  if wr then
    wx = math.max(wr.x + 8, math.min(wx, wr.x + wr.w - win_w - 8))
    if wy + win_h > wr.y + wr.h - 8 then
      wy = (anchor.y or wy) - win_h - 8
    end
    wy = math.max(wr.y + 8, math.min(wy, wr.y + wr.h - win_h - 8))
  end

  if r.ImGui_SetNextWindowPos then
    r.ImGui_SetNextWindowPos(ctx, wx, wy, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
  end
  if r.ImGui_SetNextWindowSize then
    r.ImGui_SetNextWindowSize(ctx, win_w, win_h, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
  end

  local flags = 0
  if r.ImGui_WindowFlags_NoTitleBar then flags = flags | r.ImGui_WindowFlags_NoTitleBar() end
  if r.ImGui_WindowFlags_NoResize then flags = flags | r.ImGui_WindowFlags_NoResize() end
  if r.ImGui_WindowFlags_NoScrollbar then flags = flags | r.ImGui_WindowFlags_NoScrollbar() end
  if r.ImGui_WindowFlags_NoCollapse then flags = flags | r.ImGui_WindowFlags_NoCollapse() end
  if r.ImGui_WindowFlags_NoSavedSettings then flags = flags | r.ImGui_WindowFlags_NoSavedSettings() end
  if r.ImGui_WindowFlags_NoDocking then flags = flags | r.ImGui_WindowFlags_NoDocking() end
  if r.ImGui_WindowFlags_NoNav then flags = flags | r.ImGui_WindowFlags_NoNav() end
  if r.ImGui_WindowFlags_NoFocusOnAppearing then flags = flags | r.ImGui_WindowFlags_NoFocusOnAppearing() end
  if r.ImGui_WindowFlags_NoBackground then flags = flags | r.ImGui_WindowFlags_NoBackground() end
  if r.ImGui_WindowFlags_NoMove then flags = flags | r.ImGui_WindowFlags_NoMove() end

  if r.ImGui_PushStyleVar and r.ImGui_StyleVar_WindowPadding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), 0, 0)
  end
  local began_ok, visible = pcall(r.ImGui_Begin, ctx, "##seq_neighbor_popup", nil, flags)
  if not began_ok or not visible then
    if r.ImGui_PopStyleVar then
      pcall(r.ImGui_PopStyleVar, ctx, 1)
    end
    if began_ok then
      pcall(r.ImGui_End, ctx)
    end
    return
  end

  local hover_flags = 0
  if r.ImGui_HoveredFlags_AllowWhenBlockedByActiveItem then
    hover_flags = r.ImGui_HoveredFlags_AllowWhenBlockedByActiveItem()
  end
  pop.hovered = r.ImGui_IsWindowHovered and r.ImGui_IsWindowHovered(ctx, hover_flags) or false

  local dl = r.ImGui_GetWindowDrawList(ctx)
  local px, py = r.ImGui_GetWindowPos(ctx)
  local bg = UI_THEME.surface or 0x121816FF
  local border = UI_THEME.border or 0x2A3830FF
  local function fade_col(col)
    local orig_a = (col % 256) / 255.0
    return change_color_alpha(col, orig_a * alpha)
  end
  r.ImGui_DrawList_AddRectFilled(dl, px, py, px + win_w, py + win_h, fade_col(bg), 8.0)
  r.ImGui_DrawList_AddRect(dl, px + 0.5, py + 0.5, px + win_w - 0.5, py + win_h - 0.5, fade_col(border), 8.0, 0, 1.0)

  local items = pop.items or {}
  local entries = pop.entries or {}
  local center_idx = pop.center_idx or SEQ_NEIGHBOR_POPUP_CENTER
  local item_count = pop.item_count or 0
  local view_left_idx = center_idx - (SEQ_NEIGHBOR_POPUP_CENTER - 1)
  local scale = pop.scale
  local pitch = sq + gap
  local clip_x0 = px + pad
  local clip_y0 = py + pad
  local clip_x1 = clip_x0 + view_w
  local clip_y1 = clip_y0 + sq
  if r.ImGui_DrawList_PushClipRect then
    r.ImGui_DrawList_PushClipRect(dl, clip_x0, clip_y0, clip_x1, clip_y1, true)
  end

  local mx, my = r.ImGui_GetMousePos(ctx)
  local clicked_sample, clicked_rel = nil, 0
  local tip_name = nil
  for i = 1, item_count do
    local x = clip_x0 + (i - view_left_idx - scroll) * pitch
    if x + sq > clip_x0 - 1 and x < clip_x1 + 1 then
      local sample = items[i]
      local entry = entries[i]
      local is_center = (i == center_idx)
      local hovered_sq = mx >= x and my >= clip_y0 and mx <= x + sq and my <= clip_y1
      seq_draw_sample_candidate_square(
        dl, seq_box(x, clip_y0, sq, sq), entry, is_center, hovered_sq, scale, nil, alpha
      )
      if sample and hovered_sq then
        tip_name = sample.name or sample.path
        if r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 0) and not is_center then
          clicked_sample = sample
          clicked_rel = i - center_idx
        end
      end
    end
  end

  if r.ImGui_DrawList_PopClipRect then
    r.ImGui_DrawList_PopClipRect(dl)
  end

  r.ImGui_InvisibleButton(ctx, "##seq_neighbor_hit", win_w, win_h)
  if tip_name and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, tip_name)
  end

  if r.ImGui_PopStyleVar then
    r.ImGui_PopStyleVar(ctx, 1)
  end
  r.ImGui_End(ctx)

  if clicked_sample then
    seq_neighbor_popup_choose(slot, clicked_sample, clicked_rel)
  end
end

SEQ_MINIMAP_SIZE = 200
SEQ_MINIMAP_ZOOM = 8.0
SEQ_MINIMAP_ZOOM_MIN = 2.0
SEQ_MINIMAP_ZOOM_MAX = 16.0
SEQ_MINIMAP_FADE_HOLD = 0.65
SEQ_MINIMAP_FADE_DUR = 0.8
SEQ_MINIMAP_LABEL_SCALE = 0.7

function seq_minimap_fade_col(col, alpha)
  if not col then
    return col
  end
  if (alpha or 1.0) >= 0.999 then
    return col
  end
  local orig_a = (col % 256) / 255.0
  return change_color_alpha(col, orig_a * (alpha or 1.0))
end

function seq_minimap_format_duration(nx)
  local log10 = math.log(10)
  local dmin = map_cache and map_cache.duration_min
  local dmax = map_cache and map_cache.duration_max
  if not dmin or not dmax then
    dmin, dmax = 0.01, 60.0
  end
  local len_min_log = math.log(math.max(dmin, 0.01)) / log10
  local len_max_log = math.log(math.max(dmax, 0.01)) / log10
  local padding = 0.05
  local t = (nx - padding) / (1.0 - 2.0 * padding)
  t = math.max(0.0, math.min(1.0, t))
  local time_val = 10 ^ (len_min_log + t * (len_max_log - len_min_log))
  if time_val < 1.0 then
    return string.format("%.2fs", time_val)
  elseif time_val < 10.0 then
    return string.format("%.1fs", time_val)
  end
  return string.format("%.0fs", time_val)
end

function seq_minimap_format_y(ny)
  local y_axis = map_y_axis_id()
  local y_normalized = 1.0 - ny
  if y_axis == "weight" then
    if y_normalized >= 0.92 then
      return "Heavy"
    elseif y_normalized <= 0.08 then
      return "Light"
    end
    return string.format("%.0f%%", y_normalized * 100.0)
  end
  local log10 = math.log(10)
  local freq_val = 10 ^ (math.log(40.0) / log10 + y_normalized * (math.log(20000.0) / log10 - math.log(40.0) / log10))
  local rounded_freq = round_to_nice_map_freq(freq_val)
  if rounded_freq >= 1000.0 then
    return string.format("%.1fkHz", rounded_freq / 1000.0)
  end
  return string.format("%.0fHz", rounded_freq)
end

function seq_minimap_label_size(text)
  local tw, th = 0, 10
  if r.ImGui_CalcTextSize then
    tw, th = r.ImGui_CalcTextSize(ctx, text)
  end
  local base_sz = (r.ImGui_GetFontSize and r.ImGui_GetFontSize(ctx)) or 13.0
  local sz = base_sz * SEQ_MINIMAP_LABEL_SCALE
  return (tw or 24) * SEQ_MINIMAP_LABEL_SCALE, (th or 10) * SEQ_MINIMAP_LABEL_SCALE, sz
end

function seq_minimap_draw_label(dl, x, y, color, text, alpha)
  local font = r.ImGui_GetFont and r.ImGui_GetFont(ctx) or nil
  local _, _, sz = seq_minimap_label_size(text)
  local shadow = seq_minimap_fade_col(0x000000AA, alpha)
  if r.ImGui_DrawList_AddTextEx then
    r.ImGui_DrawList_AddTextEx(dl, font, sz, x + 0.7, y + 0.7, shadow, text)
    r.ImGui_DrawList_AddTextEx(dl, font, sz, x, y, color, text)
  else
    r.ImGui_DrawList_AddText(dl, x + 0.7, y + 0.7, shadow, text)
    r.ImGui_DrawList_AddText(dl, x, y, color, text)
  end
end

function draw_seq_minimap_rulers(dl, pop, x0, y0, w, h, alpha, draw_labels)
  local zoom = pop.zoom or SEQ_MINIMAP_ZOOM
  if zoom < 0.001 then
    zoom = 0.001
  end
  local center_x = x0 + w * 0.5 + (pop.pan_x or 0)
  local center_y = y0 + h * 0.5 + (pop.pan_y or 0)
  local grid_color = seq_minimap_fade_col(0x4A5850AA, alpha)
  local text_color = seq_minimap_fade_col(0xC8D4CCDD, alpha)
  local n = 3
  local nx0 = ((x0 - center_x) / (w * zoom)) + 0.5
  local nx1 = ((x0 + w - center_x) / (w * zoom)) + 0.5
  local ny0 = ((y0 - center_y) / (h * zoom)) + 0.5
  local ny1 = ((y0 + h - center_y) / (h * zoom)) + 0.5
  local inset = 3.0

  for i = 0, n do
    local nx = nx0 + (i / n) * (nx1 - nx0)
    local px = center_x + w * (nx - 0.5) * zoom
    if not draw_labels then
      r.ImGui_DrawList_AddLine(dl, px, y0, px, y0 + h, grid_color, 1.0)
    else
      local label = seq_minimap_format_duration(nx)
      local tw = seq_minimap_label_size(label)
      local tx = px + 3
      if i == 0 then
        tx = x0 + 28
      elseif i == n or tx + tw > x0 + w - inset then
        tx = math.max(x0 + inset, px - tw - 2)
      end
      seq_minimap_draw_label(dl, tx, y0 + inset, text_color, label, alpha)
    end
  end

  for i = 0, n do
    local ny = ny0 + (i / n) * (ny1 - ny0)
    local py = center_y + h * (ny - 0.5) * zoom
    if not draw_labels then
      r.ImGui_DrawList_AddLine(dl, x0, py, x0 + w, py, grid_color, 1.0)
    elseif i > 0 then
      local label = seq_minimap_format_y(ny)
      local tw, th = seq_minimap_label_size(label)
      local ty = py - (th or 8) * 0.5
      if ty < y0 + 12 then
        ty = y0 + 12
      elseif ty > y0 + h - (th or 8) - inset then
        ty = y0 + h - (th or 8) - inset
      end
      seq_minimap_draw_label(dl, x0 + inset, ty, text_color, label, alpha)
    end
  end
end

function seq_minimap_filter_tag(slot)
  local tag = resolve_seq_swap_filter_tag(slot)
  if not tag or tag == "" then
    return ""
  end
  return find_library_tag(tag) or tag
end

function seq_minimap_ensure_samples(pop, slot)
  local tag = seq_minimap_filter_tag(slot)
  local lib_n = #(state.samples or {})
  if pop.samples and pop.tag == tag and pop.lib_n == lib_n then
    return
  end
  pop.tag = tag
  pop.lib_n = lib_n
  local list = {}
  for i = 1, lib_n do
    local s = state.samples[i]
    if s and s.path and s.x and s.y
      and not sample_scan_folder_unavailable(s)
      and (tag == "" or sample_has_tag(s, tag)) then
      if not s._render_color then
        s._render_color = get_sample_dot_color(s)
      end
      list[#list + 1] = s
    end
  end
  pop.samples = list
end

function seq_minimap_center_on(pop, sample, w, h)
  local sx = (sample and sample.x) or 0.5
  local sy = (sample and sample.y) or 0.5
  local z = pop.zoom or SEQ_MINIMAP_ZOOM
  pop.pan_x = -w * (sx - 0.5) * z
  pop.pan_y = -h * (sy - 0.5) * z
end

function seq_minimap_clamp_pan(pop, w, h)
  local z = pop.zoom or SEQ_MINIMAP_ZOOM
  local max_pan = w * 0.5 * z
  pop.pan_x = math.max(-max_pan, math.min(max_pan, pop.pan_x or 0))
  local min_pan_y = h * 0.5 * (1.0 - z)
  local max_pan_y = h * 0.5 * (z - 1.0)
  pop.pan_y = math.max(min_pan_y, math.min(max_pan_y, pop.pan_y or 0))
end

function seq_pin_note_sample(note, sample, slot, region)
  if type(note) ~= "table" or not sample or not sample.path then
    return false
  end
  local path = sample.path
  local origin_path = seq_note_vary_origin_path(note, slot, region)
  local track_path, track_name = seq_effective_slot_sample_path(slot, region)
  if not track_path then
    track_path, track_name = slot and slot.sample_path, slot and slot.sample_name
  end
  local same_as_track = track_path and seq_paths_same(path, track_path)
  local already = seq_paths_same(note.frozen_sample_path, path)
    or ((not seq_note_has_frozen_sample(note)) and same_as_track)
  if already and (tonumber(note.sample_vary) or 0) <= 0.000001 then
    return false
  end

  local function zero_hit_vary(hit)
    if type(hit) == "table" then
      hit.sample_vary = 0.0
    end
  end

  if same_as_track then
    seq_clear_frozen_sample(note)
    note.sample_path = track_path
    note.sample_name = track_name or basename(track_path)
    note.sample_vary = 0.0
    if type(note.stutter_hits) == "table" then
      for _, hit in pairs(note.stutter_hits) do
        zero_hit_vary(hit)
      end
    end
    return true
  end

  seq_apply_frozen_sample(note, path, sample, origin_path)
  note.sample_path = path
  note.sample_name = sample.name or basename(path)
  note.sample_vary = 0.0
  note.picked_sample = true
  if type(note.stutter_hits) == "table" then
    for _, hit in pairs(note.stutter_hits) do
      if type(hit) == "table" then
        seq_apply_frozen_sample(hit, path, sample, origin_path)
        hit.sample_vary = 0.0
        hit.picked_sample = true
      end
    end
  end
  return true
end

function seq_collect_note_sample_pick_targets()
  local targets = {}
  local seen = {}
  local function add(region_id, track_id, step_key)
    if not region_id or track_id == nil or step_key == nil then
      return
    end
    local key = tostring(region_id) .. ":" .. tostring(track_id) .. ":" .. tostring(step_key)
    if seen[key] then
      return
    end
    if not get_seq_note(get_seq_region_by_id(region_id), track_id, step_key) then
      return
    end
    seen[key] = true
    targets[#targets + 1] = {
      region_id = region_id,
      track_id = track_id,
      step_key = tostring(step_key),
    }
  end

  if seq_has_razors() then
    local items = seq_razor_collect_notes()
    for i = 1, #items do
      local rec = items[i]
      add(rec.region_id, rec.track_id, rec.step_key)
    end
    return targets
  end

  local hover = state.seq_grid_hover
  if hover and hover.note and hover.region_id and hover.step_key then
    add(hover.region_id, hover.slot_id, hover.step_key)
    return targets
  end

  local sel = state.selected_seq_note
  if sel then
    add(sel.region_id, sel.track_id, sel.step_key)
  end
  return targets
end

function seq_assign_sample_to_note_targets(targets, sample)
  if not sample or not sample.path or not targets or #targets == 0 then
    return false
  end
  local own = seq_undo_own_begin("Swap note sample")
  local changed = false
  local synced = {}
  for i = 1, #targets do
    local t = targets[i]
    local region = get_seq_region_by_id(t.region_id)
    local slot = seq_find_slot_by_id(t.track_id)
    local note = get_seq_note(region, t.track_id, t.step_key)
    if note and slot and seq_pin_note_sample(note, sample, slot, region) then
      changed = true
      if region and region.pattern_id then
        local by_track = synced[region.pattern_id]
        if not by_track then
          by_track = {}
          synced[region.pattern_id] = by_track
        end
        by_track[slot.id] = slot
      end
    end
  end
  if changed then
    if r.PreventUIRefresh then
      r.PreventUIRefresh(1)
    end
    for pattern_id, slots in pairs(synced) do
      for _, slot in pairs(slots) do
        sync_seq_pattern_track(pattern_id, slot, { skip_arrange = true, force_rebuild = true })
      end
    end
    if r.PreventUIRefresh then
      r.PreventUIRefresh(-1)
    end
    r.UpdateArrange()
    save_config()
  end
  preview_sample(sample)
  if own then
    end_seq_undo("Swap note sample")
  end
  return true
end

function seq_begin_note_sample_pick()
  if seq_ingest_busy and seq_ingest_busy() then
    return false
  end
  local targets = seq_collect_note_sample_pick_targets()
  if #targets == 0 then
    if seq_has_razors() then
      log("No notes in the razor to swap")
    else
      log("Hover a sequencer note or draw a razor, then Shift+V to pick a sample")
    end
    return false
  end
  local origin = targets[1]
  local hover = state.seq_grid_hover
  if hover and hover.slot_id then
    for i = 1, #targets do
      if targets[i].track_id == hover.slot_id then
        origin = targets[i]
        break
      end
    end
  end
  local region = get_seq_region_by_id(origin.region_id)
  local slot = seq_find_slot_by_id(origin.track_id)
  if not slot then
    return false
  end
  local note = get_seq_note(region, origin.track_id, origin.step_key)
  local origin_sample = nil
  if note then
    local vary = seq_random_vary_amount(note, region, slot.id, origin.step_key, 1)
    local _, resolved = seq_resolve_note_sample(note, slot, vary, region, slot.id, origin.step_key)
    origin_sample = resolved
  end
  origin_sample = origin_sample or find_sample_by_path(slot.sample_path)
  seq_open_minimap_popup(slot, true, {
    mode = "notes",
    targets = targets,
    origin_path = (origin_sample and origin_sample.path) or slot.sample_path,
    place_at_mouse = true,
    pin_anchor = true,
  })
  return true
end

function seq_toggle_note_sample_pick()
  local pop = state.seq_minimap_popup
  if pop and pop.mode == "notes" then
    state.seq_minimap_popup = nil
    return true
  end
  return seq_begin_note_sample_pick()
end

function seq_minimap_assign(slot, sample)
  if not sample or not sample.path then
    return
  end
  local pop = state.seq_minimap_popup
  if pop and pop.mode == "notes" then
    seq_assign_sample_to_note_targets(pop.targets, sample)
    pop.origin_path = sample.path
    return
  end
  if not slot then
    return
  end
  local region = seq_sample_assign_region and seq_sample_assign_region() or nil
  local current_path = seq_effective_slot_sample_path and select(1, seq_effective_slot_sample_path(slot, region))
    or slot.sample_path
  if current_path and seq_paths_same and seq_paths_same(current_path, sample.path) then
    preview_seq_track_sample(slot)
    return
  end
  local persist = not seq_slot_in_swap_mode(slot)
  local own = persist and seq_undo_own_begin("Swap sequencer sample")
  seq_assign_sample_for_context(slot, sample, persist)
  preview_seq_track_sample(slot)
  if own then
    end_seq_undo("Swap sequencer sample")
  end
end

function seq_open_minimap_popup(slot, recenter, opts)
  if not slot then
    return
  end
  opts = opts or {}
  local mode = opts.mode or "track"
  local now = r.time_precise()
  local prev = state.seq_minimap_popup
  local same = prev and prev.slot_id == slot.id and (prev.mode or "track") == mode
  local anchors = state.seq_nav_anchors
  local anchor = opts.anchor
    or ((not opts.pin_anchor) and anchors and anchors[slot.id])
    or (same and prev.anchor)
    or nil
  if (not anchor or not anchor.x) and r.ImGui_GetMousePos then
    local mx, my = r.ImGui_GetMousePos(ctx)
    anchor = { x = (mx or 0) - 100, y = (my or 0) + 16, w = 200, h = 24 }
  end
  local pop = same and prev or {
    zoom = SEQ_MINIMAP_ZOOM,
    pan_x = 0,
    pan_y = 0,
  }
  pop.slot_id = slot.id
  pop.mode = mode
  pop.targets = opts.targets
  pop.origin_path = opts.origin_path
  pop.place_at_mouse = opts.place_at_mouse and true or nil
  pop.pin_anchor = opts.pin_anchor and true or nil
  pop.anchor = anchor
  pop.hovered = true
  pop.opened_at = now
  pop.idle_since = now
  pop.need_center = (not same) or (recenter ~= false)
  if not same then
    pop.samples = nil
    pop.tag = nil
    pop.zoom = SEQ_MINIMAP_ZOOM
    pop.press_x = nil
    pop.dragging = false
    pop.pan_drag = false
  end
  if mode ~= "notes" then
    pop.targets = nil
    pop.origin_path = nil
    pop.place_at_mouse = nil
    pop.pin_anchor = nil
  end
  state.seq_minimap_popup = pop
  state.seq_neighbor_popup = nil
end

function render_seq_minimap_popup()
  local pop = state.seq_minimap_popup
  if not pop then
    return
  end
  local slot = nil
  for _, s in ipairs(state.seq_tracks or {}) do
    if s.id == pop.slot_id then
      slot = s
      break
    end
  end
  if not slot then
    state.seq_minimap_popup = nil
    return
  end

  if r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
      and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false) then
    state.seq_minimap_popup = nil
    return
  end

  local anchors = state.seq_nav_anchors
  if (not pop.pin_anchor) and anchors and anchors[pop.slot_id] then
    pop.anchor = anchors[pop.slot_id]
  end
  local anchor = pop.anchor
  if not anchor or not anchor.x then
    local mx, my = r.ImGui_GetMousePos(ctx)
    anchor = { x = (mx or 40) - 100, y = (my or 40) + 16, w = 200, h = 24 }
    pop.anchor = anchor
  end

  pcall(seq_minimap_ensure_samples, pop, slot)

  local now = r.time_precise()
  local keep = pop.hovered or pop.pan_drag or pop.dragging or pop.press_x
  if keep then
    pop.idle_since = now
  end
  local age = now - (pop.idle_since or pop.opened_at or now)
  local hold = SEQ_MINIMAP_FADE_HOLD
  local fade_dur = SEQ_MINIMAP_FADE_DUR
  if (not keep) and age >= hold + fade_dur then
    state.seq_minimap_popup = nil
    return
  end
  local alpha = 1.0
  if (not keep) and age > hold then
    alpha = math.max(0.0, 1.0 - (age - hold) / fade_dur)
  end

  local map_w, map_h = SEQ_MINIMAP_SIZE, SEQ_MINIMAP_SIZE
  local pad = 6.0
  local win_w = map_w + pad * 2
  local win_h = map_h + pad * 2
  local wx = (anchor.x or 0) + (anchor.w or 0) * 0.5 - win_w * 0.5
  local wy = (anchor.y or 0) + (anchor.h or 0) + 8.0
  local wr = state.main_window_rect
  if wr then
    wx = math.max(wr.x + 8, math.min(wx, wr.x + wr.w - win_w - 8))
    if wy + win_h > wr.y + wr.h - 8 then
      wy = (anchor.y or wy) - win_h - 8
    end
    wy = math.max(wr.y + 8, math.min(wy, wr.y + wr.h - win_h - 8))
  end

  if pop.place_at_mouse and r.ImGui_GetMousePos then
    local mx, my = r.ImGui_GetMousePos(ctx)
    wx = (mx or wx) - win_w * 0.5
    wy = (my or wy) - 24
    pop.place_at_mouse = nil
    if wr then
      wx = math.max(wr.x + 8, math.min(wx, wr.x + wr.w - win_w - 8))
      wy = math.max(wr.y + 8, math.min(wy, wr.y + wr.h - win_h - 8))
    end
  end

  if pop.need_center then
    seq_minimap_center_on(pop, find_sample_by_path(pop.origin_path or (seq_effective_slot_sample_path and select(1, seq_effective_slot_sample_path(slot, seq_sample_assign_region and seq_sample_assign_region()))) or slot.sample_path), map_w, map_h)
    seq_minimap_clamp_pan(pop, map_w, map_h)
    pop.need_center = false
  end

  if r.ImGui_SetNextWindowPos then
    r.ImGui_SetNextWindowPos(ctx, wx, wy, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
  end
  if r.ImGui_SetNextWindowSize then
    r.ImGui_SetNextWindowSize(ctx, win_w, win_h, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
  end
  if r.ImGui_SetNextWindowCollapsed then
    r.ImGui_SetNextWindowCollapsed(ctx, false, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
  end

  local pushed_vars = 0
  if r.ImGui_PushStyleVar and r.ImGui_StyleVar_Alpha then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_Alpha(), alpha)
    pushed_vars = pushed_vars + 1
  end
  if r.ImGui_PushStyleVar and r.ImGui_StyleVar_WindowPadding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), 0, 0)
    pushed_vars = pushed_vars + 1
  end
  if r.ImGui_PushStyleVar and r.ImGui_StyleVar_WindowRounding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowRounding(), 8)
    pushed_vars = pushed_vars + 1
  end
  if r.ImGui_PushStyleVar and r.ImGui_StyleVar_WindowBorderSize then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowBorderSize(), 0)
    pushed_vars = pushed_vars + 1
  end
  local function pop_minimap_alpha()
    if pushed_vars > 0 and r.ImGui_PopStyleVar then
      r.ImGui_PopStyleVar(ctx, pushed_vars)
      pushed_vars = 0
    end
  end

  local flags = 0
  if r.ImGui_WindowFlags_NoTitleBar then flags = flags | r.ImGui_WindowFlags_NoTitleBar() end
  if r.ImGui_WindowFlags_NoCollapse then flags = flags | r.ImGui_WindowFlags_NoCollapse() end
  if r.ImGui_WindowFlags_NoResize then flags = flags | r.ImGui_WindowFlags_NoResize() end
  if r.ImGui_WindowFlags_NoScrollbar then flags = flags | r.ImGui_WindowFlags_NoScrollbar() end
  if r.ImGui_WindowFlags_NoScrollWithMouse then flags = flags | r.ImGui_WindowFlags_NoScrollWithMouse() end
  if r.ImGui_WindowFlags_NoSavedSettings then flags = flags | r.ImGui_WindowFlags_NoSavedSettings() end
  if r.ImGui_WindowFlags_NoDocking then flags = flags | r.ImGui_WindowFlags_NoDocking() end
  if r.ImGui_WindowFlags_NoNav then flags = flags | r.ImGui_WindowFlags_NoNav() end
  if r.ImGui_WindowFlags_NoFocusOnAppearing then flags = flags | r.ImGui_WindowFlags_NoFocusOnAppearing() end
  if r.ImGui_WindowFlags_NoMove then flags = flags | r.ImGui_WindowFlags_NoMove() end
  if r.ImGui_WindowFlags_NoBackground then flags = flags | r.ImGui_WindowFlags_NoBackground() end
  if r.ImGui_WindowFlags_TopMost then flags = flags | r.ImGui_WindowFlags_TopMost() end

  local began_ok, visible = pcall(r.ImGui_Begin, ctx, "##seq_minimap_popup", nil, flags)
  if not began_ok then
    pop_minimap_alpha()
    log("Mini map window failed: " .. tostring(visible))
    return
  end
  if not visible then
    r.ImGui_End(ctx)
    pop_minimap_alpha()
    return
  end

  local hover_flags = 0
  if r.ImGui_HoveredFlags_AllowWhenBlockedByActiveItem then
    hover_flags = r.ImGui_HoveredFlags_AllowWhenBlockedByActiveItem()
  end
  pop.hovered = r.ImGui_IsWindowHovered and r.ImGui_IsWindowHovered(ctx, hover_flags) or false

  local dl = r.ImGui_GetWindowDrawList(ctx)
  local wx0, wy0 = r.ImGui_GetWindowPos(ctx)
  local mx0 = wx0 + pad
  local my0 = wy0 + pad
  if r.ImGui_SetCursorScreenPos then
    r.ImGui_SetCursorScreenPos(ctx, mx0, my0)
  end
  r.ImGui_InvisibleButton(ctx, "##seq_minimap_area", map_w, map_h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local mx, my = r.ImGui_GetMousePos(ctx)

  local frame_bg = seq_minimap_fade_col(UI_THEME.surface or 0x121816FF, alpha)
  local frame_border = seq_minimap_fade_col(UI_THEME.border or 0x2A3830FF, alpha)
  r.ImGui_DrawList_AddRectFilled(dl, wx0, wy0, wx0 + win_w, wy0 + win_h, frame_bg, 8.0)
  r.ImGui_DrawList_AddRect(dl, wx0 + 0.5, wy0 + 0.5, wx0 + win_w - 0.5, wy0 + win_h - 0.5, frame_border, 8.0, 0, 1.0)
  r.ImGui_DrawList_AddRectFilled(dl, mx0, my0, mx0 + map_w, my0 + map_h, seq_minimap_fade_col(UI_THEME.bg or 0x0A0E0CFF, alpha), 5.0)

  local zoom = pop.zoom or SEQ_MINIMAP_ZOOM
  local pan_x = pop.pan_x or 0
  local pan_y = pop.pan_y or 0
  local samples = pop.samples or {}
  local current_path = (pop.mode == "notes" and pop.origin_path)
    or (seq_effective_slot_sample_path and select(1, seq_effective_slot_sample_path(slot, seq_sample_assign_region and seq_sample_assign_region())))
    or slot.sample_path
  local playing_path = preview_sample_obj and preview_sample_obj.path or nil
  local dot_r = 3.6
  local hit_r_sq = (dot_r * 5.0) * (dot_r * 5.0)
  local margin = dot_r * 4
  local closest, current_e, playing_e = nil, nil, nil

  if r.ImGui_DrawList_PushClipRect then
    r.ImGui_DrawList_PushClipRect(dl, mx0, my0, mx0 + map_w, my0 + map_h, true)
  end
  draw_seq_minimap_rulers(dl, pop, mx0, my0, map_w, map_h, alpha, false)

  for i = 1, #samples do
    local s = samples[i]
    local sx = mx0 + map_w * 0.5 + pan_x + map_w * ((s.x or 0.5) - 0.5) * zoom
    local sy = my0 + map_h * 0.5 + pan_y + map_h * ((s.y or 0.5) - 0.5) * zoom
    if sx >= mx0 - margin and sx <= mx0 + map_w + margin
        and sy >= my0 - margin and sy <= my0 + map_h + margin then
      local col = seq_minimap_fade_col(s._render_color or get_sample_dot_color(s), alpha)
      local is_current = current_path and s.path == current_path
      local is_playing = playing_path and s.path == playing_path
      if is_current then
        current_e = { s = s, px = sx, py = sy, color = col }
      elseif is_playing then
        playing_e = { s = s, px = sx, py = sy, color = col }
      else
        r.ImGui_DrawList_AddCircleFilled(dl, sx, sy, dot_r, col, 8)
      end
      if hovered then
        local dx = mx - sx
        local dy = my - sy
        local dist_sq = dx * dx + dy * dy
        if dist_sq <= hit_r_sq and (not closest or dist_sq < closest.dist_sq) then
          closest = { sample = s, px = sx, py = sy, dist_sq = dist_sq, color = col }
        end
      end
    end
  end

  local function draw_focus(e, radius, ring)
    if not e then
      return
    end
    r.ImGui_DrawList_AddCircleFilled(dl, e.px, e.py, radius, e.color, 12)
    r.ImGui_DrawList_AddCircle(dl, e.px, e.py, radius + 2.4, seq_minimap_fade_col(ring, alpha), 12, 1.6)
  end
  draw_focus(playing_e, dot_r * 1.7, 0xE8F4FFFF)
  draw_focus(current_e, dot_r * 2.0, 0x4DE8FFFF)

  if closest then
    r.ImGui_DrawList_AddCircle(dl, closest.px, closest.py, dot_r + 2.0, closest.color, 12, 1.6)
    if r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, closest.sample.name or closest.sample.path or "")
    end
  end

  draw_seq_minimap_rulers(dl, pop, mx0, my0, map_w, map_h, alpha, true)

  if r.ImGui_DrawList_PopClipRect then
    r.ImGui_DrawList_PopClipRect(dl)
  end
  r.ImGui_DrawList_AddRect(dl, mx0 + 0.5, my0 + 0.5, mx0 + map_w - 0.5, my0 + map_h - 0.5,
    seq_minimap_fade_col(UI_THEME.border or 0x2A3830FF, alpha), 5.0, 0, 1.0)

  -- Right-drag pan
  if hovered and r.ImGui_IsMouseClicked(ctx, 1) then
    pop.pan_drag = true
    pop.drag_mx = mx
    pop.drag_my = my
    pop.drag_pan_x = pop.pan_x
    pop.drag_pan_y = pop.pan_y
    pop.dragging = false
    pop.press_x = nil
  elseif pop.pan_drag and r.ImGui_IsMouseDown(ctx, 1) then
    pop.pan_x = (pop.drag_pan_x or 0) + (mx - (pop.drag_mx or mx))
    pop.pan_y = (pop.drag_pan_y or 0) + (my - (pop.drag_my or my))
    seq_minimap_clamp_pan(pop, map_w, map_h)
  elseif pop.pan_drag and r.ImGui_IsMouseReleased(ctx, 1) then
    pop.pan_drag = false
  end

  -- Left click / drag-audition
  if hovered and not pop.pan_drag and r.ImGui_IsMouseClicked(ctx, 0) then
    pop.press_x = mx
    pop.press_y = my
    pop.press_sample = closest and closest.sample or nil
    pop.dragging = false
    pop.last_preview_path = nil
  elseif pop.press_x and r.ImGui_IsMouseDown(ctx, 0) then
    local dx = mx - pop.press_x
    local dy = my - pop.press_y
    if (not pop.dragging) and (dx * dx + dy * dy) > 16 then
      pop.dragging = true
    end
    if pop.dragging and closest and closest.sample
        and closest.sample.path ~= pop.last_preview_path then
      pop.last_preview_path = closest.sample.path
      preview_sample(closest.sample)
    end
  elseif pop.press_x and r.ImGui_IsMouseReleased(ctx, 0) then
    if not pop.dragging and pop.press_sample then
      seq_minimap_assign(slot, pop.press_sample)
    elseif pop.dragging and closest and closest.sample then
      seq_minimap_assign(slot, closest.sample)
    end
    pop.press_x = nil
    pop.press_sample = nil
    pop.dragging = false
  end

  -- Wheel zoom toward cursor
  if hovered and not pop.pan_drag then
    local wheel = r.ImGui_GetMouseWheel(ctx)
    if wheel ~= 0 then
      local old_zoom = pop.zoom or SEQ_MINIMAP_ZOOM
      local new_zoom = math.max(SEQ_MINIMAP_ZOOM_MIN, math.min(SEQ_MINIMAP_ZOOM_MAX, old_zoom * math.exp(wheel * 0.15)))
      local center_x = mx0 + map_w * 0.5 + (pop.pan_x or 0)
      local center_y = my0 + map_h * 0.5 + (pop.pan_y or 0)
      local map_norm_x = ((mx - center_x) / (map_w * old_zoom)) + 0.5
      local map_norm_y = ((my - center_y) / (map_h * old_zoom)) + 0.5
      pop.zoom = new_zoom
      pop.pan_x = mx - map_w * (map_norm_x - 0.5) * new_zoom - (mx0 + map_w * 0.5)
      pop.pan_y = my - map_h * (map_norm_y - 0.5) * new_zoom - (my0 + map_h * 0.5)
      seq_minimap_clamp_pan(pop, map_w, map_h)
    end
  end

  r.ImGui_End(ctx)
  pop_minimap_alpha()
end

PREVIEW_HISTORY_ROW_H = 20
PREVIEW_HISTORY_MAX_ROWS = 10
PREVIEW_HISTORY_WIDTH = 228

function seq_open_history_popup()
  history_compact_unique()
  if not preview_sample_obj and #(state.played_history or {}) == 0 then
    return
  end
  if not state.history_head then
    state.history_head = preview_sample_obj
  end
  local now = r.time_precise()
  local pop = state.preview_history_popup
  local reuse = pop ~= nil
  pop = pop or {}
  pop.hovered = true
  pop.opened_at = now
  pop.idle_since = now
  if not reuse or not pop.x then
    local mx, my = 40, 40
    if r.ImGui_GetMousePos then
      mx, my = r.ImGui_GetMousePos(ctx)
    end
    pop.x = (mx or 40) + 16
    pop.y = (my or 40) + 16
  end
  state.preview_history_popup = pop
end

function history_preview_item(sample)
  if not sample or not sample.path then
    return
  end
  local head = state.history_head
  if head and head.path == sample.path then
    state.history_index = 0
  else
    local idx = 0
    local hist = state.played_history or {}
    for i = 1, #hist do
      if hist[i] and hist[i].path == sample.path then
        idx = i
        break
      end
    end
    if idx == 0 then
      return
    end
    state.history_index = idx
  end
  preview_sample_from_history(sample)
end

function render_preview_history_popup()
  local pop = state.preview_history_popup
  if not pop then
    return
  end

  if r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
      and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false) then
    state.preview_history_popup = nil
    return
  end

  local now = r.time_precise()
  local keep = pop.hovered
  if keep then
    pop.idle_since = now
  end
  local age = now - (pop.idle_since or pop.opened_at or now)
  local hold = SEQ_MINIMAP_FADE_HOLD
  local fade_dur = SEQ_MINIMAP_FADE_DUR
  if (not keep) and age >= hold + fade_dur then
    state.preview_history_popup = nil
    return
  end
  local alpha = 1.0
  if (not keep) and age > hold then
    alpha = math.max(0.0, 1.0 - (age - hold) / fade_dur)
  end

  local items = history_build_items()
  if #items == 0 then
    state.preview_history_popup = nil
    return
  end

  local current_path = preview_sample_obj and preview_sample_obj.path or nil
  local sel = 1
  for i = 1, #items do
    if items[i].path == current_path then
      sel = i
      break
    end
  end

  local row_h = PREVIEW_HISTORY_ROW_H
  local max_rows = PREVIEW_HISTORY_MAX_ROWS
  local vis = math.min(max_rows, #items)
  local start_i = 1
  if #items > vis then
    start_i = math.max(1, math.min(sel - math.floor((vis - 1) * 0.5), #items - vis + 1))
  end
  local pad = 6.0
  local win_w = PREVIEW_HISTORY_WIDTH
  local win_h = pad * 2 + vis * row_h

  local wx = pop.x or 40
  local wy = pop.y or 40
  local wr = state.main_window_rect
  if wr then
    wx = math.max(wr.x + 8, math.min(wx, wr.x + wr.w - win_w - 8))
    wy = math.max(wr.y + 8, math.min(wy, wr.y + wr.h - win_h - 8))
  end
  pop.x, pop.y = wx, wy

  if r.ImGui_SetNextWindowPos then
    r.ImGui_SetNextWindowPos(ctx, wx, wy, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
  end
  if r.ImGui_SetNextWindowSize then
    r.ImGui_SetNextWindowSize(ctx, win_w, win_h, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
  end

  local pushed_vars = 0
  if r.ImGui_PushStyleVar and r.ImGui_StyleVar_Alpha then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_Alpha(), alpha)
    pushed_vars = pushed_vars + 1
  end
  if r.ImGui_PushStyleVar and r.ImGui_StyleVar_WindowPadding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), 0, 0)
    pushed_vars = pushed_vars + 1
  end
  if r.ImGui_PushStyleVar and r.ImGui_StyleVar_WindowRounding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowRounding(), 8)
    pushed_vars = pushed_vars + 1
  end
  if r.ImGui_PushStyleVar and r.ImGui_StyleVar_WindowBorderSize then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowBorderSize(), 0)
    pushed_vars = pushed_vars + 1
  end
  local function pop_hist_style()
    if pushed_vars > 0 and r.ImGui_PopStyleVar then
      r.ImGui_PopStyleVar(ctx, pushed_vars)
      pushed_vars = 0
    end
  end

  local flags = 0
  if r.ImGui_WindowFlags_NoTitleBar then flags = flags | r.ImGui_WindowFlags_NoTitleBar() end
  if r.ImGui_WindowFlags_NoResize then flags = flags | r.ImGui_WindowFlags_NoResize() end
  if r.ImGui_WindowFlags_NoScrollbar then flags = flags | r.ImGui_WindowFlags_NoScrollbar() end
  if r.ImGui_WindowFlags_NoScrollWithMouse then flags = flags | r.ImGui_WindowFlags_NoScrollWithMouse() end
  if r.ImGui_WindowFlags_NoCollapse then flags = flags | r.ImGui_WindowFlags_NoCollapse() end
  if r.ImGui_WindowFlags_NoSavedSettings then flags = flags | r.ImGui_WindowFlags_NoSavedSettings() end
  if r.ImGui_WindowFlags_NoDocking then flags = flags | r.ImGui_WindowFlags_NoDocking() end
  if r.ImGui_WindowFlags_NoNav then flags = flags | r.ImGui_WindowFlags_NoNav() end
  if r.ImGui_WindowFlags_NoFocusOnAppearing then flags = flags | r.ImGui_WindowFlags_NoFocusOnAppearing() end
  if r.ImGui_WindowFlags_NoMove then flags = flags | r.ImGui_WindowFlags_NoMove() end
  if r.ImGui_WindowFlags_NoBackground then flags = flags | r.ImGui_WindowFlags_NoBackground() end
  if r.ImGui_WindowFlags_TopMost then flags = flags | r.ImGui_WindowFlags_TopMost() end

  local began_ok, visible = pcall(r.ImGui_Begin, ctx, "##preview_history_popup", nil, flags)
  if not began_ok then
    pop_hist_style()
    log("History list failed: " .. tostring(visible))
    return
  end
  if not visible then
    r.ImGui_End(ctx)
    pop_hist_style()
    return
  end

  local hover_flags = 0
  if r.ImGui_HoveredFlags_AllowWhenBlockedByActiveItem then
    hover_flags = r.ImGui_HoveredFlags_AllowWhenBlockedByActiveItem()
  end
  pop.hovered = r.ImGui_IsWindowHovered and r.ImGui_IsWindowHovered(ctx, hover_flags) or false

  local dl = r.ImGui_GetWindowDrawList(ctx)
  local px, py = r.ImGui_GetWindowPos(ctx)
  r.ImGui_InvisibleButton(ctx, "##preview_history_hit", win_w, win_h)
  local mx2, my2 = r.ImGui_GetMousePos(ctx)

  r.ImGui_DrawList_AddRectFilled(dl, px, py, px + win_w, py + win_h, seq_minimap_fade_col(UI_THEME.surface or 0x121816FF, alpha), 8.0)
  r.ImGui_DrawList_AddRect(dl, px + 0.5, py + 0.5, px + win_w - 0.5, py + win_h - 0.5,
    seq_minimap_fade_col(UI_THEME.border or 0x2A3830FF, alpha), 8.0, 0, 1.0)

  local clicked = nil
  for row = 0, vis - 1 do
    local i = start_i + row
    local sample = items[i]
    if sample then
      local ry = py + pad + row * row_h
      local hovered_row = mx2 >= px and mx2 <= px + win_w and my2 >= ry and my2 <= ry + row_h
      local is_cur = current_path and sample.path == current_path
      if is_cur then
        r.ImGui_DrawList_AddRectFilled(dl, px + 3, ry, px + win_w - 3, ry + row_h,
          seq_minimap_fade_col(0x1EFF5E44, alpha), 4.0)
      elseif hovered_row then
        r.ImGui_DrawList_AddRectFilled(dl, px + 3, ry, px + win_w - 3, ry + row_h,
          seq_minimap_fade_col(0xFFFFFF18, alpha), 4.0)
      end
      local col = sample._render_color or get_sample_dot_color(sample)
      local dot_x = px + 14
      local dot_y = ry + row_h * 0.5
      r.ImGui_DrawList_AddCircleFilled(dl, dot_x, dot_y, 4.0, seq_minimap_fade_col(col, alpha), 10)
      if is_cur then
        r.ImGui_DrawList_AddCircle(dl, dot_x, dot_y, 6.0, seq_minimap_fade_col(0x4DE8FFFF, alpha), 10, 1.4)
      end
      local name = sample.name
      if not name or name == "" then
        name = (sample.path and sample.path:match("([^/\\]+)$")) or sample.path or "Sample"
      end
      local text_x = px + 24
      local text_w = win_w - 32
      if seq_truncate_text_to_width then
        name = seq_truncate_text_to_width(name, text_w)
      end
      local tw, th = 0, 12
      if r.ImGui_CalcTextSize then
        tw, th = r.ImGui_CalcTextSize(ctx, name)
      end
      r.ImGui_DrawList_AddText(dl, text_x, ry + (row_h - (th or 12)) * 0.5,
        seq_minimap_fade_col(is_cur and 0xF4FFF8FF or (UI_THEME.text or 0xE8EEE8FF), alpha), name)
      if hovered_row and r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 0) then
        clicked = sample
      end
    end
  end

  r.ImGui_End(ctx)
  pop_hist_style()

  if clicked then
    history_preview_item(clicked)
    pop.idle_since = r.time_precise()
  end
end

function render_swap_mode_bar()
  if not state.seq_swap_track_id then
    return
  end

  local slot, idx = get_active_swap_slot()
  if not slot then
    clear_seq_swap_mode_state()
    return
  end
  state.seq_swap_track_idx = idx

  r.ImGui_PushStyleColor(ctx, r.ImGui_Col_ChildBg(), UI_THEME.accent_fill)
  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FrameRounding(), 8)
  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FramePadding(), 10, 8)

  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "Swap sample")
  r.ImGui_SameLine(ctx)
  r.ImGui_TextColored(ctx, UI_THEME.accent_hvr, slot.name)
  r.ImGui_SameLine(ctx)

  if state.block_swap_bar_input then
    r.ImGui_BeginDisabled(ctx)
  end

  if draw_ui_button("swap_cancel", nil, 28, 26, { icon = "close", style = "danger" }) then
    end_seq_swap_mode(false)
  end

  r.ImGui_SameLine(ctx)
  if draw_ui_button("swap_confirm", nil, 28, 26, { icon = "check", style = "success" }) then
    end_seq_swap_mode(true)
  end

  if state.block_swap_bar_input then
    r.ImGui_EndDisabled(ctx)
  end

  r.ImGui_PopStyleVar(ctx, 2)
  r.ImGui_PopStyleColor(ctx, 1)
  r.ImGui_Separator(ctx)
end

