function ensure_vfx_icons()
  if not ctx or not r.ImGui_CreateImage or not r.ImGui_Attach then
    return false
  end
  local cached = vfx_icon_images.by_name.Link
  if vfx_icon_images.attached_ctx == ctx
      and cached
      and r.ImGui_ValidatePtr
      and r.ImGui_ValidatePtr(cached, "ImGui_Image*") then
    return true
  end

  vfx_icon_images.by_name = {}
  for name, filename in pairs(VFX_ICON_FILES) do
    local path = VFX_ICON_DIR .. "/" .. filename
    local ok, img = pcall(r.ImGui_CreateImage, path)
    if ok and img then
      local ok_attach = pcall(r.ImGui_Attach, ctx, img)
      if ok_attach then
        vfx_icon_images.by_name[name] = img
      end
    end
  end
  vfx_icon_images.attached_ctx = ctx
  return vfx_icon_images.by_name.Link ~= nil
end

function get_vfx_icon(name)
  ensure_vfx_icons()
  return vfx_icon_images.by_name[name]
end

function ensure_seq_role_icons()
  if not ctx or not r.ImGui_CreateImage or not r.ImGui_Attach then
    return false
  end
  local cached = seq_icon_images.by_role.default or seq_icon_images.by_role.kick
  if seq_icon_images.attached_ctx == ctx
      and cached
      and r.ImGui_ValidatePtr
      and r.ImGui_ValidatePtr(cached, "ImGui_Image*") then
    return true
  end

  seq_icon_images.by_role = {}
  for role, filename in pairs(SEQ_ROLE_ICON_FILES) do
    local path = SEQ_ICON_DIR .. "/" .. filename
    local ok, img = pcall(r.ImGui_CreateImage, path)
    if ok and img then
      local ok_attach = pcall(r.ImGui_Attach, ctx, img)
      if ok_attach then
        seq_icon_images.by_role[role] = img
      end
    end
  end
  seq_icon_images.attached_ctx = ctx
  return next(seq_icon_images.by_role) ~= nil
end

function seq_icon_role_from_tags(tags)
  if type(tags) ~= "table" then
    return nil
  end
  local best_tag = nil
  local best_weight = -1
  for _, tag_name in ipairs(tags) do
    local key = tostring(tag_name or ""):lower()
    if SEQ_ROLE_ICON_FILES[key] then
      local weight = TAG_KEYWORD_WEIGHT[key] or 1
      if weight > best_weight then
        best_weight = weight
        best_tag = key
      end
    end
  end
  return best_tag
end

-- Resolve icon role without using full file paths (parent folders like
-- "Snare Pack/Hats/..." falsely match "snare" before "hat").
function seq_icon_role_for_sample(sample)
  if not sample then
    return "default"
  end

  local role = seq_icon_role_from_tags(sample.tags)
  if role then
    return role
  end

  role = classify_seq_role_text(sample.name)
  if role and SEQ_ROLE_ICON_FILES[role] then
    return role
  end

  if sample.path then
    local base = sample.path:match("([^/\\]+)$") or sample.path
    role = classify_seq_role_text(base)
    if role and SEQ_ROLE_ICON_FILES[role] then
      return role
    end
  end

  return "default"
end

-- Sequencer lanes: prefer the track's role identity over sample-path heuristics.
function seq_icon_role_for_slot(slot, sample)
  if slot then
    local role = classify_seq_role_text(slot.name)
    if role and SEQ_ROLE_ICON_FILES[role] then
      return role
    end
    role = classify_seq_role_text(slot.sample_tag)
    if role and SEQ_ROLE_ICON_FILES[role] then
      return role
    end
  end
  return seq_icon_role_for_sample(sample or (slot and find_sample_by_path(slot.sample_path)) or nil)
end

function get_seq_role_icon(role)
  ensure_seq_role_icons()
  if role and seq_icon_images.by_role[role] then
    return seq_icon_images.by_role[role]
  end
  return seq_icon_images.by_role.default
end

function draw_seq_role_icon(dl, cx, cy, half, sample, tint, role)
  if not r.ImGui_DrawList_AddImage then
    return false
  end
  role = role or seq_icon_role_for_sample(sample)
  if not role or not SEQ_ROLE_ICON_FILES[role] then
    role = "default"
  end
  local img = get_seq_role_icon(role)
  if not img then
    return false
  end
  if r.ImGui_ValidatePtr and not r.ImGui_ValidatePtr(img, "ImGui_Image*") then
    seq_icon_images.attached_ctx = nil
    img = get_seq_role_icon(role)
    if not img then
      return false
    end
  end
  r.ImGui_DrawList_AddImage(
    dl, img,
    cx - half, cy - half, cx + half, cy + half,
    0.0, 0.0, 1.0, 1.0,
    tint or 0xFFFFFFFF
  )
  return true
end

function prune_seq_track_play_anims(now)
  local anims = state.seq_track_play_anims
  if not anims then
    return
  end
  for key, anim in pairs(anims) do
    local start_t = anim.start_time or 0.0
    local dur = anim.duration or SEQ_TRACK_PLAY_ANIM_DURATION
    if (now - start_t) >= dur then
      anims[key] = nil
    end
  end
end

function get_seq_track_play_anim(track_id, now)
  local anims = state.seq_track_play_anims
  if not anims or track_id == nil then
    return nil
  end
  local anim = anims[tostring(track_id)]
  if not anim then
    return nil
  end
  local dur = anim.duration or SEQ_TRACK_PLAY_ANIM_DURATION
  local t = dur > 0 and ((now - (anim.start_time or now)) / dur) or 1.0
  if t <= 0.0 then
    t = 0.0
  elseif t >= 1.0 then
    anims[tostring(track_id)] = nil
    return nil
  end
  anim.t = t
  return anim
end

function draw_seq_track_play_row_fx(dl, x0, y0, x1, y1, play_t, sample)
  if not play_t then
    return
  end
  local pulse = math.sin(play_t * math.pi)
  local accent = sample and get_sample_dot_color(sample) or UI_THEME.accent
  local ar, ag, ab = extract_rgb_rrgbbaa(accent)
  local bg_alpha = math.floor(24 + pulse * 48 + (1.0 - play_t) * 36)
  local edge_alpha = math.floor(50 + pulse * 130)
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, build_color_rrgbbaa(ar, ag, ab, bg_alpha), 4)
  r.ImGui_DrawList_AddRect(dl, x0, y0, x1, y1, build_color_rrgbbaa(255, 255, 255, edge_alpha), 4, 0, 1.0 + pulse * 1.5)
  local bar_w = 2.0 + pulse * 3.0
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x0 + bar_w, y1, build_color_rrgbbaa(ar, ag, ab, math.floor(110 + pulse * 145)), 2)
end

function get_seq_track_sample_controls_width(ctrl_size, icon_size)
  ctrl_size = ctrl_size or 20.0
  icon_size = icon_size or SEQ_SAMPLE_DOT_SIZE
  local item_spacing = seq_sample_controls_item_spacing()
  return ctrl_size * 2 + icon_size + item_spacing * 2 + 2.0
end

function draw_sample_dot_control(sample, id_suffix, is_swap_active, play_t, role, icon_size, cue)
  local size = icon_size or SEQ_SAMPLE_DOT_SIZE
  r.ImGui_InvisibleButton(ctx, "seq_dot_" .. id_suffix, size, size)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local hover_flags = 0
  if sample_drag_active() and r.ImGui_HoveredFlags_AllowWhenBlockedByActiveItem then
    hover_flags = r.ImGui_HoveredFlags_AllowWhenBlockedByActiveItem()
  end
  local hovered = r.ImGui_IsItemHovered(ctx, hover_flags)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local min_x, min_y = r.ImGui_GetItemRectMin(ctx)
  local max_x, max_y = r.ImGui_GetItemRectMax(ctx)
  if sample_drag_active() and not hovered then
    local mx, my = r.ImGui_GetMousePos(ctx)
    if mx and mx >= min_x and mx <= max_x and my >= min_y and my <= max_y then
      hovered = true
    end
  end
  local cx = (min_x + max_x) * 0.5
  local cy = (min_y + max_y) * 0.5
  local pulse = play_t and math.sin(play_t * math.pi) or 0.0
  local icon_half = (size * 0.46) + pulse * math.min(2.0, size * 0.06)
  local fill = get_sample_dot_color(sample)
  cue = cue or {}
  local region_color = cue.region_color
  local override_color = cue.override_color or region_color
  local has_override = cue.has_override
  local edit_mode = cue.edit_mode
  local ring_color = is_swap_active and 0xFFFFFFFF
    or (edit_mode and region_color)
    or (has_override and override_color)
    or 0x666666FF
  local ring_radius = icon_half + ((is_swap_active or edit_mode or has_override) and 2.0 or 1.0)
  local ring_thickness = is_swap_active and 2.0 or ((edit_mode or has_override) and 2.0 or 1.0)

  if (edit_mode or has_override) and (region_color or override_color) then
    local halo_col = (edit_mode and region_color) or override_color
    local halo_a = edit_mode and (has_override and 90 or 55) or 40
    local rr, rg, rb = extract_rgb_rrgbbaa(halo_col)
    r.ImGui_DrawList_AddCircleFilled(
      dl, cx, cy, icon_half + 3.5,
      build_color_rrgbbaa(rr, rg, rb, halo_a),
      24
    )
  end

  if play_t and sample then
    local ripple_r = ring_radius + 4.0 + play_t * 12.0
    local ripple_alpha = math.floor((1.0 - play_t) * 170 + pulse * 35)
    local sr, sg, sb = extract_rgb_rrgbbaa(fill)
    r.ImGui_DrawList_AddCircle(dl, cx, cy, ripple_r, build_color_rrgbbaa(sr, sg, sb, ripple_alpha), 24, 1.5)
    local outer_r = icon_half + 2.0 + pulse * 3.0
    r.ImGui_DrawList_AddCircle(dl, cx, cy, outer_r, build_color_rrgbbaa(255, 255, 255, math.floor(40 + pulse * 120)), 24, 1.0)
  end

  if sample then
    local icon_role = role or seq_icon_role_for_sample(sample)
    if not draw_seq_role_icon(dl, cx, cy, icon_half, sample, fill, icon_role) then
      r.ImGui_DrawList_AddCircleFilled(dl, cx, cy, icon_half * 0.55, fill, 24)
    end
  end
  r.ImGui_DrawList_AddCircle(dl, cx, cy, ring_radius, ring_color or 0x666666FF, 24, ring_thickness)
  if cue.drop_armed and hovered then
    local dp = drag_pulse()
    local rr, rg, rb
    if region_color then
      rr, rg, rb = extract_rgb_rrgbbaa(region_color)
    else
      rr, rg, rb = 30, 255, 94
    end
    r.ImGui_DrawList_AddCircle(
      dl, cx, cy, ring_radius + 3.0 + dp * 2.0,
      build_color_rrgbbaa(rr, rg, rb, math.floor(160 + 80 * dp)),
      24, 2.2
    )
  end
  if has_override and override_color then
    local pip_r = math.max(2.2, size * 0.13)
    local pip_x = max_x - pip_r - 0.4
    local pip_y = max_y - pip_r - 0.4
    r.ImGui_DrawList_AddCircleFilled(dl, pip_x, pip_y, pip_r + 1.1, 0xFF111111, 12)
    r.ImGui_DrawList_AddCircleFilled(dl, pip_x, pip_y, pip_r, override_color, 12)
    r.ImGui_DrawList_AddCircle(dl, pip_x, pip_y, pip_r, 0xFFFFFFFF, 12, 1.0)
  end

  return clicked, hovered
end

function render_seq_track_sample_controls(slot, idx, opts)
  opts = opts or {}
  local id_suffix = opts.id_suffix or tostring(slot.id)
  local icon_size = opts.icon_size
  if not icon_size and opts.lane_h then
    icon_size = seq_icon_size_for_lane_h(opts.lane_h)
  end
  icon_size = icon_size or SEQ_SAMPLE_DOT_SIZE
  local ctrl_size = opts.ctrl_size or seq_ctrl_size_for_icon(icon_size)
  local show_sample_label = opts.show_sample_label == true
  local sample_label_max_len = opts.sample_label_max_len or 22
  local item_spacing = seq_sample_controls_item_spacing()
  local container_h = opts.container_h or opts.lane_h
  if not container_h then
    container_h = math.max(ctrl_size, icon_size)
  end

  local swap_active = state.seq_swap_track_id and state.seq_swap_track_id == slot.id
  local edit_region = seq_region_sample_edit_region and seq_region_sample_edit_region() or nil
  local cue_region, has_override = seq_slot_region_sample_cue(slot)
  local display_region = edit_region or get_seq_region_by_id(state.selected_seq_region_id)
  local assigned_sample = seq_effective_slot_sample(slot, display_region)
    or (slot.sample_path and find_sample_by_path(slot.sample_path)) or nil
  local play_anim = get_seq_track_play_anim(slot.id, r.time_precise())
  local play_t = play_anim and play_anim.t or nil
  local icon_role = seq_icon_role_for_slot(slot, assigned_sample)
  local sample_label = (assigned_sample and (assigned_sample.name or basename(assigned_sample.path)))
    or slot.sample_name or "(no sample)"
  if #sample_label > sample_label_max_len then
    sample_label = sample_label:sub(1, sample_label_max_len - 3) .. "..."
  end
  local cue_color = (edit_region or (has_override and cue_region))
    and seq_region_pool_color((edit_region or cue_region).pool_id, 230)
    or nil
  local dot_cue = {
    region_color = cue_color,
    override_color = has_override and cue_color or nil,
    has_override = has_override,
    edit_mode = edit_region ~= nil,
  }

  local row_drop_hovered = false
  local can_nav = assigned_sample ~= nil or (slot.sample_path and slot.sample_path ~= "")
  local start_x, start_y = r.ImGui_GetCursorScreenPos(ctx)
  local x = start_x
  -- Center in the track/row rect (opts.y0/y1), not relative to a pre-offset cursor.
  local area_y0 = opts.y0 or start_y
  local area_y1 = opts.y1 or (area_y0 + container_h)
  local mid_y = (area_y0 + area_y1) * 0.5

  -- Lay out chevrons + icon on a shared vertical center so lane zoom never skews them.
  if not can_nav then
    r.ImGui_BeginDisabled(ctx)
  end
  r.ImGui_SetCursorScreenPos(ctx, x, mid_y - ctrl_size * 0.5)
  if draw_ui_button("seq_left_" .. id_suffix, nil, ctrl_size, ctrl_size, { icon = "chev_left", compact = true, style = "ghost_arrow" }) then
    swap_seq_track_sample_neighbor(slot, -1)
    seq_open_minimap_popup(slot, true)
  end
  if sample_drag_active() and r.ImGui_IsItemHovered(ctx) and not seq_drag_is_from_candidate() then
    row_drop_hovered = true
  end
  if not can_nav then
    r.ImGui_EndDisabled(ctx)
  end
  x = x + ctrl_size + item_spacing

  r.ImGui_SetCursorScreenPos(ctx, x, mid_y - icon_size * 0.5)
  local region_mode = edit_region ~= nil
  dot_cue.drop_armed = sample_drag_active() and region_mode
  local dot_clicked, dot_hovered = draw_sample_dot_control(assigned_sample, id_suffix, swap_active, play_t, icon_role, icon_size, dot_cue)
  if r.ImGui_IsItemClicked(ctx, 1) then
    local region = seq_region_sample_edit_region and seq_region_sample_edit_region() or nil
    if region and seq_slot_has_region_sample(slot, region) then
      local own = seq_undo_own_begin("Clear region sample")
      seq_assign_region_track_sample(region, slot, nil, true)
      preview_seq_track_sample(slot)
      if own then
        end_seq_undo("Clear region sample")
      end
    end
  end
  if dot_hovered and r.ImGui_SetTooltip then
    if sample_drag_active() and edit_region then
      r.ImGui_SetTooltip(ctx, "Release to set this region's sample")
    elseif edit_region then
      if has_override then
        r.ImGui_SetTooltip(ctx, "Region sample — swap to change this region and linked copies\nRight-click to restore the track sample")
      else
        r.ImGui_SetTooltip(ctx, "Swap drums to change this region's sample (linked copies too)")
      end
    elseif has_override then
      r.ImGui_SetTooltip(ctx, "This track has a sample for the focused region")
    end
  end
  if dot_clicked and not sample_drag_active() then
    begin_seq_swap_mode(idx)
    if not sample_map_is_open() then
      state.active_view = "sample_map"
      save_config()
    end
  end
  if sample_drag_active() and dot_hovered and not seq_candidate_drag_from_slot(slot) then
    if region_mode then
      state.seq_drum_drop = { slot_id = slot.id, idx = idx }
      state.seq_candidate_drop = nil
      state.seq_drop_target_idx = nil
      state.seq_timeline_drop_time = nil
      state.seq_timeline_drop_track_idx = nil
    elseif not seq_drag_is_from_candidate() then
      row_drop_hovered = true
    end
  end
  x = x + icon_size + item_spacing

  if not can_nav then
    r.ImGui_BeginDisabled(ctx)
  end
  r.ImGui_SetCursorScreenPos(ctx, x, mid_y - ctrl_size * 0.5)
  if draw_ui_button("seq_right_" .. id_suffix, nil, ctrl_size, ctrl_size, { icon = "chev_right", compact = true, style = "ghost_arrow" }) then
    swap_seq_track_sample_neighbor(slot, 1)
    seq_open_minimap_popup(slot, true)
  end
  if sample_drag_active() and r.ImGui_IsItemHovered(ctx) and not seq_drag_is_from_candidate() then
    row_drop_hovered = true
  end
  if not can_nav then
    r.ImGui_EndDisabled(ctx)
  end
  x = x + ctrl_size

  if show_sample_label then
    local _, label_h = r.ImGui_CalcTextSize(ctx, sample_label)
    r.ImGui_SetCursorScreenPos(ctx, x + item_spacing, mid_y - (label_h or 0) * 0.5)
    r.ImGui_TextColored(ctx, assigned_sample and 0xFFCCCCCC or 0xFF666666, sample_label)
    if sample_drag_active() and r.ImGui_IsItemHovered(ctx) and not seq_drag_is_from_candidate() then
      row_drop_hovered = true
    end
    local label_max_x = select(1, r.ImGui_GetItemRectMax(ctx)) or (x + item_spacing)
    x = math.max(x, label_max_x)
  end

  -- Reserve the laid-out strip so following widgets don't overlap.
  r.ImGui_SetCursorScreenPos(ctx, start_x, start_y)
  r.ImGui_Dummy(ctx, math.max(1.0, x - start_x), container_h)

  state.seq_nav_anchors = state.seq_nav_anchors or {}
  state.seq_nav_anchors[slot.id] = {
    x = start_x,
    y = area_y0,
    w = math.max(1.0, x - start_x),
    h = math.max(1.0, area_y1 - area_y0),
  }

  return {
    row_drop_hovered = row_drop_hovered,
    swap_active = swap_active,
    row_h = container_h,
    icon_size = icon_size,
    ctrl_size = ctrl_size,
  }
end


local function render_seq_tracks_panel()
  state.map_hover_track_id = nil
  seq_sync_track_order_from_arrange()

  if state.seq_random_edit_region_id then
    local random_edit_region = nil
    for _, reg in ipairs(state.seq_regions) do
      if reg.id == state.seq_random_edit_region_id then
        random_edit_region = reg
        break
      end
    end
    if random_edit_region then
      r.ImGui_TextColored(ctx, UI_THEME.text, "Region Random: " .. (random_edit_region.name or ("Region " .. tostring(random_edit_region.id))))
      r.ImGui_TextColored(ctx, UI_THEME.text_dim, "Adjust knobs in sequencer lanes. Swap drums for this region only.")
      r.ImGui_Separator(ctx)
    else
      state.seq_random_edit_region_id = nil
    end
  end

  prune_seq_track_play_anims(r.time_precise())

  local add_row_h = 28.0
  local add_row_gap = 6.0
  local row_h = SEQ_PANEL_TRACK_ROW_H
  local icon_size = SEQ_PANEL_ICON_SIZE
  local ctrl_size = seq_ctrl_size_for_icon(icon_size)
  local nav_w = get_seq_track_sample_controls_width(ctrl_size, icon_size)
  local dl = r.ImGui_GetWindowDrawList(ctx)

  if #state.seq_tracks == 0 then
    r.ImGui_TextColored(ctx, 0xFF888888, "No tracks")
  else
    for idx, slot in ipairs(state.seq_tracks) do
      local selected = state.selected_seq_track == idx
      local swap_active = state.seq_swap_track_id and state.seq_swap_track_id == slot.id
      local display_region = seq_region_sample_edit_region() or get_seq_region_by_id(state.selected_seq_region_id)
      local assigned_sample = seq_effective_slot_sample(slot, display_region)
        or (slot.sample_path and find_sample_by_path(slot.sample_path)) or nil
      local cue_region, has_override = seq_slot_region_sample_cue(slot)
      local stripe_region = has_override and (display_region or cue_region) or nil

      r.ImGui_PushID(ctx, slot.id)

      local row_x, row_y = r.ImGui_GetCursorScreenPos(ctx)
      local avail_w = r.ImGui_GetContentRegionAvail(ctx)
      local gap = 4.0
      local ctrl_x1 = row_x + math.max(90.0, avail_w - nav_w - gap)
      local row_drop_hovered = false
      local mx, my = r.ImGui_GetMousePos(ctx)
      local row_hovered = mx >= row_x and mx < row_x + avail_w and my >= row_y and my < row_y + row_h
        and r.ImGui_IsWindowHovered(ctx)
      if row_hovered then
        state.map_hover_track_id = slot.id
      end

      if selected or swap_active then
        r.ImGui_DrawList_AddRectFilled(dl, row_x, row_y, row_x + avail_w, row_y + row_h,
          swap_active and UI_THEME.accent_fill_h or UI_THEME.accent_fill, 4.0)
      elseif row_hovered and not seq_candidate_drag_from_slot(slot) then
        r.ImGui_DrawList_AddRectFilled(dl, row_x, row_y, row_x + avail_w, row_y + row_h, 0xFFFFFF12, 4.0)
      end
      if stripe_region then
        local stripe = seq_region_pool_color(stripe_region.pool_id, 220)
        r.ImGui_DrawList_AddRectFilled(dl, row_x, row_y, row_x + 3.5, row_y + row_h, stripe, 2.0)
        local sr, sg, sb = extract_rgb_rrgbbaa(stripe)
        r.ImGui_DrawList_AddRectFilled(
          dl, row_x, row_y, row_x + avail_w, row_y + row_h,
          build_color_rrgbbaa(sr, sg, sb, 22),
          4.0
        )
      end

      local layout = seq_get_track_control_layout(row_x, row_y, ctrl_x1, row_y + row_h, slot, { hide_expand = true })
      seq_draw_track_name_and_expand(dl, slot, layout, false, 255, nil, slot.name)

      local name_box = layout.name
      if name_box and name_box.w > 4 then
        r.ImGui_SetCursorScreenPos(ctx, name_box.x, name_box.y)
        r.ImGui_InvisibleButton(ctx, "##seq_panel_name_" .. slot.id, name_box.w, name_box.h)
        if r.ImGui_IsItemClicked(ctx, 0) and not sample_drag_active() then
          select_seq_track(idx)
        end
        if r.ImGui_IsItemClicked(ctx, 1) then
          seq_open_track_context_menu(slot.id)
        end
        if sample_drag_active() and r.ImGui_IsItemHovered(ctx)
            and not seq_candidate_drag_from_slot(slot) then
          row_drop_hovered = true
        end
        if r.ImGui_IsItemHovered(ctx) and r.ImGui_SetTooltip then
          local linked_name = get_reaper_track_display_name(slot.reaper_track_guid)
          local tip = slot.name
          if linked_name and linked_name ~= "" and linked_name ~= slot.name then
            tip = tip .. "\n" .. linked_name
          end
          if assigned_sample and assigned_sample.name then
            tip = tip .. "\n" .. assigned_sample.name
          end
          if has_override then
            tip = tip .. "\nRegion sample"
          end
          r.ImGui_SetTooltip(ctx, tip)
        end
      end

      local mix_changed, overlap_changed, mix_hovered = render_seq_track_mix_controls(dl, slot, layout)
      if mix_hovered and not seq_candidate_drag_from_slot(slot) then
        row_drop_hovered = true
      end
      if row_hovered and r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 1)
          and not seq_layout_hit(layout.mix_hit, mx, my)
          and mx < ctrl_x1 then
        seq_open_track_context_menu(slot.id)
      end
      if mix_changed then
        begin_seq_undo("Adjust sequencer mix")
        seq_undo_commit_on_release = true
        seq_on_slot_mix_changed(slot, { resync = overlap_changed })
      end

      r.ImGui_SetCursorScreenPos(ctx, ctrl_x1 + gap, row_y)
      r.ImGui_PushID(ctx, "seq_panel_nav_" .. slot.id)
      local nav = render_seq_track_sample_controls(slot, idx, {
        id_suffix = "panel_" .. slot.id,
        ctrl_size = ctrl_size,
        icon_size = icon_size,
        container_h = row_h,
        y0 = row_y,
        y1 = row_y + row_h,
      })
      r.ImGui_PopID(ctx)
      if nav.row_drop_hovered then
        row_drop_hovered = true
      end

      r.ImGui_SetCursorScreenPos(ctx, row_x, row_y + row_h)

      if sample_drag_active() and row_hovered and not seq_drag_is_from_candidate() then
        row_drop_hovered = true
      end
      local play_anim = get_seq_track_play_anim(slot.id, r.time_precise())
      if play_anim then
        draw_seq_track_play_row_fx(dl, row_x, row_y, row_x + avail_w, row_y + row_h, play_anim.t, assigned_sample)
      end
      local cand_drop = state.seq_candidate_drop ~= nil
      local drum_drop = state.seq_drum_drop ~= nil
      if sample_drag_active() and row_drop_hovered and not cand_drop and not drum_drop
          and not seq_drag_is_from_candidate() then
        state.seq_drop_target_idx = idx
        state.seq_timeline_drop_time = nil
        state.seq_timeline_drop_track_idx = nil
        draw_drop_target_highlight(dl, row_x, row_y, row_x + avail_w, row_y + row_h, 4)
      end

      r.ImGui_Dummy(ctx, 0, 2)
      r.ImGui_PopID(ctx)
    end
  end

  r.ImGui_Dummy(ctx, 0, add_row_gap)
  render_seq_add_track_full_width_button("seq_add_track_popup_open", add_row_h)
  render_seq_add_track_popup()
  render_seq_track_context_menu()

  if render_seq_midi_assign_popup() then
    save_config()
    if save_seq_project_state then
      save_seq_project_state()
    end
  end

  if seq_undo_commit_on_release and r.ImGui_IsMouseReleased
      and (r.ImGui_IsMouseReleased(ctx, 0) or r.ImGui_IsMouseReleased(ctx, 1)) then
    if seq_undo_is_open() then
      end_seq_undo()
    end
    seq_undo_commit_on_release = false
  end

  if sample_drag_active() and (state.seq_drop_target_idx or state.seq_candidate_drop or state.seq_drum_drop) then
    r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
  end
end

function get_arrange_view_range()
  if r.GetSet_ArrangeView2 then
    local a, b, c, d = r.GetSet_ArrangeView2(0, false, 0, 0, 0, 0)
    local start_time = nil
    local end_time = nil
    if type(a) == "number" and type(b) == "number" then
      start_time, end_time = a, b
    elseif type(c) == "number" and type(d) == "number" then
      start_time, end_time = c, d
    end
    if start_time and end_time and end_time > start_time then
      return start_time, end_time
    end
  end
  local cursor = r.GetCursorPosition()
  return math.max(0.0, cursor - 4.0), cursor + 12.0
end

function set_arrange_view_range(start_time, end_time)
  if not r.GetSet_ArrangeView2 or type(start_time) ~= "number" or type(end_time) ~= "number" then
    return false
  end
  if end_time <= start_time then
    return false
  end
  r.GetSet_ArrangeView2(0, true, 0, 0, start_time, end_time)
  return true
end

function seq_push_view_to_arrange()
  local start_qn = state.seq_view_start_qn
  local span_qn = state.seq_view_span_qn
  if type(start_qn) ~= "number" or type(span_qn) ~= "number" or span_qn <= 0 then
    return false
  end
  local t0 = qn_to_time(start_qn)
  local t1 = qn_to_time(start_qn + span_qn)
  if not t0 or not t1 or t1 <= t0 then
    return false
  end
  return set_arrange_view_range(t0, t1)
end

function get_project_grid_step_qn()
  local step_qn = 0.25
  if r.GetSetProjectGrid then
    local _, div = r.GetSetProjectGrid(0, false)
    if type(div) == "number" and div > 0.000001 then
      step_qn = math.abs(div)
    end
  end
  return step_qn
end

function time_to_qn(time_pos)
  if r.TimeMap2_timeToQN then
    return r.TimeMap2_timeToQN(0, time_pos)
  elseif r.TimeMap_timeToQN then
    return r.TimeMap_timeToQN(time_pos)
  end
  return nil
end

function qn_to_time(qn)
  if r.TimeMap2_QNToTime then
    return r.TimeMap2_QNToTime(0, qn)
  elseif r.TimeMap_QNToTime then
    return r.TimeMap_QNToTime(qn)
  end
  return nil
end

function get_visible_qn_grid_range(qn_start_raw, qn_end_raw)
  local step_qn = (type(state.seq_grid_qn) == "number" and state.seq_grid_qn > 0) and state.seq_grid_qn or get_project_grid_step_qn()
  qn_start_raw = qn_start_raw or 0.0
  qn_end_raw = qn_end_raw or (qn_start_raw + step_qn * 16.0)
  if qn_end_raw <= qn_start_raw then
    qn_end_raw = qn_start_raw + step_qn * 16.0
  end

  local start_qn = math.floor((qn_start_raw / step_qn) + 1e-9) * step_qn
  local end_qn = math.ceil((qn_end_raw / step_qn) - 1e-9) * step_qn
  if end_qn <= start_qn then
    end_qn = start_qn + step_qn
  end

  local step_count = math.max(1, math.floor(((end_qn - start_qn) / step_qn) + 0.5))
  local max_steps = 768
  if step_count > max_steps then
    local mult = math.ceil(step_count / max_steps)
    step_qn = step_qn * mult
    start_qn = math.floor((qn_start_raw / step_qn) + 1e-9) * step_qn
    end_qn = math.ceil((qn_end_raw / step_qn) - 1e-9) * step_qn
    if end_qn <= start_qn then
      end_qn = start_qn + step_qn
    end
    step_count = math.max(1, math.floor(((end_qn - start_qn) / step_qn) + 0.5))
  end

  return start_qn, end_qn, step_qn, step_count
end

function get_seq_slot_target_track(slot)
  if not slot then
    return nil
  end
  if slot.reaper_track_guid then
    local tr = get_track_by_guid(slot.reaper_track_guid)
    if tr then
      return tr
    end
  end
  local tr = r.GetSelectedTrack(0, 0)
  if tr then
    return tr
  end
  if r.CountTracks(0) > 0 then
    return r.GetTrack(0, 0)
  end
  return nil
end

function collect_seq_item_cells(start_qn, end_qn, step_qn, step_count)
  local occupied_any = {}
  local occupied_match = {}

  for idx, slot in ipairs(state.seq_tracks) do
    occupied_any[idx] = {}
    occupied_match[idx] = {}

    local tr = get_seq_slot_target_track(slot)
    if tr then
      local item_count = r.CountTrackMediaItems(tr)
      local expected_path = nil
      if slot.sample_path and slot.sample_path ~= "" then
        expected_path = normalize_path(slot.sample_path)
      end

      for item_idx = 0, item_count - 1 do
        local item = r.GetTrackMediaItem(tr, item_idx)
        if item then
          local item_time = r.GetMediaItemInfo_Value(item, "D_POSITION")
          local item_qn = time_to_qn(item_time)
          if item_qn then
            local col = math.floor(((item_qn - start_qn) / step_qn) + 0.5)
            if col >= 0 and col < step_count then
              occupied_any[idx][col] = true
              if not expected_path then
                occupied_match[idx][col] = true
              else
                local take = r.GetActiveTake(item)
                local src = take and r.GetMediaItemTake_Source(take) or nil
                if src and r.GetMediaSourceFileName then
                  local _, src_path = r.GetMediaSourceFileName(src, "")
                  if src_path and normalize_path(src_path) == expected_path then
                    occupied_match[idx][col] = true
                  end
                end
              end
            end
          end
        end
      end
    end
  end

  return occupied_any, occupied_match
end

function remove_seq_items_in_cell(slot, start_qn, step_qn, col)
  local tr = get_seq_slot_target_track(slot)
  if not tr then
    return 0
  end

  local removed = 0

  for item_idx = r.CountTrackMediaItems(tr) - 1, 0, -1 do
    local item = r.GetTrackMediaItem(tr, item_idx)
    if item then
      local item_time = r.GetMediaItemInfo_Value(item, "D_POSITION")
      local item_qn = time_to_qn(item_time)
      if item_qn then
        local item_col = math.floor(((item_qn - start_qn) / step_qn) + 0.5)
        if item_col == col then
          if r.DeleteTrackMediaItem(tr, item) then
            removed = removed + 1
          end
        end
      end
    end
  end

  if removed > 0 then
    r.UpdateArrange()
  end
  return removed
end

SEQ_EXT_FLAG = "P_EXT:SampleMapSeq"
SEQ_EXT_REGION = "P_EXT:SampleMapSeqRegion"
SEQ_EXT_PATTERN = "P_EXT:SampleMapSeqPattern"
SEQ_EXT_TRACK = "P_EXT:SampleMapSeqTrack"
SEQ_EXT_STEP = "P_EXT:SampleMapSeqStep"
SEQ_EXT_LAYER = "P_EXT:SampleMapSeqLayer"
SEQ_EXT_GHOST = "P_EXT:SampleMapSeqGhost"
SEQ_EXT_PARENT = "P_EXT:SampleMapSeqParent"
SEQ_EXT_POOL = "P_EXT:SampleMapSeqPool"

function get_item_ext(item, key)
  if not item or not r.GetSetMediaItemInfo_String then
    return nil
  end
  local ok, value = r.GetSetMediaItemInfo_String(item, key, "", false)
  if ok then
    return value
  end
  return nil
end

function set_item_ext(item, key, value)
  if item and r.GetSetMediaItemInfo_String then
    r.GetSetMediaItemInfo_String(item, key, tostring(value or ""), true)
  end
end

seq_arrange_overlay_ctx = nil
seq_arrange_overlay_hwnd = nil
seq_arrange_hl_bm = nil
seq_arrange_hl_bm_w = 0
seq_arrange_hl_bm_h = 0
seq_arrange_hl_hwnd = nil
seq_arrange_hl_linked = false
seq_arrange_hl_pending = nil

function seq_get_arrange_hwnd()
  if not r.GetMainHwnd then
    return nil
  end
  local main = r.GetMainHwnd()
  if not main then
    return nil
  end
  if r.JS_Window_FindChildByID then
    local hwnd = r.JS_Window_FindChildByID(main, 1000)
    if hwnd then
      return hwnd
    end
  end
  if r.JS_Window_FindChild then
    return r.JS_Window_FindChild(main, "trackview", true)
  end
  return nil
end

function seq_js_unpack4(a, b, c, d, e)
  if type(a) == "boolean" or a == nil then
    return b, c, d, e
  end
  return a, b, c, d
end

function seq_get_arrange_geometry()
  local hwnd = seq_get_arrange_hwnd()
  if not hwnd then
    return nil
  end
  local geo = { hwnd = hwnd, view_w = nil, view_h = nil, scroll_pos = 0, l = nil, t = nil, r = nil, b = nil }

  if r.JS_Window_GetClientSize then
    local w, h = seq_js_unpack4(r.JS_Window_GetClientSize(hwnd))
    if type(w) == "number" and type(h) == "number" then
      geo.view_w = math.abs(w)
      geo.view_h = math.abs(h)
    end
  end

  if r.JS_Window_GetScrollInfo then
    local pos, page = seq_js_unpack4(r.JS_Window_GetScrollInfo(hwnd, "v"))
    if type(pos) == "number" then
      geo.scroll_pos = pos
    end
    -- pageSize is the visible arrange height in the same space as I_TCPY
    if type(page) == "number" and page > 8 then
      geo.view_h = page
    end
  end

  if r.JS_Window_GetClientRect then
    local l, t, rgt, btm = seq_js_unpack4(r.JS_Window_GetClientRect(hwnd))
    if type(l) == "number" and type(t) == "number" and type(rgt) == "number" and type(btm) == "number" then
      geo.l, geo.t, geo.r, geo.b = l, t, rgt, btm
      if not geo.view_w then
        geo.view_w = math.abs(rgt - l)
      end
      if not geo.view_h then
        geo.view_h = math.abs(btm - t)
      end
    end
  end

  if not geo.view_h or geo.view_h <= 8 then
    return geo
  end
  return geo
end

function seq_arrange_imgui_rect(octx, geo)
  if not geo or not geo.l then
    return nil
  end
  local x0, y0 = seq_native_to_imgui(octx, geo.l, geo.t)
  local x1, y1 = seq_native_to_imgui(octx, geo.r, geo.b)
  if x1 < x0 then x0, x1 = x1, x0 end
  if y1 < y0 then y0, y1 = y1, y0 end
  if x1 - x0 < 4 or y1 - y0 < 4 then
    return nil
  end
  return x0, y0, x1, y1
end

function seq_find_hovered_arrange_items()
  local hover = state.seq_grid_hover
  if not hover or not hover.slot_id or not hover.note then
    return nil, nil
  end
  local slot = nil
  for _, s in ipairs(state.seq_tracks) do
    if s.id == hover.slot_id then
      slot = s
      break
    end
  end
  if not slot then
    return nil, nil
  end
  local tr = get_seq_slot_target_track(slot)
  if not tr then
    return nil, nil
  end
  local region_id = hover.region_id
  local step = tostring(hover.step_key or "")
  local track_key = tostring(slot.id)
  local items = {}
  local aux = {}
  for i = 0, r.CountTrackMediaItems(tr) - 1 do
    local item = r.GetTrackMediaItem(tr, i)
    if item and seq_item_is_owned(item, region_id)
        and tostring(get_item_ext(item, SEQ_EXT_TRACK) or "") == track_key
        and tostring(get_item_ext(item, SEQ_EXT_STEP) or "") == step then
      if seq_item_is_aux_piece(item) then
        aux[#aux + 1] = item
      else
        items[#items + 1] = item
      end
    end
  end
  if #items == 0 then
    items = aux
  end
  if #items == 0 then
    local t0, t1 = seq_hover_note_time_span()
    if t0 and t1 then
      for i = 0, r.CountTrackMediaItems(tr) - 1 do
        local item = r.GetTrackMediaItem(tr, i)
        if item and seq_item_is_owned(item, region_id) then
          local pos = r.GetMediaItemInfo_Value(item, "D_POSITION") or 0
          local len = r.GetMediaItemInfo_Value(item, "D_LENGTH") or 0
          if pos < t1 and (pos + len) > t0 then
            items[#items + 1] = item
          end
        end
      end
    end
  end
  if #items == 0 then
    return nil, tr
  end
  return items, tr
end

function seq_hover_note_time_span()
  local hover = state.seq_grid_hover
  if not hover or not hover.note then
    return nil
  end
  local region = hover.region_id and get_seq_region_by_id(hover.region_id) or nil
  local abs_qn = seq_note_visual_abs_qn(region, hover.note, hover.step_key)
  local t0 = qn_to_time(abs_qn)
  if type(t0) ~= "number" then
    return nil
  end
  local t1 = nil
  local len_qn = tonumber(hover.note.length_qn)
  if len_qn and len_qn > 0 then
    t1 = qn_to_time(abs_qn + len_qn)
  end
  if type(t1) ~= "number" or t1 <= t0 then
    local sample = resolve_seq_hovered_grid_sample and resolve_seq_hovered_grid_sample() or nil
    local dur = sample and (tonumber(sample.effective_duration) or tonumber(sample.duration)) or 0.25
    t1 = t0 + math.max(0.05, dur)
  end
  return t0, t1
end

function seq_scroll_track_vertically_into_view(track)
  if not track then
    return
  end
  local tcp_y = r.GetMediaTrackInfo_Value(track, "I_TCPY") or 0
  local tcp_h = r.GetMediaTrackInfo_Value(track, "I_TCPH") or 0
  if tcp_h <= 1 then
    tcp_h = r.GetMediaTrackInfo_Value(track, "I_WNDH") or 24
  end
  local pad = 16
  local geo = seq_get_arrange_geometry()
  local hwnd = geo and geo.hwnd
  local view_h = geo and geo.view_h
  local pos = geo and geo.scroll_pos or 0

  if hwnd and view_h and view_h > 8 and r.JS_Window_SetScrollPos then
    local top_ok = tcp_y >= pad
    local bot_ok = (tcp_y + tcp_h) <= (view_h - pad)
    if top_ok and bot_ok then
      return
    end
    local delta = 0
    if not top_ok then
      delta = tcp_y - pad
    else
      delta = (tcp_y + tcp_h) - (view_h - pad)
    end
    r.JS_Window_SetScrollPos(hwnd, "v", math.max(0, math.floor(pos + delta + 0.5)))
    seq_request_script_refocus(10)
    return
  end

  -- Fallback: REAPER's scroll-selected-tracks-into-view works in both directions.
  local out_of_view = tcp_y < 0 or (view_h and (tcp_y + tcp_h) > view_h)
  if not out_of_view and view_h then
    return
  end
  if not out_of_view and not view_h and tcp_y >= 0 then
    -- Without a known arrange height, still scroll when the track sits far below the top.
    if tcp_y < 240 then
      return
    end
  end
  local sel = {}
  local n = r.CountTracks(0)
  for i = 0, n - 1 do
    local tr = r.GetTrack(0, i)
    sel[i] = r.IsTrackSelected(tr)
  end
  if r.PreventUIRefresh then r.PreventUIRefresh(1) end
  r.SetOnlyTrackSelected(track)
  r.Main_OnCommand(40913, 0)
  for i = 0, n - 1 do
    r.SetTrackSelected(r.GetTrack(0, i), sel[i] and true or false)
  end
  if r.PreventUIRefresh then r.PreventUIRefresh(-1) end
  seq_request_script_refocus(10)
end

function seq_item_imgui_rect(octx, item, track, ar_x0, ar_y0, ar_x1, ar_y1, t0, t1)
  if not item or not track or not t0 or not t1 or t1 <= t0 then
    return nil
  end
  local pos = r.GetMediaItemInfo_Value(item, "D_POSITION") or 0
  local len = r.GetMediaItemInfo_Value(item, "D_LENGTH") or 0
  local ar_w = ar_x1 - ar_x0
  local x0 = ar_x0 + ((pos - t0) / (t1 - t0)) * ar_w
  local x1 = ar_x0 + ((pos + len - t0) / (t1 - t0)) * ar_w
  local tcp_y = r.GetMediaTrackInfo_Value(track, "I_TCPY") or 0
  local tcp_h = r.GetMediaTrackInfo_Value(track, "I_TCPH") or 0
  if tcp_h <= 1 then
    tcp_h = r.GetMediaTrackInfo_Value(track, "I_WNDH") or 24
  end
  local last_y = r.GetMediaItemInfo_Value(item, "I_LASTY") or 0
  local last_h = r.GetMediaItemInfo_Value(item, "I_LASTH") or 0
  if last_h <= 1 then
    last_h = tcp_h
  end
  local y0 = ar_y0 + tcp_y + last_y
  local y1 = y0 + last_h
  x0 = math.max(ar_x0, x0)
  x1 = math.min(ar_x1, x1)
  y0 = math.max(ar_y0, y0)
  y1 = math.min(ar_y1, y1)
  if x1 - x0 < 2 or y1 - y0 < 2 then
    return nil
  end
  return x0, y0, x1, y1
end

function seq_union_item_imgui_rect(octx, items, track, ar_x0, ar_y0, ar_x1, ar_y1, t0, t1)
  local ux0, uy0, ux1, uy1 = nil, nil, nil, nil
  if items then
    for i = 1, #items do
      local x0, y0, x1, y1 = seq_item_imgui_rect(octx, items[i], track, ar_x0, ar_y0, ar_x1, ar_y1, t0, t1)
      if x0 then
        ux0 = ux0 and math.min(ux0, x0) or x0
        uy0 = uy0 and math.min(uy0, y0) or y0
        ux1 = ux1 and math.max(ux1, x1) or x1
        uy1 = uy1 and math.max(uy1, y1) or y1
      end
    end
  end
  if ux0 then
    return ux0, uy0, ux1, uy1
  end
  -- No tagged item: still highlight the track lane at the hovered note's time.
  local nt0, nt1 = seq_hover_note_time_span()
  if not nt0 or not track then
    return nil
  end
  local tcp_y = r.GetMediaTrackInfo_Value(track, "I_TCPY") or 0
  local tcp_h = r.GetMediaTrackInfo_Value(track, "I_TCPH") or 0
  if tcp_h <= 1 then
    tcp_h = r.GetMediaTrackInfo_Value(track, "I_WNDH") or 24
  end
  local span = t1 - t0
  if span <= 0 then
    return nil
  end
  local x0 = ar_x0 + ((nt0 - t0) / span) * (ar_x1 - ar_x0)
  local x1 = ar_x0 + ((nt1 - t0) / span) * (ar_x1 - ar_x0)
  local y0 = ar_y0 + tcp_y
  local y1 = y0 + tcp_h
  x0 = math.max(ar_x0, x0)
  x1 = math.min(ar_x1, x1)
  y0 = math.max(ar_y0, y0)
  y1 = math.min(ar_y1, y1)
  if x1 - x0 < 2 or y1 - y0 < 2 then
    return nil
  end
  return x0, y0, x1, y1
end

function seq_native_to_imgui(octx, x, y)
  if r.ImGui_PointConvertNative then
    local nx, ny = r.ImGui_PointConvertNative(octx, x, y)
    if type(nx) == "number" and type(ny) == "number" then
      return nx, ny
    end
  end
  return x, y
end

function seq_get_script_hwnd()
  if r.ImGui_GetNativeHwnd and ctx and r.ImGui_ValidatePtr(ctx, "ImGui_Context*") then
    local hwnd = r.ImGui_GetNativeHwnd(ctx)
    if hwnd then
      return hwnd
    end
  end
  if r.JS_Window_Find then
    return r.JS_Window_Find(SCRIPT_NAME, true)
  end
  return nil
end

function seq_focus_is_overlay(focused)
  if not focused then
    return false
  end
  if seq_arrange_overlay_hwnd then
    if focused == seq_arrange_overlay_hwnd then
      return true
    end
    if r.JS_Window_IsChild and r.JS_Window_IsChild(seq_arrange_overlay_hwnd, focused) then
      return true
    end
  end
  if r.JS_Window_GetTitle then
    local title = r.JS_Window_GetTitle(focused)
    if title == "Sample Map Item Highlight" or title == "Sample Map Link Highlight" then
      return true
    end
  end
  return false
end

function seq_focus_is_arrange(focused)
  if not focused then
    return false
  end
  local arrange = seq_get_arrange_hwnd and seq_get_arrange_hwnd() or nil
  if arrange then
    if focused == arrange then
      return true
    end
    if r.JS_Window_IsChild and r.JS_Window_IsChild(arrange, focused) then
      return true
    end
  end
  local main = r.GetMainHwnd and r.GetMainHwnd() or nil
  if main and focused == main then
    return true
  end
  return false
end

function seq_hwnd_is_reaper(hwnd)
  if not hwnd then
    return false
  end
  if seq_focus_is_overlay(hwnd) or seq_focus_is_arrange(hwnd) then
    return true
  end
  local main = r.GetMainHwnd and r.GetMainHwnd() or nil
  local script = seq_get_script_hwnd()
  local h = hwnd
  local guard = 0
  while h and guard < 24 do
    if h == main or h == script then
      return true
    end
    h = r.JS_Window_GetParent and r.JS_Window_GetParent(h) or nil
    guard = guard + 1
  end
  return false
end

function seq_reaper_is_active()
  if not r.JS_Window_GetForeground then
    return true
  end
  -- On macOS GetForeground often stays on a REAPER window even when another
  -- app is in front. Arrange highlights are painted into the arrange itself.
  return seq_hwnd_is_reaper(r.JS_Window_GetForeground())
end

function seq_mouse_over_reaper()
  if r.JS_Window_FromPoint and r.GetMousePosition then
    local x, y = r.GetMousePosition()
    local hwnd = r.JS_Window_FromPoint(x, y)
    if hwnd and seq_focus_is_overlay(hwnd) then
      return true
    end
    if hwnd then
      return seq_hwnd_is_reaper(hwnd)
    end
    return false
  end
  return seq_reaper_is_active()
end

seq_script_refocus_frames = 0

function seq_restore_script_keyboard_focus(force)
  if not r.JS_Window_SetFocus then
    return
  end
  local script = seq_get_script_hwnd()
  if not script then
    return
  end
  local focused = r.JS_Window_GetFocus and r.JS_Window_GetFocus() or nil
  if focused == script then
    return
  end
  if focused and r.JS_Window_IsChild and r.JS_Window_IsChild(script, focused) then
    return
  end
  if not force and focused and not seq_focus_is_overlay(focused) and not seq_focus_is_arrange(focused) then
    return
  end
  if r.JS_Window_SetForeground then
    r.JS_Window_SetForeground(script)
  end
  r.JS_Window_SetFocus(script)
end

function seq_request_script_refocus(frames)
  seq_script_refocus_frames = math.max(seq_script_refocus_frames or 0, tonumber(frames) or 8)
  seq_restore_script_keyboard_focus(true)
end

function seq_pump_script_refocus()
  if (seq_script_refocus_frames or 0) <= 0 then
    return
  end
  seq_restore_script_keyboard_focus(true)
  seq_script_refocus_frames = seq_script_refocus_frames - 1
end

function seq_lice_color(rr, gg, bb)
  return (0xFF << 24) | ((rr & 0xFF) << 16) | ((gg & 0xFF) << 8) | (bb & 0xFF)
end

function seq_destroy_stale_overlay_windows()
  if not r.JS_Window_Find then
    return
  end
  for _, title in ipairs({ "Sample Map Item Highlight", "Sample Map Link Highlight" }) do
    local hwnd = r.JS_Window_Find(title, true)
    if hwnd then
      if r.JS_Window_Show then
        pcall(r.JS_Window_Show, hwnd, "HIDE")
      end
      if r.JS_Window_Move then
        pcall(r.JS_Window_Move, hwnd, -8000, -8000)
      end
    end
  end
end

function seq_arrange_hl_unlink()
  if seq_arrange_hl_linked and seq_arrange_hl_hwnd and seq_arrange_hl_bm and r.JS_Composite_Unlink then
    pcall(r.JS_Composite_Unlink, seq_arrange_hl_hwnd, seq_arrange_hl_bm, true)
  end
  seq_arrange_hl_linked = false
end

function seq_destroy_arrange_overlay_ctx()
  seq_arrange_hl_unlink()
  if seq_arrange_hl_bm and r.JS_LICE_DestroyBitmap then
    pcall(r.JS_LICE_DestroyBitmap, seq_arrange_hl_bm)
  end
  seq_arrange_hl_bm = nil
  seq_arrange_hl_bm_w = 0
  seq_arrange_hl_bm_h = 0
  seq_arrange_hl_hwnd = nil
  seq_arrange_hl_pending = nil
  if seq_arrange_overlay_ctx and r.ImGui_ValidatePtr(seq_arrange_overlay_ctx, "ImGui_Context*") then
    if r.APIExists("ImGui_DestroyContext") then
      pcall(r.ImGui_DestroyContext, seq_arrange_overlay_ctx)
    end
  end
  seq_arrange_overlay_ctx = nil
  seq_arrange_overlay_hwnd = nil
  seq_destroy_stale_overlay_windows()
end

function seq_arrange_hl_reset()
  seq_arrange_hl_pending = {}
end

function seq_arrange_hl_add(x0, y0, x1, y1, fill_rgb, fill_a, edge_rgb)
  if not seq_arrange_hl_pending then
    seq_arrange_hl_pending = {}
  end
  seq_arrange_hl_pending[#seq_arrange_hl_pending + 1] = {
    x0 = x0, y0 = y0, x1 = x1, y1 = y1,
    fill_rgb = fill_rgb, fill_a = fill_a, edge_rgb = edge_rgb
  }
end

function seq_arrange_hl_draw_rect(bm, rect)
  local x = math.floor(rect.x0 + 0.5)
  local y = math.floor(rect.y0 + 0.5)
  local w = math.floor(rect.x1 - rect.x0 + 0.5)
  local h = math.floor(rect.y1 - rect.y0 + 0.5)
  if w < 2 or h < 2 then
    return
  end
  if r.JS_LICE_FillRect then
    r.JS_LICE_FillRect(bm, x, y, w, h, rect.fill_rgb, rect.fill_a or 0.3, "COPY")
  end
  if r.JS_LICE_RoundRect then
    pcall(r.JS_LICE_RoundRect, bm, x, y, w - 1, h - 1, 3, rect.edge_rgb, 1.0, "COPY", true)
  elseif r.JS_LICE_Line then
    local x2, y2 = x + w - 1, y + h - 1
    r.JS_LICE_Line(bm, x, y, x2, y, rect.edge_rgb, 1.0, "COPY", true)
    r.JS_LICE_Line(bm, x2, y, x2, y2, rect.edge_rgb, 1.0, "COPY", true)
    r.JS_LICE_Line(bm, x2, y2, x, y2, rect.edge_rgb, 1.0, "COPY", true)
    r.JS_LICE_Line(bm, x, y2, x, y, rect.edge_rgb, 1.0, "COPY", true)
  end
end

function seq_arrange_hl_flush()
  local pending = seq_arrange_hl_pending
  seq_arrange_hl_pending = nil
  if not pending or #pending == 0 then
    seq_arrange_hl_unlink()
    return
  end
  if not (r.JS_LICE_CreateBitmap and r.JS_LICE_Clear and r.JS_Composite) then
    seq_arrange_hl_unlink()
    return
  end
  local hwnd = seq_get_arrange_hwnd()
  local geo = seq_get_arrange_geometry()
  if not hwnd or not geo or not geo.view_w or not geo.view_h then
    seq_arrange_hl_unlink()
    return
  end
  local w = math.max(1, math.floor((geo.view_w or 0) + 0.5))
  local h = math.max(1, math.floor((geo.view_h or 0) + 0.5))
  if seq_arrange_hl_hwnd and seq_arrange_hl_hwnd ~= hwnd then
    seq_arrange_hl_unlink()
  end
  if seq_arrange_hl_bm and (seq_arrange_hl_bm_w ~= w or seq_arrange_hl_bm_h ~= h) then
    seq_arrange_hl_unlink()
    if r.JS_LICE_Resize then
      r.JS_LICE_Resize(seq_arrange_hl_bm, w, h)
      seq_arrange_hl_bm_w = w
      seq_arrange_hl_bm_h = h
    else
      pcall(r.JS_LICE_DestroyBitmap, seq_arrange_hl_bm)
      seq_arrange_hl_bm = nil
    end
  end
  if not seq_arrange_hl_bm then
    seq_arrange_hl_bm = r.JS_LICE_CreateBitmap(true, w, h)
    seq_arrange_hl_bm_w = w
    seq_arrange_hl_bm_h = h
  end
  if not seq_arrange_hl_bm then
    return
  end
  r.JS_LICE_Clear(seq_arrange_hl_bm, 0)
  for i = 1, #pending do
    seq_arrange_hl_draw_rect(seq_arrange_hl_bm, pending[i])
  end
  seq_arrange_hl_hwnd = hwnd
  r.JS_Composite(hwnd, 0, 0, w, h, seq_arrange_hl_bm, 0, 0, w, h, true)
  seq_arrange_hl_linked = true
end

function seq_update_arrange_item_follow()
  if not state.seq_follow_hovered_item then
    return nil
  end
  if state.active_view ~= "sequencer" and not state.sequencer_floating then
    return nil
  end
  if state.seq_note_drag or state.seq_param_drag or state.seq_region_drag or state.seq_razor_drag or state.seq_lane_h_drag or state.seq_track_reorder_drag then
    return nil
  end
  local items, track = seq_find_hovered_arrange_items()
  if not track then
    return nil
  end
  seq_scroll_track_vertically_into_view(track)
  return items, track
end

function seq_render_arrange_item_overlay()
  if not seq_arrange_hl_killed_stale then
    seq_arrange_hl_killed_stale = true
    seq_destroy_stale_overlay_windows()
  end
  seq_arrange_hl_reset()
  if not state.seq_follow_hovered_item or not sequencer_is_open()
      or state.seq_note_drag or state.seq_param_drag or state.seq_region_drag or state.seq_razor_drag or state.seq_lane_h_drag or state.seq_track_reorder_drag then
    return
  end
  local items, track = seq_find_hovered_arrange_items()
  if not track then
    return
  end
  local geo = seq_get_arrange_geometry()
  if not geo or not geo.view_w or not geo.view_h then
    return
  end
  local t0, t1 = get_arrange_view_range()
  local x0, y0, x1, y1 = seq_union_item_imgui_rect(nil, items, track, 0, 0, geo.view_w, geo.view_h, t0, t1)
  if not x0 then
    return
  end
  seq_arrange_hl_add(x0, y0, x1, y1, seq_lice_color(255, 255, 136), 0.16, seq_lice_color(255, 255, 136))
end

function seq_render_link_parent_overlay()
  if not sequencer_is_open() then
    state.seq_link_hover_region_id = nil
    seq_arrange_hl_flush()
    return
  end
  local hover = get_seq_region_by_id(state.seq_link_hover_region_id)
  if hover and seq_region_is_linked(hover) then
    local geo = seq_get_arrange_geometry()
    local t0, t1 = get_arrange_view_range()
    if geo and geo.view_w and geo.view_h and t0 and t1 then
      for _, reg in ipairs(state.seq_regions or {}) do
        if seq_region_in_link_group(reg, hover) and reg.parent_item_guid then
          local item = seq_find_item_by_guid(reg.parent_item_guid)
          local track = item and r.GetMediaItemTrack and r.GetMediaItemTrack(item)
          if item and track then
            local x0, y0, x1, y1 = seq_item_imgui_rect(nil, item, track, 0, 0, geo.view_w, geo.view_h, t0, t1)
            if x0 then
              seq_arrange_hl_add(x0, y0, x1, y1, seq_lice_color(255, 229, 153), 0.33, seq_lice_color(255, 229, 153))
            end
          end
        end
      end
    end
  end
  seq_arrange_hl_flush()
end

-- Internal sequencer undo/redo. REAPER's undo cannot restore Lua sequencer
-- state (ProjExtState is not in the undo history), so Sample Map keeps its
-- own snapshot stack. Ctrl/Cmd+Z and Ctrl/Cmd+Shift+Z drive it.
SEQ_UNDO_MAX = 80
seq_undo_stack = {}
seq_redo_stack = {}
seq_undo_session = nil
seq_undo_applying = false
seq_undo_commit_on_release = false

function seq_undo_is_open()
  return seq_undo_session ~= nil
end

function seq_undo_clear_history()
  seq_undo_stack = {}
  seq_redo_stack = {}
  seq_undo_session = nil
  seq_undo_applying = false
  seq_undo_commit_on_release = false
end

function seq_undo_values_equal(a, b)
  if a == b then
    return true
  end
  if type(a) ~= type(b) then
    return false
  end
  if type(a) ~= "table" then
    if type(a) == "number" and type(b) == "number" then
      if a ~= a or b ~= b then
        return a ~= a and b ~= b
      end
      return math.abs(a - b) < 0.000000001
    end
    return a == b
  end
  for k, v in pairs(a) do
    if not seq_undo_values_equal(v, b[k]) then
      return false
    end
  end
  for k, v in pairs(b) do
    if a[k] == nil and v ~= nil then
      return false
    end
  end
  return true
end

function capture_seq_document_snapshot()
  return {
    seq_tracks = clone_table_deep(state.seq_tracks),
    selected_seq_track = state.selected_seq_track,
    seq_track_next_id = state.seq_track_next_id,
    seq_regions = clone_table_deep(state.seq_regions),
    seq_patterns = clone_table_deep(state.seq_patterns),
    seq_region_next_id = state.seq_region_next_id,
    seq_pattern_next_id = state.seq_pattern_next_id,
    seq_pool_next_id = state.seq_pool_next_id,
    selected_seq_region_id = state.selected_seq_region_id,
    seq_kit_history = clone_table_deep(state.seq_kit_history),
    seq_kit_history_next_id = state.seq_kit_history_next_id,
    seq_razors = clone_table_deep(state.seq_razors) or {},
  }
end

function restore_seq_document_snapshot(snap)
  if type(snap) ~= "table" then
    return
  end
  -- Clone field-by-field so later edits cannot mutate the stacked snapshot.
  state.seq_tracks = clone_table_deep(snap.seq_tracks) or {}
  state.selected_seq_track = snap.selected_seq_track
  state.seq_track_next_id = snap.seq_track_next_id or 1
  state.seq_regions = clone_table_deep(snap.seq_regions) or {}
  state.seq_patterns = clone_table_deep(snap.seq_patterns) or {}
  state.seq_region_next_id = snap.seq_region_next_id or 1
  state.seq_pattern_next_id = snap.seq_pattern_next_id or 1
  state.seq_pool_next_id = snap.seq_pool_next_id or 1
  state.selected_seq_region_id = snap.selected_seq_region_id
  state.seq_kit_history = clone_table_deep(snap.seq_kit_history) or {}
  state.seq_kit_history_next_id = snap.seq_kit_history_next_id or 1
  state.seq_razors = clone_table_deep(snap.seq_razors) or {}
  state.selected_seq_note = nil
  state.seq_note_drag = nil
  state.seq_param_drag = nil
  state.seq_region_drag = nil
  state.seq_region_rename = nil
  state.seq_vary_filter_edit = nil
  state.seq_rect_drag = nil
  state.seq_random_knob_drag = nil
  state.seq_random_sync_pending = nil
  state.seq_random_sync_run = false
  state.seq_env_graph_drag = nil
  state.seq_razor_drag = nil
  state.seq_track_reorder_drag = nil
  seq_undo_commit_on_release = false
  if seq_normalize_slot_mix then
    for _, slot in ipairs(state.seq_tracks) do
      seq_normalize_slot_mix(slot)
    end
  end
end

function seq_undo_index_by_id(list)
  local by_id = {}
  if type(list) ~= "table" then
    return by_id
  end
  for _, entry in ipairs(list) do
    if type(entry) == "table" and entry.id then
      by_id[entry.id] = entry
    end
  end
  return by_id
end

function seq_undo_track_needs_item_resync(a, b)
  if not a or not b then
    return true
  end
  if a.sample_path ~= b.sample_path or a.reaper_track_guid ~= b.reaper_track_guid then
    return true
  end
  if (a.overlap and true or false) ~= (b.overlap and true or false) then
    return true
  end
  return not seq_undo_values_equal(a.env, b.env)
end

function seq_undo_track_needs_mix(a, b)
  if not a or not b then
    return true
  end
  if math.abs((a.volume or 1.0) - (b.volume or 1.0)) > 0.000000001 then
    return true
  end
  if math.abs((a.pan or 0.0) - (b.pan or 0.0)) > 0.000000001 then
    return true
  end
  if (a.mute and true or false) ~= (b.mute and true or false) then
    return true
  end
  if (a.solo and true or false) ~= (b.solo and true or false) then
    return true
  end
  return false
end

-- Compare live sequencer state to a snapshot and return the cheapest arrange update.
-- full: rebuild every region. Otherwise delete items for remove_ids and recreate sync_ids.
function seq_undo_plan_resync(from_state, to_snap)
  local remove_ids = {}
  local sync_ids = {}
  local mix = false
  if type(from_state) ~= "table" or type(to_snap) ~= "table" then
    return remove_ids, sync_ids, true, true
  end

  local from_tracks = seq_undo_index_by_id(from_state.seq_tracks)
  local to_tracks = seq_undo_index_by_id(to_snap.seq_tracks)
  for id, from_slot in pairs(from_tracks) do
    local to_slot = to_tracks[id]
    if not to_slot or seq_undo_track_needs_item_resync(from_slot, to_slot) then
      return remove_ids, sync_ids, true, true
    end
    if seq_undo_track_needs_mix(from_slot, to_slot) then
      mix = true
    end
  end
  for id, _ in pairs(to_tracks) do
    if not from_tracks[id] then
      return remove_ids, sync_ids, true, true
    end
  end

  local from_regs = seq_undo_index_by_id(from_state.seq_regions)
  local to_regs = seq_undo_index_by_id(to_snap.seq_regions)
  local changed_patterns = {}
  local function consider_pattern(pid)
    if not pid or changed_patterns[pid] then
      return
    end
    local key = tostring(pid)
    local from_pat = from_state.seq_patterns and from_state.seq_patterns[key]
    local to_pat = to_snap.seq_patterns and to_snap.seq_patterns[key]
    if not seq_undo_values_equal(from_pat, to_pat) then
      changed_patterns[pid] = true
    end
  end
  for _, reg in ipairs(from_state.seq_regions or {}) do
    consider_pattern(reg.pattern_id)
  end
  for _, reg in ipairs(to_snap.seq_regions or {}) do
    consider_pattern(reg.pattern_id)
  end

  for id, _ in pairs(from_regs) do
    if not to_regs[id] then
      remove_ids[id] = true
    end
  end
  for id, to_reg in pairs(to_regs) do
    local from_reg = from_regs[id]
    if not from_reg then
      sync_ids[id] = true
    elseif math.abs((from_reg.start_qn or 0) - (to_reg.start_qn or 0)) > 0.000000001
        or from_reg.length_bars ~= to_reg.length_bars
        or from_reg.pattern_id ~= to_reg.pattern_id
        or from_reg.pool_id ~= to_reg.pool_id
        or changed_patterns[to_reg.pattern_id] then
      remove_ids[id] = true
      sync_ids[id] = true
    end
  end
  return remove_ids, sync_ids, mix, false
end

function seq_undo_set_has_ids(id_set)
  if type(id_set) ~= "table" then
    return false
  end
  for _ in pairs(id_set) do
    return true
  end
  return false
end

function seq_undo_begin_reaper()
  if r.Undo_BeginBlock2 then
    r.Undo_BeginBlock2(0)
  elseif r.Undo_BeginBlock then
    r.Undo_BeginBlock()
  end
end

function seq_undo_end_reaper(label)
  if r.Undo_EndBlock2 then
    r.Undo_EndBlock2(0, label or "Sample Map Sequencer edit", -1)
  elseif r.Undo_EndBlock then
    r.Undo_EndBlock(label or "Sample Map Sequencer edit", -1)
  end
end

function apply_seq_undo_snapshot(snap, label)
  if type(snap) ~= "table" then
    return
  end
  local remove_ids, sync_ids, mix, full = seq_undo_plan_resync(state, snap)
  seq_undo_applying = true
  restore_seq_document_snapshot(snap)
  seq_undo_begin_reaper()
  if r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  if seq_ensure_slot_reaper_tracks then
    seq_ensure_slot_reaper_tracks()
  end
  if full then
    if remove_seq_rendered_items then
      remove_seq_rendered_items(nil)
    end
    if seq_resync_all_regions then
      seq_resync_all_regions({ skip_remove = true, skip_arrange = true, skip_mix = true })
    end
    mix = true
  else
    if seq_undo_set_has_ids(remove_ids) and remove_seq_rendered_items_by_ids then
      remove_seq_rendered_items_by_ids(remove_ids)
    end
    if seq_undo_set_has_ids(sync_ids) then
      if clear_seq_vary_rank_cache then
        clear_seq_vary_rank_cache()
      end
      for _, region in ipairs(state.seq_regions or {}) do
        if sync_ids[region.id] then
          sync_seq_region(region, {
            skip_remove = true,
            skip_mix = true,
            skip_arrange = true,
            skip_cache_clear = true,
          })
        end
      end
    end
  end
  if mix and seq_apply_all_slot_mix_to_reaper then
    seq_apply_all_slot_mix_to_reaper()
  end
  if seq_apply_seq_order_to_arrange then
    seq_apply_seq_order_to_arrange()
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  r.UpdateArrange()
  seq_undo_end_reaper(label or "Sample Map undo")
  if save_seq_project_state then
    save_seq_project_state()
  end
  if seq_mark_self_arrange_write then
    seq_mark_self_arrange_write()
  end
  if r.GetProjectStateChangeCount then
    state.seq_last_proj_change = r.GetProjectStateChangeCount(0)
  end
  seq_undo_applying = false
end

function seq_undo_own_begin(label)
  if seq_undo_applying or seq_undo_is_open() then
    return false
  end
  begin_seq_undo(label)
  return true
end

function begin_seq_undo(label)
  label = label or "Sample Map Sequencer edit"
  if seq_undo_applying then
    return label
  end
  if seq_undo_session then
    return seq_undo_session.label or label
  end
  seq_undo_session = {
    label = label,
    before = capture_seq_document_snapshot(),
  }
  seq_undo_begin_reaper()
  return label
end

function end_seq_undo(label)
  if seq_undo_applying or not seq_undo_session then
    return
  end
  label = label or seq_undo_session.label or "Sample Map Sequencer edit"
  local before = seq_undo_session.before
  seq_undo_session = nil
  seq_undo_end_reaper(label)
  local after = capture_seq_document_snapshot()
  if seq_undo_values_equal(before, after) then
    return
  end
  seq_undo_stack[#seq_undo_stack + 1] = {
    label = label,
    before = before,
    after = after,
  }
  while #seq_undo_stack > SEQ_UNDO_MAX do
    table.remove(seq_undo_stack, 1)
  end
  seq_redo_stack = {}
end

function seq_undo()
  if seq_undo_applying or seq_undo_is_open() then
    return false
  end
  if state.seq_region_drag or state.seq_note_drag or state.seq_param_drag or state.seq_razor_drag or state.seq_lane_h_drag or state.seq_track_reorder_drag then
    return false
  end
  if #seq_undo_stack == 0 then
    return false
  end
  local entry = table.remove(seq_undo_stack)
  seq_redo_stack[#seq_redo_stack + 1] = entry
  apply_seq_undo_snapshot(entry.before, "Undo: " .. (entry.label or "Sample Map edit"))
  log("Undo: " .. (entry.label or "Sample Map edit"))
  return true
end

function seq_redo()
  if seq_undo_applying or seq_undo_is_open() then
    return false
  end
  if state.seq_region_drag or state.seq_note_drag or state.seq_param_drag or state.seq_razor_drag or state.seq_lane_h_drag or state.seq_track_reorder_drag then
    return false
  end
  if #seq_redo_stack == 0 then
    return false
  end
  local entry = table.remove(seq_redo_stack)
  seq_undo_stack[#seq_undo_stack + 1] = entry
  apply_seq_undo_snapshot(entry.after, "Redo: " .. (entry.label or "Sample Map edit"))
  log("Redo: " .. (entry.label or "Sample Map edit"))
  return true
end

function handle_seq_undo_keys()
  if imgui_text_input_active and imgui_text_input_active() then
    return false
  end
  local redo = shortcut_pressed("redo")
  local undo = shortcut_pressed("undo")
  if not redo and not undo then
    return false
  end
  if r.ImGui_SetNextFrameWantCaptureKeyboard then
    r.ImGui_SetNextFrameWantCaptureKeyboard(ctx, true)
  end
  if redo then
    seq_redo()
  else
    seq_undo()
  end
  return true
end

function alloc_seq_pattern()
  local id = state.seq_pattern_next_id
  state.seq_pattern_next_id = state.seq_pattern_next_id + 1
  state.seq_patterns[tostring(id)] = state.seq_patterns[tostring(id)] or { notes = {} }
  return id
end

function alloc_seq_pool()
  local id = state.seq_pool_next_id
  state.seq_pool_next_id = state.seq_pool_next_id + 1
  return id
end

function get_seq_pattern(pattern_id, create)
  if not pattern_id then
    return nil
  end
  local key = tostring(pattern_id)
  if not state.seq_patterns[key] and create then
    state.seq_patterns[key] = { notes = {} }
  end
  local pattern = state.seq_patterns[key]
  if pattern and type(pattern.notes) ~= "table" then
    pattern.notes = {}
  end
  return pattern
end

function get_seq_region_by_id(region_id)
  if not region_id then
    return nil
  end
  for _, region in ipairs(state.seq_regions) do
    if region.id == region_id then
      return region
    end
  end
  return nil
end

function get_seq_region_length_qn(region)
  if not region then
    return 16.0
  end
  local bars = math.max(1, math.floor(region.length_bars or 4))
  if r.TimeMap_GetMeasureInfo and r.TimeMap2_timeToBeats then
    local start_time = qn_to_time(region.start_qn or 0.0)
    if start_time then
      local _, measure = r.TimeMap2_timeToBeats(0, start_time)
      if measure then
        local _, qn_start = r.TimeMap_GetMeasureInfo(0, measure)
        local _, qn_end = r.TimeMap_GetMeasureInfo(0, measure + bars)
        if qn_start and qn_end and qn_end > qn_start then
          return qn_end - qn_start
        end
      end
    end
  end
  return bars * 4.0
end

function seq_region_max_step(region, grid_qn)
  grid_qn = grid_qn or state.seq_grid_qn or 0.25
  if not grid_qn or grid_qn <= 0 then
    grid_qn = 0.25
  end
  local length_qn = get_seq_region_length_qn(region)
  return math.max(0, math.floor((length_qn / grid_qn) - 1e-9))
end

function seq_step_in_region(region, step_idx, grid_qn)
  step_idx = tonumber(step_idx)
  if not step_idx or step_idx < 0 then
    return false
  end
  return step_idx <= seq_region_max_step(region, grid_qn)
end

-- Musical position is stored on the note (qn_offset) so grid changes never
-- re-index or hide hits that were painted on a finer grid.
function seq_note_qn_offset(note, step_key, grid_qn)
  if note and type(note.qn_offset) == "number" then
    return note.qn_offset
  end
  local step_idx = tonumber(step_key) or (note and tonumber(note.step)) or 0
  return step_idx * (grid_qn or state.seq_grid_qn or 0.25)
end

function seq_note_abs_qn(region, note, step_key, grid_qn)
  return (region and region.start_qn or 0.0) + seq_note_qn_offset(note, step_key, grid_qn)
end

function seq_note_visual_abs_qn(region, note, step_key, grid_qn)
  return seq_note_abs_qn(region, note, step_key, grid_qn) + ((note and note.offset_qn) or 0.0)
end

function seq_next_note_vis_qn_after(region, track_id, after_qn, grid_qn)
  local region_end = (region and region.start_qn or 0.0) + get_seq_region_length_qn(region)
  if not region or type(after_qn) ~= "number" then
    return region_end
  end
  local notes = get_track_note_table(get_seq_pattern(region.pattern_id, false), track_id, false)
  if not notes then
    return region_end
  end
  local next_qn = region_end
  for key, note in pairs(notes) do
    if type(note) == "table" and note.enabled ~= false then
      local vis = seq_note_visual_abs_qn(region, note, key, grid_qn)
      if vis > after_qn + 1e-9 and vis < next_qn then
        next_qn = vis
      end
    end
  end
  return next_qn
end

function seq_note_in_region(region, note, step_key, grid_qn)
  if not region then
    return false
  end
  local abs_qn = seq_note_abs_qn(region, note, step_key, grid_qn)
  local start = region.start_qn or 0.0
  local length = get_seq_region_length_qn(region)
  return abs_qn >= start - 1e-9 and abs_qn < start + length - 1e-9
end

function seq_storage_key_from_qn(qn_offset)
  return tostring(math.floor((qn_offset or 0.0) * 192.0 + 0.5))
end

function seq_quantize_free_qn(qn)
  return math.floor((qn or 0.0) * 192.0 + 0.5) / 192.0
end

function seq_find_note_key_at_qn(region, track_id, qn_offset, slop)
  slop = slop or 1e-4
  local notes = get_track_note_table(get_seq_pattern(region and region.pattern_id, false), track_id, false)
  if not notes or type(qn_offset) ~= "number" then
    return nil, nil
  end
  for key, note in pairs(notes) do
    if type(note) == "table" and math.abs(seq_note_qn_offset(note, key) - qn_offset) <= slop then
      return tostring(key), note
    end
  end
  return nil, nil
end

function seq_alloc_note_key(region, track_id, qn_offset)
  local found_key = seq_find_note_key_at_qn(region, track_id, qn_offset)
  if found_key then
    return found_key
  end
  local notes = get_track_note_table(get_seq_pattern(region and region.pattern_id, false), track_id, false)
  local base = seq_storage_key_from_qn(qn_offset)
  local key = base
  local n = 0
  while notes and notes[key] do
    n = n + 1
    key = base .. "_" .. tostring(n)
  end
  return key
end

function seq_active_cell_notes(active)
  if not active then
    return nil
  end
  return active.pack or { active }
end

function seq_for_each_active_note(active, fn)
  local pack = seq_active_cell_notes(active)
  if not pack then
    return
  end
  for i = 1, #pack do
    fn(pack[i])
  end
end

function seq_note_playable_head_span(note, abs_qn, step_qn)
  step_qn = step_qn or 0.25
  local vis = (abs_qn or 0.0) + ((note and note.offset_qn) or 0.0)
  local span = seq_stutter_span_qn(note, step_qn)
  local head = (type(span) == "number" and span > 1e-9) and span or step_qn
  return vis, vis + head
end

function seq_entry_vis_qn(entry)
  if not entry then
    return 0.0
  end
  return (entry.abs_qn or 0.0) + ((entry.note and entry.note.offset_qn) or 0.0)
end

function seq_pack_sort_later_on_top(pack)
  if type(pack) ~= "table" or #pack < 2 then
    return pack
  end
  table.sort(pack, function(a, b)
    local av, bv = seq_entry_vis_qn(a), seq_entry_vis_qn(b)
    if math.abs(av - bv) > 1e-9 then
      return av < bv
    end
    return tostring(a and a.key or "") < tostring(b and b.key or "")
  end)
  return pack
end

function seq_pick_packed_note(active, hovered_qn, start_qn, col, step_qn)
  local pack = seq_active_cell_notes(active)
  if not pack or #pack == 0 then
    return nil
  end
  step_qn = step_qn or 0.25
  local hover = hovered_qn
  if type(hover) ~= "number" then
    return pack[#pack]
  end
  local cell_qn = (start_qn or 0.0) + (col or 0) * step_qn
  local cell_end = cell_qn + step_qn
  local top, top_vis = nil, -math.huge
  for i = 1, #pack do
    local entry = pack[i]
    if type(entry) == "table" and type(entry.note) == "table"
       and seq_active_cell_is_playable(entry, start_qn, col, step_qn) then
      local vis, head_end = seq_note_playable_head_span(entry.note, entry.abs_qn, step_qn)
      -- Only the part of the head that sits in this cell is the note.
      -- Overflow / sustain in the next grid stays empty so a click paints.
      local cover_hi = math.min(head_end, cell_end)
      if hover >= vis - 1e-9 and hover < cover_hi - 1e-9 and vis >= top_vis then
        top, top_vis = entry, vis
      end
    end
  end
  return top
end

function seq_resolve_hover_note(active, hovered_qn, start_qn, col, step_qn)
  if not active or not seq_active_cell_is_playable(active, start_qn, col, step_qn) then
    return nil
  end
  return seq_pick_packed_note(active, hovered_qn, start_qn, col, step_qn)
end

function seq_erase_notes_starting_in_span(region, slot, abs0, abs1, opts)
  if not region or not slot or type(abs0) ~= "number" or type(abs1) ~= "number" then
    return false
  end
  local notes = get_track_note_table(get_seq_pattern(region.pattern_id, false), slot.id, false)
  if not notes then
    return false
  end
  local region_start = region.start_qn or 0.0
  local to_erase = {}
  for key, note in pairs(notes) do
    if type(note) == "table" then
      local abs = region_start + seq_note_qn_offset(note, key)
      local vis = abs + (note.offset_qn or 0.0)
      if vis >= abs0 - 1e-9 and vis < abs1 - 1e-9 then
        to_erase[#to_erase + 1] = { key = tostring(key), qn = abs - region_start }
      end
    end
  end
  local changed = false
  for i = 1, #to_erase do
    local item = to_erase[i]
    if toggle_seq_note(region, slot, item.key, item.qn, "erase", opts) then
      changed = true
    end
  end
  return changed
end

function snap_seq_length_qn(length_qn, step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local steps = math.max(1, math.floor(((length_qn or step_qn) / step_qn) + 0.5))
  return steps * step_qn
end

function seq_region_pool_color(pool_id, alpha)
  local palette = {
    {0x4A, 0x8B, 0xD6},
    {0x7D, 0xD6, 0x70},
    {0xD6, 0xA4, 0x4A},
    {0xC7, 0x6D, 0xD6},
    {0x4A, 0xD6, 0xC1},
    {0xD6, 0x6D, 0x6D},
  }
  local idx = ((math.floor(pool_id or 1) - 1) % #palette) + 1
  local rgb = palette[idx]
  return build_color_rrgbbaa(rgb[1], rgb[2], rgb[3], alpha or 160)
end

function seq_region_overlaps(start_qn, length_qn, ignore_region_id)
  local end_qn = start_qn + length_qn
  for _, reg in ipairs(state.seq_regions) do
    if reg.id ~= ignore_region_id then
      local reg_start = reg.start_qn or 0.0
      local reg_end = reg_start + get_seq_region_length_qn(reg)
      if start_qn < reg_end - 0.000001 and end_qn > reg_start + 0.000001 then
        return true
      end
    end
  end
  return false
end

function find_non_overlapping_region_start(preferred_start_qn, length_qn, ignore_region_id)
  local start_qn = math.max(0.0, preferred_start_qn or 0.0)
  local guard = 0
  while seq_region_overlaps(start_qn, length_qn, ignore_region_id) and guard < 256 do
    local next_start = nil
    local end_qn = start_qn + length_qn
    for _, reg in ipairs(state.seq_regions) do
      if reg.id ~= ignore_region_id then
        local reg_start = reg.start_qn or 0.0
        local reg_end = reg_start + get_seq_region_length_qn(reg)
        if start_qn < reg_end - 0.000001 and end_qn > reg_start + 0.000001 then
          if not next_start or reg_end > next_start then
            next_start = reg_end
          end
        end
      end
    end
    if not next_start or next_start <= start_qn then
      start_qn = start_qn + length_qn
    else
      start_qn = next_start
    end
    guard = guard + 1
  end
  return start_qn
end

function find_prev_non_overlapping_region_start(preferred_start_qn, length_qn, ignore_region_id)
  local start_qn = math.max(0.0, preferred_start_qn or 0.0)
  local guard = 0
  while seq_region_overlaps(start_qn, length_qn, ignore_region_id) and guard < 256 do
    local prev_start = nil
    local end_qn = start_qn + length_qn
    for _, reg in ipairs(state.seq_regions) do
      if reg.id ~= ignore_region_id then
        local reg_start = reg.start_qn or 0.0
        local reg_end = reg_start + get_seq_region_length_qn(reg)
        if start_qn < reg_end - 0.000001 and end_qn > reg_start + 0.000001 then
          local candidate = reg_start - length_qn
          if candidate >= 0 and (not prev_start or candidate < prev_start) then
            prev_start = candidate
          end
        end
      end
    end
    if prev_start == nil then
      return find_non_overlapping_region_start(preferred_start_qn, length_qn, ignore_region_id)
    end
    start_qn = math.max(0.0, prev_start)
    guard = guard + 1
  end
  return start_qn
end

function sort_seq_regions()
  table.sort(state.seq_regions, function(a, b) return (a.start_qn or 0) < (b.start_qn or 0) end)
end

SEQ_REGION_SECTION_DEFS = {
  { key = "intro", display = "Intro", aliases = { "intro" } },
  { key = "verse", display = "Verse", aliases = { "verse", "vrs" } },
  { key = "prechorus", display = "Pre-Chorus", aliases = { "pre-chorus", "prechorus", "pre chorus", "pre" } },
  { key = "chorus", display = "Chorus", aliases = { "chorus", "chs" } },
  { key = "postchorus", display = "Post-Chorus", aliases = { "post-chorus", "postchorus", "post chorus" } },
  { key = "refrain", display = "Refrain", aliases = { "refrain" } },
  { key = "bridge", display = "Bridge", aliases = { "bridge", "brg" } },
  { key = "breakdown", display = "Breakdown", aliases = { "breakdown", "break down", "break" } },
  { key = "solo", display = "Solo", aliases = { "solo" } },
  { key = "interlude", display = "Interlude", aliases = { "interlude" } },
  { key = "instrumental", display = "Instrumental", aliases = { "instrumental" } },
  { key = "build", display = "Build", aliases = { "build", "buildup", "build-up", "riser" } },
  { key = "drop", display = "Drop", aliases = { "drop" } },
  { key = "outro", display = "Outro", aliases = { "outro", "ending", "coda" } },
  { key = "tag", display = "Tag", aliases = { "tag" } },
}

function seq_region_section_def(key)
  for _, def in ipairs(SEQ_REGION_SECTION_DEFS) do
    if def.key == key then
      return def
    end
  end
  return nil
end

function seq_parse_region_section(name)
  local raw = seq_trim_text(name):lower()
  if raw == "" then
    return nil, 1
  end
  local word, num = raw:match("^(.-)%s*(%d+)$")
  if not word or seq_trim_text(word) == "" then
    word, num = raw:match("^([%a%-%s]+)%s*(%d+)$")
  end
  if not word or seq_trim_text(word) == "" then
    word = raw
    num = 1
  else
    word = seq_trim_text(word)
    num = tonumber(num) or 1
  end
  local compact = word:gsub("[%s%-_]+", "")
  local spaced = word:gsub("[%s%-_]+", " ")
  local best, best_len = nil, -1
  for _, def in ipairs(SEQ_REGION_SECTION_DEFS) do
    for _, alias in ipairs(def.aliases) do
      local a_compact = alias:gsub("[%s%-_]+", "")
      local a_spaced = alias:gsub("[%s%-_]+", " ")
      if compact == a_compact or spaced == a_spaced then
        if #a_compact > best_len then
          best = def.key
          best_len = #a_compact
        end
      end
    end
  end
  return best, num
end

function seq_format_region_section_name(key, number)
  local def = seq_region_section_def(key)
  if not def then
    return "Region"
  end
  number = math.max(1, math.floor(tonumber(number) or 1))
  return def.display .. " " .. tostring(number)
end

function seq_region_section_number_used(key, number, ignore_id)
  number = tonumber(number) or 1
  for _, reg in ipairs(state.seq_regions or {}) do
    if reg.id ~= ignore_id then
      local k, n = seq_parse_region_section(reg.name)
      if k == key and n == number then
        return true
      end
    end
  end
  return false
end

function seq_next_section_number(key, ignore_id)
  local n = 1
  while seq_region_section_number_used(key, n, ignore_id) do
    n = n + 1
  end
  return n
end

function seq_region_neighbors_at(start_qn, ignore_id)
  start_qn = start_qn or 0.0
  local prev_reg, next_reg = nil, nil
  for _, reg in ipairs(state.seq_regions or {}) do
    if reg.id ~= ignore_id then
      local qn = reg.start_qn or 0.0
      if qn < start_qn - 1e-9 then
        if not prev_reg or qn > (prev_reg.start_qn or 0.0) then
          prev_reg = reg
        end
      elseif qn > start_qn + 1e-9 then
        if not next_reg or qn < (next_reg.start_qn or 0.0) then
          next_reg = reg
        end
      end
    end
  end
  return prev_reg, next_reg
end

function seq_region_section_counts(ignore_id)
  local counts = {}
  for _, def in ipairs(SEQ_REGION_SECTION_DEFS) do
    counts[def.key] = 0
  end
  for _, reg in ipairs(state.seq_regions or {}) do
    if reg.id ~= ignore_id then
      local key = seq_parse_region_section(reg.name)
      if key then
        counts[key] = (counts[key] or 0) + 1
      end
    end
  end
  return counts
end

function seq_auto_name_new_region(start_qn, ignore_id)
  local prev_reg, next_reg = seq_region_neighbors_at(start_qn, ignore_id)
  local counts = seq_region_section_counts(ignore_id)
  local prev_key, prev_num = seq_parse_region_section(prev_reg and prev_reg.name)
  local next_key = seq_parse_region_section(next_reg and next_reg.name)
  local existing = 0
  for _, reg in ipairs(state.seq_regions or {}) do
    if reg.id ~= ignore_id then
      existing = existing + 1
    end
  end

  local key
  if not prev_reg then
    key = (counts.intro or 0) == 0 and "intro" or "verse"
  elseif prev_key == "intro" then
    key = "verse"
  elseif prev_key == "verse" then
    key = (next_key == "chorus") and "prechorus" or "chorus"
  elseif prev_key == "prechorus" then
    key = "chorus"
  elseif prev_key == "chorus" then
    if next_key == "verse" then
      key = "verse"
    elseif next_key == "outro" or next_key == "tag" then
      key = ((counts.bridge or 0) == 0) and "bridge" or "outro"
    elseif not next_reg and (counts.chorus or 0) >= 2 and (counts.bridge or 0) == 0 then
      key = "bridge"
    elseif not next_reg and (counts.chorus or 0) >= 2 then
      key = "outro"
    else
      key = "verse"
    end
  elseif prev_key == "postchorus" then
    key = "verse"
  elseif prev_key == "refrain" then
    key = "chorus"
  elseif prev_key == "bridge" or prev_key == "breakdown" or prev_key == "solo" then
    key = (not next_reg and (counts.chorus or 0) >= 2) and "outro" or "chorus"
  elseif prev_key == "interlude" or prev_key == "instrumental" then
    key = "verse"
  elseif prev_key == "build" then
    key = "drop"
  elseif prev_key == "drop" then
    key = "chorus"
  elseif prev_key == "outro" or prev_key == "tag" then
    key = "outro"
  elseif existing <= 0 then
    key = "intro"
  elseif existing == 1 then
    key = "verse"
  elseif existing == 2 then
    key = "chorus"
  elseif existing % 2 == 1 then
    key = "verse"
  else
    key = "chorus"
  end

  local num = seq_next_section_number(key, ignore_id)
  if key == "chorus" and prev_key == "verse" and prev_num and not seq_region_section_number_used("chorus", prev_num, ignore_id) then
    num = prev_num
  end
  return seq_format_region_section_name(key, num)
end

function seq_region_name_suggestions(region, typed)
  local start_qn = region and (region.start_qn or 0.0) or 0.0
  local ignore_id = region and region.id or nil
  local current = seq_trim_text(region and region.name or "")
  local current_l = current:lower()
  local typed_trim = seq_trim_text(typed)
  local typed_l = typed_trim:lower()
  -- Only filter after the user changes the prefilled current name.
  local filter_active = typed_l ~= "" and typed_l ~= current_l
  local prev_reg, next_reg = seq_region_neighbors_at(start_qn, ignore_id)
  local prev_key = seq_parse_region_section(prev_reg and prev_reg.name)
  local next_key = seq_parse_region_section(next_reg and next_reg.name)
  local scores = {
    intro = 40, verse = 55, prechorus = 48, chorus = 55, postchorus = 36,
    refrain = 42, bridge = 44, breakdown = 32, solo = 30, interlude = 26,
    instrumental = 22, build = 22, drop = 24, outro = 46, tag = 28,
  }
  if not prev_reg then
    scores.intro = 95
    scores.verse = 72
  elseif prev_key == "intro" then
    scores.verse = 90
    scores.chorus = 60
    scores.prechorus = 50
  elseif prev_key == "verse" then
    scores.chorus = 90
    scores.prechorus = 82
    scores.refrain = 64
    scores.verse = 58
  elseif prev_key == "prechorus" then
    scores.chorus = 92
    scores.verse = 50
  elseif prev_key == "chorus" then
    scores.verse = 86
    scores.chorus = 70
    scores.bridge = 68
    scores.postchorus = 62
    scores.outro = 60
  elseif prev_key == "bridge" then
    scores.chorus = 88
    scores.outro = 70
    scores.solo = 50
  elseif prev_key == "outro" then
    scores.outro = 80
    scores.tag = 60
  end
  if not next_reg then
    scores.outro = math.max(scores.outro or 0, 58)
  elseif next_key == "chorus" then
    scores.prechorus = math.max(scores.prechorus or 0, 80)
    scores.verse = math.max(scores.verse or 0, 70)
  elseif next_key == "outro" then
    scores.bridge = math.max(scores.bridge or 0, 74)
    scores.chorus = math.max(scores.chorus or 0, 66)
  end

  local score_by_name = {}
  local function add(name, score)
    name = seq_trim_text(name)
    if name == "" or name:lower() == current_l then
      return
    end
    local prev = score_by_name[name]
    if not prev or score > prev then
      score_by_name[name] = score
    end
  end

  add(seq_auto_name_new_region(start_qn, ignore_id), 100)
  local cur_key, cur_num = seq_parse_region_section(region and region.name)
  if cur_key then
    if cur_num > 1 then
      add(seq_format_region_section_name(cur_key, cur_num - 1), 56)
    end
    add(seq_format_region_section_name(cur_key, cur_num + 1), 64)
  end
  -- Count this region too so "next unused" is not the name it already has.
  for _, def in ipairs(SEQ_REGION_SECTION_DEFS) do
    local n = seq_next_section_number(def.key, nil)
    add(seq_format_region_section_name(def.key, n), scores[def.key] or 20)
    if def.key == "verse" or def.key == "chorus" or def.key == "intro" then
      add(seq_format_region_section_name(def.key, n + 1), (scores[def.key] or 20) - 14)
    end
  end

  local function collect(filter)
    local list = {}
    for name, score in pairs(score_by_name) do
      if not filter_active or name:lower():find(filter, 1, true) then
        list[#list + 1] = { name = name, score = score }
      end
    end
    table.sort(list, function(a, b)
      if a.score ~= b.score then
        return a.score > b.score
      end
      return a.name < b.name
    end)
    return list
  end

  local ranked = collect(typed_l)
  if #ranked == 0 then
    ranked = collect("")
  end
  local out = {}
  for _, item in ipairs(ranked) do
    out[#out + 1] = item.name
    if #out >= 12 then
      break
    end
  end
  return out
end

function seq_begin_region_rename(region)
  if not region then
    return
  end
  state.seq_region_rename = {
    region_id = region.id,
    text = region.name or "",
    orig = region.name or "",
    typed_prefix = nil,
    completed = false,
    apply_sel = false,
    select_from = 0,
    suggest_index = nil,
    arrow_pick = false,
    focus = true,
    over_suggest = false,
  }
end

function seq_cancel_region_rename()
  state.seq_region_rename = nil
end

function seq_region_autocomplete_match(region, typed)
  if type(typed) ~= "string" or typed == "" then
    return nil
  end
  local current_l = seq_trim_text(region and region.name or ""):lower()
  local typed_l = typed:lower()
  if typed_l == current_l then
    return nil
  end
  local function first_prefix(list)
    for _, name in ipairs(list or {}) do
      if type(name) == "string" and name:lower():sub(1, #typed_l) == typed_l then
        return name
      end
    end
    return nil
  end
  return first_prefix(seq_region_name_suggestions(region, typed))
    or first_prefix(seq_region_name_suggestions(region, ""))
end

function seq_ensure_region_rename_callback()
  if not r.ImGui_CreateFunctionFromEEL then
    return nil
  end
  local valid = seq_region_rename_cb
    and r.ImGui_ValidatePtr
    and r.ImGui_ValidatePtr(seq_region_rename_cb, "ImGui_Function*")
  if not valid then
    seq_region_rename_cb = r.ImGui_CreateFunctionFromEEL([[
      EventFlag == InputTextFlags_CallbackAlways ? (
        apply_sel ? (
          InputTextCallback_DeleteChars(0, strlen(#Buf));
          InputTextCallback_InsertChars(0, #complete);
          SelectionStart = sel_from;
          SelectionEnd = strlen(#Buf);
          CursorPos = sel_from;
          apply_sel = 0;
        );
      );
      EventFlag == InputTextFlags_CallbackCompletion ? (
        SelectionStart = strlen(#Buf);
        SelectionEnd = strlen(#Buf);
        CursorPos = strlen(#Buf);
      );
    ]])
    if seq_region_rename_cb and r.ImGui_Attach and ctx then
      pcall(r.ImGui_Attach, ctx, seq_region_rename_cb)
    end
    if seq_region_rename_cb and r.ImGui_Function_SetValue then
      if r.ImGui_InputTextFlags_CallbackAlways then
        r.ImGui_Function_SetValue(seq_region_rename_cb, "InputTextFlags_CallbackAlways", r.ImGui_InputTextFlags_CallbackAlways())
      end
      if r.ImGui_InputTextFlags_CallbackCompletion then
        r.ImGui_Function_SetValue(seq_region_rename_cb, "InputTextFlags_CallbackCompletion", r.ImGui_InputTextFlags_CallbackCompletion())
      end
    end
  end
  return seq_region_rename_cb
end

function seq_region_rename_suggestion_list(edit, region)
  local filter_text = edit and edit.typed_prefix
  if filter_text == nil or filter_text == (edit.orig or "") then
    filter_text = ""
  end
  return seq_region_name_suggestions(region, filter_text)
end

function seq_region_rename_index_of(list, name)
  if not name then
    return nil
  end
  for i, item in ipairs(list or {}) do
    if item == name then
      return i
    end
  end
  return nil
end

function seq_region_rename_apply_pick(edit, name, keep_prefix)
  if not edit or type(name) ~= "string" or name == "" then
    return
  end
  edit.text = name
  edit.completed = true
  local prefix = keep_prefix and (edit.typed_prefix or "") or ""
  if prefix ~= "" and name:lower():sub(1, #prefix) == prefix:lower() then
    edit.select_from = #prefix
  else
    edit.select_from = 0
  end
end

function seq_region_rename_move_candidate(edit, region, delta)
  if not edit then
    return
  end
  local list = seq_region_rename_suggestion_list(edit, region)
  if #list == 0 then
    return
  end
  local idx = edit.suggest_index
  if type(idx) ~= "number" then
    idx = seq_region_rename_index_of(list, edit.text) or 0
  end
  idx = idx + (delta or 1)
  if idx < 1 then
    idx = #list
  elseif idx > #list then
    idx = 1
  end
  edit.suggest_index = idx
  edit.arrow_pick = true
  seq_region_rename_apply_pick(edit, list[idx], true)
end

function seq_apply_region_rename_autocomplete(edit, new_text, region)
  if not edit or type(new_text) ~= "string" then
    return
  end
  if edit.arrow_pick and new_text == (edit.typed_prefix or "") then
    return
  end
  if edit.arrow_pick then
    edit.arrow_pick = false
  end
  edit.typed_prefix = new_text
  local match = seq_region_autocomplete_match(region, new_text)
  if match and #match > #new_text then
    seq_region_rename_apply_pick(edit, match, true)
    edit.suggest_index = seq_region_rename_index_of(seq_region_rename_suggestion_list(edit, region), match)
  else
    edit.text = new_text
    edit.completed = false
    edit.select_from = 0
    edit.suggest_index = nil
  end
end

function seq_draw_region_rename_completion(edit, x0, y0, x1, y1)
  if not edit or not edit.completed or type(edit.text) ~= "string" or edit.text == "" then
    return
  end
  local prefix_len = math.max(0, math.min(#edit.text, edit.select_from or 0))
  local prefix = edit.text:sub(1, prefix_len)
  local suffix = edit.text:sub(prefix_len + 1)
  if suffix == "" then
    return
  end
  local dl = (r.ImGui_GetForegroundDrawList and r.ImGui_GetForegroundDrawList(ctx))
    or r.ImGui_GetWindowDrawList(ctx)
  if not dl then
    return
  end
  local pad_x = 4
  local tw_prefix, th = r.ImGui_CalcTextSize(ctx, prefix ~= "" and prefix or " ")
  if prefix == "" then
    tw_prefix = 0
  end
  local tw_suffix = select(1, r.ImGui_CalcTextSize(ctx, suffix)) or 0
  th = th or (y1 - y0)
  local text_x = x0 + pad_x
  local text_y = y0 + math.max(0, (y1 - y0 - th) * 0.5)
  local sx0 = text_x + tw_prefix
  local sy0 = text_y - 1
  local sx1 = math.min(x1 - 2, sx0 + tw_suffix + 1)
  local sy1 = text_y + th + 1
  r.ImGui_DrawList_AddRectFilled(dl, sx0, sy0, sx1, sy1, 0x1EFF5E99, 2.0)
  r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, prefix)
  r.ImGui_DrawList_AddText(dl, sx0, text_y, 0xFFFFFFFF, suffix)
end

function seq_commit_region_rename(forced_name)
  local edit = state.seq_region_rename
  if not edit then
    return
  end
  local region = get_seq_region_by_id(edit.region_id)
  local new_name = seq_trim_text(forced_name or edit.text)
  state.seq_region_rename = nil
  if not region then
    return
  end
  if new_name == "" then
    new_name = edit.orig or ""
  end
  if new_name == (region.name or "") then
    return
  end
  local label = begin_seq_undo("Rename sequencer region")
  region.name = new_name
  seq_sync_region_parent_item(region)
  save_config()
  end_seq_undo(label)
end

function render_seq_region_name_suggest_popup(edit_x, edit_y, edit_w)
  local edit = state.seq_region_rename
  if not edit then
    return
  end
  local region = get_seq_region_by_id(edit.region_id)
  local filter_text = edit.typed_prefix
  if filter_text == nil or filter_text == (edit.orig or "") then
    filter_text = ""
  end
  local suggestions = seq_region_name_suggestions(region, filter_text)
  local candidate = nil
  if type(edit.suggest_index) == "number" then
    candidate = suggestions[edit.suggest_index]
  end
  if not candidate then
    candidate = seq_region_autocomplete_match(region, edit.typed_prefix or "")
  end
  if not candidate and edit.completed then
    candidate = edit.text
  end
  if candidate then
    edit.suggest_index = seq_region_rename_index_of(suggestions, candidate) or edit.suggest_index
  end
  if #suggestions == 0 then
    edit.over_suggest = false
    return
  end
  local row_h = 20.0
  local pad_x, pad_y = 6.0, 4.0
  local popup_w = math.max(edit_w or 150, 168)
  for _, name in ipairs(suggestions) do
    local tw = select(1, r.ImGui_CalcTextSize(ctx, name)) or 0
    popup_w = math.max(popup_w, tw + pad_x * 2 + 8)
  end
  local popup_h = pad_y * 2 + #suggestions * row_h
  local popup_x = edit_x
  local popup_y = edit_y - popup_h
  if popup_y < 0 then
    popup_y = 0
  end

  local mx, my = r.ImGui_GetMousePos(ctx)
  edit.over_suggest = mx and my
    and mx >= popup_x and mx <= popup_x + popup_w
    and my >= popup_y and my <= popup_y + popup_h

  local flags = 0
  if r.ImGui_WindowFlags_NoTitleBar then flags = flags | r.ImGui_WindowFlags_NoTitleBar() end
  if r.ImGui_WindowFlags_NoResize then flags = flags | r.ImGui_WindowFlags_NoResize() end
  if r.ImGui_WindowFlags_NoMove then flags = flags | r.ImGui_WindowFlags_NoMove() end
  if r.ImGui_WindowFlags_NoCollapse then flags = flags | r.ImGui_WindowFlags_NoCollapse() end
  if r.ImGui_WindowFlags_NoSavedSettings then flags = flags | r.ImGui_WindowFlags_NoSavedSettings() end
  if r.ImGui_WindowFlags_NoFocusOnAppearing then flags = flags | r.ImGui_WindowFlags_NoFocusOnAppearing() end
  if r.ImGui_WindowFlags_NoNav then flags = flags | r.ImGui_WindowFlags_NoNav() end
  if r.ImGui_WindowFlags_NoScrollbar then flags = flags | r.ImGui_WindowFlags_NoScrollbar() end
  if r.ImGui_WindowFlags_AlwaysAutoResize then flags = flags | r.ImGui_WindowFlags_AlwaysAutoResize() end

  local cond = r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0
  if r.ImGui_SetNextWindowPos then
    r.ImGui_SetNextWindowPos(ctx, popup_x, popup_y, cond)
  end
  if r.ImGui_SetNextWindowSize then
    r.ImGui_SetNextWindowSize(ctx, popup_w, popup_h, cond)
  end
  local style_vars, style_cols = 0, 0
  if r.ImGui_StyleVar_WindowPadding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), pad_x, pad_y)
    style_vars = style_vars + 1
  end
  if r.ImGui_StyleVar_WindowRounding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowRounding(), 6)
    style_vars = style_vars + 1
  end
  if r.ImGui_StyleVar_ItemSpacing then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 0, 0)
    style_vars = style_vars + 1
  end
  if r.ImGui_Col_WindowBg then
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_WindowBg(), UI_THEME.popup_bg or 0x161C18F5)
    style_cols = style_cols + 1
  end
  if r.ImGui_Col_Border then
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Border(), UI_THEME.border_hvr or 0x3D5446FF)
    style_cols = style_cols + 1
  end

  local visible = r.ImGui_Begin(ctx, "##seq_region_name_suggest", true, flags)
  if visible then
    local dl = r.ImGui_GetWindowDrawList(ctx)
    local chosen = nil
    for i, name in ipairs(suggestions) do
      r.ImGui_InvisibleButton(ctx, "##seq_region_sug_" .. tostring(i), popup_w - pad_x * 2, row_h)
      local x0, y0 = r.ImGui_GetItemRectMin(ctx)
      local x1, y1 = r.ImGui_GetItemRectMax(ctx)
      local hovered = r.ImGui_IsItemHovered(ctx)
      local selected = candidate and name == candidate
      if hovered or selected then
        local fill = hovered and (UI_THEME.accent_fill_h or 0x174A24FF) or (UI_THEME.accent_fill or 0x0E2A18FF)
        r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, fill, 3.0)
        if selected then
          r.ImGui_DrawList_AddRect(dl, x0, y0, x1, y1, UI_THEME.accent or 0x1EFF5EFF, 3.0, 0, 1.4)
        end
      end
      local tw, th = r.ImGui_CalcTextSize(ctx, name)
      local text_col = selected and (UI_THEME.accent_hvr or 0x62FF8AFF) or (UI_THEME.text or 0xE8EEEAFF)
      r.ImGui_DrawList_AddText(dl, x0 + 4, y0 + (row_h - th) * 0.5, text_col, name)
      if r.ImGui_IsItemClicked(ctx, 0) then
        chosen = name
      end
    end
    if chosen then
      seq_commit_region_rename(chosen)
    end
  end
  r.ImGui_End(ctx)
  if style_cols > 0 then
    r.ImGui_PopStyleColor(ctx, style_cols)
  end
  if style_vars > 0 then
    r.ImGui_PopStyleVar(ctx, style_vars)
  end
end

function ensure_default_seq_region()
  if #state.seq_regions > 0 then
    if not get_seq_region_by_id(state.selected_seq_region_id) then
      state.selected_seq_region_id = state.seq_regions[1].id
    end
    return state.seq_regions[1]
  end

  local arrange_start, arrange_end = get_arrange_view_range()
  local start_qn = time_to_qn(arrange_start) or 0.0
  local pattern_id = alloc_seq_pattern()
  local temp_region = { start_qn = start_qn, length_bars = 4 }
  start_qn = find_non_overlapping_region_start(start_qn, get_seq_region_length_qn(temp_region), nil)
  local region = {
    id = state.seq_region_next_id,
    name = seq_auto_name_new_region(start_qn),
    start_qn = start_qn,
    length_bars = 4,
    pool_id = alloc_seq_pool(),
    pattern_id = pattern_id,
    groove = "off",
  }
  state.seq_region_next_id = state.seq_region_next_id + 1
  table.insert(state.seq_regions, region)
  state.selected_seq_region_id = region.id
  state.seq_view_start_qn = start_qn
  local span_qn = math.max(get_project_grid_step_qn(), (time_to_qn(arrange_end) or (start_qn + 16.0)) - start_qn)
  state.seq_view_span_qn = span_qn
  save_config()
  return region
end

function get_selected_seq_region()
  ensure_default_seq_region()
  return get_seq_region_by_id(state.selected_seq_region_id) or state.seq_regions[1]
end

function get_seq_region_display_name(region)
  if not region then
    return "Region"
  end
  if type(region.name) == "string" and region.name ~= "" then
    return region.name
  end
  return "Region " .. tostring(region.id or "?")
end

function get_track_note_table(pattern, track_id, create)
  if not pattern then
    return nil
  end
  pattern.notes = pattern.notes or {}
  local key = tostring(track_id)
  if not pattern.notes[key] and create then
    pattern.notes[key] = {}
  end
  return pattern.notes[key]
end

function seq_new_seed()
  local t = (r.time_precise and r.time_precise()) or os.clock()
  return math.floor(t * 1000000 + math.random(0, 1000000)) % 2147483647
end

function seq_apply_reseed_with_undo(reseed_fn)
  if type(reseed_fn) ~= "function" then
    return false
  end
  local already_open = seq_undo_is_open()
  local label = begin_seq_undo("Reseed sequencer random")
  reseed_fn()
  if already_open then
    return false
  end
  end_seq_undo(label)
  if save_config then
    save_config()
  end
  return true
end

function get_seq_track_settings(pattern, track_id, create)
  if not pattern then
    return nil
  end
  pattern.track_settings = pattern.track_settings or {}
  local key = tostring(track_id)
  if not pattern.track_settings[key] and create then
    pattern.track_settings[key] = {
      probability = 1.0,
      humanize_ms = 0.0,
      humanize_pitch_min = 0.0,
      humanize_pitch_max = 0.0,
      humanize_stretch_min = 1.0,
      humanize_stretch_max = 1.0,
      humanize_len_min = 1.0,
      humanize_len_max = 1.0,
      humanize_fade_min = 0.0,
      humanize_fade_max = 0.0,
      humanize_time_min = 0.0,
      humanize_time_max = 0.0,
      humanize_time_is_ms = true,
      humanize_vel = 0.0,
      humanize_vel_beat = 0.0,
      vary_prob = 0.0,
      vary_beat = 0.0,
      stutter_prob = 0.0,
      stutter_beat = 0.0,
      stutter_min = 2.0,
      stutter_max = 4.0,
      ghost_grace = 0.0,
      ghost_after = 0.0,
      ghost_grace_beat = 0.0,
      ghost_after_beat = 0.0,
      ghost_grace_close_min = 0.0625,
      ghost_grace_close_max = 0.125,
      ghost_after_close_min = 0.0625,
      ghost_after_close_max = 0.125,
      ghost_grace_vary = 0.0,
      ghost_after_vary = 0.0,
      ghost_grace_vol_min = 0.20,
      ghost_grace_vol_max = 0.40,
      ghost_after_vol_min = 0.20,
      ghost_after_vol_max = 0.40,
      probability_seed = seq_new_seed(),
      humanize_seed = seq_new_seed(),
      humanize_vel_seed = seq_new_seed(),
      vary_seed = seq_new_seed(),
      vary_swap_seed = seq_new_seed(),
      stutter_seed = seq_new_seed(),
      ghost_grace_seed = seq_new_seed(),
      ghost_after_seed = seq_new_seed(),
    }
  end
  local settings = pattern.track_settings[key]
  if settings then
    if type(settings.probability) ~= "number" then
      settings.probability = 1.0
    end
    if type(settings.humanize_ms) ~= "number" then
      settings.humanize_ms = 0.0
    end
    if type(settings.humanize_pitch_min) ~= "number" then
      settings.humanize_pitch_min = 0.0
    end
    if type(settings.humanize_pitch_max) ~= "number" then
      settings.humanize_pitch_max = settings.humanize_pitch_min
    end
    if type(settings.humanize_stretch_min) ~= "number" then
      settings.humanize_stretch_min = 1.0
    end
    if type(settings.humanize_stretch_max) ~= "number" then
      settings.humanize_stretch_max = settings.humanize_stretch_min
    end
    if type(settings.humanize_len_min) ~= "number" then
      settings.humanize_len_min = 1.0
    end
    if type(settings.humanize_len_max) ~= "number" then
      settings.humanize_len_max = settings.humanize_len_min
    end
    if type(settings.humanize_fade_min) ~= "number" then
      settings.humanize_fade_min = 0.0
    end
    if type(settings.humanize_fade_max) ~= "number" then
      settings.humanize_fade_max = settings.humanize_fade_min
    end
    if settings.humanize_time_is_ms ~= true then
      local lo = tonumber(settings.humanize_time_min)
      local hi = tonumber(settings.humanize_time_max)
      local ms = tonumber(settings.humanize_ms) or 0.0
      if lo ~= nil and hi ~= nil and math.abs(lo) <= 1.0001 and math.abs(hi) <= 1.0001 then
        settings.humanize_time_min = lo * ms
        settings.humanize_time_max = hi * ms
      else
        settings.humanize_time_min = lo or 0.0
        settings.humanize_time_max = hi or settings.humanize_time_min or 0.0
      end
      settings.humanize_time_is_ms = true
    end
    if type(settings.humanize_time_min) ~= "number" then
      settings.humanize_time_min = 0.0
    end
    if type(settings.humanize_time_max) ~= "number" then
      settings.humanize_time_max = 0.0
    end
    if type(settings.humanize_vel) ~= "number" then
      settings.humanize_vel = 0.0
    end
    if type(settings.humanize_vel_beat) ~= "number" then
      settings.humanize_vel_beat = 0.0
    end
    if type(settings.vary_prob) ~= "number" then
      settings.vary_prob = 0.0
    end
    if type(settings.vary_beat) ~= "number" then
      settings.vary_beat = 0.0
    end
    if type(settings.stutter_prob) ~= "number" then
      settings.stutter_prob = 0.0
    end
    if type(settings.stutter_beat) ~= "number" then
      settings.stutter_beat = 0.0
    end
    if type(settings.stutter_min) ~= "number" then
      settings.stutter_min = 2.0
    end
    if type(settings.stutter_max) ~= "number" then
      settings.stutter_max = math.max(settings.stutter_min, 4.0)
    end
    if type(settings.ghost_grace) ~= "number" then
      settings.ghost_grace = 0.0
    end
    if type(settings.ghost_after) ~= "number" then
      settings.ghost_after = 0.0
    end
    if type(settings.ghost_beat) ~= "number" then
      settings.ghost_beat = 0.0
    end
    if type(settings.ghost_close_min) ~= "number" then
      settings.ghost_close_min = 0.0625
    end
    if type(settings.ghost_close_max) ~= "number" then
      settings.ghost_close_max = 0.125
    end
    if type(settings.ghost_grace_beat) ~= "number" then
      settings.ghost_grace_beat = settings.ghost_beat or 0.0
    end
    if type(settings.ghost_after_beat) ~= "number" then
      settings.ghost_after_beat = settings.ghost_beat or 0.0
    end
    if type(settings.ghost_grace_close_min) ~= "number" then
      settings.ghost_grace_close_min = settings.ghost_close_min or 0.0625
    end
    if type(settings.ghost_grace_close_max) ~= "number" then
      settings.ghost_grace_close_max = settings.ghost_close_max or 0.125
    end
    if type(settings.ghost_after_close_min) ~= "number" then
      settings.ghost_after_close_min = settings.ghost_close_min or 0.0625
    end
    if type(settings.ghost_after_close_max) ~= "number" then
      settings.ghost_after_close_max = settings.ghost_close_max or 0.125
    end
    if type(settings.ghost_grace_vary) ~= "number" then
      settings.ghost_grace_vary = 0.0
    end
    if type(settings.ghost_after_vary) ~= "number" then
      settings.ghost_after_vary = 0.0
    end
    if type(settings.ghost_grace_vol_min) ~= "number" then
      settings.ghost_grace_vol_min = 0.20
    end
    if type(settings.ghost_grace_vol_max) ~= "number" then
      settings.ghost_grace_vol_max = math.max(settings.ghost_grace_vol_min, 0.40)
    end
    if type(settings.ghost_after_vol_min) ~= "number" then
      settings.ghost_after_vol_min = 0.20
    end
    if type(settings.ghost_after_vol_max) ~= "number" then
      settings.ghost_after_vol_max = math.max(settings.ghost_after_vol_min, 0.40)
    end
    if type(settings.probability_seed) ~= "number" then
      settings.probability_seed = settings.seed or seq_new_seed()
    end
    if type(settings.humanize_seed) ~= "number" then
      settings.humanize_seed = settings.seed or settings.probability_seed or seq_new_seed()
    end
    if type(settings.humanize_vel_seed) ~= "number" then
      settings.humanize_vel_seed = settings.humanize_seed or settings.seed or seq_new_seed()
    end
    if type(settings.vary_seed) ~= "number" then
      settings.vary_seed = settings.humanize_seed or settings.seed or seq_new_seed()
    end
    if type(settings.vary_swap_seed) ~= "number" then
      settings.vary_swap_seed = settings.vary_seed or seq_new_seed()
    end
    if type(settings.stutter_seed) ~= "number" then
      settings.stutter_seed = settings.vary_seed or settings.humanize_seed or settings.seed or seq_new_seed()
    end
    if type(settings.ghost_seed) ~= "number" then
      settings.ghost_seed = settings.stutter_seed or settings.vary_seed or seq_new_seed()
    end
    if type(settings.ghost_grace_seed) ~= "number" then
      settings.ghost_grace_seed = settings.ghost_seed or seq_new_seed()
    end
    if type(settings.ghost_after_seed) ~= "number" then
      settings.ghost_after_seed = settings.ghost_seed or seq_new_seed()
    end
  end
  return settings
end

function seq_settings_probability_active(settings)
  return settings and (tonumber(settings.probability) or 1.0) < 0.9995
end

function seq_settings_humanize_pitch_active(settings)
  if not settings then
    return false
  end
  local lo, hi = seq_normalize_range(settings.humanize_pitch_min, settings.humanize_pitch_max, -12.0, 12.0)
  return math.abs(lo) > 0.02 or math.abs(hi) > 0.02
end

function seq_settings_humanize_stretch_active(settings)
  if not settings then
    return false
  end
  local lo, hi = seq_normalize_range(settings.humanize_stretch_min, settings.humanize_stretch_max, 0.5, 2.0)
  return math.abs(lo - 1.0) > 0.01 or math.abs(hi - 1.0) > 0.01
end

function seq_settings_humanize_len_active(settings)
  if not settings then
    return false
  end
  local lo, hi = seq_normalize_range(settings.humanize_len_min, settings.humanize_len_max, SEQ_HUMANIZE_LEN_MIN, 1.0)
  return lo < 0.995 or hi < 0.995
end

function seq_settings_humanize_fade_active(settings)
  if not settings or not seq_settings_humanize_len_active(settings) then
    return false
  end
  local lo, hi = seq_normalize_range(settings.humanize_fade_min, settings.humanize_fade_max, 0.0, SEQ_HUMANIZE_FADE_MS)
  return lo > 0.05 or hi > 0.05
end

function seq_settings_humanize_time_active(settings)
  if not settings then
    return false
  end
  local lo, hi = seq_humanize_time_ms_range(settings)
  return math.abs(lo) > 0.05 or math.abs(hi) > 0.05
end

function seq_settings_humanize_active(settings)
  return settings and (
    (tonumber(settings.humanize_ms) or 0.0) > 0.05
    or seq_settings_humanize_time_active(settings)
    or seq_settings_humanize_pitch_active(settings)
    or seq_settings_humanize_stretch_active(settings)
    or seq_settings_humanize_len_active(settings)
  )
end

function seq_settings_vel_humanize_active(settings)
  return settings and (tonumber(settings.humanize_vel) or 0.0) > 0.01
end

function seq_settings_vary_active(settings)
  return settings and (tonumber(settings.vary_prob) or 0.0) > 0.005
end

function seq_settings_stutter_active(settings)
  return settings and (tonumber(settings.stutter_prob) or 0.0) > 0.005
end

function seq_settings_grace_active(settings)
  return settings and (tonumber(settings.ghost_grace) or 0.0) > 0.005
end

function seq_settings_after_active(settings)
  return settings and (tonumber(settings.ghost_after) or 0.0) > 0.005
end

function seq_settings_ghost_active(settings)
  return seq_settings_grace_active(settings) or seq_settings_after_active(settings)
end

function seq_ghost_which_keys(which)
  if which == "after" then
    return {
      prob = "ghost_after",
      beat = "ghost_after_beat",
      close_min = "ghost_after_close_min",
      close_max = "ghost_after_close_max",
      vary = "ghost_after_vary",
      vol_min = "ghost_after_vol_min",
      vol_max = "ghost_after_vol_max",
      seed = "ghost_after_seed",
    }
  end
  return {
    prob = "ghost_grace",
    beat = "ghost_grace_beat",
    close_min = "ghost_grace_close_min",
    close_max = "ghost_grace_close_max",
    vary = "ghost_grace_vary",
    vol_min = "ghost_grace_vol_min",
    vol_max = "ghost_grace_vol_max",
    seed = "ghost_grace_seed",
  }
end

-- bias +1 favors quarter-note downbeats, -1 favors 8th-note offbeats.
function seq_beat_weighted_prob(base_p, abs_qn, bias)
  base_p = tonumber(base_p) or 0.0
  if base_p <= 0.0 then
    return 0.0
  end
  bias = tonumber(bias) or 0.0
  if bias < -1.0 then bias = -1.0 elseif bias > 1.0 then bias = 1.0 end
  local weight = 1.0 + bias * seq_qn_onbeat_signed(abs_qn)
  if weight < 0.0 then weight = 0.0 end
  local p = base_p * weight
  if p > 1.0 then p = 1.0 end
  return p
end

function seq_random_vary_amount(note, region, track_id, step_key, hit_idx)
  local painted = seq_note_param_value(note, "sample_vary", hit_idx) or 0.0
  if painted > 0.000001 then
    return painted
  end
  local hit = hit_idx and seq_stutter_hit_table(note, hit_idx) or nil
  if (hit and type(hit.frozen_sample_path) == "string" and hit.frozen_sample_path ~= "")
     or (note and type(note.frozen_sample_path) == "string" and note.frozen_sample_path ~= "") then
    return 0.0
  end
  if seq_note_is_locked(note) or seq_note_is_locked(get_seq_note(region, track_id, step_key)) then
    return 0.0
  end
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local settings = get_seq_track_settings(pattern, track_id, false)
  if not seq_settings_vary_active(settings) then
    return 0.0
  end
  local abs_qn = seq_note_humanize_abs_qn(region, note, step_key, hit_idx)
  local p = seq_beat_weighted_prob(settings.vary_prob, abs_qn, settings.vary_beat)
  local seed = (tonumber(settings.vary_seed) or 0)
    + (region and region.id or 1) * 1597334677
    + (tonumber(track_id) or 1) * 3812423773
    + (tonumber(step_key) or 1) * 274177
    + (tonumber(hit_idx) or 1) * 668265263
  if seq_stable_unit_rand(seed) > p then
    return 0.0
  end
  local swap = tonumber(settings.vary_swap_seed) or 0
  return 0.40 + seq_stable_unit_rand(seed + 99991 + swap) * 0.60
end

function seq_random_stutter_count(note, region, track_id, step_key)
  local painted = seq_stutter_count(note)
  if painted > 1 then
    return painted
  end
  if seq_note_is_locked(note) or seq_note_is_locked(get_seq_note(region, track_id, step_key)) then
    return painted
  end
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local settings = get_seq_track_settings(pattern, track_id, false)
  if not seq_settings_stutter_active(settings) then
    return 1
  end
  local abs_qn = seq_note_humanize_abs_qn(region, note, step_key, 1)
  local p = seq_beat_weighted_prob(settings.stutter_prob, abs_qn, settings.stutter_beat)
  local seed = (tonumber(settings.stutter_seed) or 0)
    + (region and region.id or 1) * 2246822519
    + (tonumber(track_id) or 1) * 3266489917
    + (tonumber(step_key) or 1) * 668265263
  if seq_stable_unit_rand(seed) > p then
    return 1
  end
  local min_n = math.max(2, math.floor((tonumber(settings.stutter_min) or 2) + 0.5))
  local max_n = math.max(min_n, math.floor((tonumber(settings.stutter_max) or 4) + 0.5))
  max_n = math.min(16, max_n)
  if max_n <= min_n then
    return min_n
  end
  return min_n + math.floor(seq_stable_unit_rand(seed + 17) * (max_n - min_n + 1))
end

function seq_normalize_range(lo, hi, min_v, max_v)
  min_v = min_v or 0.0
  max_v = max_v or 1.0
  lo = tonumber(lo)
  hi = tonumber(hi)
  if lo == nil then lo = min_v end
  if hi == nil then hi = lo end
  if lo > hi then lo, hi = hi, lo end
  if lo < min_v then lo = min_v end
  if hi > max_v then hi = max_v end
  if hi < lo then hi = lo end
  return lo, hi
end

function seq_range_is_single(lo, hi, eps)
  lo, hi = tonumber(lo) or 0.0, tonumber(hi) or 0.0
  return math.abs(hi - lo) <= (eps or 1e-4)
end

function seq_pick_range_value(lo, hi, seed)
  lo = tonumber(lo) or 0.0
  hi = tonumber(hi) or lo
  if hi < lo then lo, hi = hi, lo end
  if hi - lo <= 1e-9 then
    return lo
  end
  return lo + seq_stable_unit_rand(seed) * (hi - lo)
end

SEQ_GHOST_CLOSE_MIN = 1.0 / 128.0
SEQ_GHOST_CLOSE_MAX = 0.25
SEQ_GHOST_CLOSE_STEPS = {
  1.0 / 128.0,   -- 512th
  1.0 / 96.0,    -- 256th triplet
  1.0 / 64.0,    -- 256th
  1.0 / 48.0,    -- 128th triplet
  1.0 / 32.0,    -- 128th
  1.0 / 24.0,    -- 64th triplet
  1.0 / 16.0,    -- 64th
  1.0 / 12.0,    -- 32nd triplet
  0.125,         -- 32nd
  1.0 / 6.0,     -- 16th triplet
  0.25,          -- 16th
}

function seq_snap_close_qn(qn)
  qn = tonumber(qn) or SEQ_GHOST_CLOSE_MIN
  local best, best_d = SEQ_GHOST_CLOSE_STEPS[1], math.abs(qn - SEQ_GHOST_CLOSE_STEPS[1])
  for i = 2, #SEQ_GHOST_CLOSE_STEPS do
    local step = SEQ_GHOST_CLOSE_STEPS[i]
    local d = math.abs(qn - step)
    if d < best_d then
      best, best_d = step, d
    end
  end
  if best < SEQ_GHOST_CLOSE_MIN then best = SEQ_GHOST_CLOSE_MIN end
  if best > SEQ_GHOST_CLOSE_MAX then best = SEQ_GHOST_CLOSE_MAX end
  return best
end

function seq_ghost_close_range(settings, which)
  local keys = seq_ghost_which_keys(which)
  local lo, hi = seq_normalize_range(
    settings and settings[keys.close_min] or 0.0625,
    settings and settings[keys.close_max] or 0.125,
    SEQ_GHOST_CLOSE_MIN,
    SEQ_GHOST_CLOSE_MAX
  )
  return lo, hi
end

function seq_ghost_should_place(settings, which, region, track_id, step_key, abs_qn)
  local keys = seq_ghost_which_keys(which)
  local base_p = tonumber(settings and settings[keys.prob]) or 0.0
  if base_p <= 0.005 then
    return false, 0.0
  end
  local p = seq_beat_weighted_prob(base_p, abs_qn, settings and settings[keys.beat] or 0.0)
  local salt = (which == "after") and 7919 or 104729
  local seed = (tonumber(settings and settings[keys.seed]) or 0)
    + (region and region.id or 1) * 198491317
    + (tonumber(track_id) or 1) * 12582917
    + (tonumber(step_key) or 1) * 16127
    + salt
  if seq_stable_unit_rand(seed) > p then
    return false, 0.0
  end
  local lo, hi = seq_ghost_close_range(settings, which)
  local close_qn = seq_pick_range_value(lo, hi, seed + 409)
  return true, close_qn
end

function seq_ghost_vol_range(settings, which)
  local keys = seq_ghost_which_keys(which)
  return seq_normalize_range(
    settings and settings[keys.vol_min] or 0.20,
    settings and settings[keys.vol_max] or 0.40,
    0.0,
    1.0
  )
end

function seq_ghost_pick_volume(settings, which, region, track_id, step_key)
  local lo, hi = seq_ghost_vol_range(settings, which)
  local keys = seq_ghost_which_keys(which)
  local salt = (which == "after") and 3371 or 2741
  local seed = (tonumber(settings and settings[keys.seed]) or 0)
    + (region and region.id or 1) * 2246822519
    + (tonumber(track_id) or 1) * 3267000013
    + (tonumber(step_key) or 1) * 668265263
    + salt
  return seq_pick_range_value(lo, hi, seed)
end

function seq_format_vol_range(lo, hi)
  lo, hi = seq_normalize_range(lo, hi, 0.0, 1.0)
  local function pct(v)
    return string.format("%.0f%%", v * 100.0)
  end
  if seq_range_is_single(lo, hi, 0.008) then
    return pct((lo + hi) * 0.5)
  end
  return pct(lo) .. " – " .. pct(hi)
end

function seq_ghost_vary_amount(settings, which, region, track_id, step_key)
  local keys = seq_ghost_which_keys(which)
  local p = tonumber(settings and settings[keys.vary]) or 0.0
  if p <= 0.005 then
    return 0.0
  end
  local salt = (which == "after") and 4243 or 6151
  local seed = (tonumber(settings and settings[keys.seed]) or 0)
    + (region and region.id or 1) * 2654435761
    + (tonumber(track_id) or 1) * 40503
    + (tonumber(step_key) or 1) * 8543
    + salt
  if seq_stable_unit_rand(seed) > p then
    return 0.0
  end
  return 0.40 + seq_stable_unit_rand(seed + 91) * 0.60
end

function seq_stable_unit_rand(seed)
  return math.abs(math.sin(tonumber(seed) or 0) * 10000.0) % 1.0
end

SEQ_HUMANIZE_TIME_MS = 500.0
SEQ_HUMANIZE_LEN_MIN = 0.05
SEQ_HUMANIZE_FADE_MS = 200.0
SEQ_PITCH_HUMANIZE = 12.0
SEQ_PITCH_CURVE = 2.25

function seq_humanize_time_ms_range(settings)
  return seq_normalize_range(
    settings and settings.humanize_time_min or 0.0,
    settings and settings.humanize_time_max or 0.0,
    -SEQ_HUMANIZE_TIME_MS, SEQ_HUMANIZE_TIME_MS
  )
end

function seq_humanize_effective_time_ms(settings, humanize_ms)
  local lo, hi = seq_humanize_time_ms_range(settings)
  if math.abs(lo) > 0.05 or math.abs(hi) > 0.05 then
    return lo, hi
  end
  humanize_ms = tonumber(humanize_ms) or (settings and tonumber(settings.humanize_ms)) or 0.0
  if humanize_ms > 0.05 then
    return -humanize_ms, humanize_ms
  end
  return 0.0, 0.0
end

function seq_humanize_sync_time_from_knob(settings, ms)
  if not settings then
    return
  end
  ms = tonumber(ms) or 0.0
  if ms < 0.0 then ms = 0.0 end
  settings.humanize_ms = ms
  settings.humanize_time_min = -ms
  settings.humanize_time_max = ms
  settings.humanize_time_is_ms = true
end

function seq_pitch_range_from_norm(t)
  if t < 0.0 then t = 0.0 elseif t > 1.0 then t = 1.0 end
  local u = t * 2.0 - 1.0
  local s = (u < 0.0) and -1.0 or 1.0
  return s * SEQ_PITCH_HUMANIZE * (math.abs(u) ^ SEQ_PITCH_CURVE)
end

function seq_pitch_range_to_norm(v)
  v = tonumber(v) or 0.0
  local a = math.abs(v) / SEQ_PITCH_HUMANIZE
  if a > 1.0 then a = 1.0 end
  local u = ((v < 0.0) and -1.0 or 1.0) * (a ^ (1.0 / SEQ_PITCH_CURVE))
  return (u + 1.0) * 0.5
end

function seq_humanize_time_offset_sec(region, track_id, step_key, humanize_ms, random_seed)
  local note = get_seq_note(region, track_id, step_key)
  if seq_note_is_locked(note) then
    return tonumber(note.locked_humanize_sec) or 0.0
  end
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local settings = get_seq_track_settings(pattern, track_id, false)
  local lo, hi = seq_humanize_effective_time_ms(settings, humanize_ms)
  if math.abs(lo) < 0.05 and math.abs(hi) < 0.05 then
    return 0.0
  end
  local seed = (tonumber(random_seed) or 0)
    + (region and region.id or 1) * 2654435761
    + (tonumber(track_id) or 1) * 1013904223
    + (tonumber(step_key) or 1) * 374761393
  return seq_pick_range_value(lo, hi, seed) / 1000.0
end

function seq_humanize_pitch_offset(region, track_id, step_key, hit_idx, opts)
  opts = opts or {}
  local note = get_seq_note(region, track_id, step_key)
  if (not opts.force) and seq_note_is_locked(note) then
    return tonumber(note.locked_humanize_pitch) or 0.0
  end
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local settings = get_seq_track_settings(pattern, track_id, false)
  if not seq_settings_humanize_pitch_active(settings) then
    return 0.0
  end
  local lo, hi = seq_normalize_range(settings.humanize_pitch_min, settings.humanize_pitch_max, -12.0, 12.0)
  local seed = (tonumber(settings.humanize_seed) or 0)
    + (region and region.id or 1) * 2246822519
    + (tonumber(track_id) or 1) * 3266489917
    + (tonumber(step_key) or 1) * 668265263
    + (tonumber(hit_idx) or 1) * 7919
    + 17
  return seq_pick_range_value(lo, hi, seed)
end

function seq_humanize_stretch_mul(region, track_id, step_key, hit_idx, opts)
  opts = opts or {}
  local note = get_seq_note(region, track_id, step_key)
  if (not opts.force) and seq_note_is_locked(note) then
    return tonumber(note.locked_humanize_stretch) or 1.0
  end
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local settings = get_seq_track_settings(pattern, track_id, false)
  if not seq_settings_humanize_stretch_active(settings) then
    return 1.0
  end
  local lo, hi = seq_normalize_range(settings.humanize_stretch_min, settings.humanize_stretch_max, 0.5, 2.0)
  local seed = (tonumber(settings.humanize_seed) or 0)
    + (region and region.id or 1) * 2654435761
    + (tonumber(track_id) or 1) * 1013904223
    + (tonumber(step_key) or 1) * 374761393
    + (tonumber(hit_idx) or 1) * 104729
    + 31
  local mul = seq_pick_range_value(lo, hi, seed)
  if mul < 0.5 then mul = 0.5 elseif mul > 2.0 then mul = 2.0 end
  return mul
end

function seq_humanize_length_mul(region, track_id, step_key, hit_idx, opts)
  opts = opts or {}
  local note = get_seq_note(region, track_id, step_key)
  if (not opts.force) and seq_note_is_locked(note) then
    local locked = tonumber(note.locked_humanize_len)
    if locked then
      if locked < SEQ_HUMANIZE_LEN_MIN then locked = SEQ_HUMANIZE_LEN_MIN end
      if locked > 1.0 then locked = 1.0 end
      return locked
    end
    return 1.0
  end
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local settings = get_seq_track_settings(pattern, track_id, false)
  if not seq_settings_humanize_len_active(settings) then
    return 1.0
  end
  local lo, hi = seq_normalize_range(settings.humanize_len_min, settings.humanize_len_max, SEQ_HUMANIZE_LEN_MIN, 1.0)
  local seed = (tonumber(settings.humanize_seed) or 0)
    + (region and region.id or 1) * 2654435761
    + (tonumber(track_id) or 1) * 1013904223
    + (tonumber(step_key) or 1) * 374761393
    + (tonumber(hit_idx) or 1) * 2246822519
    + 47
  local mul = seq_pick_range_value(lo, hi, seed)
  if mul < SEQ_HUMANIZE_LEN_MIN then mul = SEQ_HUMANIZE_LEN_MIN elseif mul > 1.0 then mul = 1.0 end
  return mul
end

function seq_humanize_fade_out_sec(region, track_id, step_key, hit_idx, opts)
  opts = opts or {}
  local note = get_seq_note(region, track_id, step_key)
  if (not opts.force) and seq_note_is_locked(note) then
    return math.max(0.0, tonumber(note.locked_humanize_fade) or 0.0)
  end
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local settings = get_seq_track_settings(pattern, track_id, false)
  if not seq_settings_humanize_fade_active(settings) then
    return 0.0
  end
  local lo, hi = seq_normalize_range(settings.humanize_fade_min, settings.humanize_fade_max, 0.0, SEQ_HUMANIZE_FADE_MS)
  local seed = (tonumber(settings.humanize_seed) or 0)
    + (region and region.id or 1) * 2246822519
    + (tonumber(track_id) or 1) * 3266489917
    + (tonumber(step_key) or 1) * 668265263
    + (tonumber(hit_idx) or 1) * 2654435761
    + 59
  return seq_pick_range_value(lo, hi, seed) / 1000.0
end

-- +1 on a quarter-note downbeat, -1 on the 8th-note offbeat.
function seq_qn_onbeat_signed(abs_qn)
  local frac = (tonumber(abs_qn) or 0.0) % 1.0
  if frac < 0.0 then
    frac = frac + 1.0
  end
  local dist = math.min(frac, 1.0 - frac)
  local on_beat = 1.0 - (dist / 0.5)
  if on_beat < 0.0 then on_beat = 0.0 end
  if on_beat > 1.0 then on_beat = 1.0 end
  return on_beat * 2.0 - 1.0
end

SEQ_VEL_HUMANIZE_FLOOR = 0.05

function seq_note_locked_vel(note, hit_idx)
  if type(note) ~= "table" then
    return nil
  end
  if hit_idx then
    local hit = seq_stutter_hit_table(note, hit_idx)
    if type(hit) == "table" and hit.locked_vel ~= nil then
      return tonumber(hit.locked_vel)
    end
  end
  return tonumber(note.locked_vel)
end

function seq_humanize_note_velocity(base_vel, region, track_id, step_key, abs_qn, hit_idx)
  base_vel = tonumber(base_vel) or 1.0
  local note = get_seq_note(region, track_id, step_key)
  if seq_note_is_locked(note) then
    return seq_note_locked_vel(note, hit_idx) or base_vel
  end
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local settings = get_seq_track_settings(pattern, track_id, false)
  local amount = settings and tonumber(settings.humanize_vel) or 0.0
  if not amount or amount <= 0.0005 then
    return base_vel
  end
  local bias = tonumber(settings.humanize_vel_beat) or 0.0
  if bias < -1.0 then bias = -1.0 elseif bias > 1.0 then bias = 1.0 end
  local seed = (tonumber(settings.humanize_vel_seed) or 0)
    + (region and region.id or 1) * 2246822519
    + (tonumber(track_id) or 1) * 3266489917
    + (tonumber(step_key) or 1) * 668265263
    + (tonumber(hit_idx) or 1) * 374761393
  local rand = seq_stable_unit_rand(seed) * 2.0 - 1.0
  local directed = seq_qn_onbeat_signed(abs_qn)
  local mix = 1.0 - math.abs(bias) * 0.65
  local vel = base_vel + rand * amount * mix + directed * amount * bias
  if base_vel > 0.001 then
    if vel < SEQ_VEL_HUMANIZE_FLOOR then vel = SEQ_VEL_HUMANIZE_FLOOR end
  elseif vel < 0.0 then
    vel = 0.0
  end
  if vel > 2.0 then vel = 2.0 end
  return vel
end

function seq_note_humanize_abs_qn(region, note, step_key, hit_idx)
  local grid_qn = state.seq_grid_qn or 0.25
  local start_qn = seq_note_trigger_qn(region, step_key, note, grid_qn)
  local idx = tonumber(hit_idx) or 1
  if idx > 1 then
    local stutter = seq_stutter_count(note)
    if stutter > 1 then
      local off0 = seq_stutter_hit_span(note, idx, grid_qn)
      start_qn = start_qn + (off0 or 0.0)
    end
  end
  return start_qn
end

function seq_expected_humanized_velocity(note, region, track_id, step_key, hit_idx)
  local base = tonumber(note and note.volume) or 1.0
  local abs_qn = seq_note_humanize_abs_qn(region, note, step_key, hit_idx)
  return seq_humanize_note_velocity(base, region, track_id, step_key, abs_qn, hit_idx)
end

-- Compare arrange take-vol to the *humanized* output. Never store that
-- output as the note's base, or the next humanize pass compounds toward 0.
function seq_ingest_resolve_volume(rec_vol, note, region, track_id, step_key)
  rec_vol = tonumber(rec_vol)
  local base = tonumber(note and note.volume)
  if base == nil then
    base = 1.0
  end
  if rec_vol == nil then
    return base, false
  end
  local expected = seq_expected_humanized_velocity(note or { volume = base }, region, track_id, step_key, 1)
  local settings = get_seq_track_settings(get_seq_pattern(region and region.pattern_id, false), track_id, false)
  local amount = settings and tonumber(settings.humanize_vel) or 0.0
  local slop = 0.03
  if amount > 0.0 then
    slop = math.max(slop, amount * 1.6 + 0.08)
  end
  if math.abs(rec_vol - expected) <= slop then
    -- Heal notes already collapsed by baked-in humanize.
    if amount > 0.0 and base < 0.08 then
      return 1.0, true
    end
    return base, false
  end
  local stored = rec_vol - (expected - base)
  if stored < 0.0 then stored = 0.0 end
  if stored > 2.0 then stored = 2.0 end
  return stored, true
end

function seq_ingest_resolve_pitch(rec_pitch, note, region, track_id, step_key)
  rec_pitch = tonumber(rec_pitch)
  local base = tonumber(note and note.pitch) or 0.0
  if rec_pitch == nil then
    return base, false
  end
  local offset = seq_humanize_pitch_offset(region, track_id, step_key, 1)
  local expected = base + offset
  local slop = 0.08
  if math.abs(offset) > 0.01 then
    slop = math.max(slop, math.abs(offset) * 0.35 + 0.12)
  end
  if math.abs(rec_pitch - expected) <= slop then
    return base, false
  end
  local stored = rec_pitch - offset
  if stored < -24.0 then stored = -24.0 elseif stored > 24.0 then stored = 24.0 end
  return stored, true
end

function seq_format_beat_drag(bias)
  bias = tonumber(bias) or 0.0
  if bias > 1.0 then bias = 1.0 elseif bias < -1.0 then bias = -1.0 end
  local pct = math.floor(math.abs(bias) * 100.0 + 0.5)
  if pct < 3 then
    return "Even"
  elseif bias > 0.0 then
    return string.format("%d%% down beat", pct)
  end
  return string.format("%d%% up beat", pct)
end

function seq_format_vel_beat(bias)
  return seq_format_beat_drag(bias)
end

function seq_format_close_qn(qn)
  qn = tonumber(qn) or 0.0
  local marks = {
    { 1.0 / 128.0, "512th" },
    { 1.0 / 96.0, "256th T" },
    { 1.0 / 64.0, "256th" },
    { 1.0 / 48.0, "128th T" },
    { 1.0 / 32.0, "128th" },
    { 1.0 / 24.0, "64th T" },
    { 1.0 / 16.0, "64th" },
    { 1.0 / 12.0, "32nd T" },
    { 0.125, "32nd" },
    { 1.0 / 6.0, "16th T" },
    { 0.25, "16th" },
  }
  local best, best_d = marks[1][2], math.abs(qn - marks[1][1])
  for i = 2, #marks do
    local d = math.abs(qn - marks[i][1])
    if d < best_d then
      best, best_d = marks[i][2], d
    end
  end
  if best_d > 0.004 then
    return string.format("%.0f ticks", qn * 960.0)
  end
  return best
end

function seq_format_close_range(lo, hi)
  lo, hi = seq_normalize_range(lo, hi, SEQ_GHOST_CLOSE_MIN, SEQ_GHOST_CLOSE_MAX)
  if seq_range_is_single(lo, hi, 0.008) then
    return seq_format_close_qn((lo + hi) * 0.5)
  end
  return seq_format_close_qn(lo) .. " – " .. seq_format_close_qn(hi)
end

function seq_format_stutter_range(lo, hi)
  lo = math.max(2, math.floor((tonumber(lo) or 2) + 0.5))
  hi = math.max(lo, math.floor((tonumber(hi) or lo) + 0.5))
  if lo == hi then
    return tostring(lo)
  end
  return string.format("%d–%d", lo, hi)
end

function seq_format_pitch_range(lo, hi)
  lo, hi = seq_normalize_range(lo, hi, -12.0, 12.0)
  local function fmt(v)
    if math.abs(v) < 0.05 then
      return "0"
    elseif v > 0.0 then
      return string.format("+%.1f", v)
    end
    return string.format("%.1f", v)
  end
  if seq_range_is_single(lo, hi, 0.05) then
    return fmt((lo + hi) * 0.5) .. " st"
  end
  return fmt(lo) .. "–" .. fmt(hi) .. " st"
end

function seq_format_stretch_range(lo, hi)
  lo, hi = seq_normalize_range(lo, hi, 0.5, 2.0)
  if seq_range_is_single(lo, hi, 0.012) then
    return string.format("%.2fx", (lo + hi) * 0.5)
  end
  return string.format("%.2f–%.2fx", lo, hi)
end

function seq_format_len_range(lo, hi)
  lo, hi = seq_normalize_range(lo, hi, SEQ_HUMANIZE_LEN_MIN, 1.0)
  local function pct(v)
    return string.format("%.0f%%", v * 100.0)
  end
  if seq_range_is_single(lo, hi, 0.008) then
    return pct((lo + hi) * 0.5)
  end
  return pct(lo) .. "–" .. pct(hi)
end

function seq_format_fade_ms_range(lo, hi)
  lo, hi = seq_normalize_range(lo, hi, 0.0, SEQ_HUMANIZE_FADE_MS)
  local function fmt(v)
    if v < 0.5 then
      return "0"
    end
    return string.format("%.0f", v)
  end
  if seq_range_is_single(lo, hi, 0.6) then
    return fmt((lo + hi) * 0.5) .. " ms"
  end
  return fmt(lo) .. "–" .. fmt(hi) .. " ms"
end

function seq_format_time_ms_range(lo, hi)
  lo, hi = seq_normalize_range(lo, hi, -SEQ_HUMANIZE_TIME_MS, SEQ_HUMANIZE_TIME_MS)
  local function fmt(v)
    if math.abs(v) < 0.5 then
      return "0"
    elseif v > 0.0 then
      return string.format("+%.0f", v)
    end
    return string.format("%.0f", v)
  end
  if seq_range_is_single(lo, hi, 0.6) then
    local v = (lo + hi) * 0.5
    if math.abs(v) < 0.5 then
      return "0 ms"
    elseif v < 0.0 then
      return string.format("%.0f ms early", -v)
    end
    return string.format("%.0f ms late", v)
  end
  return fmt(lo) .. "–" .. fmt(hi) .. " ms"
end

function seq_queue_random_sync(pattern_id, track_id)
  if not pattern_id then
    return
  end
  local pending = state.seq_random_sync_pending
  if not pending then
    pending = { pattern_id = pattern_id, track_ids = {} }
    state.seq_random_sync_pending = pending
  end
  pending.pattern_id = pattern_id
  if track_id then
    pending.track_ids[track_id] = true
  else
    pending.all_tracks = true
  end
end

function seq_repair_collapsed_note_velocities(pattern, track_id)
  local notes = get_track_note_table(pattern, track_id, false)
  if not notes then
    return
  end
  for _, note in pairs(notes) do
    if type(note) == "table" and (tonumber(note.volume) or 1.0) < 0.08 then
      note.volume = 1.0
    end
  end
end

function seq_flush_pending_random_sync()
  local pending = state.seq_random_sync_pending
  if not pending then
    return
  end
  state.seq_random_sync_pending = nil
  state.seq_random_sync_run = false
  local pattern = get_seq_pattern(pending.pattern_id, false)
  if pattern and pending.track_ids and not pending.all_tracks then
    for track_id, _ in pairs(pending.track_ids) do
      seq_repair_collapsed_note_velocities(pattern, track_id)
    end
  elseif pattern then
    for _, slot in ipairs(state.seq_tracks or {}) do
      seq_repair_collapsed_note_velocities(pattern, slot.id)
    end
  end
  if seq_schedule_ingest_save then
    seq_schedule_ingest_save()
  elseif save_seq_project_state then
    save_seq_project_state()
  end
  if pending.all_tracks or not pending.track_ids then
    sync_seq_pattern_regions(pending.pattern_id)
    return
  end
  local any = false
  for _ in pairs(pending.track_ids) do
    any = true
    break
  end
  if not any then
    sync_seq_pattern_regions(pending.pattern_id)
    return
  end
  if r.PreventUIRefresh then r.PreventUIRefresh(1) end
  for track_id, _ in pairs(pending.track_ids) do
    local slot = seq_find_track_slot_by_id(track_id) or seq_find_slot_by_id(track_id)
    if slot then
      sync_seq_pattern_track(pending.pattern_id, slot, { skip_arrange = true, force_rebuild = true })
    end
  end
  if r.PreventUIRefresh then r.PreventUIRefresh(-1) end
  if r.UpdateArrange then
    r.UpdateArrange()
  end
end

function seq_collect_region_random_entries(region)
  local entries = {}
  local has_prob = false
  local has_human = false
  local has_vel = false
  local has_vary = false
  local has_stut = false
  local has_ghost = false
  local has_grace = false
  local has_after = false
  if not region then
    return entries, has_prob, has_human, has_vel, has_vary, has_stut, has_ghost, has_grace, has_after
  end
  local pattern = get_seq_pattern(region.pattern_id, false)
  if not pattern then
    return entries, has_prob, has_human, has_vel, has_vary, has_stut, has_ghost, has_grace, has_after
  end
  for _, slot in ipairs(state.seq_tracks or {}) do
    local settings = get_seq_track_settings(pattern, slot.id, false)
    local show_prob = seq_settings_probability_active(settings)
    local show_human = seq_settings_humanize_active(settings)
    local show_vel = seq_settings_vel_humanize_active(settings)
    local show_vary = seq_settings_vary_active(settings)
    local show_stut = seq_settings_stutter_active(settings)
    local show_grace = seq_settings_grace_active(settings)
    local show_after = seq_settings_after_active(settings)
    local show_ghost = show_grace or show_after
    if show_prob or show_human or show_vel or show_vary or show_stut or show_ghost then
      entries[#entries + 1] = {
        slot = slot,
        settings = settings,
        show_prob = show_prob,
        show_human = show_human,
        show_vel = show_vel,
        show_vary = show_vary,
        show_stut = show_stut,
        show_grace = show_grace,
        show_after = show_after,
        show_ghost = show_ghost,
      }
      has_prob = has_prob or show_prob
      has_human = has_human or show_human
      has_vel = has_vel or show_vel
      has_vary = has_vary or show_vary
      has_stut = has_stut or show_stut
      has_ghost = has_ghost or show_ghost
      has_grace = has_grace or show_grace
      has_after = has_after or show_after
    end
  end
  return entries, has_prob, has_human, has_vel, has_vary, has_stut, has_ghost, has_grace, has_after
end

function seq_snapshot_region_random_popup(region)
  local entries = seq_collect_region_random_entries(region)
  local snapshot = {}
  for _, entry in ipairs(entries) do
    snapshot[#snapshot + 1] = {
      track_id = entry.slot.id,
      show_prob = entry.show_prob,
      show_human = entry.show_human,
      show_vel = entry.show_vel,
      show_vary = entry.show_vary,
      show_stut = entry.show_stut,
      show_grace = entry.show_grace,
      show_after = entry.show_after,
      show_ghost = entry.show_ghost,
    }
  end
  return snapshot
end

function seq_reset_region_random_settings(region, kind)
  if not region then
    return false
  end
  local pattern = get_seq_pattern(region.pattern_id, false)
  if not pattern then
    return false
  end
  local changed = false
  for _, slot in ipairs(state.seq_tracks or {}) do
    local settings = get_seq_track_settings(pattern, slot.id, false)
    if settings then
      if (kind == "prob" or kind == "all") and seq_settings_probability_active(settings) then
        settings.probability = 1.0
        changed = true
      end
      if (kind == "human" or kind == "all") and seq_settings_humanize_active(settings) then
        settings.humanize_ms = 0.0
        settings.humanize_pitch_min = 0.0
        settings.humanize_pitch_max = 0.0
        settings.humanize_stretch_min = 1.0
        settings.humanize_stretch_max = 1.0
        settings.humanize_len_min = 1.0
        settings.humanize_len_max = 1.0
        settings.humanize_fade_min = 0.0
        settings.humanize_fade_max = 0.0
        settings.humanize_time_min = 0.0
        settings.humanize_time_max = 0.0
        settings.humanize_time_is_ms = true
        changed = true
      end
      if (kind == "vel" or kind == "all") and seq_settings_vel_humanize_active(settings) then
        settings.humanize_vel = 0.0
        settings.humanize_vel_beat = 0.0
        changed = true
      end
      if (kind == "vary" or kind == "all") and seq_settings_vary_active(settings) then
        settings.vary_prob = 0.0
        settings.vary_beat = 0.0
        changed = true
      end
      if (kind == "stut" or kind == "all") and seq_settings_stutter_active(settings) then
        settings.stutter_prob = 0.0
        settings.stutter_beat = 0.0
        changed = true
      end
      if (kind == "grace" or kind == "ghost" or kind == "all") and seq_settings_grace_active(settings) then
        settings.ghost_grace = 0.0
        settings.ghost_grace_beat = 0.0
        settings.ghost_grace_vary = 0.0
        settings.ghost_grace_vol_min = 0.20
        settings.ghost_grace_vol_max = 0.40
        changed = true
      end
      if (kind == "after" or kind == "ghost" or kind == "all") and seq_settings_after_active(settings) then
        settings.ghost_after = 0.0
        settings.ghost_after_beat = 0.0
        settings.ghost_after_vary = 0.0
        settings.ghost_after_vol_min = 0.20
        settings.ghost_after_vol_max = 0.40
        changed = true
      end
    end
  end
  return changed
end

function seq_note_probability_roll(region, track_id, step_key, probability, probability_seed)
  probability = tonumber(probability)
  if not probability or probability >= 1.0 then
    return true
  end
  if probability <= 0.0 then
    return false
  end
  local seed = (tonumber(probability_seed) or 0)
    + (region and region.id or 1) * 73856093
    + (tonumber(track_id) or 1) * 19349663
    + (tonumber(step_key) or 1) * 83492791
  local pseudo = math.abs(math.sin(seed) * 10000.0) % 1.0
  return pseudo <= probability
end

function seq_note_passes_probability(region, track_id, step_key, probability, probability_seed)
  local note = get_seq_note(region, track_id, step_key)
  if seq_note_is_locked(note) then
    return note.locked_skip ~= true
  end
  return seq_note_probability_roll(region, track_id, step_key, probability, probability_seed)
end

