function seq_random_refresh_button(id, dl, x, y, w, h, alpha)
  w = math.max(10.0, w or 16.0)
  h = math.max(10.0, h or 14.0)
  r.ImGui_SetCursorScreenPos(ctx, x, y)
  local clicked = r.ImGui_InvisibleButton(ctx, id, w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local pressed = r.ImGui_IsItemActive(ctx)
  local bg = hovered and UI_THEME.surface_hvr or UI_THEME.surface
  local edge = hovered and UI_THEME.accent or UI_THEME.border
  ui_draw_panel(dl, x, y, x + w, y + h, 5.0, bg, edge, hovered, pressed)
  local col = hovered and 0xFFFFFFFF or UI_THEME.text_dim
  local cx, cy = x + w * 0.5, y + h * 0.5
  local rad = math.min(w, h) * 0.28
  local function arc(a0, a1)
    local prev_x, prev_y = nil, nil
    for i = 0, 7 do
      local a = a0 + (a1 - a0) * (i / 7)
      local ax = cx + math.cos(a) * rad
      local ay = cy + math.sin(a) * rad
      if prev_x then
        r.ImGui_DrawList_AddLine(dl, prev_x, prev_y, ax, ay, col, 1.3)
      end
      prev_x, prev_y = ax, ay
    end
  end
  arc(-0.2, 2.2)
  arc(math.pi - 0.2, math.pi + 2.2)
  r.ImGui_DrawList_AddTriangleFilled(
    dl, cx + rad + 1.2, cy - 1.6, cx + rad - 2.4, cy + 1.8, cx + rad + 2.2, cy + 1.8, col
  )
  if hovered and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, "Swap varied samples, keep which notes vary")
  end
  return clicked
end

function seq_random_beat_drag(id, dl, x, y, w, h, value, alpha, tooltip)
  w = math.max(70.0, w or 108.0)
  h = math.max(16.0, h or 20.0)
  alpha = alpha or 170
  value = math.max(-1.0, math.min(1.0, tonumber(value) or 0.0))
  r.ImGui_SetCursorScreenPos(ctx, x, y)
  r.ImGui_InvisibleButton(ctx, id, w, h)
  local active = r.ImGui_IsItemActive(ctx)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local fine = seq_fine_drag_down()
  if hovered and tooltip and tooltip ~= "" and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, tooltip)
  end
  local changed = false
  if active then
    local mx = r.ImGui_GetMousePos(ctx)
    mx = mx or x
    if (not state.seq_random_knob_drag) or state.seq_random_knob_drag.id ~= id then
      state.seq_random_knob_drag = { id = id, start_value = value, start_mx = mx, fine = fine }
    end
    local drag = state.seq_random_knob_drag
    if drag.fine ~= fine then
      drag.start_value = value
      drag.start_mx = mx
      drag.fine = fine
    end
    local dx = mx - (drag.start_mx or mx)
    local scale = fine and SEQ_FINE_DRAG_SCALE or 1.0
    local new_value = (drag.start_value or value) + dx / math.max(36.0, w * 0.48) * scale
    new_value = math.max(-1.0, math.min(1.0, new_value))
    if math.abs(new_value - value) > 1e-6 then
      value = new_value
      changed = true
    end
  elseif state.seq_random_knob_drag and state.seq_random_knob_drag.id == id then
    state.seq_random_knob_drag = nil
  end

  local bg = build_color_rrgbbaa(28, 34, 46, alpha)
  local edge = hovered and UI_THEME.accent or build_color_rrgbbaa(90, 108, 132, math.min(255, alpha + 40))
  ui_draw_panel(dl, x, y, x + w, y + h, 5.0, bg, edge, hovered, active)
  local mid = x + w * 0.5
  r.ImGui_DrawList_AddLine(dl, mid, y + 3.0, mid, y + h - 3.0, 0xFFFFFF28, 1.0)
  local t = (value + 1.0) * 0.5
  local fill_x = x + 3.0 + t * (w - 6.0)
  local fill_col = value >= 0.0 and 0xFFE7A6AA or 0xA8C8F0AA
  if math.abs(value) > 0.03 then
    if fill_x >= mid then
      r.ImGui_DrawList_AddRectFilled(dl, mid, y + 3.0, fill_x, y + h - 3.0, fill_col, 3.0)
    else
      r.ImGui_DrawList_AddRectFilled(dl, fill_x, y + 3.0, mid, y + h - 3.0, fill_col, 3.0)
    end
  end
  local text = seq_format_beat_drag(value)
  local tw, th = r.ImGui_CalcTextSize(ctx, text)
  tw, th = tw or 40.0, th or 12.0
  local tx = x + (w - tw) * 0.5
  local ty = y + (h - th) * 0.5
  r.ImGui_DrawList_AddText(dl, tx + 1, ty + 1, 0x00000099, text)
  r.ImGui_DrawList_AddText(dl, tx, ty, 0xF4F0E8FF, text)
  return changed, value, active
end

function seq_random_range_control(id, dl, x, y, w, h, lo, hi, min_v, max_v, alpha, opts)
  opts = opts or {}
  w = math.max(64.0, w or 120.0)
  h = math.max(16.0, h or 20.0)
  min_v = min_v or 0.0
  max_v = max_v or 1.0
  if max_v <= min_v then max_v = min_v + 1.0 end
  alpha = alpha or 170
  local step = opts.step
  local snap = opts.snap
  local snap_free = opts.shift_free and is_shift_down and is_shift_down()
  local function apply_snap(v)
    if snap and (not snap_free) then
      v = snap(v)
    elseif step and step > 0 then
      v = min_v + math.floor((v - min_v) / step + 0.5) * step
    end
    if v < min_v then v = min_v elseif v > max_v then v = max_v end
    return v
  end
  lo, hi = seq_normalize_range(lo, hi, min_v, max_v)
  if (step and step > 0) or (snap and not snap_free) then
    lo, hi = apply_snap(lo), apply_snap(hi)
    lo, hi = seq_normalize_range(lo, hi, min_v, max_v)
  end

  local caption = opts.caption
  local cap_w = 0.0
  if caption and caption ~= "" then
    local ctw = select(1, r.ImGui_CalcTextSize(ctx, caption)) or 24.0
    cap_w = math.max(34.0, ctw + 14.0)
  end
  local ctrl_x = x + cap_w
  local ctrl_w = math.max(28.0, w - cap_w)

  r.ImGui_SetCursorScreenPos(ctx, ctrl_x, y)
  r.ImGui_InvisibleButton(ctx, id, ctrl_w, h)
  local active = r.ImGui_IsItemActive(ctx)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local mx, my = r.ImGui_GetMousePos(ctx)
  local over = mx and my and mx >= x and mx <= x + w and my >= y and my <= y + h
  local fine = seq_fine_drag_down()
  if (hovered or over) and opts.tooltip and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, opts.tooltip)
  end
  local changed = false
  local span = max_v - min_v
  local to_norm = opts.to_norm
  local from_norm = opts.from_norm
  local function norm_at(px)
    local t = (px - ctrl_x) / math.max(1.0, ctrl_w)
    if t < 0 then t = 0 elseif t > 1 then t = 1 end
    return t
  end
  local function value_from_norm(t, skip_snap)
    local v = from_norm and from_norm(t) or (min_v + t * span)
    if skip_snap then
      if v < min_v then v = min_v elseif v > max_v then v = max_v end
      return v
    end
    return apply_snap(v)
  end
  local function value_at(px)
    return value_from_norm(norm_at(px))
  end
  local function norm_from_value(v)
    if to_norm then
      local t = to_norm(v)
      if t < 0 then t = 0 elseif t > 1 then t = 1 end
      return t
    end
    return (v - min_v) / span
  end
  local function x_at(v)
    return ctrl_x + norm_from_value(v) * ctrl_w
  end

  -- Geometric hit: InvisibleButton is left-click only, and mouse-down can hitch.
  local right_reset = over and (seq_imgui_right_released() or seq_imgui_right_clicked())
  if right_reset then
    local rlo = opts.reset_lo
    local rhi = opts.reset_hi
    if rlo == nil then rlo = min_v end
    if rhi == nil then rhi = rlo end
    lo, hi = seq_normalize_range(rlo, rhi, min_v, max_v)
    if (step and step > 0) or (snap and not snap_free) then
      lo, hi = apply_snap(lo), apply_snap(hi)
      lo, hi = seq_normalize_range(lo, hi, min_v, max_v)
    end
    changed = true
    state.seq_random_knob_drag = nil
  elseif active and not (r.ImGui_IsMouseDown and r.ImGui_IsMouseDown(ctx, 1)) then
    local mx = r.ImGui_GetMousePos(ctx)
    mx = mx or x
    if (not state.seq_random_knob_drag) or state.seq_random_knob_drag.id ~= id then
      local lo_x, hi_x = x_at(lo), x_at(hi)
      local unified = seq_range_is_single(lo, hi, (step or span * 0.02) * 0.6)
      local handle = "body"
      if unified then
        -- First move away from the collapsed value opens the range again.
        handle = "split"
      elseif math.abs(mx - lo_x) <= 8.0 and math.abs(mx - lo_x) <= math.abs(mx - hi_x) then
        handle = "lo"
      elseif math.abs(mx - hi_x) <= 8.0 then
        handle = "hi"
      end
      state.seq_random_knob_drag = {
        id = id, handle = handle, start_lo = lo, start_hi = hi, start_mx = mx, fine = fine,
      }
    end
    local drag = state.seq_random_knob_drag
    if drag.fine ~= fine then
      drag.start_lo, drag.start_hi = lo, hi
      drag.start_mx = mx
      drag.fine = fine
    end
    local scale = fine and SEQ_FINE_DRAG_SCALE or 1.0
    local function fine_or_abs(start_v)
      if fine then
        local dt = (norm_at(mx) - norm_at(drag.start_mx or mx)) * scale
        return value_from_norm(norm_from_value(start_v) + dt, true)
      end
      return value_at(mx)
    end
    local v = fine_or_abs((drag.handle == "hi") and (drag.start_hi or hi) or (drag.start_lo or lo))
    if drag.handle == "split" then
      local start = drag.start_lo or lo
      if v < start then
        lo, hi = v, start
        drag.handle = "lo"
      elseif v > start then
        lo, hi = start, v
        drag.handle = "hi"
      else
        lo, hi = start, start
      end
    elseif drag.handle == "lo" then
      lo = math.min(v, hi)
    elseif drag.handle == "hi" then
      hi = math.max(v, lo)
    elseif to_norm and from_norm then
      local dt = (norm_at(mx) - norm_at(drag.start_mx or mx)) * scale
      local width_t = norm_from_value(drag.start_hi or hi) - norm_from_value(drag.start_lo or lo)
      local nlo_t = norm_from_value(drag.start_lo or lo) + dt
      if nlo_t < 0.0 then nlo_t = 0.0 end
      if nlo_t + width_t > 1.0 then nlo_t = 1.0 - width_t end
      lo, hi = value_from_norm(nlo_t, fine), value_from_norm(nlo_t + width_t, fine)
    else
      local dv
      if fine then
        dv = (norm_at(mx) - norm_at(drag.start_mx or mx)) * span * scale
      else
        dv = value_at(mx) - value_at(drag.start_mx or mx)
      end
      local nlo = (drag.start_lo or lo) + dv
      local nhi = (drag.start_hi or hi) + dv
      local width = (drag.start_hi or hi) - (drag.start_lo or lo)
      if nlo < min_v then nlo, nhi = min_v, min_v + width end
      if nhi > max_v then nhi, nlo = max_v, max_v - width end
      lo, hi = seq_normalize_range(nlo, nhi, min_v, max_v)
    end
    if not fine then
      lo, hi = apply_snap(lo), apply_snap(hi)
    end
    lo, hi = seq_normalize_range(lo, hi, min_v, max_v)
    changed = true
  elseif state.seq_random_knob_drag and state.seq_random_knob_drag.id == id then
    state.seq_random_knob_drag = nil
  end

  local bg = build_color_rrgbbaa(28, 34, 46, alpha)
  local edge = hovered and UI_THEME.accent or build_color_rrgbbaa(90, 108, 132, math.min(255, alpha + 40))
  ui_draw_panel(dl, x, y, x + w, y + h, 5.0, bg, edge, hovered, active)
  if cap_w > 0 then
    r.ImGui_DrawList_AddRectFilled(dl, x + 3.0, y + 3.0, x + cap_w - 2.0, y + h - 3.0, 0x000000AA, 4.0)
    local ctw, cth = r.ImGui_CalcTextSize(ctx, caption)
    ctw, cth = ctw or 20.0, cth or 12.0
    r.ImGui_DrawList_AddText(dl, x + (cap_w - ctw) * 0.5, y + (h - cth) * 0.5, 0xF4F0E8FF, caption)
  end
  local lo_x, hi_x = x_at(lo), x_at(hi)
  r.ImGui_DrawList_AddRectFilled(dl, lo_x, y + 4.0, math.max(lo_x + 2.0, hi_x), y + h - 4.0, 0xFFE7A688, 3.0)
  local unified = seq_range_is_single(lo, hi, (step or span * 0.02) * 0.6)
  local function thumb(px)
    r.ImGui_DrawList_AddRectFilled(dl, px - 3.0, y + 2.0, px + 3.0, y + h - 2.0, 0xFFE7A6FF, 2.0)
  end
  thumb(lo_x)
  if not unified then
    thumb(hi_x)
  end
  local label = opts.format and opts.format(lo, hi) or string.format("%.2f–%.2f", lo, hi)
  local tw, th = r.ImGui_CalcTextSize(ctx, label)
  tw, th = tw or 24.0, th or 12.0
  local tx = ctrl_x + (ctrl_w - tw) * 0.5
  local ty = y + (h - th) * 0.5
  r.ImGui_DrawList_AddText(dl, tx + 1, ty + 1, 0x00000099, label)
  r.ImGui_DrawList_AddText(dl, tx, ty, 0xF4F0E8FF, label)
  return changed, lo, hi, active
end

function seq_draw_random_caption(dl, x, y, w, text, color)
  if not text or text == "" then
    return
  end
  local tw = select(1, r.ImGui_CalcTextSize(ctx, text)) or 8.0
  r.ImGui_DrawList_AddText(dl, x + (w - tw) * 0.5, y, color or UI_THEME.text_dim, text)
end

function seq_get_lane_random_layout(row_pos, timeline_x0)
  local y0 = row_pos.y0
  local y1 = row_pos.y1
  local lane_h = y1 - y0
  local defs = {
    { id = "prob",  label = "Prob", short = "P", has_seed = true },
    { id = "human", label = "Hum",  short = "H", has_seed = true },
    { id = "vel",   label = "Vel",  short = "V", has_seed = true },
    { id = "vary",  label = "Vary", short = "Y", has_seed = true, has_refresh = true },
    { id = "stut",  label = "Stut", short = "S", has_seed = true },
    { id = "grace", label = "Grace", short = "G", has_seed = true },
    { id = "after", label = "After", short = "A", has_seed = true },
  }

  local mode, two_row, show_labels, show_seeds
  if lane_h >= 100 then
    mode, two_row = "xlarge", true
    show_labels, show_seeds = true, true
  elseif lane_h >= 72 then
    mode, two_row = "tall", false
    show_labels, show_seeds = true, true
  elseif lane_h >= 50 then
    mode, two_row = "medium", false
    show_labels, show_seeds = true, true
  else
    mode, two_row = "compact", false
    show_labels, show_seeds = lane_h >= 34, lane_h >= 42
  end

  local label_h, seed_h, seed_w, v_gap, gap_x, group_gap
  if mode == "xlarge" then
    label_h, seed_h, seed_w, v_gap, gap_x, group_gap = 13.0, 13.0, 15.0, 3.0, 6.0, 16.0
  elseif mode == "tall" then
    label_h, seed_h, seed_w, v_gap, gap_x, group_gap = 12.0, 12.0, 14.0, 2.0, 5.0, 12.0
  elseif mode == "medium" then
    label_h, seed_h, seed_w, v_gap, gap_x, group_gap = 11.0, 11.0, 13.0, 1.0, 4.0, 10.0
  else
    label_h, seed_h, seed_w, v_gap, gap_x, group_gap = 10.0, 10.0, 12.0, 1.0, 3.0, 8.0
  end

  local pad_x, pad_y = 8.0, 3.0
  local panel_x0 = timeline_x0 + 6.0
  local panel_y0 = y0 + 2.0
  local panel_y1 = y1 - 2.0
  local row_h = two_row and ((panel_y1 - panel_y0 - 4.0) * 0.5) or (panel_y1 - panel_y0 - pad_y * 2.0)

  local extra = 0.0
  if show_labels then extra = extra + label_h + v_gap end
  if show_seeds then extra = extra + seed_h + v_gap end
  local knob_size = math.max(14.0, math.min(mode == "xlarge" and 36.0 or (mode == "tall" and 30.0 or (mode == "medium" and 26.0 or 20.0)), row_h - extra))

  local use_short = (mode == "compact")
  local groups = {}

  local function group_width(def)
    local label = use_short and def.short or def.label
    local tw = select(1, r.ImGui_CalcTextSize(ctx, label)) or 16.0
    local seed_row = 0.0
    if show_seeds and def.has_seed then
      seed_row = seed_w
      if def.has_refresh then
        seed_row = seed_w * 2.0 + 2.0
      end
    end
    return math.max(knob_size, show_labels and (tw + 4.0) or 0.0, seed_row)
  end

  local function place_row(ids, row_y0, row_y1)
    local x = panel_x0 + pad_x
    local avail_h = row_y1 - row_y0
    for _, id in ipairs(ids) do
      local def
      for _, d in ipairs(defs) do
        if d.id == id then def = d break end
      end
      local col_w = group_width(def)
      local label_text = use_short and def.short or def.label
      local g = {
        id = def.id,
        label = label_text,
        has_seed = show_seeds and def.has_seed,
        has_refresh = show_seeds and def.has_refresh,
        col_x = x,
        col_w = col_w,
      }
      local stack = knob_size
      if show_labels then stack = stack + v_gap + label_h end
      if g.has_seed then stack = stack + v_gap + seed_h end
      local cursor = row_y0 + math.max(0.0, (avail_h - stack) * 0.5)
      local labels_on_top = (mode == "tall" or mode == "xlarge")

      if show_labels and labels_on_top then
        g.label_x, g.label_y, g.label_w = x, cursor, col_w
        cursor = cursor + label_h + v_gap
      end

      g.knob_x = x + (col_w - knob_size) * 0.5
      g.knob_y = cursor
      cursor = cursor + knob_size

      if show_labels and not labels_on_top then
        cursor = cursor + v_gap
        g.label_x, g.label_y, g.label_w = x, cursor, col_w
        cursor = cursor + label_h
      end

      if g.has_seed or g.has_refresh then
        cursor = cursor + v_gap
        local btn_n = (g.has_seed and 1 or 0) + (g.has_refresh and 1 or 0)
        local row_w = btn_n * seed_w + math.max(0, btn_n - 1) * 2.0
        local bx = x + (col_w - row_w) * 0.5
        if g.has_seed then
          g.seed_x = bx
          g.seed_y = cursor
          bx = bx + seed_w + 2.0
        end
        if g.has_refresh then
          g.refresh_x = bx
          g.refresh_y = cursor
        end
      end

      groups[def.id] = g
      x = x + col_w + group_gap
    end
    return x - group_gap
  end

  local row_right
  if two_row then
    local mid = panel_y0 + (panel_y1 - panel_y0) * 0.5
    local r1 = place_row({ "prob", "human", "vel", "vary" }, panel_y0 + pad_y, mid - 2.0)
    local r2 = place_row({ "stut", "grace", "after" }, mid + 2.0, panel_y1 - pad_y)
    row_right = math.max(r1, r2)
  else
    row_right = place_row({ "prob", "human", "vel", "vary", "stut", "grace", "after" }, panel_y0 + pad_y, panel_y1 - pad_y)
  end

  return {
    mode = mode,
    knob_size = knob_size,
    seed_w = seed_w,
    seed_h = seed_h,
    show_labels = show_labels,
    show_seeds = show_seeds,
    panel_x0 = panel_x0,
    panel_y0 = panel_y0,
    panel_x1 = row_right + pad_x,
    panel_y1 = panel_y1,
    groups = groups,
  }
end

function seq_lane_random_controls_hit(row_pos, mx, my, timeline_x0, clip_y0, clip_y1)
  if not row_pos or not row_pos.row or row_pos.row.type ~= "note" then
    return false
  end
  if seq_random_flyout_hit(mx, my) then
    return true
  end
  if clip_y0 and my < clip_y0 then
    return false
  end
  if clip_y1 and my > clip_y1 then
    return false
  end
  local ui = seq_get_lane_random_layout(row_pos, timeline_x0)
  return mx >= ui.panel_x0 and mx <= ui.panel_x1 and my >= ui.panel_y0 and my <= ui.panel_y1
end

function seq_render_lane_random_controls(dl, row_pos, slot_id, random_settings, focus_key, timeline_x0, clip_y0, clip_y1)
  if clip_y0 and clip_y1 and (row_pos.y1 <= clip_y0 or row_pos.y0 >= clip_y1) then
    return false, nil, nil, nil, false
  end
  local ui = seq_get_lane_random_layout(row_pos, timeline_x0)
  local bg = build_color_rrgbbaa(12, 16, 24, 236)
  local edge = build_color_rrgbbaa(72, 90, 114, 220)
  local clipped = false
  if clip_y0 and clip_y1 and r.ImGui_DrawList_PushClipRect then
    r.ImGui_DrawList_PushClipRect(
      dl,
      ui.panel_x0,
      math.max(ui.panel_y0, clip_y0),
      ui.panel_x1,
      math.min(ui.panel_y1, clip_y1),
      true
    )
    clipped = true
  end
  ui_draw_panel(dl, ui.panel_x0, ui.panel_y0, ui.panel_x1, ui.panel_y1, 6.0, bg, edge, false, false)

  local changed = false
  local reseeded = false
  local active_key = nil
  local overlay_text = nil
  local caption_color = UI_THEME.text_dim
  local specs = {
    {
      id = "prob",
      key = "rand_prob_" .. slot_id,
      family = nil,
      value = random_settings.probability or 1.0,
      min_v = 0.0, max_v = 1.0,
      knob_id = "##seq_lane_prob_knob_" .. slot_id,
      seed_id = "##seq_lane_prob_seed_" .. slot_id,
      tooltip = "Chance this hit plays",
      overlay = function(v) return string.format("Prob %.2f", v) end,
      apply = function(v) random_settings.probability = v end,
      reseed = function() random_settings.probability_seed = seq_new_seed() end,
    },
    {
      id = "human",
      key = "rand_human_" .. slot_id,
      family = nil,
      value = random_settings.humanize_ms or 0.0,
      min_v = 0.0, max_v = 50.0,
      knob_id = "##seq_lane_human_knob_" .. slot_id,
      seed_id = "##seq_lane_human_seed_" .. slot_id,
      tooltip = "Timing humanize (ms). Hover for pitch, stretch, length, and early/late range.",
      overlay = function(v) return string.format("Human %.1f ms", v) end,
      apply = function(v) seq_humanize_sync_time_from_knob(random_settings, v) end,
      reseed = function() random_settings.humanize_seed = seq_new_seed() end,
      flyout = "human",
    },
    {
      id = "vel",
      key = "rand_vel_" .. slot_id,
      value = random_settings.humanize_vel or 0.0,
      min_v = 0.0, max_v = 1.0,
      knob_id = "##seq_lane_vel_knob_" .. slot_id,
      seed_id = "##seq_lane_vel_seed_" .. slot_id,
      tooltip = "Velocity humanize amount",
      overlay = function(v) return string.format("Vel %.2f", v) end,
      apply = function(v) random_settings.humanize_vel = v end,
      reseed = function() random_settings.humanize_vel_seed = seq_new_seed() end,
      flyout = "vel",
    },
    {
      id = "vary",
      key = "rand_vary_" .. slot_id,
      value = random_settings.vary_prob or 0.0,
      min_v = 0.0, max_v = 1.0,
      knob_id = "##seq_lane_vary_knob_" .. slot_id,
      seed_id = "##seq_lane_vary_seed_" .. slot_id,
      tooltip = "Chance this hit uses a varied sample",
      overlay = function(v) return string.format("Vary %.2f", v) end,
      apply = function(v) random_settings.vary_prob = v end,
      reseed = function() random_settings.vary_seed = seq_new_seed() end,
      refresh = function() random_settings.vary_swap_seed = seq_new_seed() end,
      flyout = "vary",
    },
    {
      id = "stut",
      key = "rand_stut_" .. slot_id,
      value = random_settings.stutter_prob or 0.0,
      min_v = 0.0, max_v = 1.0,
      knob_id = "##seq_lane_stut_knob_" .. slot_id,
      seed_id = "##seq_lane_stut_seed_" .. slot_id,
      tooltip = "Chance this hit stutters",
      overlay = function(v) return string.format("Stut %.2f", v) end,
      apply = function(v) random_settings.stutter_prob = v end,
      reseed = function() random_settings.stutter_seed = seq_new_seed() end,
      flyout = "stut",
    },
    {
      id = "grace",
      key = "rand_grace_" .. slot_id,
      value = random_settings.ghost_grace or 0.0,
      min_v = 0.0, max_v = 1.0,
      knob_id = "##seq_lane_grace_knob_" .. slot_id,
      seed_id = "##seq_lane_grace_seed_" .. slot_id,
      tooltip = "Chance of a quiet grace note before the hit",
      overlay = function(v) return string.format("Grace %.2f", v) end,
      apply = function(v) random_settings.ghost_grace = v end,
      reseed = function() random_settings.ghost_grace_seed = seq_new_seed() end,
      flyout = "grace",
    },
    {
      id = "after",
      key = "rand_after_" .. slot_id,
      value = random_settings.ghost_after or 0.0,
      min_v = 0.0, max_v = 1.0,
      knob_id = "##seq_lane_after_knob_" .. slot_id,
      seed_id = "##seq_lane_after_seed_" .. slot_id,
      tooltip = "Chance of a quiet note after the hit",
      overlay = function(v) return string.format("After %.2f", v) end,
      apply = function(v) random_settings.ghost_after = v end,
      reseed = function() random_settings.ghost_after_seed = seq_new_seed() end,
      flyout = "after",
    },
  }

  local function widget_in_clip(y, h)
    if not clip_y0 or not clip_y1 then
      return true
    end
    return (y + (h or 0)) > clip_y0 + 0.5 and y < clip_y1 - 0.5
  end

  for _, spec in ipairs(specs) do
    local g = ui.groups[spec.id]
    if g and widget_in_clip(g.knob_y, ui.knob_size) then
      local alpha = seq_random_control_alpha(focus_key, spec.key)
      if g.label_x then
        seq_draw_random_caption(dl, g.label_x, g.label_y, g.label_w, g.label, caption_color)
      end
      local knob_changed, knob_value, knob_active = seq_random_knob_control(
        spec.knob_id, dl, g.knob_x, g.knob_y, ui.knob_size,
        spec.value, spec.min_v, spec.max_v, alpha, spec.flyout and nil or spec.tooltip
      )
      local knob_hovered = r.ImGui_IsItemHovered(ctx)
      if knob_changed then
        spec.apply(knob_value)
        changed = true
      end
      if knob_active then
        active_key = spec.key
        overlay_text = spec.overlay(knob_value or spec.value)
      end
      if spec.flyout and (knob_hovered or knob_active) then
        seq_random_flyout_pin(spec.flyout, slot_id, {
          x = g.knob_x, y = g.knob_y, w = ui.knob_size, h = ui.knob_size,
          label_y = g.label_y,
        }, "lane")
      end
      if g.has_seed and g.seed_x then
        if seq_random_seed_button(spec.seed_id, dl, g.seed_x, g.seed_y, ui.seed_w, ui.seed_h, alpha) then
          if seq_apply_reseed_with_undo(spec.reseed) then
            reseeded = true
          else
            changed = true
          end
        end
      end
      if g.has_refresh and g.refresh_x and spec.refresh then
        if seq_random_refresh_button(spec.knob_id .. "_refresh", dl, g.refresh_x, g.refresh_y, ui.seed_w, ui.seed_h, alpha) then
          if seq_apply_reseed_with_undo(spec.refresh) then
            reseeded = true
          else
            changed = true
          end
        end
      end
    end
  end

  if clipped and r.ImGui_DrawList_PopClipRect then
    r.ImGui_DrawList_PopClipRect(dl)
  end
  return changed, active_key, overlay_text, ui.panel_x1, reseeded
end

SEQ_RANDOM_POPUP_DELAY = 0.34
SEQ_RANDOM_FLYOUT_HOLD = 0.12
SEQ_RANDOM_LABEL_H = 14.0
SEQ_RANDOM_CHIPS_MAX_FRAC = 0.40

function seq_region_random_chip_width(text, pad_x)
  local tw = select(1, r.ImGui_CalcTextSize(ctx, text)) or 8.0
  return math.max(12.0, tw + (pad_x or 4.0) * 2.0)
end

function seq_region_random_label_layout(rx0, rx1, y0, region_lane_h, has_prob, has_human, has_vel, has_vary, has_stut, has_ghost, has_grace, has_after)
  local labels = {}
  has_grace = has_grace or false
  has_after = has_after or false
  if has_ghost and not has_grace and not has_after then
    has_grace, has_after = true, true
  end
  if not has_prob and not has_human and not has_vel and not has_vary and not has_stut and not has_grace and not has_after then
    return labels
  end
  local vis_w = (rx1 or 0) - (rx0 or 0)
  if vis_w < 18.0 then
    return labels
  end
  local chip_h = math.min(SEQ_RANDOM_LABEL_H, math.max(11.0, (region_lane_h or 22.0) - 8.0))
  local chip_y = y0 + ((region_lane_h or 22.0) - chip_h) * 0.5
  local use_full = vis_w >= 200.0
  local pad_x = 4.0
  local gap = 3.0
  local x = rx1 - 7.0
  local min_x = (rx0 or 0) + 4.0

  local specs = {}
  if has_prob then specs[#specs + 1] = { kind = "prob", full = "Prob", short = "P" } end
  if has_human then specs[#specs + 1] = { kind = "human", full = "Hum", short = "H" } end
  if has_vel then specs[#specs + 1] = { kind = "vel", full = "Vel", short = "V" } end
  if has_vary then specs[#specs + 1] = { kind = "vary", full = "Vary", short = "Y" } end
  if has_stut then specs[#specs + 1] = { kind = "stut", full = "Stut", short = "S" } end
  if has_grace then specs[#specs + 1] = { kind = "grace", full = "Grace", short = "G" } end
  if has_after then specs[#specs + 1] = { kind = "after", full = "After", short = "A" } end

  local function chips_width(full)
    local w = 0.0
    for i, spec in ipairs(specs) do
      w = w + seq_region_random_chip_width(full and spec.full or spec.short, pad_x)
      if i < #specs then
        w = w + gap
      end
    end
    return w
  end

  -- Collapse to one control when even the compact chips eat too much of the region.
  local collapse = #specs > 1 and (chips_width(false) / vis_w) > SEQ_RANDOM_CHIPS_MAX_FRAC
  if collapse then
    use_full = vis_w >= 52.0
    specs = { { kind = "all", full = "Rand", short = "R" } }
  elseif use_full and (chips_width(true) / vis_w) > SEQ_RANDOM_CHIPS_MAX_FRAC then
    use_full = false
  end

  local function add_label(kind, text)
    local w = seq_region_random_chip_width(text, pad_x)
    if x - w < min_x then
      return false
    end
    x = x - w
    labels[#labels + 1] = {
      kind = kind,
      text = text,
      x0 = x,
      y0 = chip_y,
      x1 = x + w,
      y1 = chip_y + chip_h,
    }
    x = x - gap
    return true
  end

  -- Right-to-left so After sits on the far right. Stop when a chip would
  -- leave the visible region (e.g. after horizontal scroll clips the left).
  for i = #specs, 1, -1 do
    local spec = specs[i]
    if not add_label(spec.kind, use_full and spec.full or spec.short) then
      break
    end
  end
  local ordered = {}
  for i = #labels, 1, -1 do
    ordered[#ordered + 1] = labels[i]
  end
  return ordered
end

function seq_draw_region_random_labels(dl, labels, mx, my)
  if not labels or #labels == 0 then
    return
  end
  for _, lab in ipairs(labels) do
    local hovered = mx >= lab.x0 and mx <= lab.x1 and my >= lab.y0 and my <= lab.y1
    local fill, edge, text
    if lab.kind == "all" then
      fill = hovered and 0xF2C15AFF or 0xC8942EEE
      edge = hovered and 0xFFF4D0FF or 0xF0D090CC
      text = 0x1A1208FF
    elseif lab.kind == "prob" then
      fill = hovered and 0x4EC4D8FF or 0x2A8A9CEE
      edge = hovered and 0xD8F6FFFF or 0x8ED4E8CC
      text = 0xFFFFFFFF
    elseif lab.kind == "vel" then
      fill = hovered and 0x7EE0A8FF or 0x3CAA6EEE
      edge = hovered and 0xD8FFE8FF or 0x8ED4A8CC
      text = 0x0A180CFF
    elseif lab.kind == "vary" then
      fill = hovered and 0x9FE88FFF or 0x4CAA5EEE
      edge = hovered and 0xD8FFD0FF or 0x8ED48CCC
      text = 0x0A180CFF
    elseif lab.kind == "stut" then
      fill = hovered and 0xD0B8FFFF or 0x8A68C8EE
      edge = hovered and 0xF0E4FFFF or 0xC9A8FFCC
      text = 0x140C20FF
    elseif lab.kind == "grace" then
      fill = hovered and 0xD4DCE8FF or 0x8A96A8EE
      edge = hovered and 0xF0F4FAFF or 0xC4CCD8CC
      text = 0x10141CFF
    elseif lab.kind == "after" then
      fill = hovered and 0xC8D4E8FF or 0x6E7E96EE
      edge = hovered and 0xE8F0FAFF or 0xB0BCC8CC
      text = 0x10141CFF
    else
      fill = hovered and 0xF0C86AFF or 0xC4A04AEE
      edge = hovered and 0xFFF3C8FF or 0xE8D090CC
      text = 0x1A1208FF
    end
    r.ImGui_DrawList_AddRectFilled(dl, lab.x0, lab.y0, lab.x1, lab.y1, fill, 3.0)
    r.ImGui_DrawList_AddRect(dl, lab.x0, lab.y0, lab.x1, lab.y1, edge, 3.0, 0, 1.0)
    local tw, th = r.ImGui_CalcTextSize(ctx, lab.text)
    r.ImGui_DrawList_AddText(
      dl,
      lab.x0 + (lab.x1 - lab.x0 - (tw or 8)) * 0.5,
      lab.y0 + (lab.y1 - lab.y0 - (th or 12)) * 0.5,
      text,
      lab.text
    )
  end
end

function seq_find_track_slot_by_id(track_id)
  for _, slot in ipairs(state.seq_tracks or {}) do
    if slot.id == track_id then
      return slot
    end
  end
  return nil
end

function seq_open_region_random_popup(region, snapshot)
  if not region then
    return
  end
  state.seq_random_popup_region_id = region.id
  state.seq_random_popup_snapshot = snapshot or seq_snapshot_region_random_popup(region)
  state.seq_random_popup_pending = nil
  state.seq_random_popup_close = false
  if not state.seq_random_popup_snapshot or #state.seq_random_popup_snapshot == 0 then
    return
  end
  r.ImGui_OpenPopup(ctx, "seq_region_random_popup")
end

function seq_random_flyout_now()
  return (r.time_precise and r.time_precise()) or os.clock()
end

function seq_random_flyout_begin_frame(host)
  local f = state.seq_random_flyout
  if f and ((not host) or f.host == host) then
    f.pinned = false
  end
end

function seq_random_flyout_pin(kind, slot_id, anchor, host)
  if not kind or not slot_id then
    return
  end
  local f = state.seq_random_flyout
  if (not f) or f.kind ~= kind or f.slot_id ~= slot_id then
    f = { kind = kind, slot_id = slot_id }
    state.seq_random_flyout = f
  end
  f.kind = kind
  f.slot_id = slot_id
  f.anchor = anchor or f.anchor
  f.host = host or f.host or "lane"
  f.hold_until = nil
  f.pinned = true
  if not f.rect then
    local fw, fh = seq_random_flyout_size(kind)
    local rx0, ry0, rx1, ry1 = seq_random_flyout_place(anchor or f.anchor, fw, fh)
    f.rect = { x0 = rx0, y0 = ry0, x1 = rx1, y1 = ry1 }
  end
end

function seq_random_flyout_hit(mx, my)
  local f = state.seq_random_flyout
  local rect = f and f.rect
  if not rect or not mx or not my then
    return false
  end
  local pad = 2.0
  return mx >= rect.x0 - pad and mx <= rect.x1 + pad and my >= rect.y0 - pad and my <= rect.y1 + pad
end

function seq_random_flyout_size(kind, settings)
  if kind == "human" then
    local rows = 4
    if settings and seq_settings_humanize_len_active(settings) then
      rows = 5
    end
    return 196.0, rows * 20.0 + (rows - 1) * 1.0 + 2.0
  end
  if kind == "grace" or kind == "after" then
    return 176.0, 85.0
  end
  if kind == "stut" then
    return 176.0, 41.0
  end
  -- Keep this at ImGui's default min window height so a transparent overlay
  -- cannot be inflated downward over Vel/Vary when labels sit below the knobs.
  return 168.0, 32.0
end

function seq_random_flyout_place(anchor, w, h)
  local gap = 3.0
  local ax = (anchor and anchor.x) or 0.0
  local ay = (anchor and anchor.y) or 0.0
  local aw = (anchor and anchor.w) or 24.0
  local ah = (anchor and anchor.h) or aw
  local x0 = ax + aw * 0.5 - w * 0.5
  -- Sit on the label row when labels are above the knob; otherwise on the knob top.
  local label_y = anchor and anchor.label_y
  local above_bottom = ay
  if type(label_y) == "number" and label_y < ay then
    above_bottom = label_y
  end
  local y_above = above_bottom - gap - h
  local y_below = ay + ah + gap

  local win_x, win_y = r.ImGui_GetWindowPos(ctx)
  local win_w, win_h = r.ImGui_GetWindowSize(ctx)
  win_x, win_y = win_x or 0.0, win_y or 0.0
  win_w, win_h = win_w or 800.0, win_h or 600.0

  -- ImGui clamps top-level overlay windows to the host viewport. If we ask
  -- for a rect above the first-lane knobs at low zoom, that clamp slides the
  -- (transparent) window down over V/Y and eats their upper-half drags.
  local top_limit = win_y + 4.0
  local wr = state.main_window_rect
  if wr and wr.y then
    top_limit = math.max(top_limit, wr.y + 4.0)
  end
  local map = state.seq_map_rect
  if map and map.y then
    top_limit = math.max(top_limit, (map.y or 0) + 2.0)
  end

  local y0 = y_above
  local force_below = (anchor and anchor.force_below) or (state.seq_random_flyout and state.seq_random_flyout.force_below)
  if force_below then
    y0 = y_below
  elseif y_above < top_limit then
    y0 = y_below
  end

  if x0 < win_x + 6.0 then
    x0 = win_x + 6.0
  end
  if x0 + w > win_x + win_w - 6.0 then
    x0 = win_x + win_w - 6.0 - w
  end
  return x0, y0, x0 + w, y0 + h
end

function seq_render_random_flyout_body(dl, kind, settings, id_prefix, x, y, w)
  local gap = 1.0
  local row_h = 22.0
  local knob_sz = 20.0
  local cy = y
  local changed = false
  local active_any = false

  if kind == "human" then
    local p_lo, p_hi = seq_normalize_range(settings.humanize_pitch_min or 0.0, settings.humanize_pitch_max or 0.0, -SEQ_PITCH_HUMANIZE, SEQ_PITCH_HUMANIZE)
    local pch, nplo, nphi, pa = seq_random_range_control(
      id_prefix .. "_pitch", dl, x, cy, w, 20.0,
      p_lo, p_hi, -SEQ_PITCH_HUMANIZE, SEQ_PITCH_HUMANIZE, 210,
      {
        caption = "Pitch",
        step = 0.05,
        format = seq_format_pitch_range,
        to_norm = seq_pitch_range_to_norm,
        from_norm = seq_pitch_range_from_norm,
        reset_lo = 0.0,
        reset_hi = 0.0,
        tooltip = "Pitch randomization in semitones. Center is finer; larger shifts sit toward the edges. Right-click to reset.",
      }
    )
    if pch then settings.humanize_pitch_min, settings.humanize_pitch_max = nplo, nphi changed = true end
    if pa then active_any = true end
    cy = cy + 20.0 + gap

    local s_lo, s_hi = seq_normalize_range(settings.humanize_stretch_min or 1.0, settings.humanize_stretch_max or 1.0, 0.5, 2.0)
    local sch, nslo, nshi, sa = seq_random_range_control(
      id_prefix .. "_stretch", dl, x, cy, w, 20.0,
      s_lo, s_hi, 0.5, 2.0, 210,
      {
        caption = "Strch",
        format = seq_format_stretch_range,
        reset_lo = 1.0,
        reset_hi = 1.0,
        tooltip = "Stretch randomization. Drag an edge for a range. Right-click to reset.",
      }
    )
    if sch then settings.humanize_stretch_min, settings.humanize_stretch_max = nslo, nshi changed = true end
    if sa then active_any = true end
    cy = cy + 20.0 + gap

    local t_lo, t_hi = seq_humanize_time_ms_range(settings)
    local tch, ntlo, nthi, ta = seq_random_range_control(
      id_prefix .. "_time", dl, x, cy, w, 20.0,
      t_lo, t_hi, -SEQ_HUMANIZE_TIME_MS, SEQ_HUMANIZE_TIME_MS, 210,
      {
        caption = "Time",
        step = 1,
        format = seq_format_time_ms_range,
        reset_lo = 0.0,
        reset_hi = 0.0,
        tooltip = "Timing window in ms. Left is early, right is late (up to 500 ms). Right-click to reset.",
      }
    )
    if tch then
      settings.humanize_time_min, settings.humanize_time_max = ntlo, nthi
      settings.humanize_time_is_ms = true
      if math.abs(ntlo) < 0.05 and math.abs(nthi) < 0.05 then
        settings.humanize_ms = 0.0
      end
      changed = true
    end
    if ta then active_any = true end
    cy = cy + 20.0 + gap

    local l_lo, l_hi = seq_normalize_range(settings.humanize_len_min or 1.0, settings.humanize_len_max or 1.0, SEQ_HUMANIZE_LEN_MIN, 1.0)
    local lch, nllo, nlhi, la = seq_random_range_control(
      id_prefix .. "_len", dl, x, cy, w, 20.0,
      l_lo, l_hi, SEQ_HUMANIZE_LEN_MIN, 1.0, 210,
      {
        caption = "Len",
        format = seq_format_len_range,
        reset_lo = 1.0,
        reset_hi = 1.0,
        tooltip = "Length shortening. Items can only get shorter. Drag an edge for a range. Right-click to reset.",
      }
    )
    if lch then settings.humanize_len_min, settings.humanize_len_max = nllo, nlhi changed = true end
    if la then active_any = true end
    cy = cy + 20.0

    if seq_settings_humanize_len_active(settings) then
      cy = cy + gap
      local f_lo, f_hi = seq_normalize_range(settings.humanize_fade_min or 0.0, settings.humanize_fade_max or 0.0, 0.0, SEQ_HUMANIZE_FADE_MS)
      local fch, nflo, nfhi, fa = seq_random_range_control(
        id_prefix .. "_fade", dl, x, cy, w, 20.0,
        f_lo, f_hi, 0.0, SEQ_HUMANIZE_FADE_MS, 210,
        {
          caption = "Fade",
          step = 1,
          format = seq_format_fade_ms_range,
          reset_lo = 0.0,
          reset_hi = 0.0,
          tooltip = "Fade-out window in ms on shortened hits. Drag an edge for a range. Right-click to reset.",
        }
      )
      if fch then settings.humanize_fade_min, settings.humanize_fade_max = nflo, nfhi changed = true end
      if fa then active_any = true end
      cy = cy + 20.0
    end
  end

  if kind == "vel" or kind == "vary" or kind == "stut" or kind == "grace" or kind == "after" then
    local beat_key = (kind == "vel" and "humanize_vel_beat")
      or (kind == "vary" and "vary_beat")
      or (kind == "stut" and "stutter_beat")
      or (kind == "after" and "ghost_after_beat")
      or "ghost_grace_beat"
    local bc, bv, ba = seq_random_beat_drag(
      id_prefix .. "_beat", dl, x, cy, w, 20.0,
      settings[beat_key] or 0.0, 210,
      "Favor this on downbeats or upbeats"
    )
    if bc then settings[beat_key] = bv changed = true end
    if ba then active_any = true end
    cy = cy + 20.0 + gap
  end

  if kind == "stut" then
    local st_lo, st_hi = seq_normalize_range(settings.stutter_min or 2, settings.stutter_max or 4, 2, 16)
    local st_ch, nlo, nhi, st_a = seq_random_range_control(
      id_prefix .. "_hits", dl, x, cy, w, 20.0,
      st_lo, st_hi, 2, 16, 210,
      {
        caption = "Hits",
        step = 1,
        format = seq_format_stutter_range,
        reset_lo = 2,
        reset_hi = 4,
        tooltip = "Min and max stutter hits. Drag an edge for a range. Right-click to reset.",
      }
    )
    if st_ch then settings.stutter_min, settings.stutter_max = nlo, nhi changed = true end
    if st_a then active_any = true end
    cy = cy + 20.0
  elseif kind == "grace" or kind == "after" then
    local keys = seq_ghost_which_keys(kind)
    local clo, chi = seq_ghost_close_range(settings, kind)
    local cch, nclo, nchi, ca = seq_random_range_control(
      id_prefix .. "_close", dl, x, cy, w, 20.0,
      clo, chi, SEQ_GHOST_CLOSE_MIN, SEQ_GHOST_CLOSE_MAX, 210,
      {
        caption = "Close",
        reset_lo = 0.0625,
        reset_hi = 0.125,
        tooltip = "How close this note sits. Drag an edge for a range. Right-click to reset. Snap to musical values; hold Shift for free values.",
        format = seq_format_close_range,
        snap = seq_snap_close_qn,
        shift_free = true,
      }
    )
    if cch then settings[keys.close_min], settings[keys.close_max] = nclo, nchi changed = true end
    if ca then active_any = true end
    cy = cy + 20.0 + gap
    local vlo, vhi = seq_ghost_vol_range(settings, kind)
    local vch_r, nvlo, nvhi, vra = seq_random_range_control(
      id_prefix .. "_vol", dl, x, cy, w, 20.0,
      vlo, vhi, 0.0, 1.0, 210,
      {
        caption = "Vol",
        reset_lo = 0.20,
        reset_hi = 0.40,
        tooltip = "Ghost note volume as a range of the parent note. Drag an edge for a range. Right-click to reset.",
        format = seq_format_vol_range,
      }
    )
    if vch_r then settings[keys.vol_min], settings[keys.vol_max] = nvlo, nvhi changed = true end
    if vra then active_any = true end
    cy = cy + 20.0 + gap
    local vch, vv, va = seq_random_knob_control(
      id_prefix .. "_vary", dl, x, cy, knob_sz,
      settings[keys.vary] or 0.0, 0.0, 1.0, 210,
      "Chance this extra note uses a different sample",
      { caption = "Vary", w = w, h = row_h }
    )
    if vch then settings[keys.vary] = vv changed = true end
    if va then active_any = true end
    cy = cy + row_h
  end

  return changed, active_any, cy - y
end

function seq_render_random_flyout(dl, pattern, host)
  local f = state.seq_random_flyout
  if not f then
    return false
  end
  if host and f.host and f.host ~= host then
    return false
  end
  local now = seq_random_flyout_now()
  if (not f.pinned) and f.hold_until and now >= f.hold_until then
    state.seq_random_flyout = nil
    return false
  end
  local slot = seq_find_track_slot_by_id(f.slot_id)
  local settings = slot and get_seq_track_settings(pattern, slot.id, true)
  if not slot or not settings then
    state.seq_random_flyout = nil
    return false
  end

  local w, h = seq_random_flyout_size(f.kind, settings)
  local x0, y0, x1, y1 = seq_random_flyout_place(f.anchor, w, h)
  f.rect = { x0 = x0, y0 = y0, x1 = x1, y1 = y1 }

  local win_flags = 0
  if r.ImGui_WindowFlags_NoScrollbar then
    win_flags = win_flags | r.ImGui_WindowFlags_NoScrollbar()
  end
  if r.ImGui_WindowFlags_NoScrollWithMouse then
    win_flags = win_flags | r.ImGui_WindowFlags_NoScrollWithMouse()
  end
  if r.ImGui_WindowFlags_NoBackground then
    win_flags = win_flags | r.ImGui_WindowFlags_NoBackground()
  end
  if r.ImGui_WindowFlags_NoTitleBar then
    win_flags = win_flags | r.ImGui_WindowFlags_NoTitleBar()
  end
  if r.ImGui_WindowFlags_NoResize then
    win_flags = win_flags | r.ImGui_WindowFlags_NoResize()
  end
  if r.ImGui_WindowFlags_NoMove then
    win_flags = win_flags | r.ImGui_WindowFlags_NoMove()
  end
  if r.ImGui_WindowFlags_NoSavedSettings then
    win_flags = win_flags | r.ImGui_WindowFlags_NoSavedSettings()
  end
  if r.ImGui_WindowFlags_NoFocusOnAppearing then
    win_flags = win_flags | r.ImGui_WindowFlags_NoFocusOnAppearing()
  end
  if r.ImGui_WindowFlags_NoNav then
    win_flags = win_flags | r.ImGui_WindowFlags_NoNav()
  end

  local mx, my = r.ImGui_GetMousePos(ctx)
  local hover = mx and my and mx >= x0 and mx <= x1 and my >= y0 and my <= y1
  local changed, active = false, false
  local body_id = "##seq_rand_fly_" .. f.kind .. "_" .. tostring(f.slot_id) .. "_" .. (f.host or "lane")
  local use_overlay = (f.host or host) ~= "popup"
  local style_vars = 0

  local function push_flyout_window_style()
    if r.ImGui_StyleVar_WindowPadding then
      r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), 0, 0)
      style_vars = style_vars + 1
    end
    if r.ImGui_StyleVar_WindowBorderSize then
      r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowBorderSize(), 0)
      style_vars = style_vars + 1
    end
    -- Default min size is ~32px. Vel/Vary extras are 22px; the extra invisible
    -- strip was covering the upper half of those knobs at compact lane zoom.
    if r.ImGui_StyleVar_WindowMinSize then
      r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowMinSize(), 1.0, 1.0)
      style_vars = style_vars + 1
    end
  end

  if use_overlay and r.ImGui_SetNextWindowPos and r.ImGui_Begin then
    -- Top-level overlay: the tracks child steals parent hits on every lane
    -- except the first (whose extras overlap the ruler).
    local cond = r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0
    r.ImGui_SetNextWindowPos(ctx, x0, y0, cond)
    if r.ImGui_SetNextWindowSize then
      r.ImGui_SetNextWindowSize(ctx, w, h, cond)
    end
    if r.ImGui_SetNextWindowBgAlpha then
      r.ImGui_SetNextWindowBgAlpha(ctx, 0.0)
    end
    push_flyout_window_style()
    local visible = r.ImGui_Begin(ctx, "##seq_rand_flyout_overlay", true, win_flags)
    local fdl = (r.ImGui_GetWindowDrawList and r.ImGui_GetWindowDrawList(ctx))
      or (r.ImGui_GetForegroundDrawList and r.ImGui_GetForegroundDrawList(ctx))
      or dl
    if visible then
      local wx, wy = r.ImGui_GetWindowPos(ctx)
      local ww, wh = r.ImGui_GetWindowSize(ctx)
      if wx and wy then
        x0, y0 = wx, wy
        x1 = wx + (ww or w)
        y1 = wy + (wh or h)
        f.rect = { x0 = x0, y0 = y0, x1 = x1, y1 = y1 }
      end
      local a = f.anchor
      if a and y1 > (a.y or y1) - 1.0 and y0 < (a.y or 0) + (a.h or 0) then
        f.force_below = true
      end
      changed, active = seq_render_random_flyout_body(fdl, f.kind, settings, body_id, x0, y0, w)
    end
    r.ImGui_End(ctx)
    if style_vars > 0 then
      r.ImGui_PopStyleVar(ctx, style_vars)
    end
  else
    push_flyout_window_style()
    r.ImGui_SetCursorScreenPos(ctx, x0, y0)
    local child_open = r.ImGui_BeginChild(ctx, "##seq_rand_flyout_hit", w, h, 0, win_flags)
    local fdl = (r.ImGui_GetWindowDrawList and r.ImGui_GetWindowDrawList(ctx))
      or (r.ImGui_GetForegroundDrawList and r.ImGui_GetForegroundDrawList(ctx))
      or dl
    if child_open then
      changed, active = seq_render_random_flyout_body(fdl, f.kind, settings, body_id, x0, y0, w)
    end
    imgui_end_child(child_open)
    if style_vars > 0 then
      r.ImGui_PopStyleVar(ctx, style_vars)
    end
  end
  hover = mx and my and mx >= x0 and mx <= x1 and my >= y0 and my <= y1
  local over_knob = false
  local a = f.anchor
  if a and mx and my then
    local ax0, ay0 = a.x or 0.0, a.y or 0.0
    local ax1 = ax0 + (a.w or 0.0)
    local ay1 = ay0 + (a.h or 0.0)
    over_knob = mx >= ax0 and mx <= ax1 and my >= ay0 and my <= ay1
  end
  -- Only the extras panel and its own knob. A union bbox is as wide as Human
  -- extras and would keep that overlay parked over Vel/Vary.
  local near = hover or over_knob
  if (not near) and mx and my then
    local pad = 8.0
    near = (mx >= x0 - pad and mx <= x1 + pad and my >= y0 - pad and my <= y1 + pad)
      or over_knob
  end
  if hover or over_knob or active or f.pinned then
    f.hold_until = nil
    f.pinned = true
  elseif not near then
    state.seq_random_flyout = nil
  elseif not f.hold_until then
    f.hold_until = now + SEQ_RANDOM_FLYOUT_HOLD
  end
  return changed
end

function seq_handle_region_random_label_click(region, kind)
  if not region then
    return
  end
  seq_select_region(region)
  if r.ImGui_IsMouseDoubleClicked(ctx, 0) then
    state.seq_random_popup_pending = nil
    state.seq_random_popup_close = true
    local undo_label = "Reset sequencer humanize"
    if kind == "all" then
      undo_label = "Reset sequencer randomization"
    elseif kind == "prob" then
      undo_label = "Reset sequencer probability"
    elseif kind == "vel" then
      undo_label = "Reset sequencer velocity humanize"
    elseif kind == "vary" then
      undo_label = "Reset sequencer sample variation"
    elseif kind == "stut" then
      undo_label = "Reset sequencer stutter probability"
    elseif kind == "ghost" then
      undo_label = "Reset sequencer ghost notes"
    elseif kind == "grace" then
      undo_label = "Reset sequencer grace notes"
    elseif kind == "after" then
      undo_label = "Reset sequencer after notes"
    end
    local label = begin_seq_undo(undo_label)
    if seq_reset_region_random_settings(region, kind) then
      save_config()
      sync_seq_pattern_regions(region.pattern_id)
    end
    end_seq_undo(label)
  else
    local now = r.time_precise and r.time_precise() or os.clock()
    state.seq_random_popup_pending = {
      region_id = region.id,
      kind = kind,
      time = now,
      snapshot = seq_snapshot_region_random_popup(region),
    }
  end
end

function render_seq_region_random_popup()
  local pending = state.seq_random_popup_pending
  if pending then
    local now = r.time_precise and r.time_precise() or os.clock()
    if (now - (pending.time or now)) >= SEQ_RANDOM_POPUP_DELAY then
      local region = get_seq_region_by_id(pending.region_id)
      if region then
        seq_open_region_random_popup(region, pending.snapshot)
      else
        state.seq_random_popup_pending = nil
      end
    end
  end

  local flags = 0
  if r.ImGui_WindowFlags_NoTitleBar then flags = flags | r.ImGui_WindowFlags_NoTitleBar() end
  if r.ImGui_WindowFlags_NoResize then flags = flags | r.ImGui_WindowFlags_NoResize() end
  if r.ImGui_WindowFlags_NoScrollbar then flags = flags | r.ImGui_WindowFlags_NoScrollbar() end
  if r.ImGui_WindowFlags_NoScrollWithMouse then flags = flags | r.ImGui_WindowFlags_NoScrollWithMouse() end
  if r.ImGui_WindowFlags_AlwaysAutoResize then flags = flags | r.ImGui_WindowFlags_AlwaysAutoResize() end

  local style_colors = 0
  local style_vars = 0
  if r.ImGui_Col_PopupBg then
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_PopupBg(), UI_THEME.popup_bg)
    style_colors = style_colors + 1
  end
  if r.ImGui_Col_Border then
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Border(), UI_THEME.border)
    style_colors = style_colors + 1
  end
  if r.ImGui_StyleVar_WindowPadding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), 0, 0)
    style_vars = style_vars + 1
  end

  local function pop_random_popup_style()
    if style_vars > 0 then r.ImGui_PopStyleVar(ctx, style_vars) end
    if style_colors > 0 then r.ImGui_PopStyleColor(ctx, style_colors) end
  end

  local open = r.ImGui_BeginPopup(ctx, "seq_region_random_popup", flags)
  if not open then
    pop_random_popup_style()
    if not state.seq_random_popup_pending then
      if state.seq_random_popup_region_id then
        state.seq_random_knob_drag = nil
        seq_flush_pending_random_sync()
      end
      state.seq_random_popup_region_id = nil
      state.seq_random_popup_snapshot = nil
      state.seq_random_popup_close = false
      state.seq_random_popup_active_key = nil
    end
    if state.seq_random_flyout and state.seq_random_flyout.host == "popup" then
      state.seq_random_flyout = nil
    end
    return
  end

  if state.seq_random_popup_close then
    state.seq_random_popup_close = false
    r.ImGui_CloseCurrentPopup(ctx)
    r.ImGui_EndPopup(ctx)
    pop_random_popup_style()
    state.seq_random_popup_region_id = nil
    state.seq_random_popup_snapshot = nil
    state.seq_random_popup_active_key = nil
    return
  end

  local region = get_seq_region_by_id(state.seq_random_popup_region_id)
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  if not region or not pattern then
    r.ImGui_CloseCurrentPopup(ctx)
    r.ImGui_EndPopup(ctx)
    pop_random_popup_style()
    state.seq_random_popup_region_id = nil
    state.seq_random_popup_snapshot = nil
    state.seq_random_popup_active_key = nil
    return
  end

  local live_entries = seq_collect_region_random_entries(region)
  local snapshot = state.seq_random_popup_snapshot or {}
  local seen = {}
  local rows = {}
  for _, snap in ipairs(snapshot) do
    seen[snap.track_id] = true
    local slot = seq_find_track_slot_by_id(snap.track_id)
    local settings = slot and get_seq_track_settings(pattern, slot.id, true)
    if slot and settings then
      rows[#rows + 1] = {
        slot = slot,
        settings = settings,
        show_prob = snap.show_prob,
        show_human = snap.show_human,
        show_vel = snap.show_vel,
        show_vary = snap.show_vary,
        show_stut = snap.show_stut,
        show_grace = snap.show_grace or snap.show_ghost,
        show_after = snap.show_after or snap.show_ghost,
        show_ghost = snap.show_ghost,
      }
    end
  end
  for _, entry in ipairs(live_entries) do
    if not seen[entry.slot.id] then
      rows[#rows + 1] = entry
    else
      for _, row in ipairs(rows) do
        if row.slot.id == entry.slot.id then
          row.show_prob = row.show_prob or entry.show_prob
          row.show_human = row.show_human or entry.show_human
          row.show_vel = row.show_vel or entry.show_vel
          row.show_vary = row.show_vary or entry.show_vary
          row.show_stut = row.show_stut or entry.show_stut
          row.show_grace = row.show_grace or entry.show_grace
          row.show_after = row.show_after or entry.show_after
          row.show_ghost = row.show_ghost or entry.show_ghost
          break
        end
      end
    end
  end

  if #rows == 0 then
    r.ImGui_CloseCurrentPopup(ctx)
    r.ImGui_EndPopup(ctx)
    pop_random_popup_style()
    state.seq_random_popup_region_id = nil
    state.seq_random_popup_snapshot = nil
    state.seq_random_popup_active_key = nil
    return
  end

  local pad = 10.0
  local name_h = 16.0
  local caption_h = 13.0
  local knob_size = 28.0
  local seed_h = 13.0
  local seed_w = 15.0
  local value_h = 13.0
  local stack_h = caption_h + 2.0 + knob_size + 2.0 + seed_h + 2.0 + value_h
  local col_w = 54.0
  local col_gap = 10.0
  local track_gap = 10.0
  local popup_dl = r.ImGui_GetWindowDrawList(ctx)
  local origin_x, origin_y = r.ImGui_GetCursorScreenPos(ctx)
  local focus_key = state.seq_random_popup_active_key
  local next_focus = nil
  local content_w = 80.0
  local content_h = pad
  local changed_any = false
  seq_random_flyout_begin_frame("popup")

  for _, row in ipairs(rows) do
    local cols = (row.show_prob and 1 or 0) + (row.show_human and 1 or 0)
      + (row.show_vel and 1 or 0) + (row.show_vary and 1 or 0)       + (row.show_stut and 1 or 0)
      + (row.show_grace and 1 or 0)
      + (row.show_after and 1 or 0)
    if cols < 1 then cols = 1 end
    local name = row.slot.name or ("Track " .. tostring(row.slot.id))
    local name_w = select(1, r.ImGui_CalcTextSize(ctx, name)) or 40.0
    local row_w = math.max(name_w, cols * col_w + math.max(0, cols - 1) * col_gap)
    content_w = math.max(content_w, row_w)
    content_h = content_h + name_h + stack_h + track_gap
  end
  content_h = content_h - track_gap + pad
  content_w = content_w + pad * 2.0

  local y = origin_y + pad
  for row_idx, row in ipairs(rows) do
    local name = row.slot.name or ("Track " .. tostring(row.slot.id))
    r.ImGui_DrawList_AddText(popup_dl, origin_x + pad, y, UI_THEME.text, name)
    y = y + name_h
    local x = origin_x + pad
    local row_changed = false
    local function apply_seed(reseed_fn)
      if seq_apply_reseed_with_undo(reseed_fn) then
        seq_queue_random_sync(region.pattern_id, row.slot.id)
      else
        row_changed = true
      end
    end
    local function render_column(control_key, caption, value_fmt, value, min_v, max_v, knob_id, seed_id, related, flyout_kind, refresh_id)
      local alpha = seq_random_control_alpha(focus_key, control_key, related)
      r.ImGui_DrawList_AddText(popup_dl, x + (col_w - (select(1, r.ImGui_CalcTextSize(ctx, caption)) or 20)) * 0.5, y, UI_THEME.text_dim, caption)
      local knob_x = x + (col_w - knob_size) * 0.5
      local knob_y = y + caption_h + 2.0
      local changed, new_value, active = seq_random_knob_control(
        knob_id, popup_dl, knob_x, knob_y, knob_size, value, min_v, max_v, alpha
      )
      local hovered = r.ImGui_IsItemHovered(ctx)
      if flyout_kind and (hovered or active) then
        seq_random_flyout_pin(flyout_kind, row.slot.id, {
          x = knob_x, y = knob_y, w = knob_size, h = knob_size,
          label_y = y,
        }, "popup")
      end
      local seed_y = knob_y + knob_size + 2.0
      local seed_clicked = false
      local refresh_clicked = false
      local btn_n = (seed_id and 1 or 0) + (refresh_id and 1 or 0)
      local row_w = btn_n * seed_w + math.max(0, btn_n - 1) * 2.0
      local bx = x + (col_w - row_w) * 0.5
      if seed_id then
        seed_clicked = seq_random_seed_button(seed_id, popup_dl, bx, seed_y, seed_w, seed_h, alpha)
        bx = bx + seed_w + 2.0
      end
      if refresh_id then
        refresh_clicked = seq_random_refresh_button(refresh_id, popup_dl, bx, seed_y, seed_w, seed_h, alpha)
      end
      local value_text
      if type(value_fmt) == "function" then
        value_text = value_fmt(new_value or value)
      else
        value_text = string.format(value_fmt, new_value or value)
      end
      r.ImGui_DrawList_AddText(
        popup_dl,
        x + (col_w - (select(1, r.ImGui_CalcTextSize(ctx, value_text)) or 20)) * 0.5,
        seed_y + seed_h + 2.0,
        0xFFE7A6DD,
        value_text
      )
      if active then
        next_focus = control_key
      end
      return changed, new_value, seed_clicked, refresh_clicked
    end

    if row.show_prob then
      local prob_changed, prob_value, prob_seed = render_column(
        "popup_prob_" .. row.slot.id,
        "Prob",
        "%.2f",
        row.settings.probability or 1.0,
        0.0,
        1.0,
        "##seq_popup_prob_knob_" .. region.id .. "_" .. row.slot.id,
        "##seq_popup_prob_seed_" .. region.id .. "_" .. row.slot.id
      )
      if prob_changed then
        row.settings.probability = prob_value
        row_changed = true
      end
      if prob_seed then
        apply_seed(function() row.settings.probability_seed = seq_new_seed() end)
      end
      x = x + col_w + col_gap
    end
    if row.show_human then
      local human_changed, human_value, human_seed = render_column(
        "popup_human_" .. row.slot.id,
        "Hum",
        "%.1f ms",
        row.settings.humanize_ms or 0.0,
        0.0,
        50.0,
        "##seq_popup_human_knob_" .. region.id .. "_" .. row.slot.id,
        "##seq_popup_human_seed_" .. region.id .. "_" .. row.slot.id,
        nil,
        "human"
      )
      if human_changed then
        seq_humanize_sync_time_from_knob(row.settings, human_value)
        row_changed = true
      end
      if human_seed then
        apply_seed(function() row.settings.humanize_seed = seq_new_seed() end)
      end
      x = x + col_w + col_gap
    end
    if row.show_vel then
      local vel_changed, vel_value, vel_seed = render_column(
        "popup_vel_" .. row.slot.id,
        "Vel",
        "%.2f",
        row.settings.humanize_vel or 0.0,
        0.0,
        1.0,
        "##seq_popup_vel_knob_" .. region.id .. "_" .. row.slot.id,
        "##seq_popup_vel_seed_" .. region.id .. "_" .. row.slot.id,
        nil,
        "vel"
      )
      if vel_changed then
        row.settings.humanize_vel = vel_value
        row_changed = true
      end
      if vel_seed then
        apply_seed(function() row.settings.humanize_vel_seed = seq_new_seed() end)
      end
      x = x + col_w + col_gap
    end
    if row.show_vary then
      local vary_changed, vary_value, vary_seed, vary_refresh = render_column(
        "popup_vary_" .. row.slot.id,
        "Vary",
        "%.2f",
        row.settings.vary_prob or 0.0,
        0.0,
        1.0,
        "##seq_popup_vary_knob_" .. region.id .. "_" .. row.slot.id,
        "##seq_popup_vary_seed_" .. region.id .. "_" .. row.slot.id,
        nil,
        "vary",
        "##seq_popup_vary_refresh_" .. region.id .. "_" .. row.slot.id
      )
      if vary_changed then
        row.settings.vary_prob = vary_value
        row_changed = true
      end
      if vary_seed then
        apply_seed(function() row.settings.vary_seed = seq_new_seed() end)
      end
      if vary_refresh then
        apply_seed(function() row.settings.vary_swap_seed = seq_new_seed() end)
      end
      x = x + col_w + col_gap
    end
    if row.show_stut then
      local stut_changed, stut_value, stut_seed = render_column(
        "popup_stut_" .. row.slot.id,
        "Stut",
        "%.2f",
        row.settings.stutter_prob or 0.0,
        0.0,
        1.0,
        "##seq_popup_stut_knob_" .. region.id .. "_" .. row.slot.id,
        "##seq_popup_stut_seed_" .. region.id .. "_" .. row.slot.id,
        nil,
        "stut"
      )
      if stut_changed then
        row.settings.stutter_prob = stut_value
        row_changed = true
      end
      if stut_seed then
        apply_seed(function() row.settings.stutter_seed = seq_new_seed() end)
      end
      x = x + col_w + col_gap
    end
    if row.show_grace then
      local grace_changed, grace_value, grace_seed = render_column(
        "popup_grace_" .. row.slot.id,
        "Grace",
        "%.2f",
        row.settings.ghost_grace or 0.0,
        0.0,
        1.0,
        "##seq_popup_grace_knob_" .. region.id .. "_" .. row.slot.id,
        "##seq_popup_grace_seed_" .. region.id .. "_" .. row.slot.id,
        nil,
        "grace"
      )
      if grace_changed then
        row.settings.ghost_grace = grace_value
        row_changed = true
      end
      if grace_seed then
        apply_seed(function() row.settings.ghost_grace_seed = seq_new_seed() end)
      end
      x = x + col_w + col_gap
    end
    if row.show_after then
      local after_changed, after_value, after_seed = render_column(
        "popup_after_" .. row.slot.id,
        "After",
        "%.2f",
        row.settings.ghost_after or 0.0,
        0.0,
        1.0,
        "##seq_popup_after_knob_" .. region.id .. "_" .. row.slot.id,
        "##seq_popup_after_seed_" .. region.id .. "_" .. row.slot.id,
        nil,
        "after"
      )
      if after_changed then
        row.settings.ghost_after = after_value
        row_changed = true
      end
      if after_seed then
        apply_seed(function() row.settings.ghost_after_seed = seq_new_seed() end)
      end
      x = x + col_w + col_gap
    end

    if row_changed then
      changed_any = true
      seq_queue_random_sync(region.pattern_id, row.slot.id)
    end
    y = y + stack_h
    if row_idx < #rows then
      y = y + track_gap
    end
  end

  state.seq_random_popup_active_key = next_focus
  r.ImGui_SetCursorScreenPos(ctx, origin_x, origin_y)
  r.ImGui_Dummy(ctx, content_w, content_h)
  local fly_slot = state.seq_random_flyout and state.seq_random_flyout.slot_id
  if seq_render_random_flyout(popup_dl, pattern, "popup") then
    changed_any = true
    seq_queue_random_sync(region.pattern_id, fly_slot)
  end

  if changed_any then
    begin_seq_undo("Edit sequencer random")
    seq_undo_commit_on_release = true
  end

  r.ImGui_EndPopup(ctx)
  pop_random_popup_style()
end

function get_seq_note(region, track_id, step_key)
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local notes = get_track_note_table(pattern, track_id, false)
  return notes and notes[tostring(step_key)] or nil
end

function set_seq_note(region, track_id, step_key, note)
  local pattern = region and get_seq_pattern(region.pattern_id, true)
  local notes = get_track_note_table(pattern, track_id, true)
  if type(note) == "table" and (type(note.vary_filter) ~= "string" or seq_trim_text(note.vary_filter) == "") then
    local text = seq_cell_vary_filter(region, track_id, step_key, note)
    if text then
      note.vary_filter = text
    end
  end
  notes[tostring(step_key)] = note
end

function delete_seq_note(region, track_id, step_key)
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local notes = get_track_note_table(pattern, track_id, false)
  if notes then
    notes[tostring(step_key)] = nil
  end
end

function clone_table_deep(src)
  if type(src) ~= "table" then
    return src
  end
  local out = {}
  for k, v in pairs(src) do
    out[k] = clone_table_deep(v)
  end
  return out
end

function seq_item_is_aux_piece(item)
  if not item then
    return false
  end
  if get_item_ext(item, SEQ_EXT_LAYER) == "1" then
    return true
  end
  local ghost = get_item_ext(item, SEQ_EXT_GHOST)
  return ghost ~= nil and ghost ~= ""
end

function seq_item_is_parent_marker(item)
  return item and get_item_ext(item, SEQ_EXT_PARENT) == "1"
end

function seq_item_is_owned(item, region_id)
  if seq_item_is_parent_marker(item) then
    return false
  end
  if get_item_ext(item, SEQ_EXT_FLAG) ~= "1" then
    return false
  end
  if region_id and tonumber(get_item_ext(item, SEQ_EXT_REGION) or "") ~= region_id then
    return false
  end
  return true
end

function seq_item_guid(item)
  if not item then
    return nil
  end
  if r.GetSetMediaItemInfo_String then
    local ok, guid = r.GetSetMediaItemInfo_String(item, "GUID", "", false)
    if type(guid) == "string" and guid ~= "" then
      return guid
    end
    if type(ok) == "string" and ok ~= "" then
      return ok
    end
  end
  if r.BR_GetMediaItemGUID then
    local guid = r.BR_GetMediaItemGUID(item)
    if type(guid) == "string" and guid ~= "" then
      return guid
    end
  end
  return nil
end

function seq_item_name(item)
  if not item then
    return ""
  end
  local take = r.GetActiveTake and r.GetActiveTake(item)
  if take and r.GetSetMediaItemTakeInfo_String then
    local ok, name = r.GetSetMediaItemTakeInfo_String(take, "P_NAME", "", false)
    if type(name) == "string" and name ~= "" then
      return name
    end
    if type(ok) == "string" and ok ~= "" then
      return ok
    end
  end
  if r.GetSetMediaItemInfo_String then
    local ok, name = r.GetSetMediaItemInfo_String(item, "P_NAME", "", false)
    if type(name) == "string" then
      return name
    end
    if type(ok) == "string" then
      return ok
    end
  end
  return ""
end

function seq_region_parent_label(region)
  if not region then
    return "Region"
  end
  local name = region.name
  if type(name) == "string" and name ~= "" then
    return name
  end
  return "Region " .. tostring(region.id)
end

function seq_refresh_arrange()
  if r.UpdateTimeline then
    r.UpdateTimeline()
  end
  if r.UpdateArrange then
    r.UpdateArrange()
  end
  if r.TrackList_AdjustWindows then
    r.TrackList_AdjustWindows(false)
  end
end

-- Transparent tiles so item color shows through (incl. the small REAPER tile gap).
SEQ_PARENT_IMAGE_FLAGS = 1 -- center/tile
SEQ_PARENT_IMAGE_STYLES = {
  { id = "drum", file = "seq-region-parent-drum.png", label = "Drum sequencer" },
  { id = "led", file = "seq-region-parent-led.png", label = "LED step row" },
  { id = "tape", file = "seq-region-parent-tape.png", label = "Measure tape" },
  { id = "wave", file = "seq-region-parent-wave.png", label = "Waveform" },
  { id = "notes", file = "seq-region-parent-notes.png", label = "Piano-roll notes" },
  { id = "dots", file = "seq-region-parent-dots.png", label = "Pulse dots" },
}

function seq_parent_image_style(id)
  id = id or (state and state.seq_parent_item_image) or "drum"
  for i = 1, #SEQ_PARENT_IMAGE_STYLES do
    if SEQ_PARENT_IMAGE_STYLES[i].id == id then
      return SEQ_PARENT_IMAGE_STYLES[i]
    end
  end
  return SEQ_PARENT_IMAGE_STYLES[1]
end

function seq_parent_image_file()
  return seq_parent_image_style().file
end

function seq_file_exists(path)
  if not path or path == "" then
    return false
  end
  if r.file_exists and r.file_exists(path) then
    return true
  end
  local f = io.open(path, "rb")
  if f then
    f:close()
    return true
  end
  return false
end

function seq_parent_item_image_candidates()
  local dirs = {}
  local data_dir = r.GetResourcePath() .. "/Data/track_icons"
  dirs[#dirs + 1] = data_dir
  dirs[#dirs + 1] = SCRIPT_DIR .. "/assets"
  local info = debug.getinfo and debug.getinfo(1, "S")
  local src = info and info.source
  if type(src) == "string" then
    local path = src:match("^@(.+)$")
    local dir = path and path:match("^(.*)[/\\]")
    if dir then
      dirs[#dirs + 1] = dir .. "/assets"
    end
  end
  return dirs, data_dir
end

function seq_parent_item_image_path()
  if seq_parent_image_ready_path and seq_file_exists(seq_parent_image_ready_path)
      and seq_parent_item_image_matches(seq_parent_image_ready_path) then
    return seq_parent_image_ready_path
  end
  local dirs, data_dir = seq_parent_item_image_candidates()
  local found = nil
  for i = 1, #dirs do
    local p = dirs[i] .. "/" .. seq_parent_image_file()
    if seq_file_exists(p) then
      found = p
      break
    end
  end
  local dest = data_dir .. "/" .. seq_parent_image_file()
  if found and found ~= dest then
    if r.RecursiveCreateDirectory then
      r.RecursiveCreateDirectory(data_dir, 0)
    end
    local sf = io.open(found, "rb")
    if sf then
      local data = sf:read("*a")
      sf:close()
      local df = io.open(dest, "wb")
      if df then
        df:write(data)
        df:close()
        found = dest
      end
    end
  end
  seq_parent_image_ready_path = found or dest
  return seq_parent_image_ready_path
end

function seq_item_state_chunk(item)
  if not item or not r.GetItemStateChunk then
    return nil
  end
  local retval, chunk = r.GetItemStateChunk(item, "", false)
  if type(retval) == "string" then
    chunk = retval
  end
  if type(chunk) == "string" and chunk ~= "" then
    return chunk
  end
  return nil
end

function seq_parent_item_image_matches(path)
  if type(path) ~= "string" or path == "" then
    return false
  end
  local name = seq_parent_image_file()
  if path == name then
    return true
  end
  if path:sub(-#name) == name then
    return true
  end
  return path:find(name, 1, true) ~= nil
end

function seq_parent_item_has_image(item)
  if not item then
    return false
  end
  if r.BR_GetMediaItemImageResource then
    local a, b, c = r.BR_GetMediaItemImageResource(item)
    local image, flags
    if type(a) == "string" then
      image, flags = a, b
    elseif a then
      image, flags = b, c
    end
    if seq_parent_item_image_matches(image)
        and (tonumber(flags) or 0) == SEQ_PARENT_IMAGE_FLAGS then
      return true
    end
  end
  local chunk = seq_item_state_chunk(item)
  if chunk then
    local fn = chunk:match('RESOURCEFN%s+"([^"]+)"') or chunk:match("RESOURCEFN%s+(%S+)")
    local flags = tonumber(chunk:match("IMGRESOURCEFLAGS%s+(%-?%d+)"))
    if seq_parent_item_image_matches(fn) and flags == SEQ_PARENT_IMAGE_FLAGS then
      return true
    end
  end
  return false
end

function seq_set_parent_item_image_chunk(item, path, flags)
  local chunk = seq_item_state_chunk(item)
  if not chunk or not path or path == "" then
    return false
  end
  flags = flags or SEQ_PARENT_IMAGE_FLAGS
  local line = string.format('RESOURCEFN "%s"', path)
  local flag_line = string.format("IMGRESOURCEFLAGS %d", flags)
  if chunk:find("RESOURCEFN%s+", 1) then
    chunk = chunk:gsub('RESOURCEFN%s+"[^"]*"', line, 1)
    if chunk:find("RESOURCEFN%s+[^\"\r\n]+", 1) and not chunk:find(line, 1, true) then
      chunk = chunk:gsub("RESOURCEFN%s+[^\r\n]+", line, 1)
    end
  elseif chunk:find("\n>%s*$") then
    chunk = chunk:gsub("\n>%s*$", "\n" .. line .. "\n" .. flag_line .. "\n>\n")
  else
    chunk = chunk .. line .. "\n" .. flag_line .. "\n"
  end
  if chunk:find("IMGRESOURCEFLAGS%s+", 1) then
    chunk = chunk:gsub("IMGRESOURCEFLAGS%s+%-?%d+", flag_line, 1)
  else
    chunk = chunk:gsub("(RESOURCEFN[^\r\n]+\r?\n)", "%1" .. flag_line .. "\n", 1)
  end
  return r.SetItemStateChunk(item, chunk, false) and true or false
end

function seq_set_parent_image_style(id)
  local style = seq_parent_image_style(id)
  if not style then
    return false
  end
  if state.seq_parent_item_image == style.id and seq_parent_image_ready_path then
    return false
  end
  state.seq_parent_item_image = style.id
  seq_parent_image_ready_path = nil
  if save_config then
    save_config()
  end
  seq_ensure_all_region_parent_items()
  return true
end

function seq_attach_parent_item_image(item)
  item = seq_media_item_ptr(item)
  if not item then
    return false
  end
  local path = seq_parent_item_image_path()
  if not path or not seq_file_exists(path) then
    return false
  end
  if r.BR_SetMediaItemImageResource then
    r.BR_SetMediaItemImageResource(item, path, SEQ_PARENT_IMAGE_FLAGS)
    if seq_parent_item_has_image(item) then
      return true
    end
  end
  return seq_set_parent_item_image_chunk(item, path, SEQ_PARENT_IMAGE_FLAGS)
end

seq_parent_pcm_by_pool = seq_parent_pcm_by_pool or {}
seq_parent_image_ready_path = seq_parent_image_ready_path or nil

function seq_parent_source_valid(src)
  if not src then
    return false
  end
  if r.ValidatePtr2 and r.ValidatePtr2(0, src, "PCM_source*") then
    return true
  end
  if r.ValidatePtr and r.ValidatePtr(src, "PCM_source*") then
    return true
  end
  if r.GetMediaSourceType then
    local ok, typ = pcall(r.GetMediaSourceType, src, "")
    if ok and type(typ) == "string" and typ ~= "" then
      return true
    end
    if type(ok) == "string" and ok ~= "" then
      return true
    end
  end
  return false
end

function seq_source_type(src)
  if not src or not r.GetMediaSourceType then
    return ""
  end
  local a, b = r.GetMediaSourceType(src, "")
  if type(b) == "string" and b ~= "" then
    return b
  end
  if type(a) == "string" then
    return a
  end
  return ""
end

function seq_parent_source_is_midi(src)
  if not seq_parent_source_valid(src) then
    return false
  end
  local typ = seq_source_type(src):upper()
  return typ:find("MIDI", 1, true) ~= nil
end

function seq_parent_item_is_midi(item)
  local take = item and r.GetActiveTake and r.GetActiveTake(item)
  if not take then
    return false, nil
  end
  if r.TakeIsMIDI then
    local ok, is_midi = pcall(r.TakeIsMIDI, take)
    if ok and is_midi then
      return true, take
    end
    if is_midi == true then
      return true, take
    end
  end
  local src = r.GetMediaItemTake_Source and r.GetMediaItemTake_Source(take)
  return seq_parent_source_is_midi(src), take
end

function seq_parent_take_source(item)
  local take = item and r.GetActiveTake and r.GetActiveTake(item)
  if not take or not r.GetMediaItemTake_Source then
    return nil, take
  end
  return r.GetMediaItemTake_Source(take), take
end

function seq_parent_takes_share_source(item_a, item_b)
  local sa = select(1, seq_parent_take_source(item_a))
  local sb = select(1, seq_parent_take_source(item_b))
  return sa and sb and sa == sb
end

function seq_parent_midi_source(pool_id, prefer_src)
  pool_id = tonumber(pool_id) or 0
  local cached = seq_parent_pcm_by_pool[pool_id]
  if seq_parent_source_is_midi(cached) then
    return cached
  end
  for _, reg in ipairs(state.seq_regions or {}) do
    if (tonumber(reg.pool_id) or 0) == pool_id and reg.parent_item_guid then
      local item = seq_find_item_by_guid(reg.parent_item_guid)
      local src = select(1, seq_parent_take_source(item))
      if seq_parent_source_is_midi(src) then
        seq_parent_pcm_by_pool[pool_id] = src
        return src
      end
    end
  end
  if seq_parent_source_is_midi(prefer_src) then
    seq_parent_pcm_by_pool[pool_id] = prefer_src
    return prefer_src
  end
  return nil
end

function seq_media_item_ptr(item)
  if item == nil then
    return nil
  end
  if r.ValidatePtr2 then
    if r.ValidatePtr2(0, item, "MediaItem*") then
      return item
    end
    return nil
  end
  if r.ValidatePtr then
    if r.ValidatePtr(item, "MediaItem*") then
      return item
    end
    return nil
  end
  return item
end

function seq_parent_item_take_count(item)
  item = seq_media_item_ptr(item)
  if not item then
    return 0
  end
  if r.GetMediaItemNumTakes then
    local ok, n = pcall(r.GetMediaItemNumTakes, item)
    if ok then
      return tonumber(n) or 0
    end
  end
  if r.GetActiveTake then
    local ok, take = pcall(r.GetActiveTake, item)
    if ok and take then
      return 1
    end
  end
  return 0
end

function seq_create_parent_midi_item(track, region)
  if not track then
    return nil
  end
  local start_qn = (region and region.start_qn) or 0.0
  local length_qn = region and get_seq_region_length_qn(region) or 16.0
  local start_pos = qn_to_time(start_qn)
  local end_pos = qn_to_time(start_qn + length_qn)
  if not start_pos or not end_pos or end_pos <= start_pos then
    start_pos = start_pos or 0.0
    end_pos = start_pos + 2.0
  end
  local item = r.CreateNewMIDIItemInProj(track, start_pos, end_pos)
  return item
end

function seq_new_reaper_guid()
  if r.genGuid then
    local g = r.genGuid("")
    if type(g) == "string" and g ~= "" then
      if g:sub(1, 1) ~= "{" then
        g = "{" .. g .. "}"
      end
      return g
    end
  end
  return string.format("{%08X-%04X-%04X-%04X-%08X%04X}",
    math.random(0, 0xFFFFFFFF),
    math.random(0, 0xFFFF),
    math.random(0, 0xFFFF),
    math.random(0, 0xFFFF),
    math.random(0, 0xFFFFFFFF),
    math.random(0, 0xFFFF))
end

function seq_normalize_pool_guid(guid)
  if type(guid) ~= "string" or guid == "" then
    return nil
  end
  if guid:sub(1, 1) ~= "{" then
    guid = "{" .. guid .. "}"
  end
  return guid
end

function seq_source_pooledevts_guid(state)
  if type(state) ~= "string" then
    return nil
  end
  return state:match("POOLEDEVTS%s+(%b{})")
end

function seq_source_set_pooledevts(state, pool_guid)
  if type(state) ~= "string" or state == "" then
    return nil
  end
  pool_guid = seq_normalize_pool_guid(pool_guid)
  if pool_guid then
    if state:find("POOLEDEVTS", 1, true) then
      return (state:gsub("POOLEDEVTS%s+%b{}", "POOLEDEVTS " .. pool_guid, 1))
    end
    local has = state:find("HASDATA", 1, true)
    local src = state:find("<SOURCE MIDI", 1, true)
    local at = has or src
    local nl = at and state:find("\n", at, true)
    if not nl then
      return state .. "\nPOOLEDEVTS " .. pool_guid
    end
    return state:sub(1, nl) .. "POOLEDEVTS " .. pool_guid .. "\n" .. state:sub(nl + 1)
  end
  return (state:gsub("[\r\n]*POOLEDEVTS%s+%b{}", ""))
end

function seq_chunk_midi_source_span(chunk)
  if type(chunk) ~= "string" then
    return nil
  end
  local start = chunk:find("<SOURCE MIDI", 1, true)
  if not start then
    return nil
  end
  local depth = 0
  for i = start, #chunk do
    local c = chunk:sub(i, i)
    if c == "<" then
      depth = depth + 1
    elseif c == ">" then
      depth = depth - 1
      if depth == 0 then
        return start, i
      end
    end
  end
  return nil
end

function seq_snm_take_source_state(take, new_state)
  if not take or not r.SNM_GetSetSourceState2 or not r.SNM_CreateFastString then
    return nil
  end
  local fs = r.SNM_CreateFastString("")
  if not fs then
    return nil
  end
  local out = nil
  if new_state then
    if not r.SNM_SetFastString then
      if r.SNM_DeleteFastString then
        r.SNM_DeleteFastString(fs)
      end
      return nil
    end
    r.SNM_SetFastString(fs, new_state)
    if r.SNM_GetSetSourceState2(take, fs, true) then
      out = new_state
    end
  else
    if r.SNM_GetSetSourceState2(take, fs, false) and r.SNM_GetFastString then
      local state = r.SNM_GetFastString(fs)
      if type(state) == "string" and state ~= "" then
        out = state
      end
    end
  end
  if r.SNM_DeleteFastString then
    r.SNM_DeleteFastString(fs)
  end
  return out
end

function seq_midi_item_source_state(item)
  local is_midi, take = seq_parent_item_is_midi(item)
  if not is_midi or not take then
    return nil, take
  end
  local state = seq_snm_take_source_state(take)
  if state then
    return state, take
  end
  local chunk = seq_item_state_chunk(item)
  local a, b = seq_chunk_midi_source_span(chunk)
  if a and b then
    return chunk:sub(a, b), take
  end
  return nil, take
end

function seq_midi_item_set_source_state(item, state)
  item = seq_media_item_ptr(item) or item
  if not item or type(state) ~= "string" or state == "" then
    return false
  end
  local take = select(2, seq_parent_item_is_midi(item))
  if take and seq_snm_take_source_state(take, state) then
    if r.UpdateItemInProject then
      r.UpdateItemInProject(item)
    end
    return true
  end
  local chunk = seq_item_state_chunk(item)
  local a, b = seq_chunk_midi_source_span(chunk)
  if not a then
    return false
  end
  chunk = chunk:sub(1, a - 1) .. state .. chunk:sub(b + 1)
  if not r.SetItemStateChunk(item, chunk, false) then
    return false
  end
  if r.UpdateItemInProject then
    r.UpdateItemInProject(item)
  end
  return true
end

function seq_midi_item_pool_guid(item)
  local is_midi, take = seq_parent_item_is_midi(item)
  if not is_midi or not take then
    return nil
  end
  if r.BR_GetMidiTakePoolGUID then
    local a, b = r.BR_GetMidiTakePoolGUID(take)
    if type(a) == "string" and a ~= "" then
      return a
    end
    if a and type(b) == "string" and b ~= "" then
      return b
    end
  end
  local state = seq_midi_item_source_state(item)
  return seq_source_pooledevts_guid(state)
end

function seq_midi_item_set_pooledevts(item, pool_guid)
  local state = seq_midi_item_source_state(item)
  if not state then
    return false
  end
  local next_state = seq_source_set_pooledevts(state, pool_guid)
  if not next_state or next_state == state then
    return next_state ~= nil
  end
  return seq_midi_item_set_source_state(item, next_state)
end

function seq_parent_midi_copy_events(from_take, to_take)
  if not from_take or not to_take or from_take == to_take then
    return
  end
  if not r.MIDI_GetAllEvts or not r.MIDI_SetAllEvts then
    return
  end
  local a, b = r.MIDI_GetAllEvts(from_take, "")
  local evts = nil
  if type(b) == "string" then
    evts = b
  elseif type(a) == "string" then
    evts = a
  end
  if evts then
    r.MIDI_SetAllEvts(to_take, evts)
    if r.MIDI_Sort then
      r.MIDI_Sort(to_take)
    end
  end
end

function seq_parent_unpool_midi_item(item)
  local is_midi, take = seq_parent_item_is_midi(item)
  if not is_midi or not take then
    return
  end
  local evts = nil
  if r.MIDI_GetAllEvts then
    local a, b = r.MIDI_GetAllEvts(take, "")
    if type(b) == "string" then
      evts = b
    elseif type(a) == "string" then
      evts = a
    end
  end
  local neu = r.PCM_Source_CreateFromType and r.PCM_Source_CreateFromType("MIDI")
  if neu and r.SetMediaItemTake_Source then
    r.SetMediaItemTake_Source(take, neu)
  end
  if evts and r.MIDI_SetAllEvts then
    r.MIDI_SetAllEvts(take, evts)
    if r.MIDI_Sort then
      r.MIDI_Sort(take)
    end
  end
  local state = seq_midi_item_source_state(item)
  if state then
    seq_midi_item_set_source_state(item, seq_source_set_pooledevts(state, nil))
  else
    seq_midi_item_set_pooledevts(item, nil)
  end
end

function seq_parent_sync_native_midi_pool(item, region)
  item = seq_media_item_ptr(item) or item
  if not item or not region then
    return
  end
  if not select(1, seq_parent_item_is_midi(item)) then
    return
  end
  local pool_id = tonumber(region.pool_id) or 0
  local linked = seq_region_pool_count(pool_id) > 1
  if not linked then
    if seq_midi_item_pool_guid(item) then
      seq_parent_unpool_midi_item(item)
    end
    return
  end
  local members = {}
  local proto_item, proto_state = nil, nil
  for _, reg in ipairs(state.seq_regions or {}) do
    if (tonumber(reg.pool_id) or 0) == pool_id and reg.parent_item_guid then
      local it = seq_find_item_by_guid(reg.parent_item_guid)
      if it and select(1, seq_parent_item_is_midi(it)) then
        members[#members + 1] = it
        if not proto_item then
          proto_item = it
          proto_state = seq_midi_item_source_state(it)
        end
      end
    end
  end
  if #members < 2 then
    members[#members + 1] = item
  end
  local majority = seq_parent_pool_majority_guid(pool_id, nil)
  if majority then
    for i = 1, #members do
      if seq_parent_native_guid(members[i]) == majority then
        proto_item = members[i]
        proto_state = seq_midi_item_source_state(members[i])
        break
      end
    end
  end
  if not proto_state then
    proto_item = item
    proto_state = seq_midi_item_source_state(item)
  end
  if not proto_state then
    return
  end
  local guid = majority
      or seq_source_pooledevts_guid(proto_state)
      or seq_midi_item_pool_guid(proto_item)
      or seq_midi_item_pool_guid(item)
      or seq_new_reaper_guid()
  guid = seq_normalize_pool_guid(guid) or guid
  proto_state = seq_source_set_pooledevts(proto_state, guid)
  for i = 1, #members do
    local it = members[i]
    local owner = region
    for _, reg in ipairs(state.seq_regions or {}) do
      if (tonumber(reg.pool_id) or 0) == pool_id and reg.parent_item_guid then
        if seq_find_item_by_guid(reg.parent_item_guid) == it then
          owner = reg
          break
        end
      end
    end
    if seq_parent_item_should_join_pool(it, owner) then
      seq_midi_item_set_source_state(it, proto_state)
    end
  end
end

function seq_parent_sync_pool(pool_id)
  pool_id = tonumber(pool_id) or 0
  if pool_id <= 0 or seq_region_pool_count(pool_id) < 2 then
    return
  end
  for _, reg in ipairs(state.seq_regions or {}) do
    if (tonumber(reg.pool_id) or 0) == pool_id and reg.parent_item_guid then
      local item = seq_find_item_by_guid(reg.parent_item_guid)
      if item then
        seq_parent_sync_native_midi_pool(item, reg)
        return
      end
    end
  end
end

function seq_ensure_parent_item_take(item, region)
  item = seq_media_item_ptr(item)
  if not item or not region then
    return nil
  end
  local is_midi, take = seq_parent_item_is_midi(item)
  if not is_midi or not take then
    return nil
  end
  local cur_src = r.GetMediaItemTake_Source and r.GetMediaItemTake_Source(take)
  local pool_id = tonumber(region.pool_id) or 0
  if seq_parent_item_should_join_pool(item, region) then
    local pooled = seq_parent_midi_source(pool_id, seq_parent_source_is_midi(cur_src) and cur_src or nil)
    if pooled and cur_src ~= pooled and r.SetMediaItemTake_Source then
      r.SetMediaItemTake_Source(take, pooled)
    elseif seq_parent_source_is_midi(cur_src) then
      seq_parent_pcm_by_pool[pool_id] = cur_src
    end
  elseif seq_parent_source_is_midi(cur_src) then
    seq_parent_pcm_by_pool[pool_id] = nil
  end
  local label = seq_region_parent_label(region)
  if r.GetSetMediaItemTakeInfo_String then
    r.GetSetMediaItemTakeInfo_String(take, "P_NAME", label, true)
  end
  return take
end

function seq_region_native_color(region)
  local palette = {
    {0x4A, 0x8B, 0xD6},
    {0x7D, 0xD6, 0x70},
    {0xD6, 0xA4, 0x4A},
    {0xC7, 0x6D, 0xD6},
    {0x4A, 0xD6, 0xC1},
    {0xD6, 0x6D, 0x6D},
  }
  local idx = ((math.floor((region and region.pool_id) or 1) - 1) % #palette) + 1
  local rgb = palette[idx]
  if r.ColorToNative then
    return r.ColorToNative(rgb[1], rgb[2], rgb[3]) | 0x1000000
  end
  return 0
end

function seq_find_item_by_guid(guid)
  if not guid or guid == "" then
    return nil, nil
  end
  local n = r.CountTracks(0)
  for tr_idx = 0, n - 1 do
    local tr = r.GetTrack(0, tr_idx)
    for item_idx = 0, r.CountTrackMediaItems(tr) - 1 do
      local item = r.GetTrackMediaItem(tr, item_idx)
      if item and seq_item_guid(item) == guid then
        return item, tr
      end
    end
  end
  return nil, nil
end

function seq_write_parent_item_ext(item, region)
  item = seq_media_item_ptr(item)
  if not item or not region then
    return
  end
  set_item_ext(item, SEQ_EXT_PARENT, "1")
  set_item_ext(item, SEQ_EXT_REGION, region.id)
  set_item_ext(item, SEQ_EXT_PATTERN, region.pattern_id)
  set_item_ext(item, SEQ_EXT_POOL, region.pool_id)
end

function seq_apply_parent_item_props(item, region)
  item = seq_media_item_ptr(item)
  if not item or not region then
    return nil
  end
  local start_qn = region.start_qn or 0.0
  local length_qn = get_seq_region_length_qn(region)
  local t0 = qn_to_time(start_qn)
  local t1 = qn_to_time(start_qn + length_qn)
  if t0 and t1 and t1 > t0 then
    r.SetMediaItemPosition(item, t0, false)
    r.SetMediaItemLength(item, t1 - t0, false)
  end
  local label = seq_region_parent_label(region)
  if r.GetSetMediaItemInfo_String then
    r.GetSetMediaItemInfo_String(item, "P_NAME", label, true)
  end
  seq_ensure_parent_item_take(item, region)
  if r.ColorToNative then
    r.SetMediaItemInfo_Value(item, "I_CUSTOMCOLOR", seq_region_native_color(region))
  end
  if r.SetMediaItemInfo_Value then
    r.SetMediaItemInfo_Value(item, "C_BEATATTACHMODE", 1)
    r.SetMediaItemInfo_Value(item, "B_LOOPSRC", 1)
  end
  seq_write_parent_item_ext(item, region)
  seq_attach_parent_item_image(item)
  seq_parent_sync_native_midi_pool(item, region)
  if r.UpdateItemInProject then
    r.UpdateItemInProject(item)
  end
  return item
end

function seq_sync_region_parent_item(region)
  if not region then
    return false
  end
  local parent_tr = find_seq_parent_folder_track() or create_seq_parent_folder_track()
  if not parent_tr then
    return false
  end
  local item = nil
  local item_tr = nil
  if region.parent_item_guid and region.parent_item_guid ~= "" then
    item, item_tr = seq_find_item_by_guid(region.parent_item_guid)
    item = seq_media_item_ptr(item)
  end
  if not item then
    local n = r.CountTrackMediaItems(parent_tr)
    for i = 0, n - 1 do
      local cand = r.GetTrackMediaItem(parent_tr, i)
      if cand and seq_item_is_parent_marker(cand)
          and tonumber(get_item_ext(cand, SEQ_EXT_REGION) or "") == region.id then
        item = cand
        item_tr = parent_tr
        break
      end
    end
  end
  local created = false
  if not item then
    item = seq_create_parent_midi_item(parent_tr, region)
    if not item then
      return false
    end
    created = true
    item_tr = parent_tr
  elseif item_tr and item_tr ~= parent_tr and r.MoveMediaItemToTrack then
    r.MoveMediaItemToTrack(item, parent_tr)
    item_tr = parent_tr
  end
  local guid = seq_item_guid(item)
  local already = false
  if item and not created then
    local pos = r.GetMediaItemInfo_Value(item, "D_POSITION") or 0.0
    local len = r.GetMediaItemInfo_Value(item, "D_LENGTH") or 0.0
    local have_start = time_to_qn(pos)
    local have_end = time_to_qn(pos + len)
    local want_start = region.start_qn or 0.0
    local want_len = get_seq_region_length_qn(region)
    already = have_start and have_end
      and math.abs(have_start - want_start) <= 0.0005
      and math.abs((have_end - have_start) - want_len) <= 0.0005
      and seq_item_name(item) == seq_region_parent_label(region)
      and seq_parent_item_has_image(item)
      and tonumber(get_item_ext(item, SEQ_EXT_REGION) or "") == region.id
      and tonumber(get_item_ext(item, SEQ_EXT_PATTERN) or "") == region.pattern_id
      and tonumber(get_item_ext(item, SEQ_EXT_POOL) or "") == region.pool_id
      and guid and guid == region.parent_item_guid
  end
  if not already then
    item = seq_apply_parent_item_props(item, region) or item
    seq_mark_self_arrange_write()
  else
    seq_parent_sync_native_midi_pool(item, region)
  end
  region.parent_item_guid = seq_item_guid(item) or guid or region.parent_item_guid
  return created
end

function seq_remove_region_parent_item(region)
  if not region then
    return false
  end
  local item = nil
  if region.parent_item_guid and region.parent_item_guid ~= "" then
    item = seq_find_item_by_guid(region.parent_item_guid)
  end
  if not item then
    local parent_tr = find_seq_parent_folder_track()
    if parent_tr then
      for i = r.CountTrackMediaItems(parent_tr) - 1, 0, -1 do
        local cand = r.GetTrackMediaItem(parent_tr, i)
        if cand and seq_item_is_parent_marker(cand)
            and tonumber(get_item_ext(cand, SEQ_EXT_REGION) or "") == region.id then
          item = cand
          break
        end
      end
    end
  end
  if not item then
    return false
  end
  local tr = r.GetMediaItemTrack and r.GetMediaItemTrack(item)
  if tr and r.DeleteTrackMediaItem(tr, item) then
    region.parent_item_guid = nil
    seq_mark_self_arrange_write()
    return true
  end
  return false
end

function seq_ensure_all_region_parent_items()
  local any = false
  for _, region in ipairs(state.seq_regions or {}) do
    seq_sync_region_parent_item(region)
    local item = region.parent_item_guid and select(1, seq_find_item_by_guid(region.parent_item_guid))
    if item then
      seq_attach_parent_item_image(item)
    end
    any = true
  end
  if any then
    seq_refresh_arrange()
  end
  return any
end

function seq_collect_parent_items()
  local out = {}
  local n = r.CountTracks(0)
  for tr_idx = 0, n - 1 do
    local tr = r.GetTrack(0, tr_idx)
    for item_idx = 0, r.CountTrackMediaItems(tr) - 1 do
      local item = r.GetTrackMediaItem(tr, item_idx)
      if item and seq_item_is_parent_marker(item) then
        local pos = r.GetMediaItemInfo_Value(item, "D_POSITION") or 0.0
        local start_qn = time_to_qn(pos)
        table.insert(out, {
          item = item,
          track = tr,
          guid = seq_item_guid(item),
          region_id = tonumber(get_item_ext(item, SEQ_EXT_REGION) or ""),
          pattern_id = tonumber(get_item_ext(item, SEQ_EXT_PATTERN) or ""),
          pool_id = tonumber(get_item_ext(item, SEQ_EXT_POOL) or ""),
          start_qn = start_qn,
          length_qn = seq_item_length_qn(item),
          name = seq_item_name(item),
        })
      end
    end
  end
  return out
end

function seq_arrange_parent_copy_unique()
  if not r.Undo_CanUndo2 then
    return false
  end
  local desc = tostring(r.Undo_CanUndo2(0) or ""):lower()
  return desc:find("unpool", 1, true) ~= nil
      or desc:find("not pooling", 1, true) ~= nil
      or desc:find("make unique", 1, true) ~= nil
end

function seq_parent_native_guid(item)
  return seq_normalize_pool_guid(seq_midi_item_pool_guid(item))
end

function seq_parent_pool_majority_guid(pool_id, ignore_item)
  pool_id = tonumber(pool_id) or 0
  local counts = {}
  for _, reg in ipairs(state.seq_regions or {}) do
    if (tonumber(reg.pool_id) or 0) == pool_id and reg.parent_item_guid then
      local it = seq_find_item_by_guid(reg.parent_item_guid)
      if it and it ~= ignore_item then
        local g = seq_parent_native_guid(it)
        if g then
          counts[g] = (counts[g] or 0) + 1
        end
      end
    end
  end
  local best, n = nil, 0
  for g, c in pairs(counts) do
    if c > n then
      best, n = g, c
    end
  end
  return best, n
end

function seq_parent_item_should_join_pool(item, region)
  if not item or not region then
    return false
  end
  local pool_id = tonumber(region.pool_id) or 0
  if seq_region_pool_count(pool_id) < 2 then
    return false
  end
  local mine = seq_parent_native_guid(item)
  local majority, majority_n = seq_parent_pool_majority_guid(pool_id, item)
  if mine and majority and mine ~= majority then
    return false
  end
  if seq_arrange_parent_copy_unique() then
    return mine ~= nil and majority ~= nil and mine == majority
  end
  if not mine and majority and majority_n >= 1 then
    -- A new linked copy has no POOLEDEVTS yet; an arrange unpool often
    -- strips it. Only auto-join when we are the ones creating the copy.
    local desc = r.Undo_CanUndo2 and tostring(r.Undo_CanUndo2(0) or ""):lower() or ""
    if desc:find("pool copy", 1, true) or desc:find("link", 1, true) then
      return true
    end
    return false
  end
  return true
end

function seq_ingest_parent_native_unpool()
  local desc = r.Undo_CanUndo2 and tostring(r.Undo_CanUndo2(0) or ""):lower() or ""
  if desc:find("pool copy", 1, true) then
    return false
  end
  local by_pool = {}
  for _, region in ipairs(state.seq_regions or {}) do
    local pid = tonumber(region.pool_id)
    if pid then
      by_pool[pid] = by_pool[pid] or {}
      by_pool[pid][#by_pool[pid] + 1] = region
    end
  end
  local any = false
  for pid, regs in pairs(by_pool) do
    if #regs >= 2 then
      local keys = {}
      local native_any = false
      for i = 1, #regs do
        local item = regs[i].parent_item_guid and seq_find_item_by_guid(regs[i].parent_item_guid)
        local g = item and seq_parent_native_guid(item) or nil
        keys[i] = g
        if g then
          native_any = true
        end
      end
      if native_any then
        local majority = seq_parent_pool_majority_guid(pid, nil)
        local keep_id = regs[1].id
        if majority then
          for i = 1, #regs do
            if keys[i] == majority then
              keep_id = regs[i].id
              break
            end
          end
        end
        local to_unpool = {}
        for i = 1, #regs do
          local left
          if majority then
            left = keys[i] ~= majority
          else
            left = regs[i].id ~= keep_id
          end
          if left then
            to_unpool[#to_unpool + 1] = regs[i]
          end
        end
        for i = 1, #to_unpool do
          seq_unpool_region(to_unpool[i], { skip_undo = true, skip_sync = true })
          any = true
        end
      elseif seq_arrange_parent_copy_unique() then
        for i = 2, #regs do
          seq_unpool_region(regs[i], { skip_undo = true, skip_sync = true })
          any = true
        end
      end
    end
  end
  return any
end

function seq_delete_region_keep_pattern(region)
  if not region then
    return false
  end
  remove_seq_rendered_items(region)
  seq_refresh_arrange()
  for i, reg in ipairs(state.seq_regions) do
    if reg.id == region.id then
      table.remove(state.seq_regions, i)
      break
    end
  end
  if state.selected_seq_region_id == region.id then
    state.selected_seq_region_id = state.seq_regions[1] and state.seq_regions[1].id or nil
  end
  return true
end

function seq_create_region_from_parent_item(rec, src, pooled)
  if not rec or not rec.start_qn then
    return nil
  end
  local length_qn = rec.length_qn or 16.0
  local length_bars = seq_qn_length_to_bars(rec.start_qn, length_qn)
  local pattern_id
  local pool_id
  if src and pooled then
    pattern_id = src.pattern_id
    pool_id = src.pool_id or alloc_seq_pool()
    src.pool_id = pool_id
  elseif src then
    pattern_id = alloc_seq_pattern()
    pool_id = alloc_seq_pool()
    local src_pattern = get_seq_pattern(src.pattern_id, false)
    state.seq_patterns[tostring(pattern_id)] = clone_table_deep(src_pattern or { notes = {} })
  else
    pattern_id = rec.pattern_id
    if not pattern_id or not get_seq_pattern(pattern_id, false) then
      pattern_id = alloc_seq_pattern()
    end
    pool_id = rec.pool_id or alloc_seq_pool()
  end
  local region = {
    id = state.seq_region_next_id,
    name = (rec.name and rec.name ~= "" and rec.name) or seq_auto_name_new_region(rec.start_qn),
    start_qn = rec.start_qn,
    length_bars = length_bars,
    pool_id = pool_id,
    pattern_id = pattern_id,
    groove = src and normalize_seq_groove(src.groove) or "off",
    style_key = src and src.style_key or nil,
    style_source = src and src.style_source or nil,
    kit_genres = src and src.kit_genres and clone_table_deep(src.kit_genres) or nil,
    parent_item_guid = rec.guid,
    track_samples = src and seq_clone_region_track_samples(src) or nil,
  }
  state.seq_region_next_id = state.seq_region_next_id + 1
  table.insert(state.seq_regions, region)
  sort_seq_regions()
  state.selected_seq_region_id = region.id
  if rec.item then
    seq_apply_parent_item_props(rec.item, region)
  end
  seq_remove_orphaned_region_items()
  sync_seq_region(region)
  if pooled then
    seq_parent_sync_pool(pool_id)
  end
  return region
end

function seq_ingest_parent_items()
  local items = seq_collect_parent_items()
  local by_guid = {}
  for _, rec in ipairs(items) do
    if rec.guid then
      by_guid[rec.guid] = rec
    end
  end

  local claimed = {}
  for _, rec in ipairs(items) do
    rec.matched = nil
  end
  for _, region in ipairs(state.seq_regions or {}) do
    local guid = region.parent_item_guid
    local rec = guid and by_guid[guid]
    if rec and not rec.matched then
      rec.matched = region
      claimed[region.id] = rec
    end
  end
  for _, rec in ipairs(items) do
    if not rec.matched and rec.region_id then
      local region = get_seq_region_by_id(rec.region_id)
      if region and not claimed[region.id] then
        region.parent_item_guid = rec.guid
        rec.matched = region
        claimed[region.id] = rec
      end
    end
  end

  local changed = false
  local needs_note_sync = false

  for _, rec in ipairs(items) do
    if not rec.matched then
      local src = rec.region_id and get_seq_region_by_id(rec.region_id) or nil
      if not src and rec.pattern_id then
        for _, region in ipairs(state.seq_regions or {}) do
          if region.pattern_id == rec.pattern_id then
            src = region
            break
          end
        end
      end
      local unique = seq_arrange_parent_copy_unique()
      local src_item = src and src.parent_item_guid and select(1, seq_find_item_by_guid(src.parent_item_guid))
      local shared = rec.item and src_item and (
        seq_parent_takes_share_source(rec.item, src_item)
        or (seq_midi_item_pool_guid(rec.item) ~= nil
            and seq_midi_item_pool_guid(rec.item) == seq_midi_item_pool_guid(src_item))
      )
      local pooled
      if shared == true then
        pooled = true
      elseif shared == false and rec.item and r.GetActiveTake and r.GetActiveTake(rec.item) then
        pooled = false
      else
        pooled = src and not unique
      end
      if seq_create_region_from_parent_item(rec, src, pooled) then
        changed = true
        needs_note_sync = true
      end
    end
  end

  for _, region in ipairs(state.seq_regions or {}) do
    local rec = claimed[region.id]
    if rec and rec.start_qn then
      local new_start = rec.start_qn
      local new_len = rec.length_qn or get_seq_region_length_qn(region)
      local new_bars = seq_qn_length_to_bars(new_start, new_len)
      local old_start = region.start_qn or 0.0
      local moved = math.abs(new_start - old_start) > 0.0005
      local resized = new_bars ~= region.length_bars
      local renamed = rec.name and rec.name ~= "" and rec.name ~= (region.name or "")
      if moved or resized or renamed then
        if moved then
          region.start_qn = new_start
        end
        if resized then
          region.length_bars = new_bars
        end
        if renamed then
          region.name = rec.name
        end
        sort_seq_regions()
        if moved or resized then
          if moved then
            local child_selected = false
            for _, slot in ipairs(state.seq_tracks or {}) do
              local tr = get_seq_slot_target_track(slot)
              if tr then
                for i = 0, r.CountTrackMediaItems(tr) - 1 do
                  local item = r.GetTrackMediaItem(tr, i)
                  if item and seq_item_is_owned(item, region.id) and seq_ingest_item_selected(item) then
                    child_selected = true
                    break
                  end
                end
              end
              if child_selected then
                break
              end
            end
            if not child_selected then
              local delta_qn = new_start - old_start
              for _, slot in ipairs(state.seq_tracks or {}) do
                local tr = get_seq_slot_target_track(slot)
                if tr then
                  for i = 0, r.CountTrackMediaItems(tr) - 1 do
                    local item = r.GetTrackMediaItem(tr, i)
                    if item and seq_item_is_owned(item, region.id) then
                      local pos = r.GetMediaItemInfo_Value(item, "D_POSITION")
                      local qn = time_to_qn(pos)
                      local t2 = qn and qn_to_time(qn + delta_qn)
                      if t2 then
                        r.SetMediaItemPosition(item, t2, false)
                      end
                    end
                  end
                end
              end
            end
          end
          if rec.item then
            seq_write_parent_item_ext(rec.item, region)
          end
        else
          seq_write_parent_item_ext(rec.item, region)
        end
        changed = true
      end
    end
  end

  local to_delete = {}
  for _, region in ipairs(state.seq_regions or {}) do
    if region.parent_item_guid and region.parent_item_guid ~= "" and not by_guid[region.parent_item_guid]
        and not claimed[region.id] then
      table.insert(to_delete, region)
    end
  end
  for _, region in ipairs(to_delete) do
    seq_delete_region_keep_pattern(region)
    changed = true
    needs_note_sync = true
  end

  if not changed then
    for _, region in ipairs(state.seq_regions or {}) do
      if not region.parent_item_guid or region.parent_item_guid == "" then
        seq_sync_region_parent_item(region)
        changed = true
      end
    end
  end

  return changed, needs_note_sync
end

function seq_item_source_path(item)
  if not item then
    return nil
  end
  local take = r.GetActiveTake(item)
  if not take then
    return nil
  end
  if r.TakeIsMIDI and r.TakeIsMIDI(take) then
    return nil
  end
  local src = r.GetMediaItemTake_Source(take)
  if not src then
    return nil
  end
  if r.GetMediaSourceParent then
    local parent = r.GetMediaSourceParent(src)
    local guard = 0
    while parent and guard < 8 do
      src = parent
      parent = r.GetMediaSourceParent(src)
      guard = guard + 1
    end
  end
  if not r.GetMediaSourceFileName then
    return nil
  end
  local a, b = r.GetMediaSourceFileName(src, "")
  local path = nil
  if type(b) == "string" and b ~= "" then
    path = b
  elseif type(a) == "string" and a ~= "" then
    path = a
  end
  if not path or path == "" then
    return nil
  end
  return normalize_path(path)
end

function seq_ingest_slot_track(slot)
  if not slot or not slot.reaper_track_guid then
    return nil
  end
  return get_track_by_guid(slot.reaper_track_guid)
end

function remove_seq_rendered_items(region)
  local removed = 0
  local region_id = region and region.id or nil
  local tr_count = r.CountTracks(0)
  for tr_idx = 0, tr_count - 1 do
    local tr = r.GetTrack(0, tr_idx)
    for item_idx = r.CountTrackMediaItems(tr) - 1, 0, -1 do
      local item = r.GetTrackMediaItem(tr, item_idx)
      if item and seq_item_is_owned(item, region_id) then
        if r.DeleteTrackMediaItem(tr, item) then
          removed = removed + 1
        end
      end
    end
  end
  if removed > 0 then
    seq_mark_self_arrange_write()
  end
  return removed
end

function remove_seq_rendered_items_by_ids(id_set)
  if type(id_set) ~= "table" then
    return 0
  end
  local removed = 0
  local tr_count = r.CountTracks(0)
  for tr_idx = 0, tr_count - 1 do
    local tr = r.GetTrack(0, tr_idx)
    for item_idx = r.CountTrackMediaItems(tr) - 1, 0, -1 do
      local item = r.GetTrackMediaItem(tr, item_idx)
      if item and get_item_ext(item, SEQ_EXT_FLAG) == "1" then
        local rid = tonumber(get_item_ext(item, SEQ_EXT_REGION) or "")
        if rid and id_set[rid] then
          if r.DeleteTrackMediaItem(tr, item) then
            removed = removed + 1
          end
        end
      end
    end
  end
  if removed > 0 then
    seq_mark_self_arrange_write()
  end
  return removed
end

function seq_remove_orphaned_region_items()
  local removed = 0
  local tr_count = r.CountTracks(0)
  for tr_idx = 0, tr_count - 1 do
    local tr = r.GetTrack(0, tr_idx)
    for item_idx = r.CountTrackMediaItems(tr) - 1, 0, -1 do
      local item = r.GetTrackMediaItem(tr, item_idx)
      if item and seq_item_is_owned(item) then
        local tagged_rid = tonumber(get_item_ext(item, SEQ_EXT_REGION) or "")
        local tagged_reg = tagged_rid and get_seq_region_by_id(tagged_rid)
        if tagged_reg then
          local pos = r.GetMediaItemInfo_Value(item, "D_POSITION")
          local item_qn = time_to_qn(pos)
          if item_qn then
            local rs = tagged_reg.start_qn or 0.0
            local re = rs + get_seq_region_length_qn(tagged_reg)
            if item_qn < rs - 0.000001 or item_qn >= re - 0.000001 then
              if r.DeleteTrackMediaItem(tr, item) then
                removed = removed + 1
              end
            end
          end
        end
      end
    end
  end
  if removed > 0 then
    seq_mark_self_arrange_write()
  end
  return removed
end

SEQ_STUTTER_MIN = 2
SEQ_STUTTER_MAX = 256
SEQ_STUTTER_DRAG_PX = 8.0
SEQ_STUTTER_AXIS_PX = 6.0
SEQ_STUTTER_SKEW_MIN = -2.0
SEQ_STUTTER_SKEW_MAX = 2.0
SEQ_STUTTER_SKEW_PX = 70.0
SEQ_STUTTER_LANE_STACK_MAX = 32

function seq_stutter_count(note)
  return math.max(1, math.floor((note and note.stutter or 1) + 0.5))
end

function seq_stutter_span_qn(note, grid_qn)
  grid_qn = grid_qn or state.seq_grid_qn or 0.25
  local span = tonumber(note and note.length_qn)
  local has_span = type(span) == "number" and span > 1e-9
  if seq_stutter_count(note) <= 1 then
    -- Keep a painted multi-grid span after count returns to 1 so the block
    -- stays occupied and the amount can be dragged back up. Default one-grid
    -- length_qn is only a placeholder and must not replace sample sustain.
    if has_span and span > grid_qn + 1e-9 then
      return math.max(grid_qn * 0.25, span)
    end
    return nil
  end
  if has_span then
    return math.max(grid_qn * 0.25, span)
  end
  return grid_qn
end

function seq_note_has_stutter_span(note, grid_qn)
  local span = seq_stutter_span_qn(note, grid_qn)
  return type(span) == "number" and span > 1e-9
end

function seq_clamp_stutter_count(n)
  n = math.floor((tonumber(n) or 1) + 0.5)
  if n < 1 then n = 1 end
  if n > SEQ_STUTTER_MAX then n = SEQ_STUTTER_MAX end
  return n
end

function seq_stutter_skew(note)
  local s = tonumber(note and note.stutter_skew) or 0.0
  if s < SEQ_STUTTER_SKEW_MIN then return SEQ_STUTTER_SKEW_MIN end
  if s > SEQ_STUTTER_SKEW_MAX then return SEQ_STUTTER_SKEW_MAX end
  return s
end

function seq_stutter_hit_start_frac(count, hit_idx, skew)
  count = math.max(1, math.floor((count or 1) + 0.5))
  local i = math.max(1, math.min(count, math.floor((hit_idx or 1) + 0.5)))
  if count <= 1 or i <= 1 then
    return 0.0
  end
  local u = (i - 1) / count
  skew = tonumber(skew) or 0.0
  if math.abs(skew) < 1e-6 then
    return u
  end
  -- Positive skew bunches hits toward the end (drag right).
  return u ^ (2 ^ (-skew))
end

function seq_stutter_hit_end_frac(count, hit_idx, skew)
  count = math.max(1, math.floor((count or 1) + 0.5))
  local i = math.max(1, math.min(count, math.floor((hit_idx or 1) + 0.5)))
  if i >= count then
    return 1.0
  end
  return seq_stutter_hit_start_frac(count, i + 1, skew)
end

function seq_stutter_hit_span(note, hit_idx, grid_qn)
  local count = seq_stutter_count(note)
  local span = seq_stutter_span_qn(note, grid_qn) or (grid_qn or 0.25)
  local skew = seq_stutter_skew(note)
  local f0 = seq_stutter_hit_start_frac(count, hit_idx, skew)
  local f1 = seq_stutter_hit_end_frac(count, hit_idx, skew)
  return span * f0, span * f1, span * math.max(0.0, f1 - f0)
end

function seq_stutter_count_from_relative_dy(origin_count, origin_y, my)
  local dy = (origin_y or my or 0) - (my or origin_y or 0)
  local steps = dy / SEQ_STUTTER_DRAG_PX
  if steps >= 0 then
    steps = math.floor(steps)
  else
    steps = math.ceil(steps)
  end
  return seq_clamp_stutter_count((origin_count or 1) + steps)
end

function seq_stutter_skew_from_dx(origin_skew, origin_x, mx)
  local dx = (mx or origin_x or 0) - (origin_x or mx or 0)
  local skew = (origin_skew or 0.0) + dx / SEQ_STUTTER_SKEW_PX
  if skew < SEQ_STUTTER_SKEW_MIN then return SEQ_STUTTER_SKEW_MIN end
  if skew > SEQ_STUTTER_SKEW_MAX then return SEQ_STUTTER_SKEW_MAX end
  if math.abs(skew) < 0.001 then return 0.0 end
  return skew
end

function seq_set_stutter_skew(note, skew)
  if type(note) ~= "table" then
    return false
  end
  skew = seq_stutter_skew({ stutter_skew = skew })
  local cur = tonumber(note.stutter_skew) or 0.0
  if math.abs(cur - skew) < 1e-6 then
    return false
  end
  note.stutter_skew = (math.abs(skew) < 1e-4) and nil or skew
  return true
end

function seq_clear_stutter_badge_hits()
  state.seq_stutter_badge_hits = {}
end

function seq_register_stutter_badge_hit(x0, y0, x1, y1, track_id, region_id, step_key)
  if not x0 or not y0 or not x1 or not y1 then
    return
  end
  state.seq_stutter_badge_hits = state.seq_stutter_badge_hits or {}
  state.seq_stutter_badge_hits[#state.seq_stutter_badge_hits + 1] = {
    x0 = x0 - 3, y0 = y0 - 3, x1 = x1 + 3, y1 = y1 + 3,
    track_id = track_id, region_id = region_id, step_key = step_key,
  }
end

function seq_stutter_badge_at(mx, my)
  local hits = state.seq_stutter_badge_hits
  if not hits or mx == nil or my == nil then
    return nil
  end
  for i = #hits, 1, -1 do
    local h = hits[i]
    if mx >= h.x0 and mx <= h.x1 and my >= h.y0 and my <= h.y1 then
      return h
    end
  end
  return nil
end

function seq_note_draw_length_qn(region, pattern, slot, track_id, step_idx, note, resolved_sample, grid_qn)
  grid_qn = grid_qn or state.seq_grid_qn or 0.25
  local span = seq_stutter_span_qn(note, grid_qn)
  if span then
    return span
  end
  local len = seq_effective_note_length_qn(region, pattern, slot, track_id, step_idx, note, resolved_sample, grid_qn)
  local decay_qn = tonumber(note and note.decay_qn)
  if type(decay_qn) == "number" and decay_qn > 1e-9 then
    return len
  end
  local resolved_path = (resolved_sample and resolved_sample.path)
    or (note and note.frozen_sample_path)
    or (note and note.sample_path)
    or (slot and slot.sample_path)
  local sample_qn = seq_sample_length_qn(resolved_path, resolved_sample)
  -- Long samples stay at least one full grid cell so a nearby next hit
  -- cannot collapse the block into a sliver.
  if sample_qn and sample_qn > grid_qn + 1e-9 then
    len = math.max(len or 0, grid_qn)
  end
  return seq_cap_length_to_region_end_qn(len, region, step_idx, note, grid_qn)
end

function seq_note_head_end_x(qn_to_x, note_abs_qn, note, step_qn)
  if not qn_to_x then
    return nil
  end
  local vis = (note_abs_qn or 0.0) + ((note and note.offset_qn) or 0.0)
  return qn_to_x(vis + (step_qn or 0.25)) - 2.0
end

-- True when this occupied cell is the note's start cell (or a stutter span).
-- Head/sustain that draws into the next grid is not playable: that cell stays
-- empty so hover shows the grid and a click paints a new note.
function seq_active_cell_is_playable(active, start_qn, col, step_qn)
  if not active or type(active.note) ~= "table" then
    return false
  end
  if seq_note_has_stutter_span(active.note, step_qn) then
    return true
  end
  local vis = (active.abs_qn or 0.0) + (active.note.offset_qn or 0.0)
  local cell_qn = (start_qn or 0.0) + (col or 0) * (step_qn or 0.25)
  return vis >= cell_qn - 1e-9 and vis < cell_qn + (step_qn or 0.25) - 1e-9
end

function seq_stutter_count_from_drag_dy(origin_y, my)
  local dy = math.abs((my or origin_y or 0) - (origin_y or 0))
  return seq_clamp_stutter_count(SEQ_STUTTER_MIN + math.floor(dy / SEQ_STUTTER_DRAG_PX))
end

SEQ_STUTTER_HIT_KEYS = {
  volume = true,
  pan = true,
  pitch = true,
  sample_vary = true,
  offset_qn = true,
  stretch = true,
  start = true,
}

function seq_stutter_hit_param_key(key)
  return (key and SEQ_STUTTER_HIT_KEYS[key]) and key or nil
end

function seq_stutter_hit_table(note, hit_idx)
  if type(note) ~= "table" or type(note.stutter_hits) ~= "table" or not hit_idx then
    return nil
  end
  local hit = note.stutter_hits[hit_idx]
  if type(hit) ~= "table" then
    hit = note.stutter_hits[tostring(hit_idx)]
  end
  if type(hit) == "table" then
    return hit
  end
  return nil
end

function seq_note_has_hit_sample_vary(note)
  if type(note) ~= "table" then
    return false
  end
  if (tonumber(note.sample_vary) or 0) > 0.000001 then
    return true
  end
  if type(note.stutter_hits) ~= "table" then
    return false
  end
  for _, hit in pairs(note.stutter_hits) do
    if type(hit) == "table" and (tonumber(hit.sample_vary) or 0) > 0.000001 then
      return true
    end
  end
  return false
end

function seq_note_has_frozen_sample(note)
  if type(note) ~= "table" then
    return false
  end
  if type(note.frozen_sample_path) == "string" and note.frozen_sample_path ~= "" then
    return true
  end
  if type(note.stutter_hits) ~= "table" then
    return false
  end
  for _, hit in pairs(note.stutter_hits) do
    if type(hit) == "table" and type(hit.frozen_sample_path) == "string" and hit.frozen_sample_path ~= "" then
      return true
    end
  end
  return false
end

function seq_clear_frozen_sample(note, hit_idx)
  if type(note) ~= "table" then
    return
  end
  if hit_idx then
    local hit = seq_stutter_hit_table(note, hit_idx)
    if type(hit) == "table" then
      hit.frozen_sample_path = nil
      hit.frozen_sample_name = nil
      hit.vary_origin_path = nil
      hit.vary_rgb = nil
      hit.picked_sample = nil
    end
    return
  end
  note.frozen_sample_path = nil
  note.frozen_sample_name = nil
  note.vary_origin_path = nil
  note.vary_rgb = nil
  note.picked_sample = nil
  if type(note.stutter_hits) ~= "table" then
    return
  end
  for _, hit in pairs(note.stutter_hits) do
    if type(hit) == "table" then
      hit.frozen_sample_path = nil
      hit.frozen_sample_name = nil
      hit.vary_origin_path = nil
      hit.vary_rgb = nil
      hit.picked_sample = nil
    end
  end
end

function seq_prune_stutter_hits(note)
  if type(note) ~= "table" then
    return
  end
  local count = seq_stutter_count(note)
  if type(note.stutter_hits) ~= "table" then
    return
  end
  if count <= 1 then
    note.stutter_hits = nil
    return
  end
  local stale = {}
  for k, _ in pairs(note.stutter_hits) do
    local i = tonumber(k)
    if i and i > count then
      stale[#stale + 1] = k
    end
  end
  for i = 1, #stale do
    note.stutter_hits[stale[i]] = nil
  end
  local any = false
  for _, hit in pairs(note.stutter_hits) do
    if type(hit) == "table" then
      any = true
      break
    end
  end
  if not any then
    note.stutter_hits = nil
  end
end

function seq_note_param_value(note, key, hit_idx)
  if not note or not key then
    return nil
  end
  if key == "locked" then
    return seq_note_is_locked(note) and 1.0 or 0.0
  end
  if hit_idx and SEQ_STUTTER_HIT_KEYS[key] then
    local hit = seq_stutter_hit_table(note, hit_idx)
    if type(hit) == "table" and hit[key] ~= nil then
      return hit[key]
    end
  end
  return note[key]
end

function seq_set_note_param_value(note, key, value, hit_idx)
  if not note or not key then
    return false
  end
  if key == "locked" then
    local locked = value == true or (tonumber(value) or 0) >= 0.5
    if seq_note_is_locked(note) == locked then
      return false
    end
    note.locked = locked or nil
    return true
  end
  if key == "stutter" then
    local new_count = seq_clamp_stutter_count(value)
    if note.stutter == new_count then
      seq_prune_stutter_hits(note)
      return false
    end
    note.stutter = new_count
    seq_prune_stutter_hits(note)
    return true
  end
  if hit_idx and SEQ_STUTTER_HIT_KEYS[key] and seq_stutter_count(note) > 1 then
    note.stutter_hits = note.stutter_hits or {}
    local hit = seq_stutter_hit_table(note, hit_idx)
    if type(hit) ~= "table" then
      hit = {}
      note.stutter_hits[hit_idx] = hit
    end
    if hit[key] == value then
      return false
    end
    hit[key] = value
    if key == "sample_vary" then
      seq_clear_frozen_sample(note, hit_idx)
    end
    return true
  end
  if note[key] == value then
    return false
  end
  note[key] = value
  if key == "sample_vary" then
    seq_clear_frozen_sample(note)
  end
  return true
end

function seq_reset_note_param_value(note, key, hit_idx, default_value)
  if not note or not key then
    return false
  end
  if key == "locked" then
    return seq_set_note_param_value(note, "locked", 0)
  end
  if hit_idx and SEQ_STUTTER_HIT_KEYS[key] and seq_stutter_count(note) > 1 then
    return seq_set_note_param_value(note, key, default_value, hit_idx)
  end
  local changed = false
  if note[key] ~= default_value then
    note[key] = default_value
    changed = true
  end
  if note.stutter_hits and SEQ_STUTTER_HIT_KEYS[key] then
    for _, hit in pairs(note.stutter_hits) do
      if type(hit) == "table" and hit[key] ~= nil then
        hit[key] = nil
        changed = true
      end
    end
  end
  if key == "stutter" then
    seq_prune_stutter_hits(note)
    if seq_set_stutter_skew(note, 0) then
      changed = true
    end
  end
  if key == "sample_vary" and seq_note_has_frozen_sample(note) then
    seq_clear_frozen_sample(note, hit_idx)
    changed = true
  end
  return changed
end

function seq_stutter_hit_index_at_qn(note, note_abs_qn, qn, grid_qn)
  local count = seq_stutter_count(note)
  if count <= 1 then
    return nil
  end
  local span = seq_stutter_span_qn(note, grid_qn) or grid_qn
  if not span or span <= 1e-9 then
    return 1
  end
  local start = (note_abs_qn or 0.0) + ((note and note.offset_qn) or 0.0)
  local t = ((qn or start) - start) / span
  if t < 0 then t = 0 end
  if t >= 1 then t = 0.999999 end
  local skew = seq_stutter_skew(note)
  if math.abs(skew) > 1e-6 then
    local exp = 2 ^ (-skew)
    if exp > 1e-6 then
      t = t ^ (1.0 / exp)
    end
  end
  return math.max(1, math.min(count, math.floor(t * count) + 1))
end

function seq_stutter_hits_overlapping_qn_range(note, note_abs_qn, qn0, qn1, grid_qn)
  local count = seq_stutter_count(note)
  if count <= 1 then
    return nil
  end
  local start = (note_abs_qn or 0.0) + ((note and note.offset_qn) or 0.0)
  local hits = {}
  for hi = 1, count do
    local off0, off1 = seq_stutter_hit_span(note, hi, grid_qn)
    local s0 = start + off0
    local s1 = start + off1
    if s0 < (qn1 or s0) - 1e-9 and s1 > (qn0 or s0) + 1e-9 then
      hits[#hits + 1] = hi
    end
  end
  return hits
end

function seq_note_for_stutter_hit(note, hit_idx)
  if type(note) ~= "table" then
    return note
  end
  local hit = seq_stutter_hit_table(note, hit_idx)
  return {
    enabled = note.enabled ~= false,
    sample_path = note.sample_path,
    sample_name = note.sample_name,
    frozen_sample_path = (hit and hit.frozen_sample_path) or note.frozen_sample_path,
    frozen_sample_name = (hit and hit.frozen_sample_name) or note.frozen_sample_name,
    vary_origin_path = (hit and hit.vary_origin_path) or note.vary_origin_path,
    vary_rgb = (hit and hit.vary_rgb) or note.vary_rgb,
    picked_sample = (hit and hit.picked_sample) or note.picked_sample,
    volume = seq_note_param_value(note, "volume", hit_idx) or 1.0,
    pan = seq_note_param_value(note, "pan", hit_idx) or 0.0,
    pitch = seq_note_param_value(note, "pitch", hit_idx) or 0.0,
    sample_vary = seq_note_param_value(note, "sample_vary", hit_idx) or 0.0,
    offset_qn = seq_note_param_value(note, "offset_qn", hit_idx) or 0.0,
    stretch = seq_note_param_value(note, "stretch", hit_idx) or 1.0,
    start = seq_note_param_value(note, "start", hit_idx) or 0.0,
    length_qn = note.length_qn,
    decay_qn = note.decay_qn,
    fade_in_qn = note.fade_in_qn,
    fade_out_qn = note.fade_out_qn,
    fade_in_shape = note.fade_in_shape,
    fade_out_shape = note.fade_out_shape,
    fade_in_curve = note.fade_in_curve,
    fade_out_curve = note.fade_out_curve,
    stutter = 1,
    locked = note.locked,
  }
end

function seq_apply_param_to_note(note, abs_qn, def, value, qn, step_qn, reset, all_hits_in_range, range_qn0, range_qn1)
  if not note or not def then
    return false
  end
  local key = def.key
  if key == "decay" then
    return false
  end
  if key == "locked" or def.boolean then
    return seq_set_note_param_value(note, "locked", reset and 0 or 1)
  end
  if reset and not seq_stutter_hit_param_key(key) then
    return seq_reset_note_param_value(note, key, nil, def.default)
  end
  if all_hits_in_range and seq_stutter_hit_param_key(key) then
    local hits = seq_stutter_hits_overlapping_qn_range(note, abs_qn, range_qn0, range_qn1, step_qn)
    if hits and #hits > 0 then
      local changed = false
      for i = 1, #hits do
        if reset then
          if seq_reset_note_param_value(note, key, hits[i], def.default) then
            changed = true
          end
        elseif seq_set_note_param_value(note, key, value, hits[i]) then
          changed = true
        end
      end
      return changed
    end
  end
  local hit_idx = seq_stutter_hit_param_key(key) and seq_stutter_hit_index_at_qn(note, abs_qn, qn, step_qn) or nil
  if reset then
    return seq_reset_note_param_value(note, key, hit_idx, def.default)
  end
  return seq_set_note_param_value(note, key, value, hit_idx)
end

function seq_note_qn_range(note, step_key, grid_qn)
  local start_qn = seq_note_qn_offset(note, step_key, grid_qn)
  local span = seq_stutter_span_qn(note, grid_qn)
  if span then
    return start_qn, start_qn + span
  end
  return start_qn, start_qn
end

function seq_find_slot_by_id(track_id)
  for _, slot in ipairs(state.seq_tracks or {}) do
    if slot.id == track_id then
      return slot
    end
  end
  return nil
end

function seq_delete_notes_overlapping_span(region, slot, span_start, span_end, keep_key, grid_qn, opts)
  if not region or not slot then
    return false
  end
  opts = opts or {}
  local notes = get_track_note_table(get_seq_pattern(region.pattern_id, false), slot.id, false)
  if not notes then
    return false
  end
  keep_key = tostring(keep_key or "")
  local slop = opts.slop or 1e-4
  local to_delete = {}
  for key, note in pairs(notes) do
    if tostring(key) ~= keep_key and type(note) == "table" then
      local n_start, n_end = seq_note_qn_range(note, key, grid_qn)
      local overlaps
      if opts.same_start then
        -- Off-grid inserts keep later grid hits even when sustain draws over them.
        overlaps = math.abs(n_start - (span_start or 0.0)) <= slop
      elseif n_end > n_start + 1e-9 then
        overlaps = n_start < span_end - 1e-9 and n_end > span_start + 1e-9
      else
        overlaps = n_start >= span_start - 1e-9 and n_start < span_end - 1e-9
      end
      if overlaps then
        to_delete[#to_delete + 1] = { key = key, note = note }
      end
    end
  end
  if #to_delete == 0 then
    return false
  end
  for i = 1, #to_delete do
    local item = to_delete[i]
    register_seq_note_anim(region.id, slot.id, item.key, item.note, "delete")
    delete_seq_note(region, slot.id, item.key)
    if not opts.defer_arrange then
      remove_seq_rendered_items_for_step(region, slot, slot.id, item.key)
    end
  end
  return true
end

function seq_active_cells_put(active_cells, slot_id, col, entry, start_qn, step_qn, step_count)
  if not active_cells or not active_cells[slot_id] or col < 0 or col >= step_count then
    return
  end
  local cell = active_cells[slot_id][col]
  if not cell then
    active_cells[slot_id][col] = {
      key = entry.key,
      note = entry.note,
      region_id = entry.region_id,
      abs_qn = entry.abs_qn,
      pack = { entry },
    }
    return
  end
  cell.pack[#cell.pack + 1] = entry
  seq_pack_sort_later_on_top(cell.pack)
  local top = cell.pack[#cell.pack]
  cell.key = top.key
  cell.note = top.note
  cell.region_id = top.region_id
  cell.abs_qn = top.abs_qn
end

function apply_seq_note_params(item, take, note)
  if item then
    -- Item vol and take vol multiply. Keep the item at unity and put
    -- note velocity on the take so 1.0 stays 0 dB.
    r.SetMediaItemInfo_Value(item, "D_VOL", 1.0)
    r.SetMediaItemInfo_Value(item, "B_LOOPSRC", 0)
  end
  if take then
    r.SetMediaItemTakeInfo_Value(take, "D_VOL", note.volume or 1.0)
    r.SetMediaItemTakeInfo_Value(take, "D_PAN", note.pan or 0.0)
    r.SetMediaItemTakeInfo_Value(take, "D_PITCH", note.pitch or 0.0)
    local stretch = seq_note_stretch_amount(note)
    r.SetMediaItemTakeInfo_Value(take, "D_PLAYRATE", 1.0 / stretch)
    r.SetMediaItemTakeInfo_Value(take, "B_PPITCH", 1)
  end
end

-- ===== Sequencer track mix + drum volume envelope ========================
-- Per-track volume/pan/mute/solo control the linked REAPER track. A free
-- breakpoint envelope (arbitrary points in sample time) is stamped onto every
-- synced hit as a take volume envelope so it shapes each drum instance.

SEQ_ENV_AMP_MAX = 3.0
SEQ_ENV_POINT_LIMIT = 64
SEQ_ENV_PREVIEW_W = 100.0
SEQ_ENV_CURVE_KMAX = 7.0

function seq_default_track_env()
  return {
    points = {
      { t = 0.0, amp = 1.0 },
      { t = 1.0, amp = 1.0 },
    },
  }
end

function seq_env_clamp_amp(amp)
  amp = tonumber(amp) or 1.0
  if amp < 0.0 then return 0.0 end
  if amp > 4.0 then return 4.0 end
  return amp
end

function seq_env_sort_points(points)
  table.sort(points, function(a, b)
    return (a.t or 0.0) < (b.t or 0.0)
  end)
  return points
end

-- Convert the previous ADSR + item-fade envelope into free points.
function seq_legacy_adsr_to_points(env, length)
  env = env or {}
  length = math.max(0.001, length or 0.25)
  local atk = math.max(0.0, math.min(0.25, tonumber(env.atk) or 0.0))
  local dec = math.max(0.0, math.min(0.40, tonumber(env.decay) or 0.02))
  local rel = math.max(0.0, math.min(0.80, tonumber(env.release) or 0.0))
  local peak = math.min(4.0, 1.0 + math.max(0.0, math.min(2.0, tonumber(env.transient) or 0.0)))
  local sus = math.max(0.0, math.min(peak, tonumber(env.sustain) or 1.0))
  local fade_in = math.max(0.0, tonumber(env.fade_in) or 0.0)
  local fade_out = math.max(0.0, tonumber(env.fade_out) or 0.0)
  local has_shape = atk > 0.0005
      or (tonumber(env.transient) or 0.0) > 0.001
      or sus < 0.999
      or rel > 0.0005
  local has_fade = fade_in > 0.0005 or fade_out > 0.0005
  if not has_shape and not has_fade then
    return { { t = 0.0, amp = 1.0 }, { t = length, amp = 1.0 } }
  end

  atk = math.min(atk, length * 0.49)
  rel = math.min(rel, length * 0.49)
  local t_dec = math.min(length, atk + dec)
  local t_rel = math.max(t_dec, length - rel)
  local pts = {}
  local function add(t, amp)
    t = math.max(0.0, math.min(length, t))
    amp = seq_env_clamp_amp(amp)
    local last = pts[#pts]
    if last and math.abs(last.t - t) < 0.00005 then
      last.amp = amp
      return
    end
    pts[#pts + 1] = { t = t, amp = amp }
  end

  if has_shape then
    if atk > 0.0005 then
      add(0.0, 0.00001)
      add(atk, peak)
    else
      add(0.0, peak)
    end
    if t_dec > atk + 0.00005 then
      add(t_dec, sus)
    elseif math.abs(peak - sus) > 0.001 then
      add(math.min(length, atk + 0.001), sus)
    end
    if t_rel > t_dec + 0.00005 then
      add(t_rel, sus)
    end
    if rel > 0.0005 then
      add(length, 0.00001)
    else
      add(length, sus)
    end
  else
    add(0.0, 1.0)
    add(length, 1.0)
  end

  if fade_in > 0.0005 then
    add(0.0, 0.00001)
    add(math.min(length, fade_in), seq_env_levels_at({ points = pts }, fade_in, length))
  end
  if fade_out > 0.0005 then
    local t_fo = math.max(0.0, length - fade_out)
    add(t_fo, seq_env_levels_at({ points = pts }, t_fo, length))
    add(length, 0.00001)
  end
  seq_env_sort_points(pts)
  return pts
end

function seq_normalize_track_env(env)
  if type(env) ~= "table" then
    return seq_default_track_env()
  end
  local pts = {}
  if type(env.points) == "table" then
    for _, p in ipairs(env.points) do
      if type(p) == "table" then
        pts[#pts + 1] = {
          t = math.max(0.0, tonumber(p.t) or 0.0),
          amp = seq_env_clamp_amp(p.amp),
          curve = seq_env_clamp_curve(p.curve),
        }
      end
    end
  end
  if #pts == 0 then
    local atk = tonumber(env.atk) or 0.0
    local dec = tonumber(env.decay) or 0.0
    local rel = tonumber(env.release) or 0.0
    local fi = tonumber(env.fade_in) or 0.0
    local fo = tonumber(env.fade_out) or 0.0
    local length = math.max(0.25, atk + dec + rel + 0.10, fi + fo + 0.05)
    pts = seq_legacy_adsr_to_points(env, length)
  end
  if #pts == 0 then
    pts = { { t = 0.0, amp = 1.0 }, { t = 1.0, amp = 1.0 } }
  end
  seq_env_sort_points(pts)
  local merged = {}
  for _, p in ipairs(pts) do
    local last = merged[#merged]
    if last and math.abs(last.t - p.t) < 0.00005 then
      last.amp = p.amp
      last.curve = p.curve
    else
      merged[#merged + 1] = p
    end
  end
  if #merged > SEQ_ENV_POINT_LIMIT then
    local kept = { merged[1] }
    local extra = SEQ_ENV_POINT_LIMIT - 2
    local inner = #merged - 2
    if extra > 0 and inner > 0 then
      for i = 1, extra do
        local idx = 1 + math.floor(i * inner / (extra + 1) + 0.5)
        kept[#kept + 1] = merged[math.max(2, math.min(#merged - 1, idx + 1))]
      end
    end
    kept[#kept + 1] = merged[#merged]
    merged = kept
  end
  for i = 1, #merged - 1 do
    merged[i].curve = seq_env_seg_clamp_curve(merged[i].amp, merged[i + 1].amp, merged[i].curve)
  end
  if #merged > 0 then
    merged[#merged].curve = 0.0
  end
  return { points = merged }
end

function seq_env_insert_point(points, t, amp)
  points = points or {}
  t = math.max(0.0, tonumber(t) or 0.0)
  amp = seq_env_clamp_amp(amp)
  local idx = #points + 1
  for i, p in ipairs(points) do
    if t < (p.t or 0.0) then
      idx = i
      break
    end
  end
  table.insert(points, idx, { t = t, amp = amp, curve = 0.0 })
  return idx
end

function seq_env_clamp_curve(curve)
  curve = tonumber(curve) or 0.0
  if curve < -1.0 then return -1.0 end
  if curve > 1.0 then return 1.0 end
  if math.abs(curve) < 0.0005 then return 0.0 end
  return curve
end

-- curve is signed ease strength in [-1, 1], independent of amplitude span.
-- Power eases stay between the two endpoints, so they cannot overshoot.
function seq_env_seg_clamp_curve(amp0, amp1, curve)
  return seq_env_clamp_curve(curve)
end

function seq_env_seg_ease(u, curve)
  u = tonumber(u) or 0.0
  if u < 0.0 then u = 0.0 elseif u > 1.0 then u = 1.0 end
  curve = seq_env_clamp_curve(curve)
  if math.abs(curve) < 0.0005 then
    return u
  end
  local kmax = SEQ_ENV_CURVE_KMAX or 7.0
  local k = 1.0 + math.abs(curve) * (kmax - 1.0)
  if curve > 0.0 then
    return u ^ k
  end
  return 1.0 - (1.0 - u) ^ k
end

-- Positive curve holds the first point longer; negative jumps toward the second.
-- Always stays between amp0 and amp1.
function seq_env_seg_eval(amp0, amp1, u, curve)
  amp0 = amp0 or 1.0
  amp1 = amp1 or 1.0
  return amp0 + (amp1 - amp0) * seq_env_seg_ease(u, curve)
end

function seq_env_seg_curve_for_amp(amp0, amp1, u, amp)
  amp0 = amp0 or 1.0
  amp1 = amp1 or 1.0
  u = tonumber(u) or 0.5
  if u < 0.08 then u = 0.08 elseif u > 0.92 then u = 0.92 end
  local span = amp1 - amp0
  if math.abs(span) < 0.0001 then
    return 0.0
  end
  local lo, hi = amp0, amp1
  if hi < lo then lo, hi = hi, lo end
  amp = tonumber(amp) or (amp0 + span * u)
  if amp < lo then amp = lo elseif amp > hi then amp = hi end
  local n = (amp - amp0) / span
  if n < 0.0001 then n = 0.0001 elseif n > 0.9999 then n = 0.9999 end
  local kmax = SEQ_ENV_CURVE_KMAX or 7.0
  local function k_to_curve(k, sign)
    k = math.max(1.0, math.min(kmax, k))
    return seq_env_clamp_curve(sign * (k - 1.0) / (kmax - 1.0))
  end
  if math.abs(n - u) < 0.002 then
    return 0.0
  end
  if n < u then
    local lu = math.log(u)
    if math.abs(lu) < 1e-8 then return 0.0 end
    return k_to_curve(math.log(n) / lu, 1.0)
  end
  local l1 = math.log(1.0 - u)
  if math.abs(l1) < 1e-8 then return 0.0 end
  return k_to_curve(math.log(1.0 - n) / l1, -1.0)
end

function seq_env_format_point_tip(t, amp)
  local db = seq_format_track_volume(amp or 1.0)
  if db == "-inf" then
    db = "-inf dB"
  else
    db = db .. " dB"
  end
  return string.format("%.0f ms · %s", (t or 0.0) * 1000.0, db)
end

function seq_env_sync_to_length(env, length)
  env = seq_normalize_track_env(env)
  length = math.max(0.001, length or 1.0)
  if not seq_env_shape_active(env) then
    env.points = {
      { t = 0.0, amp = 1.0 },
      { t = length, amp = 1.0 },
    }
    return env
  end
  for _, p in ipairs(env.points) do
    if (p.t or 0.0) > length then
      p.t = length
    end
  end
  seq_env_sort_points(env.points)
  return env
end

-- REAPER track volume: linear amplitude → dB (1.0 = 0 dB, 4.0 ≈ +12 dB).
-- Global helpers (not local) to stay under Lua's 200-local main-chunk limit.
function seq_format_track_volume(v)
  if not v or v < 0.0000000298023223876953125 then return "-inf" end
  local db = math.log(v) * 8.6858896380650365530225783783321
  if db >= -0.05 and db <= 0.05 then return "0.0" end
  if db > 0 then return string.format("+%.1f", db) end
  return string.format("%.1f", db)
end

-- Compact volume bar: linear in dB from -48 to +12 so 0 dB sits at 80%.
SEQ_VOL_FADER_MIN_DB = -48.0
SEQ_VOL_FADER_MAX_DB = 12.0

function seq_vol_amp_to_pos(amp)
  if not amp or amp < 0.0000000298023223876953125 then
    return 0.0
  end
  local db = math.log(amp) * 8.6858896380650365530225783783321
  local t = (db - SEQ_VOL_FADER_MIN_DB) / (SEQ_VOL_FADER_MAX_DB - SEQ_VOL_FADER_MIN_DB)
  if t < 0.0 then return 0.0 end
  if t > 1.0 then return 1.0 end
  return t
end

function seq_vol_pos_to_amp(pos)
  pos = math.max(0.0, math.min(1.0, pos or 0.0))
  if pos <= 0.0 then
    return 0.0
  end
  local db = SEQ_VOL_FADER_MIN_DB + pos * (SEQ_VOL_FADER_MAX_DB - SEQ_VOL_FADER_MIN_DB)
  local amp = math.exp(db * 0.11512925464970228420089957273422)
  if amp > 4.0 then
    return 4.0
  end
  return amp
end

function seq_format_track_pan(v)
  local pct = math.floor(math.abs(v or 0) * 100.0 + 0.5)
  if pct == 0 then return "C" end
  if (v or 0) < 0 then return tostring(pct) .. "L" end
  return tostring(pct) .. "R"
end

function seq_normalize_slot_mix(slot)
  if not slot then return end
  if type(slot.volume) ~= "number" then slot.volume = 1.0 end
  -- Match REAPER track fader range: 0 (-inf) .. 4 (+12 dB), unity at 1.0
  slot.volume = math.max(0.0, math.min(4.0, slot.volume))
  if type(slot.pan) ~= "number" then slot.pan = 0.0 end
  slot.pan = math.max(-1.0, math.min(1.0, slot.pan))
  slot.mute = slot.mute == true
  slot.solo = slot.solo == true
  slot.overlap = slot.overlap == true
  slot.env = seq_normalize_track_env(slot.env)
  seq_normalize_slot_layers(slot)
  seq_normalize_slot_midi(slot)
  seq_normalize_slot_candidates(slot)
end

function seq_midi_clamp_note(n)
  n = math.floor(tonumber(n) or 0)
  if n < 0 then return 0 end
  if n > 127 then return 127 end
  return n
end

function seq_midi_note_name(n)
  n = seq_midi_clamp_note(n)
  return (SEQ_MIDI_PC_NAMES[(n % 12) + 1] or "?") .. tostring(math.floor(n / 12) - 2)
end

function seq_midi_slot_label(slot)
  if not slot then return "--" end
  local lo = seq_midi_clamp_note(slot.midi_lo or 36)
  local hi = seq_midi_clamp_note(slot.midi_hi or lo)
  if lo > hi then lo, hi = hi, lo end
  if lo == hi then
    return seq_midi_note_name(lo)
  end
  return seq_midi_note_name(lo) .. "+"
end

function seq_midi_used_notes(ignore_slot)
  local used = {}
  for _, slot in ipairs(state.seq_tracks or {}) do
    if slot ~= ignore_slot then
      local lo = tonumber(slot.midi_lo)
      if lo then
        local hi = tonumber(slot.midi_hi) or lo
        if lo > hi then lo, hi = hi, lo end
        for n = lo, hi do
          used[n] = true
        end
      end
    end
  end
  return used
end

function seq_midi_default_note_for_slot(slot)
  local role = infer_seq_track_role(slot)
  local preferred = SEQ_MIDI_ROLE_NOTES[role] or 36
  local used = seq_midi_used_notes(slot)
  if not used[preferred] then
    return preferred
  end
  for delta = 1, 127 do
    local up, down = preferred + delta, preferred - delta
    if up <= 127 and not used[up] then return up end
    if down >= 0 and not used[down] then return down end
  end
  return preferred
end

function seq_normalize_slot_midi(slot)
  if not slot then return end
  local lo = tonumber(slot.midi_lo)
  local hi = tonumber(slot.midi_hi)
  if not lo then
    lo = seq_midi_default_note_for_slot(slot)
    hi = lo
  elseif not hi then
    hi = lo
  end
  lo = seq_midi_clamp_note(lo)
  hi = seq_midi_clamp_note(hi)
  if lo > hi then lo, hi = hi, lo end
  slot.midi_lo = lo
  slot.midi_hi = hi
end

function seq_midi_set_note(slot, note, as_range)
  if not slot then return false end
  note = seq_midi_clamp_note(note)
  seq_normalize_slot_midi(slot)
  if as_range then
    if note < slot.midi_lo then
      slot.midi_lo = note
    elseif note > slot.midi_hi then
      slot.midi_hi = note
    else
      slot.midi_lo = note
      slot.midi_hi = note
    end
  else
    slot.midi_lo = note
    slot.midi_hi = note
  end
  return true
end

function seq_midi_set_range(slot, lo, hi)
  if not slot then return false end
  lo = seq_midi_clamp_note(lo)
  hi = seq_midi_clamp_note(hi)
  if lo > hi then lo, hi = hi, lo end
  slot.midi_lo = lo
  slot.midi_hi = hi
  return true
end

function seq_midi_slot_matches(slot, note)
  if not slot then return false end
  note = tonumber(note)
  if not note then return false end
  seq_normalize_slot_midi(slot)
  return note >= slot.midi_lo and note <= slot.midi_hi
end

function seq_midi_any_solo()
  for _, slot in ipairs(state.seq_tracks or {}) do
    if slot.solo then return true end
  end
  return false
end

function seq_midi_slot_audible(slot)
  if not slot or slot.mute then return false end
  if seq_midi_any_solo() and not slot.solo then return false end
  return true
end

function seq_midi_stop_voice(slot_id)
  if slot_id == nil then return end
  local key = tostring(slot_id)
  local voice = seq_midi_voices[key]
  if not voice then return end
  if voice.preview and r.CF_Preview_Stop then
    pcall(r.CF_Preview_Stop, voice.preview)
  end
  if voice.source and r.PCM_Source_Destroy then
    pcall(r.PCM_Source_Destroy, voice.source)
  end
  seq_midi_voices[key] = nil
end

function seq_midi_stop_all_voices()
  for slot_id in pairs(seq_midi_voices) do
    seq_midi_stop_voice(slot_id)
  end
end

function seq_midi_trigger_slot(slot, vel)
  if not slot or not seq_midi_slot_audible(slot) then
    return false
  end
  vel = tonumber(vel) or 100
  if vel <= 0 then
    return false
  end
  if not slot.sample_path then
    return false
  end

  seq_midi_stop_voice(slot.id)
  local started = seq_player_trigger(slot, vel)
  if started then
    state.seq_track_play_anims = state.seq_track_play_anims or {}
    state.seq_track_play_anims[tostring(slot.id)] = {
      start_time = r.time_precise(),
      duration = 0.35,
    }
    return true
  end
  preview_seq_track_sample(slot)
  return true
end

function seq_midi_handle_note_on(note, vel)
  seq_midi_ensure_jsfx()
  note = seq_midi_clamp_note(note)
  vel = math.max(1, math.min(127, math.floor(tonumber(vel) or 100)))
  local now = r.time_precise()
  state.seq_midi_recent = state.seq_midi_recent or {}
  local last_t = state.seq_midi_recent[note]
  if last_t and (now - last_t) < 0.03 then
    return false
  end
  state.seq_midi_recent[note] = now
  local learn_id = state.seq_midi_learn_slot_id
  if learn_id then
    local slot = seq_find_track_slot_by_id(learn_id)
    if slot then
      seq_midi_set_note(slot, note, state.seq_midi_learn_range == true)
      state.seq_midi_learn_slot_id = nil
      state.seq_midi_learn_range = false
      save_config()
      if save_seq_project_state then save_seq_project_state() end
      seq_midi_trigger_slot(slot, vel)
      return true
    end
    state.seq_midi_learn_slot_id = nil
  end

  -- SampleMapPlayer plays via its trigger slider so the kit tracks meter.
  local hit = false
  for _, slot in ipairs(state.seq_tracks or {}) do
    if seq_midi_slot_matches(slot, note) then
      if seq_midi_trigger_slot(slot, vel) then
        hit = true
      end
    end
  end
  return hit
end

-- MIDI All devices / all channels. bits 0-4 = channel (0=all), bits 5-10 = device (63=all).
SEQ_MIDI_RECINPUT_ALL = 4096 + (63 * 32)
SEQ_MIDI_RECMODE_MONITOR = 2

function seq_midi_parent_track(create_if_missing)
  local tr = find_seq_parent_folder_track and find_seq_parent_folder_track() or nil
  if tr then
    return tr
  end
  if create_if_missing and create_seq_parent_folder_track then
    return create_seq_parent_folder_track()
  end
  return nil
end

function seq_midi_find_jsfx(tr)
  if not tr or not r.TrackFX_GetCount then
    return -1
  end
  local n = r.TrackFX_GetCount(tr) or 0
  for i = 0, n - 1 do
    local retval, name = r.TrackFX_GetFXName(tr, i, "")
    if type(retval) == "string" then
      name = retval
    end
    name = tostring(name or "")
    if name:find("Sample Map MIDI", 1, true) or name:find("SampleMapMIDI", 1, true) then
      return i
    end
  end
  return -1
end

function seq_midi_delete_jsfx(tr)
  if not tr or not r.TrackFX_Delete then
    return
  end
  local fx = seq_midi_find_jsfx(tr)
  if fx >= 0 then
    r.TrackFX_Delete(tr, fx)
  end
end

function seq_midi_strip_preview_jsfx()
  local tr = nil
  if preview_track then
    local valid = false
    if r.ValidatePtr2 then
      valid = r.ValidatePtr2(0, preview_track, "MediaTrack*") and true or false
    elseif r.ValidatePtr then
      valid = r.ValidatePtr(preview_track, "MediaTrack*") and true or false
    end
    if valid then
      tr = preview_track
    end
  end
  if not tr then
    for i = 0, r.CountTracks(0) - 1 do
      local cand = r.GetTrack(0, i)
      local _, name = r.GetTrackName(cand, "")
      if name == PREVIEW_TRACK_NAME then
        tr = cand
        break
      end
    end
  end
  if tr then
    seq_midi_delete_jsfx(tr)
  end
end

function seq_midi_ensure_jsfx()
  if not r.TrackFX_AddByName then
    state.seq_midi_jsfx_ready = false
    return false
  end
  local tr = seq_midi_parent_track(true)
  if not tr then
    state.seq_midi_jsfx_ready = false
    return false
  end
  local fx = seq_midi_find_jsfx(tr)
  if fx < 0 then
    for _, name in ipairs(SEQ_MIDI_JSFX_NAMES) do
      fx = r.TrackFX_AddByName(tr, name, false, 1)
      if fx and fx >= 0 then
        if r.TrackFX_SetOpen then
          r.TrackFX_SetOpen(tr, fx, false)
        end
        break
      end
    end
  end
  if fx and fx >= 0 then
    state.seq_midi_jsfx_ready = true
    seq_midi_strip_preview_jsfx()
    return true
  end
  state.seq_midi_jsfx_ready = false
  return false
end

function seq_player_find_jsfx(tr)
  if not tr or not r.TrackFX_GetCount then
    return -1
  end
  local n = r.TrackFX_GetCount(tr) or 0
  for i = 0, n - 1 do
    local retval, name = r.TrackFX_GetFXName(tr, i, "")
    if type(retval) == "string" then
      name = retval
    end
    name = tostring(name or "")
    if name:find("Sample Map Player", 1, true) or name:find("SampleMapPlayer", 1, true) then
      return i
    end
  end
  return -1
end

function seq_player_set_param(tr, fx, param, value)
  if not tr or not fx or fx < 0 or not r.TrackFX_SetParam then
    return
  end
  r.TrackFX_SetParam(tr, fx, param, value)
  if r.TrackFX_EndParamEdit then
    r.TrackFX_EndParamEdit(tr, fx, param)
  end
end

function seq_player_instance_id(slot)
  local id = math.floor(tonumber(slot and slot.id) or 0)
  if id < 1 then
    id = 1
  elseif id > 4095 then
    id = (id % 4095) + 1
  end
  return id
end

function seq_player_collect_layers(slot)
  local layers = {}
  if slot and seq_layering_is_active and seq_layering_is_active(slot) then
    seq_normalize_slot_layers(slot)
    local function add_side(side)
      if type(side) ~= "table" or type(side.verts) ~= "table" then
        return
      end
      for i = 1, 3 do
        local vert = side.verts[i]
        if vert and type(vert.path) == "string" and vert.path ~= "" then
          layers[#layers + 1] = {
            path = vert.path,
            vol = math.max(0.0, tonumber(vert.vol) or 1.0),
          }
          if #layers >= 6 then
            return
          end
        end
      end
    end
    add_side(slot.layers.transient)
    if #layers < 6 then
      add_side(slot.layers.sustain)
    end
  end
  if #layers == 0 and slot and type(slot.sample_path) == "string" and slot.sample_path ~= "" then
    layers[1] = { path = slot.sample_path, vol = 1.0 }
  end
  return layers
end

function seq_player_config_sig(slot)
  if not slot then
    return ""
  end
  seq_normalize_slot_midi(slot)
  local parts = {
    tostring(slot.id or ""),
    tostring(slot.reaper_track_guid or ""),
    tostring(slot.sample_path or ""),
    tostring(slot.midi_lo or 36),
    tostring(slot.midi_hi or slot.midi_lo or 36),
    slot.overlap and "1" or "0",
  }
  local layers = seq_player_collect_layers(slot)
  parts[#parts + 1] = tostring(#layers)
  for i = 1, #layers do
    parts[#parts + 1] = layers[i].path
    parts[#parts + 1] = string.format("%.5f", layers[i].vol or 1)
  end
  local env = seq_normalize_track_env(slot.env)
  local pts = env.points or {}
  parts[#parts + 1] = tostring(#pts)
  for i = 1, #pts do
    local p = pts[i]
    parts[#parts + 1] = string.format(
      "%.5f:%.5f:%.5f", p.t or 0, p.amp or 1, p.curve or 0)
  end
  return table.concat(parts, "\n")
end

function seq_player_cfg_paths(instance_id)
  local res = (r.GetResourcePath and r.GetResourcePath()) or ""
  local name = string.format("%d.txt", instance_id)
  return {
    res .. "/Effects/SampleMapPlayerData/" .. name,
    res .. "/SampleMapPlayerData/" .. name,
    res .. "/Data/SampleMapPlayerData/" .. name,
  }
end

function seq_player_write_cfg(slot)
  local id = seq_player_instance_id(slot)
  seq_normalize_slot_midi(slot)
  local layers = seq_player_collect_layers(slot)
  local env = seq_normalize_track_env(slot.env)
  local pts = env.points or {}
  if #pts < 1 then
    pts = { { t = 0, amp = 1, curve = 0 }, { t = 1, amp = 1, curve = 0 } }
  end
  if #pts > 32 then
    local trimmed = {}
    for i = 1, 32 do
      trimmed[i] = pts[i]
    end
    pts = trimmed
  end
  if #layers > 6 then
    local trimmed = {}
    for i = 1, 6 do
      trimmed[i] = layers[i]
    end
    layers = trimmed
  end
  local lo = slot.midi_lo or 36
  local hi = slot.midi_hi or lo
  local lines = {
    "SMP1",
    string.format(
      "%.9g %.9g %.9g %.9g %.9g %.9g %d %d",
      0, lo, hi, lo, 1, slot.overlap and 1 or 0, #pts, #layers
    ),
  }
  for i = 1, #pts do
    local p = pts[i]
    lines[#lines + 1] = string.format(
      "%.9g %.9g %.9g", p.t or 0, p.amp or 1, p.curve or 0)
  end
  for i = 1, #layers do
    local layer = layers[i]
    lines[#lines + 1] = string.format(
      "%.9g %.9g %.9g %.9g %.9g %.9g", 0, 0, 0, 0, 0, layer.vol or 1)
    lines[#lines + 1] = tostring(layer.path or ""):gsub("[\r\n]", "")
  end
  local body = table.concat(lines, "\n") .. "\n"
  local paths = seq_player_cfg_paths(id)
  for i = 1, #paths do
    local path = paths[i]
    local dir = path:match("^(.*)/[^/]+$")
    if dir and r.RecursiveCreateDirectory then
      r.RecursiveCreateDirectory(dir, 0)
    end
    local f = io.open(path, "wb")
    if f then
      f:write(body)
      f:close()
    end
  end
  return id
end

function seq_player_ensure_fx(slot)
  if not slot or not slot.reaper_track_guid or not r.TrackFX_AddByName then
    return nil, -1
  end
  local tr = get_track_by_guid(slot.reaper_track_guid)
  if not tr then
    return nil, -1
  end
  local fx = seq_player_find_jsfx(tr)
  if fx < 0 then
    for _, name in ipairs(SEQ_PLAYER_JSFX_NAMES) do
      fx = r.TrackFX_AddByName(tr, name, false, 1)
      if fx and fx >= 0 then
        if r.TrackFX_SetOpen then
          r.TrackFX_SetOpen(tr, fx, false)
        end
        break
      end
    end
  end
  if not fx or fx < 0 then
    return tr, -1
  end
  return tr, fx
end

function seq_player_sync_slot(slot, force)
  if not slot then
    return false
  end
  local id = slot.id
  local sig = seq_player_config_sig(slot)
  local rt = seq_player_runtime[id]
  if not force and rt and rt.sig == sig then
    return true
  end
  local tr, fx = seq_player_ensure_fx(slot)
  if not tr or fx < 0 then
    return false
  end
  local instance_id = seq_player_write_cfg(slot)
  local P = SEQ_PLAYER_PARAM
  seq_player_set_param(tr, fx, P.instance_id, instance_id)
  seq_player_set_param(tr, fx, P.midi_lo, slot.midi_lo or 36)
  seq_player_set_param(tr, fx, P.midi_hi, slot.midi_hi or slot.midi_lo or 36)
  seq_player_set_param(tr, fx, P.root, slot.midi_lo or 36)
  seq_player_set_param(tr, fx, P.gain, 1)
  seq_player_set_param(tr, fx, P.pitch, 0)
  seq_player_set_param(tr, fx, P.overlap, slot.overlap and 1 or 0)
  local cur = select(1, r.TrackFX_GetParam(tr, fx, P.reload)) or 0
  seq_player_set_param(tr, fx, P.reload, cur + 1)
  seq_player_runtime[id] = { sig = sig }
  return true
end

function seq_player_sync_all()
  for _, slot in ipairs(state.seq_tracks or {}) do
    seq_player_sync_slot(slot)
  end
end

function seq_player_trigger(slot, vel)
  if not slot then
    return false
  end
  seq_player_sync_slot(slot)
  local tr, fx = seq_player_ensure_fx(slot)
  if not tr or fx < 0 then
    return false
  end
  vel = math.max(1, math.min(127, math.floor(tonumber(vel) or 100)))
  local P = SEQ_PLAYER_PARAM
  seq_player_set_param(tr, fx, P.vel, vel)
  local cur = select(1, r.TrackFX_GetParam(tr, fx, P.trigger)) or 0
  seq_player_set_param(tr, fx, P.trigger, cur + 1)
  return true
end

function seq_midi_parent_is_armed()
  local tr = seq_midi_parent_track(false)
  if not tr then
    return false
  end
  return (r.GetMediaTrackInfo_Value(tr, "I_RECARM") or 0) > 0.5
end

function seq_midi_apply_parent_input(tr)
  if not tr then
    return
  end
  r.SetMediaTrackInfo_Value(tr, "I_RECINPUT", SEQ_MIDI_RECINPUT_ALL)
  r.SetMediaTrackInfo_Value(tr, "I_RECMODE", SEQ_MIDI_RECMODE_MONITOR)
  r.SetMediaTrackInfo_Value(tr, "I_RECMON", 1)
end

function seq_midi_set_parent_arm(on)
  local tr = seq_midi_parent_track(on and true or false)
  if not tr then
    return false
  end
  seq_midi_ensure_jsfx()
  if on then
    seq_midi_apply_parent_input(tr)
    r.SetMediaTrackInfo_Value(tr, "I_RECARM", 1)
  else
    r.SetMediaTrackInfo_Value(tr, "I_RECARM", 0)
  end
  return true
end

function seq_midi_toggle_parent_arm()
  return seq_midi_set_parent_arm(not seq_midi_parent_is_armed())
end

function seq_midi_arm_button_width(h)
  h = h or 18
  local tw = select(1, r.ImGui_CalcTextSize(ctx, "MIDI")) or 28
  return 6 + (h - 2) + 4 + tw + 7
end

function render_seq_midi_arm_icon_button(id, h)
  h = h or 18
  local label = "MIDI"
  local tw, th = r.ImGui_CalcTextSize(ctx, label)
  local icon_sz = h - 2
  local w = seq_midi_arm_button_width(h)
  local armed = seq_midi_parent_is_armed()

  r.ImGui_InvisibleButton(ctx, "##ui_" .. tostring(id), w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local pressed = r.ImGui_IsItemActive(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  local press = pressed and 1.0 or 0.0

  local bg, border, line
  if armed then
    bg = hovered and 0x4A1414FF or 0x2C1010FF
    border = hovered and 0xFF6A6AFF or 0xFF3A3AFF
    line = 0xFF4A4AFF
  else
    bg = hovered and UI_THEME.surface_hvr or UI_THEME.surface
    border = hovered and UI_THEME.border_hvr or UI_THEME.border
    line = hovered and UI_THEME.text or UI_THEME.text_dim
  end
  ui_draw_panel(dl, x0, y0, x1, y1, 5.0, bg, border, hovered, pressed)

  local icon_cx = x0 + 6 + icon_sz * 0.5
  local icon_cy = (y0 + y1) * 0.5 + press
  ui_button_draw_icon(dl, "midi", icon_cx, icon_cy, icon_sz, line)
  r.ImGui_DrawList_AddText(dl, x0 + 6 + icon_sz + 4, y0 + (h - th) * 0.5 + press, line, label)

  if clicked then
    seq_midi_toggle_parent_arm()
  end
  if hovered and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, armed
      and "MIDI arm on — Sample Map folder is receiving MIDI"
      or "MIDI arm — record-arm the Sample Map folder for live MIDI")
  end
end

function seq_midi_poll_gmem()
  if not r.gmem_attach or not r.gmem_read then
    return
  end
  r.gmem_attach(SEQ_MIDI_GMEM_NAME)
  local serial = tonumber(r.gmem_read(0)) or 0
  if serial <= 0 then
    return
  end
  local last = state.seq_midi_gmem_serial
  if last == nil or serial < last then
    state.seq_midi_gmem_serial = serial
    return
  end
  if serial == last then
    return
  end
  local pending = {}
  for i = 0, 63 do
    local base = 16 + i * 4
    local evt_serial = tonumber(r.gmem_read(base + 3)) or 0
    if evt_serial > last and evt_serial <= serial then
      local on = (tonumber(r.gmem_read(base + 2)) or 0) > 0.5
      if on then
        pending[#pending + 1] = {
          serial = evt_serial,
          note = tonumber(r.gmem_read(base)) or 0,
          vel = tonumber(r.gmem_read(base + 1)) or 0,
        }
      end
    end
  end
  table.sort(pending, function(a, b) return a.serial < b.serial end)
  for _, evt in ipairs(pending) do
    seq_midi_handle_note_on(evt.note, evt.vel)
  end
  state.seq_midi_gmem_serial = serial
end

function seq_midi_poll()
  if not state.seq_midi_jsfx_ready and seq_midi_parent_track(false) then
    seq_midi_ensure_jsfx()
  end
  seq_player_sync_all()
  seq_midi_poll_gmem()
end

function seq_mix_controls_inner_w()
  local btn = SEQ_MIX_BTN or 14.0
  local gap = SEQ_MIX_GAP or 3.0
  local ms_w = btn * 3 + 6
  return btn + gap
      + (SEQ_MIX_VOL_W or 52.0) + gap
      + (SEQ_MIX_PAN_W or 40.0) + gap
      + (SEQ_MIX_MIDI_W or 30.0) + gap
      + ms_w
end


function seq_env_shape_active(env)
  env = seq_normalize_track_env(env)
  local pts = env.points
  if not pts or #pts == 0 then
    return false
  end
  if #pts > 2 then
    return true
  end
  for _, p in ipairs(pts) do
    if math.abs((p.amp or 1.0) - 1.0) > 0.001 then
      return true
    end
    if math.abs(p.curve or 0.0) > 0.001 then
      return true
    end
  end
  return (pts[1].t or 0.0) > 0.0005
end

function seq_env_is_active(env)
  return seq_env_shape_active(env)
end

function seq_apply_slot_mix_to_reaper_track(slot)
  if not slot then return end
  seq_normalize_slot_mix(slot)
  if not slot.reaper_track_guid then return end
  local tr = get_track_by_guid(slot.reaper_track_guid)
  if not tr then return end
  r.SetMediaTrackInfo_Value(tr, "D_VOL", slot.volume or 1.0)
  r.SetMediaTrackInfo_Value(tr, "D_PAN", slot.pan or 0.0)
  r.SetMediaTrackInfo_Value(tr, "B_MUTE", slot.mute and 1 or 0)
  r.SetMediaTrackInfo_Value(tr, "I_SOLO", slot.solo and 1 or 0)
end

function seq_apply_all_slot_mix_to_reaper()
  for _, slot in ipairs(state.seq_tracks) do
    seq_apply_slot_mix_to_reaper_track(slot)
  end
end

function seq_ensure_take_volume_envelope(take)
  if not take then return nil end
  local env = r.GetTakeEnvelopeByName(take, "Volume")
  if env then return env end

  local item = r.GetMediaItemTake_Item(take)
  if not item then return nil end

  -- 1) Chunk inject after the SOURCE block (Lua '.' does not match newlines, so
  --    find the first "\n>" that closes <SOURCE ...>).
  local retval, chunk = r.GetItemStateChunk(item, "", false)
  if type(retval) == "string" then
    chunk = retval
    retval = chunk ~= ""
  end
  if type(chunk) == "string" and chunk ~= "" and not chunk:find("<VOLENV[%s\r\n]") then
    local src_at = chunk:find("<SOURCE", 1, true)
    local insert_at = nil
    if src_at then
      local close_at = chunk:find("\n>", src_at, true)
      if close_at then insert_at = close_at + 2 end
    end
    if not insert_at then
      local last = nil
      local search_from = 1
      while true do
        local a, b = chunk:find("\n>", search_from, true)
        if not a then break end
        last = b
        search_from = b + 1
      end
      if last then insert_at = last + 1 end
    end
    if insert_at then
      local block = "<VOLENV\nACT 1\nVIS 0 1 1\nLANEHEIGHT 0 0\nARM 0\nDEFSHAPE 0\nVOLTYPE 1\n>\n"
      local patched = chunk:sub(1, insert_at) .. block .. chunk:sub(insert_at + 1)
      if r.SetItemStateChunk(item, patched, false) then
        env = r.GetTakeEnvelopeByName(take, "Volume")
        if env then return env end
      end
    end
  end

  -- 2) Action-based create (SWS preferred; else native toggle).
  local selected = {}
  local sel_count = r.CountSelectedMediaItems(0)
  for i = 0, sel_count - 1 do
    selected[#selected + 1] = r.GetSelectedMediaItem(0, i)
  end
  r.SelectAllMediaItems(0, false)
  r.SetMediaItemSelected(item, true)

  local sws = 0
  if r.NamedCommandLookup then
    sws = r.NamedCommandLookup("_S&M_TAKEENV1") or 0
  end
  if sws ~= 0 then
    r.Main_OnCommand(sws, 0)
  else
    r.Main_OnCommand(40693, 0) -- Take: Toggle take volume envelope
  end

  env = r.GetTakeEnvelopeByName(take, "Volume")

  r.SelectAllMediaItems(0, false)
  for _, it in ipairs(selected) do
    if r.ValidatePtr2 and not r.ValidatePtr2(0, it, "MediaItem*") then
      -- skip invalidated
    else
      r.SetMediaItemSelected(it, true)
    end
  end

  return env
end

function seq_env_levels_at(env, t, length)
  env = seq_normalize_track_env(env)
  local pts = env.points
  if not pts or #pts == 0 then
    return 1.0
  end
  t = t or 0.0
  if t <= (pts[1].t or 0.0) then
    return pts[1].amp or 1.0
  end
  local last = pts[#pts]
  if t >= (last.t or 0.0) then
    return last.amp or 1.0
  end
  for i = 2, #pts do
    local a, b = pts[i - 1], pts[i]
    if t <= (b.t or 0.0) then
      local span = math.max(0.0000001, (b.t or 0.0) - (a.t or 0.0))
      local u = (t - (a.t or 0.0)) / span
      return seq_env_seg_eval(a.amp or 1.0, b.amp or 1.0, u, a.curve)
    end
  end
  return last.amp or 1.0
end

function seq_build_env_amp_points(item_len, env, env_offset)
  env = seq_normalize_track_env(env)
  item_len = math.max(0.001, item_len or 0.25)
  env_offset = math.max(0.0, env_offset or 0.0)
  local pts = {}
  local function add(t, amp)
    t = math.max(0.0, math.min(item_len, t))
    amp = math.max(0.00001, math.min(4.0, amp or 1.0))
    local last = pts[#pts]
    if last and math.abs(last.t - t) < 0.00005 then
      last.amp = amp
      return
    end
    pts[#pts + 1] = { t = t, amp = amp }
  end

  add(0.0, seq_env_levels_at(env, env_offset, item_len))
  local src = env.points
  for i, p in ipairs(src) do
    local local_t = (p.t or 0.0) - env_offset
    if local_t > 0.00005 and local_t < item_len - 0.00005 then
      add(local_t, p.amp)
    end
    local nxt = src[i + 1]
    local curve = p.curve or 0.0
    if nxt and math.abs(curve) > 0.001 then
      local t0, t1 = p.t or 0.0, nxt.t or 0.0
      local span = t1 - t0
      if span > 0.0002 then
        local steps = math.max(6, math.min(16, math.floor(span * 80.0 + 0.5)))
        for k = 1, steps - 1 do
          local u = k / steps
          local t = t0 + span * u - env_offset
          if t > 0.00005 and t < item_len - 0.00005 then
            add(t, seq_env_seg_eval(p.amp, nxt.amp, u, curve))
          end
        end
      end
    end
  end
  add(item_len, seq_env_levels_at(env, env_offset + item_len, item_len))
  return pts
end

function seq_apply_envelope_fades_fallback(item, take, item_len, env, env_offset)
  -- Audible fallback when take envelopes can't be created.
  env = seq_normalize_track_env(env)
  env_offset = math.max(0.0, env_offset or 0.0)
  if item then
    r.SetMediaItemInfo_Value(item, "D_FADEINLEN", 0)
    r.SetMediaItemInfo_Value(item, "D_FADEOUTLEN", 0)
  end
  if not take then
    return
  end
  local amp = seq_env_levels_at(env, env_offset, item_len)
  local max_amp = amp
  local win_end = env_offset + (item_len or 0.0)
  for _, p in ipairs(env.points) do
    local pt = p.t or 0.0
    if pt >= env_offset - 0.0001 and pt <= win_end + 0.0001 then
      if (p.amp or 0.0) > max_amp then
        max_amp = p.amp
      end
    end
  end
  local shaped = math.max(0.05, math.min(4.0, amp * 0.4 + max_amp * 0.6))
  local base = r.GetMediaItemTakeInfo_Value(take, "D_VOL")
  if not base or base <= 0 then
    base = 1.0
  end
  r.SetMediaItemTakeInfo_Value(take, "D_VOL", base * math.min(1.0, shaped))
end

function seq_apply_item_edge_fades(item, item_len, env)
  if not item then
    return
  end
  r.SetMediaItemInfo_Value(item, "D_FADEINLEN", 0)
  r.SetMediaItemInfo_Value(item, "D_FADEOUTLEN", 0)
end

function seq_apply_take_volume_envelope(take, item_len, env, env_offset)
  if not take or not item_len or item_len <= 0.0001 then
    return false
  end
  env = seq_normalize_track_env(env)
  env_offset = math.max(0.0, env_offset or 0.0)
  local item = r.GetMediaItemTake_Item(take)
  if not seq_env_is_active(env) then
    if item then
      r.SetMediaItemInfo_Value(item, "D_FADEINLEN", 0)
      r.SetMediaItemInfo_Value(item, "D_FADEOUTLEN", 0)
    end
    return false
  end

  local pts = seq_build_env_amp_points(item_len, env, env_offset)
  local tenv = seq_ensure_take_volume_envelope(take)
  if tenv then
    r.DeleteEnvelopePointRange(tenv, -0.01, item_len + 1.0)
    local scaling = r.GetEnvelopeScalingMode(tenv)
    for _, p in ipairs(pts) do
      local y = r.ScaleToEnvelopeMode(scaling, p.amp)
      r.InsertEnvelopePoint(tenv, p.t, y, 0, 0, false, true)
    end
    r.Envelope_SortPoints(tenv)
    if item then
      r.SetMediaItemInfo_Value(item, "D_FADEINLEN", 0)
      r.SetMediaItemInfo_Value(item, "D_FADEOUTLEN", 0)
    end
    return true
  elseif item then
    seq_apply_envelope_fades_fallback(item, take, item_len, env, env_offset)
  end
  return false
end

function seq_resync_all_regions(opts)
  opts = opts or {}
  local own_refresh = not opts.skip_arrange
  if own_refresh and r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  if not opts.skip_remove then
    remove_seq_rendered_items(nil)
  end
  clear_seq_vary_rank_cache()
  for _, region in ipairs(state.seq_regions) do
    sync_seq_region(region, {
      skip_remove = true,
      skip_mix = true,
      skip_arrange = true,
      skip_cache_clear = true,
    })
  end
  if not opts.skip_mix then
    seq_apply_all_slot_mix_to_reaper()
  end
  if own_refresh and r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  if own_refresh then
    r.UpdateArrange()
  end
end

function seq_on_slot_mix_changed(slot, opts)
  opts = opts or {}
  seq_normalize_slot_mix(slot)
  seq_apply_slot_mix_to_reaper_track(slot)
  if seq_player_sync_slot then
    seq_player_sync_slot(slot)
  end
  if seq_schedule_ingest_save then
    seq_schedule_ingest_save()
  elseif save_seq_project_state then
    save_seq_project_state()
  end
  if opts.resync then
    seq_resync_all_regions()
  end
end

-- Lightweight peak cache for envelope popup (does not clobber the main preview waveform).
-- Global (not local) to stay under Lua's 200-local main-chunk limit.
seq_env_wave_cache = {}
seq_layer_mix_preview = nil
seq_layer_mix_wave_cache = nil

function seq_env_downsample_peaks(src_peaks, width)
  if not src_peaks or #src_peaks == 0 or width < 2 then return nil end
  local out = {}
  local n = #src_peaks
  for i = 1, width do
    local a = math.floor((i - 1) * n / width) + 1
    local b = math.floor(i * n / width)
    if b < a then b = a end
    local peak = 0.0
    for j = a, math.min(n, b) do
      local v = src_peaks[j] or 0.0
      if v > peak then peak = v end
    end
    out[i] = peak
  end
  return out
end

function seq_env_build_wave_peaks(path, width)
  if not path or path == "" or not r.GetAudioAccessorSamples then return nil, nil end
  width = math.max(48, math.min(320, math.floor(width or 200)))
  local src = r.PCM_Source_CreateFromFile(path)
  if not src then return nil, nil end
  local duration = pick_number({ r.GetMediaSourceLength(src) }, 0.0)
  local sr = pick_number({ r.GetMediaSourceSampleRate(src) }, 44100.0)
  local channels = math.max(1, math.floor(pick_number({ r.GetMediaSourceNumChannels(src) }, 1)))
  if duration <= 0.0001 or sr <= 0 then
    r.PCM_Source_Destroy(src)
    return nil, nil
  end

  r.PreventUIRefresh(1)
  local track = r.GetTrack(0, 0)
  local item = track and r.AddMediaItemToTrack(track) or nil
  local peaks = nil
  if item then
    r.SetMediaItemPosition(item, 0, false)
    r.SetMediaItemLength(item, duration, false)
    local take = r.AddTakeToMediaItem(item)
    if take then
      r.SetMediaItemTake_Source(take, src)
      src = nil
      local accessor = r.CreateTakeAudioAccessor(take)
      if accessor then
        peaks = {}
        local max_v = 0.0
        for i = 0, width - 1 do
          local t0 = (i / width) * duration
          local read_n = math.min(128, math.max(32, math.floor((duration / width) * sr)))
          local buf = r.new_array(read_n * channels)
          local got = r.GetAudioAccessorSamples(accessor, sr, channels, t0, read_n, buf)
          local peak = 0.0
          if got and got > 0 and buf then
            local frames = got
            for j = 0, frames - 1 do
              for c = 0, channels - 1 do
                local v = buf[j * channels + c + 1]
                if v then
                  local a = math.abs(v)
                  if a > peak then peak = a end
                end
              end
            end
          end
          peaks[i + 1] = peak
          if peak > max_v then max_v = peak end
          if buf and buf.clear then buf.clear(buf) end
        end
        if max_v > 0.0001 then
          for i = 1, #peaks do peaks[i] = peaks[i] / max_v end
        end
        r.DestroyAudioAccessor(accessor)
      end
    end
    r.DeleteTrackMediaItem(track, item)
  end
  r.PreventUIRefresh(-1)
  if src then r.PCM_Source_Destroy(src) end
  return peaks, duration
end

function seq_env_get_wave_peaks(sample, width)
  if not sample or not sample.path then return nil, nil end
  width = math.max(48, math.min(320, math.floor(width or 200)))
  local cached = seq_env_wave_cache[sample.path]
  if cached and cached.peaks and #cached.peaks > 0 and cached.duration and cached.duration > 0 then
    if cached.width == width then
      return cached.peaks, cached.duration
    end
    local resized = seq_env_downsample_peaks(cached.peaks, width)
    return resized or cached.peaks, cached.duration
  end

  -- Prefer PCM-built peaks so duration and waveform share one timeline.
  -- Fall back to downsampling the preview waveform only when PCM build fails.
  local build_w = 256
  local peaks, duration = seq_env_build_wave_peaks(sample.path, build_w)
  if (not peaks or not duration or duration <= 0)
      and waveform_data
      and waveform_data.sample_path == sample.path
      and waveform_data.data
      and #waveform_data.data > 0 then
    peaks = seq_env_downsample_peaks(waveform_data.data, build_w)
    duration = tonumber(waveform_data.duration) or tonumber(sample.duration)
  end
  if peaks and duration and duration > 0 then
    seq_env_wave_cache[sample.path] = { peaks = peaks, duration = duration, width = build_w }
    if build_w ~= width then
      local resized = seq_env_downsample_peaks(peaks, width)
      return resized or peaks, duration
    end
    return peaks, duration
  end
  return peaks, duration or tonumber(sample.duration)
end

-- Draw waveform peaks across [x, x+w]. bins are evenly spaced over the sample duration.
-- Optional t0, t1, duration zoom the same time window as the envelope editor.
function seq_draw_env_waveform(dl, x, y, w, h, peaks, t0, t1, duration)
  if not peaks or #peaks == 0 or w < 2 or h < 2 then return end
  local mid = y + h * 0.5
  local amp = h * 0.42
  local n = #peaks
  local dur = (duration and duration > 0.0001) and duration or 1.0
  local view0 = t0 or 0.0
  local view1 = t1 or dur
  if view1 <= view0 then view1 = view0 + 0.001 end
  local span = view1 - view0
  local col_fill = 0x5A7A9855
  local col_line = 0x8AA8C888
  if r.ImGui_DrawList_PushClipRect then
    r.ImGui_DrawList_PushClipRect(dl, x, y, x + w, y + h, true)
  end
  local prev_x, prev_y = nil, nil
  for i = 1, n do
    local v = peaks[i] or 0.0
    local bin0 = ((i - 1) / n) * dur
    local bin1 = (i / n) * dur
    if bin1 >= view0 and bin0 <= view1 then
      local x0 = x + ((bin0 - view0) / span) * w
      local x1 = x + ((bin1 - view0) / span) * w
      local px = (x0 + x1) * 0.5
      local half = v * amp
      r.ImGui_DrawList_AddLine(dl, px, mid - half, px, mid + half, col_fill, math.max(1.0, x1 - x0))
      local py = mid - v * amp
      if prev_x then
        r.ImGui_DrawList_AddLine(dl, prev_x, prev_y, px, py, col_line, 1.0)
      end
      prev_x, prev_y = px, py
    end
  end
  if r.ImGui_DrawList_PopClipRect then
    r.ImGui_DrawList_PopClipRect(dl)
  end
end

function seq_draw_env_sparkline(dl, x, y, w, h, env, active, hovered)
  -- Compact non-interactive preview; click handling lives in the lane controls.
  env = seq_normalize_track_env(env)
  local bg = UI_THEME.bg_panel
  local edge = UI_THEME.border
  local edge_w = 1.0
  if active then
    bg = UI_THEME.accent_fill
    edge = UI_THEME.accent
  end
  if hovered then
    bg = active and UI_THEME.accent_fill_h or UI_THEME.surface_hvr
    edge = active and UI_THEME.accent_hvr or UI_THEME.border_hvr
    edge_w = 1.4
  end
  local line = seq_env_is_active(env) and 0x9FE3B5FF or 0x6A849EFF
  if hovered then
    line = seq_env_is_active(env) and 0xC8FFD8FF or 0x9EC0E0FF
  end
  r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, bg, 3.0)
  if hovered then
    r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, 0xFFFFFF18, 3.0)
  end
  r.ImGui_DrawList_AddRect(dl, x, y, x + w, y + h, edge, 3.0, 0, edge_w)

  local pts = env.points
  local t1 = 1.0
  if pts and #pts > 0 then
    t1 = math.max(0.001, pts[#pts].t or 1.0)
  end
  local max_y = 1.0
  if pts then
    for i = 1, #pts do
      local a = pts[i].amp or 0.0
      if a > max_y then max_y = a end
    end
  end
  local prev_x, prev_y = nil, nil
  local steps = math.max(12, math.floor(w / 2))
  for i = 0, steps do
    local t = (i / steps) * t1
    local amp = seq_env_levels_at(env, t, t1)
    local px = x + 2 + (i / steps) * (w - 4)
    local py = y + h - 2 - (amp / max_y) * (h - 4)
    if prev_x then
      r.ImGui_DrawList_AddLine(dl, prev_x, prev_y, px, py, line, 1.4)
    end
    prev_x, prev_y = px, py
  end
end

function seq_draw_env_trans_sustain_markers(dl, sample, time_to_x, iy0, iy1)
  if not sample or type(sample.transient_end) ~= "number" or sample.transient_end <= 0 then
    return
  end
  local trans_t = sample.transient_end
  local onset_t = (type(sample.onset) == "number" and sample.onset >= 0) and sample.onset or 0.0
  local sustain_t = sample_map_duration(sample)
  if not sustain_t or sustain_t <= 0 then
    sustain_t = tonumber(sample.duration) or trans_t
  end
  local ox = time_to_x(onset_t)
  local tx = time_to_x(trans_t)
  local sx = time_to_x(sustain_t)
  if tx > ox + 0.5 then
    r.ImGui_DrawList_AddRectFilled(dl, ox, iy0, tx, iy1, 0xFF6B3C33, 0)
  end
  if sx > tx + 0.5 then
    r.ImGui_DrawList_AddRectFilled(dl, tx, iy0, sx, iy1, 0x4A9CFF28, 0)
  end
  local col = 0x7CFF4AFF
  r.ImGui_DrawList_AddLine(dl, tx, iy0, tx, iy1, col, 1.6)
  local tri = 4.5
  r.ImGui_DrawList_AddTriangleFilled(dl, tx, iy0, tx - tri, iy0 + tri, tx + tri, iy0 + tri, col)
  r.ImGui_DrawList_AddTriangleFilled(dl, tx, iy1, tx - tri, iy1 - tri, tx + tri, iy1 - tri, col)
  if (tx - ox) >= 12.0 then
    r.ImGui_DrawList_AddText(dl, ox + 3, iy0 + 2, 0xFFB08AFF, "T")
  end
  if (sx - tx) >= 12.0 then
    r.ImGui_DrawList_AddText(dl, tx + 4, iy0 + 2, 0xA8D4FFFF, "S")
  end
end

function seq_env_view_min_span(duration)
  duration = math.max(0.001, duration or 1.0)
  return math.max(0.02, duration * 0.02)
end

function seq_env_view_clamp(t0, t1, duration)
  duration = math.max(0.001, duration or 1.0)
  local min_span = seq_env_view_min_span(duration)
  local span = math.max(min_span, (t1 or duration) - (t0 or 0.0))
  if span > duration then span = duration end
  t0 = t0 or 0.0
  t1 = t0 + span
  if t0 < 0.0 then
    t1 = t1 - t0
    t0 = 0.0
  end
  if t1 > duration then
    t0 = t0 - (t1 - duration)
    t1 = duration
    if t0 < 0.0 then t0 = 0.0 end
  end
  return t0, t1
end

function seq_env_view_get(slot_id, duration)
  duration = math.max(0.001, duration or 1.0)
  local v = state.seq_env_view
  if not v or v.slot_id ~= slot_id then
    return 0.0, duration
  end
  return seq_env_view_clamp(v.t0 or 0.0, v.t1 or duration, duration)
end

function seq_env_view_set(slot_id, t0, t1, duration)
  t0, t1 = seq_env_view_clamp(t0, t1, duration)
  if (t1 - t0) >= (duration or 1.0) - 0.0001 then
    state.seq_env_view = nil
    return t0, t1
  end
  state.seq_env_view = { slot_id = slot_id, t0 = t0, t1 = t1 }
  return t0, t1
end

function seq_env_view_reset()
  state.seq_env_view = nil
  state.seq_env_view_pan = nil
end

-- Interactive free envelope editor. Click empty space to add a point, drag to
-- move, drag a segment to bow the curve. Alt-click or right-click a point to
-- delete; double-click a segment to reset it to linear.
-- Scroll zooms (waveform follows); Shift+scroll or middle-drag pans.
-- opts: { show_waveform = bool }
-- Returns changed, hovered, tip_text
function seq_render_env_graph_editor(dl, slot, x, y, w, h, opts)
  if not slot then return false, false, nil end
  opts = opts or {}
  seq_normalize_slot_mix(slot)
  local env = slot.env
  local changed = false
  local tip = nil

  local pad = 2.0
  local ix0, iy0 = x + pad, y + pad
  local ix1, iy1 = x + w - pad, y + h - pad
  local iw = math.max(8.0, ix1 - ix0)
  local ih = math.max(8.0, iy1 - iy0)

  local sample = nil
  local wave_peaks, wave_dur = nil, nil
  if opts.show_waveform and slot.sample_path then
    sample = find_sample_by_path(slot.sample_path)
    if not sample then
      sample = { path = slot.sample_path }
    end
    wave_peaks, wave_dur = seq_env_get_wave_peaks(sample, math.floor(iw))
  end
  local PREVIEW_LEN = 1.0
  if wave_dur and wave_dur > 0.0001 then
    PREVIEW_LEN = wave_dur
  else
    local sample_dur = sample and tonumber(sample.duration) or nil
    if sample_dur and sample_dur > 0.0001 then
      PREVIEW_LEN = sample_dur
    end
  end
  local AMP_MAX = SEQ_ENV_AMP_MAX or 3.0
  local view_t0, view_t1 = seq_env_view_get(slot.id, PREVIEW_LEN)
  local view_span = math.max(0.001, view_t1 - view_t0)

  local dragging = state.seq_env_graph_drag and state.seq_env_graph_drag.slot_id == slot.id
  if not dragging then
    env = seq_env_sync_to_length(env, PREVIEW_LEN)
    slot.env = env
  end
  local points = env.points

  local function time_to_x(t)
    return ix0 + ((t - view_t0) / view_span) * iw
  end
  local function amp_to_y(a)
    return iy1 - (math.max(0.0, math.min(AMP_MAX, a)) / AMP_MAX) * ih
  end
  local function x_to_time(px)
    return view_t0 + math.max(0.0, math.min(1.0, (px - ix0) / iw)) * view_span
  end
  local function y_to_amp(py)
    return math.max(0.0, math.min(AMP_MAX, (iy1 - py) / ih * AMP_MAX))
  end

  r.ImGui_SetCursorScreenPos(ctx, x, y)
  r.ImGui_InvisibleButton(ctx, "##seq_env_graph_" .. tostring(slot.id), w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  local mx, my = r.ImGui_GetMousePos(ctx)
  mx, my = mx or x, my or y
  if hovered and r.ImGui_SetItemUsingMouseWheel then
    r.ImGui_SetItemUsingMouseWheel(ctx)
  end

  -- Zoom / pan the shared envelope+waveform time window.
  local panning = state.seq_env_view_pan and state.seq_env_view_pan.slot_id == slot.id
  if hovered and not dragging then
    local wheel, wheel_h = 0.0, 0.0
    if r.ImGui_GetMouseWheel then
      wheel, wheel_h = r.ImGui_GetMouseWheel(ctx)
      wheel_h = wheel_h or 0.0
    end
    local shift = is_shift_down()
    if wheel ~= 0.0 and not shift then
      local pivot = x_to_time(mx)
      local new_span = view_span * math.exp(-wheel * 0.18)
      new_span = math.max(seq_env_view_min_span(PREVIEW_LEN), math.min(PREVIEW_LEN, new_span))
      local u = (pivot - view_t0) / view_span
      view_t0 = pivot - u * new_span
      view_t1 = view_t0 + new_span
      view_t0, view_t1 = seq_env_view_set(slot.id, view_t0, view_t1, PREVIEW_LEN)
      view_span = math.max(0.001, view_t1 - view_t0)
    elseif (shift and wheel ~= 0.0) or wheel_h ~= 0.0 then
      local pan = ((shift and wheel ~= 0.0) and -wheel or -wheel_h) * view_span * 0.12
      view_t0, view_t1 = seq_env_view_set(slot.id, view_t0 + pan, view_t1 + pan, PREVIEW_LEN)
      view_span = math.max(0.001, view_t1 - view_t0)
    end
    if r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 2) then
      state.seq_env_view_pan = { slot_id = slot.id, mx = mx, t0 = view_t0, t1 = view_t1 }
      panning = true
    end
  end
  if panning then
    local pan = state.seq_env_view_pan
    if pan and r.ImGui_IsMouseDown and r.ImGui_IsMouseDown(ctx, 2) then
      local dt = -(mx - pan.mx) / iw * (pan.t1 - pan.t0)
      view_t0, view_t1 = seq_env_view_set(slot.id, pan.t0 + dt, pan.t1 + dt, PREVIEW_LEN)
      view_span = math.max(0.001, view_t1 - view_t0)
    else
      state.seq_env_view_pan = nil
      panning = false
    end
  end

  local live = seq_env_is_active(env) or active or hovered
  r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, live and 0x15241AEE or 0x121814EE, 4.0)
  r.ImGui_DrawList_AddRect(dl, x, y, x + w, y + h, (active or hovered) and UI_THEME.accent or UI_THEME.border, 4.0, 0, 1.2)
  if r.ImGui_DrawList_PushClipRect then
    r.ImGui_DrawList_PushClipRect(dl, ix0, iy0, ix1, iy1, true)
  end
  if wave_peaks then
    seq_draw_env_waveform(dl, ix0, iy0, iw, ih, wave_peaks, view_t0, view_t1, PREVIEW_LEN)
  end
  if sample and sample.path then
    local grip_w, grip_h = 16, 14
    local gx, gy = ix1 - grip_w - 1, iy0 + 1
    r.ImGui_SetCursorScreenPos(ctx, gx, gy)
    r.ImGui_InvisibleButton(ctx, "##seq_env_wave_drag_" .. tostring(slot.id), grip_w, grip_h)
    local grip_hov = r.ImGui_IsItemHovered(ctx)
    local grip_col = grip_hov and UI_THEME.accent or UI_THEME.text_dim
    for row = 0, 1 do
      for col = 0, 2 do
        r.ImGui_DrawList_AddCircleFilled(dl,
          gx + 4 + col * 4, gy + 5 + row * 5, 1.2, grip_col, 6)
      end
    end
    if grip_hov and r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, "Drag to drop this sample")
    end
    if waveform_drag_should_start(grip_hov) then
      begin_waveform_sample_drag(sample)
    end
  end
  seq_draw_env_trans_sustain_markers(dl, sample, time_to_x, iy0, iy1)
  local unity_y = amp_to_y(1.0)
  r.ImGui_DrawList_AddLine(dl, ix0, unity_y, ix1, unity_y, 0xFFFFFF22, 1.0)

  local line_col = live and 0x9FE3B5FF or 0x6A849EFF
  local function dist2(ax, ay, bx, by)
    local dx, dy = ax - bx, ay - by
    return dx * dx + dy * dy
  end
  local function dist_point_seg(px, py, x0, y0, x1, y1)
    local dx, dy = x1 - x0, y1 - y0
    local l2 = dx * dx + dy * dy
    if l2 < 0.0001 then
      return math.sqrt(dist2(px, py, x0, y0)), 0.0
    end
    local u = ((px - x0) * dx + (py - y0) * dy) / l2
    if u < 0.0 then u = 0.0 elseif u > 1.0 then u = 1.0 end
    local qx, qy = x0 + dx * u, y0 + dy * u
    return math.sqrt(dist2(px, py, qx, qy)), u
  end
  local function seg_sample_count(t0, t1)
    local px_span = math.abs(time_to_x(t1) - time_to_x(t0))
    return math.max(8, math.min(28, math.floor(px_span / 6.0 + 0.5)))
  end
  local function draw_env_segment(x0, y0, t0, amp0, t1, amp1, curve, col, thickness)
    local steps = seg_sample_count(t0, t1)
    local prev_x, prev_y = x0, y0
    for k = 1, steps do
      local u = k / steps
      local sx = time_to_x(t0 + (t1 - t0) * u)
      local sy = amp_to_y(seq_env_seg_eval(amp0, amp1, u, curve))
      r.ImGui_DrawList_AddLine(dl, prev_x, prev_y, sx, sy, col, thickness)
      prev_x, prev_y = sx, sy
    end
  end

  local hit_r = 8.0
  local hit_r2 = hit_r * hit_r
  local nearest_idx, nearest_d = nil, hit_r2
  for i = 1, #points do
    local hx = time_to_x(points[i].t or 0.0)
    if hx >= ix0 - 6 and hx <= ix1 + 6 then
      local d = dist2(mx, my, hx, amp_to_y(points[i].amp or 1.0))
      if d <= nearest_d then
        nearest_d = d
        nearest_idx = i
      end
    end
  end

  local seg_hit_px = 10.0
  local nearest_seg, nearest_seg_d, nearest_seg_u = nil, seg_hit_px, 0.5
  if not nearest_idx then
    for i = 1, #points - 1 do
      local a, b = points[i], points[i + 1]
      local t0, t1 = a.t or 0.0, b.t or 0.0
      local steps = seg_sample_count(t0, t1)
      local px0 = time_to_x(t0)
      local py0 = amp_to_y(a.amp or 1.0)
      for k = 1, steps do
        local u1 = k / steps
        local px1 = time_to_x(t0 + (t1 - t0) * u1)
        local py1 = amp_to_y(seq_env_seg_eval(a.amp, b.amp, u1, a.curve))
        local d, _ = dist_point_seg(mx, my, px0, py0, px1, py1)
        if d <= nearest_seg_d then
          nearest_seg_d = d
          nearest_seg = i
          nearest_seg_u = (k - 0.5) / steps
        end
        px0, py0 = px1, py1
      end
    end
  end
  if nearest_seg then
    nearest_seg_u = math.max(0.08, math.min(0.92, (mx - time_to_x(points[nearest_seg].t or 0.0))
      / math.max(1.0, time_to_x(points[nearest_seg + 1].t or 0.0) - time_to_x(points[nearest_seg].t or 0.0))))
  end

  local alt = is_alt_down()
  local shift = is_shift_down()
  local right_clicked = hovered and r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 1)
  local left_clicked = hovered and r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 0)
  local dbl = hovered and r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0)
  local drag = state.seq_env_graph_drag
  local deleting = (not panning) and nearest_idx and #points > 1 and (right_clicked or (left_clicked and alt))
  local reset_curve = (not panning) and dbl and nearest_seg and not nearest_idx

  if hovered and not dragging and dbl and not nearest_seg and not nearest_idx then
    seq_env_view_reset()
    view_t0, view_t1 = 0.0, PREVIEW_LEN
    view_span = PREVIEW_LEN
  end

  if panning or (dbl and not reset_curve) then
    -- Pan / double-click zoom owns this click.
  elseif reset_curve then
    points[nearest_seg].curve = 0.0
    env.points = points
    slot.env = seq_normalize_track_env(env)
    env = slot.env
    points = env.points
    changed = true
    tip = "Linear"
    state.seq_env_graph_drag = { slot_id = slot.id, handle = "none" }
    drag = state.seq_env_graph_drag
  elseif deleting then
    table.remove(points, nearest_idx)
    env.points = points
    slot.env = seq_normalize_track_env(env)
    env = slot.env
    points = env.points
    changed = true
    tip = "Delete point"
    state.seq_env_graph_drag = { slot_id = slot.id, handle = "none" }
    drag = state.seq_env_graph_drag
  elseif active and not alt then
    if drag and drag.slot_id == slot.id and drag.handle == "none" then
      -- Swallow the rest of the click that deleted a point or reset a curve.
    else
      if (not drag) or drag.slot_id ~= slot.id then
        if nearest_idx then
          state.seq_env_graph_drag = { slot_id = slot.id, handle = nearest_idx }
        elseif nearest_seg then
          state.seq_env_graph_drag = {
            slot_id = slot.id, handle = "curve", seg = nearest_seg, u = nearest_seg_u,
          }
        else
          local idx = nil
          if #points < SEQ_ENV_POINT_LIMIT then
            idx = seq_env_insert_point(points, x_to_time(mx), y_to_amp(my))
            changed = true
          else
            local best_d = 1e12
            for i = 1, #points do
              local d = dist2(mx, my, time_to_x(points[i].t or 0.0), amp_to_y(points[i].amp or 1.0))
              if d < best_d then
                best_d = d
                idx = i
              end
            end
          end
          state.seq_env_graph_drag = { slot_id = slot.id, handle = idx or 1 }
        end
        drag = state.seq_env_graph_drag
      end
      if drag and drag.handle == "curve" then
        local idx = tonumber(drag.seg)
        local a = idx and points[idx]
        local b = idx and points[idx + 1]
        if a and b then
          local t0, t1 = a.t or 0.0, b.t or 0.0
          local span_x = math.max(1.0, time_to_x(t1) - time_to_x(t0))
          local u = drag.u or 0.5
          if span_x > 1.0 then
            u = math.max(0.08, math.min(0.92, (mx - time_to_x(t0)) / span_x))
          end
          a.curve = seq_env_seg_curve_for_amp(a.amp, b.amp, u, y_to_amp(my))
          tip = string.format("Curve %+.2f  ·  double-click to flatten", a.curve)
          changed = true
        end
      else
        local idx = tonumber(drag and drag.handle)
        local p = idx and points[idx]
        if p then
          local tmin = 0.0
          local tmax = PREVIEW_LEN
          if idx > 1 then
            tmin = (points[idx - 1].t or 0.0) + 0.0005
          end
          if idx < #points then
            tmax = (points[idx + 1].t or PREVIEW_LEN) - 0.0005
          end
          if tmax < tmin then tmax = tmin end
          p.t = math.max(tmin, math.min(tmax, x_to_time(mx)))
          p.amp = shift and 1.0 or y_to_amp(my)
          tip = seq_env_format_point_tip(p.t, p.amp)
          changed = true
        end
      end
    end
  elseif drag and drag.slot_id == slot.id then
    slot.env = seq_normalize_track_env(env)
    state.seq_env_graph_drag = nil
  end

  env = slot.env
  points = env.points
  local drag_now = state.seq_env_graph_drag
  local curve_idx = nil
  if drag_now and drag_now.slot_id == slot.id and drag_now.handle == "curve" then
    curve_idx = tonumber(drag_now.seg)
  elseif nearest_seg then
    curve_idx = nearest_seg
  end
  if points and #points > 0 then
    local hold_y = amp_to_y(points[1].amp or 1.0)
    if (points[1].t or 0.0) > 0.0005 then
      r.ImGui_DrawList_AddLine(dl, time_to_x(0.0), hold_y, time_to_x(points[1].t), hold_y, line_col, 1.8)
    end
    for i = 1, #points - 1 do
      local a, b = points[i], points[i + 1]
      local hot = (curve_idx == i)
      draw_env_segment(
        time_to_x(a.t or 0.0), amp_to_y(a.amp or 1.0),
        a.t or 0.0, a.amp or 1.0,
        b.t or 0.0, b.amp or 1.0,
        a.curve,
        hot and (UI_THEME.accent_hvr or 0xC8FFD8FF) or line_col,
        hot and 2.4 or 1.8
      )
    end
    local last = points[#points]
    if (last.t or 0.0) < PREVIEW_LEN - 0.0005 then
      local ly = amp_to_y(last.amp or 1.0)
      r.ImGui_DrawList_AddLine(dl, time_to_x(last.t or 0.0), ly, time_to_x(PREVIEW_LEN), ly, line_col, 1.8)
    end
  end
  if curve_idx and points[curve_idx] and points[curve_idx + 1] then
    local a, b = points[curve_idx], points[curve_idx + 1]
    local mid_t = (a.t or 0.0) + ((b.t or 0.0) - (a.t or 0.0)) * 0.5
    local mid_amp = seq_env_seg_eval(a.amp, b.amp, 0.5, a.curve)
    local mxh, myh = time_to_x(mid_t), amp_to_y(mid_amp)
    r.ImGui_DrawList_AddCircleFilled(dl, mxh, myh, 3.2, 0xFFFFFFFF, 10)
    r.ImGui_DrawList_AddCircle(dl, mxh, myh, 4.4, UI_THEME.accent_hvr or 0xC8FFD8FF, 10, 1.2)
  end

  local active_idx = (drag_now and drag_now.slot_id == slot.id)
      and tonumber(drag_now.handle) or nearest_idx

  for i = 1, #points do
    local p = points[i]
    local hx = time_to_x(p.t or 0.0)
    if hx >= ix0 - 4 and hx <= ix1 + 4 then
      local hy = amp_to_y(p.amp or 1.0)
      local hot = active_idx == i
      local rad = hot and 4.5 or 3.5
      r.ImGui_DrawList_AddCircleFilled(dl, hx, hy, rad, hot and 0xFFFFFFFF or UI_THEME.text, 12)
      r.ImGui_DrawList_AddCircle(dl, hx, hy, rad + 1.2, hot and UI_THEME.accent_hvr or UI_THEME.accent, 12, 1.1)
    end
  end
  if r.ImGui_DrawList_PopClipRect then
    r.ImGui_DrawList_PopClipRect(dl)
  end

  if view_span < PREVIEW_LEN - 0.0005 then
    local bar_h = 3.0
    local by = iy1 - bar_h
    r.ImGui_DrawList_AddRectFilled(dl, ix0, by, ix1, iy1, 0xFFFFFF14, 1.0)
    local bx0 = ix0 + (view_t0 / PREVIEW_LEN) * iw
    local bx1 = ix0 + (view_t1 / PREVIEW_LEN) * iw
    r.ImGui_DrawList_AddRectFilled(dl, bx0, by, bx1, iy1, 0x9FE3B5AA, 1.0)
    local label = string.format("%.0f–%.0f ms", view_t0 * 1000.0, view_t1 * 1000.0)
    r.ImGui_DrawList_AddText(dl, ix0 + 4, iy0 + 2, UI_THEME.text_dim, label)
  end

  if not tip and hovered then
    if nearest_idx then
      local p = points[nearest_idx]
      tip = seq_env_format_point_tip(p.t, p.amp) .. "  ·  Alt/RMB delete"
    elseif nearest_seg then
      local c = points[nearest_seg].curve or 0.0
      if math.abs(c) > 0.001 then
        tip = string.format("Drag to reshape  ·  %.2f  ·  double-click: flatten", c)
      else
        tip = "Drag segment to change curve  ·  double-click: flatten"
      end
    else
      tip = "Click: add point  ·  Drag segment: curve  ·  Scroll: zoom"
    end
  end

  return changed, hovered or active or panning, tip
end

function seq_ms_button(id, dl, x, y, size, label, active, color_on)
  r.ImGui_SetCursorScreenPos(ctx, x, y)
  local clicked = r.ImGui_InvisibleButton(ctx, id, size, size)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local pressed = r.ImGui_IsItemActive(ctx)
  local bg = active and (color_on or UI_THEME.accent_fill) or (hovered and UI_THEME.surface_hvr or UI_THEME.surface)
  local edge = hovered and UI_THEME.accent_hvr or (active and (color_on or UI_THEME.accent) or UI_THEME.border)
  local text = active and 0xFFFFFFFF or (hovered and UI_THEME.text or UI_THEME.text_dim)
  ui_draw_panel(dl, x, y, x + size, y + size, 6.0, bg, edge, hovered, pressed)
  local tw, th = r.ImGui_CalcTextSize(ctx, label)
  r.ImGui_DrawList_AddText(dl, x + (size - tw) * 0.5, y + (size - th) * 0.5 + (pressed and 1.0 or 0.0), text, label)
  return clicked
end

function seq_midi_note_button(id, dl, x, y, w, h, slot, active)
  r.ImGui_SetCursorScreenPos(ctx, x, y)
  local clicked = r.ImGui_InvisibleButton(ctx, id, w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local pressed = r.ImGui_IsItemActive(ctx)
  local learning = state.seq_midi_learn_slot_id == (slot and slot.id)
  local pulse = learning and (0.5 + 0.5 * math.sin(r.time_precise() * 8.0)) or 0.0
  local bg = (active or learning) and UI_THEME.accent_fill or (hovered and UI_THEME.surface_hvr or UI_THEME.surface)
  local edge = learning and UI_THEME.accent_hvr or ((hovered or active) and UI_THEME.accent or UI_THEME.border)
  if learning then
    local a = math.floor(80 + pulse * 140)
    edge = build_color_rrgbbaa(30, 255, 94, a)
  end
  ui_draw_panel(dl, x, y, x + w, y + h, 5.0, bg, edge, hovered, pressed)
  local label = learning and "…" or seq_midi_slot_label(slot)
  local tw, th = r.ImGui_CalcTextSize(ctx, label)
  local text = (active or learning) and 0xFFFFFFFF or (hovered and UI_THEME.text or UI_THEME.text_dim)
  r.ImGui_DrawList_AddText(dl, x + (w - tw) * 0.5, y + (h - th) * 0.5 + (pressed and 1.0 or 0.0), text, label)
  return clicked
end

-- Horizontal rectangular drag control (volume / pan style).
-- Drag vertically to adjust (like a compact fader); shows fill for volume or
-- a bipolar marker for pan when bipolar=true.
function seq_rect_drag_control(id, dl, x, y, w, h, value, min_v, max_v, opts)
  opts = opts or {}
  w = math.max(18.0, w or 44.0)
  h = math.max(12.0, h or 16.0)
  min_v = min_v or 0.0
  max_v = max_v or 1.0
  if max_v <= min_v then max_v = min_v + 1.0 end
  value = math.max(min_v, math.min(max_v, value or min_v))

  r.ImGui_SetCursorScreenPos(ctx, x, y)
  r.ImGui_InvisibleButton(ctx, id, w, h)
  local active = r.ImGui_IsItemActive(ctx)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local fine = seq_fine_drag_down()
  local changed = false
  local reset = opts.reset
  if reset == nil then
    reset = opts.unity
  end

  if reset ~= nil and hovered and r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0) then
    value = math.max(min_v, math.min(max_v, reset))
    changed = true
    state.seq_rect_drag = nil
  elseif active then
    local mx, my = r.ImGui_GetMousePos(ctx)
    mx, my = mx or x, my or y
    if (not state.seq_rect_drag) or state.seq_rect_drag.id ~= id then
      state.seq_rect_drag = { id = id, start_value = value, start_my = my, start_mx = mx, fine = fine }
    end
    local drag = state.seq_rect_drag
    if drag.fine ~= fine then
      drag.start_value = value
      drag.start_my = my
      drag.start_mx = mx
      drag.fine = fine
    end
    local span = max_v - min_v
    local scale = fine and SEQ_FINE_DRAG_SCALE or 1.0
    if opts.horizontal then
      if fine then
        local start_t = opts.to_pos and opts.to_pos(drag.start_value or value)
          or (((drag.start_value or value) - min_v) / span)
        local t = start_t + (mx - (drag.start_mx or mx)) / math.max(1.0, w) * scale
        t = math.max(0.0, math.min(1.0, t))
        if opts.from_pos then
          value = opts.from_pos(t)
        else
          value = min_v + t * span
        end
      else
        local t = (mx - x) / math.max(1.0, w)
        t = math.max(0.0, math.min(1.0, t))
        if opts.from_pos then
          value = opts.from_pos(t)
        else
          value = min_v + t * span
        end
      end
      value = math.max(min_v, math.min(max_v, value))
    else
      local sensitivity = span / 120.0 * scale
      local drag_y = my - (drag.start_my or my)
      value = (drag.start_value or value) - drag_y * sensitivity
      value = math.max(min_v, math.min(max_v, value))
    end
    changed = true
  elseif state.seq_rect_drag and state.seq_rect_drag.id == id then
    state.seq_rect_drag = nil
  end

  local bg = hovered and UI_THEME.surface_hvr or UI_THEME.surface
  local edge = (hovered or active) and UI_THEME.accent or UI_THEME.border
  local fill = opts.fill_color or UI_THEME.accent
  ui_draw_panel(dl, x, y, x + w, y + h, 5.0, bg, edge, hovered, active)

  local t
  if opts.to_pos then
    t = opts.to_pos(value)
  else
    t = (value - min_v) / (max_v - min_v)
  end
  if t < 0.0 then t = 0.0 elseif t > 1.0 then t = 1.0 end
  if opts.bipolar then
    local mid = x + w * 0.5
    r.ImGui_DrawList_AddLine(dl, mid, y + 2, mid, y + h - 2, 0xFFFFFF55, 1.0)
    local mx = x + t * w
    r.ImGui_DrawList_AddRectFilled(dl, mx - 2.0, y + 2, mx + 2.0, y + h - 2, fill, 1.5)
    if t >= 0.5 then
      r.ImGui_DrawList_AddRectFilled(dl, mid, y + 3, mx, y + h - 3, build_color_rrgbbaa(106, 160, 224, 90), 1.0)
    else
      r.ImGui_DrawList_AddRectFilled(dl, mx, y + 3, mid, y + h - 3, build_color_rrgbbaa(106, 160, 224, 90), 1.0)
    end
  else
    local fill_w = math.max(2.0, t * (w - 4))
    r.ImGui_DrawList_AddRectFilled(dl, x + 2, y + 2, x + 2 + fill_w, y + h - 2, fill, 2.0)
    if opts.unity and opts.unity >= min_v and opts.unity <= max_v then
      local ut = opts.to_pos and opts.to_pos(opts.unity) or ((opts.unity - min_v) / (max_v - min_v))
      local ux = x + math.max(0.0, math.min(1.0, ut)) * w
      r.ImGui_DrawList_AddLine(dl, ux, y + 1, ux, y + h - 1, 0xFFFFFF66, 1.0)
    end
  end

  local display = nil
  if opts.format_value then
    display = opts.format_value(value)
  elseif opts.value_text and opts.value_text ~= "" then
    display = opts.value_text
  end
  if display and display ~= "" then
    local tw, th = r.ImGui_CalcTextSize(ctx, display)
    local tx = x + (w - tw) * 0.5
    local ty = y + (h - th) * 0.5
    r.ImGui_DrawList_AddText(dl, tx + 1, ty + 1, 0x000000AA, display)
    r.ImGui_DrawList_AddText(dl, tx, ty, 0xF0F4FAFF, display)
  end

  return changed, value, active or hovered
end

function seq_layout_hit(box, mx, my)
  return box and (box.w or 0) > 0.5 and (box.h or 0) > 0.5
    and mx >= box.x and mx < box.x1 and my >= box.y and my < box.y1
end

function seq_set_candidate_drop(slot, idx)
  idx = tonumber(idx)
  if not slot or not idx then
    return
  end
  state.seq_candidate_drop = { slot_id = slot.id, idx = idx }
  state.seq_drop_target_idx = nil
  state.seq_drum_drop = nil
  state.seq_timeline_drop_time = nil
  state.seq_timeline_drop_track_idx = nil
end

function seq_track_nav_width(lane_h)
  local icon_size = seq_icon_size_for_lane_h(lane_h)
  return get_seq_track_sample_controls_width(seq_ctrl_size_for_icon(icon_size), icon_size)
end

function seq_mix_strip_width(btn, gap, vol_w, pan_w, midi_w)
  return (btn or 14) * 4 + (vol_w or 52) + (pan_w or 40) + (midi_w or 28) + (gap or 3) * 6
end

function seq_box(x, y, w, h)
  w = math.max(0, w or 0)
  h = math.max(0, h or 0)
  return { x = x, y = y, w = w, h = h, x1 = x + w, y1 = y + h }
end

function seq_fit_mix_strip(avail_w, btn, gap, vol_w, pan_w, midi_w)
  vol_w = vol_w or 52.0
  pan_w = pan_w or 40.0
  midi_w = midi_w or 28.0
  btn = btn or 14.0
  gap = gap or 3.0
  local function width()
    return seq_mix_strip_width(btn, gap, vol_w, pan_w, midi_w)
  end
  while width() > avail_w do
    if vol_w > 34 then
      vol_w = vol_w - 2
    elseif pan_w > 26 then
      pan_w = pan_w - 2
    elseif midi_w > 22 then
      midi_w = midi_w - 2
    elseif btn > 12 then
      btn = btn - 1
    else
      break
    end
  end
  return btn, vol_w, pan_w, midi_w, width()
end

function seq_place_mix_strip(layout, x, y, btn, gap, vol_w, pan_w, midi_w, row_h)
  layout.gear = seq_box(x, y, btn, btn)
  x = x + btn + gap
  layout.vol = seq_box(x, y, vol_w, row_h)
  x = x + vol_w + gap
  layout.pan = seq_box(x, y, pan_w, row_h)
  x = x + pan_w + gap
  layout.midi = seq_box(x, y, midi_w, row_h)
  x = x + midi_w + gap
  layout.mute = seq_box(x, y, btn, btn)
  x = x + btn + gap
  layout.solo = seq_box(x, y, btn, btn)
  x = x + btn + gap
  layout.overlap = seq_box(x, y, btn, btn)
  return layout.overlap.x1
end

function seq_candidate_log_unit(value, lo, hi)
  lo = lo or 0.03
  hi = hi or 1.0
  if type(value) ~= "number" or value <= 0 or hi <= lo then
    return 0.5
  end
  value = math.max(lo, math.min(hi, value))
  return (math.log(value) - math.log(lo)) / (math.log(hi) - math.log(lo))
end

function seq_candidate_freq_hue(freq)
  -- Log map so kick-band differences (60 vs 180 vs 400 Hz) actually move hue.
  freq = tonumber(freq) or 440.0
  freq = math.max(40.0, math.min(10000.0, freq))
  return seq_candidate_log_unit(freq, 40.0, 10000.0) * 210.0
end

function seq_candidate_unit_in_range(value, lo, hi, fallback)
  if type(value) ~= "number" or type(lo) ~= "number" or type(hi) ~= "number" then
    return fallback or 0.5
  end
  if hi - lo < 1e-6 then
    return fallback or 0.5
  end
  return math.max(0.0, math.min(1.0, (value - lo) / (hi - lo)))
end

function seq_candidate_slot_scale(slot)
  if not slot then
    return nil
  end
  seq_normalize_slot_candidates(slot)
  local n = 0
  local b_lo, b_hi = 1e9, -1e9
  local w_lo, w_hi = 1e9, -1e9
  local d_lo, d_hi = 1e9, -1e9
  local list = slot.sample_candidates
  if type(list) ~= "table" then
    return nil
  end
  for i = 1, SEQ_SAMPLE_CANDIDATES_MAX do
    if seq_candidate_entry_taken(list[i]) then
      local p = seq_candidate_chip_props(list[i])
      local bright = p.brightness or p.freq
      n = n + 1
      if type(bright) == "number" then
        b_lo = math.min(b_lo, bright)
        b_hi = math.max(b_hi, bright)
      end
      w_lo = math.min(w_lo, p.weight)
      w_hi = math.max(w_hi, p.weight)
      if type(p.duration) == "number" and p.duration > 0 then
        d_lo = math.min(d_lo, p.duration)
        d_hi = math.max(d_hi, p.duration)
      end
    end
  end
  if n < 2 then
    return nil
  end
  return {
    bright_lo = b_lo, bright_hi = b_hi,
    weight_lo = w_lo, weight_hi = w_hi,
    dur_lo = d_lo, dur_hi = d_hi,
  }
end

function seq_candidate_hsv_to_color(h, s, v, a)
  h = ((tonumber(h) or 0) % 360.0 + 360.0) % 360.0
  s = math.max(0.0, math.min(1.0, tonumber(s) or 0.7))
  v = math.max(0.0, math.min(1.0, tonumber(v) or 0.7))
  a = math.max(0, math.min(255, math.floor((tonumber(a) or 1.0) * 255 + 0.5)))
  local c = v * s
  local hp = h / 60.0
  local x = c * (1.0 - math.abs(hp % 2.0 - 1.0))
  local m = v - c
  local r, g, b = 0, 0, 0
  if hp < 1 then
    r, g, b = c, x, 0
  elseif hp < 2 then
    r, g, b = x, c, 0
  elseif hp < 3 then
    r, g, b = 0, c, x
  elseif hp < 4 then
    r, g, b = 0, x, c
  elseif hp < 5 then
    r, g, b = x, 0, c
  else
    r, g, b = c, 0, x
  end
  return build_color_rrgbbaa(
    math.floor((r + m) * 255 + 0.5),
    math.floor((g + m) * 255 + 0.5),
    math.floor((b + m) * 255 + 0.5),
    a
  )
end

function seq_candidate_chip_props(entry)
  local sample = entry and entry.path and find_sample_by_path(entry.path) or nil
  local function num(key, fallback)
    if sample and type(sample[key]) == "number" then
      return sample[key]
    end
    if entry and type(entry[key]) == "number" then
      return entry[key]
    end
    return fallback
  end
  local dur = nil
  if sample and sample_map_duration then
    dur = sample_map_duration(sample)
  end
  if type(dur) ~= "number" or dur <= 0 then
    dur = num("effective_duration", num("duration", nil))
  end
  return {
    freq = num("dominant_freq", 440.0),
    brightness = num("brightness", nil),
    weight = math.max(0.0, math.min(1.0, num("sub_weight", 0.45))),
    duration = dur,
  }
end

function seq_layout_place_name_candidates(layout, slot, inner_x0, inner_x1, top_y, name_h, expand_w, gap)
  layout.expand = seq_box(inner_x0, top_y, expand_w, name_h)
  local name_x = inner_x0 + expand_w
  local name_w = math.max(0.0, inner_x1 - name_x)
  local cand = seq_place_sample_candidates(slot, inner_x1, top_y, top_y + name_h, math.max(0.0, name_w - 36.0))
  if cand.w > 0 then
    layout.candidates = cand.hit
    layout.candidate_boxes = cand.boxes
    name_w = math.max(0.0, cand.hit.x - (gap or 3.0) - name_x)
  end
  layout.name = seq_box(name_x, top_y, name_w, name_h)
end

function seq_place_sample_candidates(slot, x1, y0, y1, max_w)
  local empty = { boxes = {}, w = 0, hit = seq_box(0, 0, 0, 0), sq = 0 }
  x1, y0, y1 = x1 or 0, y0 or 0, y1 or 0
  max_w = max_w or 0
  local avail_h = y1 - y0
  if avail_h < 12.0 or max_w < 12.0 then
    return empty
  end
  local gap = 2.0
  local count = seq_candidate_visible_count(slot)
  local sq = math.max(12.0, math.min(avail_h, 24.0))
  local rows = 1
  local cols = count
  local function dims(size, n, r)
    r = math.max(1, r)
    local c = math.ceil(n / r)
    return r, c, c * size + (c - 1) * gap, math.min(n, r) * size + (math.min(n, r) - 1) * gap
  end
  local _, _, grid_w, grid_h = dims(sq, count, rows)
  if grid_w > max_w then
    local rows_fit = math.max(1, math.floor((avail_h + gap) / (sq + gap)))
    if rows_fit > 1 then
      rows = math.min(rows_fit, count)
      _, cols, grid_w, grid_h = dims(sq, count, rows)
    end
  end
  while grid_w > max_w and sq > 12.0 do
    sq = sq - 1.0
    _, cols, grid_w, grid_h = dims(sq, count, rows)
  end
  if grid_w > max_w then
    local fit_cols = math.max(1, math.floor((max_w + gap) / (sq + gap)))
    count = math.max(1, math.min(count, fit_cols * rows))
    rows, cols, grid_w, grid_h = dims(sq, count, rows)
  end
  if grid_w > max_w or grid_w <= 0 then
    return empty
  end
  local left = x1 - grid_w
  local top = y0 + (avail_h - grid_h) * 0.5
  local boxes = {}
  local i = 1
  for row = 1, rows do
    for col = 1, cols do
      if i > count then
        break
      end
      boxes[i] = seq_box(left + (col - 1) * (sq + gap), top + (row - 1) * (sq + gap), sq, sq)
      i = i + 1
    end
  end
  return {
    boxes = boxes,
    w = grid_w,
    hit = seq_box(left, top, grid_w, grid_h),
    sq = sq,
  }
end

function seq_draw_sample_candidate_square(dl, box, entry, is_active, is_hovered, scale, slot_n, alpha)
  if not dl or not box or box.w < 4 then
    return
  end
  local x, y, w, h = box.x, box.y, box.w, box.h
  local rounding = math.min(3.5, w * 0.22)
  local taken = seq_candidate_entry_taken(entry)
  local a = math.max(0.0, math.min(1.0, tonumber(alpha) or 1.0))
  local function ca(col, mul)
    if not col then
      return col
    end
    local orig_a = (col % 256) / 255.0
    return change_color_alpha(col, orig_a * a * (mul or 1.0))
  end
  local bg = is_active and (taken and 0x122016FF or UI_THEME.accent_fill) or (is_hovered and 0x161E1AFF or 0x0C1210FF)
  local edge = UI_THEME.border
  local edge_w = 1.0
  if is_active then
    edge = 0xFFFFFF80
    edge_w = 1.8
  elseif is_hovered then
    edge = 0xE8EEEAFF
  elseif taken then
    edge = UI_THEME.border_hvr
  end

  r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, ca(bg), rounding)

  if taken then
    local props = seq_candidate_chip_props(entry)
    local hue = seq_candidate_freq_hue(props.freq)
    local bright_src = props.brightness or props.freq
    local bright_g = seq_candidate_log_unit(bright_src, 100.0, 2500.0)
    local bright_t = bright_g
    local weight_t = props.weight
    if scale then
      bright_t = seq_candidate_unit_in_range(bright_src, scale.bright_lo, scale.bright_hi, bright_g)
      weight_t = seq_candidate_unit_in_range(props.weight, scale.weight_lo, scale.weight_hi, props.weight)
    end
    local sat = 0.55 + weight_t * 0.40
    if is_hovered then
      bright_t = math.min(1.0, bright_t + 0.08)
    end
    if is_active then
      bright_t = math.min(1.0, bright_t + 0.10)
    end
    local col_top = seq_candidate_hsv_to_color(hue, sat, 0.52 + bright_t * 0.46, a)
    local col_bot = seq_candidate_hsv_to_color(hue, math.min(1.0, sat + 0.08), 0.22 + bright_t * 0.28, a)

    -- MultiColor fills are square; clip rounded rects per band so the chip
    -- follows the same corner radius as the outline.
    local bands = math.max(4, math.min(10, math.floor(h + 0.5)))
    if r.ImGui_DrawList_PushClipRect then
      for i = 0, bands - 1 do
        local t = (i + 0.5) / bands
        local col = blend_colors(col_top, col_bot, t)
        local y0 = y + (h * i) / bands
        local y1 = y + (h * (i + 1) / bands)
        r.ImGui_DrawList_PushClipRect(dl, x, y0, x + w, math.min(y + h, y1 + 0.5), true)
        r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, col, rounding)
        r.ImGui_DrawList_PopClipRect(dl)
      end
    else
      r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, col_top, rounding)
    end
  end

  if is_active then
    r.ImGui_DrawList_AddRect(dl, x - 1.2, y - 1.2, x + w + 1.2, y + h + 1.2,
      ca(0xFFFFFF40), rounding + 1.0, 0, 2.0)
  end
  r.ImGui_DrawList_AddRect(dl, x, y, x + w, y + h, ca(edge), rounding, 0, edge_w)

  if state.seq_candidate_show_numbers ~= false and slot_n then
    local label = tostring(slot_n)
    local font = r.ImGui_GetFont and r.ImGui_GetFont(ctx) or nil
    local base_sz = (r.ImGui_GetFontSize and r.ImGui_GetFontSize(ctx)) or 13.0
    local sz = base_sz * 0.58
    local tw, th = r.ImGui_CalcTextSize(ctx, label)
    tw = (tw or 6) * (sz / math.max(1.0, base_sz))
    th = (th or 10) * (sz / math.max(1.0, base_sz))
    local tx = x + (w - tw) * 0.5
    local ty = y + (h - th) * 0.5
    local num_col = ca(taken and 0xFFFFFF72 or 0xC8D0C850)
    local sh_col = ca(0x00000044)
    if r.ImGui_DrawList_AddTextEx then
      r.ImGui_DrawList_AddTextEx(dl, font, sz, tx + 0.5, ty + 0.5, sh_col, label)
      r.ImGui_DrawList_AddTextEx(dl, font, sz, tx, ty, num_col, label)
    else
      r.ImGui_DrawList_AddText(dl, tx + 0.5, ty + 0.5, sh_col, label)
      r.ImGui_DrawList_AddText(dl, tx, ty, num_col, label)
    end
  end
end

function seq_draw_candidate_delete_x(dl, box, alpha)
  if not dl or not box or box.w < 4 then
    return
  end
  alpha = math.max(0.0, math.min(1.0, tonumber(alpha) or 1.0))
  if alpha <= 0.01 then
    return
  end
  local x, y, w, h = box.x, box.y, box.w, box.h
  local rounding = math.min(3.5, w * 0.22)
  local pulse = 0.5 + 0.5 * math.sin(r.time_precise() * 8.0)
  r.ImGui_DrawList_AddRectFilled(
    dl, x, y, x + w, y + h,
    build_color_rrgbbaa(18, 6, 6, math.floor((70 + pulse * 24) * alpha)),
    rounding
  )
  local inset = math.max(2.2, math.min(w, h) * 0.24)
  local x0, y0 = x + inset, y + inset
  local x1, y1 = x + w - inset, y + h - inset
  local thick = math.max(1.5, math.min(w, h) * 0.13)
  local col = build_color_rrgbbaa(255, 92, 92, math.floor((200 + pulse * 40) * alpha))
  local sh = build_color_rrgbbaa(0, 0, 0, math.floor(90 * alpha))
  r.ImGui_DrawList_AddLine(dl, x0 + 0.6, y0 + 0.6, x1 + 0.6, y1 + 0.6, sh, thick)
  r.ImGui_DrawList_AddLine(dl, x1 + 0.6, y0 + 0.6, x0 + 0.6, y1 + 0.6, sh, thick)
  r.ImGui_DrawList_AddLine(dl, x0, y0, x1, y1, col, thick)
  r.ImGui_DrawList_AddLine(dl, x1, y0, x0, y1, col, thick)
end

function seq_select_sample_candidate(slot, idx, persist)
  if not slot then
    return false
  end
  seq_normalize_slot_candidates(slot)
  idx = tonumber(idx)
  if not idx or idx < 1 or idx > SEQ_SAMPLE_CANDIDATES_MAX then
    return false
  end
  slot.sample_candidate_idx = idx
  if persist then
    save_config()
    if save_seq_project_state then
      save_seq_project_state()
    end
  end
  return true
end

function seq_apply_sample_candidate(slot, idx)
  if not slot then
    return false
  end
  seq_normalize_slot_candidates(slot)
  local persist = not seq_slot_in_swap_mode(slot)
  local entry = slot.sample_candidates and slot.sample_candidates[idx]
  if seq_candidate_entry_taken(entry) then
    local sample = find_sample_by_path(entry.path)
    if not sample then
      sample = { path = entry.path, name = entry.name, x = entry.x, y = entry.y }
    end
    local own = persist and seq_undo_own_begin and seq_undo_own_begin("Recall sample candidate")
    slot.sample_candidate_idx = idx
    seq_assign_sample_for_context(slot, sample, persist)
    if preview_seq_track_sample then
      preview_seq_track_sample(slot)
    elseif preview_sample and find_sample_by_path(entry.path) then
      preview_sample(find_sample_by_path(entry.path))
    end
    if own and end_seq_undo then
      end_seq_undo("Recall sample candidate")
    end
    return true
  end

  slot.sample_candidate_idx = idx
  if slot.sample_path and slot.sample_path ~= "" then
    local sample = find_sample_by_path(slot.sample_path) or {
      path = slot.sample_path,
      name = slot.sample_name,
    }
    seq_remember_sample_candidate(slot, sample)
  end
  if persist then
    save_config()
    if save_seq_project_state then
      save_seq_project_state()
    end
  end
  return true
end

function seq_drop_sample_on_candidate(slot, idx, sample, persist)
  if not slot or not sample then
    return false
  end
  seq_normalize_slot_candidates(slot)
  idx = tonumber(idx)
  if not idx or idx < 1 or idx > SEQ_SAMPLE_CANDIDATES_MAX then
    return false
  end
  slot.sample_candidate_idx = idx
  if apply_dragged_sample_to_seq_track then
    return apply_dragged_sample_to_seq_track(slot, sample, persist)
  end
  return assign_sample_to_seq_track(slot, sample, persist)
end

function render_seq_track_sample_candidates(dl, slot, layout)
  if not slot or not layout or not layout.candidate_boxes then
    return false
  end
  seq_normalize_slot_candidates(slot)
  local boxes = layout.candidate_boxes
  if #boxes == 0 then
    return false
  end
  local scale = seq_candidate_slot_scale(slot)
  local hovered = false
  local changed = false
  local dragging = sample_drag_active()
  local mx, my = r.ImGui_GetMousePos(ctx)
  local hover_flags = 0
  if dragging and r.ImGui_HoveredFlags_AllowWhenBlockedByActiveItem then
    hover_flags = r.ImGui_HoveredFlags_AllowWhenBlockedByActiveItem()
  end
  local anim, _, ease = seq_candidate_slide_anim(slot)
  if anim and anim.fade then
    local fade = anim.fade
    local s = 1.0 - ease * 0.58
    local cx = fade.x + fade.w * 0.5
    local cy = fade.y + fade.h * 0.5 - ease * 7.0
    local fw, fh = fade.w * s, fade.h * s
    local fade_box = seq_box(cx - fw * 0.5, cy - fh * 0.5, fw, fh)
    seq_draw_sample_candidate_square(dl, fade_box,
      fade.entry, false, false, scale, nil, 1.0 - ease)
    seq_draw_candidate_delete_x(dl, fade_box, (1.0 - ease) * (1.0 - ease * 0.35))
  end
  for i = 1, #boxes do
    local box = boxes[i]
    if box and box.w > 0 and box.h > 0 then
      r.ImGui_SetCursorScreenPos(ctx, box.x, box.y)
      r.ImGui_InvisibleButton(ctx, "##seq_cand_" .. tostring(slot.id) .. "_" .. i, box.w, box.h)
      local hot = r.ImGui_IsItemHovered(ctx, hover_flags)
      local is_source = seq_candidate_is_drag_source(slot, i)
      if dragging and seq_layout_hit(box, mx, my) then
        hot = true
        seq_set_candidate_drop(slot, i)
      end
      if hot then
        hovered = true
      end
      local entry = slot.sample_candidates[i]
      local is_active = slot.sample_candidate_idx == i
      local draw_box = box
      if anim and anim.moves and anim.moves[i] then
        local move = anim.moves[i]
        draw_box = seq_box(
          move.from_x + (box.x - move.from_x) * ease,
          move.from_y + (box.y - move.from_y) * ease,
          box.w, box.h
        )
      end
      seq_draw_sample_candidate_square(dl, draw_box, entry, is_active, hot, scale, i)
      local alt_delete = (not dragging) and hot and is_alt_down() and seq_candidate_entry_taken(entry)
      if alt_delete then
        seq_draw_candidate_delete_x(dl, draw_box, 1.0)
      end
      if is_source and dl then
        draw_waveform_drag_source_cue(dl, box.x, box.y, box.w, box.h)
      elseif dragging and state.seq_candidate_drop
          and state.seq_candidate_drop.slot_id == slot.id
          and state.seq_candidate_drop.idx == i
          and dl then
        draw_drop_target_highlight(dl, box.x, box.y, box.x + box.w, box.y + box.h, 3)
      end
      if hot and r.ImGui_SetTooltip then
        if dragging then
          r.ImGui_SetTooltip(ctx, is_source
            and "Drop anywhere to place this sample"
            or "Drop to save in this slot")
        elseif alt_delete then
          r.ImGui_SetTooltip(ctx, "Click to remove")
        elseif seq_candidate_entry_taken(entry) then
          r.ImGui_SetTooltip(ctx, (entry.name or "Sample")
            .. (is_active and "\nSelected — sample changes save here" or "\nClick to recall")
            .. "\nDrag to drop · Alt-click to remove")
        else
          r.ImGui_SetTooltip(ctx, "Click to copy the current sample here")
        end
      end
      if (not dragging) and r.ImGui_IsItemClicked(ctx, 0) then
        if is_alt_down() and seq_candidate_entry_taken(entry) then
          state.seq_candidate_press = nil
          local persist = not seq_slot_in_swap_mode(slot)
          local own = persist and seq_undo_own_begin and seq_undo_own_begin("Remove sample candidate")
          seq_begin_candidate_slide(slot, i, boxes)
          if seq_remove_sample_candidate(slot, i) then
            changed = true
            if persist then
              save_config()
              if save_seq_project_state then
                save_seq_project_state()
              end
            end
          else
            if state.seq_candidate_slide then
              state.seq_candidate_slide[slot.id] = nil
            end
          end
          if own and end_seq_undo then
            end_seq_undo("Remove sample candidate")
          end
          break
        elseif seq_candidate_entry_taken(entry) then
          state.seq_candidate_press = { slot_id = slot.id, idx = i }
        elseif seq_apply_sample_candidate(slot, i) then
          changed = true
        end
      end
    end
  end
  local press = state.seq_candidate_press
  if press and press.slot_id == slot.id and not dragging then
    if not is_alt_down()
        and r.ImGui_IsMouseDragging and r.ImGui_IsMouseDragging(ctx, 0, 6.0) then
      local drag_sample = seq_candidate_sample_from_entry(slot.sample_candidates[press.idx])
      if drag_sample and begin_waveform_sample_drag(drag_sample) then
        state.seq_candidate_drag_source = { slot_id = press.slot_id, idx = press.idx }
        state.seq_candidate_press = nil
      end
    end
  end
  return changed, hovered
end

-- Height-aware TCP layout for the sequencer label column (left of the sample nav).
-- tiny  (<38): one centered row, shrink mix, hide env if it would crush the name
-- split (38-63): name on its own row, mix+env share the second row
-- stack (64-99): name, full-width mix, full-width envelope
-- mixer (>=100): name, button row, stacked wide vol/pan, tall envelope
function seq_get_track_control_layout(x0, y0, x1, y1, slot, opts)
  x0, y0, x1, y1 = x0 or 0, y0 or 0, x1 or 0, y1 or 0
  if x1 < x0 then x1 = x0 end
  if y1 < y0 then y1 = y0 end
  opts = opts or {}
  local lane_h = y1 - y0
  local pad = (lane_h >= 64.0) and 4.0 or 3.0
  local gap = 3.0
  local expand_w = opts.hide_expand and 0.0 or 26.0
  local inner_x0 = x0 + pad
  local inner_x1 = x1 - pad
  local inner_w = math.max(0.0, inner_x1 - inner_x0)
  local mode = "tiny"
  if lane_h >= 100.0 then
    mode = "mixer"
  elseif lane_h >= 64.0 then
    mode = "stack"
  elseif lane_h >= 38.0 then
    mode = "split"
  end

  local layout = {
    mode = mode,
    lane_h = lane_h,
    expand = seq_box(0, 0, 0, 0),
    name = seq_box(0, 0, 0, 0),
    gear = seq_box(0, 0, 0, 0),
    vol = seq_box(0, 0, 0, 0),
    pan = seq_box(0, 0, 0, 0),
    midi = seq_box(0, 0, 0, 0),
    mute = seq_box(0, 0, 0, 0),
    solo = seq_box(0, 0, 0, 0),
    overlap = seq_box(0, 0, 0, 0),
    env = seq_box(0, 0, 0, 0),
    mix_hit = seq_box(0, 0, 0, 0),
    candidates = seq_box(0, 0, 0, 0),
    candidate_boxes = {},
  }

  if mode == "tiny" then
    local btn = math.max(12.0, math.min(15.0, lane_h - 8.0))
    local row_h = btn
    local mid_y = y0 + (lane_h - row_h) * 0.5
    local name_min = 28.0
    local btn2, vol_w, pan_w, midi_w, mix_w = seq_fit_mix_strip(
      math.max(80.0, inner_w - expand_w - name_min - gap), btn, gap, 48.0, 36.0, 26.0
    )
    btn = btn2
    row_h = btn
    mid_y = y0 + (lane_h - row_h) * 0.5
    local mix_x = inner_x1 - mix_w
    local name_x = inner_x0 + expand_w
    local mid_space = math.max(0.0, mix_x - gap - name_x)
    local env_w = 0.0
    if mid_space >= name_min + gap + 40.0 then
      env_w = math.min(SEQ_ENV_PREVIEW_W or 80.0, mid_space - name_min - gap)
      if env_w < 36.0 then env_w = 0.0 end
    end
    local name_w = math.max(0.0, mid_space - (env_w > 0 and (env_w + gap) or 0.0))
    layout.expand = seq_box(inner_x0, mid_y, expand_w, row_h)
    layout.name = seq_box(name_x, mid_y, name_w, row_h)
    if env_w > 0 then
      layout.env = seq_box(name_x + name_w + gap, mid_y, env_w, row_h)
    end
    seq_place_mix_strip(layout, mix_x, mid_y, btn, gap, vol_w, pan_w, midi_w, row_h)
    local hit_x0 = (env_w > 0) and layout.env.x or layout.gear.x
    layout.mix_hit = seq_box(hit_x0, mid_y, inner_x1 - hit_x0, row_h)

  elseif mode == "split" then
    local name_h = math.max(14.0, math.min(17.0, 14.0 + (lane_h - 38.0) * 0.12))
    local btn = math.max(13.0, math.min(17.0, 13.0 + (lane_h - 38.0) * 0.16))
    local row_h = btn
    local gap_v = 2.0
    local block_h = name_h + gap_v + row_h
    local top_y = y0 + math.max(pad, (lane_h - block_h) * 0.5)
    local ctrl_y = top_y + name_h + gap_v
    seq_layout_place_name_candidates(layout, slot, inner_x0, inner_x1, top_y, name_h, expand_w, gap)

    local env_reserve = 0.0
    if inner_w >= 210.0 then
      env_reserve = math.max(40.0, math.min(88.0, inner_w * 0.24))
    end
    local mix_avail = inner_w - (env_reserve > 0 and (env_reserve + gap) or 0.0)
    local btn2, vol_w, pan_w, midi_w, mix_w = seq_fit_mix_strip(mix_avail, btn, gap, 52.0, 40.0, 28.0)
    btn = btn2
    row_h = math.max(row_h, btn)
    ctrl_y = top_y + name_h + gap_v
    local leftover = inner_w - mix_w - gap
    local env_w = 0.0
    if leftover >= 36.0 then
      if leftover > 92.0 then
        local grow = leftover - 92.0
        vol_w = vol_w + grow * 0.62
        pan_w = pan_w + grow * 0.38
        mix_w = seq_mix_strip_width(btn, gap, vol_w, pan_w, midi_w)
        leftover = inner_w - mix_w - gap
      end
      env_w = leftover
    end
    seq_place_mix_strip(layout, inner_x0, ctrl_y, btn, gap, vol_w, pan_w, midi_w, row_h)
    if env_w >= 36.0 then
      layout.env = seq_box(layout.overlap.x1 + gap, ctrl_y, env_w, row_h)
    end
    layout.mix_hit = seq_box(inner_x0, ctrl_y, inner_w, row_h)

  elseif mode == "stack" then
    local name_h = 16.0
    local rest = lane_h - pad * 2 - name_h - 4.0
    local row_h = math.max(14.0, math.min(20.0, rest * 0.42))
    local env_h = math.max(12.0, rest - row_h - 3.0)
    local btn = math.max(14.0, math.min(row_h, 18.0))
    local top_y = y0 + pad
    local mix_y = top_y + name_h + 3.0
    local env_y = mix_y + row_h + 3.0
    if env_y + env_h > y1 - pad then
      env_h = math.max(12.0, (y1 - pad) - env_y)
    end
    seq_layout_place_name_candidates(layout, slot, inner_x0, inner_x1, top_y, name_h, expand_w, gap)

    local btn2, vol_w, pan_w, midi_w, mix_w = seq_fit_mix_strip(inner_w, btn, gap, 56.0, 42.0, 30.0)
    btn = btn2
    if inner_w > mix_w then
      local grow = inner_w - mix_w
      vol_w = vol_w + grow * 0.62
      pan_w = pan_w + grow * 0.38
    end
    seq_place_mix_strip(layout, inner_x0, mix_y, btn, gap, vol_w, pan_w, midi_w, row_h)
    layout.env = seq_box(inner_x0, env_y, inner_w, env_h)
    layout.mix_hit = seq_box(inner_x0, mix_y, inner_w, (y1 - pad) - mix_y)

  else
    local name_h = math.max(15.0, math.min(20.0, 15.0 + (lane_h - 100.0) * 0.05))
    local btn = math.max(15.0, math.min(20.0, 15.0 + (lane_h - 100.0) * 0.05))
    local rest = lane_h - pad * 2 - name_h - btn - 9.0
    local bar_h = math.max(15.0, math.min(26.0, (rest - 6.0) / 3.0))
    local env_h = math.max(14.0, rest - bar_h * 2.0 - 6.0)
    local y = y0 + pad
    seq_layout_place_name_candidates(layout, slot, inner_x0, inner_x1, y, name_h, expand_w, gap)
    y = y + name_h + 3.0
    local midi_w = math.max(32.0, math.min(52.0, btn * 2.4))
    local cx = inner_x0
    layout.gear = seq_box(cx, y, btn, btn); cx = cx + btn + gap
    layout.mute = seq_box(cx, y, btn, btn); cx = cx + btn + gap
    layout.solo = seq_box(cx, y, btn, btn); cx = cx + btn + gap
    layout.overlap = seq_box(cx, y, btn, btn); cx = cx + btn + gap
    layout.midi = seq_box(cx, y, midi_w, btn)
    y = y + btn + 3.0
    layout.vol = seq_box(inner_x0, y, inner_w, bar_h)
    y = y + bar_h + 3.0
    layout.pan = seq_box(inner_x0, y, inner_w, bar_h)
    y = y + bar_h + 3.0
    env_h = math.max(12.0, (y1 - pad) - y)
    layout.env = seq_box(inner_x0, y, inner_w, env_h)
    layout.mix_hit = seq_box(inner_x0, layout.gear.y, inner_w, (y1 - pad) - layout.gear.y)
  end

  return layout
end

function seq_draw_track_name_and_expand(dl, slot, layout, expanded, name_alpha, expand_color, fallback_name)
  if not layout or not slot then
    return
  end
  local exp = layout.expand
  if exp and exp.w > 0 then
    local exp_label = expanded and "[-]" or "[+]"
    local tw, th = r.ImGui_CalcTextSize(ctx, exp_label)
    r.ImGui_DrawList_AddText(
      dl,
      exp.x + (exp.w - (tw or 16)) * 0.5,
      exp.y + (exp.h - (th or 12)) * 0.5,
      expand_color or 0xFFDFAAFF,
      exp_label
    )
  end
  local name_box = layout.name
  if name_box and name_box.w > 4 then
    local name_txt = seq_truncate_text_to_width(slot.name or fallback_name or "Track", name_box.w)
    local _, nh = r.ImGui_CalcTextSize(ctx, name_txt)
    r.ImGui_DrawList_AddText(
      dl,
      name_box.x,
      name_box.y + (name_box.h - (nh or 12)) * 0.5,
      build_color_rrgbbaa(255, 255, 255, name_alpha or 255),
      name_txt
    )
  end
end

function seq_lane_mix_controls_hit(row_pos, mx, my, x0, timeline_x0, map_nav_w)
  if not row_pos or not row_pos.row or row_pos.row.type ~= "note" then
    return false
  end
  local layout = row_pos.ctrl
  if not layout and x0 and timeline_x0 then
    local nav_w = map_nav_w or seq_track_nav_width(row_pos.y1 - row_pos.y0)
    layout = seq_get_track_control_layout(
      x0, row_pos.y0, timeline_x0 - nav_w - 6.0, row_pos.y1,
      row_pos.row and row_pos.row.slot
    )
  end
  return seq_layout_hit(layout and layout.mix_hit, mx, my)
    or seq_layout_hit(layout and layout.candidates, mx, my)
end

-- Compact mixer + envelope preview in the sequencer track label column.
-- Layout is computed by seq_get_track_control_layout so widgets reflow with lane height.
-- Returns changed_mix, overlap_changed, hovered
function render_seq_track_mix_controls(dl, slot, x0, y0, x1, y1, layout)
  if not slot then return false, false, false end
  seq_normalize_slot_mix(slot)
  if type(x0) == "table" then
    layout = x0
  else
    layout = layout or seq_get_track_control_layout(x0, y0, x1, y1, slot)
  end
  if not layout then return false, false, false end

  local changed_mix = false
  local hovered = false
  local overlap_changed = false

  local function mark_hover()
    if r.ImGui_IsItemHovered(ctx) then
      hovered = true
    end
  end

  local gear = layout.gear
  if gear and gear.w > 0 then
    local layering_open = state.seq_layering_slot_id == slot.id
    if seq_layering_button("##seq_layering_" .. slot.id, dl, gear.x, gear.y, gear.w, layering_open) then
      if layering_open then
        state.seq_layering_slot_id = nil
      else
        state.seq_layering_slot_id = slot.id
        seq_layering_seed_from_track(slot)
      end
    end
    if r.ImGui_IsItemHovered(ctx) then
      hovered = true
      if r.ImGui_SetTooltip then
        r.ImGui_SetTooltip(ctx, "Drum layering")
      end
    end
  end

  local vol = layout.vol
  if vol and vol.w > 0 then
    local vol_changed, vol_val, vol_hot = seq_rect_drag_control(
      "##seq_track_vol_" .. slot.id, dl, vol.x, vol.y, vol.w, vol.h,
      slot.volume, 0.0, 4.0,
      {
        fill_color = 0x6AA0E0FF,
        unity = 1.0,
        reset = 1.0,
        horizontal = true,
        to_pos = seq_vol_amp_to_pos,
        from_pos = seq_vol_pos_to_amp,
        format_value = seq_format_track_volume,
      }
    )
    if vol_hot then hovered = true end
    if vol_changed then
      slot.volume = vol_val
      changed_mix = true
    end
  end

  local pan = layout.pan
  if pan and pan.w > 0 then
    local pan_changed, pan_val, pan_hot = seq_rect_drag_control(
      "##seq_track_pan_" .. slot.id, dl, pan.x, pan.y, pan.w, pan.h,
      slot.pan, -1.0, 1.0,
      {
        bipolar = true,
        fill_color = 0x9FE3B5FF,
        horizontal = true,
        reset = 0.0,
        format_value = seq_format_track_pan,
      }
    )
    if pan_hot then hovered = true end
    if pan_changed then
      slot.pan = pan_val
      changed_mix = true
    end
  end

  local midi = layout.midi
  if midi and midi.w > 0 then
    local midi_learning = state.seq_midi_learn_slot_id == slot.id
    local midi_open = state.seq_midi_popup_slot_id == slot.id
    if seq_midi_note_button("##seq_midi_" .. slot.id, dl, midi.x, midi.y, midi.w, midi.h, slot, midi_learning or midi_open) then
      seq_midi_ensure_jsfx()
      if is_alt_down and is_alt_down() then
        local def = seq_midi_default_note_for_slot(slot)
        seq_midi_set_range(slot, def, def)
        save_config()
        if save_seq_project_state then save_seq_project_state() end
      else
        state.seq_midi_popup_slot_id = slot.id
        r.ImGui_OpenPopup(ctx, "seq_midi_assign_popup")
      end
    end
    if r.ImGui_IsItemClicked(ctx, 1) then
      seq_midi_ensure_jsfx()
      if state.seq_midi_learn_slot_id == slot.id then
        state.seq_midi_learn_slot_id = nil
      else
        state.seq_midi_learn_slot_id = slot.id
        state.seq_midi_learn_range = false
      end
    end
    if r.ImGui_IsItemHovered(ctx) then
      hovered = true
      if r.ImGui_SetTooltip then
        seq_normalize_slot_midi(slot)
        local lo, hi = slot.midi_lo, slot.midi_hi
        local range = (lo == hi)
            and (seq_midi_note_name(lo) .. "  (" .. tostring(lo) .. ")")
            or (seq_midi_note_name(lo) .. "–" .. seq_midi_note_name(hi)
                .. "  (" .. tostring(lo) .. "–" .. tostring(hi) .. ")")
        r.ImGui_SetTooltip(ctx, "MIDI " .. range
          .. "\nClick to assign notes  ·  Right-click: learn  ·  Alt-click: GM default")
      end
    end
  end

  local mute = layout.mute
  if mute and mute.w > 0 then
    if seq_ms_button("##seq_mute_" .. slot.id, dl, mute.x, mute.y, mute.w, "M", slot.mute, 0xE05050FF) then
      slot.mute = not slot.mute
      changed_mix = true
    end
    mark_hover()
  end
  local solo = layout.solo
  if solo and solo.w > 0 then
    if seq_ms_button("##seq_solo_" .. slot.id, dl, solo.x, solo.y, solo.w, "S", slot.solo, 0xE8A020FF) then
      slot.solo = not slot.solo
      changed_mix = true
    end
    mark_hover()
  end
  local overlap = layout.overlap
  if overlap and overlap.w > 0 then
    if seq_ms_button("##seq_overlap_" .. slot.id, dl, overlap.x, overlap.y, overlap.w, "O", slot.overlap, 0x40C8C8FF) then
      slot.overlap = not slot.overlap
      changed_mix = true
      overlap_changed = true
    end
    if r.ImGui_IsItemHovered(ctx) then
      hovered = true
      if r.ImGui_SetTooltip then
        r.ImGui_SetTooltip(ctx, slot.overlap
          and "Overlap on — hits can overlap the next note"
          or "Overlap off — crop to the next hit")
      end
    end
  end

  local env = layout.env
  if env and env.w > 4 and env.h > 4 then
    local env_live = seq_env_is_active(slot.env) or (state.seq_env_popup_slot_id == slot.id)
    r.ImGui_SetCursorScreenPos(ctx, env.x, env.y)
    local env_clicked = r.ImGui_InvisibleButton(ctx, "##seq_env_preview_" .. tostring(slot.id), env.w, env.h)
    local env_hovered = r.ImGui_IsItemHovered(ctx)
    if env_hovered then
      hovered = true
    end
    seq_draw_env_sparkline(dl, env.x, env.y, env.w, env.h, slot.env, env_live, env_hovered)
    if state.seq_env_popup_slot_id == slot.id then
      state.seq_env_popup_preview_rect = {
        x = env.x, y = env.y, w = env.w, h = env.h, x1 = env.x1, y1 = env.y1,
      }
    end
    if env_clicked then
      if is_alt_down() then
        local label = begin_seq_undo("Reset sequencer envelope")
        slot.env = seq_default_track_env()
        seq_normalize_slot_mix(slot)
        seq_on_slot_mix_changed(slot, { resync = true })
        end_seq_undo(label)
      else
        if state.seq_env_popup_slot_id == slot.id then
          state.seq_env_popup_slot_id = nil
          state.seq_env_popup_just_opened = nil
          state.seq_env_popup_preview_rect = nil
          if seq_env_view_reset then seq_env_view_reset() end
        else
          state.seq_env_popup_slot_id = slot.id
          state.seq_env_popup_just_opened = true
          state.seq_env_popup_preview_rect = {
            x = env.x, y = env.y, w = env.w, h = env.h, x1 = env.x1, y1 = env.y1,
          }
        end
      end
    end
  end

  local _, cand_hovered = render_seq_track_sample_candidates(dl, slot, layout)
  if cand_hovered then
    hovered = true
  end

  return changed_mix, overlap_changed, hovered
end

function seq_midi_draw_keyboard(dl, x, y, w, h, slot, octave)
  octave = math.max(-2, math.min(8, math.floor(tonumber(octave) or 1)))
  local start_note = (octave + 2) * 12
  if start_note < 0 then start_note = 0 end
  local n_keys = 24
  local is_black = {
    [1] = true, [3] = true, [6] = true, [8] = true, [10] = true,
  }
  local whites = 0
  for i = 0, n_keys - 1 do
    if not is_black[i % 12] then whites = whites + 1 end
  end
  local ww = w / math.max(1, whites)
  local bh = h * 0.58
  local bw = ww * 0.62
  seq_normalize_slot_midi(slot)
  local lo, hi = slot.midi_lo, slot.midi_hi
  local changed = false
  local hovered_note = nil

  local function in_range(n)
    return n >= lo and n <= hi
  end

  local function paint_key(note, kx0, ky0, kx1, ky1, black)
    if note < 0 or note > 127 then return end
    r.ImGui_SetCursorScreenPos(ctx, kx0, ky0)
    r.ImGui_InvisibleButton(ctx, "##seq_midi_key_" .. note, kx1 - kx0, ky1 - ky0)
    local hovered = r.ImGui_IsItemHovered(ctx)
    local pressed = r.ImGui_IsItemActive(ctx)
    if hovered then hovered_note = note end
    local selected = in_range(note)
    local fill
    if black then
      fill = selected and 0x1EFF5EFF or (hovered and 0x3A4A40FF or 0x121816FF)
    else
      fill = selected and 0x174A24FF or (hovered and 0xE8EEEAFF or 0xD8DED8FF)
    end
    local edge = selected and UI_THEME.accent or (black and 0x000000FF or 0x2A342EFF)
    r.ImGui_DrawList_AddRectFilled(dl, kx0, ky0, kx1, ky1, fill, 2.0)
    r.ImGui_DrawList_AddRect(dl, kx0, ky0, kx1, ky1, edge, 2.0, 0, 1.0)
    if r.ImGui_IsItemClicked(ctx, 0) then
      local shift = false
      if r.ImGui_IsKeyDown then
        local lshift = r.ImGui_Key_LeftShift and r.ImGui_IsKeyDown(ctx, r.ImGui_Key_LeftShift())
        local rshift = r.ImGui_Key_RightShift and r.ImGui_IsKeyDown(ctx, r.ImGui_Key_RightShift())
        shift = lshift or rshift
      end
      seq_midi_set_note(slot, note, shift)
      seq_midi_trigger_slot(slot, 110)
      changed = true
    end
    if pressed and state.seq_midi_key_drag and state.seq_midi_key_drag.origin then
      local a = state.seq_midi_key_drag.origin
      if note ~= a then
        seq_midi_set_range(slot, a, note)
        changed = true
      end
    elseif r.ImGui_IsItemActivated and r.ImGui_IsItemActivated(ctx) then
      state.seq_midi_key_drag = { origin = note }
    end
  end

  local wx = x
  for i = 0, n_keys - 1 do
    local pc = i % 12
    if not is_black[pc] then
      paint_key(start_note + i, wx, y, wx + ww - 1.0, y + h, false)
      wx = wx + ww
    end
  end
  wx = x
  for i = 0, n_keys - 1 do
    local pc = i % 12
    if not is_black[pc] then
      if is_black[(i + 1) % 12] then
        local bx0 = wx + ww - bw * 0.5
        paint_key(start_note + i + 1, bx0, y, bx0 + bw, y + bh, true)
      end
      wx = wx + ww
    end
  end

  if r.ImGui_IsMouseReleased and r.ImGui_IsMouseReleased(ctx, 0) then
    state.seq_midi_key_drag = nil
  end
  return changed, hovered_note
end

function render_seq_midi_assign_popup()
  local flags = 0
  if r.ImGui_WindowFlags_NoTitleBar then flags = flags | r.ImGui_WindowFlags_NoTitleBar() end
  if r.ImGui_WindowFlags_NoResize then flags = flags | r.ImGui_WindowFlags_NoResize() end
  if r.ImGui_WindowFlags_NoScrollbar then flags = flags | r.ImGui_WindowFlags_NoScrollbar() end
  if r.ImGui_WindowFlags_AlwaysAutoResize then flags = flags | r.ImGui_WindowFlags_AlwaysAutoResize() end

  local style_colors, style_vars = 0, 0
  if r.ImGui_Col_PopupBg then
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_PopupBg(), UI_THEME.popup_bg)
    style_colors = style_colors + 1
  end
  if r.ImGui_Col_Border then
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Border(), UI_THEME.border)
    style_colors = style_colors + 1
  end
  if r.ImGui_StyleVar_WindowPadding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), 10, 10)
    style_vars = style_vars + 1
  end
  local function pop_style()
    if style_vars > 0 then r.ImGui_PopStyleVar(ctx, style_vars) end
    if style_colors > 0 then r.ImGui_PopStyleColor(ctx, style_colors) end
  end

  local open = r.ImGui_BeginPopup(ctx, "seq_midi_assign_popup", flags)
  if not open then
    pop_style()
    if not r.ImGui_IsPopupOpen or not r.ImGui_IsPopupOpen(ctx, "seq_midi_assign_popup") then
      if state.seq_midi_popup_slot_id then
        local dirty = state.seq_midi_assign_dirty == true
        state.seq_midi_popup_slot_id = nil
        state.seq_midi_key_drag = nil
        state.seq_midi_assign_dirty = nil
        return dirty
      end
    end
    return false
  end

  local slot = seq_find_track_slot_by_id(state.seq_midi_popup_slot_id)
  if not slot then
    r.ImGui_CloseCurrentPopup(ctx)
    r.ImGui_EndPopup(ctx)
    pop_style()
    state.seq_midi_popup_slot_id = nil
    return false
  end
  seq_midi_ensure_jsfx()
  seq_normalize_slot_midi(slot)

  local changed = false
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local name = slot.name or ("Track " .. tostring(slot.id))
  r.ImGui_TextColored(ctx, UI_THEME.text, name)
  r.ImGui_SameLine(ctx)
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "MIDI trigger")

  local learning = state.seq_midi_learn_slot_id == slot.id
  if draw_ui_button("seq_midi_learn", learning and "Listening…" or "Learn", 88, 22, {
    style = learning and "success" or "default",
    compact = true,
  }) then
    if learning then
      state.seq_midi_learn_slot_id = nil
    else
      state.seq_midi_learn_slot_id = slot.id
      state.seq_midi_learn_range = false
    end
  end
  r.ImGui_SameLine(ctx)
  if draw_ui_button("seq_midi_reset", "GM", 36, 22, { compact = true }) then
    local def = seq_midi_default_note_for_slot(slot)
    seq_midi_set_range(slot, def, def)
    changed = true
  end
  if r.ImGui_IsItemHovered(ctx) and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, "Reset to General MIDI default for this drum")
  end

  r.ImGui_Dummy(ctx, 1, 4)
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "Notes in this range trigger the sample")

  local lo, hi = slot.midi_lo, slot.midi_hi
  local lo_changed, lo_val, lo_hot = seq_rect_drag_control(
    "##seq_midi_lo", dl, select(1, r.ImGui_GetCursorScreenPos(ctx)), select(2, r.ImGui_GetCursorScreenPos(ctx)),
    120, 18, lo, 0, 127,
    {
      horizontal = true,
      fill_color = 0x1EFF5EFF,
      format_value = function(v)
        v = seq_midi_clamp_note(v)
        return "Lo " .. seq_midi_note_name(v) .. "  " .. tostring(v)
      end,
    }
  )
  r.ImGui_Dummy(ctx, 120, 18)
  r.ImGui_SameLine(ctx)
  local hi_x, hi_y = r.ImGui_GetCursorScreenPos(ctx)
  local hi_changed, hi_val, hi_hot = seq_rect_drag_control(
    "##seq_midi_hi", dl, hi_x, hi_y, 120, 18, hi, 0, 127,
    {
      horizontal = true,
      fill_color = 0x62FF8AFF,
      format_value = function(v)
        v = seq_midi_clamp_note(v)
        return "Hi " .. seq_midi_note_name(v) .. "  " .. tostring(v)
      end,
    }
  )
  r.ImGui_Dummy(ctx, 120, 18)
  if lo_changed then
    seq_midi_set_range(slot, lo_val, math.max(lo_val, slot.midi_hi))
    changed = true
  end
  if hi_changed then
    seq_midi_set_range(slot, math.min(slot.midi_lo, hi_val), hi_val)
    changed = true
  end

  r.ImGui_Dummy(ctx, 1, 6)
  local oct = state.seq_midi_kb_octave
  if not oct then
    oct = math.floor((slot.midi_lo or 36) / 12) - 2
    state.seq_midi_kb_octave = oct
  end
  if draw_ui_button("seq_midi_oct_l", "<", 22, 22, { compact = true }) then
    state.seq_midi_kb_octave = math.max(-2, oct - 1)
  end
  r.ImGui_SameLine(ctx)
  r.ImGui_TextColored(ctx, UI_THEME.text, "C" .. tostring(state.seq_midi_kb_octave))
  r.ImGui_SameLine(ctx)
  if draw_ui_button("seq_midi_oct_r", ">", 22, 22, { compact = true }) then
    state.seq_midi_kb_octave = math.min(7, oct + 1)
  end
  r.ImGui_SameLine(ctx)
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "Shift-click / drag for a range")

  local kb_x, kb_y = r.ImGui_GetCursorScreenPos(ctx)
  local kb_w, kb_h = 248.0, 56.0
  local kb_changed = seq_midi_draw_keyboard(dl, kb_x, kb_y, kb_w, kb_h, slot, state.seq_midi_kb_octave)
  r.ImGui_Dummy(ctx, kb_w, kb_h)
  if kb_changed then changed = true end
  if changed then
    state.seq_midi_assign_dirty = true
  end

  r.ImGui_EndPopup(ctx)
  pop_style()
  return false
end

-- Transparent popup containing only the envelope graph (with sample waveform).
-- Returns true when the envelope was changed this frame.
function seq_env_popup_anchor_pos(graph_w, graph_h)
  -- Sit next to the envelope sparkline that opened the editor.
  local gap = 6.0
  local preview = state.seq_env_popup_preview_rect
  local map = state.seq_map_rect
  local px, py = nil, nil
  if preview and preview.x1 then
    px = preview.x1 + gap
    py = (preview.y or 0) + (preview.h or 0) * 0.5 - graph_h * 0.5
  elseif map and map.timeline_x then
    px = map.timeline_x + gap
    py = (map.header_y1 or map.y or 0) + gap
  else
    local rect = state.main_window_rect
    if rect and rect.w then
      px = rect.x + gap
      py = (rect.y or 0) + 80.0
    end
  end
  if not px or not py then
    return nil, nil
  end

  if map then
    local min_x = (map.x or px) + gap
    local max_x = ((map.x or px) + (map.w or graph_w) ) - graph_w - gap
    if preview and preview.x and px > max_x then
      px = preview.x - graph_w - gap
    end
    if max_x >= min_x then
      px = math.max(min_x, math.min(px, max_x))
    end
    local min_y = (map.y or py) + gap
    local map_bottom = (map.y or py) + (map.h or graph_h)
    local max_y = map_bottom - graph_h - gap
    if max_y >= min_y then
      py = math.max(min_y, math.min(py, max_y))
    else
      py = min_y
    end
  end
  return px, py
end

function seq_close_env_editor_popup()
  state.seq_env_popup_slot_id = nil
  state.seq_env_popup_just_opened = nil
  state.seq_env_popup_preview_rect = nil
  state.seq_env_graph_drag = nil
  if seq_env_view_reset then
    seq_env_view_reset()
  end
end

function render_seq_env_editor_popup()
  if not state.seq_env_popup_slot_id then
    return false
  end

  local slot = seq_find_slot_by_id and seq_find_slot_by_id(state.seq_env_popup_slot_id)
  if not slot then
    for _, s in ipairs(state.seq_tracks or {}) do
      if s.id == state.seq_env_popup_slot_id then
        slot = s
        break
      end
    end
  end
  if not slot then
    seq_close_env_editor_popup()
    return false
  end

  local graph_w, graph_h = 380.0, 168.0
  local px, py = seq_env_popup_anchor_pos(graph_w, graph_h)
  if not px or not py then
    return false
  end

  -- Same overlay pattern as the extras flyout: top-level window so the tracks
  -- child cannot steal hits or reinterpret the screen-space anchor.
  local cond = r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 1
  if not cond or cond == 0 then cond = 1 end
  r.ImGui_SetNextWindowPos(ctx, px, py, cond)
  if r.ImGui_SetNextWindowSize then
    r.ImGui_SetNextWindowSize(ctx, graph_w, graph_h, cond)
  end
  if r.ImGui_SetNextWindowBgAlpha then
    r.ImGui_SetNextWindowBgAlpha(ctx, 0.0)
  end

  local style_colors = 0
  local style_vars = 0
  if r.ImGui_Col_WindowBg then
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_WindowBg(), 0x00000000)
    style_colors = style_colors + 1
  end
  if r.ImGui_Col_Border then
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Border(), 0x00000000)
    style_colors = style_colors + 1
  end
  if r.ImGui_StyleVar_WindowPadding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), 0, 0)
    style_vars = style_vars + 1
  end
  if r.ImGui_StyleVar_WindowBorderSize then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowBorderSize(), 0)
    style_vars = style_vars + 1
  end

  local flags = 0
  if r.ImGui_WindowFlags_NoTitleBar then flags = flags | r.ImGui_WindowFlags_NoTitleBar() end
  if r.ImGui_WindowFlags_NoResize then flags = flags | r.ImGui_WindowFlags_NoResize() end
  if r.ImGui_WindowFlags_NoMove then flags = flags | r.ImGui_WindowFlags_NoMove() end
  if r.ImGui_WindowFlags_NoCollapse then flags = flags | r.ImGui_WindowFlags_NoCollapse() end
  if r.ImGui_WindowFlags_NoScrollbar then flags = flags | r.ImGui_WindowFlags_NoScrollbar() end
  if r.ImGui_WindowFlags_NoScrollWithMouse then flags = flags | r.ImGui_WindowFlags_NoScrollWithMouse() end
  if r.ImGui_WindowFlags_NoSavedSettings then flags = flags | r.ImGui_WindowFlags_NoSavedSettings() end
  if r.ImGui_WindowFlags_NoFocusOnAppearing then flags = flags | r.ImGui_WindowFlags_NoFocusOnAppearing() end
  if r.ImGui_WindowFlags_NoNav then flags = flags | r.ImGui_WindowFlags_NoNav() end
  if r.ImGui_WindowFlags_NoBackground then flags = flags | r.ImGui_WindowFlags_NoBackground() end

  local visible = r.ImGui_Begin(ctx, "##seq_env_editor", true, flags)
  local popup_dl = (r.ImGui_GetWindowDrawList and r.ImGui_GetWindowDrawList(ctx))
    or (r.ImGui_GetForegroundDrawList and r.ImGui_GetForegroundDrawList(ctx))
  local gx, gy = px, py
  if r.ImGui_GetCursorScreenPos then
    gx, gy = r.ImGui_GetCursorScreenPos(ctx)
  end

  local changed = false
  if visible then
    seq_normalize_slot_mix(slot)
    local env_hot, tip
    changed, env_hot, tip = seq_render_env_graph_editor(
      popup_dl, slot, gx, gy, graph_w, graph_h, { show_waveform = true }
    )
    if (env_hot or tip) and tip and r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, tip)
    end
    r.ImGui_Dummy(ctx, graph_w, graph_h)

    local dragging = state.seq_env_graph_drag and state.seq_env_graph_drag.slot_id
    local win_hovered = r.ImGui_IsWindowHovered and r.ImGui_IsWindowHovered(ctx)
    local escape = r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
      and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false)
    local clicked_outside = r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 0)
      and not win_hovered and not env_hot
    if state.seq_env_popup_just_opened then
      state.seq_env_popup_just_opened = nil
    elseif escape or (clicked_outside and not dragging) then
      seq_close_env_editor_popup()
    end
  end

  r.ImGui_End(ctx)
  if style_vars > 0 then r.ImGui_PopStyleVar(ctx, style_vars) end
  if style_colors > 0 then r.ImGui_PopStyleColor(ctx, style_colors) end
  return changed and true or false
end

function seq_render_env_editor_host()
  if not render_seq_env_editor_popup() then
    return false
  end
  begin_seq_undo("Edit sequencer envelope")
  seq_undo_commit_on_release = true
  local popup_slot = seq_find_slot_by_id and seq_find_slot_by_id(state.seq_env_popup_slot_id)
  if not popup_slot then
    for _, s in ipairs(state.seq_tracks or {}) do
      if s.id == state.seq_env_popup_slot_id then
        popup_slot = s
        break
      end
    end
  end
  if popup_slot then
    seq_normalize_slot_mix(popup_slot)
  end
  if seq_schedule_ingest_save then
    seq_schedule_ingest_save()
  end
  if not (state.seq_env_graph_drag and state.seq_env_graph_drag.slot_id) then
    if popup_slot then
      sync_seq_slot_all_regions(popup_slot, { force_rebuild = true })
    else
      seq_resync_all_regions()
    end
    state.seq_env_pending_resync = nil
    state.seq_env_pending_resync_slot_id = nil
  else
    state.seq_env_pending_resync = true
    if popup_slot then
      state.seq_env_pending_resync_slot_id = popup_slot.id
    end
  end
  return true
end

-- ===== Drum layering ====================================================
-- Each sequencer track can blend three samples for the transient and three
-- for the sustain. Blend weights are barycentric coordinates in a triangle.

function seq_layering_button(id, dl, x, y, size, active)
  r.ImGui_SetCursorScreenPos(ctx, x, y)
  local clicked = r.ImGui_InvisibleButton(ctx, id, size, size)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local bg = active and UI_THEME.accent_fill or UI_THEME.surface
  local edge = hovered and 0xFFFFFFFF or (active and UI_THEME.accent or UI_THEME.border)
  local col = active and 0xC8FF9AFF or 0xD0D8E8FF
  r.ImGui_DrawList_AddRectFilled(dl, x, y, x + size, y + size, bg, 3.0)
  r.ImGui_DrawList_AddRect(dl, x, y, x + size, y + size, edge, 3.0, 0, 1.0)
  local pad = size * 0.22
  local ax = x + size * 0.5
  local ay = y + pad
  local bx = x + pad
  local by = y + size - pad
  local cx_pt = x + size - pad
  local cy_pt = by
  r.ImGui_DrawList_AddTriangleFilled(dl, ax, ay, bx, by, cx_pt, cy_pt, col)
  r.ImGui_DrawList_AddLine(dl, ax, ay, bx, by, edge, 1.0)
  r.ImGui_DrawList_AddLine(dl, bx, by, cx_pt, cy_pt, edge, 1.0)
  r.ImGui_DrawList_AddLine(dl, cx_pt, cy_pt, ax, ay, edge, 1.0)
  return clicked
end

function seq_layer_vert_vol(vert)
  local v = tonumber(vert and vert.vol)
  if v == nil then return 1.0 end
  if v < 0.0 then return 0.0 end
  local max_v = SEQ_LAYER_VOL_MAX or 4.0
  if v > max_v then return max_v end
  return v
end

function seq_layer_default_side()
  return {
    verts = {
      { path = nil, name = nil, locked = true, vol = 1.0 },
      { path = nil, name = nil, locked = false, vol = 1.0 },
      { path = nil, name = nil, locked = false, vol = 1.0 },
    },
    blend = { 1.0, 0.0, 0.0 },
  }
end

function seq_layer_normalize_side(side)
  if type(side) ~= "table" then
    return seq_layer_default_side()
  end
  if type(side.verts) ~= "table" then
    side.verts = seq_layer_default_side().verts
  end
  for i = 1, 3 do
    local v = side.verts[i]
    if type(v) ~= "table" then
      side.verts[i] = { path = nil, name = nil, locked = (i == 1), vol = 1.0 }
    else
      v.locked = v.locked == true
      v.vol = seq_layer_vert_vol(v)
      if v.path == "" then v.path = nil end
    end
  end
  local b = side.blend
  if type(b) ~= "table" then
    side.blend = { 1.0, 0.0, 0.0 }
  else
    local a = tonumber(b[1]) or 0
    local bb = tonumber(b[2]) or 0
    local c = tonumber(b[3]) or 0
    a, bb, c = seq_layer_clamp_bary(a, bb, c)
    side.blend = { a, bb, c }
  end
  return side
end

function seq_normalize_slot_layers(slot)
  if not slot then return end
  if type(slot.layers) ~= "table" then
    slot.layers = {}
  end
  slot.layers.transient = seq_layer_normalize_side(slot.layers.transient)
  slot.layers.sustain = seq_layer_normalize_side(slot.layers.sustain)
  slot.layers.linked = slot.layers.linked == true
  if slot.layers.output ~= "original" and slot.layers.output ~= "layered" then
    slot.layers.output = nil
  end
  local bias = tonumber(slot.layers.bias)
  if bias == nil then
    slot.layers.bias = 0.0
  else
    if bias < -1.0 then bias = -1.0 elseif bias > 1.0 then bias = 1.0 end
    slot.layers.bias = bias
  end
  if slot.layers.top_locked_inited ~= true then
    slot.layers.transient.verts[1].locked = true
    slot.layers.sustain.verts[1].locked = true
    slot.layers.top_locked_inited = true
  end
end

function seq_layering_copy_side(dst, src)
  if not dst or not src then return end
  if type(dst.verts) ~= "table" then
    dst.verts = seq_layer_default_side().verts
  end
  local sb = src.blend or { 1.0, 0.0, 0.0 }
  dst.blend = { sb[1] or 1.0, sb[2] or 0.0, sb[3] or 0.0 }
  for i = 1, 3 do
    local sv = src.verts and src.verts[i]
    if type(dst.verts[i]) ~= "table" then
      dst.verts[i] = { path = nil, name = nil, locked = (i == 1), vol = 1.0 }
    end
    if sv then
      dst.verts[i].path = sv.path
      dst.verts[i].name = sv.name
      dst.verts[i].locked = sv.locked == true
      dst.verts[i].vol = seq_layer_vert_vol(sv)
    end
  end
end

function seq_layering_copy_to_slot(dst, src)
  if not dst or not src then return end
  seq_normalize_slot_layers(src)
  seq_normalize_slot_layers(dst)
  dst.layers.linked = src.layers.linked == true
  dst.layers.output = src.layers.output
  dst.layers.bias = src.layers.bias or 0.0
  dst.layers.top_locked_inited = true
  seq_layering_copy_side(dst.layers.transient, src.layers.transient)
  seq_layering_copy_side(dst.layers.sustain, src.layers.sustain)
end

function seq_layering_sync_linked(slot, from_key)
  if not slot then return end
  seq_normalize_slot_layers(slot)
  if not slot.layers.linked then return end
  from_key = from_key or "transient"
  local src = slot.layers[from_key]
  local dst = slot.layers[from_key == "transient" and "sustain" or "transient"]
  seq_layering_copy_side(dst, src)
end

function seq_layering_set_linked(slot, linked)
  if not slot then return end
  seq_normalize_slot_layers(slot)
  linked = linked == true
  if slot.layers.linked == linked then return end
  slot.layers.linked = linked
  if linked then
    seq_layering_sync_linked(slot, "transient")
  end
end

function seq_layering_follow_track_sample(slot, old_path, sample)
  if not slot or not sample or not sample.path then
    return
  end
  seq_normalize_slot_layers(slot)
  local old_norm = old_path and normalize_path(old_path) or nil
  local new_path = sample.path
  local new_name = sample.name or basename(new_path)
  for _, side_key in ipairs({ "transient", "sustain" }) do
    local side = slot.layers[side_key]
    local v = side and side.verts and side.verts[1]
    if type(v) == "table" then
      local vp = v.path and normalize_path(v.path) or nil
      -- Locked top is the track original and must follow a swap.
      -- Also replace empty verts or verts that still point at the old sample.
      if v.locked or not vp or (old_norm and vp == old_norm) then
        v.path = new_path
        v.name = new_name
        v.vol = 1.0
        if v.locked or not vp then
          v.locked = true
        end
      end
    end
  end
  if slot.layers.linked then
    seq_layering_sync_linked(slot, "transient")
  end
end

function seq_layering_seed_from_track(slot)
  if not slot then return end
  seq_normalize_slot_layers(slot)
  if not slot.sample_path then return end
  local sides = { slot.layers.transient, slot.layers.sustain }
  for i = 1, 2 do
    local v = sides[i] and sides[i].verts and sides[i].verts[1]
    if type(v) == "table" and not v.path then
      v.path = slot.sample_path
      v.name = slot.sample_name or basename(slot.sample_path)
      v.locked = true
    end
  end
  if slot.layers.linked then
    seq_layering_sync_linked(slot, "transient")
  end
end

function seq_layering_set_vert(slot, side_key, idx, sample)
  if not slot or not sample or not sample.path then return end
  seq_normalize_slot_layers(slot)
  local side = slot.layers[side_key]
  if not side or idx < 1 or idx > 3 then return end
  local v = side.verts[idx]
  if v.locked then
    if idx == 1 then
      assign_sample_to_seq_track(slot, sample, true)
    end
    return
  end
  v.path = sample.path
  v.name = sample.name or basename(sample.path)
  v.vol = 1.0
  seq_layering_ensure_audible(side, idx)
  seq_layering_sync_linked(slot, side_key)
end

function seq_layer_clamp_bary(a, b, c)
  a = math.max(0.0, a or 0.0)
  b = math.max(0.0, b or 0.0)
  c = math.max(0.0, c or 0.0)
  local s = a + b + c
  if s < 1e-9 then
    return 1.0, 0.0, 0.0
  end
  return a / s, b / s, c / s
end

function seq_layer_barycentric_raw(px, py, ax, ay, bx, by, cx, cy)
  local v0x, v0y = cx - ax, cy - ay
  local v1x, v1y = bx - ax, by - ay
  local v2x, v2y = px - ax, py - ay
  local dot00 = v0x * v0x + v0y * v0y
  local dot01 = v0x * v1x + v0y * v1y
  local dot02 = v0x * v2x + v0y * v2y
  local dot11 = v1x * v1x + v1y * v1y
  local dot12 = v1x * v2x + v1y * v2y
  local denom = dot00 * dot11 - dot01 * dot01
  if math.abs(denom) < 1e-12 then
    return 1.0, 0.0, 0.0
  end
  local u = (dot11 * dot02 - dot01 * dot12) / denom
  local v = (dot00 * dot12 - dot01 * dot02) / denom
  local w = 1.0 - u - v
  return w, v, u
end

function seq_layer_barycentric(px, py, ax, ay, bx, by, cx, cy)
  local w, v, u = seq_layer_barycentric_raw(px, py, ax, ay, bx, by, cx, cy)
  return seq_layer_clamp_bary(w, v, u)
end

function seq_layer_point_from_bary(blend, ax, ay, bx, by, cx, cy)
  local a = blend[1] or 1.0
  local b = blend[2] or 0.0
  local c = blend[3] or 0.0
  return ax * a + bx * b + cx * c, ay * a + by * b + cy * c
end

function seq_layering_collect_pool(slot, side, vert_idx)
  local pool = {}
  local used = {}
  seq_normalize_slot_layers(slot)
  local verts = slot.layers[side].verts
  for i = 1, 3 do
    if verts[i] and verts[i].path then
      used[verts[i].path] = true
    end
  end
  if slot.sample_path then
    used[slot.sample_path] = true
  end
  local origin = (verts[vert_idx] and verts[vert_idx].path and find_sample_by_path(verts[vert_idx].path))
      or find_sample_by_path(slot.sample_path)
  local role = seq_vary_role_for_origin(slot, origin)

  local function consider(s, drums_only)
    if not s or not s.path or used[s.path] then
      return
    end
    if sample_scan_folder_unavailable(s) then
      return
    end
    if drums_only and not sample_is_drum_oneshot(s) then
      return
    end
    if role and not seq_sample_matches_vary_role(s, role) then
      return
    end
    pool[#pool + 1] = s
    used[s.path] = true
  end

  local ranked = {}
  if origin and collect_map_samples_by_distance then
    ranked = collect_map_samples_by_distance(origin, role)
  end
  for i = 1, #ranked do
    consider(ranked[i].sample, true)
    if #pool >= 48 then return pool end
  end
  if #pool < 8 then
    for i = 1, #ranked do
      consider(ranked[i].sample, false)
      if #pool >= 48 then return pool end
    end
  end
  if #pool < 4 then
    for _, s in ipairs(state.samples) do
      consider(s, true)
      if #pool >= 48 then return pool end
    end
  end
  if #pool < 2 then
    for _, s in ipairs(state.samples) do
      consider(s, false)
      if #pool >= 48 then return pool end
    end
  end
  return pool
end

function seq_layering_ensure_audible(side, idx)
  if not side or not side.blend then return end
  local b = side.blend
  if (b[idx] or 0) >= 0.08 then
    return
  end
  local pull = 0.34
  b[1] = (b[1] or 0) * (1.0 - pull)
  b[2] = (b[2] or 0) * (1.0 - pull)
  b[3] = (b[3] or 0) * (1.0 - pull)
  b[idx] = (b[idx] or 0) + pull
  local a, bb, c = seq_layer_clamp_bary(b[1], b[2], b[3])
  side.blend = { a, bb, c }
end

function seq_layering_repair_note_volumes(slot)
  if not slot or not slot.id then
    return
  end
  for _, pattern in pairs(state.seq_patterns or {}) do
    if type(pattern) == "table" then
      local notes = get_track_note_table(pattern, slot.id, false)
      if notes then
        for _, note in pairs(notes) do
          -- Older layering wrote item*take*blend into note.volume (~0.08 and down).
          if type(note) == "table" and type(note.volume) == "number"
             and note.volume > 0.0 and note.volume < 0.1 then
            note.volume = 1.0
          end
        end
      end
    end
  end
end

function seq_layering_sync_arrange(slot, opts)
  if not slot or not slot.id then
    return
  end
  opts = opts or {}
  seq_layering_repair_note_volumes(slot)
  if r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  for _, region in ipairs(state.seq_regions or {}) do
    sync_seq_region_track(region, slot, {
      skip_arrange = true,
      force_rebuild = opts.force_rebuild,
    })
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  if r.UpdateArrange then
    r.UpdateArrange()
  end
end

function seq_layering_get_bias(slot)
  if not slot then return 0.0 end
  seq_normalize_slot_layers(slot)
  return slot.layers.bias or 0.0
end

function seq_layering_apply_bias(base_trans, onset, dur, bias)
  onset = math.max(0.0, onset or 0.0)
  dur = math.max(onset + 0.02, dur or 0.2)
  local base_len = math.max(0.004, (base_trans or (onset + 0.02)) - onset)
  local min_len = 0.004
  local max_len = math.min(math.max(0.02, dur - onset - 0.012), math.max(base_len * 4.0, 0.12))
  if max_len < base_len then
    max_len = math.min(math.max(0.02, dur - onset - 0.012), base_len * 2.0)
  end
  bias = tonumber(bias) or 0.0
  if bias < -1.0 then bias = -1.0 elseif bias > 1.0 then bias = 1.0 end
  local len
  if bias <= 0.0 then
    len = min_len + (base_len - min_len) * (bias + 1.0)
  else
    len = base_len + (max_len - base_len) * bias
  end
  return onset + math.max(min_len, len)
end

function seq_layering_piece_times(sample, side_key, slot)
  local dur = seq_sample_source_length_sec(sample and sample.path, sample)
      or (sample and tonumber(sample.duration)) or 0.2
  if dur <= 0.001 then dur = 0.2 end
  local onset = (sample and type(sample.onset) == "number" and sample.onset > 0) and sample.onset or 0.0
  local trans = (sample and type(sample.transient_end) == "number" and sample.transient_end > 0)
      and sample.transient_end or math.min(0.024, dur * 0.18)
  trans = math.max(onset + 0.003, math.min(trans, dur * 0.9))
  if slot then
    trans = seq_layering_apply_bias(trans, onset, dur, seq_layering_get_bias(slot))
    trans = math.max(onset + 0.003, math.min(trans, dur * 0.9))
  end
  if side_key == "transient" then
    return onset, math.max(0.004, trans - onset)
  end
  return trans, math.max(0.012, dur - trans)
end

SEQ_LAYER_XFADE_SEC = 0.008
SEQ_LAYER_VOL_MAX = 4.0

function seq_layering_geometry_active(slot)
  if not slot then
    return false
  end
  seq_normalize_slot_layers(slot)
  local sides = { slot.layers.transient, slot.layers.sustain }
  for s = 1, 2 do
    local side = sides[s]
    if math.abs((side.blend[1] or 1.0) - 1.0) > 0.02 then
      return true
    end
    for i = 2, 3 do
      if (side.blend[i] or 0.0) >= 0.02 and side.verts[i] and side.verts[i].path then
        return true
      end
    end
    local v1 = side.verts[1]
    if v1 and v1.path and slot.sample_path and v1.path ~= slot.sample_path then
      return true
    end
  end
  return false
end

function seq_layering_output(slot)
  if not slot then
    return "original"
  end
  seq_normalize_slot_layers(slot)
  local out = slot.layers.output
  if out == "original" or out == "layered" then
    return out
  end
  return seq_layering_geometry_active(slot) and "layered" or "original"
end

function seq_layering_set_output(slot, kind)
  if not slot or (kind ~= "original" and kind ~= "layered") then
    return false
  end
  seq_normalize_slot_layers(slot)
  if slot.layers.output == kind then
    return false
  end
  slot.layers.output = kind
  state.seq_layering_ab = kind
  seq_layering_sync_arrange(slot, { force_rebuild = true })
  save_config()
  if save_seq_project_state then
    save_seq_project_state()
  end
  return true
end

function seq_layering_is_active(slot)
  return seq_layering_output(slot) == "layered" and seq_layering_geometry_active(slot)
end

function seq_layering_drag_sample(slot)
  if not slot or not slot.sample_path then
    return nil
  end
  local src = find_sample_by_path(slot.sample_path)
  local name = slot.sample_name or (src and src.name) or basename(slot.sample_path)
  return {
    path = slot.sample_path,
    name = name .. " (layered)",
    duration = src and src.duration,
    is_layering_mix = true,
    layering_slot_id = slot.id,
  }
end

function apply_dragged_sample_to_seq_track(slot, sample, persist)
  if not slot or not sample then
    return false
  end
  if sample.is_layering_mix then
    local src = find_seq_track_by_id(sample.layering_slot_id)
    if src and src.id ~= slot.id then
      local base = find_sample_by_path(src.sample_path)
        or { path = src.sample_path, name = src.sample_name }
      assign_sample_to_seq_track(slot, base, persist)
      seq_layering_copy_to_slot(slot, src)
    elseif (not src) and sample.path then
      assign_sample_to_seq_track(slot, find_sample_by_path(sample.path) or sample, persist)
    end
    seq_normalize_slot_layers(slot)
    slot.layers.output = "layered"
    seq_layering_sync_arrange(slot)
    if persist ~= false then
      save_config()
      if save_seq_project_state then
        save_seq_project_state()
      end
    end
    return true
  end
  return seq_assign_sample_for_context(slot, sample, persist)
end

function seq_layering_insert_mix_at_position(sample, time_pos, target_track)
  if not sample or not time_pos then
    return false
  end
  local slot = sample.layering_slot_id and find_seq_track_by_id(sample.layering_slot_id)
  local pieces = slot and seq_layering_build_pieces(slot) or {}
  if #pieces == 0 then
    local fallback = (slot and slot.sample_path and find_sample_by_path(slot.sample_path))
      or find_sample_by_path(sample.path)
      or sample
    local clean = {
      path = fallback.path,
      name = fallback.name,
      duration = fallback.duration,
    }
    return insert_sample_at_position(clean, time_pos, target_track)
  end

  local track = target_track
  if not track then
    track = r.GetSelectedTrack(0, 0)
    if not track then
      local num_tracks = r.CountTracks(0)
      if num_tracks > 0 then
        track = r.GetTrack(0, 0)
      end
    end
  end
  if not track then
    return false
  end

  r.PreventUIRefresh(1)
  local any = false
  for i = 1, #pieces do
    local piece = pieces[i]
    if piece.path and r.file_exists(piece.path) then
      local item = r.AddMediaItemToTrack(track)
      if item then
        local src_sample = piece.sample or find_sample_by_path(piece.path)
        local pdur = (seq_sample_source_length_sec and seq_sample_source_length_sec(piece.path, src_sample))
          or (src_sample and tonumber(src_sample.duration))
          or (sample.duration or 1.0)
        local startoffs = piece.startoffs or 0.0
        local len = piece.length_sec
        if not len or len <= 0 then
          len = math.max(0.001, pdur - startoffs)
        end
        r.SetMediaItemPosition(item, time_pos + (piece.time_offset_sec or 0.0), false)
        r.SetMediaItemLength(item, len, false)
        local take = r.AddTakeToMediaItem(item)
        if take then
          local src = r.PCM_Source_CreateFromFile(piece.path)
          if src then
            r.SetMediaItemTake_Source(take, src)
            set_item_name(item, take, piece.path)
            if startoffs > 0 then
              r.SetMediaItemTakeInfo_Value(take, "D_STARTOFFS", startoffs)
            end
            local gain = (piece.weight or 1.0) * get_sample_gain(src_sample)
            if gain ~= 1.0 then
              r.SetMediaItemTakeInfo_Value(take, "D_VOL", gain)
            end
            seq_item_apply_layer_fades(item, piece.fade_in, piece.fade_out)
            rebuild_peaks_for_item(item)
            any = true
          end
        end
      end
    end
  end
  r.UpdateArrange()
  r.PreventUIRefresh(-1)
  return any
end

function seq_layering_split_sec(slot)
  local sample = slot and find_sample_by_path(slot.sample_path)
  if not sample then
    seq_normalize_slot_layers(slot)
    for i = 1, 3 do
      local v = slot.layers.transient.verts[i]
      if v and v.path then
        sample = find_sample_by_path(v.path)
        if sample then
          break
        end
      end
    end
  end
  local _, tlen = seq_layering_piece_times(sample, "transient", slot)
  return math.max(0.004, tlen or 0.02)
end

function seq_layering_remap_piece_lanes(pieces)
  local used = {}
  for p = 1, #pieces do
    used[pieces[p].lane] = true
  end
  local map = {}
  local n = 0
  for i = 0, 2 do
    if used[i] then
      map[i] = n
      n = n + 1
    end
  end
  for p = 1, #pieces do
    pieces[p].lane = map[pieces[p].lane] or 0
  end
  return pieces
end

function seq_layering_build_pieces(slot)
  seq_normalize_slot_layers(slot)
  if not seq_layering_geometry_active(slot) then
    return {}
  end
  if slot.layers.linked then
    local side = slot.layers.transient
    local pieces = {}
    for i = 1, 3 do
      local v, w = side.verts[i], side.blend[i] or 0.0
      local path = (w >= 0.02 and v and v.path) and normalize_path(v.path) or nil
      if path then
        pieces[#pieces + 1] = {
          path = path,
          sample = find_sample_by_path(path) or { path = path, name = v and v.name },
          weight = w * seq_layer_vert_vol(v),
          lane = i - 1,
          startoffs = 0.0,
          time_offset_sec = 0.0,
          length_sec = nil,
          fade_in = 0.0,
          fade_out = 0.0,
        }
      end
    end
    return seq_layering_remap_piece_lanes(pieces)
  end
  local tside = slot.layers.transient
  local sside = slot.layers.sustain
  local split = seq_layering_split_sec(slot)
  local xf = SEQ_LAYER_XFADE_SEC
  if split < xf * 2.0 then
    xf = math.max(0.002, split * 0.35)
  end
  local pieces = {}
  for i = 1, 3 do
    local tv, tw = tside.verts[i], tside.blend[i] or 0.0
    local sv, sw = sside.verts[i], sside.blend[i] or 0.0
    local tpath = (tw >= 0.02 and tv and tv.path) and normalize_path(tv.path) or nil
    local spath = (sw >= 0.02 and sv and sv.path) and normalize_path(sv.path) or nil
    if tpath and spath and tpath == spath and math.abs(tw - sw) < 0.05 then
      pieces[#pieces + 1] = {
        path = tpath,
        sample = find_sample_by_path(tpath) or { path = tpath, name = tv and tv.name },
        weight = (tw * seq_layer_vert_vol(tv) + sw * seq_layer_vert_vol(sv)) * 0.5,
        lane = i - 1,
        startoffs = 0.0,
        time_offset_sec = 0.0,
        length_sec = nil,
        fade_in = 0.0,
        fade_out = 0.0,
      }
    else
      if tpath then
        local sample = find_sample_by_path(tpath) or { path = tpath, name = tv and tv.name }
        local offs = seq_layering_piece_times(sample, "transient", slot)
        pieces[#pieces + 1] = {
          path = tpath,
          sample = sample,
          weight = tw * seq_layer_vert_vol(tv),
          lane = i - 1,
          startoffs = offs or 0.0,
          time_offset_sec = 0.0,
          length_sec = split + xf,
          fade_in = 0.0,
          fade_out = xf,
        }
      end
      if spath then
        local sample = find_sample_by_path(spath) or { path = spath, name = sv and sv.name }
        local offs, slen = seq_layering_piece_times(sample, "sustain", slot)
        pieces[#pieces + 1] = {
          path = spath,
          sample = sample,
          weight = sw * seq_layer_vert_vol(sv),
          lane = i - 1,
          startoffs = offs or 0.0,
          time_offset_sec = split,
          length_sec = slen,
          fade_in = xf,
          fade_out = 0.0,
        }
      end
    end
  end
  return seq_layering_remap_piece_lanes(pieces)
end

function seq_item_apply_layer_fades(item, fade_in, fade_out)
  if not item then
    return
  end
  fade_in = math.max(0.0, fade_in or 0.0)
  fade_out = math.max(0.0, fade_out or 0.0)
  r.SetMediaItemInfo_Value(item, "D_FADEINLEN", fade_in)
  r.SetMediaItemInfo_Value(item, "D_FADEOUTLEN", fade_out)
  if fade_in > 0.0 then
    pcall(function()
      r.SetMediaItemInfo_Value(item, "C_FADEINSHAPE", 1)
    end)
  end
  if fade_out > 0.0 then
    pcall(function()
      r.SetMediaItemInfo_Value(item, "C_FADEOUTSHAPE", 1)
    end)
  end
  pcall(function()
    r.SetMediaItemInfo_Value(item, "D_FADEINLEN_AUTO", 0)
    r.SetMediaItemInfo_Value(item, "D_FADEOUTLEN_AUTO", 0)
  end)
end

function seq_layering_randomize_vert(slot, side, vert_idx)
  seq_normalize_slot_layers(slot)
  local v = slot.layers[side].verts[vert_idx]
  if not v or v.locked then
    return false
  end
  local pool = seq_layering_collect_pool(slot, side, vert_idx)
  if #pool == 0 then
    log("No other samples available to layer")
    return false
  end
  local pick = pool[math.random(1, #pool)]
  if not pick then
    return false
  end
  v.path = pick.path
  v.name = pick.name or basename(pick.path)
  v.vol = 1.0
  seq_layering_ensure_audible(slot.layers[side], vert_idx)
  seq_layering_sync_linked(slot, side)
  state.seq_layering_ab = nil
  preview_sample(pick)
  return true
end

function seq_layering_randomize_side(slot, side)
  seq_normalize_slot_layers(slot)
  local changed = false
  for i = 1, 3 do
    if seq_layering_randomize_vert(slot, side, i) then
      changed = true
    end
  end
  return changed
end

function seq_layering_draw_lock(dl, x, y, w, h, locked, hovered)
  local col = locked and 0xE8C070FF or (hovered and 0xFFFFFFFF or UI_THEME.text_dim)
  local cx = x + w * 0.5
  local body_y = y + h * 0.48
  local body_h = h * 0.38
  local body_w = w * 0.46
  r.ImGui_DrawList_AddRectFilled(dl, cx - body_w * 0.5, body_y, cx + body_w * 0.5, body_y + body_h, col, 1.5)
  local shackle_r = w * 0.16
  local shackle_y = body_y
  if locked then
    r.ImGui_DrawList_AddCircle(dl, cx, shackle_y, shackle_r, col, 10, 1.4)
  else
    r.ImGui_DrawList_AddCircle(dl, cx + w * 0.08, shackle_y, shackle_r, col, 10, 1.4)
  end
end

function seq_layering_icon_button(id, dl, x, y, w, h, kind, active)
  r.ImGui_SetCursorScreenPos(ctx, x, y)
  local clicked = r.ImGui_InvisibleButton(ctx, id, w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local pressed = r.ImGui_IsItemActive(ctx)
  local bg = active and UI_THEME.accent_fill or (hovered and UI_THEME.surface_hvr or UI_THEME.surface)
  local edge = hovered and UI_THEME.accent_hvr or (active and UI_THEME.accent or UI_THEME.border)
  ui_draw_panel(dl, x, y, x + w, y + h, 6.0, bg, edge, hovered, pressed)
  if kind == "dice" then
    ui_button_draw_icon(dl, "dice5", x + w * 0.5, y + h * 0.5 + (pressed and 1.0 or 0.0), math.min(w, h) * 0.9, hovered and 0xFFFFFFFF or UI_THEME.text)
  else
    seq_layering_draw_lock(dl, x, y + (pressed and 1.0 or 0.0), w, h, active, hovered)
  end
  return clicked, hovered
end

function seq_layering_mix_fingerprint(slot)
  seq_normalize_slot_layers(slot)
  local bits = { tostring(slot.id or 0), slot.layers.linked and "1" or "0" }
  for _, side_key in ipairs({ "transient", "sustain" }) do
    local side = slot.layers[side_key]
    bits[#bits + 1] = string.format("%.3f,%.3f,%.3f", side.blend[1] or 0, side.blend[2] or 0, side.blend[3] or 0)
    for i = 1, 3 do
      local v = side.verts[i]
      bits[#bits + 1] = (v and v.path) or ""
      bits[#bits + 1] = string.format("%.3f", seq_layer_vert_vol(v))
    end
  end
  bits[#bits + 1] = slot.sample_path or ""
  bits[#bits + 1] = string.format("%.3f", slot.layers.bias or 0.0)
  return table.concat(bits, "|")
end

function seq_layering_mix_peaks(slot, width)
  width = math.max(48, math.min(320, math.floor(width or 200)))
  local fp = seq_layering_mix_fingerprint(slot) .. "#" .. tostring(width)
  local cache = seq_layer_mix_wave_cache
  if cache and cache.fp == fp and cache.peaks then
    return cache.peaks, cache.dur
  end
  local pieces = seq_layering_build_pieces(slot)
  local orig = slot.sample_path and find_sample_by_path(slot.sample_path) or nil
  if #pieces == 0 then
    if not orig then
      return nil, nil
    end
    local peaks, dur = seq_env_get_wave_peaks(orig, width)
    seq_layer_mix_wave_cache = { fp = fp, peaks = peaks, dur = dur }
    return peaks, dur
  end
  local dur = 0.0
  local resolved = {}
  for i = 1, #pieces do
    local p = pieces[i]
    local sample = p.sample or find_sample_by_path(p.path)
    local pdur = seq_sample_source_length_sec(p.path, sample)
        or (sample and tonumber(sample.duration)) or 0.2
    local startoffs = p.startoffs or 0.0
    local t_off = p.time_offset_sec or 0.0
    local len = p.length_sec
    if not len or len <= 0 then
      len = math.max(0.01, pdur - startoffs)
    end
    local end_t = t_off + len
    if end_t > dur then dur = end_t end
    resolved[#resolved + 1] = {
      sample = sample,
      startoffs = startoffs,
      t_off = t_off,
      len = len,
      weight = p.weight or 1.0,
      pdur = pdur,
    }
  end
  if dur <= 0.001 then dur = 0.2 end
  local out = {}
  for i = 1, width do out[i] = 0.0 end
  for i = 1, #resolved do
    local rp = resolved[i]
    if rp.sample then
      local peaks, pd = seq_env_get_wave_peaks(rp.sample, width)
      pd = pd or rp.pdur
      if peaks and pd and pd > 0 then
        local n = #peaks
        for b = 1, width do
          local t = ((b - 0.5) / width) * dur
          if t >= rp.t_off and t <= rp.t_off + rp.len then
            local src_t = rp.startoffs + (t - rp.t_off)
            local si = math.floor((src_t / pd) * n) + 1
            if si >= 1 and si <= n then
              out[b] = out[b] + (peaks[si] or 0) * rp.weight
            end
          end
        end
      end
    end
  end
  local max_v = 0.0
  for i = 1, width do
    if out[i] > max_v then max_v = out[i] end
  end
  if max_v > 0.0001 then
    for i = 1, width do out[i] = out[i] / max_v end
  end
  seq_layer_mix_wave_cache = { fp = fp, peaks = out, dur = dur }
  return out, dur
end

function seq_layering_start_mix_voice(v, into)
  if not v or not v.path or v.started then
    return
  end
  local src = r.PCM_Source_CreateFromFile(v.path)
  if not src then
    return
  end
  local vol = (state.preview_volume or 1.0) * (v.volume or 1.0)
  local pos = (v.startoffs or 0.0) + (into or 0.0)
  if r.CF_CreatePreview and r.CF_Preview_SetValue and r.CF_Preview_Play then
    local obj = r.CF_CreatePreview(src)
    if obj then
      r.CF_Preview_SetValue(obj, "D_VOLUME", vol)
      if pos > 0 then
        r.CF_Preview_SetValue(obj, "D_POSITION", pos)
      end
      if r.CF_Preview_Play(obj) then
        v.started = true
        v.obj = obj
        v.src = src
        return
      end
    end
  elseif r.Xen_StartSourcePreview then
    local preview_id = r.Xen_StartSourcePreview(src, vol, false)
    if preview_id and preview_id ~= 0 then
      v.started = true
      v.xen_id = preview_id
      v.src = src
      v.engine_owned = true
      return
    end
  end
  if r.PCM_Source_Destroy then
    pcall(r.PCM_Source_Destroy, src)
  end
end

function seq_layering_stop_mix_voice(v)
  if not v or not v.started then
    return
  end
  if v.obj and r.CF_Preview_Stop then
    pcall(r.CF_Preview_Stop, v.obj)
  elseif v.xen_id and r.Xen_StopSourcePreview then
    pcall(r.Xen_StopSourcePreview, v.xen_id)
  end
  if v.src and not v.engine_owned and r.PCM_Source_Destroy then
    pcall(r.PCM_Source_Destroy, v.src)
  end
  v.obj = nil
  v.xen_id = nil
  v.src = nil
  v.started = false
end

function seq_layering_update_mix_preview()
  local mix = seq_layer_mix_preview
  if not mix then
    return
  end
  local now = r.time_precise()
  local elapsed = now - (mix.t0 or now)
  if elapsed >= (mix.duration or 0) + 0.04 then
    stop_preview()
    return
  end
  for i = 1, #(mix.voices or {}) do
    local v = mix.voices[i]
    if v and not v.started and elapsed >= (v.start_at or 0) - 0.001 then
      seq_layering_start_mix_voice(v, math.max(0.0, elapsed - (v.start_at or 0)))
    end
    if v and v.started and v.stop_at and elapsed >= v.stop_at then
      seq_layering_stop_mix_voice(v)
    end
  end
end

function seq_layering_preview_original(slot, start_time)
  if not slot then return end
  local sample = slot.sample_path and find_sample_by_path(slot.sample_path) or nil
  if not sample then return end
  state.seq_layering_ab = "original"
  preview_sample(sample, start_time)
end

function seq_layering_preview_layered(slot, start_time)
  if not slot then return end
  start_time = math.max(0.0, start_time or 0.0)
  state.seq_layering_ab = "layered"
  local pieces = seq_layering_build_pieces(slot)
  local _, dur = seq_layering_mix_peaks(slot, 200)
  dur = dur or 0.2
  if #pieces == 0 then
    seq_layering_preview_original(slot, start_time)
    state.seq_layering_ab = "layered"
    return
  end
  stop_preview()
  local voices = {}
  for i = 1, #pieces do
    local piece = pieces[i]
    local t_off = piece.time_offset_sec or 0.0
    local len = piece.length_sec
    voices[#voices + 1] = {
      path = piece.path,
      startoffs = piece.startoffs or 0.0,
      volume = piece.weight or 1.0,
      start_at = t_off,
      stop_at = (len and len > 0) and (t_off + len) or nil,
      started = false,
    }
  end
  seq_layer_mix_preview = {
    slot_id = slot.id,
    t0 = r.time_precise() - start_time,
    duration = dur,
    voices = voices,
  }
  preview_sample_obj = {
    path = "layering-mix:" .. tostring(slot.id),
    name = (slot.name or "Track") .. " (layered)",
    duration = dur,
  }
  preview_proc = true
  preview_start_time = seq_layer_mix_preview.t0
  state.preview_position = start_time
  state.preview_paused = false
  seq_layering_update_mix_preview()
end

function seq_layering_ab_playing(slot, kind)
  if not slot then return false end
  if kind == "layered" then
    return seq_layer_mix_preview ~= nil and seq_layer_mix_preview.slot_id == slot.id
  end
  return seq_layer_mix_preview == nil
      and preview_sample_obj
      and slot.sample_path
      and preview_sample_obj.path == slot.sample_path
end

function seq_layering_draw_wave_pane(dl, slot, x, y, w, h, kind, hover_side)
  local selected = state.seq_layering_ab == kind
  local playing = seq_layering_ab_playing(slot, kind)
  local using = seq_layering_output(slot) == kind
  local hovered_btn = false
  r.ImGui_SetCursorScreenPos(ctx, x, y)
  r.ImGui_InvisibleButton(ctx, "##seq_layer_ab_" .. kind .. "_" .. tostring(slot.id), w, h)
  hovered_btn = r.ImGui_IsItemHovered(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)

  local bg = (selected or playing or using) and UI_THEME.accent_fill or (hovered_btn and UI_THEME.surface_hvr or UI_THEME.bg_panel)
  local edge = (selected or playing or using) and UI_THEME.accent or (hovered_btn and UI_THEME.accent_hvr or UI_THEME.border)
  r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, bg, 4.0)
  r.ImGui_DrawList_AddRect(dl, x, y, x + w, y + h, edge, 4.0, 0, (selected or playing or using) and 1.6 or 1.0)

  local sample = slot.sample_path and find_sample_by_path(slot.sample_path) or nil
  local ix, iy, iw, ih = x + 6, y + 16, w - 12, h - 22
  local peaks, dur = nil, nil
  if kind == "layered" then
    peaks, dur = seq_layering_mix_peaks(slot, math.floor(iw))
  elseif sample then
    peaks, dur = seq_env_get_wave_peaks(sample, math.floor(iw))
  end
  if peaks and iw > 4 and ih > 4 then
    seq_draw_env_waveform(dl, ix, iy, iw, ih, peaks, nil, nil, dur)
  elseif not sample then
    r.ImGui_DrawList_AddText(dl, x + 10, y + h * 0.5 - 7, UI_THEME.text_mute, "Assign a sample to this track")
  end

  dur = dur or (sample and tonumber(sample.duration)) or 0
  local label = (kind == "original") and "Original" or "Layered"
  local label_col = (selected or playing or using) and 0xFFFFFFFF or UI_THEME.text
  r.ImGui_DrawList_AddText(dl, x + 8, y + 2, label_col, label)
  if playing then
    ui_button_draw_icon(dl, "play", x + w - 14, y + 10, 14, 0x7CFF4AFF)
  end

  local btn_w, btn_h = 52, 16
  local play_pad = playing and 16 or 0
  local btn_x = x + w - 6 - btn_w - play_pad
  local btn_y = y + 2
  local mx, my = r.ImGui_GetMousePos(ctx)
  mx, my = tonumber(mx) or -1, tonumber(my) or -1
  local over_use = mx >= btn_x and mx <= btn_x + btn_w and my >= btn_y and my <= btn_y + btn_h
  r.ImGui_SetCursorScreenPos(ctx, btn_x, btn_y)
  local use_clicked = draw_ui_button(
    "seq_layer_use_" .. kind .. "_" .. tostring(slot.id),
    using and "USING" or "USE",
    btn_w, btn_h,
    { compact = true, selected = using, style = using and "accent" or "default" }
  )
  local use_hovered = over_use or r.ImGui_IsItemHovered(ctx)
  if use_hovered and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, using
      and "This is the track output"
      or "Use this as the track output")
  end
  if (use_clicked or (over_use and r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 0)))
      and not using then
    seq_layering_set_output(slot, kind)
  end

  if kind == "original" and sample and dur > 0 and not (slot.layers and slot.layers.linked) then
    local onset = (type(sample.onset) == "number" and sample.onset > 0) and sample.onset or 0.0
    local trans = seq_layering_apply_bias(
      (type(sample.transient_end) == "number" and sample.transient_end > 0)
        and sample.transient_end or math.min(0.024, dur * 0.18),
      onset, dur, seq_layering_get_bias(slot)
    )
    local sustain_end = sample_map_duration(sample)
    if sustain_end <= 0 then sustain_end = dur end
    local function t2x(t)
      return ix + (math.max(0.0, math.min(dur, t)) / dur) * iw
    end
    if trans then
      local ox, tx, sx = t2x(onset), t2x(trans), t2x(sustain_end)
      local t_alpha = (hover_side == "transient") and 0xFF6B3C55 or 0xFF6B3C33
      local s_alpha = (hover_side == "sustain") and 0x4A9CFF44 or 0x4A9CFF28
      if tx > ox + 0.5 then
        r.ImGui_DrawList_AddRectFilled(dl, ox, iy, tx, iy + ih, t_alpha, 0)
      end
      if sx > tx + 0.5 then
        r.ImGui_DrawList_AddRectFilled(dl, tx, iy, sx, iy + ih, s_alpha, 0)
      end
      r.ImGui_DrawList_AddLine(dl, tx, iy, tx, iy + ih, 0x7CFF4AFF, 1.6)
    end
  end

  if playing and dur > 0 then
    local pos = get_preview_position() or state.preview_position or 0.0
    local playhead_x = ix + (math.max(0.0, math.min(dur, pos)) / dur) * iw
    r.ImGui_DrawList_AddLine(dl, playhead_x, y + 1, playhead_x, y + h - 1, 0xFFFF88FF, 1.6)
    r.ImGui_DrawList_AddCircleFilled(dl, playhead_x, y + 4, 3.0, 0xFFFF88FF, 10)
  end

  if hovered_btn and not use_hovered and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, kind == "original"
      and "Click to play · Drag to drop original sample"
      or "Click to play · Drag to drop layered mix")
  end
  local drag_sample = nil
  if kind == "original" then
    drag_sample = sample
  elseif slot.sample_path then
    drag_sample = seq_layering_drag_sample(slot)
  end
  if drag_sample and not use_hovered
      and waveform_drag_should_start(hovered_btn) then
    begin_waveform_sample_drag(drag_sample)
  end
  if drag_sample and sample_is_waveform_drag_source(drag_sample) then
    draw_waveform_drag_source_cue(dl, x, y, w, h)
  end
  if clicked and not use_hovered and not state.pending_waveform_drop then
    if kind == "original" then
      seq_layering_preview_original(slot)
    else
      seq_layering_preview_layered(slot, 0)
    end
  end
end

function seq_layering_draw_waveforms(dl, slot, x, y, w, h, hover_side)
  local gap = 6.0
  local pane_h = (h - gap) * 0.5
  seq_layering_draw_wave_pane(dl, slot, x, y, w, pane_h, "original", hover_side)
  seq_layering_draw_wave_pane(dl, slot, x, y + pane_h + gap, w, pane_h, "layered", hover_side)
end

SEQ_LAYER_WAVE_H = 148.0
SEQ_LAYER_WAVE_GAP = 0.0
SEQ_LAYER_LINK_W = 44.0
SEQ_LAYER_PAD_TOP = 36.0
SEQ_LAYER_PAD_BOT = 36.0
SEQ_LAYER_PAD_SIDE = 72.0
SEQ_LAYER_VERT_DROP_R = 24.0

function seq_layering_tri_geom(x, y, w, h)
  local pad_top, pad_bot, pad_side = SEQ_LAYER_PAD_TOP, SEQ_LAYER_PAD_BOT, SEQ_LAYER_PAD_SIDE
  local avail_w = math.max(72.0, w - pad_side * 2.0)
  local avail_h = math.max(72.0, h - pad_top - pad_bot)
  local side = math.min(avail_w, avail_h * 2.0 / math.sqrt(3.0))
  local tri_h = side * (math.sqrt(3.0) * 0.5)
  local ax = x + w * 0.5
  local ay = y + pad_top
  local bx = ax - side * 0.5
  local by = ay + tri_h
  local cx = ax + side * 0.5
  local cy = by
  return ax, ay, bx, by, cx, cy, side, tri_h
end

function seq_layering_ideal_content_h(content_w)
  local col_w = math.max(160.0, (content_w - SEQ_LAYER_LINK_W) * 0.5)
  local avail_w = math.max(72.0, col_w - SEQ_LAYER_PAD_SIDE * 2.0)
  local tri_h = avail_w * (math.sqrt(3.0) * 0.5)
  return SEQ_LAYER_WAVE_H + SEQ_LAYER_WAVE_GAP + SEQ_LAYER_PAD_TOP + tri_h + SEQ_LAYER_PAD_BOT
end

function seq_layering_rounded_tri_points(ax, ay, bx, by, cx, cy, radius)
  local V = { { ax, ay }, { bx, by }, { cx, cy } }
  local pts = {}
  local steps = 7
  for i = 1, 3 do
    local p0 = V[i == 1 and 3 or (i - 1)]
    local p1 = V[i]
    local p2 = V[i == 3 and 1 or (i + 1)]
    local e1x, e1y = p0[1] - p1[1], p0[2] - p1[2]
    local e2x, e2y = p2[1] - p1[1], p2[2] - p1[2]
    local l1 = math.sqrt(e1x * e1x + e1y * e1y)
    local l2 = math.sqrt(e2x * e2x + e2y * e2y)
    if l1 < 1e-4 or l2 < 1e-4 then
      pts[#pts + 1] = { p1[1], p1[2] }
    else
      e1x, e1y = e1x / l1, e1y / l1
      e2x, e2y = e2x / l2, e2y / l2
      local dot = math.max(-1.0, math.min(1.0, e1x * e2x + e1y * e2y))
      local ang = math.acos(dot)
      local d = radius / math.max(0.18, math.tan(ang * 0.5))
      d = math.min(d, l1 * 0.42, l2 * 0.42)
      local a1x, a1y = p1[1] + e1x * d, p1[2] + e1y * d
      local a2x, a2y = p1[1] + e2x * d, p1[2] + e2y * d
      local bisx, bisy = e1x + e2x, e1y + e2y
      local bl = math.sqrt(bisx * bisx + bisy * bisy)
      local sin_h = math.sin(ang * 0.5)
      local clen = (sin_h > 1e-4) and (radius / sin_h) or radius
      local ocx = p1[1] + (bisx / bl) * clen
      local ocy = p1[2] + (bisy / bl) * clen
      local t0 = math.atan2(a1y - ocy, a1x - ocx)
      local t1 = math.atan2(a2y - ocy, a2x - ocx)
      local sweep = t1 - t0
      while sweep > math.pi do sweep = sweep - 2.0 * math.pi end
      while sweep < -math.pi do sweep = sweep + 2.0 * math.pi end
      local mid = t0 + sweep * 0.5
      local mx = ocx + math.cos(mid) * radius
      local my = ocy + math.sin(mid) * radius
      if (mx - p1[1]) * (mx - p1[1]) + (my - p1[2]) * (my - p1[2]) < (radius * 0.55) * (radius * 0.55) then
        if sweep > 0 then sweep = sweep - 2.0 * math.pi else sweep = sweep + 2.0 * math.pi end
      end
      for s = 0, steps do
        local t = t0 + sweep * (s / steps)
        pts[#pts + 1] = { ocx + math.cos(t) * radius, ocy + math.sin(t) * radius }
      end
    end
  end
  return pts
end

function seq_layering_draw_poly(dl, pts, fill, stroke, stroke_w)
  if not pts or #pts < 3 or not dl then return end
  if fill and r.ImGui_DrawList_PathLineTo and r.ImGui_DrawList_PathFillConvex then
    pcall(function()
      if r.ImGui_DrawList_PathClear then r.ImGui_DrawList_PathClear(dl) end
      for i = 1, #pts do
        local p = pts[i]
        if p and p[1] and p[2] then
          r.ImGui_DrawList_PathLineTo(dl, p[1], p[2])
        end
      end
      r.ImGui_DrawList_PathFillConvex(dl, fill)
    end)
  end
  if stroke and stroke_w and stroke_w > 0 then
    local n = #pts
    for i = 1, n do
      local a, b = pts[i], pts[i == n and 1 or (i + 1)]
      if a and b then
        r.ImGui_DrawList_AddLine(dl, a[1], a[2], b[1], b[2], stroke, stroke_w)
      end
    end
  end
end

function seq_layering_expand_tri(ax, ay, bx, by, cx, cy, amt)
  local mx = (ax + bx + cx) / 3.0
  local my = (ay + by + cy) / 3.0
  local function push(px, py)
    local dx, dy = px - mx, py - my
    local l = math.sqrt(dx * dx + dy * dy)
    if l < 1e-4 then return px, py end
    return px + dx / l * amt, py + dy / l * amt
  end
  local ax2, ay2 = push(ax, ay)
  local bx2, by2 = push(bx, by)
  local cx2, cy2 = push(cx, cy)
  return ax2, ay2, bx2, by2, cx2, cy2
end

function seq_layer_col_alpha(color, alpha_value)
  color = tonumber(color) or 0x1EFF5EFF
  alpha_value = tonumber(alpha_value) or 1.0
  local rr = math.floor((color / 16777216) % 256)
  local gg = math.floor((color / 65536) % 256)
  local bb = math.floor((color / 256) % 256)
  local aa = math.max(0, math.min(255, math.floor(alpha_value * 255)))
  return rr * 16777216 + gg * 65536 + bb * 256 + aa
end

function seq_layering_draw_polished_tri(dl, ax, ay, bx, by, cx, cy, hot)
  if not dl then return end
  ax, ay = tonumber(ax), tonumber(ay)
  bx, by = tonumber(bx), tonumber(by)
  cx, cy = tonumber(cx), tonumber(cy)
  if not (ax and ay and bx and by and cx and cy) then return end
  local accent = (hot and UI_THEME.accent_hvr) or UI_THEME.accent or 0x1EFF5EFF
  local fill = UI_THEME.accent_fill or 0x0E2A18FF
  r.ImGui_DrawList_AddTriangleFilled(dl, ax, ay, bx, by, cx, cy, fill)
  local outlined = pcall(function()
    local radius = 14.0
    for i = 4, 1, -1 do
      local grow = i * 2.4
      local ea, ey, eb, eby, ec, ecy = seq_layering_expand_tri(ax, ay, bx, by, cx, cy, grow)
      local pts = seq_layering_rounded_tri_points(ea, ey, eb, eby, ec, ecy, radius + i)
      local alpha = hot and (0.10 * (5 - i)) or (0.055 * (5 - i))
      seq_layering_draw_poly(dl, pts, nil, seq_layer_col_alpha(accent, alpha), 3.0 + i * 0.8)
    end
    local pts = seq_layering_rounded_tri_points(ax, ay, bx, by, cx, cy, radius)
    seq_layering_draw_poly(dl, pts, fill, nil, 0)
    seq_layering_draw_poly(dl, pts, nil, seq_layer_col_alpha(accent, 0.95), 2.6)
  end)
  if not outlined then
    r.ImGui_DrawList_AddLine(dl, ax, ay, bx, by, accent, 2.2)
    r.ImGui_DrawList_AddLine(dl, bx, by, cx, cy, accent, 2.2)
    r.ImGui_DrawList_AddLine(dl, cx, cy, ax, ay, accent, 2.2)
  end
end

function seq_layering_draw_pct_badge(dl, cx, cy, pct)
  local text = string.format("%d%%", pct)
  local tw = select(1, r.ImGui_CalcTextSize(ctx, text)) or 24
  local w, h = tw + 10, 16
  local x0, y0 = cx - w * 0.5, cy - h * 0.5
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x0 + w, y0 + h, 0x0C100EFF, 3.0)
  r.ImGui_DrawList_AddRect(dl, x0, y0, x0 + w, y0 + h, 0x1EFF5E55, 3.0, 0, 1.0)
  r.ImGui_DrawList_AddText(dl, x0 + 5, y0 + 1, 0xE8EEEAFF, text)
end

function seq_layering_vol_knob(id, dl, x, y, size, vert)
  if type(vert) ~= "table" then
    return false, false
  end
  r.ImGui_SetCursorScreenPos(ctx, x, y)
  r.ImGui_InvisibleButton(ctx, id, size, size)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  local vol = seq_layer_vert_vol(vert)
  local changed = false
  local fine = seq_fine_drag_down()
  if active then
    local _, dy = r.ImGui_GetMouseDelta(ctx)
    if dy and dy ~= 0.0 then
      local step = ((SEQ_LAYER_VOL_MAX or 4.0) / 180.0) * (fine and SEQ_FINE_DRAG_SCALE or 1.0)
      vol = seq_layer_vert_vol({ vol = vol + (-dy) * step })
      vert.vol = vol
      changed = true
    end
  end
  if r.ImGui_IsItemClicked(ctx, 0) and r.ImGui_IsMouseDoubleClicked(ctx, 0) then
    vert.vol = 1.0
    vol = 1.0
    changed = true
  end
  local cx, cy = x + size * 0.5, y + size * 0.5 + (active and 1.0 or 0.0)
  local radius = size * 0.46
  local fill = active and UI_THEME.accent_fill_h or (hovered and UI_THEME.surface_hvr or UI_THEME.surface)
  local edge = (hovered or active) and UI_THEME.accent or UI_THEME.border
  r.ImGui_DrawList_AddCircleFilled(dl, cx, cy, radius, fill, 18)
  r.ImGui_DrawList_AddCircle(dl, cx, cy, radius, edge, 18, hovered and 1.5 or 1.2)
  local amin, amax = math.pi * 0.75, math.pi * 2.25
  local t = vol / (SEQ_LAYER_VOL_MAX or 4.0)
  local ang = amin + (amax - amin) * t
  local ar = radius - 2.6
  local prevx, prevy
  for i = 0, 12 do
    local a = amin + (ang - amin) * (i / 12)
    local px = cx + math.cos(a) * ar
    local py = cy + math.sin(a) * ar
    if prevx then
      r.ImGui_DrawList_AddLine(dl, prevx, prevy, px, py, UI_THEME.accent, 1.6)
    end
    prevx, prevy = px, py
  end
  if hovered and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, string.format("Sample volume  %.0f%%\nDrag to adjust, double-click to reset", vol * 100.0))
  end
  return changed, hovered
end

function seq_layering_vert_can_drop(hit)
  if not hit then
    return false
  end
  return (not hit.locked) or (hit.idx == 1)
end

function seq_layering_store_vert_hit(side_key, idx, vx, vy, locked)
  state.seq_layering_vert_hits = state.seq_layering_vert_hits or {}
  state.seq_layering_vert_hits[#state.seq_layering_vert_hits + 1] = {
    side = side_key,
    idx = idx,
    x = vx,
    y = vy,
    locked = locked == true,
  }
end

function seq_layering_hit_vert(mx, my)
  local hits = state.seq_layering_vert_hits
  mx, my = tonumber(mx), tonumber(my)
  if not hits or not mx or not my then
    return nil
  end
  local rad = SEQ_LAYER_VERT_DROP_R or 24.0
  local r2 = rad * rad
  local best, best_d = nil, r2
  for i = 1, #hits do
    local h = hits[i]
    if seq_layering_vert_can_drop(h) then
      local dx, dy = mx - h.x, my - h.y
      local d = dx * dx + dy * dy
      if d <= best_d then
        best_d = d
        best = h
      end
    end
  end
  return best
end

function seq_layering_pointer_over_window()
  local rect = state.seq_layering_rect
  if not rect then
    return false
  end
  local mx, my = r.ImGui_GetMousePos(ctx)
  mx, my = tonumber(mx), tonumber(my)
  if not mx or not my then
    return false
  end
  return mx >= (rect.x or 0) and my >= (rect.y or 0)
    and mx <= (rect.x or 0) + (rect.w or 0)
    and my <= (rect.y or 0) + (rect.h or 0)
end

function seq_layering_resolve_drop_vert()
  if not sample_drag_active() then
    state.seq_layering_drop_vert = nil
    return nil
  end
  local mx, my = r.ImGui_GetMousePos(ctx)
  local hit = seq_layering_hit_vert(mx, my)
  if hit then
    state.seq_layering_drop_vert = { side = hit.side, idx = hit.idx }
    return hit
  end
  state.seq_layering_drop_vert = nil
  return nil
end

function seq_layering_draw_vert_drop_cues(dl)
  if not dl or not sample_drag_active() then
    return
  end
  local hits = state.seq_layering_vert_hits
  if not hits then
    return
  end
  local drop = state.seq_layering_drop_vert
  local pulse = (drag_pulse and drag_pulse()) or 0.5
  for i = 1, #hits do
    local h = hits[i]
    if seq_layering_vert_can_drop(h) then
      local is_hot = drop and drop.side == h.side and drop.idx == h.idx
      if is_hot then
        r.ImGui_DrawList_AddCircleFilled(dl, h.x, h.y, 16.0, seq_layer_col_alpha(UI_THEME.accent, 0.32 + 0.22 * pulse), 20)
        r.ImGui_DrawList_AddCircle(dl, h.x, h.y, 16.0, 0x7CFF4AFF, 20, 2.4)
        r.ImGui_DrawList_AddCircle(dl, h.x, h.y, 21.0, seq_layer_col_alpha(UI_THEME.accent, 0.55), 20, 1.5)
      else
        r.ImGui_DrawList_AddCircle(dl, h.x, h.y, 13.0, seq_layer_col_alpha(UI_THEME.accent, 0.40 + 0.18 * pulse), 18, 1.6)
      end
    end
  end
end

function seq_layering_draw_triangle(dl, slot, side_key, x, y, w, h)
  seq_normalize_slot_layers(slot)
  local side = slot and slot.layers and slot.layers[side_key]
  if type(side) ~= "table" then
    side = seq_layer_default_side()
    if slot and type(slot.layers) == "table" then
      slot.layers[side_key] = side
    end
  end
  if type(side.verts) ~= "table" then
    side.verts = seq_layer_default_side().verts
  end
  if type(side.blend) ~= "table" then
    side.blend = { 1.0, 0.0, 0.0 }
  end
  x, y, w, h = tonumber(x) or 0, tonumber(y) or 0, tonumber(w) or 200, tonumber(h) or 200
  local ax, ay, bx, by, cx, cy = seq_layering_tri_geom(x, y, w, h)
  local hot = state.seq_layering_hover_side == side_key
  seq_layering_draw_polished_tri(dl, ax, ay, bx, by, cx, cy, hot)
  local side_label = (side_key == "transient") and "TRANSIENT" or "SUSTAIN"
  local slw = select(1, r.ImGui_CalcTextSize(ctx, side_label)) or 60
  local dice_sz = 18.0
  local label_x = x + (w - slw) * 0.5
  r.ImGui_SetCursorScreenPos(ctx, label_x - dice_sz - 5, y + 1)
  if draw_ui_button("seq_layer_global_" .. slot.id .. "_" .. side_key, nil, dice_sz, dice_sz, { icon = "dice5", style = "accent" }) then
    if seq_layering_randomize_side(slot, side_key) then
      save_config()
      if save_seq_project_state then save_seq_project_state() end
      seq_layering_sync_arrange(slot)
    end
  end
  if r.ImGui_IsItemHovered(ctx) and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, "Randomize all unlocked " .. side_key .. " samples")
  end
  r.ImGui_DrawList_AddText(dl, label_x, y + 3, UI_THEME.accent, side_label)

  local mx, my = r.ImGui_GetMousePos(ctx)
  local inside = false
  if mx and my then
    local rw, rv, ru = seq_layer_barycentric_raw(mx, my, ax, ay, bx, by, cx, cy)
    inside = rw >= -0.02 and rv >= -0.02 and ru >= -0.02
  end

  local px, py = seq_layer_point_from_bary(side.blend, ax, ay, bx, by, cx, cy)
  local mabx, maby = (ax + bx) * 0.5, (ay + by) * 0.5
  local mbcx, mbcy = (bx + cx) * 0.5, (by + cy) * 0.5
  local mcax, mcay = (cx + ax) * 0.5, (cy + ay) * 0.5
  local div = seq_layer_col_alpha(UI_THEME.accent, hot and 0.45 or 0.28)
  r.ImGui_DrawList_AddLine(dl, px, py, mabx, maby, div, 1.1)
  r.ImGui_DrawList_AddLine(dl, px, py, mbcx, mbcy, div, 1.1)
  r.ImGui_DrawList_AddLine(dl, px, py, mcax, mcay, div, 1.1)
  local hs = 7.5
  local hax, hay = px, py - hs * 0.72
  local hbx, hby = px - hs * 0.62, py + hs * 0.42
  local hcx, hcy = px + hs * 0.62, py + hs * 0.42
  r.ImGui_DrawList_AddTriangleFilled(dl, hax, hay, hbx, hby, hcx, hcy, UI_THEME.accent)
  r.ImGui_DrawList_AddLine(dl, hax, hay, hbx, hby, 0xE8FFEEFF, 1.2)
  r.ImGui_DrawList_AddLine(dl, hbx, hby, hcx, hcy, 0xE8FFEEFF, 1.2)
  r.ImGui_DrawList_AddLine(dl, hcx, hcy, hax, hay, 0xE8FFEEFF, 1.2)

  local verts_xy = { { ax, ay }, { bx, by }, { cx, cy } }
  local btn = 18.0
  local btn_gap = 3.0
  local changed = false
  local controls_hot = false

  for i = 1, 3 do
    local vx, vy = verts_xy[i][1], verts_xy[i][2]
    local vert = side.verts[i]
    if type(vert) ~= "table" then
      vert = { path = nil, name = nil, locked = (i == 1), vol = 1.0 }
      side.verts[i] = vert
    end
    local sample = vert.path and find_sample_by_path(vert.path) or nil
    local color = sample and get_sample_dot_color(sample) or 0x667788FF
    r.ImGui_DrawList_AddCircleFilled(dl, vx, vy, 6.5, color, 16)
    r.ImGui_DrawList_AddCircle(dl, vx, vy, 6.5, 0xE8FFEECC, 16, 1.3)

    local cluster_w = btn * 3 + btn_gap * 2
    local cluster_x, cluster_y
    if i == 1 then
      cluster_x = vx + 18
      cluster_y = vy - btn * 0.5
    elseif i == 2 then
      cluster_x = vx - cluster_w - 14
      cluster_y = vy + 10
    else
      cluster_x = vx + 14
      cluster_y = vy + 10
    end

    local dice_id = "##seq_layer_dice_" .. slot.id .. "_" .. side_key .. "_" .. i
    local lock_id = "##seq_layer_lock_" .. slot.id .. "_" .. side_key .. "_" .. i
    local vol_id = "##seq_layer_vol_" .. slot.id .. "_" .. side_key .. "_" .. i
    local dice_clicked, dice_hovered = seq_layering_icon_button(dice_id, dl, cluster_x, cluster_y, btn, btn, "dice", false)
    local lock_clicked, lock_hovered = seq_layering_icon_button(lock_id, dl, cluster_x + btn + btn_gap, cluster_y, btn, btn, "lock", vert.locked)
    local vol_changed, vol_hovered = seq_layering_vol_knob(vol_id, dl, cluster_x + (btn + btn_gap) * 2, cluster_y, btn, vert)
    if dice_clicked then
      if seq_layering_randomize_vert(slot, side_key, i) then
        changed = true
      end
    end
    if lock_clicked then
      vert.locked = not vert.locked
      seq_layering_sync_linked(slot, side_key)
      changed = true
    end
    if vol_changed then
      seq_layering_sync_linked(slot, side_key)
      state.seq_layering_vol_drag = true
    end
    if dice_hovered or lock_hovered or vol_hovered then
      controls_hot = true
    end
    if dice_hovered and r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, vert.locked and "Unlock to randomize" or "Randomize this sample")
    elseif lock_hovered and r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, vert.locked and "Unlock this sample" or "Lock this sample")
    end

    local name = "empty"
    if vert.path and vert.path ~= "" then
      name = basename(vert.path)
    elseif vert.name and vert.name ~= "" then
      name = tostring(vert.name)
    end
    name = name:upper()
    if #name > 18 then
      name = name:sub(1, 14) .. "..."
    end
    local nw = select(1, r.ImGui_CalcTextSize(ctx, name)) or 40
    local nx, ny
    if i == 1 then
      nx = vx - 12 - nw
      ny = vy - 7
    else
      nx = cluster_x
      ny = cluster_y + btn + 2
    end
    r.ImGui_DrawList_AddText(dl, nx, ny, sample and 0xF4F7FCFF or UI_THEME.text_mute, name)

    local pct = math.floor(((side.blend[i] or 0) * 100) + 0.5)
    local ptx, pty
    if i == 1 then
      ptx, pty = vx, vy + 20
    elseif i == 2 then
      ptx, pty = vx + 20, vy - 14
    else
      ptx, pty = vx - 20, vy - 14
    end
    seq_layering_draw_pct_badge(dl, ptx, pty, pct)

    -- Vertex hit for preview. Sample drops use screen-space hit tests so they
    -- still work when the map (or another window) has captured the mouse.
    seq_layering_store_vert_hit(side_key, i, vx, vy, vert.locked == true)
    r.ImGui_SetCursorScreenPos(ctx, vx - 14, vy - 14)
    r.ImGui_InvisibleButton(ctx, "##seq_layer_vert_" .. slot.id .. "_" .. side_key .. "_" .. i, 28, 28)
    if r.ImGui_IsItemHovered(ctx) then
      controls_hot = true
    end
    if r.ImGui_IsItemClicked(ctx, 0) and sample and not sample_drag_active() then
      state.seq_layering_ab = nil
      preview_sample(sample)
    end
  end

  local drag_id = side_key
  local dragging = state.seq_layering_drag and state.seq_layering_drag.side == drag_id
      and state.seq_layering_drag.slot_id == slot.id
  local win_hovered = r.ImGui_IsWindowHovered and r.ImGui_IsWindowHovered(ctx) or true
  if dragging then
    if r.ImGui_IsMouseDown(ctx, 0) then
      local ba, bb, bc = seq_layer_barycentric(mx, my, ax, ay, bx, by, cx, cy)
      side.blend = { ba, bb, bc }
      seq_layering_sync_linked(slot, side_key)
    else
      state.seq_layering_drag = nil
      seq_layering_sync_linked(slot, side_key)
      changed = true
    end
  elseif win_hovered and inside and not controls_hot and not sample_drag_active() then
    state.seq_layering_hover_side = side_key
    if r.ImGui_IsMouseClicked(ctx, 0) then
      state.seq_layering_drag = { side = drag_id, slot_id = slot.id }
      local ba, bb, bc = seq_layer_barycentric(mx, my, ax, ay, bx, by, cx, cy)
      side.blend = { ba, bb, bc }
      seq_layering_sync_linked(slot, side_key)
    end
  end

  if state.seq_layering_vol_drag and not r.ImGui_IsMouseDown(ctx, 0) then
    state.seq_layering_vol_drag = nil
    changed = true
  end

  if changed then
    save_config()
    if save_seq_project_state then save_seq_project_state() end
    seq_layering_sync_arrange(slot)
  end
end

function render_seq_layering_window()
  if not state.seq_layering_slot_id then
    state.seq_layering_hover_side = nil
    state.seq_layering_hovered = false
    state.seq_layering_rect = nil
    state.seq_layering_vert_hits = nil
    state.seq_layering_drop_vert = nil
    return
  end
  local slot = find_seq_track_by_id(state.seq_layering_slot_id)
  if not slot then
    state.seq_layering_slot_id = nil
    state.seq_layering_vert_hits = nil
    state.seq_layering_drop_vert = nil
    return
  end
  seq_layering_seed_from_track(slot)

  local stored_w = tonumber(state.seq_layering_win_w) or 760
  stored_w = math.max(620, math.min(1200, stored_w))
  local ideal_h = seq_layering_ideal_content_h(math.max(400, stored_w - 20)) + 36
  if r.ImGui_SetNextWindowSizeConstraints then
    r.ImGui_SetNextWindowSizeConstraints(ctx, 620.0, 360.0, 1400.0, 1200.0)
  end
  if r.ImGui_Cond_Always then
    r.ImGui_SetNextWindowSize(ctx, stored_w, ideal_h, r.ImGui_Cond_Always())
  else
    r.ImGui_SetNextWindowSize(ctx, stored_w, ideal_h, r.ImGui_Cond_FirstUseEver())
  end

  local title = "Drum Layering — " .. (slot.name or "Track")
  local flags = 0
  if r.ImGui_WindowFlags_NoCollapse then
    flags = flags | r.ImGui_WindowFlags_NoCollapse()
  end
  if r.ImGui_WindowFlags_NoDocking then
    flags = flags | r.ImGui_WindowFlags_NoDocking()
  end
  if r.ImGui_SetNextWindowCollapsed then
    r.ImGui_SetNextWindowCollapsed(ctx, false, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
  end
  local began_ok, visible, open = pcall(r.ImGui_Begin, ctx, title .. "###seq_layering_window", true, flags)
  if not began_ok then
    if log then log("Drum layering Begin failed: " .. tostring(visible)) end
    return
  end
  if open == false then
    state.seq_layering_slot_id = nil
    state.seq_layering_drag = nil
    state.seq_layering_hover_side = nil
    state.seq_layering_hovered = false
    state.seq_layering_rect = nil
  end

  if visible then
    if r.ImGui_GetWindowPos and r.ImGui_GetWindowSize then
      local x, y = r.ImGui_GetWindowPos(ctx)
      local w, h = r.ImGui_GetWindowSize(ctx)
      state.seq_layering_rect = {
        x = tonumber(x) or 0,
        y = tonumber(y) or 0,
        w = tonumber(w) or 0,
        h = tonumber(h) or 0,
      }
    end
    local hover_flags = 0
    if r.ImGui_HoveredFlags_RootAndChildWindows then
      hover_flags = r.ImGui_HoveredFlags_RootAndChildWindows()
    end
    state.seq_layering_hovered = r.ImGui_IsWindowHovered
        and r.ImGui_IsWindowHovered(ctx, hover_flags)
        or false
    local body_ok, body_err = pcall(seq_layering_render_body, slot)
    if not body_ok and log then
      log("Drum layering draw error: " .. tostring(body_err))
    end
    pcall(r.ImGui_End, ctx)
  else
    state.seq_layering_hovered = false
  end
end

function seq_layering_draw_bias(dl, slot, x, y, w, h, linked)
  if not slot or not dl then return end
  seq_normalize_slot_layers(slot)
  local bias = slot.layers.bias or 0.0
  r.ImGui_SetCursorScreenPos(ctx, x, y)
  r.ImGui_InvisibleButton(ctx, "##seq_layer_bias_" .. tostring(slot.id), w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  local disabled = linked == true

  if not disabled then
    if hovered and r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0) then
      slot.layers.bias = 0.0
      state.seq_layering_bias_drag = nil
      save_config()
      if save_seq_project_state then save_seq_project_state() end
      seq_layering_sync_arrange(slot, { force_rebuild = true })
    elseif active then
      local dx = select(1, r.ImGui_GetMouseDelta(ctx))
      if dx and dx ~= 0.0 then
        state.seq_layering_bias_drag = true
        -- Left shortens the transient; right lengthens it.
        bias = bias + dx / math.max(36.0, w * 0.85)
        if bias < -1.0 then bias = -1.0 elseif bias > 1.0 then bias = 1.0 end
        slot.layers.bias = bias
      end
    elseif state.seq_layering_bias_drag and not (r.ImGui_IsMouseDown and r.ImGui_IsMouseDown(ctx, 0)) then
      state.seq_layering_bias_drag = nil
      save_config()
      if save_seq_project_state then save_seq_project_state() end
      seq_layering_sync_arrange(slot, { force_rebuild = true })
    end
  elseif state.seq_layering_bias_drag then
    state.seq_layering_bias_drag = nil
  end

  local mid_x = x + w * 0.5
  local u = ((slot.layers.bias or 0.0) + 1.0) * 0.5
  local thumb_x = x + 4 + u * math.max(1.0, w - 8)
  local fill_col = disabled and 0x3A4A40FF or UI_THEME.accent
  local bg = (hovered or active) and not disabled and UI_THEME.surface_hvr or UI_THEME.surface
  local edge = (hovered or active) and not disabled and UI_THEME.accent or UI_THEME.border
  ui_draw_panel(dl, x, y, x + w, y + h, 5.0, bg, edge, hovered and not disabled, active and not disabled)
  r.ImGui_DrawList_AddLine(dl, mid_x, y + 3, mid_x, y + h - 3, 0xFFFFFF28, 1.0)
  if thumb_x < mid_x then
    r.ImGui_DrawList_AddRectFilled(dl, thumb_x, y + 4, mid_x, y + h - 4, fill_col, 2.0)
  elseif thumb_x > mid_x then
    r.ImGui_DrawList_AddRectFilled(dl, mid_x, y + 4, thumb_x, y + h - 4, fill_col, 2.0)
  end
  r.ImGui_DrawList_AddRectFilled(dl, thumb_x - 3, y + 2, thumb_x + 3, y + h - 2, fill_col, 2.0)

  local label = "BIAS"
  local lw = select(1, r.ImGui_CalcTextSize(ctx, label)) or 22
  r.ImGui_DrawList_AddText(dl, x + (w - lw) * 0.5, y + h + 3,
    disabled and UI_THEME.text_mute or UI_THEME.text_dim, label)

  if hovered and r.ImGui_SetTooltip then
    if disabled then
      r.ImGui_SetTooltip(ctx, "Unlink to split transient / sustain")
    else
      local split = seq_layering_split_sec(slot)
      r.ImGui_SetTooltip(ctx, string.format(
        "Transient  %.0f ms\nLeft: shorter   Right: longer\nDouble-click to reset",
        (split or 0.0) * 1000.0
      ))
    end
  end
end

function seq_layering_render_body(slot)
  local prev_hover = state.seq_layering_hover_side
  state.seq_layering_hover_side = nil
  state.seq_layering_vert_hits = {}
  if not sample_drag_active() then
    state.seq_layering_drop_vert = nil
  end

  seq_normalize_slot_layers(slot)
  local linked = slot.layers and slot.layers.linked == true
  local dl = r.ImGui_GetWindowDrawList and r.ImGui_GetWindowDrawList(ctx)
  if not dl and r.ImGui_GetForegroundDrawList then
    dl = r.ImGui_GetForegroundDrawList(ctx)
  end
  local avail_w = select(1, r.ImGui_GetContentRegionAvail(ctx)) or 700
  avail_w = tonumber(avail_w) or 700
  if avail_w < 200 then avail_w = 200 end
  if r.ImGui_GetWindowSize then
    local win_w = select(1, r.ImGui_GetWindowSize(ctx))
    win_w = tonumber(win_w)
    if win_w and win_w > 0 then
      state.seq_layering_win_w = win_w
    end
  end

  local wave_h = SEQ_LAYER_WAVE_H
  local col_w = (avail_w - SEQ_LAYER_LINK_W) * 0.5
  if col_w < 160 then col_w = 160 end
  local tri_h = select(8, seq_layering_tri_geom(0, 0, col_w, 800)) or 180
  local block_h = SEQ_LAYER_PAD_TOP + tri_h + SEQ_LAYER_PAD_BOT
  local wx, wy = 0, 0
  if r.ImGui_GetCursorScreenPos then
    wx, wy = r.ImGui_GetCursorScreenPos(ctx)
  end
  wx, wy = tonumber(wx) or 0, tonumber(wy) or 0
  if r.ImGui_PushStyleVar and r.ImGui_StyleVar_ItemSpacing then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 0, 0)
  end
  if dl then
    seq_layering_draw_waveforms(dl, slot, wx, wy, avail_w, wave_h, prev_hover)
  end
  r.ImGui_Dummy(ctx, avail_w, wave_h)

  local left_x, left_y = wx, wy + wave_h
  r.ImGui_Dummy(ctx, avail_w, block_h)
  if r.ImGui_PopStyleVar then
    r.ImGui_PopStyleVar(ctx, 1)
  end

  if dl then
    pcall(seq_layering_draw_triangle, dl, slot, "transient", left_x, left_y, col_w, block_h)
    pcall(seq_layering_draw_triangle, dl, slot, "sustain", left_x + col_w + SEQ_LAYER_LINK_W, left_y, col_w, block_h)
    if sample_drag_active() then
      seq_layering_resolve_drop_vert()
      seq_layering_draw_vert_drop_cues(dl)
    end
  end

  local link_sz = 28.0
  local bias_w, bias_h = 80.0, 18.0
  local link_x = left_x + col_w + (SEQ_LAYER_LINK_W - link_sz) * 0.5
  local cluster_h = link_sz + 22 + bias_h + 14
  local link_y = left_y + math.max(8.0, (block_h - cluster_h) * 0.5)
  r.ImGui_SetCursorScreenPos(ctx, link_x, link_y)
  if draw_ui_button("seq_layer_link_" .. slot.id, nil, link_sz, link_sz, {
    icon = "link",
    style = linked and "accent" or "default",
    selected = linked,
  }) then
    seq_layering_set_linked(slot, not linked)
    save_config()
    if save_seq_project_state then save_seq_project_state() end
    seq_layering_sync_arrange(slot)
  end
  if r.ImGui_IsItemHovered(ctx) and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, linked
      and "Unlink transient and sustain"
      or "Link transient and sustain — use whole samples, no split")
  end
  local link_caption = linked and "LINKED" or "LINK"
  local cap_w = select(1, r.ImGui_CalcTextSize(ctx, link_caption)) or 28
  if dl then
    r.ImGui_DrawList_AddText(dl, left_x + col_w + (SEQ_LAYER_LINK_W - cap_w) * 0.5, link_y + link_sz + 4,
      linked and UI_THEME.accent or UI_THEME.text_dim, link_caption)
  end

  local bias_x = left_x + col_w + (SEQ_LAYER_LINK_W - bias_w) * 0.5
  local bias_y = link_y + link_sz + 22
  if dl then
    seq_layering_draw_bias(dl, slot, bias_x, bias_y, bias_w, bias_h, linked)
  end
end

-- ===== Groove templates =================================================
-- A groove nudges each grid cell off the rigid metronomic grid so beats feel
-- more human. Each preset is a 16-slot table (one bar of 1/16 notes in 4/4).
-- Each slot value is a timing offset expressed as a FRACTION OF A 1/16 NOTE:
--   positive = lay the hit back (behind the beat), negative = push it ahead.
-- The values are grounded in the classic "swing %" convention used by the
-- LinnDrum / Akai MPC / Logic / Ableton groove pools, where 50% is straight
-- and a given % delays the off-beat. Converting that to a fraction of a 1/16:
--   1/16 swing off-note delay  = (pct - 50) / 50      (delays the e & a)
--   1/8  swing off-note delay  = (pct - 50) / 25      (delays the "and")
SEQ_SIXTEENTH_QN = 0.25

function seq_groove_swing16(amount)
  -- Delay every other 1/16 (the "e" and "a" of each beat).
  local t = {}
  for i = 0, 15 do
    t[i + 1] = (i % 2 == 1) and amount or 0.0
  end
  return t
end

function seq_groove_swing8(amount)
  -- Delay the off-8th (the "and") of each beat.
  local t = {}
  for i = 0, 15 do
    t[i + 1] = (i % 4 == 2) and amount or 0.0
  end
  return t
end

function seq_groove_uniform(amount)
  local t = {}
  for i = 0, 15 do t[i + 1] = amount end
  return t
end

-- Deterministic per-slot jitter so "humanized" feels are stable across renders
-- (same groove always produces the same offsets) yet uneven like a real player.
function seq_groove_jitter(base, seed, depth)
  local t = {}
  local s = (seed or 1) % 2147483648
  for i = 0, 15 do
    s = (s * 1103515245 + 12345) % 2147483648
    local centered = (s / 2147483648.0) * 2.0 - 1.0
    local b = base and base[i + 1] or 0.0
    t[i + 1] = b + centered * depth
  end
  return t
end

-- Hand-built lopsided "drunk" feel inspired by J Dilla's off-grid timing:
-- swung 1/16s with the backbeats laid back and a few subdivisions pulled early.
SEQ_GROOVE_DILLA = {
  0.00, 0.30, -0.04, 0.22,
  0.06, 0.34,  0.02, 0.20,
 -0.02, 0.32,  0.04, 0.24,
  0.08, 0.30,  0.00, 0.18,
}

-- Boom-bap: moderate 1/16 swing with the snare backbeats (beats 2 & 4) dragged.
SEQ_GROOVE_BOOM_BAP = {
  0.00, 0.18, 0.00, 0.18,
  0.07, 0.18, 0.00, 0.18,
  0.00, 0.18, 0.00, 0.18,
  0.07, 0.18, 0.00, 0.18,
}

SEQ_GROOVE_PRESETS = {
  off              = { steps = nil },
  swing16_54       = { steps = seq_groove_swing16(0.08) },
  swing16_58       = { steps = seq_groove_swing16(0.16) },
  swing16_60       = { steps = seq_groove_swing16(0.20) },
  swing16_62       = { steps = seq_groove_swing16(0.24) },
  swing16_66       = { steps = seq_groove_swing16(0.333) },
  swing16_71       = { steps = seq_groove_swing16(0.42) },
  swing8_56        = { steps = seq_groove_swing8(0.24) },
  swing8_62        = { steps = seq_groove_swing8(0.48) },
  mpc_60           = { steps = seq_groove_jitter(seq_groove_swing16(0.20), 7321, 0.04) },
  mpc_66           = { steps = seq_groove_jitter(seq_groove_swing16(0.333), 5189, 0.05) },
  linn             = { steps = seq_groove_jitter(seq_groove_swing16(0.16), 2654, 0.03) },
  dilla            = { steps = SEQ_GROOVE_DILLA },
  boom_bap         = { steps = SEQ_GROOVE_BOOM_BAP },
  laid_back        = { steps = seq_groove_uniform(0.06) },
  pushed           = { steps = seq_groove_uniform(-0.06) },
  quintuplet       = { steps = seq_groove_swing16(0.20) },
  septuplet        = { steps = seq_groove_swing16(0.14) },
  shuffle_triplet  = { steps = seq_groove_swing8(0.667) },
  human_tight      = { steps = seq_groove_jitter(nil, 9001, 0.05) },
  human_loose      = { steps = seq_groove_jitter(nil, 4242, 0.13) },
}

