function seq_groove_exists(groove_key)
  return type(groove_key) == "string" and SEQ_GROOVE_PRESETS[groove_key] ~= nil
end

function normalize_seq_groove(groove_key)
  if seq_groove_exists(groove_key) then
    return groove_key
  end
  return "off"
end

function get_seq_groove_label(groove_key)
  groove_key = normalize_seq_groove(groove_key)
  for _, entry in ipairs(SEQ_GROOVE_ORDER) do
    if entry.key == groove_key then
      return entry.label
    end
  end
  return "Straight"
end

function get_seq_groove_chip_label(groove_key)
  groove_key = normalize_seq_groove(groove_key)
  if groove_key == "off" then
    return "Straight"
  end
  local label = get_seq_groove_label(groove_key)
  return (label:gsub("%s*%b()%s*$", ""))
end

function get_seq_region_groove(region)
  if type(region) == "table" then
    return normalize_seq_groove(region.groove)
  end
  return "off"
end

function get_seq_region_pattern_label(region)
  if region and type(region.style_key) == "string" and region.style_key ~= "" then
    if seq_gen_style_exists(region.style_key) then
      return get_seq_gen_style_label(region.style_key)
    end
    return seq_gmd_pretty_label(region.style_key)
  end
  return get_seq_gen_style_label(state.seq_gen_style)
end

-- Old projects stored one groove for the whole sequencer. Copy that onto any
-- region that does not yet have its own feel so existing timing is preserved.
function migrate_seq_region_grooves()
  local fallback = normalize_seq_groove(state.seq_groove)
  for _, region in ipairs(state.seq_regions or {}) do
    if type(region) == "table" then
      if region.groove == nil or region.groove == "" then
        region.groove = fallback
      else
        region.groove = normalize_seq_groove(region.groove)
      end
    end
  end
end

function set_seq_region_groove(region, groove_key)
  if not region then
    return false
  end
  groove_key = normalize_seq_groove(groove_key)
  if get_seq_region_groove(region) == groove_key then
    return false
  end
  local own = seq_undo_own_begin("Set region groove")
  region.groove = groove_key
  state.seq_groove = groove_key
  save_config()
  sync_seq_region(region)
  if own then
    end_seq_undo("Set region groove")
  end
  return true
end

-- Timing offset (in QN) for a grid cell at the given absolute musical position.
-- The bar is treated as 16 x 1/16 in 4/4; the cell is mapped to its nearest
-- 1/16 slot so the groove lines up with project bars regardless of grid size.
-- groove_key is the region's feel; omitting it applies no groove.
function seq_groove_offset_qn(abs_qn, groove_key)
  local preset = SEQ_GROOVE_PRESETS[normalize_seq_groove(groove_key)]
  if not preset or not preset.steps then
    return 0.0
  end
  local sixteenth = math.floor((abs_qn / SEQ_SIXTEENTH_QN) + 0.5)
  local idx = sixteenth % 16
  if idx < 0 then idx = idx + 16 end
  local frac = preset.steps[idx + 1] or 0.0
  return frac * SEQ_SIXTEENTH_QN
end


function seq_tag_uses_sustain_length(tag)
  if not tag then
    return false
  end
  local tl = string.lower(tostring(tag))
  if SEQ_SUSTAIN_TAGS[tl] then
    return true
  end
  local cat = categorize_tags(tag)
  return cat == "melodic" or cat == "loop"
end

function seq_note_uses_sustain_length(slot, resolved_sample)
  if slot and SEQ_SUSTAIN_ROLES[infer_seq_track_role(slot)] then
    return true
  end
  if slot and seq_tag_uses_sustain_length(slot.sample_tag) then
    return true
  end
  if resolved_sample and type(resolved_sample.tags) == "table" then
    for _, tag in ipairs(resolved_sample.tags) do
      if seq_tag_uses_sustain_length(tag) then
        return true
      end
    end
  end
  if resolved_sample and resolved_sample.path then
    if detect_loop_or_oneshot(resolved_sample.path, resolved_sample.folder or "", resolved_sample.playback_type) == "loop" then
      return true
    end
  end
  return false
end

function seq_note_trigger_qn(region, step_idx, note, grid_qn)
  local cell_start_qn = seq_note_abs_qn(region, note, step_idx, grid_qn)
  local offset_qn = (note and note.offset_qn) or 0.0
  local groove_qn = seq_groove_offset_qn(cell_start_qn, get_seq_region_groove(region))
  local qn = cell_start_qn + groove_qn + offset_qn
  if qn < 0.0 then
    qn = 0.0
  end
  return qn
end

function seq_next_note_trigger_qn(region, pattern, track_id, step_idx, grid_qn, note)
  if not region then
    return 0.0
  end
  local track_notes = get_track_note_table(pattern, track_id, false)
  if not track_notes then
    return (region.start_qn or 0.0) + get_seq_region_length_qn(region)
  end

  local start_qn = seq_note_trigger_qn(region, step_idx, note, grid_qn)
  local next_qn = nil
  local next_key = nil
  for sk, nnote in pairs(track_notes) do
    if type(nnote) == "table" and nnote.enabled ~= false then
      local qn = seq_note_trigger_qn(region, sk, nnote, grid_qn)
      if qn > start_qn + 1e-9 and (not next_qn or qn < next_qn) then
        next_qn = qn
        next_key = sk
      end
    end
  end

  if next_key then
    return seq_note_trigger_qn(region, next_key, track_notes[next_key] or track_notes[tostring(next_key)], grid_qn)
  end

  return (region.start_qn or 0.0) + get_seq_region_length_qn(region)
end

function seq_sustain_note_length_qn(region, pattern, track_id, step_idx, note, grid_qn)
  local start_qn = seq_note_trigger_qn(region, step_idx, note, grid_qn)
  local end_qn = seq_next_note_trigger_qn(region, pattern, track_id, step_idx, grid_qn, note)
  return math.max((grid_qn or 0.25) * 0.25, end_qn - start_qn)
end

seq_sample_len_sec_cache = {}
seq_defer_item_updates = false

-- Shared PCM prototypes while rewriting many takes of the same file (swap, region sync).
seq_pcm_take_src_cache = nil
seq_pcm_take_src_depth = 0
seq_path_exists_cache = {}

function seq_path_exists(path)
  if not path or path == "" then
    return false
  end
  local cached = seq_path_exists_cache[path]
  if cached ~= nil then
    return cached
  end
  local ok = r.file_exists(path) and true or false
  seq_path_exists_cache[path] = ok
  return ok
end

function seq_pcm_take_src_begin()
  seq_pcm_take_src_depth = (seq_pcm_take_src_depth or 0) + 1
  if seq_pcm_take_src_depth == 1 then
    seq_pcm_take_src_cache = {}
  end
end

function seq_pcm_take_src_end()
  local depth = (seq_pcm_take_src_depth or 1) - 1
  if depth < 0 then
    depth = 0
  end
  seq_pcm_take_src_depth = depth
  if depth > 0 then
    return
  end
  local cache = seq_pcm_take_src_cache
  seq_pcm_take_src_cache = nil
  if type(cache) ~= "table" or not r.PCM_Source_Destroy then
    return
  end
  for _, proto in pairs(cache) do
    if proto then
      r.PCM_Source_Destroy(proto)
    end
  end
end

function seq_pcm_take_src_get(path)
  if not path or path == "" then
    return nil
  end
  local cache = seq_pcm_take_src_cache
  if type(cache) == "table" and r.PCM_Source_Duplicate then
    local proto = cache[path]
    if proto == nil then
      proto = r.PCM_Source_CreateFromFile(path)
      cache[path] = proto or false
    end
    if proto then
      local copy = r.PCM_Source_Duplicate(proto)
      if copy then
        return copy
      end
    elseif proto == false then
      return nil
    end
  end
  return r.PCM_Source_CreateFromFile(path)
end

function seq_sample_source_length_sec(path, sample)
  local map_dur = sample_map_duration(sample)
  if map_dur > 0 then
    return map_dur
  end
  if not path or path == "" then
    return nil
  end
  local cached = seq_sample_len_sec_cache[path]
  if cached ~= nil then
    return cached > 0 and cached or nil
  end
  if not seq_path_exists(path) then
    seq_sample_len_sec_cache[path] = 0
    return nil
  end
  local src = r.PCM_Source_CreateFromFile(path)
  if not src then
    seq_sample_len_sec_cache[path] = 0
    return nil
  end
  local length_sec = pick_number({ r.GetMediaSourceLength(src) }, 0.0)
  if r.PCM_Source_Destroy then
    r.PCM_Source_Destroy(src)
  end
  seq_sample_len_sec_cache[path] = length_sec or 0
  if length_sec > 0 then
    return length_sec
  end
  return nil
end

function seq_sample_length_qn(path, sample)
  local length_sec = seq_sample_source_length_sec(path, sample)
  if not length_sec or length_sec <= 0 then
    return nil
  end
  local sec_per = seq_sec_per_qn
  if not sec_per or sec_per <= 0 then
    local t0 = qn_to_time(0)
    local t1 = qn_to_time(1)
    if not t0 or not t1 or t1 <= t0 then
      return nil
    end
    sec_per = t1 - t0
    seq_sec_per_qn = sec_per
  end
  return length_sec / sec_per
end

SEQ_STRETCH_MIN = 0.25
SEQ_STRETCH_MAX = 4.0
SEQ_START_MAX = 0.99

SEQ_DRUM_STRETCH_ROLES = {
  kick = true, snare = true, clap = true, rim = true, tom = true,
  hat = true, perc = true, ["808"] = true, crash = true, ride = true,
}

function seq_sample_is_drum_sound(sample)
  if not sample then
    return false
  end
  if sample.sample_type == "Drum" then
    return true
  end
  local tags = sample.tags
  if type(tags) == "table" then
    for _, tag in ipairs(tags) do
      if DRUM_TRANSIENT_TAGS[string.lower(tostring(tag))] then
        return true
      end
    end
  end
  return false
end

function seq_stretch_target_is_drum(sample, slot)
  if seq_sample_is_drum_sound(sample) then
    return true
  end
  if slot and SEQ_DRUM_STRETCH_ROLES[infer_seq_track_role(slot)] then
    return true
  end
  return false
end

function seq_rubber_band_pitch_mode()
  if state.seq_rb_pitch_mode_ready then
    return state.seq_rb_pitch_mode
  end
  state.seq_rb_pitch_mode_ready = true
  state.seq_rb_pitch_mode = nil
  if not r.EnumPitchShiftModes then
    return nil
  end
  local best_mode, best_score = nil, -1
  local i = 0
  while i < 64 do
    local a, b = r.EnumPitchShiftModes(i)
    if a == false and (b == nil or b == "") then
      break
    end
    local name = (type(a) == "string" and a) or (type(b) == "string" and b) or nil
    if name then
      local lower = string.lower(name)
      if lower:find("rubber band", 1, true) then
        local score = 1
        if lower:find("library", 1, true) then
          score = 3
        end
        if score > best_score then
          best_mode, best_score = i, score
        end
      end
    end
    i = i + 1
  end
  if best_mode then
    -- Default Rubber Band Library submode (0).
    state.seq_rb_pitch_mode = (best_mode << 16)
  end
  return state.seq_rb_pitch_mode
end

function seq_apply_drum_rubber_band_stretch(take, stretch, sample, slot)
  if not take then
    return
  end
  stretch = tonumber(stretch) or 1.0
  if math.abs(stretch - 1.0) <= 0.0001 then
    return
  end
  if not seq_stretch_target_is_drum(sample, slot) then
    return
  end
  local mode = seq_rubber_band_pitch_mode()
  if not mode then
    return
  end
  r.SetMediaItemTakeInfo_Value(take, "I_PITCHMODE", mode)
end

function seq_note_stretch_amount(note, hit_idx)
  local v = tonumber(seq_note_param_value(note, "stretch", hit_idx) or (note and note.stretch)) or 1.0
  if v < SEQ_STRETCH_MIN then return SEQ_STRETCH_MIN end
  if v > SEQ_STRETCH_MAX then return SEQ_STRETCH_MAX end
  return v
end

function seq_note_start_frac(note, hit_idx)
  local v = tonumber(seq_note_param_value(note, "start", hit_idx) or (note and note.start)) or 0.0
  if v < 0.0 then return 0.0 end
  if v > SEQ_START_MAX then return SEQ_START_MAX end
  return v
end

-- Remaining source after Start, then Stretch can shrink it but not grow past
-- the unstretched remaining length (so a longer stretch never pushes the end).
function seq_source_play_cap_qn(length_qn, path, sample, note, hit_idx)
  local src_qn = seq_sample_length_qn(path, sample)
  if not src_qn or src_qn <= 0 then
    return length_qn
  end
  local remaining = src_qn * (1.0 - seq_note_start_frac(note, hit_idx))
  local stretch = seq_note_stretch_amount(note, hit_idx)
  local cap = math.min(remaining, remaining * stretch)
  if not length_qn then
    return math.max(0.001, cap)
  end
  return math.min(length_qn, math.max(0.001, cap))
end

function seq_cap_length_to_sample_qn(length_qn, path, sample, note, hit_idx)
  if note then
    return seq_source_play_cap_qn(length_qn, path, sample, note, hit_idx)
  end
  local cap_qn = seq_sample_length_qn(path, sample)
  if cap_qn and cap_qn > 0 then
    return math.min(length_qn, cap_qn)
  end
  return length_qn
end

function seq_region_end_qn(region)
  return (region and region.start_qn or 0.0) + get_seq_region_length_qn(region)
end

-- Auto sample sustain stops at the region end. Explicit decay_qn may pass it.
function seq_cap_length_to_region_end_qn(length_qn, region, step_idx, note, grid_qn)
  if not region or not length_qn or length_qn <= 0 then
    return length_qn
  end
  local start_qn = seq_note_trigger_qn(region, step_idx, note, grid_qn)
  local remain = seq_region_end_qn(region) - start_qn
  if remain <= 0 then
    return length_qn
  end
  return math.min(length_qn, remain)
end

function seq_note_length_qn_for_copy(region, slot, note, step_key, grid_qn)
  if type(note) ~= "table" then
    return nil
  end
  grid_qn = grid_qn or state.seq_grid_qn or 0.25
  if seq_note_has_stutter_span(note, grid_qn) then
    return seq_stutter_span_qn(note, grid_qn)
  end
  local decay_qn = tonumber(note.decay_qn)
  if type(decay_qn) == "number" and decay_qn > 1e-9 then
    return decay_qn
  end
  if not region or not slot then
    return nil
  end
  local _, resolved_sample = seq_resolve_note_sample(note, slot, nil, region, slot.id, step_key)
  local pattern = get_seq_pattern(region.pattern_id, false)
  return seq_effective_note_length_qn(
    region, pattern, slot, slot.id, step_key, note, resolved_sample, grid_qn
  )
end

-- Copy/move keeps the source length when that placement would cross the region end.
function seq_keep_copied_note_over_region(note, length_qn, dest_region, dest_rel)
  if type(note) ~= "table" or not dest_region then
    return
  end
  length_qn = tonumber(length_qn)
  if not length_qn or length_qn <= 1e-9 or seq_note_has_stutter_span(note) then
    return
  end
  local decay_qn = tonumber(note.decay_qn)
  if type(decay_qn) == "number" and decay_qn > 1e-9 then
    return
  end
  local dest_start = (dest_region.start_qn or 0.0) + (tonumber(dest_rel) or 0.0) + (note.offset_qn or 0.0)
  if dest_start + length_qn > seq_region_end_qn(dest_region) + 1e-9 then
    note.decay_qn = length_qn
  end
end

function seq_gap_to_next_hit_qn(region, pattern, track_id, step_idx, note, grid_qn)
  if not region then
    return nil
  end
  local start_qn = seq_note_trigger_qn(region, step_idx, note, grid_qn)
  local end_qn = seq_next_note_trigger_qn(region, pattern, track_id, step_idx, grid_qn, note)
  local region_end = (region.start_qn or 0.0) + get_seq_region_length_qn(region)
  if math.abs(end_qn - region_end) <= 1e-9 then
    return nil
  end
  return math.max((grid_qn or 0.25) * 0.05, end_qn - start_qn)
end

function seq_effective_note_length_qn(region, pattern, slot, track_id, step_idx, note, resolved_sample, grid_qn, hit_idx)
  grid_qn = grid_qn or state.seq_grid_qn or 0.25
  local resolved_path = (resolved_sample and resolved_sample.path)
    or (note and note.frozen_sample_path)
    or (note and note.sample_path)
    or (slot and slot.sample_path)
  local stutter_count = seq_stutter_count(note)
  if stutter_count > 1 then
    local _, _, slice_qn = seq_stutter_hit_span(note, hit_idx or 1, grid_qn)
    if not slice_qn or slice_qn <= 1e-9 then
      slice_qn = (seq_stutter_span_qn(note, grid_qn) or grid_qn) / stutter_count
    end
    return seq_cap_length_to_sample_qn(slice_qn * 0.98, resolved_path, resolved_sample, note)
  end

  local sample_qn = seq_sample_length_qn(resolved_path, resolved_sample)
  if not sample_qn or sample_qn <= 0 then
    sample_qn = grid_qn
  end
  -- Decay mode stores an explicit playback length. Ignore the default
  -- length_qn (one grid cell) which is only a stutter-span placeholder.
  local decay_qn = tonumber(note and note.decay_qn)
  if type(decay_qn) == "number" and decay_qn > 1e-9 then
    return seq_cap_length_to_sample_qn(math.max(grid_qn * 0.05, decay_qn), resolved_path, resolved_sample, note)
  end
  -- Default: full effective length, cropped so it does not overlap the next hit.
  -- Per-track overlap lets the sample ring out over later notes, unless a
  -- copy/move asked to keep items butted against the next start.
  if state.seq_force_item_crop or not (slot and slot.overlap) then
    local gap_qn = seq_gap_to_next_hit_qn(region, pattern, track_id, step_idx, note, grid_qn)
    if gap_qn then
      sample_qn = math.min(sample_qn, gap_qn)
    end
  end
  -- Auto sustain stays inside the region. Explicit decay_qn may cross it.
  sample_qn = seq_cap_length_to_region_end_qn(sample_qn, region, step_idx, note, grid_qn)
  return seq_cap_length_to_sample_qn(sample_qn, resolved_path, resolved_sample, note)
end

SEQ_FADE_SHAPE_COUNT = 7
SEQ_FADE_SHAPE_PX = 14.0
SEQ_FADE_SHAPE_NAMES = {
  [0] = "Linear",
  [1] = "Equal power",
  [2] = "Fast start",
  [3] = "Fast end",
  [4] = "Slow start",
  [5] = "Slow end",
  [6] = "Bezier",
}

function seq_fade_shape_clamp(shape)
  shape = math.floor(tonumber(shape) or 0)
  if shape < 0 then return 0 end
  if shape > 6 then return 6 end
  return shape
end

function seq_fade_shape_name(shape)
  return SEQ_FADE_SHAPE_NAMES[seq_fade_shape_clamp(shape)] or "Linear"
end

SEQ_FADE_CURVE_PX = 52.0
SEQ_FADE_AXIS_PX = 8.0

function seq_fade_curve_clamp(curve)
  curve = tonumber(curve) or 0.0
  if curve < -1.0 then return -1.0 end
  if curve > 1.0 then return 1.0 end
  return curve
end

-- Warp 0..1 by native D_FADEINDIR / D_FADEOUTDIR (-1..1).
function seq_fade_apply_dir(t, dir)
  if t <= 0 then return 0.0 end
  if t >= 1 then return 1.0 end
  dir = seq_fade_curve_clamp(dir)
  if math.abs(dir) < 0.0001 then
    return t
  end
  local k = dir * 2.4
  if k > 0 then
    local e = math.exp(k)
    return (math.exp(k * t) - 1.0) / (e - 1.0)
  end
  k = -k
  local e = math.exp(k)
  return 1.0 - (math.exp(k * (1.0 - t)) - 1.0) / (e - 1.0)
end

-- Native REAPER item-fade shapes (C_FADEINSHAPE / C_FADEOUTSHAPE 0..6).
-- t is 0 at the silent edge and 1 at full level. dir is D_FADEINDIR / D_FADEOUTDIR.
function seq_native_fade_gain(t, shape, dir)
  if t <= 0 then return 0.0 end
  if t >= 1 then return 1.0 end
  shape = seq_fade_shape_clamp(shape)
  local g
  if shape == 1 then
    g = math.sin(t * math.pi * 0.5)
  elseif shape == 2 then
    g = math.sqrt(t)
  elseif shape == 3 then
    g = t * t
  elseif shape == 4 then
    g = t * t * t
  elseif shape == 5 then
    g = 1.0 - (1.0 - t) * (1.0 - t) * (1.0 - t)
  elseif shape == 6 then
    g = t * t * (3.0 - 2.0 * t)
  else
    g = t
  end
  return seq_fade_apply_dir(g, dir)
end

function seq_qn_delta_to_sec(start_qn, delta_qn)
  delta_qn = tonumber(delta_qn) or 0.0
  if delta_qn <= 0 then
    return 0.0
  end
  local t0 = qn_to_time(start_qn or 0.0)
  local t1 = qn_to_time((start_qn or 0.0) + delta_qn)
  if t0 and t1 and t1 > t0 then
    return t1 - t0
  end
  local spq = seq_sec_per_qn
  if not spq or spq <= 0 then
    local a = qn_to_time(0)
    local b = qn_to_time(1)
    if a and b and b > a then
      spq = b - a
    end
  end
  return delta_qn * (spq or 0.5)
end

function seq_note_fade_qn(note, which)
  if type(note) ~= "table" then
    return 0.0
  end
  local v = tonumber(which == "in" and note.fade_in_qn or note.fade_out_qn) or 0.0
  if v < 0 then return 0.0 end
  return v
end

function seq_note_fade_shape(note, which)
  if type(note) ~= "table" then
    return 0
  end
  return seq_fade_shape_clamp(which == "in" and note.fade_in_shape or note.fade_out_shape)
end

function seq_note_fade_curve(note, which)
  if type(note) ~= "table" then
    return 0.0
  end
  return seq_fade_curve_clamp(which == "in" and note.fade_in_curve or note.fade_out_curve)
end

function seq_note_clear_fade_side(note, which)
  if type(note) ~= "table" then
    return false
  end
  local key_qn = (which == "in") and "fade_in_qn" or "fade_out_qn"
  local key_shape = (which == "in") and "fade_in_shape" or "fade_out_shape"
  local key_curve = (which == "in") and "fade_in_curve" or "fade_out_curve"
  local changed = false
  if note[key_qn] ~= nil then note[key_qn] = nil; changed = true end
  if note[key_shape] ~= nil then note[key_shape] = nil; changed = true end
  if note[key_curve] ~= nil then note[key_curve] = nil; changed = true end
  return changed
end

function seq_clamp_note_fades(note, length_qn)
  if type(note) ~= "table" then
    return
  end
  length_qn = math.max(0.0, tonumber(length_qn) or 0.0)
  local fade_in = seq_note_fade_qn(note, "in")
  local fade_out = seq_note_fade_qn(note, "out")
  if fade_in + fade_out > length_qn and (fade_in + fade_out) > 1e-9 then
    local scale = math.max(0.0, length_qn * 0.98) / (fade_in + fade_out)
    fade_in = fade_in * scale
    fade_out = fade_out * scale
  end
  if fade_in < 1e-6 then
    seq_note_clear_fade_side(note, "in")
  else
    note.fade_in_qn = fade_in
  end
  if fade_out < 1e-6 then
    seq_note_clear_fade_side(note, "out")
  else
    note.fade_out_qn = fade_out
  end
end

-- Grow `prefer` ("in"/"out") and shrink the opposite fade if they collide.
function seq_push_note_fades(note, length_qn, prefer)
  if type(note) ~= "table" then
    return
  end
  length_qn = math.max(0.0, tonumber(length_qn) or 0.0)
  local min_keep = math.max(0.0, math.min(0.02, length_qn * 0.02))
  local fade_in = seq_note_fade_qn(note, "in")
  local fade_out = seq_note_fade_qn(note, "out")
  if prefer == "in" then
    fade_in = math.min(fade_in, math.max(0.0, length_qn - min_keep))
    local room = math.max(0.0, length_qn - fade_in - min_keep)
    if fade_out > room then
      fade_out = room
    end
  else
    fade_out = math.min(fade_out, math.max(0.0, length_qn - min_keep))
    local room = math.max(0.0, length_qn - fade_out - min_keep)
    if fade_in > room then
      fade_in = room
    end
  end
  if fade_in < 1e-6 then
    seq_note_clear_fade_side(note, "in")
  else
    note.fade_in_qn = fade_in
  end
  if fade_out < 1e-6 then
    seq_note_clear_fade_side(note, "out")
  else
    note.fade_out_qn = fade_out
  end
end

function seq_note_set_fade(note, which, fade_qn, shape)
  if type(note) ~= "table" then
    return false
  end
  fade_qn = math.max(0.0, tonumber(fade_qn) or 0.0)
  local key_qn = (which == "in") and "fade_in_qn" or "fade_out_qn"
  local key_shape = (which == "in") and "fade_in_shape" or "fade_out_shape"
  local changed = false
  if fade_qn < 1e-6 then
    if seq_note_clear_fade_side(note, which) then
      changed = true
    end
  elseif math.abs((tonumber(note[key_qn]) or 0.0) - fade_qn) > 1e-9 then
    note[key_qn] = fade_qn
    changed = true
  end
  if fade_qn >= 1e-6 and shape ~= nil then
    shape = seq_fade_shape_clamp(shape)
    if note[key_shape] ~= shape then
      note[key_shape] = shape
      changed = true
    end
  end
  return changed
end

function seq_note_set_fade_curve(note, which, curve)
  if type(note) ~= "table" then
    return false
  end
  if seq_note_fade_qn(note, which) < 1e-6 then
    return false
  end
  curve = seq_fade_curve_clamp(curve)
  local key = (which == "in") and "fade_in_curve" or "fade_out_curve"
  local prev = seq_fade_curve_clamp(note[key])
  if math.abs(prev - curve) < 0.0001 then
    return false
  end
  if math.abs(curve) < 0.0001 then
    note[key] = nil
  else
    note[key] = curve
  end
  return true
end

function seq_apply_native_item_fades(item, item_len, fade_in_sec, fade_out_sec, fade_in_shape, fade_out_shape, opts)
  if not item or not item_len or item_len <= 0.0001 then
    return
  end
  opts = opts or {}
  fade_in_sec = math.max(0.0, tonumber(fade_in_sec) or 0.0)
  fade_out_sec = math.max(0.0, tonumber(fade_out_sec) or 0.0)
  if fade_in_sec + fade_out_sec > item_len - 0.0005 then
    local need = fade_in_sec + fade_out_sec + 0.0005
    if need > 0 then
      local scale = math.max(0.0, (item_len - 0.0005) / need)
      fade_in_sec = fade_in_sec * scale
      fade_out_sec = fade_out_sec * scale
    end
  end
  if opts.keep_existing then
    local cur_in = r.GetMediaItemInfo_Value(item, "D_FADEINLEN") or 0.0
    local cur_out = r.GetMediaItemInfo_Value(item, "D_FADEOUTLEN") or 0.0
    if fade_in_sec < cur_in then fade_in_sec = cur_in end
    if fade_out_sec < cur_out then fade_out_sec = cur_out end
  end
  r.SetMediaItemInfo_Value(item, "D_FADEINLEN", fade_in_sec)
  r.SetMediaItemInfo_Value(item, "D_FADEOUTLEN", fade_out_sec)
  pcall(function()
    r.SetMediaItemInfo_Value(item, "D_FADEINLEN_AUTO", 0)
    r.SetMediaItemInfo_Value(item, "D_FADEOUTLEN_AUTO", 0)
  end)
  if fade_in_sec > 0 then
    pcall(function()
      r.SetMediaItemInfo_Value(item, "C_FADEINSHAPE", seq_fade_shape_clamp(fade_in_shape))
      r.SetMediaItemInfo_Value(item, "D_FADEINDIR", seq_fade_curve_clamp(opts.fade_in_curve))
    end)
  end
  if fade_out_sec > 0 then
    pcall(function()
      r.SetMediaItemInfo_Value(item, "C_FADEOUTSHAPE", seq_fade_shape_clamp(fade_out_shape))
      r.SetMediaItemInfo_Value(item, "D_FADEOUTDIR", seq_fade_curve_clamp(opts.fade_out_curve))
    end)
  end
end

function seq_apply_note_native_fades(item, item_len, note, hit_start_qn, apply_in, apply_out, opts)
  if not item then
    return
  end
  local fade_in_qn = (apply_in ~= false) and seq_note_fade_qn(note, "in") or 0.0
  local fade_out_qn = (apply_out ~= false) and seq_note_fade_qn(note, "out") or 0.0
  local fade_in_sec = seq_qn_delta_to_sec(hit_start_qn, fade_in_qn)
  local fade_out_sec = 0.0
  if fade_out_qn > 0 then
    local hit_len_qn = 0.0
    local t0 = qn_to_time(hit_start_qn)
    local t1 = t0 and (t0 + (item_len or 0))
    if t0 and t1 then
      local q1 = time_to_qn(t1)
      if q1 then
        hit_len_qn = math.max(0.0, q1 - (hit_start_qn or 0.0))
      end
    end
    fade_out_sec = seq_qn_delta_to_sec((hit_start_qn or 0.0) + math.max(0.0, hit_len_qn - fade_out_qn), fade_out_qn)
  end
  seq_apply_native_item_fades(
    item, item_len, fade_in_sec, fade_out_sec,
    seq_note_fade_shape(note, "in"), seq_note_fade_shape(note, "out"),
    {
      keep_existing = opts and opts.keep_existing,
      fade_in_curve = (apply_in ~= false) and seq_note_fade_curve(note, "in") or 0.0,
      fade_out_curve = (apply_out ~= false) and seq_note_fade_curve(note, "out") or 0.0,
    }
  )
end

function seq_is_decay_mode()
  return state.seq_note_edit_mode == "decay"
end

function seq_is_decay_def(def)
  return def and def.key == "decay"
end

function seq_is_lock_def(def)
  return def and def.key == "locked"
end

function seq_is_vary_def(def)
  return def and def.key == "sample_vary"
end

function seq_is_vary_filter_def(def)
  return def and def.key == "vary_filter"
end

function seq_is_span_overlay_def(def)
  return seq_is_lock_def(def) or seq_is_vary_filter_def(def)
end

function seq_is_stutter_def(def)
  return def and def.key == "stutter"
end

function seq_note_is_locked(note)
  if type(note) ~= "table" then
    return false
  end
  local v = note.locked
  return v == true or v == 1 or v == 1.0
end

function seq_region_step_key(region, cell_qn, step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local rel = (cell_qn or 0.0) - ((region and region.start_qn) or 0.0)
  return tostring(math.floor((rel / math.max(1e-9, step_qn)) + 0.5))
end

function seq_pattern_locked_cells(pattern, create)
  if not pattern then
    return nil
  end
  if type(pattern.locked_cells) ~= "table" then
    if not create then
      return nil
    end
    pattern.locked_cells = {}
  end
  return pattern.locked_cells
end

function seq_track_locked_cells(pattern, track_id, create)
  local all = seq_pattern_locked_cells(pattern, create)
  if not all then
    return nil
  end
  local key = tostring(track_id)
  if not all[key] then
    if not create then
      return nil
    end
    all[key] = {}
  end
  return all[key]
end

function seq_cell_is_locked(pattern, track_id, step_key)
  local cells = seq_track_locked_cells(pattern, track_id, false)
  return cells and cells[tostring(step_key)] == true
end

function seq_set_cell_locked(pattern, track_id, step_key, locked)
  if not pattern or track_id == nil or step_key == nil then
    return false
  end
  step_key = tostring(step_key)
  if locked then
    local cells = seq_track_locked_cells(pattern, track_id, true)
    if cells[step_key] then
      return false
    end
    cells[step_key] = true
    return true
  end
  local cells = seq_track_locked_cells(pattern, track_id, false)
  if not cells or not cells[step_key] then
    return false
  end
  cells[step_key] = nil
  local empty = true
  for _ in pairs(cells) do
    empty = false
    break
  end
  if empty then
    local all = seq_pattern_locked_cells(pattern, false)
    if all then
      all[tostring(track_id)] = nil
    end
  end
  return true
end

function seq_merge_locked_cell_seen(seen, pattern, track_id)
  seen = seen or {}
  local cells = seq_track_locked_cells(pattern, track_id, false)
  if not cells then
    return seen
  end
  for step_key, v in pairs(cells) do
    if v then
      local idx = tonumber(step_key)
      if idx then
        seen[idx] = true
      end
    end
  end
  return seen
end

function seq_clear_lock_overlays(note)
  if type(note) ~= "table" then
    return
  end
  note.locked_skip = nil
  note.locked_ghosts = nil
  note.locked_humanize_sec = nil
  note.locked_humanize_pitch = nil
  note.locked_humanize_stretch = nil
  note.locked_humanize_len = nil
  note.locked_humanize_fade = nil
  note.locked_vel = nil
  if type(note.stutter_hits) == "table" then
    for _, hit in pairs(note.stutter_hits) do
      if type(hit) == "table" then
        hit.locked_vel = nil
      end
    end
  end
end

-- Snapshot the current live random result so lock keeps that roll instead of
-- falling back to the unvaried painted note.
function seq_bake_note_random(region, track_id, step_key, note)
  if type(note) ~= "table" then
    return false
  end
  local pattern = region and get_seq_pattern(region.pattern_id, false)
  local settings = get_seq_track_settings(pattern, track_id, false) or {}
  local slot = seq_find_slot_by_id(track_id)

  local plays = seq_note_probability_roll(
    region, track_id, step_key,
    settings.probability or 1.0,
    settings.probability_seed or settings.seed or 0
  )
  if plays then
    note.locked_skip = nil
  else
    note.locked_skip = true
  end

  local stut = seq_random_stutter_count(note, region, track_id, step_key)
  if stut > (seq_stutter_count(note) or 1) then
    note.stutter = stut
  end

  local count = math.max(1, seq_stutter_count(note))
  local varies = {}
  for i = 1, count do
    varies[i] = seq_random_vary_amount(note, region, track_id, step_key, i)
  end
  local function freeze_into(target, hit_idx, vary)
    if not (vary and vary > 0.000001) then
      return
    end
    local hit_note = seq_note_for_stutter_hit(note, hit_idx)
    local path, sample = seq_resolve_note_sample(hit_note, slot, vary, region, track_id, step_key)
    if path then
      seq_apply_frozen_sample(target, path, sample, seq_note_vary_origin_path(note, slot, region))
    end
    if (tonumber(target.sample_vary) or 0) <= 0.000001 then
      target.sample_vary = vary
    end
  end
  freeze_into(note, 1, varies[1])
  if count > 1 then
    note.stutter_hits = note.stutter_hits or {}
    for i = 1, count do
      local hit = seq_stutter_hit_table(note, i)
      if type(hit) ~= "table" then
        hit = {}
        note.stutter_hits[i] = hit
      end
      freeze_into(hit, i, varies[i])
    end
  end

  for i = 1, count do
    local base = seq_note_param_value(note, "volume", i) or 1.0
    local abs_qn = seq_note_humanize_abs_qn(region, note, step_key, i)
    local vel = seq_humanize_note_velocity(base, region, track_id, step_key, abs_qn, i)
    if count > 1 then
      local hit = seq_stutter_hit_table(note, i)
      if type(hit) ~= "table" then
        note.stutter_hits = note.stutter_hits or {}
        hit = {}
        note.stutter_hits[i] = hit
      end
      hit.locked_vel = vel
    else
      note.locked_vel = vel
    end
  end

  local ms = tonumber(settings.humanize_ms) or 0.0
  local t_lo, t_hi = seq_humanize_effective_time_ms(settings, ms)
  if math.abs(t_lo) > 0.05 or math.abs(t_hi) > 0.05 then
    note.locked_humanize_sec = seq_humanize_time_offset_sec(
      region, track_id, step_key, ms, settings.humanize_seed or settings.seed
    )
  else
    note.locked_humanize_sec = nil
  end
  if seq_settings_humanize_pitch_active(settings) then
    note.locked_humanize_pitch = seq_humanize_pitch_offset(region, track_id, step_key, 1, { force = true })
  else
    note.locked_humanize_pitch = nil
  end
  if seq_settings_humanize_stretch_active(settings) then
    note.locked_humanize_stretch = seq_humanize_stretch_mul(region, track_id, step_key, 1, { force = true })
  else
    note.locked_humanize_stretch = nil
  end
  if seq_settings_humanize_len_active(settings) then
    note.locked_humanize_len = seq_humanize_length_mul(region, track_id, step_key, 1, { force = true })
    if seq_settings_humanize_fade_active(settings) then
      note.locked_humanize_fade = seq_humanize_fade_out_sec(region, track_id, step_key, 1, { force = true })
    else
      note.locked_humanize_fade = nil
    end
  else
    note.locked_humanize_len = nil
    note.locked_humanize_fade = nil
  end

  if seq_settings_ghost_active(settings) then
    local abs_qn = seq_note_abs_qn(region, note, step_key, state.seq_grid_qn or 0.25)
    local ghosts = {}
    local function bake_ghost(which)
      local do_place, close_qn = seq_ghost_should_place(settings, which, region, track_id, step_key, abs_qn)
      if not do_place then
        return
      end
      ghosts[which] = close_qn
      ghosts[which .. "_vol"] = seq_ghost_pick_volume(settings, which, region, track_id, step_key)
      local vary = seq_ghost_vary_amount(settings, which, region, track_id, step_key)
      if vary > 0.000001 then
        ghosts[which .. "_vary"] = vary
        local gpath, gsample = seq_resolve_note_sample(note, slot, vary, region, track_id, step_key)
        if gpath then
          ghosts[which .. "_path"] = gpath
          ghosts[which .. "_name"] = (gsample and (gsample.name or gsample.path)) or basename(gpath)
        end
      end
    end
    bake_ghost("grace")
    bake_ghost("after")
    if ghosts.grace or ghosts.after then
      note.locked_ghosts = ghosts
    else
      note.locked_ghosts = false
    end
  else
    note.locked_ghosts = nil
  end
  return true
end

function seq_apply_lock_to_step(region, track_id, step_key, lock, note)
  if not region or track_id == nil or step_key == nil then
    return false
  end
  step_key = tostring(step_key)
  local pattern = get_seq_pattern(region.pattern_id, true)
  local changed = false
  note = note or get_seq_note(region, track_id, step_key)
  if type(note) == "table" then
    if lock then
      if not seq_note_is_locked(note) then
        seq_bake_note_random(region, track_id, step_key, note)
      end
    elseif seq_note_is_locked(note) then
      seq_clear_lock_overlays(note)
    end
    if seq_set_note_param_value(note, "locked", lock and 1 or 0) then
      changed = true
    end
    if seq_set_cell_locked(pattern, track_id, step_key, false) then
      changed = true
    end
    return changed
  end
  return seq_set_cell_locked(pattern, track_id, step_key, lock and true or false)
end

function seq_pattern_vary_filters(pattern, create)
  if not pattern then
    return nil
  end
  if type(pattern.vary_filters) ~= "table" then
    if not create then
      return nil
    end
    pattern.vary_filters = {}
  end
  return pattern.vary_filters
end

function seq_track_vary_filters(pattern, track_id, create)
  local all = seq_pattern_vary_filters(pattern, create)
  if not all then
    return nil
  end
  local key = tostring(track_id)
  if not all[key] then
    if not create then
      return nil
    end
    all[key] = {}
  end
  return all[key]
end

function seq_get_cell_vary_filter(pattern, track_id, step_key)
  local cells = seq_track_vary_filters(pattern, track_id, false)
  if not cells then
    return nil
  end
  local text = cells[tostring(step_key)]
  if type(text) ~= "string" then
    return nil
  end
  text = seq_trim_text(text)
  if text == "" then
    return nil
  end
  return text
end

function seq_cell_vary_filter(region, track_id, step_key, note)
  if not region or track_id == nil then
    return nil
  end

  local edit = state.seq_vary_filter_edit
  if edit and tostring(edit.track_id) == tostring(track_id)
      and (edit.region_id == nil or edit.region_id == region.id) then
    local live = seq_trim_text(edit.text)
    if live ~= "" and type(edit.start_qn) == "number" and type(edit.step_qn) == "number" then
      local abs_qn = note and seq_note_abs_qn(region, note, step_key, edit.step_qn) or nil
      if type(abs_qn) == "number" then
        local col = math.floor(((abs_qn - edit.start_qn) / math.max(1e-9, edit.step_qn)) + 1e-9)
        if col >= (edit.col_min or 0) and col <= (edit.col_max or 0) then
          return live
        end
      end
    end
  end

  if note and type(note.vary_filter) == "string" then
    local stamped = seq_trim_text(note.vary_filter)
    if stamped ~= "" then
      return stamped
    end
  end

  local pattern = get_seq_pattern(region.pattern_id, false)
  local cells = seq_track_vary_filters(pattern, track_id, false)
  if not cells then
    return nil
  end

  local function hit(key)
    if key == nil then
      return nil
    end
    local text = cells[tostring(key)]
    if type(text) ~= "string" then
      return nil
    end
    text = seq_trim_text(text)
    if text == "" then
      return nil
    end
    return text
  end

  local text = hit(step_key)
  if text then
    return text
  end

  local grid_qn = state.seq_grid_qn or 0.25
  local offsets = {}
  if note and type(note.qn_offset) == "number" then
    offsets[#offsets + 1] = note.qn_offset
    if type(note.offset_qn) == "number" and math.abs(note.offset_qn) > 1e-9 then
      offsets[#offsets + 1] = note.qn_offset + note.offset_qn
    end
  else
    local n = tonumber(step_key)
    if n then
      offsets[#offsets + 1] = n / 192.0
      offsets[#offsets + 1] = n * grid_qn
    end
  end

  for i = 1, #offsets do
    local qn_off = offsets[i]
    text = hit(math.floor(qn_off / grid_qn + 1e-9)) or hit(math.floor(qn_off / grid_qn + 0.5))
    if text then
      return text
    end
    for key, raw in pairs(cells) do
      local idx = tonumber(key)
      if idx and type(raw) == "string" then
        local lo = idx * grid_qn
        if qn_off >= lo - 1e-9 and qn_off < lo + grid_qn - 1e-9 then
          local found = seq_trim_text(raw)
          if found ~= "" then
            return found
          end
        end
      end
    end
  end

  return nil
end

function seq_set_cell_vary_filter(pattern, track_id, step_key, filter_text)
  if not pattern or track_id == nil or step_key == nil then
    return false
  end
  step_key = tostring(step_key)
  filter_text = seq_trim_text(filter_text)
  if filter_text == "" then
    local cells = seq_track_vary_filters(pattern, track_id, false)
    if not cells or cells[step_key] == nil then
      return false
    end
    cells[step_key] = nil
    local empty = true
    for _ in pairs(cells) do
      empty = false
      break
    end
    if empty then
      local all = seq_pattern_vary_filters(pattern, false)
      if all then
        all[tostring(track_id)] = nil
      end
    end
    return true
  end
  local cells = seq_track_vary_filters(pattern, track_id, true)
  if cells[step_key] == filter_text then
    return false
  end
  cells[step_key] = filter_text
  return true
end

function seq_stamp_notes_in_filter_range(region, track_id, col_min, col_max, start_qn, step_qn, filter_text)
  if not region or track_id == nil then
    return false
  end
  local pattern = get_seq_pattern(region.pattern_id, false)
  local notes = get_track_note_table(pattern, track_id, false)
  if not notes then
    return false
  end
  filter_text = seq_trim_text(filter_text)
  if filter_text == "" then
    filter_text = nil
  end
  local changed = false
  for step_key, note in pairs(notes) do
    if type(note) == "table" then
      local qn_off = (type(note.qn_offset) == "number") and note.qn_offset
        or ((tonumber(step_key) or 0) / 192.0)
      local vis = (region.start_qn or 0.0) + qn_off + (note.offset_qn or 0.0)
      local col = math.floor(((vis - (start_qn or 0.0)) / math.max(1e-9, step_qn or 0.25)) + 1e-9)
      if col >= col_min and col <= col_max then
        if note.vary_filter ~= filter_text then
          note.vary_filter = filter_text
          changed = true
        end
        if not seq_note_is_locked(note) and seq_note_has_frozen_sample(note) then
          seq_clear_frozen_sample(note)
          changed = true
        end
      end
    end
  end
  return changed
end

function seq_apply_vary_filter_range(region, track_id, col_min, col_max, start_qn, step_qn, filter_text)
  if not region or track_id == nil then
    return false
  end
  local pattern = get_seq_pattern(region.pattern_id, true)
  if not pattern then
    return false
  end
  local region_start = region.start_qn or 0.0
  local region_end = region_start + get_seq_region_length_qn(region)
  local changed = false
  for col = col_min, col_max do
    local cell_qn = start_qn + col * step_qn
    if cell_qn >= region_start - 1e-9 and cell_qn < region_end - 1e-9 then
      local step_key = seq_region_step_key(region, cell_qn, step_qn)
      if seq_set_cell_vary_filter(pattern, track_id, step_key, filter_text) then
        changed = true
      end
    end
  end
  if seq_stamp_notes_in_filter_range(region, track_id, col_min, col_max, start_qn, step_qn, filter_text) then
    changed = true
  end
  return changed
end

function seq_cancel_vary_filter_edit()
  state.seq_vary_filter_edit = nil
end

function seq_begin_vary_filter_edit(region, track_id, col_min, col_max, start_qn, step_qn, text, orig)
  if not region or track_id == nil then
    return
  end
  col_min = math.min(col_min or 0, col_max or 0)
  col_max = math.max(col_min, col_max or col_min)
  state.seq_vary_filter_edit = {
    region_id = region.id,
    track_id = track_id,
    col_min = col_min,
    col_max = col_max,
    start_qn = start_qn,
    step_qn = step_qn,
    text = text or "",
    orig = orig,
    focus = true,
    hovered = false,
  }
end

function seq_commit_vary_filter_edit()
  local edit = state.seq_vary_filter_edit
  if not edit then
    return false
  end
  local region = get_seq_region_by_id(edit.region_id)
  local text = seq_trim_text(edit.text)
  state.seq_vary_filter_edit = nil
  if not region then
    return false
  end
  if text == (edit.orig or "") then
    return false
  end
  local label = begin_seq_undo(text ~= "" and "Set sequencer vary filter" or "Clear sequencer vary filter")
  local changed = seq_apply_vary_filter_range(
    region, edit.track_id, edit.col_min, edit.col_max, edit.start_qn, edit.step_qn, text
  )
  if changed then
    local slot = seq_find_slot_by_id(edit.track_id)
    if slot then
      sync_seq_pattern_track(region.pattern_id, slot, { force_rebuild = true })
    else
      sync_seq_pattern_regions(region.pattern_id)
    end
    if seq_schedule_ingest_save then
      seq_schedule_ingest_save()
    else
      save_config()
    end
  end
  end_seq_undo(label)
  return changed
end

function seq_vary_filter_edit_blocks_clicks()
  local edit = state.seq_vary_filter_edit
  return edit and edit.hovered == true
end

function seq_apply_lock_range(region, track_id, col_min, col_max, start_qn, step_qn, lock, active_cells)
  if not region or track_id == nil then
    return false
  end
  local region_start = region.start_qn or 0.0
  local region_end = region_start + get_seq_region_length_qn(region)
  local changed = false
  for col = col_min, col_max do
    local cell_qn = start_qn + col * step_qn
    if cell_qn >= region_start - 1e-9 and cell_qn < region_end - 1e-9 then
      local active = active_cells and active_cells[track_id] and active_cells[track_id][col]
      local applied_note = false
      if active then
        seq_for_each_active_note(active, function(entry)
          if entry.region_id and entry.region_id ~= region.id then
            return
          end
          if seq_apply_lock_to_step(region, track_id, entry.key, lock, entry.note) then
            changed = true
          end
          applied_note = true
        end)
      end
      if not applied_note then
        local step_key = seq_region_step_key(region, cell_qn, step_qn)
        if seq_apply_lock_to_step(region, track_id, step_key, lock, nil) then
          changed = true
        end
      end
    end
  end
  return changed
end

function insert_seq_note_hit(tr, region, track_id, step_key, note, resolved_path, hit_start_qn, hit_length_qn, humanize_ms, random_seed, resolved_sample, opts)
  opts = opts or {}
  local start_time = qn_to_time(hit_start_qn)
  local end_time = qn_to_time(hit_start_qn + hit_length_qn)
  if not start_time or not end_time or end_time <= start_time then
    return nil
  end

  local item_len = end_time - start_time
  local dt = seq_humanize_time_offset_sec(region, track_id, step_key, humanize_ms, random_seed)
  if dt ~= 0.0 then
    start_time = math.max(0.0, start_time + dt)
  end
  local time_offset = opts.time_offset_sec or 0.0
  if time_offset > 0.0 then
    start_time = start_time + time_offset
    item_len = item_len - time_offset
  end
  if opts.length_sec and opts.length_sec > 0 then
    item_len = math.min(item_len, opts.length_sec)
  end
  local max_len_sec = seq_sample_source_length_sec(resolved_path, resolved_sample)
  local startoffs = opts.startoffs
  if startoffs == nil then
    startoffs = get_sample_start_offset(resolved_sample)
  end
  local stretch = seq_note_stretch_amount(note)
  if not opts.ghost then
    stretch = stretch * seq_humanize_stretch_mul(region, track_id, step_key, opts.hit_idx)
    if stretch < SEQ_STRETCH_MIN then stretch = SEQ_STRETCH_MIN end
    if stretch > SEQ_STRETCH_MAX then stretch = SEQ_STRETCH_MAX end
  end
  if max_len_sec and max_len_sec > 0 then
    local remaining0 = math.max(0.001, max_len_sec - startoffs)
    startoffs = startoffs + seq_note_start_frac(note) * remaining0
    if startoffs > max_len_sec - 0.001 then
      startoffs = max_len_sec - 0.001
    end
    local remaining = math.max(0.001, max_len_sec - startoffs)
    -- Stretch longer keeps the current end; stretch shorter may pull it in.
    item_len = math.min(item_len, remaining, remaining * stretch)
  end
  local len_mul = 1.0
  if not opts.ghost then
    len_mul = seq_humanize_length_mul(region, track_id, step_key, opts.hit_idx)
    if len_mul < 0.9995 then
      item_len = math.max(0.002, item_len * len_mul)
    end
  end
  local fade_in = opts.fade_in or 0.0
  local fade_out = opts.fade_out or 0.0
  if item_len < fade_in + fade_out + 0.001 then
    local need = fade_in + fade_out + 0.001
    if item_len < 0.002 then
      return nil
    end
    if need > item_len then
      local scale = item_len / need
      fade_in = fade_in * scale
      fade_out = fade_out * scale
    end
  end
  if item_len <= 0.000001 then
    return nil
  end

  local item = r.AddMediaItemToTrack(tr)
  if not item then
    return nil
  end
  r.SetMediaItemPosition(item, start_time, false)
  r.SetMediaItemLength(item, item_len, false)

  local take = r.AddTakeToMediaItem(item)
  if take then
    local src = seq_pcm_take_src_get(resolved_path)
    if src then
      r.SetMediaItemTake_Source(take, src)
      set_item_name(item, take, resolved_path)
      apply_seq_note_params(item, take, note)
      if not opts.ghost then
        local pitch = (tonumber(note.pitch) or 0.0) + seq_humanize_pitch_offset(region, track_id, step_key, opts.hit_idx)
        if pitch < -24.0 then pitch = -24.0 elseif pitch > 24.0 then pitch = 24.0 end
        r.SetMediaItemTakeInfo_Value(take, "D_PITCH", pitch)
        r.SetMediaItemTakeInfo_Value(take, "D_PLAYRATE", 1.0 / stretch)
      end
      seq_apply_drum_rubber_band_stretch(take, stretch, resolved_sample, find_seq_track_by_id(track_id))
      if startoffs > 0 then
        r.SetMediaItemTakeInfo_Value(take, "D_STARTOFFS", startoffs)
      end
    end
  end

  set_item_ext(item, SEQ_EXT_FLAG, "1")
  set_item_ext(item, SEQ_EXT_REGION, region.id)
  set_item_ext(item, SEQ_EXT_PATTERN, region.pattern_id)
  set_item_ext(item, SEQ_EXT_TRACK, track_id)
  set_item_ext(item, SEQ_EXT_STEP, step_key)
  if opts.layer_piece then
    set_item_ext(item, SEQ_EXT_LAYER, "1")
  end
  if opts.ghost then
    set_item_ext(item, SEQ_EXT_GHOST, tostring(opts.ghost))
  end
  -- Assigning source / stretching item length can re-enable loop; force off last.
  r.SetMediaItemInfo_Value(item, "B_LOOPSRC", 0)
  if not seq_defer_item_updates and r.UpdateItemInProject then
    r.UpdateItemInProject(item)
  end
  seq_mark_self_arrange_write()

  -- Apply drum envelope last so earlier item/chunk writes can't wipe it.
  if take then
    local slot = find_seq_track_by_id(track_id)
    if slot then
      seq_normalize_slot_mix(slot)
      seq_apply_take_volume_envelope(take, item_len, slot.env, opts.time_offset_sec or 0.0)
    end
  end
  -- Volume last: item stays at 1, take is note velocity * blend.
  local scale = opts.vol_scale
  if scale == nil then scale = 1.0 end
  if take then
    local vel = tonumber(note.volume) or 1.0
    if opts.layer_piece and vel < 0.1 then vel = 1.0 end
    local pattern = region and get_seq_pattern(region.pattern_id, false)
    local vel_settings = get_seq_track_settings(pattern, track_id, false)
    -- Previous humanize bake-in drove stored level to 0; restore unity so
    -- further tweaks can be heard instead of staying at -inf.
    if vel < 0.08 and (not opts.ghost) and seq_settings_vel_humanize_active(vel_settings) then
      vel = 1.0
      if type(note) == "table" then
        note.volume = 1.0
      end
    end
    if not opts.ghost then
      vel = seq_humanize_note_velocity(vel, region, track_id, step_key, hit_start_qn, opts.hit_idx)
    end
    r.SetMediaItemInfo_Value(item, "D_VOL", 1.0)
    r.SetMediaItemTakeInfo_Value(take, "D_VOL", vel * scale * get_sample_gain(resolved_sample))
  end
  if opts.layer_piece then
    seq_item_apply_layer_fades(item, fade_in, fade_out)
  end
  local apply_in = opts.note_fade_in
  local apply_out = opts.note_fade_out
  if apply_in == nil then apply_in = true end
  if apply_out == nil then apply_out = true end
  if apply_in or apply_out then
    seq_apply_note_native_fades(
      item, item_len, note, hit_start_qn, apply_in, apply_out,
      { keep_existing = opts.layer_piece and true or false }
    )
  end
  if not opts.ghost and len_mul < 0.9995 then
    local fade_sec = seq_humanize_fade_out_sec(region, track_id, step_key, opts.hit_idx)
    if fade_sec > 0.0005 then
      local cur_in = r.GetMediaItemInfo_Value(item, "D_FADEINLEN") or 0.0
      seq_apply_native_item_fades(
        item, item_len, cur_in, fade_sec,
        r.GetMediaItemInfo_Value(item, "C_FADEINSHAPE"),
        r.GetMediaItemInfo_Value(item, "C_FADEOUTSHAPE"),
        { keep_existing = true }
      )
    end
  end
  return item
end

function seq_insert_note_ghosts(tr, region, slot, track_id, step_key, note, path, sample, settings, first_qn, first_len, last_qn, last_len)
  if not tr or not first_qn then
    return
  end
  last_qn = last_qn or first_qn
  first_len = first_len or (state.seq_grid_qn or 0.25)
  last_len = last_len or first_len
  local function place(which, start_qn, close_qn, vary_amt, frozen_path, frozen_name, vol_mul)
    local ghost_len = math.max(0.03, math.min(close_qn * 1.35, first_len * 0.45))
    vary_amt = tonumber(vary_amt) or 0.0
    local gpath, gsample = path, sample
    if type(frozen_path) == "string" and frozen_path ~= "" and seq_path_exists(frozen_path) then
      gpath = frozen_path
      gsample = find_sample_by_path(frozen_path) or { name = frozen_name, path = frozen_path }
    elseif vary_amt > 0.000001 then
      local vpath, vsample = seq_resolve_note_sample(note, slot, vary_amt, region, track_id, step_key)
      if vpath then
        gpath, gsample = vpath, vsample
      end
    end
    local mul = tonumber(vol_mul)
    if mul == nil then
      mul = seq_ghost_pick_volume(settings, which, region, track_id, step_key)
    end
    local ghost_note = {
      volume = math.max(0.0, (tonumber(note.volume) or 1.0) * mul),
      pan = note.pan or 0.0,
      pitch = note.pitch or 0.0,
      sample_path = note.sample_path,
      sample_vary = vary_amt,
      stutter = 1,
    }
    insert_seq_note_hit(
      tr, region, track_id, step_key, ghost_note, gpath,
      start_qn, ghost_len,
      0.0, 0,
      gsample,
      {
        ghost = which,
        vol_scale = 1.0,
        note_fade_in = true,
        note_fade_out = true,
        hit_idx = (which == "after") and 90 or 0,
      }
    )
  end
  if seq_note_is_locked(note) then
    local g = note.locked_ghosts
    if type(g) ~= "table" then
      return
    end
    if g.grace then
      place("grace", first_qn - g.grace, g.grace, g.grace_vary, g.grace_path, g.grace_name, g.grace_vol)
    end
    if g.after then
      place("after", last_qn + math.max(0.02, g.after * 0.35), g.after, g.after_vary, g.after_path, g.after_name, g.after_vol)
    end
    return
  end
  if not seq_settings_ghost_active(settings) then
    return
  end
  local abs_qn = seq_note_abs_qn(region, note, step_key, state.seq_grid_qn or 0.25) or first_qn
  local do_grace, grace_qn = seq_ghost_should_place(settings, "grace", region, track_id, step_key, abs_qn)
  if do_grace then
    place("grace", first_qn - grace_qn, grace_qn, seq_ghost_vary_amount(settings, "grace", region, track_id, step_key))
  end
  local do_after, after_qn = seq_ghost_should_place(settings, "after", region, track_id, step_key, abs_qn)
  if do_after then
    place("after", last_qn + math.max(0.02, after_qn * 0.35), after_qn, seq_ghost_vary_amount(settings, "after", region, track_id, step_key))
  end
end

function insert_seq_note_item(region, slot, track_id, step_key, note)
  if not region or not slot or not note then
    return nil
  end

  local resolved_path, resolved_sample = seq_resolve_note_sample(
    note, slot, seq_random_vary_amount(note, region, track_id, step_key, 1),
    region, track_id, step_key
  )
  if not resolved_path then
    return nil
  end
  if not seq_path_exists(resolved_path) then
    log("Sequencer sample missing: " .. tostring(resolved_path))
    return nil
  end

  local tr = get_seq_slot_target_track(slot)
  if not tr then
    log("No target track for sequencer note")
    return nil
  end

  local pattern = get_seq_pattern(region.pattern_id, false)
  local track_settings = get_seq_track_settings(pattern, track_id, false) or {}
  local probability = track_settings.probability or 1.0
  local probability_seed = track_settings.probability_seed or track_settings.seed or 0
  local humanize_seed = track_settings.humanize_seed or track_settings.seed or 0
  if not seq_note_passes_probability(region, track_id, step_key, probability, probability_seed) then
    return nil
  end

  local grid_qn = state.seq_grid_qn or 0.25
  local stutter_count = seq_random_stutter_count(note, region, track_id, step_key)
  local step_idx = tonumber(step_key) or 0
  if not seq_note_in_region(region, note, step_key, grid_qn) then
    return nil
  end
  local cell_start_qn = seq_note_abs_qn(region, note, step_key, grid_qn)
  local groove_qn = seq_groove_offset_qn(cell_start_qn, get_seq_region_groove(region))
  local humanize_ms = track_settings.humanize_ms or 0.0

  local first_item = nil
  local first_start_qn, first_len_qn, last_start_qn, last_len_qn
  local pieces = (seq_layering_is_active and seq_layering_is_active(slot))
    and seq_layering_build_pieces(slot) or {}
  for i = 0, stutter_count - 1 do
    local hit_idx = i + 1
    local hit_note = seq_note_for_stutter_hit(note, hit_idx)
    local vary_amt = seq_random_vary_amount(hit_note, region, track_id, step_key, hit_idx)
    local hit_path, hit_sample = seq_resolve_note_sample(hit_note, slot, vary_amt, region, track_id, step_key)
    if not hit_path then
      hit_path, hit_sample = resolved_path, resolved_sample
    end
    local hit_len_qn = seq_effective_note_length_qn(
      region, pattern, slot, track_id, step_idx, note, hit_sample, grid_qn, hit_idx
    )
    local hit_offset = hit_note.offset_qn or 0.0
    local off0 = seq_stutter_hit_span(note, hit_idx, grid_qn)
    local hit_start_qn = cell_start_qn + groove_qn + hit_offset + (off0 or 0.0)
    if hit_start_qn < 0.0 then hit_start_qn = 0.0 end
    local apply_fade_in = (i == 0)
    local apply_fade_out = (i == stutter_count - 1)
    if #pieces > 0 then
      for p = 1, #pieces do
        local piece = pieces[p]
        if piece.path and seq_path_exists(piece.path) then
          local item = insert_seq_note_hit(
            tr, region, track_id, step_key, hit_note, piece.path,
            hit_start_qn, hit_len_qn,
            (i == 0) and humanize_ms or 0.0,
            humanize_seed,
            piece.sample,
            {
              layer_piece = true,
              startoffs = piece.startoffs or 0.0,
              length_sec = piece.length_sec,
              vol_scale = piece.weight or 1.0,
              time_offset_sec = piece.time_offset_sec or 0.0,
              fade_in = piece.fade_in or 0.0,
              fade_out = piece.fade_out or 0.0,
              note_fade_in = apply_fade_in and (p == 1),
              note_fade_out = apply_fade_out and (p == #pieces),
              hit_idx = hit_idx,
            }
          )
          if item and not first_item then
            first_item = item
          end
        end
      end
    else
      local item = insert_seq_note_hit(
        tr, region, track_id, step_key, hit_note, hit_path,
        hit_start_qn, hit_len_qn,
        (i == 0) and humanize_ms or 0.0,
        humanize_seed,
        hit_sample,
        {
          note_fade_in = apply_fade_in,
          note_fade_out = apply_fade_out,
          hit_idx = hit_idx,
        }
      )
      if item and not first_item then
        first_item = item
      end
    end
    if i == 0 then
      first_start_qn = hit_start_qn
      first_len_qn = hit_len_qn
    end
    last_start_qn = hit_start_qn
    last_len_qn = hit_len_qn
  end
  seq_insert_note_ghosts(
    tr, region, slot, track_id, step_key, note,
    resolved_path, resolved_sample, track_settings,
    first_start_qn, first_len_qn, last_start_qn, last_len_qn
  )
  return first_item
end

function remove_seq_rendered_items_for_track(region, slot, track_id)
  if not region then
    return 0
  end
  local region_id = region.id
  local track_key = tostring(track_id)
  local removed = 0
  local function scan_track(tr)
    if not tr then
      return
    end
    for item_idx = r.CountTrackMediaItems(tr) - 1, 0, -1 do
      local item = r.GetTrackMediaItem(tr, item_idx)
      if item and seq_item_is_owned(item, region_id)
         and tostring(get_item_ext(item, SEQ_EXT_TRACK) or "") == track_key then
        if r.DeleteTrackMediaItem(tr, item) then
          removed = removed + 1
        end
      end
    end
  end
  local tr = slot and get_seq_slot_target_track(slot)
  if tr then
    scan_track(tr)
  else
    for tr_idx = 0, r.CountTracks(0) - 1 do
      scan_track(r.GetTrack(0, tr_idx))
    end
  end
  if removed > 0 then
    seq_mark_self_arrange_write()
  end
  return removed
end

function remove_seq_rendered_items_for_step(region, slot, track_id, step_key)
  if not region then
    return 0
  end
  local region_id = region.id
  local track_key = tostring(track_id)
  local step = tostring(step_key)
  local removed = 0
  local function scan_track(tr)
    if not tr then
      return
    end
    for item_idx = r.CountTrackMediaItems(tr) - 1, 0, -1 do
      local item = r.GetTrackMediaItem(tr, item_idx)
      if item and seq_item_is_owned(item, region_id)
         and tostring(get_item_ext(item, SEQ_EXT_TRACK) or "") == track_key
         and tostring(get_item_ext(item, SEQ_EXT_STEP) or "") == step then
        if r.DeleteTrackMediaItem(tr, item) then
          removed = removed + 1
        end
      end
    end
  end
  local tr = slot and get_seq_slot_target_track(slot)
  if tr then
    scan_track(tr)
  else
    for tr_idx = 0, r.CountTracks(0) - 1 do
      scan_track(r.GetTrack(0, tr_idx))
    end
  end
  if removed > 0 then
    seq_mark_self_arrange_write()
  end
  return removed
end

function seq_prune_stale_region_items(region)
  if not region then
    return 0
  end
  local region_id = region.id
  local grid_qn = (type(state.seq_grid_qn) == "number" and state.seq_grid_qn > 0) and state.seq_grid_qn or 0.25
  local removed = 0
  local tr_count = r.CountTracks(0)
  for tr_idx = 0, tr_count - 1 do
    local tr = r.GetTrack(0, tr_idx)
    for item_idx = r.CountTrackMediaItems(tr) - 1, 0, -1 do
      local item = r.GetTrackMediaItem(tr, item_idx)
      if item and seq_item_is_owned(item, region_id) then
        local step = tostring(get_item_ext(item, SEQ_EXT_STEP) or "")
        local track_id = tonumber(get_item_ext(item, SEQ_EXT_TRACK) or "")
          or get_item_ext(item, SEQ_EXT_TRACK)
        local note = (step ~= "" and track_id) and get_seq_note(region, track_id, step) or nil
        if not note or not seq_note_in_region(region, note, step, grid_qn) then
          if r.DeleteTrackMediaItem(tr, item) then
            removed = removed + 1
          end
        end
      end
    end
  end
  if removed > 0 then
    seq_mark_self_arrange_write()
  end
  return removed
end

-- Swap take sources on existing hits when the item layout is unchanged.
-- Returns false if the track must be deleted and rebuilt instead.
function seq_retarget_region_track_sources(region, slot)
  if not region or not slot or not slot.sample_path then
    return false
  end
  if seq_layering_is_active and seq_layering_is_active(slot) then
    return false
  end
  local tr = get_seq_slot_target_track(slot)
  if not tr then
    return false
  end
  local pattern = get_seq_pattern(region.pattern_id, false)
  if not pattern then
    return false
  end
  local track_notes = get_track_note_table(pattern, slot.id, false)
  if not track_notes then
    return false
  end

  local region_id = region.id
  local track_key = tostring(slot.id)
  local items_by_step = {}
  local item_n = 0
  for item_idx = 0, r.CountTrackMediaItems(tr) - 1 do
    local item = r.GetTrackMediaItem(tr, item_idx)
    if item and seq_item_is_owned(item, region_id)
       and tostring(get_item_ext(item, SEQ_EXT_TRACK) or "") == track_key then
      if seq_item_is_aux_piece(item) then
        return false
      end
      local step = tostring(get_item_ext(item, SEQ_EXT_STEP) or "")
      local list = items_by_step[step]
      if not list then
        list = {}
        items_by_step[step] = list
      end
      list[#list + 1] = item
      item_n = item_n + 1
    end
  end

  local track_settings = get_seq_track_settings(pattern, slot.id, false) or {}
  if seq_settings_vary_active(track_settings) or seq_settings_stutter_active(track_settings)
     or seq_settings_ghost_active(track_settings) then
    return false
  end
  local probability = track_settings.probability or 1.0
  local probability_seed = track_settings.probability_seed or track_settings.seed or 0
  local expected = {}
  local expected_hits = 0
  for step_key, note in pairs(track_notes) do
    if type(note) == "table" and note.enabled ~= false
       and seq_note_in_region(region, note, step_key)
       and seq_note_passes_probability(region, slot.id, step_key, probability, probability_seed) then
      if seq_note_has_hit_sample_vary(note) then
        return false
      end
      local stutter = seq_stutter_count(note)
      expected[tostring(step_key)] = { note = note, hits = stutter }
      expected_hits = expected_hits + stutter
    end
  end
  if expected_hits ~= item_n then
    return false
  end
  for step, info in pairs(expected) do
    local items = items_by_step[step]
    if not items or #items ~= info.hits then
      return false
    end
  end
  for step, _ in pairs(items_by_step) do
    if not expected[step] then
      return false
    end
  end

  local grid_qn = state.seq_grid_qn or 0.25
  if seq_normalize_slot_mix then
    seq_normalize_slot_mix(slot)
  end

  seq_pcm_take_src_begin()
  local ok = true
  for step, info in pairs(expected) do
    if not ok then
      break
    end
    local note = info.note
    local resolved_path, resolved_sample = seq_resolve_note_sample(note, slot, nil, region, slot.id, step)
    if not resolved_path or not seq_path_exists(resolved_path) then
      ok = false
      break
    end
    local max_len = seq_sample_source_length_sec(resolved_path, resolved_sample)
    local step_idx = tonumber(step) or 0
    local hit_len_qn = seq_effective_note_length_qn(
      region, pattern, slot, slot.id, step_idx, note, resolved_sample, grid_qn
    )
    local items = items_by_step[step]
    for i = 1, #items do
      local item = items[i]
      local take = r.GetActiveTake(item)
      local src = take and seq_pcm_take_src_get(resolved_path)
      if not take or not src then
        ok = false
        break
      end
      r.SetMediaItemTake_Source(take, src)
      set_item_name(item, take, resolved_path)
      r.SetMediaItemTakeInfo_Value(take, "D_STARTOFFS", 0.0)
      local pos = r.GetMediaItemInfo_Value(item, "D_POSITION")
      local old_len = r.GetMediaItemInfo_Value(item, "D_LENGTH")
      local pos_qn = time_to_qn(pos)
      local item_len = nil
      if pos_qn and hit_len_qn then
        local end_time = qn_to_time(pos_qn + hit_len_qn)
        if end_time and end_time > pos then
          item_len = end_time - pos
        end
      end
      if item_len and max_len and max_len > 0 then
        item_len = math.min(item_len, max_len)
      end
      if item_len and item_len > 0.000001 then
        r.SetMediaItemLength(item, item_len, false)
        if math.abs((old_len or 0) - item_len) > 0.0001 then
          seq_apply_take_volume_envelope(take, item_len, slot.env, 0.0)
        end
      end
      seq_apply_note_native_fades(
        item, item_len or old_len, note, pos_qn or 0.0, i == 1, i == #items
      )
      r.SetMediaItemInfo_Value(item, "B_LOOPSRC", 0)
      if r.UpdateItemInProject then
        r.UpdateItemInProject(item)
      end
    end
  end
  seq_pcm_take_src_end()
  if not ok then
    return false
  end
  seq_mark_self_arrange_write()
  return true
end

function sync_seq_region_track(region, slot, opts)
  opts = opts or {}
  if not region or not slot then
    return
  end
  local own_refresh = not opts.skip_arrange
  if own_refresh and r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  local retargeted = (not opts.force_rebuild) and seq_retarget_region_track_sources(region, slot)
  if not retargeted then
    remove_seq_rendered_items_for_track(region, slot, slot.id)
    local pattern = get_seq_pattern(region.pattern_id, false)
    local track_notes = pattern and get_track_note_table(pattern, slot.id, false)
    if track_notes then
      seq_pcm_take_src_begin()
      local prev_defer = seq_defer_item_updates
      seq_defer_item_updates = true
      for step_key, note in pairs(track_notes) do
        if type(note) == "table" and note.enabled ~= false
           and seq_note_in_region(region, note, step_key) then
          insert_seq_note_item(region, slot, slot.id, step_key, note)
        end
      end
      seq_defer_item_updates = prev_defer
      seq_pcm_take_src_end()
    end
  end
  if own_refresh and r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  if not opts.skip_arrange then
    r.UpdateArrange()
  end
end

function sync_seq_pattern_track(pattern_id, slot, opts)
  if not pattern_id or not slot then
    return
  end
  opts = opts or {}
  local own_refresh = not opts.skip_arrange
  if own_refresh and r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  for _, region in ipairs(state.seq_regions) do
    if region.pattern_id == pattern_id then
      sync_seq_region_track(region, slot, {
        skip_arrange = true,
        force_rebuild = opts.force_rebuild,
      })
    end
  end
  if own_refresh and r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  if not opts.skip_arrange then
    r.UpdateArrange()
  end
end

function sync_seq_slot_all_regions(slot, opts)
  if not slot then
    return
  end
  opts = opts or {}
  local own_refresh = not opts.skip_arrange
  if own_refresh and r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  for _, region in ipairs(state.seq_regions or {}) do
    sync_seq_region_track(region, slot, {
      skip_arrange = true,
      force_rebuild = opts.force_rebuild,
    })
  end
  if own_refresh and r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  if not opts.skip_arrange then
    r.UpdateArrange()
  end
end

function seq_previous_step_key(pattern, track_id, step_key, region)
  local track_notes = get_track_note_table(pattern, track_id, false)
  if not track_notes then
    return nil
  end
  local target = track_notes[tostring(step_key)]
  local target_qn = seq_note_qn_offset(target, step_key)
  local prev_key = nil
  local prev_qn = nil
  for sk, nnote in pairs(track_notes) do
    if type(nnote) == "table" and nnote.enabled ~= false then
      local qn = seq_note_qn_offset(nnote, sk)
      if qn < target_qn - 1e-9 and (not prev_qn or qn > prev_qn) then
        prev_qn = qn
        prev_key = tostring(sk)
      end
    end
  end
  return prev_key
end

function sync_seq_single_note(region, slot, step_key, opts)
  opts = opts or {}
  if not region or not slot then
    return
  end
  step_key = tostring(step_key)
  local note = get_seq_note(region, slot.id, step_key)
  remove_seq_rendered_items_for_step(region, slot, slot.id, step_key)
  if note and note.enabled ~= false and seq_note_in_region(region, note, step_key) then
    insert_seq_note_item(region, slot, slot.id, step_key, note)
  end
  if not opts.skip_neighbor and (state.seq_force_item_crop or not slot.overlap) then
    local pattern = get_seq_pattern(region.pattern_id, false)
    local prev_key = seq_previous_step_key(pattern, slot.id, step_key, region)
    if prev_key and prev_key ~= step_key then
      local prev_note = get_seq_note(region, slot.id, prev_key)
      remove_seq_rendered_items_for_step(region, slot, slot.id, prev_key)
      if prev_note and prev_note.enabled ~= false and seq_note_in_region(region, prev_note, prev_key) then
        insert_seq_note_item(region, slot, slot.id, prev_key, prev_note)
      end
    end
  end
end

function sync_seq_pattern_note(pattern_id, slot, step_key, opts)
  if not pattern_id or not slot then
    return
  end
  for _, region in ipairs(state.seq_regions) do
    if region.pattern_id == pattern_id then
      sync_seq_single_note(region, slot, step_key, opts)
    end
  end
end

function sync_seq_region(region, opts)
  if not region then
    return
  end
  opts = opts or {}
  if not opts.skip_cache_clear then
    clear_seq_vary_rank_cache()
  end
  if not opts.skip_remove then
    remove_seq_rendered_items(region)
  end

  local pattern = get_seq_pattern(region.pattern_id, false)
  if not pattern or type(pattern.notes) ~= "table" then
    seq_sync_region_parent_item(region)
    if not opts.skip_arrange then
      r.UpdateArrange()
    end
    return
  end

  local own_refresh = not opts.skip_arrange
  if own_refresh and r.PreventUIRefresh then r.PreventUIRefresh(1) end
  local prev_defer = seq_defer_item_updates
  seq_defer_item_updates = true
  seq_pcm_take_src_begin()
  for _, slot in ipairs(state.seq_tracks) do
    seq_normalize_slot_mix(slot)
    if not opts.skip_mix then
      seq_apply_slot_mix_to_reaper_track(slot)
    end
    local track_notes = get_track_note_table(pattern, slot.id, false)
    if track_notes then
      for step_key, note in pairs(track_notes) do
        if type(note) == "table" and note.enabled ~= false
           and seq_note_in_region(region, note, step_key) then
          insert_seq_note_item(region, slot, slot.id, step_key, note)
        end
      end
    end
  end
  seq_pcm_take_src_end()
  seq_defer_item_updates = prev_defer
  if own_refresh and r.PreventUIRefresh then r.PreventUIRefresh(-1) end
  seq_sync_region_parent_item(region)
  if not opts.skip_arrange then
    r.UpdateArrange()
  end
end

function sync_seq_pattern_regions(pattern_id)
  local pid = tonumber(pattern_id) or pattern_id
  for _, region in ipairs(state.seq_regions) do
    if (tonumber(region.pattern_id) or region.pattern_id) == pid then
      sync_seq_region(region)
    end
  end
end

function seq_sync_linked_arrange_from(region)
  if not region or not region.pattern_id then
    return
  end
  local pid = tonumber(region.pattern_id) or region.pattern_id
  local others = {}
  for _, other in ipairs(state.seq_regions or {}) do
    if other.id ~= region.id and (tonumber(other.pattern_id) or other.pattern_id) == pid then
      others[#others + 1] = other
    end
  end
  if #others == 0 then
    return
  end
  -- The ingested copy already updated shared notes from arrange. Push those
  -- notes onto the other pooled copies so they stay linked, but never rewrite
  -- the copy that was just ingested.
  if r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  local rebuild = {}
  local pruned = false
  for i = 1, #others do
    if seq_prune_stale_region_items(others[i]) > 0 then
      pruned = true
    end
    local item_n = seq_count_owned_primary_items(others[i])
    local note_n = seq_region_expected_primary_notes(others[i])
    if item_n ~= note_n then
      rebuild[#rebuild + 1] = others[i]
    end
  end
  for i = 1, #rebuild do
    sync_seq_region(rebuild[i], { skip_cache_clear = true, skip_arrange = true })
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  if pruned or #rebuild > 0 then
    r.UpdateArrange()
  end
end

function sync_all_seq_regions()
  for _, region in ipairs(state.seq_regions) do
    sync_seq_region(region)
  end
end

function seq_mark_self_arrange_write()
  state.seq_skip_ingest = true
  if r.GetProjectStateChangeCount then
    state.seq_self_write_count = r.GetProjectStateChangeCount(0)
  end
end

function seq_schedule_ingest_save()
  state.seq_ingest_save_due = (r.time_precise and r.time_precise() or os.clock()) + 0.4
end

function seq_flush_ingest_save()
  if not state.seq_ingest_save_due then
    return
  end
  local now = r.time_precise and r.time_precise() or os.clock()
  if now < state.seq_ingest_save_due then
    return
  end
  state.seq_ingest_save_due = nil
  if save_seq_project_state then
    save_seq_project_state()
  end
end

function seq_ingest_busy()
  return state.seq_note_drag ~= nil or state.seq_param_drag ~= nil or state.seq_region_drag ~= nil
    or state.seq_razor_drag ~= nil
    or state.seq_lane_h_drag ~= nil
    or state.seq_track_reorder_drag ~= nil
    or state.pending_waveform_drop ~= nil
    or seq_undo_is_open()
    or state.seq_random_knob_drag ~= nil
    or state.seq_random_sync_pending ~= nil
end

function seq_item_take_params(item)
  local vol, pan, pitch = 1.0, 0.0, 0.0
  if not item then
    return vol, pan, pitch
  end
  local take = r.GetActiveTake(item)
  if take then
    vol = r.GetMediaItemTakeInfo_Value(take, "D_VOL") or 1.0
    pan = r.GetMediaItemTakeInfo_Value(take, "D_PAN") or 0.0
    pitch = r.GetMediaItemTakeInfo_Value(take, "D_PITCH") or 0.0
  else
    vol = r.GetMediaItemInfo_Value(item, "D_VOL") or 1.0
  end
  if vol < 0 then vol = 0 end
  if vol > 2 then vol = 2 end
  if pan < -1 then pan = -1 elseif pan > 1 then pan = 1 end
  if pitch < -24 then pitch = -24 elseif pitch > 24 then pitch = 24 end
  return vol, pan, pitch, take
end

function seq_item_length_qn(item)
  if not item then
    return nil
  end
  local pos = r.GetMediaItemInfo_Value(item, "D_POSITION")
  local len = r.GetMediaItemInfo_Value(item, "D_LENGTH")
  if not pos or not len or len <= 1e-9 then
    return nil
  end
  local q0 = time_to_qn(pos)
  local q1 = time_to_qn(pos + len)
  if q0 and q1 and q1 > q0 then
    return q1 - q0
  end
  return nil
end

function seq_ingest_item_end_qn(item)
  if not item then
    return nil
  end
  local pos = r.GetMediaItemInfo_Value(item, "D_POSITION")
  local len = r.GetMediaItemInfo_Value(item, "D_LENGTH")
  if not pos or not len or len <= 1e-9 then
    return nil
  end
  return time_to_qn(pos + len)
end

function seq_ingest_items_contiguous(items, slop)
  slop = slop or 0.02
  local metas = {}
  for i = 1, #(items or {}) do
    if not seq_item_is_aux_piece(items[i]) then
      local q0 = seq_ingest_item_qn(items[i])
      local q1 = seq_ingest_item_end_qn(items[i])
      if q0 and q1 then
        metas[#metas + 1] = { q0 = q0, q1 = q1 }
      end
    end
  end
  if #metas < 2 then
    return false
  end
  table.sort(metas, function(a, b) return a.q0 < b.q0 end)
  for i = 2, #metas do
    if math.abs(metas[i].q0 - metas[i - 1].q1) > slop then
      return false
    end
  end
  return true
end

-- Earliest start to latest end across a stitched cluster (layers / ghosts).
function seq_ingest_cluster_span_qn(rec)
  local items = rec and rec.items
  if type(items) ~= "table" or #items == 0 then
    items = rec and rec.item and { rec.item } or nil
  end
  if not items then
    return nil
  end
  local t0, t1 = nil, nil
  for i = 1, #items do
    local item = items[i]
    if item then
      local pos = r.GetMediaItemInfo_Value(item, "D_POSITION")
      local len = r.GetMediaItemInfo_Value(item, "D_LENGTH")
      if pos and len and len > 1e-9 then
        local q0 = time_to_qn(pos)
        local q1 = time_to_qn(pos + len)
        if q0 and (not t0 or q0 < t0) then
          t0 = q0
        end
        if q1 and (not t1 or q1 > t1) then
          t1 = q1
        end
      end
    end
  end
  if t0 and t1 and t1 > t0 then
    return t1 - t0
  end
  return nil
end

function seq_ingest_length_qn_from_rec(rec, item)
  local items = rec and rec.items
  if type(items) == "table" then
    local slop = math.max(0.02, (state.seq_grid_qn or 0.25) * 0.08)
    if seq_ingest_items_contiguous(items, slop) then
      return seq_ingest_cluster_span_qn(rec)
    end
    local best = nil
    for i = 1, #items do
      if not seq_item_is_aux_piece(items[i]) then
        local qn = seq_item_length_qn(items[i])
        if qn and (not best or qn > best) then
          best = qn
        end
      end
    end
    if best then
      return best
    end
    return seq_ingest_cluster_span_qn(rec)
  end
  if item and not seq_item_is_aux_piece(item) then
    return seq_item_length_qn(item)
  end
  return nil
end

-- How far past the trigger a same-step stitch (layer/ghost/sustain) may start
-- and still belong to this note. Off-grid heads plus a replaced transient can
-- put the sustain item a long way after the stored qn_offset.
function seq_ingest_note_cover_end_qn(region, track_id, step_key, note, grid_qn)
  local home = seq_note_trigger_qn(region, step_key, note, grid_qn)
  grid_qn = grid_qn or 0.25
  local cover = grid_qn
  local span = seq_stutter_span_qn(note, grid_qn)
  if span and span > cover then
    cover = span
  end
  local decay = tonumber(note and note.decay_qn)
  if type(decay) == "number" and decay > cover then
    cover = decay
  end
  local len = tonumber(note and note.length_qn)
  if type(len) == "number" and len > cover then
    cover = len
  end
  -- One beat covers long drum transients at typical tempos.
  if cover < 1.0 then
    cover = 1.0
  end
  return home + cover
end

-- Trimmed arrange items keep the full source file; D_LENGTH is the audible
-- length. Store that as decay_qn so the sequencer draws and rebuilds it.
-- Layer slices are not the note length — use the primary item or the full
-- stitch span so a short transient does not collapse the hit.
function seq_ingest_apply_item_length(note, item, region, pattern, slot, step_key, grid_qn, rec)
  if not note or seq_stutter_count(note) > 1 then
    return false
  end
  local item_qn = seq_ingest_length_qn_from_rec(rec, item)
  if not item_qn or item_qn <= 1e-9 then
    return false
  end
  local saved = note.decay_qn
  note.decay_qn = nil
  local _, resolved_sample = seq_resolve_note_sample(note, slot, nil, region, slot and slot.id, step_key)
  local auto_qn = seq_effective_note_length_qn(
    region, pattern, slot, slot and slot.id, step_key, note, resolved_sample, grid_qn
  ) or 0.0
  note.decay_qn = saved
  local slop = math.max(0.015, (grid_qn or 0.25) * 0.06)
  if math.abs(item_qn - auto_qn) <= slop then
    if saved ~= nil then
      note.decay_qn = nil
      return true
    end
    return false
  end
  if math.abs((tonumber(saved) or 0.0) - item_qn) > slop then
    note.decay_qn = item_qn
    return true
  end
  return false
end

function seq_note_from_arrange_item(slot, step_key, step_qn, src_note, vol, pan, pitch, qn_offset)
  local note
  if src_note and type(src_note) == "table" then
    note = clone_table_deep(src_note)
  else
    local fallback_qn = qn_offset
    if type(fallback_qn) ~= "number" then
      fallback_qn = 0.0
    end
    note = make_default_seq_note(slot, step_key, fallback_qn)
  end
  if not note then
    note = {
      enabled = true,
      sample_path = slot and slot.sample_path,
      sample_name = slot and slot.sample_name,
      sample_vary = 0.0,
      stutter = 1,
    }
  end
  note.enabled = true
  if type(qn_offset) == "number" then
    note.qn_offset = qn_offset
    note.step = math.floor((qn_offset / (step_qn or 0.25)) + 1e-9)
  elseif type(note.qn_offset) ~= "number" then
    note.step = tonumber(step_key) or 0
    note.qn_offset = note.step * (step_qn or 0.25)
  end
  note.volume = vol
  note.pan = pan
  note.pitch = pitch
  return note
end

function seq_ingest_timing_slop_qn(region, track_id, grid_qn)
  local slop = math.max(0.02, (grid_qn or 0.25) * 0.04)
  local settings = get_seq_track_settings(get_seq_pattern(region and region.pattern_id, false), track_id, false)
  local t_lo, t_hi = seq_humanize_effective_time_ms(settings, settings and settings.humanize_ms)
  local max_ms = math.max(math.abs(t_lo), math.abs(t_hi))
  if max_ms > 0.05 then
    local sec_per = seq_sec_per_qn
    if not sec_per or sec_per <= 0 then
      local t0 = qn_to_time(0)
      local t1 = qn_to_time(1)
      if t0 and t1 and t1 > t0 then
        sec_per = t1 - t0
      end
    end
    if sec_per and sec_per > 0 then
      slop = math.max(slop, (max_ms / 1000.0) / sec_per * 1.25)
    end
  end
  return slop
end

-- Arrange item QN after groove + timing humanize, matching insert_seq_note_hit.
function seq_note_expected_item_qn(region, track_id, step_key, note, grid_qn)
  local qn = seq_note_trigger_qn(region, step_key, note, grid_qn)
  local settings = get_seq_track_settings(get_seq_pattern(region and region.pattern_id, false), track_id, false)
  local ms = settings and tonumber(settings.humanize_ms) or 0.0
  local t_lo, t_hi = seq_humanize_effective_time_ms(settings, ms)
  if math.abs(t_lo) < 0.05 and math.abs(t_hi) < 0.05 then
    return qn
  end
  local t = qn_to_time(qn)
  if not t then
    return qn
  end
  local dt = seq_humanize_time_offset_sec(
    region, track_id, step_key, ms, settings.humanize_seed or settings.seed
  )
  local q2 = time_to_qn(math.max(0.0, t + dt))
  return q2 or qn
end

function seq_ingest_humanize_delta_qn(region, track_id, step_key, base_qn)
  local settings = get_seq_track_settings(get_seq_pattern(region and region.pattern_id, false), track_id, false)
  local ms = settings and tonumber(settings.humanize_ms) or 0.0
  local t_lo, t_hi = seq_humanize_effective_time_ms(settings, ms)
  if type(base_qn) ~= "number" or (math.abs(t_lo) < 0.05 and math.abs(t_hi) < 0.05) then
    return 0.0
  end
  local t = qn_to_time(base_qn)
  if not t then
    return 0.0
  end
  local dt = seq_humanize_time_offset_sec(
    region, track_id, step_key, ms, settings.humanize_seed or settings.seed
  )
  if not dt or dt == 0.0 then
    return 0.0
  end
  local q2 = time_to_qn(math.max(0.0, t + dt))
  if not q2 then
    return 0.0
  end
  return q2 - base_qn
end

-- True if this arrange item is this note's first hit (plus humanize) or a
-- later stutter / layer piece in the same home span. Used so follow-up hits
-- are not treated as moves.
function seq_ingest_item_explained_by_note(item_qn, region, track_id, step_key, note, grid_qn, item)
  if not note or type(item_qn) ~= "number" then
    return false
  end
  local slop = seq_ingest_timing_slop_qn(region, track_id, grid_qn)
  local ghost_pad = 0.0
  if item and seq_item_is_aux_piece(item) then
    ghost_pad = SEQ_GHOST_CLOSE_MAX + 0.04
  else
    local pattern = region and get_seq_pattern(region.pattern_id, false)
    local settings = get_seq_track_settings(pattern, track_id, false)
    if seq_settings_ghost_active(settings) then
      local _, grace_hi = seq_ghost_close_range(settings, "grace")
      local _, after_hi = seq_ghost_close_range(settings, "after")
      ghost_pad = math.max(grace_hi or 0.0, after_hi or 0.0) + 0.04
    end
  end
  local expected = seq_note_expected_item_qn(region, track_id, step_key, note, grid_qn)
  if math.abs(item_qn - expected) <= slop + ghost_pad then
    return true
  end
  local home = seq_note_trigger_qn(region, step_key, note, grid_qn)
  local span = seq_stutter_span_qn(note, grid_qn)
  if (not span or span <= 0) and seq_random_stutter_count(note, region, track_id, step_key) > 1 then
    span = grid_qn or 0.25
  end
  if span and span > 0 then
    local lo = math.min(expected, home) - slop - ghost_pad
    local hi = home + span + slop + ghost_pad
    if item_qn >= lo and item_qn <= hi then
      return true
    end
  end
  -- Stitched layer / sustain pieces start after the trigger. Keep them on
  -- this note so off-grid hits do not spawn extra notes in arrange ingest.
  -- Primary copies (Ctrl+drag between grids) must become their own notes;
  -- the 1-beat cover is only for aux layer/ghost slices.
  if item and seq_item_is_aux_piece(item) then
    local cover_end = seq_ingest_note_cover_end_qn(region, track_id, step_key, note, grid_qn)
    local lo = math.min(expected, home) - slop - ghost_pad
    if item_qn >= lo and item_qn <= cover_end + slop + ghost_pad then
      return true
    end
  end
  return false
end

function seq_ingest_rec_matches_note(rec, region, track_id, step_key, note, grid_qn)
  if not rec or not note then
    return false
  end
  if rec.qn and seq_ingest_item_explained_by_note(rec.qn, region, track_id, step_key, note, grid_qn, rec.item) then
    return true
  end
  for i = 1, #(rec.items or {}) do
    local qn = seq_ingest_item_qn(rec.items[i])
    if qn and seq_ingest_item_explained_by_note(qn, region, track_id, step_key, note, grid_qn, rec.items[i]) then
      return true
    end
  end
  return false
end

-- First-hit item in a cluster: closest to the note's expected arrange position.
-- rec.qn is the earliest piece, which can be a later stutter hit or a layer
-- with a negative time offset.
function seq_ingest_rec_anchor_qn(rec, region, track_id, step_key, note, grid_qn)
  if not rec then
    return nil
  end
  if note then
    local expected = seq_note_expected_item_qn(region, track_id, step_key, note, grid_qn)
    local best_qn, best_d = rec.qn, math.huge
    for i = 1, #(rec.items or {}) do
      local item = rec.items[i]
      if not seq_item_is_aux_piece(item) then
        local qn = seq_ingest_item_qn(item)
        if qn then
          local d = math.abs(qn - expected)
          if d < best_d then
            best_d = d
            best_qn = qn
          end
        end
      end
    end
    return best_qn
  end
  return rec.qn
end

-- Map an arrange item's absolute QN to sequencer qn_offset + offset_qn.
-- Large moves retarget the note's cell instead of clamping a micro-offset.
-- The cell is the one that CONTAINS the item (floor), not the nearest cell.
-- Rounding to nearest made notes vanish past the halfway point: occupancy
-- sat on the next 16th while the note was still drawn in the previous one.
function seq_ingest_resolve_position(region, item_qn, grid_qn, track_id, existing, old_step_key)
  grid_qn = (type(grid_qn) == "number" and grid_qn > 0) and grid_qn or 0.25
  local region_start = region and region.start_qn or 0.0
  local region_len = get_seq_region_length_qn(region)
  local rel = item_qn - region_start

  if existing and seq_ingest_item_explained_by_note(item_qn, region, track_id, old_step_key, existing, grid_qn) then
    return seq_note_qn_offset(existing, old_step_key, grid_qn), existing.offset_qn or 0.0, true
  end

  local function containing_cell(rel_qn)
    local snapped = math.floor((rel_qn / grid_qn) + 1e-9) * grid_qn
    if snapped < 0 then
      snapped = 0.0
    end
    local max_start = math.max(0.0, region_len - 1e-9)
    if snapped >= max_start then
      snapped = math.floor((max_start / grid_qn) - 1e-9) * grid_qn
      if snapped < 0 then
        snapped = 0.0
      end
    end
    return snapped
  end

  local guess = containing_cell(rel)
  local groove_key = get_seq_region_groove(region)
  local groove = seq_groove_offset_qn(region_start + guess, groove_key)
  local ungrooved = rel - groove
  local snapped = containing_cell(ungrooved)
  groove = seq_groove_offset_qn(region_start + snapped, groove_key)
  -- Timing humanize is an arrange-only jitter. Do not bake it into offset_qn
  -- or the GUI shifts off-grid and the next ingest double-counts it.
  local hum = 0.0
  if old_step_key and old_step_key ~= "" then
    local base_qn = region_start + snapped + groove
    hum = seq_ingest_humanize_delta_qn(region, track_id, old_step_key, base_qn)
  end
  return snapped, rel - snapped - groove - hum, false
end

function seq_ingest_alloc_note_key(notes, qn_offset, existing)
  local base = seq_storage_key_from_qn(qn_offset)
  if not notes or not notes[base] or notes[base] == existing then
    return base
  end
  local n = 0
  local key = base
  while notes[key] and notes[key] ~= existing do
    n = n + 1
    key = base .. "_" .. tostring(n)
  end
  return key
end

function seq_add_ingest_region(out, region)
  if out and region and region.id then
    out[region.id] = region
  end
end

function seq_add_ingest_regions_overlapping_qn(out, q0, q1)
  if not out or type(q0) ~= "number" then
    return
  end
  q1 = (type(q1) == "number") and q1 or q0
  for _, region in ipairs(state.seq_regions or {}) do
    local rs = region.start_qn or 0.0
    local re = rs + get_seq_region_length_qn(region)
    if q0 < re and q1 > rs then
      seq_add_ingest_region(out, region)
    end
  end
end

-- Native arrange razors: "START END \"guid\" ..." (P_RAZOREDITS / _EXT).
function seq_track_razor_time_ranges(tr)
  local ranges = {}
  if not tr or not r.GetSetMediaTrackInfo_String then
    return ranges
  end
  local a, b = r.GetSetMediaTrackInfo_String(tr, "P_RAZOREDITS", "", false)
  local s = (type(b) == "string" and b ~= "" and b) or (type(a) == "string" and a ~= "" and a) or ""
  if s == "" then
    a, b = r.GetSetMediaTrackInfo_String(tr, "P_RAZOREDITS_EXT", "", false)
    s = (type(b) == "string" and b ~= "" and b) or (type(a) == "string" and a ~= "" and a) or ""
  end
  if s == "" then
    return ranges
  end
  for a, b in s:gmatch("([%-%d%.eE]+)%s+([%-%d%.eE]+)%s+\"") do
    local t0, t1 = tonumber(a), tonumber(b)
    if t0 and t1 and t1 > t0 then
      ranges[#ranges + 1] = { t0, t1 }
    end
  end
  return ranges
end

function seq_linked_track_guid_set()
  local set = {}
  for _, slot in ipairs(state.seq_tracks or {}) do
    if slot.reaper_track_guid then
      set[slot.reaper_track_guid] = true
    end
  end
  return set
end

function seq_ingest_item_qn(item)
  if not item then
    return nil
  end
  local pos = r.GetMediaItemInfo_Value(item, "D_POSITION")
  return time_to_qn(pos)
end

function seq_ingest_consider_item(rec, item, item_qn)
  if not rec or not item or not item_qn then
    return
  end
  local is_aux = seq_item_is_aux_piece(item)
  local vol, pan, pitch = seq_item_take_params(item)
  if not rec.item then
    rec.item = item
    rec.qn = item_qn
    rec.vol = vol
    rec.pan = pan
    rec.pitch = pitch
    rec.is_layer = is_aux
    return
  end
  if rec.is_layer and not is_aux then
    rec.item = item
    rec.qn = item_qn
    rec.vol = vol
    rec.pan = pan
    rec.pitch = pitch
    rec.is_layer = false
    return
  end
  if is_aux == rec.is_layer and item_qn < rec.qn then
    rec.item = item
    rec.qn = item_qn
    rec.vol = vol
    rec.pan = pan
    rec.pitch = pitch
    rec.is_layer = is_aux
  end
end

function seq_ingest_primary_item_count(items)
  local n = 0
  for i = 1, #(items or {}) do
    if not seq_item_is_aux_piece(items[i]) then
      n = n + 1
    end
  end
  return n
end

function seq_ingest_rec_from_items(items, template)
  local rec = {
    items = items or {},
    old_step = template and template.old_step or "",
    old_track = template and template.old_track or "",
    source_path = template and template.source_path or nil,
    claim_existing = false,
  }
  for i = 1, #(rec.items) do
    local item = rec.items[i]
    seq_ingest_consider_item(rec, item, seq_ingest_item_qn(item))
  end
  return rec
end

-- Razor splits copy P_EXT tags, so leftover + moved pieces share one step key.
-- Keep layers / stutter hits that still occupy the original window as one note;
-- pieces that landed elsewhere become their own notes.
function seq_ingest_split_tagged_clusters(rec, notes, region, track_id, grid_qn)
  local items = rec and rec.items or {}
  local old_key = rec and rec.old_step or ""
  local existing = notes and (notes[tostring(old_key)] or notes[old_key]) or nil
  if #items <= 1 or old_key == "" then
    rec.claim_existing = existing ~= nil
    return { rec }
  end

  -- Drum layering writes several items (transient / sustain / ghosts) that
  -- share one step key. Keep them as a single note even when the sustain
  -- starts later — ingest must not invent extra off-grid hits.
  if not existing or seq_stutter_count(existing) <= 1 then
    local stitched = false
    for i = 1, #items do
      if seq_item_is_aux_piece(items[i]) then
        stitched = true
        break
      end
    end
    if stitched then
      rec.claim_existing = existing ~= nil
      return { rec }
    end
  end

  local same_slop = math.max(0.02, (grid_qn or 0.25) * 0.08)
  local metas = {}
  for i = 1, #items do
    local qn = seq_ingest_item_qn(items[i])
    if qn then
      metas[#metas + 1] = { item = items[i], qn = qn }
    end
  end
  table.sort(metas, function(a, b) return a.qn < b.qn end)

  local buckets = {}
  for i = 1, #metas do
    local m = metas[i]
    local last = buckets[#buckets]
    local same_start = last and math.abs(m.qn - last.qn) <= same_slop
    if same_start then
      local last_aux = seq_item_is_aux_piece(last.items[1])
      local this_aux = seq_item_is_aux_piece(m.item)
      if not last_aux and not this_aux then
        same_start = false
      end
    end
    local last_end = last and seq_ingest_item_end_qn(last.items[#last.items])
    local contiguous = last_end and math.abs(m.qn - last_end) <= same_slop
    if same_start or contiguous then
      last.items[#last.items + 1] = m.item
      if m.qn < last.qn then
        last.qn = m.qn
      end
    else
      buckets[#buckets + 1] = { qn = m.qn, items = { m.item } }
    end
  end

  if #buckets <= 1 then
    rec.claim_existing = existing ~= nil
    return { rec }
  end

  local merge_gap = same_slop
  if existing and seq_stutter_count(existing) > 1 then
    local span = seq_stutter_span_qn(existing, grid_qn) or grid_qn
    local count = seq_stutter_count(existing)
    merge_gap = (span / math.max(1, count)) + same_slop
  end
  local has_stitch = false
  for i = 1, #items do
    if seq_item_is_aux_piece(items[i]) then
      has_stitch = true
      break
    end
  end
  if has_stitch then
    merge_gap = math.max(merge_gap, (grid_qn or 0.25) + same_slop)
  end

  local home_buckets, other_buckets = {}, {}
  for i = 1, #buckets do
    local b = buckets[i]
    if existing and seq_ingest_item_explained_by_note(b.qn, region, track_id, old_key, existing, grid_qn, b.items and b.items[1]) then
      home_buckets[#home_buckets + 1] = b
    else
      other_buckets[#other_buckets + 1] = b
    end
  end

  local function merge_buckets(list, gap)
    local runs = {}
    for i = 1, #list do
      local b = list[i]
      local last = runs[#runs]
      if last and (b.qn - last.last_qn) <= gap then
        for j = 1, #b.items do
          last.items[#last.items + 1] = b.items[j]
        end
        last.last_qn = b.qn
      else
        local copy = {}
        for j = 1, #b.items do
          copy[j] = b.items[j]
        end
        runs[#runs + 1] = { qn = b.qn, last_qn = b.qn, items = copy }
      end
    end
    local recs = {}
    for i = 1, #runs do
      recs[i] = seq_ingest_rec_from_items(runs[i].items, rec)
    end
    return recs
  end

  local clusters = {}
  if #home_buckets > 0 then
    local home_items = {}
    for i = 1, #home_buckets do
      for j = 1, #home_buckets[i].items do
        home_items[#home_items + 1] = home_buckets[i].items[j]
      end
    end
    local home_rec = seq_ingest_rec_from_items(home_items, rec)
    home_rec.claim_existing = existing ~= nil
    clusters[#clusters + 1] = home_rec
  end

  local other_recs = merge_buckets(other_buckets, merge_gap)
  for i = 1, #other_recs do
    clusters[#clusters + 1] = other_recs[i]
  end

  if existing and #home_buckets == 0 and #clusters > 0 then
    local best = 1
    for i = 2, #clusters do
      local ni = #(clusters[i].items or {})
      local nb = #(clusters[best].items or {})
      if ni > nb or (ni == nb and (clusters[i].qn or 0) < (clusters[best].qn or 0)) then
        best = i
      end
    end
    clusters[best].claim_existing = true
  end

  return clusters
end

function seq_ingest_expand_razor_groups(by_group, notes, region, track_id, grid_qn)
  local out = {}
  for _, rec in pairs(by_group or {}) do
    local clusters = seq_ingest_split_tagged_clusters(rec, notes, region, track_id, grid_qn)
    for i = 1, #clusters do
      out[#out + 1] = clusters[i]
    end
  end
  table.sort(out, function(a, b)
    if a.claim_existing and not b.claim_existing then
      return true
    end
    if b.claim_existing and not a.claim_existing then
      return false
    end
    return (a.qn or 0) < (b.qn or 0)
  end)
  for i = 1, #out do
    local rec = out[i]
    local old_key = rec.old_step
    rec.src_note = (old_key ~= "" and notes and (notes[tostring(old_key)] or notes[old_key])) or nil
    if rec.claim_existing and not rec.src_note then
      rec.claim_existing = false
    end
  end
  return out
end

function seq_count_owned_primary_items(region)
  local n = 0
  if not region then
    return 0
  end
  for _, slot in ipairs(state.seq_tracks or {}) do
    local tr = get_seq_slot_target_track(slot)
    if tr then
      for i = 0, r.CountTrackMediaItems(tr) - 1 do
        local item = r.GetTrackMediaItem(tr, i)
        if item and not seq_item_is_aux_piece(item) and seq_item_is_owned(item, region.id) then
          n = n + 1
        end
      end
    end
  end
  return n
end

function seq_region_expected_primary_notes(region)
  local n = 0
  if not region then
    return 0
  end
  local pattern = get_seq_pattern(region.pattern_id, false)
  if not pattern then
    return 0
  end
  local grid_qn = (type(state.seq_grid_qn) == "number" and state.seq_grid_qn > 0) and state.seq_grid_qn or 0.25
  for _, slot in ipairs(state.seq_tracks or {}) do
    local notes = get_track_note_table(pattern, slot.id, false)
    if notes then
      local st = get_seq_track_settings(pattern, slot.id, false)
      for step_key, note in pairs(notes) do
        if type(note) == "table" and note.enabled ~= false
            and seq_note_in_region(region, note, step_key, grid_qn)
            and seq_note_passes_probability(
              region,
              slot.id,
              step_key,
              st and st.probability,
              st and (st.probability_seed or st.seed)
            ) then
          n = n + seq_stutter_count(note)
        end
      end
    end
  end
  return n
end

function seq_regions_for_ingest()
  local out = {}
  local has_sel_item = {}
  local selected = get_selected_seq_region()
  if selected then
    out[selected.id] = selected
  end
  local sel_count = r.CountSelectedMediaItems and r.CountSelectedMediaItems(0) or 0
  for i = 0, sel_count - 1 do
    local item = r.GetSelectedMediaItem(0, i)
    if item and seq_item_is_parent_marker(item) then
      local rid = tonumber(get_item_ext(item, SEQ_EXT_REGION) or "")
      local tagged = get_seq_region_by_id(rid)
      if tagged then
        out[tagged.id] = tagged
      end
    elseif item then
      local tr = r.GetMediaItemTrack and r.GetMediaItemTrack(item)
      local on_seq = false
      if tr then
        local guid = r.GetTrackGUID(tr)
        for _, slot in ipairs(state.seq_tracks or {}) do
          if slot.reaper_track_guid and slot.reaper_track_guid == guid then
            on_seq = true
            break
          end
        end
      end
      if on_seq then
        if seq_item_is_owned(item) then
          local rid = tonumber(get_item_ext(item, SEQ_EXT_REGION) or "")
          local tagged = get_seq_region_by_id(rid)
          if tagged then
            out[tagged.id] = tagged
          end
        end
        local pos = r.GetMediaItemInfo_Value(item, "D_POSITION")
        local item_qn = time_to_qn(pos)
        local dest = item_qn and seq_region_at_qn(item_qn)
        if dest then
          out[dest.id] = dest
          has_sel_item[dest.id] = true
        end
      end
    end
  end

  -- Arrange razor edits don't select items, so also follow native razors and
  -- tagged items that actually moved (wrong region, track, or time).
  local linked = seq_linked_track_guid_set()
  local grid_qn = (type(state.seq_grid_qn) == "number" and state.seq_grid_qn > 0) and state.seq_grid_qn or 0.25
  local tr_count = r.CountTracks(0)
  for tr_idx = 0, tr_count - 1 do
    local tr = r.GetTrack(0, tr_idx)
    local guid = tr and r.GetTrackGUID(tr)
    if guid and linked[guid] then
      local razors = seq_track_razor_time_ranges(tr)
      for i = 1, #razors do
        local t0, t1 = razors[i][1], razors[i][2]
        local q0 = time_to_qn(t0)
        local q1 = time_to_qn(t1)
        if q0 and q1 then
          seq_add_ingest_regions_overlapping_qn(out, q0, q1)
        end
      end
      for item_idx = 0, r.CountTrackMediaItems(tr) - 1 do
        local item = r.GetTrackMediaItem(tr, item_idx)
        if item and seq_item_is_owned(item) then
          local rid = tonumber(get_item_ext(item, SEQ_EXT_REGION) or "")
          local tagged = get_seq_region_by_id(rid)
          local item_qn = seq_ingest_item_qn(item)
          local dest = item_qn and seq_region_at_qn(item_qn)
          local displaced = tagged and dest and tagged.id ~= dest.id
          if not displaced and tagged and item_qn then
            local step = tostring(get_item_ext(item, SEQ_EXT_STEP) or "")
            local track_id = tonumber(get_item_ext(item, SEQ_EXT_TRACK) or "")
              or get_item_ext(item, SEQ_EXT_TRACK)
            local slot = find_seq_track_by_id(track_id)
            if slot and slot.reaper_track_guid and slot.reaper_track_guid ~= guid then
              displaced = true
            elseif step ~= "" then
              local note = get_seq_note(tagged, track_id, step)
              if not note or not seq_ingest_item_explained_by_note(item_qn, tagged, track_id, step, note, grid_qn, item) then
                displaced = true
              end
            end
          end
          if displaced then
            seq_add_ingest_region(out, tagged)
            seq_add_ingest_region(out, dest)
          end
        end
      end
    end
  end

  -- Pooled copies share pattern.notes. Ingesting two copies in one pass
  -- fights: each copy's humanize/items rewrite the same notes. Keep one
  -- region per pattern, preferring the copy that actually has the edit.
  local add = {}
  for _, region in pairs(out) do
    local pid = tonumber(region.pattern_id) or region.pattern_id
    if pid ~= nil then
      for _, other in ipairs(state.seq_regions or {}) do
        if (tonumber(other.pattern_id) or other.pattern_id) == pid then
          add[other.id] = other
        end
      end
    end
  end
  for id, region in pairs(add) do
    out[id] = region
  end
  local mismatch = {}
  for _, region in pairs(out) do
    mismatch[region.id] = seq_count_owned_primary_items(region) ~= seq_region_expected_primary_notes(region)
  end
  local best = {}
  for _, region in pairs(out) do
    local pid = tonumber(region.pattern_id) or region.pattern_id
    local cur = best[pid]
    if not cur then
      best[pid] = region
    else
      local r_hit = has_sel_item[region.id]
      local c_hit = has_sel_item[cur.id]
      local r_mis = mismatch[region.id]
      local c_mis = mismatch[cur.id]
      if r_hit and not c_hit then
        best[pid] = region
      elseif r_hit == c_hit and r_mis and not c_mis then
        best[pid] = region
      elseif r_hit == c_hit and r_mis == c_mis and selected then
        if region.id == selected.id then
          best[pid] = region
        end
      end
    end
  end
  return best
end

function seq_ingest_item_selected(item)
  if item and r.IsMediaItemSelected then
    return r.IsMediaItemSelected(item)
  end
  return false
end

function seq_ingest_tagged_region_owns(tagged_reg, item_qn)
  if not tagged_reg or not item_qn then
    return false
  end
  local rs = tagged_reg.start_qn or 0.0
  local re = rs + get_seq_region_length_qn(tagged_reg)
  return item_qn >= rs - 1e-9 and item_qn < re - 1e-9
end

function seq_paths_same(a, b)
  if type(a) ~= "string" or type(b) ~= "string" or a == "" or b == "" then
    return false
  end
  if a == b then
    return true
  end
  return normalize_path(a) == normalize_path(b)
end

-- Pin a hit to the file currently on the arrange item when that file is not
-- the track assignment (or the sample this note would already play).
function seq_ingest_freeze_foreign_source(note, slot, source_path, region, track_id, step_key)
  if type(note) ~= "table" or not source_path or source_path == "" then
    return false
  end
  if seq_paths_same(note.frozen_sample_path, source_path) then
    return false
  end
  -- Live vary notes keep re-picking. Pinning the last roll is what made a
  -- second filter edit (or another vary stroke) stick on one file.
  if not seq_note_is_locked(note) and seq_note_has_hit_sample_vary(note) then
    return false
  end
  local vary = 0.0
  if region and track_id and step_key and seq_random_vary_amount then
    vary = seq_random_vary_amount(note, region, track_id, step_key, 1) or 0.0
  end
  local resolved = seq_resolve_note_sample and select(1, seq_resolve_note_sample(note, slot, vary, region, track_id, step_key)) or nil
  if seq_paths_same(resolved, source_path) then
    return false
  end
  local region_path = seq_effective_slot_sample_path and select(1, seq_effective_slot_sample_path(slot, region))
  if region_path and seq_paths_same(source_path, region_path) then
    if seq_note_has_frozen_sample(note) then
      seq_clear_frozen_sample(note)
      return true
    end
    return false
  end
  if slot and slot.sample_path and slot.sample_path ~= "" and seq_paths_same(source_path, slot.sample_path) then
    if seq_note_has_frozen_sample(note) then
      seq_clear_frozen_sample(note)
      return true
    end
    return false
  end
  local sample = find_sample_by_path(source_path)
  seq_apply_frozen_sample(note, source_path, sample, slot and slot.sample_path)
  note.sample_path = source_path
  note.sample_name = (sample and sample.name) or basename(source_path)
  return true
end

function seq_ingest_region_from_arrange(region)
  if not region or not state.seq_tracks or #state.seq_tracks == 0 then
    return false
  end
  local grid_qn = (type(state.seq_grid_qn) == "number" and state.seq_grid_qn > 0) and state.seq_grid_qn or 0.25
  local region_start = region.start_qn or 0.0
  local region_len = get_seq_region_length_qn(region)
  local pattern = get_seq_pattern(region.pattern_id, true)
  if not pattern then
    return false
  end

  local present = {}
  local wrote_ext = false

  for _, slot in ipairs(state.seq_tracks) do
    local tr = seq_ingest_slot_track(slot) or get_seq_slot_target_track(slot)
    local linked_tr = seq_ingest_slot_track(slot)
    if tr then
      local by_group = {}
      local razor_ranges = seq_track_razor_time_ranges(tr)
      for item_idx = 0, r.CountTrackMediaItems(tr) - 1 do
        local item = r.GetTrackMediaItem(tr, item_idx)
        if item then
          local owned = seq_item_is_owned(item)
          local source_path = seq_item_source_path(item)
          -- Untagged audio is claimed on a slot's linked REAPER track. A
          -- different file is frozen onto the note so later syncs keep it.
          if owned or (source_path and linked_tr and tr == linked_tr) then
          local pos = r.GetMediaItemInfo_Value(item, "D_POSITION")
          local item_qn = time_to_qn(pos)
          if item_qn then
            local dest = seq_region_at_qn(item_qn)
            local tagged_rid = tonumber(get_item_ext(item, SEQ_EXT_REGION) or "")
            local tagged_reg = tagged_rid and get_seq_region_by_id(tagged_rid) or nil
            local rel = item_qn - region_start
            local in_this_span = rel >= -1e-9 and rel < region_len - 1e-9
            local belongs = false
            local in_native_razor = false
            if #razor_ranges > 0 then
              local len = r.GetMediaItemInfo_Value(item, "D_LENGTH") or 0
              for ri = 1, #razor_ranges do
                local t0, t1 = razor_ranges[ri][1], razor_ranges[ri][2]
                if pos < t1 and (pos + len) > t0 then
                  in_native_razor = true
                  break
                end
              end
            end
            if not in_this_span then
              belongs = false
            elseif owned and tagged_rid == region.id then
              belongs = (not dest) or dest.id == region.id
            elseif owned and dest and dest.id == region.id then
              -- Incoming move. Ignore unselected leftovers still tagged to
              -- another living region that owns this time (e.g. after a shorten).
              -- Arrange razor moves don't select items, so treat razor hits
              -- as selected.
              if not tagged_reg or not seq_ingest_tagged_region_owns(tagged_reg, item_qn)
                 or seq_ingest_item_selected(item) or in_native_razor then
                belongs = true
              end
            elseif (not owned) and source_path then
              belongs = (not dest) or dest.id == region.id
            end
            if belongs then
              local tagged_step = tostring(get_item_ext(item, SEQ_EXT_STEP) or "")
              local group_key
              if tagged_step ~= "" then
                group_key = "t:" .. tagged_step
              elseif owned then
                group_key = "u:" .. tostring(math.floor((rel / grid_qn) + 0.5))
              else
                group_key = "n:" .. tostring(item)
              end
              local rec = by_group[group_key]
              if not rec then
                rec = {
                  items = {},
                  qn = item_qn,
                  old_step = tagged_step,
                  old_track = tostring(get_item_ext(item, SEQ_EXT_TRACK) or ""),
                  source_path = source_path,
                }
                by_group[group_key] = rec
              end
              rec.items[#rec.items + 1] = item
              seq_ingest_consider_item(rec, item, item_qn)
              rec.old_step = tagged_step
              rec.old_track = tostring(get_item_ext(item, SEQ_EXT_TRACK) or "")
              if source_path and source_path ~= "" and not seq_item_is_aux_piece(item) then
                rec.source_path = source_path
              end
            end
          end
          end
        end
      end
      present[slot.id] = by_group
    end
  end

  local changed = false
  for _, slot in ipairs(state.seq_tracks) do
    local by_group = present[slot.id]
    if by_group then
    local notes = get_track_note_table(pattern, slot.id, true)
    if notes then
      local kept = {}
      local recs = seq_ingest_expand_razor_groups(by_group, notes, region, slot.id, grid_qn)

      for _, rec in ipairs(recs) do
        if rec.qn then
        local old_key = rec.old_step
        local existing = (rec.claim_existing and rec.src_note) or nil
        local near = existing and seq_ingest_rec_matches_note(rec, region, slot.id, old_key, existing, grid_qn)
        local qn_offset, offset_qn
        if near then
          qn_offset = seq_note_qn_offset(existing, old_key, grid_qn)
          offset_qn = existing.offset_qn or 0.0
        else
          local anchor_qn = seq_ingest_rec_anchor_qn(rec, region, slot.id, old_key, existing, grid_qn) or rec.qn
          qn_offset, offset_qn, near = seq_ingest_resolve_position(
            region, anchor_qn, grid_qn, slot.id, existing, old_key
          )
        end
        local new_key = seq_ingest_alloc_note_key(notes, qn_offset, existing)

        if not existing then
          local src = rec.src_note
          local vol = rec.vol
          if rec.is_layer then
            vol = 1.0
          else
            local vel_key = (old_key ~= "" and old_key) or new_key
            vol = select(1, seq_ingest_resolve_volume(rec.vol, src, region, slot.id, vel_key))
          end
          local pitch_key = (old_key ~= "" and old_key) or new_key
          local pitch = select(1, seq_ingest_resolve_pitch(rec.pitch, src, region, slot.id, pitch_key))
          local note = seq_note_from_arrange_item(slot, new_key, grid_qn, src, vol, rec.pan, pitch, qn_offset)
          note.qn_offset = qn_offset
          note.offset_qn = offset_qn
          note.step = math.floor((qn_offset / grid_qn) + 1e-9)
          if rec.source_path and rec.source_path ~= "" then
            if not slot.sample_path or slot.sample_path == "" then
              note.sample_path = rec.source_path
              note.sample_name = basename(rec.source_path)
              slot.sample_path = rec.source_path
              slot.sample_name = note.sample_name
            else
              seq_ingest_freeze_foreign_source(note, slot, rec.source_path, region, slot.id, new_key)
            end
          end
          local piece_count = seq_ingest_primary_item_count(rec.items)
          if seq_stutter_count(note) > 1 then
            if piece_count <= 1 then
              note.stutter = 1
              note.stutter_hits = nil
              note.length_qn = nil
            elseif piece_count ~= seq_stutter_count(note) then
              note.stutter = piece_count
              seq_prune_stutter_hits(note)
            end
          end
          seq_ingest_apply_item_length(note, rec.item, region, pattern, slot, new_key, grid_qn, rec)
          notes[new_key] = note
          register_seq_note_anim(region.id, slot.id, new_key, note, "add")
          changed = true
        else
          local note_changed = false
          if not near then
            if math.abs((existing.qn_offset or 0) - qn_offset) > 0.0005 then
              existing.qn_offset = qn_offset
              existing.step = math.floor((qn_offset / grid_qn) + 1e-9)
              note_changed = true
            end
            if math.abs((existing.offset_qn or 0) - offset_qn) > 0.0005 then
              existing.offset_qn = offset_qn
              note_changed = true
            end
          end
          if not rec.is_layer then
            local vel_key = (old_key ~= "" and old_key) or new_key
            local new_vol, vol_changed = seq_ingest_resolve_volume(rec.vol, existing, region, slot.id, vel_key)
            if vol_changed then
              existing.volume = new_vol
              note_changed = true
            end
          end
          if math.abs((existing.pan or 0) - rec.pan) > 0.001 then
            existing.pan = rec.pan
            note_changed = true
          end
          local new_pitch, pitch_changed = seq_ingest_resolve_pitch(rec.pitch, existing, region, slot.id, vel_key)
          if pitch_changed then
            existing.pitch = new_pitch
            note_changed = true
          end
          if seq_ingest_apply_item_length(existing, rec.item, region, pattern, slot, new_key, grid_qn, rec) then
            note_changed = true
          end
          if rec.source_path and rec.source_path ~= ""
             and seq_ingest_freeze_foreign_source(existing, slot, rec.source_path, region, slot.id, new_key) then
            note_changed = true
          end
          if old_key ~= "" and old_key ~= new_key and (notes[old_key] == existing or notes[tostring(old_key)] == existing) then
            notes[old_key] = nil
            notes[tostring(old_key)] = nil
            notes[new_key] = existing
            if state.selected_seq_note and state.selected_seq_note.region_id == region.id
               and state.selected_seq_note.track_id == slot.id
               and tostring(state.selected_seq_note.step_key) == tostring(old_key) then
              state.selected_seq_note.step_key = new_key
            end
            note_changed = true
          elseif not notes[new_key] then
            notes[new_key] = existing
            note_changed = true
          end
          if note_changed then
            register_seq_note_anim(region.id, slot.id, new_key, existing, "sync")
            changed = true
          end
        end

        kept[tostring(new_key)] = true

        for i = 1, #(rec.items or {}) do
          local item = rec.items[i]
          if get_item_ext(item, SEQ_EXT_FLAG) ~= "1"
             or tostring(get_item_ext(item, SEQ_EXT_STEP) or "") ~= tostring(new_key)
             or tostring(get_item_ext(item, SEQ_EXT_TRACK) or "") ~= tostring(slot.id)
             or tonumber(get_item_ext(item, SEQ_EXT_REGION) or "") ~= region.id then
            set_item_ext(item, SEQ_EXT_FLAG, "1")
            set_item_ext(item, SEQ_EXT_REGION, region.id)
            set_item_ext(item, SEQ_EXT_PATTERN, region.pattern_id)
            set_item_ext(item, SEQ_EXT_TRACK, slot.id)
            set_item_ext(item, SEQ_EXT_STEP, new_key)
            wrote_ext = true
          end
        end
        end
      end

      for step_key, note in pairs(notes) do
        if type(note) == "table" and not kept[tostring(step_key)]
           and seq_note_in_region(region, note, step_key, grid_qn) then
          local st = get_seq_track_settings(pattern, slot.id, false)
          local skipped = not seq_note_passes_probability(
            region,
            slot.id,
            step_key,
            st and st.probability,
            st and (st.probability_seed or st.seed)
          )
          if not skipped then
            register_seq_note_anim(region.id, slot.id, step_key, note, "delete")
            notes[step_key] = nil
            if state.selected_seq_note and state.selected_seq_note.region_id == region.id
               and state.selected_seq_note.track_id == slot.id
               and tostring(state.selected_seq_note.step_key) == tostring(step_key) then
              state.selected_seq_note = nil
            end
            changed = true
          end
        end
      end
    end
    end
  end

  if wrote_ext then
    seq_mark_self_arrange_write()
  end
  return changed
end

function ingest_seq_from_arrange()
  seq_flush_ingest_save()
  if not r.GetProjectStateChangeCount then
    return
  end

  local count = r.GetProjectStateChangeCount(0)
  if state.seq_skip_ingest then
    -- Ignore the change count from our own item writes, but do not swallow a
    -- user edit that landed in the same defer (e.g. Delete right after a sync).
    local self_count = state.seq_self_write_count
    state.seq_skip_ingest = false
    state.seq_self_write_count = nil
    state.seq_ingest_pending_count = nil
    if state.seq_last_proj_change == count then
      return
    end
    if self_count and count <= self_count then
      state.seq_last_proj_change = count
      return
    end
    if not state.seq_last_proj_change then
      state.seq_last_proj_change = self_count
    end
  end
  if seq_ingest_busy() then
    return
  end
  if state.seq_last_proj_change == count then
    state.seq_ingest_pending_count = nil
    if not state.seq_parent_items_ensured then
      state.seq_parent_items_ensured = true
      seq_ensure_all_region_parent_items()
    end
    return
  end
  -- Wait until the change count stops moving so we ingest the settled
  -- arrange positions, not an in-between mouse-drag frame. Discrete edits
  -- (Delete/Cut) leave nothing selected — ingest those immediately.
  local selected_items = r.CountSelectedMediaItems and r.CountSelectedMediaItems(0) or 0
  if selected_items > 0 and state.seq_ingest_pending_count ~= count then
    state.seq_ingest_pending_count = count
    return
  end
  state.seq_ingest_pending_count = nil
  state.seq_last_proj_change = count

  seq_sync_track_order_from_arrange()

  local parent_changed, parent_synced = seq_ingest_parent_items()
  if parent_changed then
    seq_schedule_ingest_save()
    if parent_synced then
      if r.GetProjectStateChangeCount then
        state.seq_last_proj_change = r.GetProjectStateChangeCount(0)
      end
      return
    end
  end

  if not state.seq_tracks or #state.seq_tracks == 0 or not state.seq_regions or #state.seq_regions == 0 then
    return
  end

  local changed = false
  local ingested = {}
  local targets = seq_regions_for_ingest()
  for _, region in pairs(targets) do
    if seq_ingest_region_from_arrange(region) then
      changed = true
      ingested[#ingested + 1] = region
    end
  end
  if changed then
    for i = 1, #ingested do
      seq_sync_linked_arrange_from(ingested[i])
    end
    seq_schedule_ingest_save()
  end
  -- Retag writes bump the change count; keep last in sync so the skip
  -- snapshot matches even if UpdateArrange ran during this ingest pass.
  if state.seq_skip_ingest and r.GetProjectStateChangeCount then
    state.seq_last_proj_change = r.GetProjectStateChangeCount(0)
  end
end

update_seq_track_sample_assignments = function(slot, sample_path, sample_name, persist, opts)
  if not slot or not slot.id or not sample_path then
    return
  end
  opts = opts or {}

  clear_seq_vary_rank_cache()

  local touched_patterns = {}
  local track_key = tostring(slot.id)
  for pattern_id, pattern in pairs(state.seq_patterns) do
    if type(pattern) == "table" and type(pattern.notes) == "table" then
      local track_notes = pattern.notes[track_key]
      if type(track_notes) == "table" then
        local touched = false
        for _, note in pairs(track_notes) do
          if type(note) == "table" and not seq_note_has_frozen_sample(note) then
            note.sample_path = sample_path
            note.sample_name = sample_name or basename(sample_path)
            touched = true
          end
        end
        if touched then
          touched_patterns[tonumber(pattern_id) or pattern_id] = true
        end
      end
    end
  end

  if next(touched_patterns) then
    seq_pcm_take_src_begin()
    if r.PreventUIRefresh then
      r.PreventUIRefresh(1)
    end
    for pattern_id, _ in pairs(touched_patterns) do
      -- Only rewrite the swapped track. Rebuilding every sequencer track in
      -- the region is what made even sparse kits feel slow.
      sync_seq_pattern_track(pattern_id, slot, {
        skip_arrange = true,
        force_rebuild = opts.force_rebuild,
      })
    end
    if r.PreventUIRefresh then
      r.PreventUIRefresh(-1)
    end
    seq_pcm_take_src_end()
    r.UpdateArrange()
  end

  if persist then
    save_config()
  end
end

function sync_selected_seq_region()
  local region = get_selected_seq_region()
  if region then
    sync_seq_pattern_regions(region.pattern_id)
  end
end

function create_seq_region(length_bars, copy_from, pooled, preferred_start_qn, insert)
  local own = seq_undo_own_begin(pooled and copy_from and "Pool copy sequencer region" or "Create sequencer region")
  seq_remove_orphaned_region_items()
  local start_qn = 0.0
  local region_length_bars = length_bars or (copy_from and copy_from.length_bars) or 4
  if preferred_start_qn then
    start_qn = preferred_start_qn
  elseif copy_from then
    start_qn = (copy_from.start_qn or 0.0) + get_seq_region_length_qn(copy_from)
  else
    local arrange_start = select(1, get_arrange_view_range())
    start_qn = time_to_qn(arrange_start) or 0.0
  end
  local length_qn = get_seq_region_length_qn({ start_qn = start_qn, length_bars = region_length_bars })
  start_qn = math.max(0.0, start_qn)
  if insert or (preferred_start_qn and seq_region_overlaps(start_qn, length_qn, nil)) then
    seq_shift_regions_from(start_qn, length_qn, nil)
  else
    start_qn = find_non_overlapping_region_start(start_qn, length_qn, nil)
  end

  local pattern_id
  local pool_id
  if copy_from and pooled then
    pattern_id = copy_from.pattern_id
    pool_id = copy_from.pool_id or alloc_seq_pool()
    copy_from.pool_id = pool_id
  else
    pattern_id = alloc_seq_pattern()
    pool_id = alloc_seq_pool()
    if copy_from then
      local src_pattern = get_seq_pattern(copy_from.pattern_id, false)
      state.seq_patterns[tostring(pattern_id)] = clone_table_deep(src_pattern or { notes = {} })
    end
  end

  local region = {
    id = state.seq_region_next_id,
    name = seq_auto_name_new_region(start_qn),
    start_qn = start_qn,
    length_bars = region_length_bars,
    pool_id = pool_id,
    pattern_id = pattern_id,
    groove = copy_from and normalize_seq_groove(copy_from.groove) or "off",
    style_key = copy_from and copy_from.style_key or nil,
    style_source = copy_from and copy_from.style_source or nil,
    kit_genres = copy_from and copy_from.kit_genres and clone_table_deep(copy_from.kit_genres) or nil,
    track_samples = copy_from and seq_clone_region_track_samples(copy_from) or nil,
  }
  state.seq_region_next_id = state.seq_region_next_id + 1
  table.insert(state.seq_regions, region)
  table.sort(state.seq_regions, function(a, b) return (a.start_qn or 0) < (b.start_qn or 0) end)
  state.selected_seq_region_id = region.id
  save_config()
  if copy_from and pooled then
    sync_seq_pattern_regions(pattern_id)
    seq_parent_sync_pool(pool_id)
  else
    sync_seq_region(region)
  end
  if own then
    end_seq_undo(pooled and copy_from and "Pool copy sequencer region" or "Create sequencer region")
  end
  return region
end

function unpool_selected_seq_region()
  seq_unpool_region(get_selected_seq_region())
end

function clear_selected_seq_region()
  local region = get_selected_seq_region()
  if not region then
    return
  end
  local own = seq_undo_own_begin("Clear sequencer region")
  local pattern = get_seq_pattern(region.pattern_id, true)
  pattern.notes = {}
  pattern.locked_cells = nil
  pattern.vary_filters = nil
  state.selected_seq_note = nil
  save_config()
  sync_seq_pattern_regions(region.pattern_id)
  if own then
    end_seq_undo("Clear sequencer region")
  end
end

function delete_selected_seq_region()
  local own = seq_undo_own_begin("Delete sequencer region")
  local region = get_selected_seq_region()
  if not region then
    if own then
      end_seq_undo("Delete sequencer region")
    end
    return
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  remove_seq_rendered_items(region)
  seq_remove_region_parent_item(region)
  local removed_idx = nil
  for i, reg in ipairs(state.seq_regions) do
    if reg.id == region.id then
      removed_idx = i
      break
    end
  end
  if removed_idx then
    table.remove(state.seq_regions, removed_idx)
  end

  local pattern_still_used = false
  for _, reg in ipairs(state.seq_regions) do
    if reg.pattern_id == region.pattern_id then
      pattern_still_used = true
      break
    end
  end
  if not pattern_still_used then
    state.seq_patterns[tostring(region.pattern_id)] = nil
  end

  if #state.seq_regions == 0 then
    state.selected_seq_region_id = nil
    state.selected_seq_note = nil
    ensure_default_seq_region()
  else
    local next_region = state.seq_regions[math.min(removed_idx or 1, #state.seq_regions)] or state.seq_regions[1]
    state.selected_seq_region_id = next_region.id
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  seq_refresh_arrange()
  save_config()
  if own then
    end_seq_undo("Delete sequencer region")
  end
end

function move_selected_seq_region(delta_qn)
  local region = get_selected_seq_region()
  if not region then
    return
  end
  local length_qn = get_seq_region_length_qn(region)
  local desired = math.max(0.0, (region.start_qn or 0.0) + delta_qn)
  local new_start
  if delta_qn < 0 then
    new_start = find_prev_non_overlapping_region_start(desired, length_qn, region.id)
  else
    new_start = find_non_overlapping_region_start(desired, length_qn, region.id)
  end
  if math.abs(new_start - (region.start_qn or 0.0)) < 0.000001 then
    return
  end
  local own = seq_undo_own_begin("Move sequencer region")
  remove_seq_rendered_items(region)
  region.start_qn = new_start
  sort_seq_regions()
  state.seq_view_start_qn = new_start
  state.seq_view_span_qn = length_qn
  save_config()
  sync_seq_region(region)
  if own then
    end_seq_undo("Move sequencer region")
  end
end

SEQ_REGION_EDGE_PX = 6
SEQ_LINK_ICON_SIZE = 12
SEQ_LINK_HIT_PAD = 3

function seq_region_link_icon_xy(rx0, y0, region_lane_h)
  local lane_h = region_lane_h or 22.0
  return (rx0 or 0) + 4, (y0 or 0) + (lane_h - SEQ_LINK_ICON_SIZE) * 0.5
end

function seq_region_link_hit_rect(rx0, y0, region_lane_h)
  local ix, iy = seq_region_link_icon_xy(rx0, y0, region_lane_h)
  local pad = SEQ_LINK_HIT_PAD
  return ix - pad, iy - pad, ix + SEQ_LINK_ICON_SIZE + pad, iy + SEQ_LINK_ICON_SIZE + pad
end

function seq_snap_qn(qn, step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  return math.floor((qn / step_qn) + 0.5) * step_qn
end

function seq_get_measure_end_qn(measure)
  if not r.TimeMap_GetMeasureInfo then
    return nil
  end
  local _, qn_start, qn_end, ts_num, ts_den = r.TimeMap_GetMeasureInfo(0, measure)
  if not qn_start then
    return nil
  end
  if type(qn_end) == "number" and qn_end > qn_start then
    return qn_end
  end
  local out_num = (type(ts_num) == "number" and ts_num > 0) and ts_num or 4
  local out_den = (type(ts_den) == "number" and ts_den > 0) and ts_den or 4
  return qn_start + out_num * (4.0 / out_den)
end

function seq_get_measure_start_qn(measure)
  if not r.TimeMap_GetMeasureInfo then
    return nil
  end
  local _, qn_start = r.TimeMap_GetMeasureInfo(0, measure)
  if type(qn_start) == "number" then
    return qn_start
  end
  return nil
end

function seq_snap_qn_to_measure_end(qn)
  qn = math.max(0.0, qn or 0.0)
  if not r.TimeMap_GetMeasureInfo or not r.TimeMap2_timeToBeats then
    return seq_snap_qn(qn, state.seq_grid_qn or 0.25)
  end
  local time = qn_to_time(qn)
  if not time then
    return qn
  end
  local _, measure = r.TimeMap2_timeToBeats(0, time)
  if measure == nil then
    return qn
  end

  local measure_idx = math.max(0, math.floor((tonumber(measure) or 0) + 0.5))
  local best = seq_snap_qn(qn, state.seq_grid_qn or 0.25)
  local best_dist = math.abs(qn - best)
  for m = math.max(0, measure_idx - 1), measure_idx + 2 do
    local end_qn = seq_get_measure_end_qn(m)
    if end_qn then
      local dist = math.abs(qn - end_qn)
      if dist < best_dist then
        best_dist = dist
        best = end_qn
      end
    end
  end
  return best
end

function seq_snap_qn_to_bar(qn, step_qn)
  qn = math.max(0.0, qn or 0.0)
  if not r.TimeMap_GetMeasureInfo or not r.TimeMap2_timeToBeats then
    return seq_snap_qn(qn, step_qn or state.seq_grid_qn or 0.25)
  end
  local time = qn_to_time(qn)
  if not time then
    return qn
  end
  local _, measure = r.TimeMap2_timeToBeats(0, time)
  if measure == nil then
    return qn
  end

  local measure_idx = math.max(0, math.floor(tonumber(measure) or 0))
  local start_qn = seq_get_measure_start_qn(measure_idx)
  if start_qn then
    return start_qn
  end
  return seq_snap_qn(qn, step_qn or state.seq_grid_qn or 0.25)
end

function seq_snap_qn_for_region_drag(qn, step_qn)
  if is_shift_down() then
    return seq_snap_qn(qn, step_qn)
  end
  return seq_snap_qn_to_bar(qn, step_qn)
end

function seq_snap_qn_for_region_move(qn, step_qn)
  if is_shift_down() then
    return seq_snap_qn(qn, step_qn)
  end
  return seq_snap_qn_to_bar(qn, step_qn)
end

function seq_x_to_qn(mx, timeline_x0, timeline_w, start_qn, qn_span)
  return start_qn + ((mx - timeline_x0) / math.max(1.0, timeline_w)) * qn_span
end

-- Timeline pan inertia (QN velocity, runtime only — not saved to config).
SEQ_TIMELINE_SCROLL_GAIN = 0.0062
SEQ_TIMELINE_SCROLL_FRICTION = 0.84
SEQ_TIMELINE_SCROLL_MAX_VEL_RATIO = 0.13

function seq_timeline_scroll_stop()
  state.seq_view_scroll_vel_qn = 0.0
  state.seq_scroll_last_t = nil
end

function seq_timeline_scroll_is_active()
  local vel = state.seq_view_scroll_vel_qn or 0.0
  local span = state.seq_view_span_qn or 4.0
  return math.abs(vel) >= span * 0.00022
end

function seq_view_is_driving_arrange()
  return state.seq_follow_arrange and (state.seq_drive_arrange or seq_timeline_scroll_is_active())
end

function seq_timeline_scroll_impulse(pan_wheel, view_span_qn)
  if not pan_wheel or pan_wheel == 0 then
    return
  end
  local impulse = -pan_wheel * view_span_qn * SEQ_TIMELINE_SCROLL_GAIN
  local vel = (state.seq_view_scroll_vel_qn or 0.0) + impulse
  local max_vel = view_span_qn * SEQ_TIMELINE_SCROLL_MAX_VEL_RATIO
  state.seq_view_scroll_vel_qn = math.max(-max_vel, math.min(max_vel, vel))
end

function seq_timeline_scroll_apply_inertia(view_span_qn, dt)
  local vel = state.seq_view_scroll_vel_qn or 0.0
  local min_vel = view_span_qn * 0.00022
  if math.abs(vel) < min_vel then
    if vel ~= 0.0 then
      state.seq_view_scroll_vel_qn = 0.0
    end
    return false
  end
  state.seq_view_start_qn = math.max(0.0, (state.seq_view_start_qn or 0.0) + vel)
  state.seq_view_scroll_vel_qn = vel * (SEQ_TIMELINE_SCROLL_FRICTION ^ (dt * 60.0))
  return true
end

function seq_apply_time_zoom(wheel_delta, mx, timeline_x0, timeline_w, view_start_qn, qn_span, step_qn)
  if not wheel_delta or wheel_delta == 0 then
    return false
  end
  if state.seq_follow_arrange then
    state.seq_drive_arrange = true
  end
  local base_span = state.seq_view_span_qn or qn_span
  local ratio = math.max(0.0, math.min(1.0, (mx - timeline_x0) / math.max(1.0, timeline_w)))
  local anchor = (view_start_qn or 0.0) + base_span * ratio
  local step = step_qn or state.seq_grid_qn or 0.25
  local new_span = math.max(step * 8.0, math.min(step * 4096.0, base_span * math.exp(-wheel_delta * 0.2)))
  state.seq_view_start_qn = math.max(0.0, anchor - new_span * ratio)
  state.seq_view_span_qn = new_span
  seq_timeline_scroll_stop()
  return true
end

function seq_region_pool_count(pool_id)
  pool_id = tonumber(pool_id)
  local count = 0
  if not pool_id then
    return 0
  end
  for _, reg in ipairs(state.seq_regions) do
    if tonumber(reg.pool_id) == pool_id then
      count = count + 1
    end
  end
  return count
end

function seq_qn_length_to_bars(start_qn, length_qn)
  length_qn = math.max(state.seq_grid_qn or 0.25, length_qn)
  local bars = 1
  while bars < 512 do
    local test = { start_qn = start_qn, length_bars = bars }
    if get_seq_region_length_qn(test) >= length_qn - 0.0001 then
      return bars
    end
    bars = bars + 1
  end
  return bars
end

function seq_select_region(reg)
  if not reg then
    return
  end
  if state.selected_seq_region_id == reg.id then
    return
  end
  state.selected_seq_region_id = reg.id
  save_config()
end

function seq_zoom_to_region(reg)
  if not reg then
    return
  end
  state.seq_view_start_qn = reg.start_qn or 0.0
  state.seq_view_span_qn = get_seq_region_length_qn(reg)
  seq_timeline_scroll_stop()
  if state.seq_follow_arrange then
    state.seq_drive_arrange = true
    seq_push_view_to_arrange()
  end
  save_config()
end

function seq_get_playhead_time()
  local play_state = r.GetPlayState and r.GetPlayState() or 0
  if play_state & 1 == 1 and r.GetPlayPosition then
    return r.GetPlayPosition()
  end
  if r.GetCursorPosition then
    return r.GetCursorPosition()
  end
  return nil
end

function seq_set_playhead_qn(qn)
  if type(qn) ~= "number" then
    return
  end
  local time_pos = qn_to_time(qn)
  if type(time_pos) ~= "number" then
    return
  end
  if r.SetEditCurPos then
    r.SetEditCurPos(time_pos, true, true)
  elseif r.SetEditCurPos2 then
    r.SetEditCurPos2(0, time_pos, true, true)
  end
end

function imgui_text_input_active()
  if state.seq_vary_filter_edit or state.seq_region_rename then
    return true
  end
  if state._text_input_item_active then
    return true
  end
  if r.ImGui_GetIO then
    local io = r.ImGui_GetIO(ctx)
    if io then
      local want = io.WantTextInput
      if type(want) == "function" then
        want = want(io)
      end
      if want == true or want == 1 then
        return true
      end
    end
  end
  return false
end

function seq_mark_text_input_item()
  if not ctx then
    return
  end
  local active = (r.ImGui_IsItemActive and r.ImGui_IsItemActive(ctx))
    or (r.ImGui_IsItemFocused and r.ImGui_IsItemFocused(ctx))
  if active then
    state._text_input_item_active = true
    state._text_input_item_active_now = true
  end
end

-- True while any ImGui popup is open (kit randomize, groove, add-track, etc.).
-- Sequencer uses raw mouse geometry, so it must ignore clicks while popups own input.
function seq_layering_blocks_input()
  if not state.seq_layering_slot_id then
    return false
  end
  if state.pending_waveform_drop then
    return false
  end
  if state.seq_layering_hovered or state.seq_layering_drag
      or state.seq_layering_vol_drag or state.seq_layering_bias_drag then
    return true
  end
  local rect = state.seq_layering_rect
  if rect and r.ImGui_GetMousePos then
    local mx, my = r.ImGui_GetMousePos(ctx)
    mx, my = tonumber(mx), tonumber(my)
    if mx and my
        and mx >= (rect.x or 0) and my >= (rect.y or 0)
        and mx <= (rect.x or 0) + (rect.w or 0)
        and my <= (rect.y or 0) + (rect.h or 0) then
      return true
    end
  end
  return false
end

function imgui_any_popup_open()
  if seq_layering_blocks_input() then
    return true
  end
  if state.seq_region_rename then
    return true
  end
  if state.seq_neighbor_popup and state.seq_neighbor_popup.hovered then
    return true
  end
  if state.seq_minimap_popup and state.seq_minimap_popup.hovered then
    return true
  end
  if state.preview_history_popup and state.preview_history_popup.hovered then
    return true
  end
  if state.seq_env_popup_slot_id then
    return true
  end
  if r.ImGui_IsPopupOpen and r.ImGui_PopupFlags_AnyPopup then
    return r.ImGui_IsPopupOpen(ctx, "", r.ImGui_PopupFlags_AnyPopup())
  end
  if not r.ImGui_IsPopupOpen then
    return false
  end
  return r.ImGui_IsPopupOpen(ctx, "seq_kit_random_popup")
      or r.ImGui_IsPopupOpen(ctx, "seq_groove_popup")
      or r.ImGui_IsPopupOpen(ctx, "seq_add_track_popup")
      or r.ImGui_IsPopupOpen(ctx, "##seq_track_context_menu")
      or r.ImGui_IsPopupOpen(ctx, "seq_pattern_variations_popup")
      or r.ImGui_IsPopupOpen(ctx, "seq_env_editor_popup")
      or r.ImGui_IsPopupOpen(ctx, "seq_region_random_popup")
      or r.ImGui_IsPopupOpen(ctx, "tag_color_picker")
      or r.ImGui_IsPopupOpen(ctx, "select_tag_preset")
      or r.ImGui_IsPopupOpen(ctx, "save_tag_preset")
end

function handle_script_keyboard_shortcuts()
  if state.shortcut_capture_id then
    if not state.settings_open then
      state.shortcut_capture_id = nil
      return
    end
    seq_capture_shortcut_key()
    local key = shortcut_poll_pressed_key()
    if key then
      shortcut_assign(state.shortcut_capture_id, shortcut_spec_from_press(key))
      state.shortcut_capture_id = nil
      state.shortcut_capture_click_cancel = false
    end
    return
  end
  if handle_seq_undo_keys() then
    return
  end
  if imgui_text_input_active() then
    if state.seq_vary_filter_edit and r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false) then
      seq_cancel_vary_filter_edit()
    end
    return
  end
  if shortcut_pressed("play_stop") then
    r.Main_OnCommand(40044, 0)
  end
  handle_seq_note_edit_mode_keys()
  handle_seq_playback_and_split_keys()
  handle_map_arrow_keys()
end

function seq_unpool_region(region, opts)
  if not region then
    return
  end
  opts = opts or {}
  local own = (not opts.skip_undo) and seq_undo_own_begin("Unlink sequencer region")
  local old_pattern_id = region.pattern_id
  local old_pattern = get_seq_pattern(old_pattern_id, false)
  local new_pattern_id = alloc_seq_pattern()
  state.seq_patterns[tostring(new_pattern_id)] = clone_table_deep(old_pattern or { notes = {} })
  region.pattern_id = new_pattern_id
  region.pool_id = alloc_seq_pool()
  save_config()
  local item = region.parent_item_guid and seq_find_item_by_guid(region.parent_item_guid)
  if item then
    seq_write_parent_item_ext(item, region)
  end
  if opts.skip_sync then
    for _, slot in ipairs(state.seq_tracks or {}) do
      local tr = get_seq_slot_target_track(slot)
      if tr then
        for i = 0, r.CountTrackMediaItems(tr) - 1 do
          local it = r.GetTrackMediaItem(tr, i)
          if it and seq_item_is_owned(it, region.id) then
            set_item_ext(it, SEQ_EXT_PATTERN, region.pattern_id)
            set_item_ext(it, SEQ_EXT_POOL, region.pool_id)
          end
        end
      end
    end
  else
    sync_seq_region(region)
    if old_pattern_id then
      sync_seq_pattern_regions(old_pattern_id)
    end
  end
  if own then
    end_seq_undo("Unlink sequencer region")
  end
end

function seq_delete_region_by_id(region_id)
  state.selected_seq_region_id = region_id
  delete_selected_seq_region()
end

function seq_region_containing_qn(qn, ignore_id)
  qn = qn or 0.0
  for _, reg in ipairs(state.seq_regions or {}) do
    if reg.id ~= ignore_id then
      local reg_start = reg.start_qn or 0.0
      local reg_end = reg_start + get_seq_region_length_qn(reg)
      if qn >= reg_start - 0.000001 and qn < reg_end - 0.000001 then
        return reg
      end
    end
  end
  return nil
end

function seq_region_insert_qn(hover_qn, ignore_id)
  hover_qn = math.max(0.0, hover_qn or 0.0)
  local inside = seq_region_containing_qn(hover_qn, ignore_id)
  if inside then
    return inside.start_qn or 0.0, inside
  end
  local prev_end, next_reg = nil, nil
  for _, reg in ipairs(state.seq_regions or {}) do
    if reg.id ~= ignore_id then
      local reg_start = reg.start_qn or 0.0
      local reg_end = reg_start + get_seq_region_length_qn(reg)
      if reg_end <= hover_qn + 0.000001 and (not prev_end or reg_end > prev_end) then
        prev_end = reg_end
      end
      if reg_start >= hover_qn - 0.000001 and (not next_reg or reg_start < (next_reg.start_qn or 0.0)) then
        next_reg = reg
      end
    end
  end
  local four_qn = 16.0
  if prev_end then
    four_qn = get_seq_region_length_qn({ start_qn = prev_end, length_bars = 4 })
  elseif next_reg then
    four_qn = get_seq_region_length_qn({ start_qn = next_reg.start_qn or 0.0, length_bars = 4 })
  end
  if next_reg and ((next_reg.start_qn or 0.0) - hover_qn) <= four_qn + 0.000001 then
    return next_reg.start_qn or 0.0, next_reg
  end
  if prev_end and (hover_qn - prev_end) <= four_qn + 0.000001 then
    return prev_end, nil
  end
  return hover_qn, nil
end

function seq_shift_regions_from(from_qn, delta_qn, ignore_id)
  from_qn = from_qn or 0.0
  delta_qn = delta_qn or 0.0
  if math.abs(delta_qn) < 0.000001 then
    return false
  end
  local affected = {}
  for _, reg in ipairs(state.seq_regions or {}) do
    if reg.id ~= ignore_id and (reg.start_qn or 0.0) >= from_qn - 0.000001 then
      table.insert(affected, reg)
    end
  end
  if #affected == 0 then
    return false
  end
  for _, reg in ipairs(affected) do
    remove_seq_rendered_items(reg)
    reg.start_qn = (reg.start_qn or 0.0) + delta_qn
  end
  sort_seq_regions()
  for _, reg in ipairs(affected) do
    sync_seq_region(reg)
  end
  return true
end

function seq_pack_overlapping_regions()
  sort_seq_regions()
  local changed = false
  for i = 2, #(state.seq_regions or {}) do
    local prev = state.seq_regions[i - 1]
    local cur = state.seq_regions[i]
    local prev_end = (prev.start_qn or 0.0) + get_seq_region_length_qn(prev)
    if (cur.start_qn or 0.0) < prev_end - 0.000001 then
      remove_seq_rendered_items(cur)
      cur.start_qn = prev_end
      sync_seq_region(cur)
      changed = true
    end
  end
  return changed
end

function seq_swap_region_positions(a, b)
  if not a or not b or a.id == b.id then
    return false
  end
  local a_start = a.start_qn or 0.0
  local b_start = b.start_qn or 0.0
  if math.abs(a_start - b_start) < 0.000001 then
    return false
  end
  remove_seq_rendered_items(a)
  remove_seq_rendered_items(b)
  a.start_qn = b_start
  b.start_qn = a_start
  sort_seq_regions()
  seq_pack_overlapping_regions()
  save_config()
  sync_seq_region(a)
  sync_seq_region(b)
  return true
end

function seq_draw_region_ghost(dl, start_qn, end_qn, y0, h, timeline_x0, timeline_w, qn_to_x, fill, edge, label)
  if not dl or not qn_to_x then
    return
  end
  local gx0 = math.max(timeline_x0, qn_to_x(start_qn or 0.0))
  local gx1 = math.min(timeline_x0 + timeline_w, qn_to_x(end_qn or start_qn or 0.0))
  if gx1 <= gx0 + 1.0 then
    return
  end
  r.ImGui_DrawList_AddRectFilled(dl, gx0 + 1, y0 + 3, gx1 - 1, y0 + h - 3, fill or 0x4A8BD688, 4.0)
  r.ImGui_DrawList_AddRect(dl, gx0 + 1, y0 + 3, gx1 - 1, y0 + h - 3, edge or 0x4A8BD6FF, 4.0, 0, 1.4)
  if label and label ~= "" then
    local tw = select(1, r.ImGui_CalcTextSize(ctx, label)) or 24.0
    if gx1 - gx0 > tw + 10.0 then
      r.ImGui_DrawList_AddText(dl, gx0 + 6, y0 + 5, 0xFFFFFFFF, label)
    end
  end
end

function seq_move_region_to(region, desired_start_qn)
  if not region then
    return false
  end
  local length_qn = get_seq_region_length_qn(region)
  desired_start_qn = math.max(0.0, desired_start_qn)
  local delta = desired_start_qn - (region.start_qn or 0.0)
  local new_start
  if delta < 0 then
    new_start = find_prev_non_overlapping_region_start(desired_start_qn, length_qn, region.id)
  else
    new_start = find_non_overlapping_region_start(desired_start_qn, length_qn, region.id)
  end
  if math.abs(new_start - (region.start_qn or 0.0)) < 0.000001 then
    return false
  end
  remove_seq_rendered_items(region)
  region.start_qn = new_start
  sort_seq_regions()
  save_config()
  sync_seq_region(region)
  return true
end

function seq_resize_region_end(region, new_end_qn, step_qn)
  if not region then
    return false
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  new_end_qn = seq_snap_qn_for_region_drag(new_end_qn, step_qn)
  local reg_start = region.start_qn or 0.0
  new_end_qn = math.max(new_end_qn, reg_start + step_qn)
  for _, other in ipairs(state.seq_regions) do
    if other.id ~= region.id then
      local other_start = other.start_qn or 0.0
      if other_start > reg_start and other_start < new_end_qn then
        new_end_qn = other_start
      end
    end
  end
  local length_qn = new_end_qn - reg_start
  if length_qn < step_qn then
    return false
  end
  local bars = seq_qn_length_to_bars(reg_start, length_qn)
  if bars == region.length_bars then
    return false
  end
  remove_seq_rendered_items(region)
  region.length_bars = bars
  save_config()
  sync_seq_region(region)
  return true
end

function seq_resize_region_start(region, new_start_qn, step_qn)
  if not region then
    return false
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local reg_end = (region.start_qn or 0.0) + get_seq_region_length_qn(region)
  new_start_qn = seq_snap_qn_for_region_drag(math.max(0.0, new_start_qn), step_qn)
  new_start_qn = math.min(new_start_qn, reg_end - step_qn)
  for _, other in ipairs(state.seq_regions) do
    if other.id ~= region.id then
      local other_end = (other.start_qn or 0.0) + get_seq_region_length_qn(other)
      if other_end > new_start_qn and other_end <= reg_end then
        new_start_qn = math.max(new_start_qn, other_end)
      end
    end
  end
  local length_qn = reg_end - new_start_qn
  if length_qn < step_qn then
    return false
  end
  local bars = seq_qn_length_to_bars(new_start_qn, length_qn)
  if math.abs(new_start_qn - (region.start_qn or 0.0)) < 0.000001 and bars == region.length_bars then
    return false
  end
  remove_seq_rendered_items(region)
  region.start_qn = new_start_qn
  region.length_bars = bars
  sort_seq_regions()
  save_config()
  sync_seq_region(region)
  return true
end

function seq_split_qn_for_region(region, split_qn, step_qn)
  if not region then
    return nil
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  split_qn = seq_snap_qn_to_bar(split_qn, step_qn)
  local reg_start = region.start_qn or 0.0
  local reg_end = reg_start + get_seq_region_length_qn(region)
  if split_qn <= reg_start + 0.0001 or split_qn >= reg_end - 0.0001 then
    return nil
  end
  local left_bars = seq_qn_length_to_bars(reg_start, split_qn - reg_start)
  local right_bars = seq_qn_length_to_bars(split_qn, reg_end - split_qn)
  if left_bars < 1 or right_bars < 1 then
    return nil
  end
  local left_len = get_seq_region_length_qn({ start_qn = reg_start, length_bars = left_bars })
  local right_len = get_seq_region_length_qn({ start_qn = split_qn, length_bars = right_bars })
  if left_len < step_qn or right_len < step_qn then
    return nil
  end
  return split_qn, left_bars, right_bars
end

function seq_remap_pattern_notes_from_step(pattern, split_step, grid_qn)
  if not pattern or type(pattern.notes) ~= "table" then
    return
  end
  grid_qn = grid_qn or state.seq_grid_qn or 0.25
  local split_qn = split_step * grid_qn
  for track_id, notes in pairs(pattern.notes) do
    if type(notes) == "table" then
      local remapped = {}
      for step_key, note in pairs(notes) do
        if type(note) == "table" then
          local qn = seq_note_qn_offset(note, step_key, grid_qn)
          if qn >= split_qn - 1e-9 then
            local new_note = clone_table_deep(note)
            new_note.qn_offset = qn - split_qn
            new_note.step = math.floor((new_note.qn_offset / grid_qn) + 1e-9)
            remapped[seq_storage_key_from_qn(new_note.qn_offset)] = new_note
          end
        end
      end
      pattern.notes[track_id] = remapped
    end
  end
end

function seq_prune_pattern_notes_from_step(pattern, split_step, grid_qn)
  if not pattern or type(pattern.notes) ~= "table" then
    return
  end
  grid_qn = grid_qn or state.seq_grid_qn or 0.25
  local split_qn = split_step * grid_qn
  for _, notes in pairs(pattern.notes) do
    if type(notes) == "table" then
      for step_key, note in pairs(notes) do
        local qn = seq_note_qn_offset(note, step_key, grid_qn)
        if qn >= split_qn - 1e-9 then
          notes[step_key] = nil
        end
      end
    end
  end
end

function seq_split_region(region, split_qn, step_qn)
  local snapped_qn, left_bars, right_bars = seq_split_qn_for_region(region, split_qn, step_qn)
  if not snapped_qn then
    return nil
  end
  local own = seq_undo_own_begin("Split sequencer region")
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local grid_qn = state.seq_grid_qn or 0.25
  local split_step = math.max(1, math.floor(((snapped_qn - (region.start_qn or 0.0)) / grid_qn) + 0.5))

  local src_pattern = get_seq_pattern(region.pattern_id, false)
  local new_pattern_id = alloc_seq_pattern()
  local cloned = clone_table_deep(src_pattern or { notes = {} })
  seq_remap_pattern_notes_from_step(cloned, split_step, grid_qn)
  state.seq_patterns[tostring(new_pattern_id)] = cloned

  if not seq_region_is_linked(region) then
    seq_prune_pattern_notes_from_step(src_pattern, split_step, grid_qn)
  end

  remove_seq_rendered_items(region)
  region.length_bars = left_bars

  local right = {
    id = state.seq_region_next_id,
    name = seq_auto_name_new_region(snapped_qn, region.id),
    start_qn = snapped_qn,
    length_bars = right_bars,
    pool_id = alloc_seq_pool(),
    pattern_id = new_pattern_id,
    style_key = region.style_key,
    style_source = region.style_source,
    kit_genres = region.kit_genres and clone_table_deep(region.kit_genres) or nil,
    groove = normalize_seq_groove(region.groove),
    track_samples = seq_clone_region_track_samples(region),
  }
  state.seq_region_next_id = state.seq_region_next_id + 1
  table.insert(state.seq_regions, right)
  sort_seq_regions()
  save_config()
  sync_seq_region(region)
  sync_seq_region(right)
  if own then
    end_seq_undo("Split sequencer region")
  end
  return right
end

function seq_draw_link_icon(dl, icon_x0, icon_y0, color, hovered)
  local sz = SEQ_LINK_ICON_SIZE
  if hovered then
    local pad = 2.0
    r.ImGui_DrawList_AddRectFilled(dl, icon_x0 - pad, icon_y0 - pad, icon_x0 + sz + pad, icon_y0 + sz + pad, 0xFFFFFF22, 3.0)
    color = 0xF2F7FCDD
  else
    color = 0xE4EEF698
  end
  local img = get_vfx_icon("Link")
  if img and r.ImGui_DrawList_AddImage then
    if r.ImGui_ValidatePtr and not r.ImGui_ValidatePtr(img, "ImGui_Image*") then
      vfx_icon_images.attached_ctx = nil
      img = get_vfx_icon("Link")
    end
    if img then
      r.ImGui_DrawList_AddImage(dl, img, icon_x0, icon_y0, icon_x0 + sz, icon_y0 + sz, nil, nil, nil, nil, color)
      return
    end
  end
  local cx0 = icon_x0 + 2.5
  local cy = icon_y0 + sz * 0.5
  local cx1 = icon_x0 + sz - 2.5
  r.ImGui_DrawList_AddCircle(dl, cx0, cy, 2.2, color, 10, 1.1)
  r.ImGui_DrawList_AddCircle(dl, cx1, cy, 2.2, color, 10, 1.1)
  r.ImGui_DrawList_AddLine(dl, cx0 + 1.6, cy, cx1 - 1.6, cy, color, 1.1)
end

function seq_hit_test_region_at(mx, my, y0, region_lane_h, timeline_x0, timeline_w, start_qn, qn_span, qn_to_x_fn)
  if my < y0 or my > y0 + region_lane_h or mx < timeline_x0 or mx > timeline_x0 + timeline_w then
    return nil
  end
  local clicked_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, start_qn, qn_span)
  for i = #state.seq_regions, 1, -1 do
    local reg = state.seq_regions[i]
    local reg_start = reg.start_qn or 0.0
    local reg_end = reg_start + get_seq_region_length_qn(reg)
    if clicked_qn >= reg_start and clicked_qn <= reg_end then
      local raw_rx0 = qn_to_x_fn(reg_start)
      local raw_rx1 = qn_to_x_fn(reg_end)
      local rx0 = math.max(timeline_x0, raw_rx0)
      local rx1 = math.min(timeline_x0 + timeline_w, raw_rx1)
      if seq_region_is_linked(reg) and (rx1 - rx0) >= (SEQ_LINK_ICON_SIZE + SEQ_LINK_HIT_PAD * 2 + 8) then
        local icon_x0, icon_y0, icon_x1, icon_y1 = seq_region_link_hit_rect(rx0, y0, region_lane_h)
        if mx >= icon_x0 and mx <= icon_x1 and my >= icon_y0 and my <= icon_y1 then
          return { region = reg, part = "link" }
        end
      end
      local _, has_prob, has_human, has_vel, has_vary, has_stut, has_ghost, has_grace, has_after = seq_collect_region_random_entries(reg)
      if has_prob or has_human or has_vel or has_vary or has_stut or has_ghost then
        local vis_x0 = rx0
        if seq_region_is_linked(reg) and (rx1 - rx0) >= (SEQ_LINK_ICON_SIZE + SEQ_LINK_HIT_PAD * 2 + 8) then
          vis_x0 = rx0 + SEQ_LINK_ICON_SIZE + SEQ_LINK_HIT_PAD + 8
        end
        local vis_x1 = rx1
        local labels = seq_region_random_label_layout(vis_x0, vis_x1, y0, region_lane_h, has_prob, has_human, has_vel, has_vary, has_stut, has_ghost, has_grace, has_after)
        for _, lab in ipairs(labels) do
          if mx >= lab.x0 and mx <= lab.x1 and my >= lab.y0 and my <= lab.y1 then
            local part = "rand_human"
            if lab.kind == "all" then
              part = "rand_all"
            elseif lab.kind == "prob" then
              part = "rand_prob"
            elseif lab.kind == "vel" then
              part = "rand_vel"
            elseif lab.kind == "vary" then
              part = "rand_vary"
            elseif lab.kind == "stut" then
              part = "rand_stut"
            elseif lab.kind == "grace" then
              part = "rand_grace"
            elseif lab.kind == "after" then
              part = "rand_after"
            elseif lab.kind == "ghost" then
              part = "rand_ghost"
            end
            return { region = reg, part = part }
          end
        end
      end
      if mx - raw_rx0 <= SEQ_REGION_EDGE_PX then
        return { region = reg, part = "left_edge" }
      elseif raw_rx1 - mx <= SEQ_REGION_EDGE_PX then
        return { region = reg, part = "right_edge" }
      end
      return { region = reg, part = "body" }
    end
  end
  return nil
end

function seq_get_default_create_region_qn(hover_qn, step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  hover_qn = seq_snap_qn_for_region_drag(hover_qn or 0.0, step_qn)

  local create_start_qn, next_reg = seq_region_insert_qn(hover_qn, nil)
  local create_length_qn = get_seq_region_length_qn({ start_qn = create_start_qn, length_bars = 4 })
  local insert = next_reg ~= nil or seq_region_overlaps(create_start_qn, create_length_qn, nil)
  if not insert then
    create_start_qn = find_non_overlapping_region_start(create_start_qn, create_length_qn, nil)
  end
  return create_start_qn, create_length_qn, insert
end

function seq_region_is_linked(reg)
  if not reg then
    return false
  end
  if seq_region_pool_count(reg.pool_id) > 1 then
    return true
  end
  for _, other in ipairs(state.seq_regions) do
    if other.id ~= reg.id and other.pattern_id == reg.pattern_id then
      return true
    end
  end
  return false
end

function seq_region_in_link_group(reg, hover)
  if not reg or not hover then
    return false
  end
  if seq_region_pool_count(hover.pool_id) > 1
      and tonumber(reg.pool_id) == tonumber(hover.pool_id) then
    return true
  end
  if hover.pattern_id and reg.pattern_id == hover.pattern_id and seq_region_is_linked(hover) then
    return true
  end
  return false
end

function seq_linked_region_names(region)
  local names = {}
  if not region then
    return names
  end
  for _, reg in ipairs(state.seq_regions or {}) do
    if reg.id ~= region.id and seq_region_in_link_group(reg, region) then
      names[#names + 1] = (reg.name and reg.name ~= "" and reg.name) or ("Region " .. tostring(reg.id))
    end
  end
  return names
end

function seq_mouse_over_script_ui()
  if not r.ImGui_IsWindowHovered then
    return false
  end
  local flags = 0
  if r.ImGui_HoveredFlags_AnyWindow then
    flags = r.ImGui_HoveredFlags_AnyWindow()
  elseif r.ImGui_HoveredFlags_RootAndChildWindows then
    flags = r.ImGui_HoveredFlags_RootAndChildWindows()
  end
  return r.ImGui_IsWindowHovered(ctx, flags)
end

function seq_region_from_arrange_parent_geometry()
  if not r.GetMousePosition then
    return nil
  end
  local mx, my = r.GetMousePosition()
  local geo = seq_get_arrange_geometry()
  if not geo or not geo.l then
    return nil
  end
  if mx < geo.l or mx > geo.r or my < geo.t or my > geo.b then
    return nil
  end
  local t0, t1 = get_arrange_view_range()
  if not t0 or not t1 or t1 <= t0 then
    return nil
  end
  local view_w = geo.r - geo.l
  if view_w < 4 then
    return nil
  end
  for _, reg in ipairs(state.seq_regions or {}) do
    local item = reg.parent_item_guid and seq_find_item_by_guid(reg.parent_item_guid)
    local track = item and r.GetMediaItemTrack and r.GetMediaItemTrack(item)
    if item and track then
      local pos = r.GetMediaItemInfo_Value(item, "D_POSITION") or 0
      local len = r.GetMediaItemInfo_Value(item, "D_LENGTH") or 0
      local x0 = geo.l + ((pos - t0) / (t1 - t0)) * view_w
      local x1 = geo.l + ((pos + len - t0) / (t1 - t0)) * view_w
      local tcp_y = r.GetMediaTrackInfo_Value(track, "I_TCPY") or 0
      local last_y = r.GetMediaItemInfo_Value(item, "I_LASTY") or 0
      local last_h = r.GetMediaItemInfo_Value(item, "I_LASTH") or 0
      if last_h <= 1 then
        last_h = r.GetMediaTrackInfo_Value(track, "I_TCPH") or 24
      end
      local y0 = geo.t + tcp_y + last_y
      local y1 = y0 + last_h
      if mx >= x0 and mx <= x1 and my >= y0 and my <= y1 then
        return reg
      end
    end
  end
  return nil
end

function seq_region_from_arrange_parent_hover()
  if seq_mouse_over_script_ui() or not seq_mouse_over_reaper() then
    return nil
  end
  if r.GetItemFromPoint and r.GetMousePosition then
    local x, y = r.GetMousePosition()
    local item = r.GetItemFromPoint(x, y, true)
    if item and seq_item_is_parent_marker(item) then
      local rid = tonumber(get_item_ext(item, SEQ_EXT_REGION) or "")
      local reg = get_seq_region_by_id(rid)
      if reg then
        return reg
      end
    end
  end
  return seq_region_from_arrange_parent_geometry()
end

function seq_update_link_hover(mx, my, y0, region_lane_h, timeline_x0, timeline_w, start_qn, qn_span, qn_to_x)
  state.seq_link_hover_region_id = nil
  local hover_reg = nil
  if seq_mouse_over_script_ui() and my >= y0 and my <= y0 + region_lane_h and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w then
    local hit = seq_hit_test_region_at(mx, my, y0, region_lane_h, timeline_x0, timeline_w, start_qn, qn_span, qn_to_x)
    if hit and hit.region then
      hover_reg = hit.region
    end
  elseif seq_mouse_over_reaper() then
    hover_reg = seq_region_from_arrange_parent_hover()
  end
  if hover_reg and seq_region_is_linked(hover_reg) then
    state.seq_link_hover_region_id = hover_reg.id
  end
  return get_seq_region_by_id(state.seq_link_hover_region_id)
end

function seq_region_at_qn(qn)
  for _, reg in ipairs(state.seq_regions) do
    local reg_start = reg.start_qn or 0.0
    local reg_end = reg_start + get_seq_region_length_qn(reg)
    if qn >= reg_start and qn < reg_end then
      return reg
    end
  end
  return nil
end

function seq_build_visible_active_cells(start_qn, end_qn, step_qn, step_count)
  local active_cells = {}
  for _, slot in ipairs(state.seq_tracks) do
    active_cells[slot.id] = {}
  end
  for _, reg in ipairs(state.seq_regions) do
    local reg_start = reg.start_qn or 0.0
    local reg_end = reg_start + get_seq_region_length_qn(reg)
    if reg_end >= start_qn and reg_start <= end_qn then
      local pattern = get_seq_pattern(reg.pattern_id, false)
      if pattern then
        for _, slot in ipairs(state.seq_tracks) do
          local notes = get_track_note_table(pattern, slot.id, false)
          if notes then
            for step_key, note in pairs(notes) do
              if type(note) == "table" and note.enabled ~= false
                 and seq_note_in_region(reg, note, step_key, step_qn) then
                local abs_qn = seq_note_abs_qn(reg, note, step_key, step_qn)
                local vis_qn = seq_note_visual_abs_qn(reg, note, step_key, step_qn)
                -- Hit-testing occupies the start cell (and stutter span). Head
                -- and sustain that draw into later cells stay empty so those
                -- grids can be painted.
                local span = seq_stutter_span_qn(note, step_qn) or 0.0
                local occupy_end = vis_qn + math.max(span, 1e-9)
                if occupy_end > start_qn - step_qn and vis_qn < end_qn + step_qn then
                  local entry = {
                    key = step_key,
                    note = note,
                    region_id = reg.id,
                    abs_qn = abs_qn,
                  }
                  local col0 = math.floor(((vis_qn - start_qn) / step_qn) + 1e-9)
                  local col1 = math.floor(((occupy_end - 1e-9 - start_qn) / step_qn) + 1e-9)
                  for col = math.max(0, col0), math.min(step_count - 1, col1) do
                    seq_active_cells_put(active_cells, slot.id, col, entry, start_qn, step_qn, step_count)
                  end
                end
              end
            end
          end
        end
      end
    end
  end
  return active_cells
end

function seq_dim_color_rrgbbaa(color, dim)
  if not dim then
    return color
  end
  local cr, cg, cb = extract_rgb_rrgbbaa(color or 0xFFFFFFFF)
  local alpha = math.max(20, math.floor((color or 0xFF) % 256 * 0.38))
  return build_color_rrgbbaa(cr, cg, cb, alpha)
end

function seq_note_sustain_split_x(cell_x1, draw_x0, draw_x1)
  local cell_content_end = cell_x1 - 2
  if draw_x1 > cell_content_end + 1.0 and draw_x0 < cell_content_end - 0.5 then
    return cell_content_end
  end
  return nil
end

-- High-contrast palette so different variant samples stay easy to tell apart.
SEQ_VARY_COLOR_PALETTE = {
  {230, 25, 75},
  {60, 180, 75},
  {0, 130, 200},
  {245, 130, 48},
  {145, 30, 180},
  {70, 240, 240},
  {240, 50, 230},
  {210, 245, 60},
  {0, 128, 128},
  {255, 225, 25},
  {128, 0, 0},
  {0, 0, 128},
  {170, 255, 195},
  {255, 99, 146},
  {139, 92, 246},
  {249, 115, 22},
}

-- Stable color keyed by sample path (not frequency).
-- Same file always gets the same RGB so copies match the source note.
function seq_sample_vary_rgb(path)
  if type(path) == "table" then
    path = path.path
  end
  if type(path) ~= "string" or path == "" then
    return nil
  end
  local h = 2166136261
  for i = 1, #path do
    h = (h + string.byte(path, i)) * 16777619
    h = h % 2147483647
  end
  local pal = SEQ_VARY_COLOR_PALETTE
  local rgb = pal[(h % #pal) + 1]
  return rgb[1], rgb[2], rgb[3]
end

function seq_note_vary_origin_path(note, slot, region)
  if note and type(note.vary_origin_path) == "string" and note.vary_origin_path ~= "" then
    return note.vary_origin_path
  end
  local path = seq_effective_slot_sample_path and select(1, seq_effective_slot_sample_path(slot, region))
  return path or (slot and slot.sample_path) or (note and note.sample_path)
end

function seq_note_vary_rgb(note, sounding_path)
  local stored = note and note.vary_rgb
  if type(stored) == "table" and stored[1] and stored[2] and stored[3] then
    return stored[1], stored[2], stored[3]
  end
  return seq_sample_vary_rgb(sounding_path)
end

function seq_stamp_vary_visual(target, sounding_path, origin_path)
  if type(target) ~= "table" or type(sounding_path) ~= "string" or sounding_path == "" then
    return
  end
  if type(origin_path) == "string" and origin_path ~= "" and origin_path ~= sounding_path then
    if type(target.vary_origin_path) ~= "string" or target.vary_origin_path == "" then
      target.vary_origin_path = origin_path
    end
    if type(target.vary_rgb) ~= "table" then
      local vr, vg, vb = seq_sample_vary_rgb(sounding_path)
      if vr then
        target.vary_rgb = { vr, vg, vb }
      end
    end
  end
end

function draw_seq_note_vary_marks(dl, draw_x0, draw_x1, block_y0, block_y1, vr, vg, vb, note_alpha)
  local w = draw_x1 - draw_x0
  local h = block_y1 - block_y0
  if w < 6.0 or h < 6.0 then
    return
  end
  local mark_a = math.max(90, math.min(255, math.floor(note_alpha)))
  local col = build_color_rrgbbaa(vr, vg, vb, mark_a)
  local stripe_w = math.min(2.5, w * 0.18)
  r.ImGui_DrawList_AddRectFilled(dl, draw_x0, block_y0, draw_x0 + stripe_w, block_y1, col, 0)
  local pip = math.min(6.0, w * 0.35, h * 0.45)
  r.ImGui_DrawList_AddTriangleFilled(
    dl,
    draw_x0, block_y0,
    draw_x0 + pip, block_y0,
    draw_x0, block_y0 + pip,
    col
  )
end

function draw_seq_note_body(dl, draw_x0, draw_x1, block_y0, block_y1, br, bg, bb, note_alpha, border_alpha, sustain_split_x, vr, vg, vb)
  local varied = vr ~= nil
  local fill_x1 = sustain_split_x or draw_x1
  if varied and r.ImGui_DrawList_AddRectFilledMultiColor and (fill_x1 - draw_x0) >= 4.0 then
    local c_l = build_color_rrgbbaa(br, bg, bb, note_alpha)
    local c_r = build_color_rrgbbaa(vr, vg, vb, note_alpha)
    r.ImGui_DrawList_AddRectFilledMultiColor(dl, draw_x0, block_y0, fill_x1, block_y1, c_l, c_r, c_r, c_l)
  else
    r.ImGui_DrawList_AddRectFilled(
      dl, draw_x0, block_y0, fill_x1, block_y1,
      build_color_rrgbbaa(br, bg, bb, note_alpha), 0
    )
  end
  r.ImGui_DrawList_AddRect(
    dl, draw_x0, block_y0, fill_x1, block_y1,
    build_color_rrgbbaa(255, 255, 255, border_alpha), 0, 0, 1.0
  )

  if sustain_split_x then
    -- Tail is a thinner faded bar so grid lines stay readable under long samples.
    local tail_inset = (block_y1 - block_y0) * 0.32
    local ty0 = block_y0 + tail_inset
    local ty1 = block_y1 - tail_inset
    local tail_a0 = math.max(6, math.floor(note_alpha * 0.18))
    local tail_a1 = math.max(0, math.floor(note_alpha * 0.04))
    local tr, tg, tb = br, bg, bb
    if varied then
      tr, tg, tb = vr, vg, vb
    end
    if r.ImGui_DrawList_AddRectFilledMultiColor then
      local c0 = build_color_rrgbbaa(tr, tg, tb, tail_a0)
      local c1 = build_color_rrgbbaa(tr, tg, tb, tail_a1)
      r.ImGui_DrawList_AddRectFilledMultiColor(dl, sustain_split_x, ty0, draw_x1, ty1, c0, c1, c1, c0)
    else
      r.ImGui_DrawList_AddRectFilled(
        dl, sustain_split_x, ty0, draw_x1, ty1,
        build_color_rrgbbaa(tr, tg, tb, tail_a0), 0
      )
    end
  end

end

function draw_seq_stutter_note_hits(dl, qn_to_x, note, note_qn, step_qn, draw_x0, draw_x1, block_y0, block_y1, br, bg, bb, note_alpha, border_alpha, vr, vg, vb)
  local count = seq_stutter_count(note)
  if count <= 1 or not qn_to_x then
    draw_seq_note_body(dl, draw_x0, draw_x1, block_y0, block_y1, br, bg, bb, note_alpha, border_alpha, nil, vr, vg, vb)
    return
  end
  local h = block_y1 - block_y0
  local span_a = math.max(12, math.floor(note_alpha * 0.18))
  local inset = h * 0.30
  r.ImGui_DrawList_AddRectFilled(
    dl, draw_x0, block_y0 + inset, draw_x1, block_y1 - inset,
    build_color_rrgbbaa(br, bg, bb, span_a), 0
  )

  local attack_a = math.min(255, math.max(160, note_alpha + 50))
  local tail_a = math.max(28, math.floor(note_alpha * 0.38))
  local start_a = math.min(255, math.max(170, border_alpha + 90))
  local note_off = (note and note.offset_qn) or 0.0
  local has_mc = r.ImGui_DrawList_AddRectFilledMultiColor ~= nil

  for hi = 1, count do
    local hit_off = seq_note_param_value(note, "offset_qn", hi)
    if hit_off == nil then
      hit_off = note_off
    end
    local off0, off1, slice_qn = seq_stutter_hit_span(note, hi, step_qn)
    local s0 = note_qn + hit_off + off0
    local sx0 = (hi == 1) and draw_x0 or qn_to_x(s0)
    if sx0 < draw_x0 then sx0 = draw_x0 end
    if sx0 < draw_x1 then
    local slice_px = qn_to_x(s0 + slice_qn) - qn_to_x(s0)
    if slice_px < 1.0 then slice_px = 1.0 end
    local gap = (slice_px >= 5.0) and math.max(1.4, math.min(3.2, slice_px * 0.20)) or 0.8
    local sx1 = math.min(draw_x1, qn_to_x(s0 + slice_qn) - gap)
    if sx1 < sx0 + 1.0 then
      sx1 = math.min(draw_x1, sx0 + 1.0)
    end

    local tr = (vr ~= nil) and vr or br
    local tg = (vg ~= nil) and vg or bg
    local tb = (vb ~= nil) and vb or bb
    if has_mc and (sx1 - sx0) >= 3.5 then
      local c0 = build_color_rrgbbaa(br, bg, bb, note_alpha)
      local c1 = build_color_rrgbbaa(tr, tg, tb, tail_a)
      r.ImGui_DrawList_AddRectFilledMultiColor(dl, sx0, block_y0, sx1, block_y1, c0, c1, c1, c0)
    else
      r.ImGui_DrawList_AddRectFilled(
        dl, sx0, block_y0, sx1, block_y1,
        build_color_rrgbbaa(br, bg, bb, note_alpha), 0
      )
    end

    local aw = math.min(3.0, math.max(1.2, (sx1 - sx0) * 0.30))
    local ar = math.floor(br * 0.28 + 255 * 0.72)
    local ag = math.floor(bg * 0.28 + 255 * 0.72)
    local ab = math.floor(bb * 0.28 + 255 * 0.72)
    r.ImGui_DrawList_AddRectFilled(dl, sx0, block_y0, sx0 + aw, block_y1, build_color_rrgbbaa(ar, ag, ab, attack_a), 0)
    r.ImGui_DrawList_AddLine(dl, sx0, block_y0, sx0, block_y1, build_color_rrgbbaa(255, 255, 255, start_a), 1.4)
    if h >= 8.0 and (sx1 - sx0) >= 4.0 then
      local pip = math.min(4.5, h * 0.38, (sx1 - sx0) * 0.45)
      r.ImGui_DrawList_AddTriangleFilled(
        dl,
        sx0, block_y0,
        sx0 + pip, block_y0,
        sx0, block_y0 + pip,
        build_color_rrgbbaa(255, 255, 255, start_a)
      )
    end
    end
  end
end

function draw_seq_note_hover(dl, mx, my, draw_x0, block_y0, draw_x1, block_y1, trigger_x1)
  local x1 = trigger_x1 or draw_x1
  if mx < draw_x0 - 2.0 or mx > x1 + 2.0 or my < block_y0 - 2.0 or my > block_y1 + 2.0 then
    return
  end
  r.ImGui_DrawList_AddRectFilled(dl, draw_x0, block_y0, x1, block_y1, 0xFFFFFF38, 2.0)
  r.ImGui_DrawList_AddRect(dl, draw_x0 - 1.0, block_y0 - 1.0, x1 + 1.0, block_y1 + 1.0, 0xFFFFFFF0, 2.0, 0, 1.6)
end

SEQ_DECAY_CIRCLE_R = 5.0
SEQ_DECAY_CIRCLE_HIT_R = 9.0
SEQ_DECAY_LINE_HIT = 7.0
SEQ_DECAY_CURVE_HIT = 10.0
seq_decay_hits = {}

function seq_decay_clear_hits()
  seq_decay_hits = {}
end

function seq_decay_add_hit(hit)
  seq_decay_hits[#seq_decay_hits + 1] = hit
end

function seq_decay_kind_is_circle(kind)
  return kind == "fade_in" or kind == "fade_out"
end

function seq_decay_kind_is_curve(kind)
  return kind == "curve_in" or kind == "curve_out"
end

function seq_decay_hit_at(mx, my)
  local hits = seq_decay_hits
  if not hits or #hits == 0 then
    return nil
  end
  local best, best_d = nil, 1e9
  for i = 1, #hits do
    local h = hits[i]
    if seq_decay_kind_is_circle(h.kind) then
      local dx = mx - h.cx
      local dy = my - h.cy
      local d = dx * dx + dy * dy
      local rad = h.hit_r or SEQ_DECAY_CIRCLE_HIT_R
      if d <= rad * rad and d < best_d then
        best = h
        best_d = d
      end
    end
  end
  if best then
    return best
  end
  best, best_d = nil, 1e9
  for i = 1, #hits do
    local h = hits[i]
    if seq_decay_kind_is_curve(h.kind) and h.cx then
      local dx = mx - h.cx
      local dy = my - h.cy
      local d = dx * dx + dy * dy
      local rad = (h.hit_r or SEQ_DECAY_CIRCLE_HIT_R)
      if d <= rad * rad and d < best_d then
        best = h
        best_d = d
      end
    end
  end
  if best then
    return best
  end
  best, best_d = nil, 1e9
  for i = 1, #hits do
    local h = hits[i]
    if seq_decay_kind_is_curve(h.kind) and h.x0 and mx >= h.x0 - 1 and mx <= h.x1 + 1 then
      local y = seq_fade_curve_y_at(mx, h.x0, h.x1, h.y0, h.y1, h.shape, h.curve, h.fade_out)
      local d = math.abs(my - y)
      if d <= SEQ_DECAY_CURVE_HIT and d < best_d then
        best = h
        best_d = d
      end
    end
  end
  if best then
    return best
  end
  for i = 1, #hits do
    local h = hits[i]
    if h.kind == "end" and mx >= h.x0 and mx <= h.x1 and my >= h.y0 and my <= h.y1 then
      return h
    end
  end
  return nil
end

function seq_fade_curve_y_at(x, x0, x1, y0, y1, shape, curve, fade_out)
  local span = math.max(1.0, x1 - x0)
  local u = (x - x0) / span
  if u < 0 then u = 0 elseif u > 1 then u = 1 end
  local t = fade_out and (1.0 - u) or u
  local gain = seq_native_fade_gain(t, shape, curve)
  return y1 - (y1 - y0) * gain
end

function seq_draw_native_fade_curve(dl, x0, x1, y0, y1, shape, fade_out, col, fill_col, curve)
  if x1 - x0 < 2.0 then
    return nil, nil
  end
  local h = y1 - y0
  if h < 2.0 then
    return nil, nil
  end
  local steps = math.max(6, math.min(24, math.floor((x1 - x0) / 3.0)))
  local prev_x, prev_y = nil, nil
  local mid_x, mid_y = nil, nil
  for i = 0, steps do
    local u = i / steps
    local t = fade_out and (1.0 - u) or u
    local gain = seq_native_fade_gain(t, shape, curve)
    local x = x0 + (x1 - x0) * u
    local y = y1 - h * gain
    if fill_col then
      r.ImGui_DrawList_AddLine(dl, x, y, x, y1, fill_col, 1.0)
    end
    if prev_x then
      r.ImGui_DrawList_AddLine(dl, prev_x, prev_y, x, y, col, 1.6)
    end
    if i == math.floor(steps * 0.5) then
      mid_x, mid_y = x, y
    end
    prev_x, prev_y = x, y
  end
  return mid_x, mid_y
end

function draw_seq_decay_handles(dl, note, slot, region, pattern, step_key, note_qn, step_qn, qn_to_x, draw_x0, draw_x1, block_y0, block_y1, mx, my, accent, selected)
  if not note then
    return
  end
  local line_col = selected and 0xFFFFFFF0 or 0xFFFFFFAA
  local circle_fill = (accent and seq_lane_color_with_alpha(accent, 255)) or 0xFFD166FF
  local circle_r = SEQ_DECAY_CIRCLE_R
  local cy = block_y0
  local start_x = draw_x0
  local end_x = draw_x1
  local fade_in_qn = seq_note_fade_qn(note, "in")
  local fade_out_qn = seq_note_fade_qn(note, "out")
  local note_off = note.offset_qn or 0.0
  local note_len = seq_note_draw_length_qn(region, pattern, slot, slot and slot.id, step_key, note, nil, step_qn)
  local note_w = math.max(1.0, end_x - start_x)
  local curve_hits = {}
  if fade_in_qn > 1e-6 and note_len > 1e-9 then
    local fade_x1 = start_x + note_w * math.min(1.0, fade_in_qn / note_len)
    local shape = seq_note_fade_shape(note, "in")
    local curve = seq_note_fade_curve(note, "in")
    local mxh, myh = seq_draw_native_fade_curve(
      dl, start_x, math.min(end_x, fade_x1), block_y0, block_y1,
      shape, false,
      seq_lane_color_with_alpha(circle_fill, 220),
      0x00000033,
      curve
    )
    curve_hits[#curve_hits + 1] = {
      kind = "curve_in",
      cx = mxh,
      cy = myh,
      x0 = start_x,
      x1 = math.min(end_x, fade_x1),
      y0 = block_y0,
      y1 = block_y1,
      shape = shape,
      curve = curve,
      fade_out = false,
    }
  end
  if fade_out_qn > 1e-6 and note_len > 1e-9 then
    local fade_x0 = end_x - note_w * math.min(1.0, fade_out_qn / note_len)
    local shape = seq_note_fade_shape(note, "out")
    local curve = seq_note_fade_curve(note, "out")
    local mxh, myh = seq_draw_native_fade_curve(
      dl, math.max(start_x, fade_x0), end_x, block_y0, block_y1,
      shape, true,
      seq_lane_color_with_alpha(circle_fill, 220),
      0x00000033,
      curve
    )
    curve_hits[#curve_hits + 1] = {
      kind = "curve_out",
      cx = mxh,
      cy = myh,
      x0 = math.max(start_x, fade_x0),
      x1 = end_x,
      y0 = block_y0,
      y1 = block_y1,
      shape = shape,
      curve = curve,
      fade_out = true,
    }
  end

  local last_grid_x0 = end_x
  if qn_to_x and note_len and note_len > 1e-9 then
    last_grid_x0 = qn_to_x(note_qn + note_off + math.max(0.0, note_len - (step_qn or 0.25)))
  end
  if last_grid_x0 > end_x - 8.0 then
    last_grid_x0 = end_x - 8.0
  end
  if last_grid_x0 < start_x then
    last_grid_x0 = start_x
  end

  local start_hit = {
    kind = "fade_in",
    cx = start_x,
    cy = cy,
    hit_r = SEQ_DECAY_CIRCLE_HIT_R,
    note = note,
    region_id = region and region.id,
    track_id = slot and slot.id,
    step_key = step_key,
    note_qn = note_qn,
    note_len = note_len,
  }
  local end_line_hit = {
    kind = "end",
    x0 = last_grid_x0,
    x1 = end_x + SEQ_DECAY_LINE_HIT,
    y0 = block_y0 - 2.0,
    y1 = block_y1 + 2.0,
    note = note,
    region_id = region and region.id,
    track_id = slot and slot.id,
    step_key = step_key,
    note_qn = note_qn,
    note_len = note_len,
  }
  local end_hit = {
    kind = "fade_out",
    cx = end_x,
    cy = cy,
    hit_r = SEQ_DECAY_CIRCLE_HIT_R,
    note = note,
    region_id = region and region.id,
    track_id = slot and slot.id,
    step_key = step_key,
    note_qn = note_qn,
    note_len = note_len,
  }
  seq_decay_add_hit(start_hit)
  seq_decay_add_hit(end_hit)
  for i = 1, #curve_hits do
    local ch = curve_hits[i]
    ch.note = note
    ch.region_id = region and region.id
    ch.track_id = slot and slot.id
    ch.step_key = step_key
    ch.note_qn = note_qn
    ch.note_len = note_len
    ch.hit_r = SEQ_DECAY_CIRCLE_HIT_R
    seq_decay_add_hit(ch)
  end
  seq_decay_add_hit(end_line_hit)

  local hover = nil
  if mx and my then
    local dxs = mx - start_x
    local dys = my - cy
    local dxe = mx - end_x
    local dye = my - cy
    if dxs * dxs + dys * dys <= SEQ_DECAY_CIRCLE_HIT_R * SEQ_DECAY_CIRCLE_HIT_R then
      hover = "fade_in"
    elseif dxe * dxe + dye * dye <= SEQ_DECAY_CIRCLE_HIT_R * SEQ_DECAY_CIRCLE_HIT_R then
      hover = "fade_out"
    else
      local best_d = 1e9
      for i = 1, #curve_hits do
        local ch = curve_hits[i]
        if ch.cx then
          local dx = mx - ch.cx
          local dcy = my - ch.cy
          local d = dx * dx + dcy * dcy
          if d <= SEQ_DECAY_CIRCLE_HIT_R * SEQ_DECAY_CIRCLE_HIT_R and d < best_d then
            hover = ch.kind
            best_d = d
          end
        end
        if not hover and ch.x0 and mx >= ch.x0 - 1 and mx <= ch.x1 + 1 then
          local y = seq_fade_curve_y_at(mx, ch.x0, ch.x1, ch.y0, ch.y1, ch.shape, ch.curve, ch.fade_out)
          local d = math.abs(my - y)
          if d <= SEQ_DECAY_CURVE_HIT and d < best_d then
            hover = ch.kind
            best_d = d
          end
        end
      end
      if not hover and mx >= end_line_hit.x0 and mx <= end_line_hit.x1 and my >= end_line_hit.y0 and my <= end_line_hit.y1 then
        hover = "end"
      end
    end
  end

  r.ImGui_DrawList_AddLine(dl, start_x, block_y0, start_x, block_y1, hover == "fade_in" and 0xFFFFFFFF or line_col, 1.6)
  r.ImGui_DrawList_AddLine(dl, end_x, block_y0, end_x, block_y1, hover == "end" and 0xFFFFFFFF or 0xFFFFFFF8, hover == "end" and 3.0 or 2.4)
  if hover == "end" then
    r.ImGui_DrawList_AddRectFilled(dl, last_grid_x0, block_y0, end_x, block_y1, 0xFFFFFF22, 0)
  end

  local function draw_circle(cx, hovered, radius)
    if not cx then
      return
    end
    radius = radius or circle_r
    local r_vis = hovered and (radius + 1.2) or radius
    r.ImGui_DrawList_AddCircleFilled(dl, cx, cy, r_vis, hovered and 0xFFFFFFFF or circle_fill, 16)
    r.ImGui_DrawList_AddCircle(dl, cx, cy, r_vis, 0xFFFFFFF0, 16, 1.4)
  end
  draw_circle(start_x, hover == "fade_in")
  draw_circle(end_x, hover == "fade_out")
  for i = 1, #curve_hits do
    local ch = curve_hits[i]
    if ch.cx and ch.cy then
      local hovered = hover == ch.kind
      local r_vis = hovered and 4.2 or 3.2
      r.ImGui_DrawList_AddCircleFilled(dl, ch.cx, ch.cy, r_vis, hovered and 0xFFFFFFFF or circle_fill, 12)
      r.ImGui_DrawList_AddCircle(dl, ch.cx, ch.cy, r_vis, 0xFFFFFFF0, 12, 1.2)
    end
  end
end

function draw_seq_note_probability_skip(dl, x0, y0, x1, y1, alpha)
  if x1 - x0 < 6.0 or y1 - y0 < 6.0 then
    return
  end
  alpha = math.max(40, math.min(220, alpha or 160))
  local pad = 3.0
  local color = build_color_rrgbbaa(255, 196, 92, alpha)
  r.ImGui_DrawList_AddLine(dl, x0 + pad, y0 + pad, x1 - pad, y1 - pad, color, 1.6)
  r.ImGui_DrawList_AddLine(dl, x1 - pad, y0 + pad, x0 + pad, y1 - pad, color, 1.6)
end

function seq_draw_lane_packed_notes(dl, slot, active, row_y0, row_y1, cx0, cx1, selected_region_id, now_t, step_qn, qn_to_x, edit_def, edit_style, mx, my, hover_on_razor, hover_qn, start_qn, col)
  local pack = seq_active_cell_notes(active)
  if not pack then
    return
  end
  seq_pack_sort_later_on_top(pack)
  local hover_pick = (not hover_on_razor) and seq_pick_packed_note(active, hover_qn, start_qn, col, step_qn) or nil
  for pi = 1, #pack do
    local entry = pack[pi]
    local note = entry.note
    if type(note) == "table" then
      local note_qn = entry.abs_qn or 0.0
      local note_off = note.offset_qn or 0.0
      -- Occupancy cells exist so hit-testing can find spanning stutter notes.
      -- Draw the note only from the cell that contains its visual start.
      local vis_x = qn_to_x(note_qn + note_off)
      if vis_x + 2 >= cx0 - 1.0 and vis_x < cx1 + 1.0 then
      local cell_selected = entry.region_id == selected_region_id
      local note_fx = get_seq_note_anim(entry.region_id, slot.id, entry.key, now_t)
      -- Delete ghosts are drawn from the anim snapshot after the cell loop.
      -- Skip the live copy so the click frame does not draw both.
      if not (note_fx and note_fx.kind == "delete") then
      local fx_t = note_fx and note_fx.t or 1.0
      local prob_region = get_seq_region_by_id(entry.region_id)
      local vary_amt = seq_random_vary_amount(note, prob_region, slot.id, entry.key, 1)
      local resolved_path, resolved_sample = seq_resolve_note_sample(note, slot, vary_amt, prob_region, slot.id, entry.key)
      local origin_path = seq_note_vary_origin_path(note, slot, prob_region)
      local origin_sample = find_sample_by_path(origin_path)
      local base = get_sample_dot_color(origin_sample or resolved_sample or find_sample_by_path(resolved_path or origin_path))
      local vary_r, vary_g, vary_b = nil, nil, nil
      if resolved_path and origin_path and resolved_path ~= origin_path then
        vary_r, vary_g, vary_b = seq_note_vary_rgb(note, resolved_path)
      end
      if prob_region then
      local pattern = get_seq_pattern(prob_region.pattern_id, false)
      local track_settings = get_seq_track_settings(pattern, slot.id, false)
      local skipped = not seq_note_passes_probability(
        prob_region,
        slot.id,
        entry.key,
        track_settings and track_settings.probability,
        track_settings and (track_settings.probability_seed or track_settings.seed)
      )
      local note_len = seq_note_draw_length_qn(
        prob_region, pattern, slot, slot.id, entry.key, note, resolved_sample, step_qn
      )
      local draw_x0 = qn_to_x(note_qn + note_off) + 2
      local draw_x1 = math.max(draw_x0 + 6.0, qn_to_x(note_qn + note_off + note_len) - 2)
      local row_pad = 4.0
      local block_y0 = row_y0 + row_pad
      local block_y1 = row_y1 - row_pad
      local note_alpha = cell_selected and 235 or 70
      local border_alpha = cell_selected and 205 or 52
      if note_fx and (note_fx.kind == "add" or note_fx.kind == "delete") then
        local scale_x, scale_y = seq_note_anim_pop_scale(note_fx.kind, fx_t)
        draw_x0, block_y0, draw_x1, block_y1 = scale_rect_about_center(draw_x0, block_y0, draw_x1, block_y1, scale_x, scale_y, 0.0)
        note_alpha, border_alpha = seq_note_anim_pop_alphas(note_fx.kind, fx_t, cell_selected)
      elseif note_fx and note_fx.kind == "sync" then
        local boost = math.floor(55 * (1.0 - fx_t))
        note_alpha = math.min(255, note_alpha + boost)
        border_alpha = math.min(255, border_alpha + boost)
      end
      if skipped then
        note_alpha = math.max(28, math.floor(note_alpha * 0.32))
        border_alpha = math.max(40, math.floor(border_alpha * 0.42))
      end
      local block_h = block_y1 - block_y0
      local br, bg, bb = extract_rgb_rrgbbaa(base)
      local stutter_count = seq_stutter_count(note)
      local is_stutter = seq_note_has_stutter_span(note, step_qn)
      local decay_mode = seq_is_decay_def(edit_def)
      local head_x1 = seq_note_head_end_x(qn_to_x, note_qn, note, step_qn)
      local sustain_split_x = nil
      if not is_stutter and not decay_mode and head_x1 and draw_x1 > head_x1 + 1.0 then
        sustain_split_x = math.max(draw_x0 + 6.0, head_x1)
      end
      local trigger_x1 = sustain_split_x or draw_x1
      if is_stutter then
        draw_seq_stutter_note_hits(
          dl, qn_to_x, note, note_qn, step_qn,
          draw_x0, draw_x1, block_y0, block_y1,
          br, bg, bb, note_alpha, border_alpha, vary_r, vary_g, vary_b
        )
      else
        draw_seq_note_body(dl, draw_x0, draw_x1, block_y0, block_y1, br, bg, bb, note_alpha, border_alpha, sustain_split_x, vary_r, vary_g, vary_b)
      end

      local gauges_fit = (trigger_x1 - draw_x0) >= 14.0
      if skipped then
        draw_seq_note_probability_skip(
          dl,
          math.max(draw_x0, cx0 + 1),
          block_y0,
          math.min(trigger_x1, cx1 - 1),
          block_y1,
          cell_selected and 210 or 95
        )
      elseif seq_is_span_overlay_def(edit_def) then
        -- Lock / vary-filter spans are drawn once per contiguous range on the lane.
      elseif seq_is_decay_def(edit_def) then
        local overlay_accent = (edit_style and edit_style.accent) or 0xFFD166FF
        draw_seq_decay_handles(
          dl, note, slot, prob_region, pattern, entry.key, note_qn, step_qn, qn_to_x,
          draw_x0, draw_x1, block_y0, block_y1, mx, my, overlay_accent, cell_selected
        )
      elseif edit_def then
        local overlay_accent = (edit_style and edit_style.accent) or 0xFFD166FF
        if not seq_draw_stutter_param_slices(
          dl, note, note_qn, edit_def, step_qn, qn_to_x, block_y0, block_y1, overlay_accent, cell_selected, hover_qn
        ) then
          draw_seq_note_param_mode_overlay(
            dl, ctx, edit_def, note[edit_def.key], draw_x0, trigger_x1, row_y0, row_y1, step_qn,
            overlay_accent, cell_selected
          )
        end
      elseif not is_stutter then
        local vol = math.max(0.0, math.min(2.0, note.volume or 1.0))
        local vol_t = vol / 2.0
        local gx0 = draw_x0 + 2
        local gx1 = gx0 + 3
        r.ImGui_DrawList_AddRectFilled(dl, gx0, block_y0 + 2, gx1, block_y1 - 2, 0x00000055, 1.0)
        local vol_top = block_y1 - 2 - vol_t * math.max(1.0, (block_h - 4))
        r.ImGui_DrawList_AddRectFilled(dl, gx0, vol_top, gx1, block_y1 - 2, 0xFFFFFFFF, 1.0)
        if gauges_fit then
          local pitch = math.max(-24.0, math.min(24.0, note.pitch or 0.0))
          local pitch_t = (pitch + 24.0) / 48.0
          local px1 = trigger_x1 - 2
          local px0 = px1 - 3
          local mid_y = (block_y0 + block_y1) * 0.5
          r.ImGui_DrawList_AddRectFilled(dl, px0, block_y0 + 2, px1, block_y1 - 2, 0x00000055, 1.0)
          r.ImGui_DrawList_AddLine(dl, px0, mid_y, px1, mid_y, 0xFFFFFF66, 1.0)
          local pitch_y = (block_y1 - 2) - pitch_t * math.max(1.0, (block_h - 4))
          local pitch_color = pitch >= 0.0 and 0xFFB84DFF or 0x58B7FFFF
          if pitch >= 0 then
            r.ImGui_DrawList_AddRectFilled(dl, px0, pitch_y, px1, mid_y, pitch_color, 1.0)
          else
            r.ImGui_DrawList_AddRectFilled(dl, px0, mid_y, px1, pitch_y, pitch_color, 1.0)
          end
        end
        local pan = math.max(-1.0, math.min(1.0, note.pan or 0.0))
        local pan_track_x0 = draw_x0 + 6
        local pan_track_x1 = trigger_x1 - (gauges_fit and 6 or 2)
        if pan_track_x1 > pan_track_x0 + 2 then
          local pan_y = block_y0 + 3
          r.ImGui_DrawList_AddLine(dl, pan_track_x0, pan_y, pan_track_x1, pan_y, 0x00000077, 1.0)
          local pan_cx = (pan_track_x0 + pan_track_x1) * 0.5
          r.ImGui_DrawList_AddLine(dl, pan_cx, pan_y - 2, pan_cx, pan_y + 2, 0xFFFFFF66, 1.0)
          local pan_x = pan_track_x0 + ((pan + 1.0) * 0.5) * (pan_track_x1 - pan_track_x0)
          r.ImGui_DrawList_AddRectFilled(dl, pan_x - 1.5, pan_y - 2.5, pan_x + 1.5, pan_y + 2.5, 0xFFFFFFFF, 1.0)
        end
      end
      if vary_r and not is_stutter then
        draw_seq_note_vary_marks(dl, draw_x0, trigger_x1, block_y0, block_y1, vary_r, vary_g, vary_b, note_alpha)
      end
      if is_stutter then
        local bx0, by0, bx1, by1 = draw_seq_stutter_count_badge(
          dl, ctx, draw_x0, block_y0, draw_x1, block_y1, stutter_count, 0xC9A8FFFF
        )
        if not edit_def then
          seq_register_stutter_badge_hit(bx0, by0, bx1, by1, slot.id, entry.region_id, entry.key)
        end
      end
      if note_fx and note_fx.kind == "sync" then
        draw_seq_note_sync_flash(dl, draw_x0, block_y0, draw_x1, block_y1, fx_t)
      end
      if hover_pick and hover_pick.key == entry.key and hover_pick.region_id == entry.region_id
         and not seq_note_is_locked(note) then
        -- Decay can hover the full body. Otherwise only the originating cell
        -- counts as the note; spilled min-grid / sustain tails look empty.
        -- Locked notes use the lock-span hover instead of this cell outline.
        local hover_x1 = seq_is_decay_def(edit_def) and draw_x1 or math.min(trigger_x1, cx1)
        draw_seq_note_hover(dl, mx, my, draw_x0, block_y0, draw_x1, block_y1, hover_x1)
      end
      end
      end
      end
    end
  end
end

function make_default_seq_note(slot, step_key, qn_offset)
  local sample = slot and slot.sample_path and find_sample_by_path(slot.sample_path) or nil
  if not sample then
    return nil
  end
  return {
    enabled = true,
    step = tonumber(step_key) or 0,
    qn_offset = qn_offset or 0.0,
    sample_path = sample.path,
    sample_name = sample.name or basename(sample.path),
    volume = 1.0,
    pan = 0.0,
    pitch = 0.0,
    length_qn = state.seq_grid_qn or 0.25,
    offset_qn = 0.0,
    stretch = 1.0,
    start = 0.0,
    sample_vary = 0.0,
    stutter = 1,
  }
end

function seq_apply_frozen_sample(target, path, sample, origin_path)
  if type(target) ~= "table" or not path or path == "" then
    return
  end
  target.frozen_sample_path = path
  target.frozen_sample_name = (sample and (sample.name or sample.path)) or basename(path)
  seq_stamp_vary_visual(target, path, origin_path)
end

-- Clone a note and freeze the sample it is currently sounding, including
-- region-random variation. The copy then keeps that file even at a new step.
function seq_clone_note_keeping_sample(note, region, track_id, step_key, slot)
  local copy = clone_table_deep(note)
  if type(copy) ~= "table" then
    return copy
  end
  local function freeze_into(target, hit_idx)
    local vary = seq_random_vary_amount(note, region, track_id, step_key, hit_idx)
    local hit_note = seq_note_for_stutter_hit(note, hit_idx)
    local path, sample = seq_resolve_note_sample(hit_note, slot, vary, region, track_id, step_key)
    if path then
      seq_apply_frozen_sample(target, path, sample, seq_note_vary_origin_path(note, slot, region))
    end
    if vary and vary > 0.000001 and (tonumber(target.sample_vary) or 0) <= 0.000001 then
      target.sample_vary = vary
    end
  end
  freeze_into(copy, 1)
  local count = seq_stutter_count(copy)
  if count > 1 then
    copy.stutter_hits = copy.stutter_hits or {}
    for i = 1, count do
      local hit = seq_stutter_hit_table(copy, i)
      if type(hit) ~= "table" then
        hit = {}
        copy.stutter_hits[i] = hit
      end
      freeze_into(hit, i)
    end
  end
  return copy
end

function seq_template_step_to_grid_step(template_step, steps_per_bar)
  local raw = (template_step or 0) * steps_per_bar / 16.0
  local rounded = math.floor(raw + 0.5)
  if math.abs(raw - rounded) > 0.000001 then
    return nil
  end
  return rounded
end

function seq_pattern_rand(seed)
  return math.abs(math.sin(seed or 0) * 10000.0) % 1.0
end

function seq_pattern_clamp(v, min_v, max_v)
  if v < min_v then return min_v end
  if v > max_v then return max_v end
  return v
end

function seq_role_anchor_hit(role, template_step)
  local fam = seq_role_family(role)
  if fam == "kick" then
    return template_step == 0 or template_step == 8
  end
  if fam == "backbeat" then
    return template_step == 4 or template_step == 12
  end
  return false
end

-- Each dice roll produces an independent random intensity (0..strength*10) for
-- every randomization type. So dice 1 yields 0..10, dice 2 yields 0..20, etc.
-- The rolled values are derived from the seed so a stored variation reproduces
-- exactly. Returns displacement %, density %, and stutter %.
function seq_dice_intensities(strength, seed)
  local s = math.max(0, math.min(6, strength or 0))
  if s <= 0 then
    return 0.0, 0.0, 0.0
  end
  local maxv = s * 10.0
  local disp = seq_pattern_rand((seed or 0) + 1234.5) * maxv
  local dens = seq_pattern_rand((seed or 0) + 6789.0) * maxv
  local stut = seq_pattern_rand((seed or 0) + 2468.0) * maxv
  return disp, dens, stut
end

-- Decides how far (in grid steps) a template hit is nudged from its position.
-- disp_pct is the rolled displacement intensity (0..60). Returns a signed step
-- delta, or 0 to stay put.
function seq_random_step_displacement(disp_pct, is_anchor, fam, rnd_gate, rnd_dir)
  if not disp_pct or disp_pct <= 0 then
    return 0
  end
  local p = disp_pct / 100.0
  if is_anchor then
    p = p * 0.55
  end
  if fam == "kick" then
    p = p * 0.8
  end
  if rnd_gate >= p then
    return 0
  end
  local span = rnd_gate / math.max(p, 1e-6)
  local mag = 1
  if disp_pct >= 25 and span > 0.5 then
    mag = 2
  end
  if disp_pct >= 45 and span > 0.8 then
    mag = 3
  end
  local dir = (rnd_dir < 0.5) and -1 or 1
  return dir * mag
end

-- Stutter/roll, intentionally rare even at high dice.
function apply_seq_random_note_shape(note, stut_pct, rnd_b)
  if not note or not stut_pct or stut_pct <= 0 then
    return
  end
  local stut_prob = (stut_pct / 100.0) * 0.10
  if rnd_b < stut_prob then
    note.stutter = math.min(6, 2 + math.floor(seq_pattern_rand(rnd_b * 10000.0 + stut_pct * 13.0) * 3))
  end
end

function seq_has_generatable_track(style_key)
  local template = SEQ_GEN_TEMPLATES[normalize_seq_gen_style(style_key)]
  if not template then
    return false
  end
  for _, slot in ipairs(state.seq_tracks) do
    if slot.sample_path then
      local role = infer_seq_track_role(slot)
      if template[role] then
        return true
      end
    end
  end
  return false
end

function seq_collect_locked_notes(pattern, grid_qn)
  local locked = {}
  if not pattern or type(pattern.notes) ~= "table" then
    return locked
  end
  grid_qn = grid_qn or state.seq_grid_qn or 0.25
  for track_id, notes in pairs(pattern.notes) do
    if type(notes) == "table" then
      for step_key, note in pairs(notes) do
        if seq_note_is_locked(note) then
          local qn = seq_note_qn_offset(note, step_key, grid_qn) or 0.0
          locked[#locked + 1] = {
            track_id = track_id,
            step_key = tostring(step_key),
            note = clone_table_deep(note),
            step_idx = math.floor((qn / math.max(1e-9, grid_qn)) + 1e-9),
          }
        end
      end
    end
  end
  return locked
end

function seq_restore_locked_notes(region, locked)
  local n = 0
  for i = 1, #(locked or {}) do
    local item = locked[i]
    set_seq_note(region, item.track_id, item.step_key, item.note)
    n = n + 1
  end
  return n
end

function seq_locked_step_seen(locked, track_id)
  local seen = {}
  for i = 1, #(locked or {}) do
    local item = locked[i]
    if tostring(item.track_id) == tostring(track_id) and item.step_idx then
      seen[item.step_idx] = true
    end
  end
  return seen
end

function generate_seq_pattern(region, style_key, opts)
  if not region then
    return 0
  end
  opts = opts or {}

  style_key = normalize_seq_gen_style(style_key)
  local template = SEQ_GEN_TEMPLATES[style_key] or SEQ_GEN_TEMPLATES.basic
  local pattern = get_seq_pattern(region.pattern_id, true)
  if not pattern then
    return 0
  end

  local grid_qn = (type(state.seq_grid_qn) == "number" and state.seq_grid_qn > 0) and state.seq_grid_qn or 0.25
  local region_len_qn = get_seq_region_length_qn(region)
  local steps_per_bar = math.max(1, math.floor((4.0 / grid_qn) + 0.5))
  local bar_count = math.max(1, math.floor((region_len_qn / 4.0) + 0.5))
  local max_steps = math.max(1, math.floor((region_len_qn / grid_qn) + 0.5))
  local strength = type(opts.random_strength) == "number" and math.max(0, math.min(6, math.floor(opts.random_strength + 0.5))) or 0
  local random_seed = opts.random_seed or seq_new_seed()

  -- One random intensity per randomization type for this dice roll.
  local disp_pct, dens_pct, stut_pct = seq_dice_intensities(strength, random_seed)
  -- Density randomization: drop some existing hits and/or add new ones.
  local drop_prob = (dens_pct / 100.0) * 0.5
  local add_prob = (dens_pct / 100.0) * 0.4

  local locked_notes = seq_collect_locked_notes(pattern, grid_qn)
  pattern.notes = {}
  state.selected_seq_note = nil
  local hit_count = seq_restore_locked_notes(region, locked_notes)

  local skipped_unassigned = false
  for _, slot in ipairs(state.seq_tracks) do
    if slot.sample_path then
      local role = infer_seq_track_role(slot)
      local role_steps = template[role]
      if role_steps then
        local seen = seq_merge_locked_cell_seen(seq_locked_step_seen(locked_notes, slot.id), pattern, slot.id)
        local fam = seq_role_family(role)
        local template_step_lookup = {}
        for _, template_step in ipairs(role_steps) do
          template_step_lookup[template_step] = true
        end

        local function add_pattern_note(step_idx)
          if step_idx >= 0 and step_idx < max_steps and not seen[step_idx] then
            local note = make_default_seq_note(slot, step_idx, step_idx * grid_qn)
            if note then
              local pos16 = steps_per_bar > 0
                and math.floor(((step_idx % steps_per_bar) * 16.0 / steps_per_bar) + 0.5)
                or step_idx
              note.offset_qn = seq_pattern_base_offset(role, pos16, style_key, grid_qn)
              local rnd_stut = seq_pattern_rand(random_seed + step_idx * 733 + (slot.id or 0) * 41)
              apply_seq_random_note_shape(note, stut_pct, rnd_stut)
              if (step_idx % steps_per_bar) == 0 and note.offset_qn < 0.0 then
                note.offset_qn = 0.0
              end
              set_seq_note(region, slot.id, step_idx, note)
              seen[step_idx] = true
              hit_count = hit_count + 1
              return true
            end
          end
          return false
        end

        for bar = 0, bar_count - 1 do
          local bar_lo = bar * steps_per_bar
          local bar_hi = bar_lo + steps_per_bar - 1

          -- Place template hits, applying density-drop and displacement.
          for _, template_step in ipairs(role_steps) do
            local grid_step = seq_template_step_to_grid_step(template_step, steps_per_bar)
            if grid_step then
              local base_idx = bar_lo + grid_step
              local is_anchor = seq_role_anchor_hit(role, template_step)

              local dropped = false
              if drop_prob > 0 and not is_anchor then
                local rnd_drop = seq_pattern_rand(random_seed + base_idx * 211 + (slot.id or 0) * 13)
                if rnd_drop < drop_prob then
                  dropped = true
                end
              end

              if not dropped then
                local target_idx = base_idx
                if disp_pct > 0 then
                  local rnd_gate = seq_pattern_rand(random_seed + base_idx * 331 + (slot.id or 0) * 7)
                  local rnd_dir = seq_pattern_rand(random_seed + base_idx * 521 + (slot.id or 0) * 29)
                  local delta = seq_random_step_displacement(disp_pct, is_anchor, fam, rnd_gate, rnd_dir)
                  if delta ~= 0 then
                    local dir = (delta > 0) and 1 or -1
                    local mag = math.abs(delta)
                    local candidates = {}
                    candidates[#candidates + 1] = dir * mag
                    candidates[#candidates + 1] = -dir * mag
                    for m = mag - 1, 1, -1 do
                      candidates[#candidates + 1] = dir * m
                      candidates[#candidates + 1] = -dir * m
                    end
                    for _, d in ipairs(candidates) do
                      local cand = base_idx + d
                      if cand >= bar_lo and cand <= bar_hi and cand >= 0 and cand < max_steps and not seen[cand] then
                        target_idx = cand
                        break
                      end
                    end
                  end
                end
                if not add_pattern_note(target_idx) and target_idx ~= base_idx then
                  add_pattern_note(base_idx)
                end
              end
            end
          end

          -- Density-add: sprinkle new hits onto empty 16th steps in this bar.
          if add_prob > 0 then
            for template_step = 0, 15 do
              if not template_step_lookup[template_step] then
                local grid_step = seq_template_step_to_grid_step(template_step, steps_per_bar)
                if grid_step then
                  local idx = bar_lo + grid_step
                  if not seen[idx] then
                    local rnd_add = seq_pattern_rand(random_seed + idx * 617 + (slot.id or 0) * 23 + template_step * 5)
                    if rnd_add < add_prob then
                      add_pattern_note(idx)
                    end
                  end
                end
              end
            end
          end
        end
      end
    else
      skipped_unassigned = true
    end
  end

  save_config()
  sync_seq_pattern_regions(region.pattern_id)
  if skipped_unassigned then
    log("Skipped unassigned sequencer tracks while generating pattern")
  end
  if strength > 0 then
    log(string.format("Randomized %s pattern at dice %d (disp %.0f / dens %.0f / stut %.0f, %d hits)",
      get_seq_gen_style_label(style_key), strength, disp_pct, dens_pct, stut_pct, hit_count))
  else
    log("Generated " .. get_seq_gen_style_label(style_key) .. " pattern (" .. tostring(hit_count) .. " hits)")
  end
  return hit_count
end

function seq_template_roles(style_key)
  local template = SEQ_GEN_TEMPLATES[normalize_seq_gen_style(style_key)] or {}
  local roles = {}
  for _, role in ipairs(SEQ_ROLE_ORDER) do
    if template[role] then
      roles[#roles + 1] = role
    end
  end
  return roles
end

function find_sample_for_role(role)
  local candidates = SEQ_ROLE_TAG_CANDIDATES[role] or { role }
  for _, tag in ipairs(candidates) do
    local sample = find_sample_for_tag(tag)
    if sample then
      return sample, tag
    end
  end
  return nil
end

-- A preset can generate if any of its roles is already on an assigned track,
-- or a matching sample exists in the library to auto-create the track from.
function seq_preset_can_generate(style_key)
  local roles = seq_template_roles(style_key)
  if #roles == 0 then
    return false
  end
  local assigned_roles = {}
  for _, slot in ipairs(state.seq_tracks) do
    if slot.sample_path then
      assigned_roles[infer_seq_track_role(slot)] = true
    end
  end
  for _, role in ipairs(roles) do
    if assigned_roles[role] then
      return true
    end
    if find_sample_for_role(role) then
      return true
    end
  end
  return false
end

-- Ensure a sequencer track exists for each role the preset needs. Missing roles
-- get a new track (named for the role, stamped with the role's primary tag) and,
-- when available, an auto-assigned sample from the library.
function ensure_seq_tracks_for_roles(roles)
  local present = {}
  for _, slot in ipairs(state.seq_tracks) do
    present[infer_seq_track_role(slot)] = true
  end
  local created = 0
  for _, role in ipairs(roles) do
    if not present[role] then
      local label = SEQ_ROLE_LABELS[role] or role
      local slot = create_seq_track_with_name(label)
      if slot then
        local candidates = SEQ_ROLE_TAG_CANDIDATES[role] or { role }
        slot.sample_tag = candidates[1] or role
        local sample = find_sample_for_role(role)
        if sample then
          assign_sample_to_seq_track(slot, sample, false)
        end
        present[role] = true
        created = created + 1
      end
    end
  end
  return created
end

-- Infer library genre tags from free text (pattern style names, GMD labels, etc.).
function seq_library_genres_from_text(text)
  local haystack = tostring(text or ""):lower()
  if haystack == "" then
    return {}
  end
  local found, out = {}, {}
  for _, entry in ipairs(GENRE_KEYWORDS) do
    local tag = entry.tag
    if not found[tag] then
      for _, key in ipairs(entry.keys) do
        if genre_key_matches(haystack, key) then
          found[tag] = true
          out[#out + 1] = tag
          break
        end
      end
    end
  end
  return out
end

function seq_style_to_library_genres(style_key)
  style_key = tostring(style_key or "")
  local mapped = SEQ_STYLE_LIBRARY_GENRES[style_key]
  if mapped and #mapped > 0 then
    local out = {}
    for _, tag in ipairs(mapped) do
      out[#out + 1] = tag
    end
    return out
  end
  return seq_library_genres_from_text(style_key)
end

function stamp_seq_region_kit_genres(region, style_key, style_source, genres)
  if not region then
    return
  end
  region.style_key = style_key and tostring(style_key) or region.style_key
  region.style_source = style_source or region.style_source
  if type(genres) == "table" then
    region.kit_genres = genres
  elseif region.style_key then
    if region.style_source == "gmd" then
      region.kit_genres = seq_library_genres_from_text(region.style_key)
    else
      region.kit_genres = seq_style_to_library_genres(region.style_key)
    end
  end
end

function get_seq_region_kit_genres(region)
  if not region then
    return {}
  end
  if type(region.kit_genres) == "table" and #region.kit_genres > 0 then
    return region.kit_genres
  end
  if region.style_key and region.style_key ~= "" then
    if region.style_source == "gmd" or not seq_gen_style_exists(region.style_key) then
      return seq_library_genres_from_text(region.style_key)
    end
    return seq_style_to_library_genres(region.style_key)
  end
  return {}
end

-- Genres present in the scanned library (for Randomize Kit popup).
function collect_library_genre_tags()
  if (not state.tag_list or #state.tag_list == 0) and #state.samples > 0 then
    rebuild_tag_index()
  end
  local out = {}
  for _, entry in ipairs(state.tag_list or {}) do
    local tag = tostring(entry.tag or "")
    if tag ~= "" and GENRE_TAG_SET[tag:lower()] then
      out[#out + 1] = { tag = tag, count = entry.count or 0 }
    end
  end
  return out
end

-- Genres corresponding to patterns already used in project regions (priority list).
function collect_project_kit_genre_priority()
  local seen, ordered = {}, {}
  local function push(tag)
    local key = tostring(tag or ""):lower()
    if key == "" or seen[key] or not GENRE_TAG_SET[key] then
      return
    end
    -- Prefer the canonical casing from GENRE_KEYWORDS when available.
    local canonical = key
    for _, entry in ipairs(GENRE_KEYWORDS) do
      if entry.tag:lower() == key then
        canonical = entry.tag
        break
      end
    end
    seen[key] = true
    ordered[#ordered + 1] = canonical
  end

  for _, region in ipairs(state.seq_regions or {}) do
    for _, tag in ipairs(get_seq_region_kit_genres(region)) do
      push(tag)
    end
  end

  -- Soft fallbacks for sessions that haven't stamped region genres yet.
  if #ordered == 0 then
    for _, tag in ipairs(seq_style_to_library_genres(state.seq_gen_style)) do
      push(tag)
    end
    if state.seq_gmd_selected_style then
      for _, tag in ipairs(seq_library_genres_from_text(state.seq_gmd_selected_style)) do
        push(tag)
      end
    end
  end

  return ordered
end

function sample_matches_kit_keyword(sample, keyword)
  local needle = seq_trim_text(keyword):lower()
  if needle == "" or not sample then
    return needle == ""
  end
  if sample_has_tag(sample, needle) then
    return true
  end
  if type(sample.tags) == "table" then
    for _, tag in ipairs(sample.tags) do
      if tostring(tag):lower():find(needle, 1, true) then
        return true
      end
    end
  end
  local hay = (
    tostring(sample.path or "") .. " "
    .. tostring(sample.folder or "") .. " "
    .. tostring(sample.name or "")
  ):lower()
  return hay:find(needle, 1, true) ~= nil
end

function sample_matches_seq_role_tags(sample, role)
  if not sample or not role or role == "other" then
    return false
  end
  local candidates = SEQ_ROLE_TAG_CANDIDATES[role] or { role }
  for _, tag in ipairs(candidates) do
    if sample_has_tag(sample, tag) then
      return true, tag
    end
  end
  return false
end

-- Melodic sequencer roles may use loops; drum / other non-melodic roles may not.
function seq_kit_role_is_melodic(role)
  if not role or role == "" or role == "other" then
    return false
  end
  return categorize_tags(role) == "melodic"
end

function sample_is_loop(sample)
  if not sample then
    return false
  end
  if sample_has_tag(sample, "loop") then
    return true
  end
  return detect_loop_or_oneshot(sample.path or "", sample.folder or "", sample.playback_type) == "loop"
end

-- Collect role-matching samples, optionally constrained by genre/custom keywords (OR).
-- Drum / non-melodic roles use one-shots only; melodic roles may include loops.
-- exact_tag: require an exact genre/tag match (genre chips).
function collect_samples_for_role_with_keywords(role, keywords, opts)
  opts = opts or {}
  local exact_tag = opts.exact_tag == true
  local oneshot_only = not seq_kit_role_is_melodic(role)
  local out = {}
  local has_keywords = type(keywords) == "table" and #keywords > 0

  for _, sample in ipairs(state.samples or {}) do
    if not sample_scan_folder_unavailable(sample)
        and (not oneshot_only or not sample_is_loop(sample))
        and sample_matches_seq_role_tags(sample, role) then
      local keyword_ok = not has_keywords
      if has_keywords then
        for _, kw in ipairs(keywords) do
          if exact_tag then
            if sample_has_tag(sample, kw) then
              keyword_ok = true
              break
            end
          elseif sample_matches_kit_keyword(sample, kw) then
            keyword_ok = true
            break
          end
        end
      end
      if keyword_ok then
        out[#out + 1] = sample
      end
    end
  end

  return out
end

SEQ_KIT_HISTORY_MAX = 24

function seq_kit_history_label(keywords)
  if type(keywords) == "table" and #keywords > 0 then
    return table.concat(keywords, ", ")
  end
  return "Any genre"
end

function collect_seq_kit_elements()
  local by_role = {}
  for _, slot in ipairs(state.seq_tracks or {}) do
    local role = infer_seq_track_role(slot)
    if role ~= "other" and slot.sample_path then
      by_role[role] = {
        role = role,
        track_id = slot.id,
        sample_path = slot.sample_path,
        sample_name = slot.sample_name or basename(slot.sample_path),
        sample_tag = slot.sample_tag,
      }
    end
  end
  local elements = {}
  for _, role in ipairs(SEQ_ROLE_ORDER) do
    if by_role[role] then
      elements[#elements + 1] = by_role[role]
      by_role[role] = nil
    end
  end
  for _, elem in pairs(by_role) do
    elements[#elements + 1] = elem
  end
  return elements
end

function seq_kit_signature(elements)
  local parts = {}
  for _, elem in ipairs(elements or {}) do
    parts[#parts + 1] = tostring(elem.role or "") .. "=" .. tostring(elem.sample_path or "")
  end
  return table.concat(parts, "|")
end

function seq_kit_history_has_signature(sig)
  if not sig or sig == "" then
    return false
  end
  for _, entry in ipairs(state.seq_kit_history or {}) do
    if seq_kit_signature(entry.elements) == sig then
      return true
    end
  end
  return false
end

function snapshot_seq_kit_history(keywords, opts)
  opts = opts or {}
  local elements = opts.elements or collect_seq_kit_elements()
  if #elements == 0 then
    return nil
  end
  local sig = seq_kit_signature(elements)
  if opts.skip_duplicate ~= false and seq_kit_history_has_signature(sig) then
    return nil
  end

  state.seq_kit_history = state.seq_kit_history or {}
  local id = state.seq_kit_history_next_id or 1
  state.seq_kit_history_next_id = id + 1
  local kw_copy = {}
  if type(keywords) == "table" then
    for _, kw in ipairs(keywords) do
      kw_copy[#kw_copy + 1] = kw
    end
  end
  local entry = {
    id = id,
    label = opts.label or seq_kit_history_label(kw_copy),
    keywords = kw_copy,
    elements = elements,
    is_original = opts.is_original == true,
    created_at = (r.time_precise and r.time_precise()) or os.clock(),
  }
  if opts.append then
    state.seq_kit_history[#state.seq_kit_history + 1] = entry
  else
    table.insert(state.seq_kit_history, 1, entry)
  end
  while #state.seq_kit_history > SEQ_KIT_HISTORY_MAX do
    local removed = false
    for i = #state.seq_kit_history, 1, -1 do
      if not state.seq_kit_history[i].is_original then
        table.remove(state.seq_kit_history, i)
        removed = true
        break
      end
    end
    if not removed then
      break
    end
  end
  return entry
end

-- Keep the pre-randomize / pre-replace kit so it remains restorable.
function preserve_current_seq_kit_in_history()
  local elements = collect_seq_kit_elements()
  if #elements == 0 then
    return nil
  end
  local has_original = false
  for _, entry in ipairs(state.seq_kit_history or {}) do
    if entry.is_original then
      has_original = true
      break
    end
  end
  if not has_original then
    return snapshot_seq_kit_history(nil, {
      elements = elements,
      label = "Original",
      is_original = true,
      append = true,
    })
  end
  return snapshot_seq_kit_history(nil, {
    elements = elements,
    label = "Previous",
  })
end

function find_seq_track_for_kit_element(element)
  if not element then
    return nil
  end
  local by_id = element.track_id and find_seq_track_by_id(element.track_id) or nil
  if by_id and (not element.role or infer_seq_track_role(by_id) == element.role) then
    return by_id
  end
  if element.role then
    for _, slot in ipairs(state.seq_tracks or {}) do
      if infer_seq_track_role(slot) == element.role then
        return slot
      end
    end
  end
  return by_id
end

function preview_seq_kit_history_element(element)
  if not element or not element.sample_path then
    return false
  end
  local sample = find_sample_by_path(element.sample_path)
  if not sample then
    log("Sample not found in library: " .. tostring(element.sample_name or element.sample_path))
    return false
  end
  preview_sample(sample)
  local slot = find_seq_track_for_kit_element(element)
  if slot then
    state.seq_track_play_anims = state.seq_track_play_anims or {}
    state.seq_track_play_anims[tostring(slot.id)] = {
      start_time = r.time_precise(),
      duration = 0.35,
    }
  end
  return true
end

function apply_seq_kit_history_element(element, opts)
  opts = opts or {}
  if not element or not element.sample_path then
    return false
  end
  local sample = find_sample_by_path(element.sample_path)
  if not sample then
    log("Sample not found in library: " .. tostring(element.sample_name or element.sample_path))
    return false
  end
  local slot = find_seq_track_for_kit_element(element)
  if not slot then
    log("No sequencer track for " .. tostring(SEQ_ROLE_LABELS[element.role] or element.role or "sample"))
    return false
  end
  local own_undo = opts.undo ~= false
  local label = own_undo and begin_seq_undo("Apply kit sample") or nil
  local ok = seq_kit_assign_sample(slot, sample)
  if ok then
    if element.sample_tag and seq_trim_text(element.sample_tag) ~= "" then
      slot.sample_tag = element.sample_tag
    elseif element.role and SEQ_ROLE_TAG_CANDIDATES[element.role] then
      slot.sample_tag = SEQ_ROLE_TAG_CANDIDATES[element.role][1]
    end
    if opts.preview ~= false then
      preview_sample(sample)
      state.seq_track_play_anims = state.seq_track_play_anims or {}
      state.seq_track_play_anims[tostring(slot.id)] = {
        start_time = r.time_precise(),
        duration = 0.35,
      }
    end
    if opts.silent ~= true then
      log(string.format(
        "Applied %s: %s",
        tostring(SEQ_ROLE_LABELS[element.role] or element.role or "sample"),
        tostring(sample.name or basename(sample.path))
      ))
    end
  end
  if own_undo then
    save_config()
    end_seq_undo(label)
  end
  return ok
end

function seq_kit_heard_sample_path(slot)
  if not slot then
    return nil
  end
  local region = seq_sample_assign_region and seq_sample_assign_region() or nil
  if not region and get_seq_region_by_id then
    region = get_seq_region_by_id(state.selected_seq_region_id)
  end
  local path = seq_effective_slot_sample_path and select(1, seq_effective_slot_sample_path(slot, region)) or nil
  if path and path ~= "" then
    return path
  end
  return slot.sample_path
end

function seq_kit_paths_same(a, b)
  if type(a) ~= "string" or type(b) ~= "string" or a == "" or b == "" then
    return false
  end
  if seq_paths_same then
    return seq_paths_same(a, b)
  end
  return a == b
end

function seq_kit_clear_slot_region_samples(slot)
  if not slot then
    return false
  end
  local cleared = false
  for _, region in ipairs(state.seq_regions or {}) do
    if seq_region_own_track_sample and seq_region_own_track_sample(region, slot.id) then
      seq_set_region_own_track_sample(region, slot, nil)
      cleared = true
    end
  end
  return cleared
end

function seq_kit_unfreeze_slot_notes(slot)
  if not slot or slot.id == nil then
    return false
  end
  local track_key = tostring(slot.id)
  local cleared = false
  for _, pattern in pairs(state.seq_patterns or {}) do
    local track_notes = type(pattern) == "table" and type(pattern.notes) == "table" and pattern.notes[track_key]
    if type(track_notes) == "table" then
      for _, note in pairs(track_notes) do
        if seq_note_has_frozen_sample and seq_note_has_frozen_sample(note) then
          seq_clear_frozen_sample(note)
          cleared = true
        end
      end
    end
  end
  return cleared
end

function seq_kit_assign_sample(slot, sample)
  if not slot or not sample or not sample.path then
    return false
  end
  local heard = seq_kit_heard_sample_path(slot)
  local had_override = seq_kit_clear_slot_region_samples(slot)
  local had_frozen = seq_kit_unfreeze_slot_notes(slot)
  local old_path = slot.sample_path
  local ok = assign_sample_to_seq_track(slot, sample, false)
  if not ok then
    return false
  end
  -- Slot path can stay the same while a region override or frozen hit was
  -- what you were actually hearing. Force a rebuild so the new kit plays.
  if (had_override or had_frozen or seq_kit_paths_same(old_path, sample.path))
      and update_seq_track_sample_assignments then
    update_seq_track_sample_assignments(slot, sample.path, slot.sample_name, false, {
      force_rebuild = true,
    })
  end
  if seq_kit_paths_same(heard, sample.path) and not had_override and not had_frozen then
    return false
  end
  return true
end

function apply_seq_kit_history_entry(entry)
  if not entry or type(entry.elements) ~= "table" or #entry.elements == 0 then
    return 0
  end
  preserve_current_seq_kit_in_history()
  local label = begin_seq_undo("Apply kit")
  local changed = 0
  local last_sample = nil
  for _, element in ipairs(entry.elements) do
    if apply_seq_kit_history_element(element, { undo = false, preview = false, silent = true }) then
      changed = changed + 1
      last_sample = find_sample_by_path(element.sample_path) or last_sample
    end
  end
  if last_sample then
    preview_sample(last_sample)
  end
  save_config()
  end_seq_undo(label)
  if changed > 0 then
    log(string.format("Applied kit \"%s\" (%d sound%s)", entry.label or "Kit", changed, changed == 1 and "" or "s"))
  else
    log("Could not apply kit \"" .. tostring(entry.label or "Kit") .. "\"")
  end
  return changed
end

function randomize_seq_kit(keywords, opts)
  opts = opts or {}
  if not state.seq_tracks or #state.seq_tracks == 0 then
    log("No sequencer tracks to randomize")
    return 0
  end

  preserve_current_seq_kit_in_history()

  local label = begin_seq_undo("Randomize kit")
  local seed = seq_new_seed()
  math.randomseed(seed)

  local changed = 0
  local stuck = 0
  for _, slot in ipairs(state.seq_tracks) do
    local role = infer_seq_track_role(slot)
    if role == "other" then
      local tag = seq_trim_text(slot.sample_tag):lower()
      local cat = tag ~= "" and categorize_tags(tag) or nil
      if cat == "drum" or cat == "melodic" then
        role = tag
      end
    end
    if role ~= "other" then
      local pool = collect_samples_for_role_with_keywords(role, keywords, opts)
      local heard = seq_kit_heard_sample_path(slot)
      local alt = {}
      for _, sample in ipairs(pool) do
        if sample.path and not seq_kit_paths_same(sample.path, heard) then
          alt[#alt + 1] = sample
        end
      end
      if #alt > 0 then
        local pick = alt[math.random(1, #alt)]
        if pick and seq_kit_assign_sample(slot, pick) then
          local candidates = SEQ_ROLE_TAG_CANDIDATES[role]
          if candidates and candidates[1] then
            slot.sample_tag = candidates[1]
          end
          changed = changed + 1
        end
      elseif #pool > 0 then
        stuck = stuck + 1
      end
    end
  end

  if changed > 0 then
    snapshot_seq_kit_history(keywords)
  end
  save_config()
  end_seq_undo(label)

  local constraint = ""
  if keywords and #keywords > 0 then
    constraint = " (" .. table.concat(keywords, ", ") .. ")"
  end
  if changed > 0 then
    local msg = string.format("Randomized kit: %d track(s)%s", changed, constraint)
    if stuck > 0 then
      msg = msg .. string.format(" (%d kept — no other matches)", stuck)
    end
    log(msg)
  else
    if stuck > 0 then
      log("No other matching samples to randomize kit" .. constraint)
    else
      log("No matching samples found to randomize kit" .. constraint)
    end
  end
  return changed
end

function open_seq_kit_random_popup()
  state.seq_kit_random_query = state.seq_kit_random_query or ""
  if (not state.tag_list or #state.tag_list == 0) and #state.samples > 0 then
    rebuild_tag_index()
  end
  if r.ImGui_SetNextWindowSize then
    local cond = r.ImGui_Cond_Appearing and r.ImGui_Cond_Appearing() or 0
    r.ImGui_SetNextWindowSize(ctx, 440, 620, cond)
  end
  r.ImGui_OpenPopup(ctx, "seq_kit_random_popup")
end

SEQ_PATTERN_POPUP_W = 340.0

function seq_truncate_text_to_width(text, max_w)
  if not text or text == "" then return "" end
  if max_w <= 0 then return "" end
  local tw = select(1, r.ImGui_CalcTextSize(ctx, text))
  if tw <= max_w then return text end
  local ell = "..."
  local len = #text
  while len > 0 do
    len = len - 1
    local candidate = text:sub(1, len) .. ell
    tw = select(1, r.ImGui_CalcTextSize(ctx, candidate))
    if tw <= max_w then return candidate end
  end
  return ell
end

-- Small pill label for inline badges (e.g. variation # tags).
function draw_ui_pill_label(dl, x, cy, text, opts)
  opts = opts or {}
  local pad_x = opts.pad_x or 6.0
  local pad_y = opts.pad_y or 2.0
  local rounding = opts.rounding or 5.0
  local bg = opts.bg or UI_THEME.accent_fill
  local border = opts.border or UI_THEME.accent
  local text_col = opts.text_col or UI_THEME.text
  local tw, th = r.ImGui_CalcTextSize(ctx, text)
  local w = tw + pad_x * 2.0
  local h = th + pad_y * 2.0
  local y = cy - h * 0.5
  r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, bg, rounding)
  r.ImGui_DrawList_AddRect(dl, x, y, x + w, y + h, border, rounding, 0, opts.border_w or 1.0)
  r.ImGui_DrawList_AddText(dl, x + pad_x, y + pad_y, text_col, text)
  return w, h
end

function open_seq_pattern_popup()
  state.seq_pattern_window_open = not state.seq_pattern_window_open
end

-- Position the preset popup flush against the left or right edge of the main
-- window (whichever side has room in the viewport) so it never covers the grid.
function seq_position_pattern_popup()
  local popup_w = SEQ_PATTERN_POPUP_W
  local rect = state.main_window_rect
  if not rect then
    if r.ImGui_SetNextWindowSize then
      r.ImGui_SetNextWindowSize(ctx, popup_w, 640.0)
    end
    if r.ImGui_SetNextWindowSizeConstraints then
      r.ImGui_SetNextWindowSizeConstraints(ctx, popup_w, 200.0, popup_w, 10000.0)
    end
    return
  end

  local vp_x, vp_w = nil, nil
  if r.ImGui_GetMainViewport and r.ImGui_Viewport_GetPos and r.ImGui_Viewport_GetSize then
    local vp = r.ImGui_GetMainViewport(ctx)
    if vp then
      vp_x = select(1, r.ImGui_Viewport_GetPos(vp))
      vp_w = select(1, r.ImGui_Viewport_GetSize(vp))
    end
  end

  local right_x = rect.x + rect.w
  local px
  if vp_x and vp_w and (right_x + popup_w) <= (vp_x + vp_w) then
    px = right_x                       -- attach just outside the right edge
  elseif rect.x - popup_w >= (vp_x or 0) then
    px = rect.x - popup_w              -- otherwise attach outside the left edge
  else
    px = right_x - popup_w             -- last resort: overlay the right edge
  end

  if r.ImGui_SetNextWindowPos then
    r.ImGui_SetNextWindowPos(ctx, px, rect.y)
  end
  if r.ImGui_SetNextWindowSize then
    r.ImGui_SetNextWindowSize(ctx, popup_w, rect.h)
  end
  if r.ImGui_SetNextWindowSizeConstraints then
    r.ImGui_SetNextWindowSizeConstraints(ctx, popup_w, 200.0, popup_w, 10000.0)
  end
end

function seq_pattern_variation_store(style_key)
  state.seq_pattern_variations = state.seq_pattern_variations or {}
  local store = state.seq_pattern_variations[style_key]
  if not store then
    store = { counter = 0, entries = {} }
    state.seq_pattern_variations[style_key] = store
  end
  return store
end

function seq_pattern_variation_count(style_key)
  local store = state.seq_pattern_variations and state.seq_pattern_variations[style_key]
  if not store then return 0 end
  return #store.entries
end

function seq_record_pattern_variation(style_key, strength, seed)
  local store = seq_pattern_variation_store(style_key)
  store.counter = store.counter + 1
  local entry = {
    id = store.counter,
    name = get_seq_gen_style_label(style_key) .. " #" .. tostring(store.counter),
    seed = seed,
    strength = strength,
  }
  store.entries[#store.entries + 1] = entry
  return entry
end

function seq_record_ai_variation(style_key, variation, role_map)
  local store = seq_pattern_variation_store(style_key)
  store.counter = store.counter + 1
  local entry = {
    id = store.counter,
    name = get_seq_gen_style_label(style_key) .. " #" .. tostring(store.counter),
    ai = true,
    ai_variation = variation,
    ai_pattern = role_map,
  }
  store.entries[#store.entries + 1] = entry
  return entry
end

-- Snapshot the affected pattern before the *first* pattern application of a
-- confirmation session, so the X button can revert all the way back to the
-- state that exmizisted before the user started auditioning patterns.
function seq_pattern_confirm_capture(region)
  if not region then return end
  if state.seq_pattern_confirm and state.seq_pattern_confirm.active then
    return
  end
  local key = tostring(region.pattern_id)
  state.seq_pattern_confirm = {
    active = true,
    region_id = region.id,
    pattern_id = region.pattern_id,
    snapshot = clone_table_deep(state.seq_patterns[key]),
  }
end

function seq_pattern_confirm_commit()
  state.seq_pattern_confirm = nil
end

function seq_pattern_confirm_restore()
  local c = state.seq_pattern_confirm
  if not c then return end
  local key = tostring(c.pattern_id)
  local label = begin_seq_undo("Revert pattern changes")
  if c.snapshot == nil then
    state.seq_patterns[key] = nil
  else
    state.seq_patterns[key] = clone_table_deep(c.snapshot)
  end
  state.selected_seq_note = nil
  save_config()
  sync_seq_pattern_regions(c.pattern_id)
  end_seq_undo(label)
  state.seq_pattern_confirm = nil
end

function render_seq_pattern_confirm_bar(dl, x0, y0, x1, y1)
  local cy = (y0 + y1) * 0.5
  r.ImGui_DrawList_AddRectFilled(dl, x0 + 2, y0 + 2, x1 + 2, y1 + 2, 0x00000066, 8.0)
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, 0x0E2A18F8, 8.0)
  r.ImGui_DrawList_AddRect(dl, x0, y0, x1, y1, UI_THEME.accent, 8.0, 0, 1.5)

  local txt = "Keep pattern?"
  local _, th = r.ImGui_CalcTextSize(ctx, txt)
  r.ImGui_DrawList_AddText(dl, x0 + 12.0, cy - th * 0.5, UI_THEME.text, txt)

  local btn = 24.0
  local gap = 6.0
  local bx = x1 - 12.0 - btn * 2.0 - gap
  local by = cy - btn * 0.5
  r.ImGui_SetCursorScreenPos(ctx, bx, by)
  if draw_ui_button("seq_pattern_confirm_apply", nil, btn, btn, { icon = "check", style = "success", compact = true }) then
    seq_pattern_confirm_commit()
  end
  r.ImGui_SetCursorScreenPos(ctx, bx + btn + gap, by)
  if draw_ui_button("seq_pattern_confirm_cancel", nil, btn, btn, { icon = "close", style = "danger", compact = true }) then
    seq_pattern_confirm_restore()
  end
end

function run_seq_pattern_preset(region, style_key, strength)
  state.seq_pattern_source = "template"
  state.seq_gen_style = normalize_seq_gen_style(style_key)
  local style = state.seq_gen_style
  if strength then
    state.seq_pattern_popup_last_style = style
    state.seq_pattern_popup_last_strength = strength
  end

  local label = begin_seq_undo(strength and "Randomize sequencer pattern" or "Generate sequencer pattern")
  local created = ensure_seq_tracks_for_roles(seq_template_roles(style))
  if created > 0 then
    log("Added " .. tostring(created) .. " track type(s) for " .. get_seq_gen_style_label(style))
    if r.TrackList_AdjustWindows then
      r.TrackList_AdjustWindows(false)
    end
    r.UpdateArrange()
  end
  if region and seq_has_generatable_track(style) then
    stamp_seq_region_kit_genres(region, style, "template", seq_style_to_library_genres(style))
    seq_pattern_confirm_capture(region)
    local seed = seq_new_seed()
    generate_seq_pattern(region, style, { random_strength = strength, random_seed = seed })
    if strength then
      seq_record_pattern_variation(style, strength, seed)
    end
  end
  end_seq_undo(label)
  save_config()
end

function seq_apply_pattern_variation(region, style_key, variation)
  if not (region and variation) then return end
  state.seq_gen_style = normalize_seq_gen_style(style_key)
  local style = state.seq_gen_style
  local label = begin_seq_undo("Apply pattern variation")
  local created = ensure_seq_tracks_for_roles(seq_template_roles(style))
  if created > 0 then
    if r.TrackList_AdjustWindows then
      r.TrackList_AdjustWindows(false)
    end
    r.UpdateArrange()
  end
  if seq_has_generatable_track(style) then
    stamp_seq_region_kit_genres(region, style, "template", seq_style_to_library_genres(style))
    seq_pattern_confirm_capture(region)
    if variation.ai_pattern then
      -- AI variations store their resulting role->step map so they reproduce
      -- exactly regardless of the current grid contents.
      seq_write_role_positions(region, style, variation.ai_pattern)
    else
      generate_seq_pattern(region, style, { random_strength = variation.strength, random_seed = variation.seed })
    end
  end
  end_seq_undo(label)
  save_config()
end

-- ===================================================================
-- AI pattern variation (local Python sidecar, SampleMapDrumAI.py)
-- ===================================================================

-- Write a role -> {16th positions} map into the region's pattern, repeating each
-- role's positions across every bar (same contract the built-in templates use).
function seq_write_role_positions(region, style_key, role_map)
  if not region or type(role_map) ~= "table" then return 0 end
  style_key = normalize_seq_gen_style(style_key)
  local pattern = get_seq_pattern(region.pattern_id, true)
  if not pattern then return 0 end

  local grid_qn = (type(state.seq_grid_qn) == "number" and state.seq_grid_qn > 0) and state.seq_grid_qn or 0.25
  local region_len_qn = get_seq_region_length_qn(region)
  local steps_per_bar = math.max(1, math.floor((4.0 / grid_qn) + 0.5))
  local bar_count = math.max(1, math.floor((region_len_qn / 4.0) + 0.5))
  local max_steps = math.max(1, math.floor((region_len_qn / grid_qn) + 0.5))

  local locked_notes = seq_collect_locked_notes(pattern, grid_qn)
  pattern.notes = {}
  state.selected_seq_note = nil
  local hit_count = seq_restore_locked_notes(region, locked_notes)

  for _, slot in ipairs(state.seq_tracks) do
    if slot.sample_path then
      local role = infer_seq_track_role(slot)
      local positions = role_map[role]
      if type(positions) == "table" then
        local seen = seq_merge_locked_cell_seen(seq_locked_step_seen(locked_notes, slot.id), pattern, slot.id)
        for bar = 0, bar_count - 1 do
          for _, pos16 in ipairs(positions) do
            local grid_step = seq_template_step_to_grid_step(pos16, steps_per_bar)
            if grid_step then
              local step_idx = bar * steps_per_bar + grid_step
              if step_idx >= 0 and step_idx < max_steps and not seen[step_idx] then
                local note = make_default_seq_note(slot, step_idx, step_idx * grid_qn)
                if note then
                  note.offset_qn = seq_pattern_base_offset(role, pos16, style_key, grid_qn)
                  if (step_idx % steps_per_bar) == 0 and note.offset_qn < 0.0 then
                    note.offset_qn = 0.0
                  end
                  set_seq_note(region, slot.id, step_idx, note)
                  seen[step_idx] = true
                  hit_count = hit_count + 1
                end
              end
            end
          end
        end
      end
    end
  end

  save_config()
  sync_seq_pattern_regions(region.pattern_id)
  return hit_count
end

-- Read the region's current pattern as a role -> {16th positions} map.
function seq_collect_current_role_positions(region)
  local map = {}
  if not region then return map end
  local pattern = get_seq_pattern(region.pattern_id, false)
  local notes_by_track = pattern and pattern.notes or nil

  local grid_qn = (type(state.seq_grid_qn) == "number" and state.seq_grid_qn > 0) and state.seq_grid_qn or 0.25
  local steps_per_bar = math.max(1, math.floor((4.0 / grid_qn) + 0.5))

  for _, slot in ipairs(state.seq_tracks) do
    if slot.sample_path then
      local role = infer_seq_track_role(slot)
      local set = {}
      local notes = notes_by_track and notes_by_track[tostring(slot.id)] or nil
      if notes then
        for step_key, note in pairs(notes) do
          if note and note.enabled ~= false then
            local step_idx = tonumber(note.step) or tonumber(step_key) or 0
            local within = step_idx % steps_per_bar
            local pos16 = math.floor((within * 16.0 / steps_per_bar) + 0.5)
            if pos16 >= 0 and pos16 < 16 then
              set[pos16] = true
            end
          end
        end
      end
      -- Merge (multiple tracks can share a role) and ensure the role exists so
      -- the model also generates for assigned-but-empty tracks.
      local arr = map[role] or {}
      for p in pairs(set) do arr[#arr + 1] = p end
      table.sort(arr)
      map[role] = arr
    end
  end
  return map
end

function seq_drum_ai_sidecar_path()
  return SCRIPT_DIR .. "/SampleMapDrumAI.py"
end

function seq_drum_ai_available()
  local fh = io.open(seq_drum_ai_sidecar_path(), "r")
  if fh then fh:close() return true end
  return false
end

-- Call the local Python model. Returns role_map (table) on success, or nil + err.
function seq_call_drum_ai(style_key, role_positions, variation, seed, steps_per_bar, bars)
  local sidecar = seq_drum_ai_sidecar_path()
  local fh = io.open(sidecar, "r")
  if not fh then return nil, "AI model script not found (SampleMapDrumAI.py)" end
  fh:close()

  local roles = {}
  for _, role in ipairs(SEQ_ROLE_ORDER) do
    if role_positions[role] then roles[#roles + 1] = role end
  end
  if #roles == 0 then return nil, "no assigned tracks to vary" end

  local payload = {
    genre = style_key,
    steps_per_bar = steps_per_bar or 16,
    bars = bars or 4,
    roles = roles,
    pattern = role_positions,
    variation = variation,
    seed = seed,
  }
  local ok_enc, json_payload = pcall(json_encode, payload)
  if not ok_enc then return nil, "failed to encode AI request" end

  local tmp = os.tmpname()
  if not tmp or tmp == "" then return nil, "could not create temp file" end
  local wf = io.open(tmp, "w")
  if not wf then return nil, "could not write temp file" end
  wf:write(json_payload)
  wf:close()

  local cmd = table.concat({
    shell_escape(PYTHON_BIN),
    shell_escape(sidecar),
    shell_escape(tmp),
  }, " ") .. " 2>&1"

  local output = nil
  local pipe = io.popen(cmd, "r")
  if pipe then
    output = pipe:read("*all")
    pipe:close()
  end
  os.remove(tmp)

  if not output or output:match("^%s*$") then
    return nil, "AI model returned no output (is python3 available?)"
  end

  -- Extract the JSON object in case python emitted warnings before it.
  local json_str = output:match("(%b{})")
  if not json_str then
    return nil, "AI model output not understood"
  end
  local ok_dec, decoded = pcall(json_decode, json_str)
  if not ok_dec or type(decoded) ~= "table" or type(decoded.pattern) ~= "table" then
    return nil, "AI model output invalid"
  end

  -- Normalize: ensure each role maps to an array of integers.
  local result = {}
  for role, positions in pairs(decoded.pattern) do
    if type(positions) == "table" then
      local arr = {}
      for _, p in ipairs(positions) do
        local n = tonumber(p)
        if n then arr[#arr + 1] = math.floor(n + 0.5) end
      end
      result[role] = arr
    end
  end
  return result
end

function run_seq_ai_variation(region, style_key, variation)
  state.seq_gen_style = normalize_seq_gen_style(style_key)
  local style = state.seq_gen_style
  variation = math.max(0.0, math.min(1.0, variation or 0.5))

  local label = begin_seq_undo("AI pattern variation")
  local created = ensure_seq_tracks_for_roles(seq_template_roles(style))
  if created > 0 then
    if r.TrackList_AdjustWindows then
      r.TrackList_AdjustWindows(false)
    end
    r.UpdateArrange()
  end

  if not (region and seq_has_generatable_track(style)) then
    end_seq_undo(label)
    save_config()
    return false
  end

  local grid_qn = (type(state.seq_grid_qn) == "number" and state.seq_grid_qn > 0) and state.seq_grid_qn or 0.25
  local steps_per_bar = math.max(1, math.floor((4.0 / grid_qn) + 0.5))
  local bar_count = math.max(1, math.floor((get_seq_region_length_qn(region) / 4.0) + 0.5))

  local role_positions = seq_collect_current_role_positions(region)
  local seed = seq_new_seed()

  seq_pattern_confirm_capture(region)
  local role_map, err = seq_call_drum_ai(style, role_positions, variation, seed, steps_per_bar, bar_count)
  if not role_map then
    -- Graceful fallback: use the built-in randomizer so the click still does
    -- something musical even when the model can't be reached.
    log("AI variation unavailable (" .. tostring(err) .. "); using built-in randomizer")
    generate_seq_pattern(region, style, { random_strength = 3, random_seed = seed })
    end_seq_undo(label)
    save_config()
    return false
  end

  stamp_seq_region_kit_genres(region, style, "template", seq_style_to_library_genres(style))
  local hits = seq_write_role_positions(region, style, role_map)
  seq_record_ai_variation(style, variation, role_map)
  log(string.format("AI variation (%s, var %.0f%%, %d hits)", get_seq_gen_style_label(style), variation * 100.0, hits))
  end_seq_undo(label)
  save_config()
  return true
end

-- ===================================================================
-- Groove MIDI Dataset (Magenta) — SampleMapGrooveMIDI.py
-- Human drum performances from Google Magenta's Groove MIDI Dataset.
-- ===================================================================

function seq_gmd_sidecar_path()
  return SCRIPT_DIR .. "/SampleMapGrooveMIDI.py"
end

function seq_gmd_available()
  local fh = io.open(seq_gmd_sidecar_path(), "r")
  if fh then fh:close() return true end
  return false
end

-- Call the Groove MIDI sidecar. Returns decoded table on success, or nil + err.
function seq_call_gmd(payload)
  local sidecar = seq_gmd_sidecar_path()
  local fh = io.open(sidecar, "r")
  if not fh then return nil, "Groove MIDI script not found (SampleMapGrooveMIDI.py)" end
  fh:close()

  local ok_enc, json_payload = pcall(json_encode, payload or {})
  if not ok_enc then return nil, "failed to encode Groove MIDI request" end

  local tmp = os.tmpname()
  if not tmp or tmp == "" then return nil, "could not create temp file" end
  local wf = io.open(tmp, "w")
  if not wf then return nil, "could not write temp file" end
  wf:write(json_payload)
  wf:close()

  local cmd = table.concat({
    shell_escape(PYTHON_BIN),
    shell_escape(sidecar),
    shell_escape(tmp),
  }, " ") .. " 2>&1"

  local output = nil
  local pipe = io.popen(cmd, "r")
  if pipe then
    output = pipe:read("*all")
    pipe:close()
  end
  os.remove(tmp)

  if not output or output:match("^%s*$") then
    return nil, "Groove MIDI returned no output (is python3 / network available?)"
  end

  local json_str = output:match("(%b{})")
  if not json_str then
    return nil, "Groove MIDI output not understood"
  end
  local ok_dec, decoded = pcall(json_decode, json_str)
  if not ok_dec or type(decoded) ~= "table" then
    return nil, "Groove MIDI output invalid"
  end
  if decoded.error then
    return nil, tostring(decoded.error)
  end
  return decoded
end

function seq_gmd_ensure(force)
  if state.seq_gmd_ready and not force then
    return true
  end
  if not seq_gmd_available() then
    state.seq_gmd_ready = false
    state.seq_gmd_status_msg = "SampleMapGrooveMIDI.py missing"
    return false
  end
  state.seq_gmd_status_msg = "Downloading Groove MIDI Dataset..."
  local result, err = seq_call_gmd({ action = "ensure" })
  if not result then
    state.seq_gmd_ready = false
    state.seq_gmd_status_msg = tostring(err)
    log("Groove MIDI ensure failed: " .. tostring(err))
    return false
  end
  state.seq_gmd_ready = result.ready == true
  state.seq_gmd_status_msg = string.format(
    "Ready — %d grooves",
    tonumber(result.count) or 0
  )
  state.seq_gmd_list_key = nil
  log("Groove MIDI Dataset ready (" .. tostring(result.count or 0) .. " files)")
  return state.seq_gmd_ready
end

function seq_gmd_list_cache_key()
  return tostring(state.seq_gmd_beat_type or "beat")
end

function seq_gmd_pretty_label(style)
  local s = tostring(style or "")
  if s == "" then return "Groove" end
  local parts = {}
  for seg in s:gmatch("[^/]+") do
    seg = seg:gsub("%-", " ")
    local words = {}
    for w in seg:gmatch("%S+") do
      words[#words + 1] = w:sub(1, 1):upper() .. w:sub(2)
    end
    parts[#parts + 1] = table.concat(words, " ")
  end
  return table.concat(parts, " / ")
end

-- Subgenre tail for flat child labels: jazz/march -> "March", rock -> "Rock".
function seq_gmd_subgenre_short_label(full_style, primary)
  local full = tostring(full_style or "")
  local tail = full
  if full:find("/", 1, true) then
    tail = full:match("/([^/]+)$") or full
  end
  local parts = {}
  for seg in tail:gmatch("[^/]+") do
    seg = seg:gsub("%-", " ")
    local words = {}
    for w in seg:gmatch("%S+") do
      words[#words + 1] = w:sub(1, 1):upper() .. w:sub(2)
    end
    parts[#parts + 1] = table.concat(words, " ")
  end
  local label = table.concat(parts, " ")
  if label == "" then
    label = seq_gmd_pretty_label(primary or full)
  end
  return label
end

-- Collapse Groove MIDI by primary genre; individual performances are flat children
-- named like "March 1", "March 2" under Jazz.
function seq_gmd_rebuild_groups()
  local items = state.seq_gmd_items or {}
  local by_primary = {}
  local order = {}
  for _, item in ipairs(items) do
    if type(item) == "table" then
      local primary = tostring(item.style_primary or ""):lower()
      if primary == "" then
        local full = tostring(item.style or "")
        primary = (full:match("^([^/]+)") or full):lower()
      end
      if primary == "" then primary = "groove" end

      local full_style = tostring(item.style or primary)
      if full_style == "" then full_style = primary end

      local group = by_primary[primary]
      if not group then
        group = {
          name = primary,
          key = "gmd:" .. primary,
          label = seq_gmd_pretty_label(primary),
          items = {},
          subgenres = {},
          subgenre_by_name = {},
        }
        by_primary[primary] = group
        order[#order + 1] = group
      end

      group.items[#group.items + 1] = item

      local sub = group.subgenre_by_name[full_style]
      if not sub then
        sub = {
          name = full_style,
          label = seq_gmd_pretty_label(full_style),
          items = {},
        }
        group.subgenre_by_name[full_style] = sub
        group.subgenres[#group.subgenres + 1] = sub
      end
      sub.items[#sub.items + 1] = item
    end
  end

  table.sort(order, function(a, b)
    return tostring(a.label):lower() < tostring(b.label):lower()
  end)
  for _, group in ipairs(order) do
    table.sort(group.subgenres, function(a, b)
      return tostring(a.label):lower() < tostring(b.label):lower()
    end)
    for _, sub in ipairs(group.subgenres) do
      table.sort(sub.items, function(a, b)
        local ba = tonumber(a.bpm) or 0
        local bb = tonumber(b.bpm) or 0
        if ba ~= bb then return ba < bb end
        return tostring(a.id or "") < tostring(b.id or "")
      end)
    end
    table.sort(group.items, function(a, b)
      local ba = tonumber(a.bpm) or 0
      local bb = tonumber(b.bpm) or 0
      if ba ~= bb then return ba < bb end
      return tostring(a.id or "") < tostring(b.id or "")
    end)
    group.children = {}
    for _, sub in ipairs(group.subgenres) do
      local short = seq_gmd_subgenre_short_label(sub.name, group.name)
      for i, item in ipairs(sub.items) do
        group.children[#group.children + 1] = {
          item = item,
          label = short .. " " .. tostring(i),
          subgenre = sub.name,
          index = i,
        }
      end
    end
    group.subgenre_by_name = nil
  end
  state.seq_gmd_groups = order
  state.seq_gmd_group_by_name = by_primary
  return order
end

function seq_gmd_find_group(style_name)
  if not style_name then return nil end
  local by_name = state.seq_gmd_group_by_name
  if type(by_name) == "table" then
    return by_name[style_name]
  end
  return nil
end

function seq_gmd_refresh_list(force)
  if not state.seq_gmd_ready then
    return false
  end
  local key = seq_gmd_list_cache_key()
  if not force and state.seq_gmd_list_key == key
      and type(state.seq_gmd_items) == "table"
      and type(state.seq_gmd_groups) == "table" then
    return true
  end

  local result, err = seq_call_gmd({
    action = "list",
    style = "all",
    beat_type = state.seq_gmd_beat_type or "beat",
    limit = 0, -- 0 = return every matching groove
    offset = 0,
  })
  if not result then
    state.seq_gmd_status_msg = tostring(err)
    return false
  end
  state.seq_gmd_items = result.items or {}
  state.seq_gmd_total = tonumber(result.total) or #state.seq_gmd_items
  state.seq_gmd_list_key = key
  local groups = seq_gmd_rebuild_groups()
  state.seq_gmd_status_msg = string.format(
    "%d preset%s · %d groove%s",
    #groups,
    #groups == 1 and "" or "s",
    state.seq_gmd_total,
    state.seq_gmd_total == 1 and "" or "s"
  )
  return true
end

function seq_gmd_cycle_beat_type()
  local order = { "beat", "fill", "all" }
  local cur = state.seq_gmd_beat_type or "beat"
  local idx = 1
  for i, v in ipairs(order) do
    if v == cur then idx = i break end
  end
  state.seq_gmd_beat_type = order[(idx % #order) + 1]
  state.seq_gmd_list_key = nil
end

-- Pick a variation from a merged Groove MIDI preset. Plain click prefers the
-- current selection / median BPM; dice strength 1..6 samples a BPM band.
function seq_gmd_pick_item(group, strength)
  if not group or type(group.items) ~= "table" or #group.items == 0 then
    return nil
  end
  local items = group.items
  local n = #items
  if not strength then
    if state.seq_gmd_selected_id then
      for _, item in ipairs(items) do
        if tostring(item.id) == tostring(state.seq_gmd_selected_id) then
          return item
        end
      end
    end
    return items[math.floor((n + 1) / 2)]
  end

  strength = math.max(1, math.min(6, math.floor(tonumber(strength) or 1)))
  local lo = math.floor((strength - 1) / 6 * n) + 1
  local hi = math.floor(strength / 6 * n)
  if hi < lo then hi = lo end
  if hi > n then hi = n end
  local seed = seq_new_seed()
  local idx = lo + ((seed - 1) % (hi - lo + 1))
  return items[idx]
end

function seq_gmd_normalize_role_map(pattern)
  local result = {}
  if type(pattern) ~= "table" then return result end
  for role, positions in pairs(pattern) do
    if type(positions) == "table" then
      local arr = {}
      for _, p in ipairs(positions) do
        local n = tonumber(p)
        if n then arr[#arr + 1] = math.floor(n + 0.5) end
      end
      if #arr > 0 then
        result[tostring(role)] = arr
      end
    end
  end
  return result
end

function seq_gmd_apply_result(region, result)
  if not region or type(result) ~= "table" then return false end
  local role_map = seq_gmd_normalize_role_map(result.pattern)
  local roles = {}
  if type(result.roles) == "table" then
    for _, role in ipairs(result.roles) do
      roles[#roles + 1] = tostring(role)
    end
  end
  if #roles == 0 then
    for _, role in ipairs(SEQ_ROLE_ORDER) do
      if role_map[role] then roles[#roles + 1] = role end
    end
  end
  if #roles == 0 then
    log("Groove MIDI pattern had no mappable drum hits")
    return false
  end

  local label = begin_seq_undo("Load Groove MIDI pattern")
  local created = ensure_seq_tracks_for_roles(roles)
  if created > 0 then
    if r.TrackList_AdjustWindows then
      r.TrackList_AdjustWindows(false)
    end
    r.UpdateArrange()
  end

  seq_pattern_confirm_capture(region)
  local style = normalize_seq_gen_style(state.seq_gen_style)
  local hits = seq_write_role_positions(region, style, role_map)

  local meta = result.meta or {}
  state.seq_pattern_source = "gmd"
  state.seq_gmd_selected_id = meta.id
  local primary = tostring(meta.style_primary or ""):lower()
  if primary == "" then
    local style_full = tostring(meta.style or "")
    primary = (style_full:match("^([^/]+)") or style_full):lower()
  end
  if primary ~= "" then
    state.seq_gmd_selected_style = primary
  end
  local gmd_style_label = tostring(meta.style or meta.style_primary or primary)
  stamp_seq_region_kit_genres(
    region,
    gmd_style_label ~= "" and gmd_style_label or primary,
    "gmd",
    seq_library_genres_from_text(gmd_style_label ~= "" and gmd_style_label or primary)
  )
  local style_label = seq_gmd_pretty_label(meta.style or meta.style_primary or state.seq_gmd_selected_style)
  local bpm = tonumber(meta.bpm)
  local beat = tostring(meta.beat_type or "")
  log(string.format(
    "Loaded Groove MIDI: %s%s%s (%d hits, bar %s/%s)",
    style_label,
    bpm and (" @ " .. tostring(bpm) .. " BPM") or "",
    beat ~= "" and (" / " .. beat) or "",
    hits,
    tostring(result.bar_offset or 0),
    tostring(result.total_bars or "?")
  ))
  end_seq_undo(label)
  save_config()
  return hits > 0
end

function run_seq_gmd_load_id(region, entry_id)
  if not region or not entry_id then return false end
  if not seq_gmd_ensure(false) then return false end
  local result, err = seq_call_gmd({
    action = "get",
    id = entry_id,
    bars = 1,
    seed = seq_new_seed(),
  })
  if not result then
    log("Groove MIDI load failed: " .. tostring(err))
    state.seq_gmd_status_msg = tostring(err)
    return false
  end
  return seq_gmd_apply_result(region, result)
end

function run_seq_gmd_preset(region, group, strength)
  if not region or type(group) ~= "table" then return false end
  if not seq_gmd_ensure(false) then return false end
  state.seq_pattern_source = "gmd"
  state.seq_gmd_selected_style = group.name
  local item = seq_gmd_pick_item(group, strength)
  if not item then
    state.seq_gmd_status_msg = "No variations in this preset"
    return false
  end
  return run_seq_gmd_load_id(region, item.id)
end

function seq_gmd_probe_ready()
  if state.seq_gmd_ready ~= nil then
    return state.seq_gmd_ready
  end
  if not seq_gmd_available() then
    state.seq_gmd_ready = false
    state.seq_gmd_status_msg = "SampleMapGrooveMIDI.py not found"
    return false
  end
  local st = seq_call_gmd({ action = "status" })
  if st and st.ready then
    state.seq_gmd_ready = true
    state.seq_gmd_status_msg = string.format("Ready — %d grooves", tonumber(st.count) or 0)
  else
    state.seq_gmd_ready = false
    state.seq_gmd_status_msg = "Not downloaded yet"
  end
  return state.seq_gmd_ready
end

function seq_pattern_query_matches(query, haystack)
  if not query or query == "" then return true end
  return tostring(haystack or ""):lower():find(query, 1, true) ~= nil
end

-- Match a hard-coded preset to a Groove MIDI parent by exact display name or style key.
function seq_pattern_match_template_for_gmd(group)
  if type(group) ~= "table" then return nil end
  local gname = tostring(group.name or ""):lower()
  local glabel = tostring(group.label or ""):lower()
  for _, style in ipairs(SEQ_GEN_STYLE_ORDER) do
    if style.key then
      local label = tostring(style.label or style.key):lower()
      local key = tostring(style.key):lower()
      if label == glabel or key == gname then
        return style
      end
    end
  end
  return nil
end

function seq_pattern_gmd_child_count(group, template_style)
  local n = type(group) == "table" and type(group.children) == "table" and #group.children or 0
  if template_style then n = n + 1 end
  return n
end

function seq_gmd_group_has_children(group, template_style)
  if template_style then return true end
  local n = type(group) == "table" and type(group.children) == "table" and #group.children or 0
  return n > 1
end

-- One alphabetical list of template presets + Groove MIDI presets.
-- Same-named hard-coded presets are nested as the first child of the GMD parent.
function seq_pattern_browser_entries()
  local raw = tostring(state.seq_pattern_search or "")
  local q = raw:lower():gsub("^%s+", ""):gsub("%s+$", "")
  local entries = {}
  local used_templates = {}

  if state.seq_gmd_ready then
    seq_gmd_refresh_list(false)
    for _, group in ipairs(state.seq_gmd_groups or {}) do
      local template = seq_pattern_match_template_for_gmd(group)
      local hay = tostring(group.label or "") .. " " .. tostring(group.name or "") .. " groove midi"
      if template then
        used_templates[template.key] = true
        hay = hay .. " " .. tostring(template.label or template.key) .. " " .. tostring(template.key)
        for _, role in ipairs(seq_template_roles(template.key)) do
          hay = hay .. " " .. (SEQ_ROLE_LABELS[role] or role)
        end
      end
      for _, child in ipairs(group.children or {}) do
        hay = hay .. " " .. tostring(child.label or "")
        local item = child.item
        if type(item) == "table" then
          hay = hay
            .. " "
            .. tostring(child.subgenre or "")
            .. " "
            .. tostring(item.drummer or "")
            .. " "
            .. tostring(item.bpm or "")
        end
      end
      if seq_pattern_query_matches(q, hay) then
        entries[#entries + 1] = {
          kind = "gmd",
          key = group.key,
          label = group.label,
          sort = tostring(group.label or group.name or ""):lower(),
          group = group,
          template = template,
        }
      end
    end
  end

  for _, style in ipairs(SEQ_GEN_STYLE_ORDER) do
    if style.key and not used_templates[style.key] then
      local label = style.label or style.key
      local hay = label .. " " .. style.key
      for _, role in ipairs(seq_template_roles(style.key)) do
        hay = hay .. " " .. (SEQ_ROLE_LABELS[role] or role)
      end
      if seq_pattern_query_matches(q, hay) then
        entries[#entries + 1] = {
          kind = "template",
          key = style.key,
          label = label,
          sort = tostring(label):lower(),
          style_def = style,
        }
      end
    end
  end

  table.sort(entries, function(a, b)
    if a.sort == b.sort then
      if a.kind ~= b.kind then return a.kind == "gmd" end
      return tostring(a.key) < tostring(b.key)
    end
    return a.sort < b.sort
  end)
  return entries
end

function render_seq_gmd_toolbar()
  if not seq_gmd_available() then
    return
  end

  seq_gmd_probe_ready()
  if not state.seq_gmd_ready then
    if draw_ui_button("seq_gmd_download", "Download Groove MIDI (~3 MB)", nil, nil, { style = "success", compact = true }) then
      seq_gmd_ensure(true)
    end
    if state.seq_gmd_status_msg then
      r.ImGui_SameLine(ctx)
      r.ImGui_TextColored(ctx, 0xFFB870FF, tostring(state.seq_gmd_status_msg))
    end
    return
  end

  local beat_label = "Type: " .. tostring(state.seq_gmd_beat_type or "beat")
  if draw_ui_button("seq_gmd_beat", beat_label, nil, nil, { style = "default", compact = true }) then
    seq_gmd_cycle_beat_type()
  end
  if state.seq_gmd_status_msg then
    r.ImGui_SameLine(ctx)
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, tostring(state.seq_gmd_status_msg))
  end
  seq_gmd_refresh_list(false)
end

-- Shared hover-dice strip used by nested child rows.
function seq_pattern_draw_hover_dice(region, id_prefix, x, y, size, gap, on_strength)
  for strength = 1, 6 do
    r.ImGui_SetCursorScreenPos(ctx, x + (strength - 1) * (size + gap), y)
    local dice_clicked = draw_ui_button(
      id_prefix .. "_" .. tostring(strength),
      nil,
      size,
      size,
      { icon = "dice" .. tostring(strength), compact = true, style = "default" }
    )
    if dice_clicked and region and on_strength then
      on_strength(strength)
    end
  end
end

function render_seq_gmd_preset_row(region, group, template_style)
  if type(group) ~= "table" then return end
  local style_key = group.key
  local id_safe = tostring(style_key or group.name or "gmd"):gsub("[^%w]", "_")
  local selected = (state.seq_pattern_source == "gmd" and state.seq_gmd_selected_style == group.name)
    or (template_style and state.seq_pattern_source ~= "gmd" and state.seq_gen_style == template_style.key)
  local avail_w = r.ImGui_GetContentRegionAvail(ctx)
  local row_w = math.max(1.0, avail_w)
  local row_h = 34.0
  local left_pad = 10.0
  local right_pad = 8.0
  local item_count = type(group.items) == "table" and #group.items or 0
  local child_count = seq_pattern_gmd_child_count(group, template_style)
  local has_children = seq_gmd_group_has_children(group, template_style)
  state.seq_gmd_expanded = state.seq_gmd_expanded or {}
  local expanded = state.seq_gmd_expanded[group.name] == true

  local x0, y0 = r.ImGui_GetCursorScreenPos(ctx)
  local x1, y1 = x0 + row_w, y0 + row_h
  local mx, my = r.ImGui_GetMousePos(ctx)
  local hovered = mx >= x0 and mx <= x1 and my >= y0 and my <= y1

  local btn_size = 20.0
  local btn_gap = 3.0
  local list_w = has_children and (btn_size + 6.0) or 0.0
  local list_x = x0 + row_w - right_pad - btn_size

  -- Dice only on leaf parents (single MIDI, no nested hard-coded child).
  local show_parent_dice = hovered and not has_children
  local dice_size = btn_size
  local dice_total_w = dice_size * 6.0 + btn_gap * 5.0
  local right_edge = x0 + row_w - right_pad - list_w
  if show_parent_dice and dice_total_w > (right_edge - x0 - 70.0) then
    dice_size = math.max(13.0, math.floor((right_edge - x0 - 70.0 - btn_gap * 5.0) / 6.0))
    dice_total_w = dice_size * 6.0 + btn_gap * 5.0
  end
  local dice_x = right_edge - dice_total_w

  local interactive_left = right_edge
  if show_parent_dice then
    interactive_left = dice_x
  end
  local row_button_w = math.max(40.0, interactive_left - x0 - 4.0)
  r.ImGui_InvisibleButton(ctx, "##seq_gmd_preset_row_" .. id_safe, row_button_w, row_h)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)

  local dl = r.ImGui_GetWindowDrawList(ctx)
  local fill = selected and UI_THEME.accent_fill or UI_THEME.bg_panel
  local edge = selected and UI_THEME.accent or UI_THEME.border
  if hovered then
    fill = selected and UI_THEME.accent_fill_h or UI_THEME.surface_hvr
    edge = UI_THEME.accent_hvr
  end
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, fill, 5.0)
  r.ImGui_DrawList_AddRect(dl, x0, y0, x1, y1, edge, 5.0, 0, selected and 1.5 or 1.0)

  local label_color = selected and 0xFFFFFFFF or UI_THEME.text
  local label_right = show_parent_dice and dice_x or (x0 + row_w - right_pad - list_w)
  local label_max_w = math.max(20.0, label_right - x0 - left_pad - 6.0)
  if not show_parent_dice then
    label_max_w = math.min(label_max_w, row_w * 0.50)
  end
  local label_text = seq_truncate_text_to_width(group.label or group.name, label_max_w)
  r.ImGui_DrawList_AddText(dl, x0 + left_pad, y0 + 9.0, label_color, label_text)

  if not show_parent_dice then
    local meta_text = child_count == 1 and "1 variation" or (tostring(child_count) .. " variations")
    local label_w = select(1, r.ImGui_CalcTextSize(ctx, label_text))
    local meta_right = x0 + row_w - right_pad - list_w
    local meta_max_w = math.max(20.0, meta_right - (x0 + left_pad + label_w) - 12.0)
    meta_text = seq_truncate_text_to_width(meta_text, meta_max_w)
    local meta_w = select(1, r.ImGui_CalcTextSize(ctx, meta_text))
    r.ImGui_DrawList_AddText(dl, meta_right - meta_w, y0 + 9.0, 0x8AA6C8FF, meta_text)
  end

  -- Parent click selects / toggles children — it does not load a variation.
  if clicked then
    state.seq_gmd_selected_style = group.name
    if has_children then
      state.seq_gmd_expanded[group.name] = not expanded
      expanded = state.seq_gmd_expanded[group.name] == true
    elseif region and item_count > 0 then
      state.seq_pattern_source = "gmd"
      run_seq_gmd_load_id(region, group.items[1].id)
    else
      state.seq_pattern_source = "gmd"
    end
  end

  if show_parent_dice then
    seq_pattern_draw_hover_dice(
      region,
      "seq_gmd_dice_" .. id_safe,
      dice_x,
      y0 + (row_h - dice_size) * 0.5,
      dice_size,
      btn_gap,
      function(strength)
        run_seq_gmd_preset(region, group, strength)
      end
    )
  end

  if has_children then
    r.ImGui_SetCursorScreenPos(ctx, list_x, y0 + (row_h - btn_size) * 0.5)
    local list_clicked = draw_ui_button(
      "seq_gmd_expand_" .. id_safe,
      nil,
      btn_size,
      btn_size,
      {
        icon = expanded and "chev_down" or "chev_right",
        compact = true,
        style = expanded and "success" or "default",
      }
    )
    if list_clicked then
      state.seq_gmd_expanded[group.name] = not expanded
      expanded = state.seq_gmd_expanded[group.name] == true
    end
  end

  r.ImGui_SetCursorScreenPos(ctx, x0, y1)
  r.ImGui_Dummy(ctx, 0, expanded and 2.0 or 5.0)

  if expanded and has_children then
    if template_style then
      render_seq_pattern_nested_template_row(region, template_style, id_safe)
    end
    for _, child in ipairs(group.children or {}) do
      render_seq_gmd_pattern_row(region, child, id_safe)
    end
    r.ImGui_Dummy(ctx, 0, 4.0)
  end
end

-- Hard-coded preset nested as the first child under a same-named Groove MIDI parent.
function render_seq_pattern_nested_template_row(region, style_def, parent_id_safe)
  if type(style_def) ~= "table" or not style_def.key then return end
  local style_key = style_def.key
  local id_safe = tostring(parent_id_safe or "gmd") .. "_tmpl_" .. tostring(style_key):gsub("[^%w]", "_")
  local selected = state.seq_pattern_source ~= "gmd" and state.seq_gen_style == style_key
  local can_generate = region and seq_preset_can_generate(style_key)
  local indent = 16.0
  local avail = r.ImGui_GetContentRegionAvail(ctx)
  local row_w = math.max(1.0, avail - indent)
  local row_h = 30.0
  local left_pad = 8.0
  local right_pad = 6.0
  local btn_size = 18.0
  local btn_gap = 2.0

  local has_variations = seq_pattern_variation_count(style_key) > 0
  local list_w = has_variations and (btn_size + 4.0) or 0.0

  local x_base, y_base = r.ImGui_GetCursorScreenPos(ctx)
  r.ImGui_SetCursorScreenPos(ctx, x_base + indent, y_base)

  local x0, y0 = r.ImGui_GetCursorScreenPos(ctx)
  local x1, y1 = x0 + row_w, y0 + row_h
  local mx, my = r.ImGui_GetMousePos(ctx)
  local hovered = mx >= x0 and mx <= x1 and my >= y0 and my <= y1

  local list_x = x0 + row_w - right_pad - btn_size
  local right_edge = x0 + row_w - right_pad - list_w
  local dice_size = btn_size
  local dice_total_w = dice_size * 6.0 + btn_gap * 5.0
  if hovered and dice_total_w > (right_edge - x0 - 60.0) then
    dice_size = math.max(12.0, math.floor((right_edge - x0 - 60.0 - btn_gap * 5.0) / 6.0))
    dice_total_w = dice_size * 6.0 + btn_gap * 5.0
  end
  local dice_x = right_edge - dice_total_w
  local interactive_left = hovered and dice_x or right_edge
  local row_button_w = math.max(40.0, interactive_left - x0 - 4.0)

  r.ImGui_InvisibleButton(ctx, "##seq_nested_tmpl_" .. id_safe, row_button_w, row_h)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local dl = r.ImGui_GetWindowDrawList(ctx)

  local fill = selected and UI_THEME.accent_fill or UI_THEME.bg_panel
  local edge = selected and UI_THEME.accent or UI_THEME.border
  if hovered then
    fill = selected and UI_THEME.accent_fill_h or UI_THEME.surface_hvr
    edge = UI_THEME.accent_hvr
  end
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, fill, 4.0)
  r.ImGui_DrawList_AddRect(dl, x0, y0, x1, y1, edge, 4.0, 0, selected and 1.5 or 1.0)

  local label_right = hovered and dice_x or right_edge
  local label_max_w = math.max(20.0, label_right - x0 - left_pad - 6.0)
  local label_text = seq_truncate_text_to_width(style_def.label or style_key, label_max_w)
  r.ImGui_DrawList_AddText(dl, x0 + left_pad, y0 + 7.0, selected and 0xFFFFFFFF or UI_THEME.text, label_text)

  if not hovered then
    local pill_x = x0 + left_pad + select(1, r.ImGui_CalcTextSize(ctx, label_text)) + 8.0
    draw_ui_pill_label(dl, pill_x, (y0 + y1) * 0.5, "Built-in", {
      bg = UI_THEME.accent_fill,
      border = UI_THEME.accent,
      text_col = 0xF0F8FFFF,
      pad_x = 6.0,
      pad_y = 2.0,
      rounding = 5.0,
    })
  end

  if clicked and can_generate then
    run_seq_pattern_preset(region, style_key, nil)
  elseif clicked then
    state.seq_pattern_source = "template"
    state.seq_gen_style = normalize_seq_gen_style(style_key)
    save_config()
  end

  if hovered then
    seq_pattern_draw_hover_dice(
      region,
      "seq_nested_tmpl_dice_" .. id_safe,
      dice_x,
      y0 + (row_h - dice_size) * 0.5,
      dice_size,
      btn_gap,
      function(strength)
        if can_generate then
          run_seq_pattern_preset(region, style_key, strength)
        end
      end
    )
  end

  if has_variations then
    r.ImGui_SetCursorScreenPos(ctx, list_x, y0 + (row_h - btn_size) * 0.5)
    if draw_ui_button(
      "seq_nested_tmpl_varlist_" .. id_safe,
      nil,
      btn_size,
      btn_size,
      { icon = "list", compact = true, style = selected and "primary" or "default" }
    ) then
      state.seq_pattern_variations_open_key = style_key
      state.seq_pattern_variations_request_open = true
    end
  end

  r.ImGui_SetCursorScreenPos(ctx, x_base, y1)
  r.ImGui_Dummy(ctx, 0, 2.0)
end

function render_seq_pattern_preset_row(region, style_def)
  local style_key = style_def.key
  local selected = state.seq_pattern_source ~= "gmd" and state.seq_gen_style == style_key
  local can_generate = region and seq_preset_can_generate(style_key)
  local avail_w = r.ImGui_GetContentRegionAvail(ctx)
  local row_w = math.max(1.0, avail_w)
  local row_h = 34.0
  local left_pad = 10.0
  local right_pad = 8.0

  local x0, y0 = r.ImGui_GetCursorScreenPos(ctx)
  local x1, y1 = x0 + row_w, y0 + row_h
  local mx, my = r.ImGui_GetMousePos(ctx)
  local hovered = mx >= x0 and mx <= x1 and my >= y0 and my <= y1

  local has_variations = seq_pattern_variation_count(style_key) > 0
  local btn_size = 20.0
  local btn_gap = 3.0

  -- The list button sits at the far right whenever variations exist.
  local list_w = has_variations and (btn_size + 6.0) or 0.0
  local list_x = x0 + row_w - right_pad - btn_size

  -- Dice strip appears on hover, to the left of the list button.
  local dice_size = btn_size
  local dice_total_w = dice_size * 6.0 + btn_gap * 5.0
  local right_edge = x0 + row_w - right_pad - list_w
  if hovered and dice_total_w > (right_edge - x0 - 70.0) then
    dice_size = math.max(13.0, math.floor((right_edge - x0 - 70.0 - btn_gap * 5.0) / 6.0))
    dice_total_w = dice_size * 6.0 + btn_gap * 5.0
  end
  local dice_x = right_edge - dice_total_w

  -- Row click area excludes the dice strip (on hover) and the list button so
  -- those overlapping buttons receive their own clicks.
  local interactive_left = right_edge
  if hovered then
    interactive_left = dice_x
  end
  local row_button_w = math.max(40.0, interactive_left - x0 - 4.0)
  r.ImGui_InvisibleButton(ctx, "##seq_pattern_preset_row_" .. style_key, row_button_w, row_h)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)

  local dl = r.ImGui_GetWindowDrawList(ctx)
  local fill = selected and UI_THEME.accent_fill or UI_THEME.bg_panel
  local edge = selected and UI_THEME.accent or UI_THEME.border
  if hovered then
    fill = selected and UI_THEME.accent_fill_h or UI_THEME.surface_hvr
    edge = UI_THEME.accent_hvr
  end
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, fill, 5.0)
  r.ImGui_DrawList_AddRect(dl, x0, y0, x1, y1, edge, 5.0, 0, selected and 1.5 or 1.0)

  local label_color = selected and 0xFFFFFFFF or UI_THEME.text
  local label_right = hovered and dice_x or (x0 + row_w - right_pad - list_w)
  local label_max_w = math.max(20.0, label_right - x0 - left_pad - 6.0)
  if not hovered then
    label_max_w = math.min(label_max_w, row_w * 0.42)
  end
  local label_text = seq_truncate_text_to_width(style_def.label, label_max_w)
  r.ImGui_DrawList_AddText(dl, x0 + left_pad, y0 + 9.0, label_color, label_text)

  if not hovered then
    local palette = {}
    for _, role in ipairs(seq_template_roles(style_key)) do
      palette[#palette + 1] = SEQ_ROLE_LABELS[role] or role
    end
    if #palette > 0 then
      local palette_text = table.concat(palette, " \xC2\xB7 ")
      local label_w = select(1, r.ImGui_CalcTextSize(ctx, label_text))
      local palette_right = x0 + row_w - right_pad - list_w
      local palette_max_w = math.max(20.0, palette_right - (x0 + left_pad + label_w) - 12.0)
      palette_text = seq_truncate_text_to_width(palette_text, palette_max_w)
      local palette_w = select(1, r.ImGui_CalcTextSize(ctx, palette_text))
      r.ImGui_DrawList_AddText(
        dl,
        palette_right - palette_w,
        y0 + 9.0,
        can_generate and 0x8AA6C8FF or 0x6A748AFF,
        palette_text
      )
    end
  end

  if clicked and can_generate then
    run_seq_pattern_preset(region, style_key, nil)
  elseif clicked then
    state.seq_pattern_source = "template"
    state.seq_gen_style = normalize_seq_gen_style(style_key)
    save_config()
  end

  if hovered then
    local dice_y = y0 + (row_h - dice_size) * 0.5
    for strength = 1, 6 do
      r.ImGui_SetCursorScreenPos(ctx, dice_x + (strength - 1) * (dice_size + btn_gap), dice_y)
      local dice_clicked = draw_ui_button(
        "seq_pattern_dice_" .. style_key .. "_" .. tostring(strength),
        nil,
        dice_size,
        dice_size,
        { icon = "dice" .. tostring(strength), compact = true, style = "default" }
      )
      if dice_clicked and can_generate then
        run_seq_pattern_preset(region, style_key, strength)
      end
    end
  end

  if has_variations then
    r.ImGui_SetCursorScreenPos(ctx, list_x, y0 + (row_h - btn_size) * 0.5)
    local list_clicked = draw_ui_button(
      "seq_pattern_varlist_" .. style_key,
      nil,
      btn_size,
      btn_size,
      { icon = "list", compact = true, style = selected and "primary" or "default" }
    )
    if list_clicked then
      state.seq_pattern_variations_open_key = style_key
      state.seq_pattern_variations_request_open = true
    end
  end

  r.ImGui_SetCursorScreenPos(ctx, x0, y1)
  r.ImGui_Dummy(ctx, 0, 5.0)
end

function render_seq_pattern_popup(region)
  if not state.seq_pattern_window_open then
    return
  end
  seq_position_pattern_popup()

  local win_flags = 0
  local function add_flag(getter)
    if getter then win_flags = win_flags | getter() end
  end
  add_flag(r.ImGui_WindowFlags_NoTitleBar)
  add_flag(r.ImGui_WindowFlags_NoCollapse)
  add_flag(r.ImGui_WindowFlags_NoDocking)
  add_flag(r.ImGui_WindowFlags_NoScrollbar)
  add_flag(r.ImGui_WindowFlags_NoScrollWithMouse)

  local visible, keep_open = r.ImGui_Begin(ctx, "Pattern Presets##seq_pattern_window", true, win_flags)
  if keep_open == false then
    state.seq_pattern_window_open = false
  end
  if visible then
    state.seq_gen_style = normalize_seq_gen_style(state.seq_gen_style)
    local can_generate = region and seq_preset_can_generate(state.seq_gen_style)

    local region_name = get_seq_region_display_name(region)
    r.ImGui_TextColored(ctx, UI_THEME.text, "Pattern Presets")
    r.ImGui_SameLine(ctx)
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, "· " .. region_name)
    r.ImGui_SameLine(ctx)
    local avail_close = r.ImGui_GetContentRegionAvail(ctx)
    r.ImGui_SetCursorPosX(ctx, r.ImGui_GetCursorPosX(ctx) + math.max(0.0, avail_close - 22.0))
    if draw_ui_button("seq_pattern_window_close", nil, 18.0, 18.0, { icon = "close", compact = true, style = "default" }) then
      state.seq_pattern_window_open = false
    end
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, "Applies to " .. region_name .. ". Click to generate. Hover for dice: 1 is subtle, 6 is unruly.")
    if not can_generate and state.seq_pattern_source ~= "gmd" then
      r.ImGui_TextColored(ctx, 0xFFB870FF, "No matching samples found for this preset's types.")
    end

    -- AI variation: a local model re-imagines the current pattern. The dice
    -- (1..6) set how far it strays from what's currently on the grid.
    r.ImGui_TextColored(ctx, 0x9FE3B5FF, "AI Variation")
    r.ImGui_SameLine(ctx)
    local ai_dice = 18.0
    local ai_gap = 3.0
    for strength = 1, 6 do
      if strength > 1 then r.ImGui_SameLine(ctx, 0, ai_gap) end
      local clicked_ai = draw_ui_button(
        "seq_ai_dice_" .. tostring(strength),
        nil, ai_dice, ai_dice,
        { icon = "dice" .. tostring(strength), compact = true, style = "success" }
      )
      if clicked_ai and can_generate then
        run_seq_ai_variation(region, state.seq_gen_style, strength / 6.0)
      end
    end
    if not seq_drum_ai_available() then
      r.ImGui_TextColored(ctx, 0xFFB870FF, "AI model script not found; dice will fall back to built-in randomizer.")
    end

    r.ImGui_Separator(ctx)

    -- Search + Groove MIDI filters share one toolbar above the unified list.
    r.ImGui_SetNextItemWidth(ctx, -1)
    local search_changed, search_val
    if r.ImGui_InputTextWithHint then
      search_changed, search_val = r.ImGui_InputTextWithHint(
        ctx, "##seq_pattern_search", "Search patterns...", state.seq_pattern_search or ""
      )
    else
      search_changed, search_val = r.ImGui_InputText(ctx, "##seq_pattern_search", state.seq_pattern_search or "", 256)
    end
    seq_mark_text_input_item()
    if search_changed then
      state.seq_pattern_search = search_val or ""
    end
    render_seq_gmd_toolbar()

    r.ImGui_Separator(ctx)

    local list_flags = 0
    if r.ImGui_WindowFlags_NoBackground then
      list_flags = r.ImGui_WindowFlags_NoBackground()
    end
    if r.ImGui_BeginChild(ctx, "seq_pattern_preset_list", 0, 0, 0, list_flags) then
      local entries = seq_pattern_browser_entries()
      if #entries == 0 then
        r.ImGui_TextColored(ctx, 0xFFB870FF, "No patterns match your search.")
      else
        for _, entry in ipairs(entries) do
          if entry.kind == "gmd" then
            render_seq_gmd_preset_row(region, entry.group, entry.template)
          elseif entry.style_def then
            render_seq_pattern_preset_row(region, entry.style_def)
          end
        end
      end
      r.ImGui_EndChild(ctx)
    end

    -- Generated-variation history popup only (Groove MIDI uses inline collapse).
    if state.seq_pattern_variations_request_open then
      state.seq_pattern_variations_request_open = false
      local open_key = state.seq_pattern_variations_open_key
      if not (type(open_key) == "string" and open_key:sub(1, 4) == "gmd:") then
        r.ImGui_OpenPopup(ctx, "seq_pattern_variations_popup")
      end
    end
    render_seq_pattern_variations_popup(region)
  end

  r.ImGui_End(ctx)
end

function render_seq_pattern_variation_row(region, style_key, entry)
  local row_w = math.max(1.0, r.ImGui_GetContentRegionAvail(ctx))
  local row_h = 30.0
  r.ImGui_InvisibleButton(ctx, "##seq_var_" .. tostring(entry.id), row_w, row_h)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  row_w = x1 - x0
  local hovered = r.ImGui_IsItemHovered(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local cy = (y0 + y1) * 0.5

  if hovered then
    r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, 0x174A24AA, 4.0)
    r.ImGui_DrawList_AddRect(dl, x0, y0, x1, y1, UI_THEME.accent, 4.0, 0, 1.0)
  end

  local x = x0 + 6.0
  local base_name = get_seq_gen_style_label(style_key)
  local _, name_h = r.ImGui_CalcTextSize(ctx, base_name)
  r.ImGui_DrawList_AddText(dl, x, cy - name_h * 0.5, UI_THEME.text, base_name)
  x = x + select(1, r.ImGui_CalcTextSize(ctx, base_name)) + 8.0

  local num_text = "#" .. tostring(entry.id)
  local pill_w = draw_ui_pill_label(dl, x, cy, num_text, {
    bg = UI_THEME.accent_fill,
    border = UI_THEME.accent,
    text_col = 0xF0F8FFFF,
    pad_x = 7.0,
    pad_y = 2.0,
    rounding = 6.0,
  })
  x = x + pill_w + 6.0

  if entry.ai then
    draw_ui_pill_label(dl, x, cy, "AI", {
      bg = 0x243A2EFF,
      border = 0x66CC88FF,
      text_col = 0xCFF5DDFF,
      pad_x = 7.0,
      pad_y = 2.0,
      rounding = 5.0,
    })
    local pct = math.floor((entry.ai_variation or 0.5) * 100.0 + 0.5)
    x = x + select(1, r.ImGui_CalcTextSize(ctx, "AI")) + 14.0 + 6.0
    draw_ui_pill_label(dl, x, cy, pct .. "%", {
      bg = UI_THEME.surface,
      border = UI_THEME.border,
      text_col = UI_THEME.text_dim,
      pad_x = 6.0,
      pad_y = 2.0,
      rounding = 5.0,
    })
  else
    local dice_text = "dice " .. tostring(entry.strength or 1)
    draw_ui_pill_label(dl, x, cy, dice_text, {
      bg = UI_THEME.surface,
      border = UI_THEME.border,
      text_col = UI_THEME.text_dim,
      pad_x = 6.0,
      pad_y = 2.0,
      rounding = 5.0,
    })
  end

  if clicked then
    seq_apply_pattern_variation(region, style_key, entry)
    r.ImGui_CloseCurrentPopup(ctx)
  end
end

function render_seq_gmd_pattern_row(region, child, parent_id_safe)
  if type(child) ~= "table" or type(child.item) ~= "table" then return end
  local item = child.item
  local indent = 16.0
  local avail = r.ImGui_GetContentRegionAvail(ctx)
  local row_w = math.max(1.0, avail - indent)
  local row_h = 30.0
  local left_pad = 8.0
  local right_pad = 6.0
  local id = tostring(item.id or child.index or "")
  local id_safe = tostring(parent_id_safe or "gmd") .. "_pat_" .. id:gsub("[^%w]", "_")
  local btn_size = 18.0
  local btn_gap = 2.0
  local selected = tostring(state.seq_gmd_selected_id or "") == id

  local x_base, y_base = r.ImGui_GetCursorScreenPos(ctx)
  r.ImGui_SetCursorScreenPos(ctx, x_base + indent, y_base)

  local x0, y0 = r.ImGui_GetCursorScreenPos(ctx)
  local x1, y1 = x0 + row_w, y0 + row_h
  local mx, my = r.ImGui_GetMousePos(ctx)
  local hovered = mx >= x0 and mx <= x1 and my >= y0 and my <= y1

  local right_edge = x0 + row_w - right_pad
  local dice_size = btn_size
  local dice_total_w = dice_size * 6.0 + btn_gap * 5.0
  if hovered and dice_total_w > (right_edge - x0 - 60.0) then
    dice_size = math.max(12.0, math.floor((right_edge - x0 - 60.0 - btn_gap * 5.0) / 6.0))
    dice_total_w = dice_size * 6.0 + btn_gap * 5.0
  end
  local dice_x = right_edge - dice_total_w
  local interactive_left = hovered and dice_x or right_edge
  local row_button_w = math.max(40.0, interactive_left - x0 - 4.0)

  r.ImGui_InvisibleButton(ctx, "##seq_gmd_pat_" .. id_safe, row_button_w, row_h)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local dl = r.ImGui_GetWindowDrawList(ctx)

  local fill = selected and UI_THEME.accent_fill or UI_THEME.bg_panel
  local edge = selected and UI_THEME.accent or UI_THEME.border
  if hovered then
    fill = selected and UI_THEME.accent_fill_h or UI_THEME.surface_hvr
    edge = UI_THEME.accent_hvr
  end
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, fill, 4.0)
  r.ImGui_DrawList_AddRect(dl, x0, y0, x1, y1, edge, 4.0, 0, 1.0)

  local label_right = hovered and dice_x or right_edge
  local label_max_w = math.max(20.0, label_right - x0 - left_pad - 6.0)
  local label_text = seq_truncate_text_to_width(child.label or "Groove", label_max_w)
  r.ImGui_DrawList_AddText(dl, x0 + left_pad, y0 + 7.0, selected and 0xFFFFFFFF or UI_THEME.text, label_text)

  if not hovered then
    local bpm = tonumber(item.bpm)
    if bpm then
      local bpm_text = tostring(bpm) .. " BPM"
      local label_w = select(1, r.ImGui_CalcTextSize(ctx, label_text))
      local meta_right = label_right
      local meta_max_w = math.max(20.0, meta_right - (x0 + left_pad + label_w) - 10.0)
      bpm_text = seq_truncate_text_to_width(bpm_text, meta_max_w)
      local meta_w = select(1, r.ImGui_CalcTextSize(ctx, bpm_text))
      r.ImGui_DrawList_AddText(dl, meta_right - meta_w, y0 + 8.0, 0x8AA6C8FF, bpm_text)
    end
  end

  if clicked and region then
    run_seq_gmd_load_id(region, id)
  end

  if hovered then
    seq_pattern_draw_hover_dice(
      region,
      "seq_gmd_pat_dice_" .. id_safe,
      dice_x,
      y0 + (row_h - dice_size) * 0.5,
      dice_size,
      btn_gap,
      function(_strength)
        run_seq_gmd_load_id(region, id)
      end
    )
  end

  r.ImGui_SetCursorScreenPos(ctx, x_base, y1)
  r.ImGui_Dummy(ctx, 0, 2.0)
end

-- Popup for code-generated / AI variation history only (not Groove MIDI).
function render_seq_pattern_variations_popup(region)
  local style_key = state.seq_pattern_variations_open_key
  if type(style_key) == "string" and style_key:sub(1, 4) == "gmd:" then
    return
  end
  if r.ImGui_SetNextWindowSizeConstraints then
    r.ImGui_SetNextWindowSizeConstraints(ctx, 280.0, 80.0, 280.0, 520.0)
  end
  if not r.ImGui_BeginPopup(ctx, "seq_pattern_variations_popup") then
    return
  end

  r.ImGui_TextColored(ctx, UI_THEME.text, "Generated Variations")
  local store = style_key and state.seq_pattern_variations and state.seq_pattern_variations[style_key]
  if style_key then
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, get_seq_gen_style_label(style_key))
  end
  r.ImGui_Separator(ctx)

  if not store or #store.entries == 0 then
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, "No variations yet. Roll a dice to add some.")
  else
    for i = #store.entries, 1, -1 do
      render_seq_pattern_variation_row(region, style_key, store.entries[i])
    end
    r.ImGui_Separator(ctx)
    if draw_ui_button("seq_var_clear", "Clear list", nil, nil, { compact = true, style = "danger" }) then
      store.entries = {}
      r.ImGui_CloseCurrentPopup(ctx)
    end
  end

  r.ImGui_EndPopup(ctx)
end

function render_seq_groove_popup()
  if r.ImGui_SetNextWindowSizeConstraints then
    r.ImGui_SetNextWindowSizeConstraints(ctx, 280.0, 80.0, 340.0, 620.0)
  end
  if not r.ImGui_BeginPopup(ctx, "seq_groove_popup") then
    return
  end

  local region = get_selected_seq_region()
  local region_name = get_seq_region_display_name(region)
  r.ImGui_TextColored(ctx, UI_THEME.text, "Groove")
  r.ImGui_SameLine(ctx)
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "· " .. region_name)
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "Timing feel for this region only.")
  r.ImGui_Separator(ctx)

  local current = get_seq_region_groove(region)
  for _, entry in ipairs(SEQ_GROOVE_ORDER) do
    if entry.header then
      r.ImGui_Dummy(ctx, 0, 2)
      r.ImGui_TextColored(ctx, UI_THEME.text_dim, entry.header)
    elseif entry.key then
      local selected = (entry.key == current)
      if r.ImGui_Selectable(ctx, entry.label .. "##seq_groove_" .. entry.key, selected) then
        set_seq_region_groove(region, entry.key)
        r.ImGui_CloseCurrentPopup(ctx)
      end
      if entry.desc and r.ImGui_IsItemHovered(ctx) and r.ImGui_SetTooltip then
        r.ImGui_SetTooltip(ctx, entry.desc)
      end
    end
  end

  r.ImGui_EndPopup(ctx)
end

function render_seq_kit_random_genre_chips(tags, id_prefix, priority_set)
  local wrap_w = r.ImGui_GetContentRegionAvail(ctx)
  local row_w = 0.0
  local gap = 6.0
  local first = true
  local shown = 0

  for idx, tag in ipairs(tags) do
    local tw = select(1, r.ImGui_CalcTextSize(ctx, tag)) + 16.0
    if not first then
      if row_w + gap + tw > wrap_w then
        row_w = 0.0
      else
        r.ImGui_SameLine(ctx, 0, gap)
        row_w = row_w + gap
      end
    end
    first = false
    shown = shown + 1
    local used_in_project = priority_set and priority_set[tag:lower()] == true
    if draw_tag_button(ctx, tag, false, tag, id_prefix .. tostring(idx) .. "_") then
      randomize_seq_kit({ tag }, { exact_tag = true })
    end
    if used_in_project then
      local dl = r.ImGui_GetWindowDrawList(ctx)
      local x0, y0 = r.ImGui_GetItemRectMin(ctx)
      local x1, y1 = r.ImGui_GetItemRectMax(ctx)
      local rounding = (y1 - y0) * 0.5
      r.ImGui_DrawList_AddRect(dl, x0 - 0.5, y0 - 0.5, x1 + 0.5, y1 + 0.5, 0xFFB870AA, rounding + 0.5, 0, 1.35)
    end
    if r.ImGui_IsItemHovered(ctx) and r.ImGui_SetTooltip then
      local tip = "Randomize kit using \"" .. tag .. "\" samples (roles preserved)"
      if used_in_project then
        tip = "Used in this project\n" .. tip
      end
      r.ImGui_SetTooltip(ctx, tip)
    end
    row_w = row_w + tw
  end
  return shown
end

function render_seq_kit_history_element_chip(kit_id, elem_idx, element)
  local role_label = SEQ_ROLE_LABELS[element.role] or tostring(element.role or "?")
  local tag = element.sample_tag or element.role or role_label
  local text_w = select(1, r.ImGui_CalcTextSize(ctx, role_label))
  local pad_x, pad_y = 6.0, 2.0
  local button_w = text_w + pad_x * 2.0
  local button_h = select(2, r.ImGui_CalcTextSize(ctx, role_label)) + pad_y * 2.0

  local active = false
  local slot = find_seq_track_for_kit_element(element)
  if slot and slot.sample_path and element.sample_path and slot.sample_path == element.sample_path then
    active = true
  end

  local tag_color = state.tag_colors[tag] or state.tag_colors[element.role] or 0x336699
  local base_r, base_g, base_b = extract_rgb(tag_color)
  local factor = active and 0.75 or 0.45
  local bg = build_color_rrgbbaa(
    math.floor(base_r * factor),
    math.floor(base_g * factor),
    math.floor(base_b * factor),
    255
  )
  local border = build_color_rrgbbaa(
    math.floor(base_r * factor * (active and 0.7 or 1.2)),
    math.floor(base_g * factor * (active and 0.7 or 1.2)),
    math.floor(base_b * factor * (active and 0.7 or 1.2)),
    255
  )
  local text_col = active and 0xFFFFFFFF or 0xFFCCCCCC

  local id = string.format("##seq_kit_el_%s_%s", tostring(kit_id), tostring(elem_idx))
  r.ImGui_InvisibleButton(ctx, id, button_w, button_h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local dbl = hovered and r.ImGui_IsMouseDoubleClicked(ctx, 0)

  local pressed = r.ImGui_IsItemActive(ctx)
  if hovered and not active then
    factor = 0.58
    text_col = 0xF4F4F4FF
  end
  bg = build_color_rrgbbaa(
    math.floor(base_r * factor),
    math.floor(base_g * factor),
    math.floor(base_b * factor),
    active and 255 or 200
  )
  border = build_color_rrgbbaa(
    math.min(255, math.floor(base_r * (active and 0.95 or 0.70))),
    math.min(255, math.floor(base_g * (active and 0.95 or 0.70))),
    math.min(255, math.floor(base_b * (active and 0.95 or 0.70))),
    hovered and 220 or 140
  )

  local dl = r.ImGui_GetWindowDrawList(ctx)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  ui_draw_panel(dl, x0, y0, x1, y1, button_h * 0.5, bg, border, hovered, pressed)
  local tw, th = r.ImGui_CalcTextSize(ctx, role_label)
  r.ImGui_DrawList_AddText(dl, x0 + (button_w - tw) * 0.5, y0 + (button_h - th) * 0.5 + (pressed and 1.0 or 0.0), text_col, role_label)

  if clicked then
    if dbl then
      apply_seq_kit_history_element(element)
    else
      preview_seq_kit_history_element(element)
    end
  end
  if hovered and r.ImGui_SetTooltip then
    local name = element.sample_name or basename(element.sample_path or "") or "sample"
    r.ImGui_SetTooltip(ctx, name .. "\nClick: preview  ·  Double-click: replace this drum")
  end

  return button_w
end

function render_seq_kit_history_entry(entry)
  if not entry or type(entry.elements) ~= "table" then
    return
  end
  local title = string.format("#%d  %s", entry.id or 0, entry.label or "Kit")
  if entry.is_original then
    title = title .. "  · original"
  end
  local count_label = string.format("(%d)", #entry.elements)
  local current_sig = seq_kit_signature(collect_seq_kit_elements())
  local is_active = current_sig ~= "" and current_sig == seq_kit_signature(entry.elements)
  local title_w = select(1, r.ImGui_CalcTextSize(ctx, title)) + 8.0
  local title_h = select(2, r.ImGui_CalcTextSize(ctx, title)) + 4.0
  r.ImGui_InvisibleButton(ctx, "##seq_kit_title_" .. tostring(entry.id or 0), title_w, title_h)
  local title_hovered = r.ImGui_IsItemHovered(ctx)
  local title_clicked = r.ImGui_IsItemClicked(ctx, 0)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local tx0, ty0 = r.ImGui_GetItemRectMin(ctx)
  local title_col = is_active and 0xFFB870FF or (title_hovered and 0xFFFFFFFF or UI_THEME.text)
  r.ImGui_DrawList_AddText(dl, tx0 + 2.0, ty0 + 2.0, title_col, title)
  if title_clicked then
    apply_seq_kit_history_entry(entry)
  end
  if title_hovered and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, "Click to replace the whole kit with this one")
  end
  r.ImGui_SameLine(ctx, 0, 6.0)
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, count_label)

  local wrap_w = r.ImGui_GetContentRegionAvail(ctx)
  local row_w = 0.0
  local gap = 4.0
  local first = true
  for idx, element in ipairs(entry.elements) do
    local role_label = SEQ_ROLE_LABELS[element.role] or tostring(element.role or "?")
    local tw = select(1, r.ImGui_CalcTextSize(ctx, role_label)) + 12.0
    if not first then
      if row_w + gap + tw > wrap_w then
        row_w = 0.0
      else
        r.ImGui_SameLine(ctx, 0, gap)
        row_w = row_w + gap
      end
    end
    first = false
    local drawn_w = render_seq_kit_history_element_chip(entry.id or idx, idx, element)
    row_w = row_w + (drawn_w or tw)
  end
  r.ImGui_Dummy(ctx, 0, 4)
end

function render_seq_kit_history_list()
  state.seq_kit_history = state.seq_kit_history or {}
  r.ImGui_TextColored(ctx, 0xFFB870FF, "Past kits")
  if r.ImGui_IsItemHovered(ctx) and r.ImGui_SetTooltip then
    r.ImGui_SetTooltip(ctx, "Title: apply kit · Chip: preview / double-click replace")
  end
  r.ImGui_Dummy(ctx, 0, 2)

  if #state.seq_kit_history == 0 then
    r.ImGui_TextColored(ctx, 0xFF888888, "No randomized kits yet")
    return
  end

  for _, entry in ipairs(state.seq_kit_history) do
    render_seq_kit_history_entry(entry)
    r.ImGui_Separator(ctx)
  end
  if draw_ui_button("seq_kit_hist_clear", "Clear kit history", nil, nil, { compact = true, style = "danger" }) then
    state.seq_kit_history = {}
    save_config()
  end
end

function render_seq_kit_random_popup()
  if r.ImGui_SetNextWindowSize then
    local cond = r.ImGui_Cond_Appearing and r.ImGui_Cond_Appearing() or 0
    r.ImGui_SetNextWindowSize(ctx, 720.0, 460.0, cond)
  end
  if r.ImGui_SetNextWindowSizeConstraints then
    r.ImGui_SetNextWindowSizeConstraints(ctx, 560.0, 340.0, 980.0, 820.0)
  end
  if not r.ImGui_BeginPopup(ctx, "seq_kit_random_popup") then
    return
  end

  if (not state.tag_list or #state.tag_list == 0) and #state.samples > 0 then
    rebuild_tag_index()
  end

  r.ImGui_TextColored(ctx, UI_THEME.text, "Randomize Kit")
  r.ImGui_Separator(ctx)

  r.ImGui_SetNextItemWidth(ctx, -1)
  local changed, query
  if r.ImGui_InputTextWithHint then
    changed, query = r.ImGui_InputTextWithHint(ctx, "##seq_kit_random_query", "Custom keyword", state.seq_kit_random_query or "")
  else
    changed, query = r.ImGui_InputText(ctx, "##seq_kit_random_query", state.seq_kit_random_query or "", 128)
  end
  seq_mark_text_input_item()
  if changed then
    state.seq_kit_random_query = query
  end
  local trimmed = seq_trim_text(state.seq_kit_random_query)
  local randomize_label = (trimmed ~= "") and ('Randomize with "' .. trimmed .. '"') or "Randomize (any genre)"
  if draw_ui_button("seq_kit_random_run", randomize_label, nil, nil, { full_width = true, style = "primary" }) then
    if trimmed ~= "" then
      randomize_seq_kit({ trimmed }, { exact_tag = false })
    else
      randomize_seq_kit(nil, { exact_tag = false })
    end
  end

  r.ImGui_Separator(ctx)

  local library_genres = collect_library_genre_tags()
  local priority = collect_project_kit_genre_priority()
  local priority_set = {}
  for _, tag in ipairs(priority) do
    priority_set[tag:lower()] = true
  end

  local query_lower = trimmed:lower()
  local function genre_matches_query(tag)
    if query_lower == "" then
      return true
    end
    return tag:lower():find(query_lower, 1, true) ~= nil
  end

  local library_set = {}
  for _, entry in ipairs(library_genres) do
    library_set[entry.tag:lower()] = entry.tag
  end

  local all_shown = {}
  local shown_set = {}
  for _, tag in ipairs(priority) do
    local lib_tag = library_set[tag:lower()]
    if lib_tag and genre_matches_query(lib_tag) and not shown_set[lib_tag:lower()] then
      all_shown[#all_shown + 1] = lib_tag
      shown_set[lib_tag:lower()] = true
    end
  end
  for _, entry in ipairs(library_genres) do
    local tag = entry.tag
    if genre_matches_query(tag) and not shown_set[tag:lower()] then
      all_shown[#all_shown + 1] = tag
      shown_set[tag:lower()] = true
    end
  end

  local avail_w, avail_h = r.ImGui_GetContentRegionAvail(ctx)
  local gap = 12.0
  local right_w = math.max(210.0, math.min(260.0, avail_w * 0.38))
  local left_w = math.max(180.0, avail_w - right_w - gap)
  local col_h = math.max(180.0, avail_h)
  local child_win_flags = r.ImGui_WindowFlags_None and r.ImGui_WindowFlags_None() or 0

  if r.ImGui_BeginChild(ctx, "seq_kit_random_tags", left_w, col_h, 0, child_win_flags) then
    if #all_shown == 0 then
      r.ImGui_TextColored(ctx, 0xFF888888, "No genres match filter")
    else
      render_seq_kit_random_genre_chips(all_shown, "seq_kit_lib_", priority_set)
    end
    r.ImGui_EndChild(ctx)
  end
  r.ImGui_SameLine(ctx, 0, gap)
  if r.ImGui_BeginChild(ctx, "seq_kit_history_list", right_w, col_h, 1, child_win_flags) then
    render_seq_kit_history_list()
    r.ImGui_EndChild(ctx)
  end

  r.ImGui_EndPopup(ctx)
end

function seq_anim_clamp01(v)
  if v <= 0.0 then return 0.0 end
  if v >= 1.0 then return 1.0 end
  return v
end

function seq_note_anim_cell_key(region_id, track_id, step_key)
  return tostring(region_id or 0) .. ":" .. tostring(track_id or 0) .. ":" .. tostring(step_key or 0)
end

function seq_snapshot_note_for_anim(note)
  if type(note) ~= "table" then
    return nil
  end
  return {
    enabled = note.enabled ~= false,
    step = note.step,
    qn_offset = note.qn_offset or 0.0,
    sample_path = note.sample_path,
    sample_name = note.sample_name,
    volume = note.volume,
    pan = note.pan,
    pitch = note.pitch,
    length_qn = note.length_qn,
    decay_qn = note.decay_qn,
    fade_in_qn = note.fade_in_qn,
    fade_out_qn = note.fade_out_qn,
    fade_in_shape = note.fade_in_shape,
    fade_out_shape = note.fade_out_shape,
    fade_in_curve = note.fade_in_curve,
    fade_out_curve = note.fade_out_curve,
    offset_qn = note.offset_qn,
    stretch = note.stretch,
    start = note.start,
    sample_vary = note.sample_vary,
    vary_filter = note.vary_filter,
    frozen_sample_path = note.frozen_sample_path,
    frozen_sample_name = note.frozen_sample_name,
    vary_origin_path = note.vary_origin_path,
    vary_rgb = note.vary_rgb,
    picked_sample = note.picked_sample,
    stutter = note.stutter,
    stutter_skew = note.stutter_skew,
    stutter_hits = clone_table_deep(note.stutter_hits),
    locked = note.locked,
    locked_skip = note.locked_skip,
    locked_vel = note.locked_vel,
    locked_humanize_sec = note.locked_humanize_sec,
    locked_humanize_pitch = note.locked_humanize_pitch,
    locked_humanize_stretch = note.locked_humanize_stretch,
    locked_humanize_len = note.locked_humanize_len,
    locked_humanize_fade = note.locked_humanize_fade,
    locked_ghosts = clone_table_deep(note.locked_ghosts),
  }
end

function register_seq_note_anim(region_id, track_id, step_key, note, kind)
  if not region_id or not track_id or step_key == nil
     or (kind ~= "add" and kind ~= "delete" and kind ~= "sync") then
    return
  end
  state.seq_note_anims = state.seq_note_anims or {}
  local duration = 0.20
  if kind == "sync" then
    duration = 0.45
  elseif kind == "delete" then
    duration = 0.18
  end
  state.seq_note_anims[seq_note_anim_cell_key(region_id, track_id, step_key)] = {
    kind = kind,
    region_id = region_id,
    track_id = track_id,
    step_key = tostring(step_key),
    note = seq_snapshot_note_for_anim(note),
    start_time = r.time_precise(),
    duration = duration,
  }
end

function prune_seq_note_anims(now)
  local anims = state.seq_note_anims
  if not anims then
    return
  end
  for key, anim in pairs(anims) do
    local start_t = anim.start_time or 0.0
    local dur = anim.duration or 0.2
    if (now - start_t) >= dur then
      anims[key] = nil
    end
  end
end

function seq_note_anim_progress(anim, now)
  if not anim then
    return 1.0
  end
  local dur = anim.duration or 0.2
  if dur <= 0 then
    return 1.0
  end
  return seq_anim_clamp01((now - (anim.start_time or now)) / dur)
end

function get_seq_note_anim(region_id, track_id, step_key, now)
  local anims = state.seq_note_anims
  if not anims then
    return nil
  end
  local key = seq_note_anim_cell_key(region_id, track_id, step_key)
  local anim = anims[key]
  if not anim then
    return nil
  end
  local t = seq_note_anim_progress(anim, now)
  if t >= 1.0 then
    anims[key] = nil
    return nil
  end
  anim.t = t
  return anim
end

function scale_rect_about_center(x0, y0, x1, y1, scale_x, scale_y, offset_y)
  local cx = (x0 + x1) * 0.5
  local cy = (y0 + y1) * 0.5 + (offset_y or 0.0)
  local hw = math.max(0.25, (x1 - x0) * 0.5 * (scale_x or 1.0))
  local hh = math.max(0.25, (y1 - y0) * 0.5 * (scale_y or 1.0))
  return cx - hw, cy - hh, cx + hw, cy + hh
end

-- Insert grows in with a mid-pop.
function seq_note_anim_pop_scale(kind, t)
  t = seq_anim_clamp01(t or 0.0)
  local pulse = math.sin(t * math.pi)
  return 0.78 + t * 0.22 + pulse * 0.12, 0.66 + t * 0.34 + pulse * 0.18
end

function seq_note_anim_pop_alphas(kind, t, cell_selected)
  t = seq_anim_clamp01(t or 0.0)
  local note_alpha = math.floor((cell_selected and (120 + t * 115) or (34 + t * 36)))
  local border_alpha = math.floor((cell_selected and (90 + t * 150) or (24 + t * 28)))
  return note_alpha, border_alpha
end

function seq_ease_out_cubic(t)
  t = 1.0 - seq_anim_clamp01(t)
  return 1.0 - t * t * t
end

function seq_ease_in_cubic(t)
  t = seq_anim_clamp01(t)
  return t * t * t
end

function seq_ease_out_quart(t)
  t = 1.0 - seq_anim_clamp01(t)
  return 1.0 - t * t * t * t
end

function seq_anim_lerp(a, b, t)
  return a + (b - a) * t
end

function seq_anim_mix_rgb(r0, g0, b0, r1, g1, b1, t)
  return seq_anim_lerp(r0, r1, t), seq_anim_lerp(g0, g1, t), seq_anim_lerp(b0, b1, t)
end

-- Flash, crush into a streak, then a colored burst. Seeded so sparks stay stable.
function draw_seq_note_delete_fx(dl, x0, y0, x1, y1, t, br, bg, bb, seed)
  t = seq_anim_clamp01(t or 0.0)
  local w = math.max(4.0, x1 - x0)
  local h = math.max(4.0, y1 - y0)
  local cx = (x0 + x1) * 0.5
  local cy = (y0 + y1) * 0.5
  seed = seed or 0

  local flash = 1.0 - seq_anim_clamp01(t / 0.20)
  local crush = seq_ease_in_cubic(seq_anim_clamp01((t - 0.05) / 0.58))
  local burst = seq_ease_out_cubic(seq_anim_clamp01((t - 0.08) / 0.92))
  local body_a = math.floor(235 * (1.0 - seq_ease_in_cubic(seq_anim_clamp01(t / 0.68))))

  local scale_x, scale_y
  if t < 0.14 then
    local punch = seq_ease_out_cubic(t / 0.14)
    scale_x = seq_anim_lerp(1.0, 1.08, punch)
    scale_y = seq_anim_lerp(1.0, 1.14, punch)
  else
    scale_x = seq_anim_lerp(1.08, 0.42, crush)
    scale_y = seq_anim_lerp(1.14, 0.06, crush)
  end
  local bx0, by0, bx1, by1 = scale_rect_about_center(x0, y0, x1, y1, scale_x, scale_y, 0.0)
  local fr, fg, fb = seq_anim_mix_rgb(br, bg, bb, 255, 255, 255, flash * 0.82)

  if body_a > 4 then
    r.ImGui_DrawList_AddRectFilled(dl, bx0, by0, bx1, by1, build_color_rrgbbaa(fr, fg, fb, body_a), 2.5)
    r.ImGui_DrawList_AddRect(dl, bx0, by0, bx1, by1, build_color_rrgbbaa(255, 255, 255, math.floor(body_a * 0.78)), 2.5, 0, 1.3)
  end

  local streak_in = seq_anim_clamp01(t / 0.08)
  local streak_out = 1.0 - seq_anim_clamp01((t - 0.10) / 0.52)
  local streak_a = math.floor(230 * streak_in * streak_out)
  if streak_a > 0 then
    local sw = w * seq_anim_lerp(0.42, 1.55, burst)
    local sh = seq_anim_lerp(2.6, 0.55, burst)
    r.ImGui_DrawList_AddRectFilled(
      dl, cx - sw * 0.5, cy - sh, cx + sw * 0.5, cy + sh,
      build_color_rrgbbaa(255, 255, 255, streak_a), 1.2
    )
    r.ImGui_DrawList_AddRectFilled(
      dl, cx - sw * 0.28, cy - sh * 0.45, cx + sw * 0.28, cy + sh * 0.45,
      build_color_rrgbbaa(br, bg, bb, math.floor(streak_a * 0.55)), 1.0
    )
  end

  local ring_t = seq_ease_out_cubic(seq_anim_clamp01((t - 0.03) / 0.80))
  local ring_a = math.floor(170 * ((1.0 - ring_t) ^ 0.65) * seq_anim_clamp01(t / 0.07))
  if ring_a > 0 then
    local pad = 1.5 + ring_t * math.max(7.0, math.min(14.0, w * 0.22))
    r.ImGui_DrawList_AddRect(
      dl, x0 - pad, y0 - pad * 0.65, x1 + pad, y1 + pad * 0.65,
      build_color_rrgbbaa(255, 255, 255, ring_a), 3.5, 0, 1.5
    )
    r.ImGui_DrawList_AddRect(
      dl, x0 - pad * 0.45, y0 - pad * 0.30, x1 + pad * 0.45, y1 + pad * 0.30,
      build_color_rrgbbaa(br, bg, bb, math.floor(ring_a * 0.6)), 3.0, 0, 1.1
    )
  end

  local spark_t = seq_ease_out_quart(seq_anim_clamp01((t - 0.07) / 0.93))
  local spark_a = math.floor(235 * (1.0 - seq_anim_clamp01((t - 0.18) / 0.72)))
  if spark_a > 8 and spark_t > 0 then
    local reach = 7.0 + h * 0.55 + w * 0.16
    for i = 1, 6 do
      local jitter = ((seed + i * 19) % 23) * 0.045
      local ang = (i - 1) * (math.pi * 2.0 / 6.0) + jitter
      local dist = reach * spark_t * (0.72 + ((seed + i * 7) % 10) * 0.03)
      local sx = cx + math.cos(ang) * dist
      local sy = cy + math.sin(ang) * dist * 0.70
      local rad = seq_anim_lerp(2.6, 0.35, spark_t)
      local hot = (i % 2 == 0) and 0.70 or 0.38
      local sr, sg, sb = seq_anim_mix_rgb(br, bg, bb, 255, 255, 255, hot)
      r.ImGui_DrawList_AddCircleFilled(dl, sx, sy, rad, build_color_rrgbbaa(sr, sg, sb, spark_a), 8)
    end
  end
end

-- Deleted notes leave active_cells immediately and use QN storage keys, so
-- ghosts are drawn from the anim snapshot rather than the live grid.
function seq_draw_lane_delete_anims(dl, slot, row_y0, row_y1, now_t, step_qn, qn_to_x, timeline_x0, timeline_x1, selected_region_id)
  local anims = state.seq_note_anims
  if not anims or not slot or not qn_to_x then
    return
  end
  local slot_key = tostring(slot.id)
  for _, anim in pairs(anims) do
    if anim.kind == "delete" and anim.note and tostring(anim.track_id) == slot_key then
      local t = seq_note_anim_progress(anim, now_t)
      if t < 1.0 then
        local region = get_seq_region_by_id(anim.region_id)
        if region then
          local note = anim.note
          local step_key = anim.step_key
          local resolved_path, resolved_sample = seq_resolve_note_sample(note, slot, nil, region, slot.id, step_key)
          local origin_path = seq_note_vary_origin_path(note, slot, region)
          local origin_sample = find_sample_by_path(origin_path)
          local base = get_sample_dot_color(origin_sample or resolved_sample or find_sample_by_path(resolved_path or origin_path or note.sample_path or slot.sample_path))
          local pattern = get_seq_pattern(region.pattern_id, false)
          local note_qn = seq_note_abs_qn(region, note, step_key, step_qn)
          local note_len = seq_note_draw_length_qn(
            region, pattern, slot, slot.id, step_key, note, resolved_sample, step_qn
          )
          local note_off = note.offset_qn or 0.0
          local draw_x0 = qn_to_x(note_qn + note_off) + 2
          local draw_x1 = math.max(draw_x0 + 6.0, qn_to_x(note_qn + note_off + note_len) - 2)
          -- Size the FX to the solid head only, not the faint sustain tail.
          if not seq_note_has_stutter_span(note, step_qn) then
            local head_x1 = seq_note_head_end_x(qn_to_x, note_qn, note, step_qn)
            if head_x1 and draw_x1 > head_x1 + 1.0 then
              draw_x1 = math.max(draw_x0 + 6.0, head_x1)
            end
          end
          if draw_x1 >= (timeline_x0 or draw_x0) - 12.0 and draw_x0 <= (timeline_x1 or draw_x1) + 12.0 then
            local row_pad = 4.0
            local br, bg, bb = extract_rgb_rrgbbaa(base)
            if resolved_path and origin_path and resolved_path ~= origin_path then
              local vr, vg, vb = seq_note_vary_rgb(note, resolved_path)
              if vr then
                br, bg, bb = math.floor((br + vr) * 0.5), math.floor((bg + vg) * 0.5), math.floor((bb + vb) * 0.5)
              end
            end
            local seed = (tonumber(step_key) or 0) + (tonumber(anim.region_id) or 0) * 31 + (tonumber(anim.track_id) or 0) * 17
            draw_seq_note_delete_fx(dl, draw_x0, row_y0 + row_pad, draw_x1, row_y1 - row_pad, t, br, bg, bb, seed)
          end
        end
      end
    end
  end
end

function draw_seq_note_sync_flash(dl, x0, y0, x1, y1, t)
  t = seq_anim_clamp01(t or 0.0)
  local fade = 1.0 - t
  local fill_a = math.floor(150 * (fade ^ 1.25))
  local edge_a = math.floor(230 * (fade ^ 0.8))
  if fill_a > 0 then
    r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, build_color_rrgbbaa(255, 255, 255, fill_a), 0)
  end
  if edge_a > 0 then
    r.ImGui_DrawList_AddRect(dl, x0 - 1.0, y0 - 1.0, x1 + 1.0, y1 + 1.0, build_color_rrgbbaa(255, 255, 255, edge_a), 0, 0, 1.8)
  end
end

function toggle_seq_note(region, slot, step_key, qn_offset, force_mode, opts)
  if not region or not slot then
    return false
  end
  opts = opts or {}
  local length = get_seq_region_length_qn(region)
  if type(qn_offset) == "number" then
    if qn_offset < -1e-9 or qn_offset >= length - 1e-9 then
      return false
    end
  elseif not seq_step_in_region(region, step_key) then
    return false
  end

  local existing_key = nil
  local existing = nil
  if type(qn_offset) == "number" then
    existing_key, existing = seq_find_note_key_at_qn(region, slot.id, qn_offset)
  end
  if not existing then
    existing = get_seq_note(region, slot.id, step_key)
    if existing and type(qn_offset) == "number"
       and math.abs(seq_note_qn_offset(existing, step_key) - qn_offset) > 1e-4 then
      existing = nil
    else
      existing_key = existing and tostring(step_key) or nil
    end
  end
  if not existing_key then
    existing_key = (type(qn_offset) == "number") and seq_alloc_note_key(region, slot.id, qn_offset) or tostring(step_key)
  end
  step_key = tostring(existing_key)

  if existing and force_mode ~= "paint" then
    local was_locked = seq_note_is_locked(existing)
    register_seq_note_anim(region.id, slot.id, step_key, existing, "delete")
    delete_seq_note(region, slot.id, step_key)
    if was_locked then
      local grid_qn = state.seq_grid_qn or 0.25
      local empty_key = seq_region_step_key(region, seq_note_abs_qn(region, existing, step_key, grid_qn), grid_qn)
      seq_set_cell_locked(get_seq_pattern(region.pattern_id, true), slot.id, empty_key, true)
    end
    if state.selected_seq_note and state.selected_seq_note.region_id == region.id and
       state.selected_seq_note.track_id == slot.id and tostring(state.selected_seq_note.step_key) == step_key then
      state.selected_seq_note = nil
    end
  elseif not existing and force_mode ~= "erase" then
    local note = make_default_seq_note(slot, step_key, qn_offset)
    if not note then
      log("Sequencer slot has no assigned sample")
      return false
    end
    local pattern = get_seq_pattern(region.pattern_id, true)
    seq_set_cell_locked(pattern, slot.id, step_key, false)
    if type(qn_offset) == "number" then
      seq_set_cell_locked(pattern, slot.id, seq_region_step_key(region, (region.start_qn or 0.0) + qn_offset, state.seq_grid_qn or 0.25), false)
    end
    set_seq_note(region, slot.id, step_key, note)
    register_seq_note_anim(region.id, slot.id, step_key, note, "add")
    state.selected_seq_note = { region_id = region.id, track_id = slot.id, step_key = step_key }
  else
    return false
  end

  if not opts.defer_sync then
    sync_seq_pattern_note(region.pattern_id, slot, step_key, { skip_neighbor = opts.skip_neighbor })
    if not opts.defer_arrange then
      r.UpdateArrange()
    end
  end
  if not opts.defer_save then
    save_config()
  end
  return true
end

function get_selected_seq_note()
  if not state.selected_seq_note then
    return nil, nil
  end
  local region = get_seq_region_by_id(state.selected_seq_note.region_id)
  if not region then
    return nil, nil
  end
  return get_seq_note(region, state.selected_seq_note.track_id, state.selected_seq_note.step_key), region
end

