function get_seq_row_lane_style(row)
  if row.type == "note" then
    return {
      bg = UI_THEME.bg_panel,
      label_bg = UI_THEME.bg,
      timeline_bg = UI_THEME.surface,
      edge = UI_THEME.border,
      accent = UI_THEME.accent,
    }
  end
  if row.type == "param" and row.param then
    local styles = {
      volume = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xFFD166FF },
      sample_vary = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0x8FD98FFF },
      vary_filter = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0x7ECFA6FF },
      stutter = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xC9A8FFFF },
      pan = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0x6EC8FFFF },
      pitch = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xFFB84DFF },
      length_qn = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0x88DDAAFF },
      decay = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xFFD166FF },
      stretch = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0x7ED0C8FF },
      start = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xA8E0C0FF },
      locked = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xE8C070FF },
    }
    return styles[row.param.key] or { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = UI_THEME.text_dim }
  end
  return { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = UI_THEME.text_mute }
end

function seq_lane_color_with_alpha(color, alpha)
  local cr, cg, cb = extract_rgb_rrgbbaa(color or 0xFFFFFFFF)
  return build_color_rrgbbaa(cr, cg, cb, alpha or 255)
end

function seq_lane_param_fill_colors(accent, bipolar, value)
  local ar, ag, ab = extract_rgb_rrgbbaa(accent or 0xFFD166FF)
  local fill = build_color_rrgbbaa(ar, ag, ab, 205)
  local cap = build_color_rrgbbaa(math.min(255, ar + 45), math.min(255, ag + 45), math.min(255, ab + 45), 255)
  local fill_neg = build_color_rrgbbaa(math.max(0, ar - 70), math.max(0, ag - 35), math.min(255, ab + 40), 205)
  if bipolar and value ~= nil and value < 0 then
    return fill_neg, cap
  end
  return fill, cap
end

function get_param_lane_def(param_key)
  for _, def in ipairs(SEQ_PARAM_LANES) do
    if def.key == param_key then
      return def
    end
  end
  return nil
end

function seq_note_edit_mode_defs()
  local defs = {}
  for _, def in ipairs(SEQ_PARAM_LANES) do
    if def.hotkey then
      defs[#defs + 1] = def
    end
  end
  return defs
end

function get_seq_note_edit_mode_def()
  return get_param_lane_def(state.seq_note_edit_mode)
end

function seq_set_note_edit_mode(param_key)
  if state.seq_note_edit_mode == "vary_filter" and param_key ~= "vary_filter" then
    if state.seq_vary_filter_edit and seq_trim_text(state.seq_vary_filter_edit.text) ~= "" then
      seq_commit_vary_filter_edit()
    else
      seq_cancel_vary_filter_edit()
    end
  end
  if param_key and get_param_lane_def(param_key) then
    state.seq_note_edit_mode = param_key
  else
    state.seq_note_edit_mode = nil
  end
end

function seq_toggle_note_edit_mode(param_key)
  if state.seq_note_edit_mode == param_key then
    seq_set_note_edit_mode(nil)
  else
    seq_set_note_edit_mode(param_key)
  end
end

function seq_plain_letter_pressed(letter)
  if not letter or not r.ImGui_IsKeyPressed then
    return false
  end
  if is_ctrl_down() or is_cmd_down() or is_alt_down() or is_shift_down() then
    return false
  end
  local fn = r["ImGui_Key_" .. string.upper(letter)]
  if not fn then
    return false
  end
  return r.ImGui_IsKeyPressed(ctx, fn(), false)
end

function seq_plain_digit_pressed(digit)
  if digit == nil or not r.ImGui_IsKeyPressed then
    return false
  end
  if is_ctrl_down() or is_cmd_down() or is_alt_down() or is_shift_down() then
    return false
  end
  local fn = r["ImGui_Key_" .. tostring(digit)]
  if not fn then
    return false
  end
  return r.ImGui_IsKeyPressed(ctx, fn(), false)
end

function seq_capture_shortcut_key()
  if r.ImGui_SetNextFrameWantCaptureKeyboard then
    r.ImGui_SetNextFrameWantCaptureKeyboard(ctx, true)
  end
end

function seq_start_transport_playback()
  local play_state = r.GetPlayState and r.GetPlayState() or 0
  if (play_state & 1) == 0 then
    r.Main_OnCommand(1007, 0)
  end
end

function seq_hover_play_qn()
  local hover = state.seq_grid_hover
  if not hover or type(hover.hovered_qn) ~= "number" then
    return nil
  end
  local step_qn = hover.step_qn or state.seq_grid_qn or 0.25
  if step_qn <= 0 then
    step_qn = 0.25
  end
  -- Start of the hovered grid cell (measure/beat on the current grid).
  return math.max(0.0, math.floor((hover.hovered_qn / step_qn) + 1e-9) * step_qn)
end

function seq_play_from_hover_grid()
  local qn = seq_hover_play_qn()
  if qn then
    seq_set_playhead_qn(qn)
  end
  seq_start_transport_playback()
  return qn ~= nil
end

function seq_set_exclusive_slot_solo(slot)
  local changed = false
  for _, s in ipairs(state.seq_tracks or {}) do
    local want = (slot ~= nil and s.id == slot.id)
    if s.solo ~= want then
      s.solo = want
      changed = true
    end
  end
  if changed then
    seq_apply_all_slot_mix_to_reaper()
    save_config()
  end
  return changed
end

function seq_clear_all_slot_solos()
  local changed = false
  for _, s in ipairs(state.seq_tracks or {}) do
    if s.solo then
      s.solo = false
      changed = true
    end
  end
  if changed then
    seq_apply_all_slot_mix_to_reaper()
    save_config()
  end
  return changed
end

function seq_hover_slot()
  local hover = state.seq_grid_hover
  if not hover or not hover.slot_id then
    return nil
  end
  return seq_find_slot_by_id(hover.slot_id)
end

function seq_set_note_body_length(note, length_qn, step_qn)
  if type(note) ~= "table" then
    return
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  length_qn = math.max(step_qn * 0.05, tonumber(length_qn) or step_qn)
  if seq_note_has_stutter_span(note, step_qn) or seq_stutter_count(note) > 1 then
    note.length_qn = length_qn
  else
    note.decay_qn = length_qn
  end
  seq_clamp_note_fades(note, length_qn)
end

function seq_find_note_covering_abs_qn(region, slot, abs_qn, step_qn)
  if not region or not slot or type(abs_qn) ~= "number" then
    return nil, nil
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local pattern = get_seq_pattern(region.pattern_id, false)
  local notes = get_track_note_table(pattern, slot.id, false)
  if not notes then
    return nil, nil
  end
  local best_key, best_note, best_start = nil, nil, -math.huge
  for key, note in pairs(notes) do
    if type(note) == "table" and note.enabled ~= false then
      local start_qn = seq_note_visual_abs_qn(region, note, key, step_qn)
      local length_qn = seq_note_current_decay_length_qn(region, slot, note, key, step_qn) or 0.0
      local end_qn = start_qn + math.max(0.0, length_qn)
      if abs_qn >= start_qn - 1e-9 and abs_qn < end_qn - 1e-9 and start_qn >= best_start then
        best_key, best_note, best_start = tostring(key), note, start_qn
      end
    end
  end
  return best_key, best_note
end

function seq_split_note_at_qn(region, slot, step_key, note, split_qn, step_qn, snap)
  if not region or not slot or not note or type(split_qn) ~= "number" then
    return false
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  if snap then
    split_qn = seq_snap_qn(split_qn, step_qn)
  else
    split_qn = seq_quantize_free_qn(split_qn)
  end
  local start_qn = seq_note_visual_abs_qn(region, note, step_key, step_qn)
  local length_qn = seq_note_current_decay_length_qn(region, slot, note, step_key, step_qn) or 0.0
  local end_qn = start_qn + math.max(0.0, length_qn)
  local min_qn = snap and 1e-4 or (1.0 / 192.0)
  if split_qn <= start_qn + min_qn or split_qn >= end_qn - min_qn then
    return false
  end
  local left_len = split_qn - start_qn
  local right_len = end_qn - split_qn
  if left_len < min_qn or right_len < min_qn then
    return false
  end

  local own = seq_undo_own_begin("Split sequencer note")
  local right = clone_table_deep(note)
  seq_set_note_body_length(note, left_len, step_qn)
  seq_note_clear_fade_side(note, "out")
  seq_clamp_note_fades(note, left_len)

  right.qn_offset = split_qn - (region.start_qn or 0.0)
  right.step = math.floor((right.qn_offset / step_qn) + 1e-9)
  right.offset_qn = 0.0
  seq_set_note_body_length(right, right_len, step_qn)
  seq_note_clear_fade_side(right, "in")
  seq_clamp_note_fades(right, right_len)

  local new_key = seq_alloc_note_key(region, slot.id, right.qn_offset)
  set_seq_note(region, slot.id, new_key, right)
  register_seq_note_anim(region.id, slot.id, new_key, right, "add")
  state.selected_seq_note = { region_id = region.id, track_id = slot.id, step_key = new_key }
  sync_seq_pattern_note(region.pattern_id, slot, step_key)
  sync_seq_pattern_note(region.pattern_id, slot, new_key, { skip_neighbor = true })
  r.UpdateArrange()
  save_config()
  if own then
    end_seq_undo("Split sequencer note")
  end
  return true
end

function handle_seq_playback_and_split_keys()
  if not sequencer_is_open() then
    return
  end
  if imgui_any_popup_open() or seq_ingest_busy() then
    return
  end
  if shortcut_pressed("solo_play") then
    local slot = seq_hover_slot()
    if slot then
      seq_capture_shortcut_key()
      seq_set_exclusive_slot_solo(slot)
      seq_play_from_hover_grid()
    end
    return
  end
  if shortcut_pressed("unsolo_play") then
    seq_capture_shortcut_key()
    seq_clear_all_slot_solos()
    seq_play_from_hover_grid()
    return
  end
  local snap_split = shortcut_pressed("split_snap")
  local free_split = shortcut_pressed("split_free")
  if snap_split or free_split then
    local hover = state.seq_grid_hover
    if not hover or not hover.slot_id or type(hover.hovered_qn) ~= "number" then
      return
    end
    local slot = seq_find_slot_by_id(hover.slot_id)
    local region = seq_region_at_qn(hover.hovered_qn)
      or (hover.region_id and get_seq_region_by_id(hover.region_id))
    if not slot or not region then
      return
    end
    local step_qn = hover.step_qn or state.seq_grid_qn or 0.25
    local step_key, note = seq_find_note_covering_abs_qn(region, slot, hover.hovered_qn, step_qn)
    if not step_key or not note then
      return
    end
    seq_capture_shortcut_key()
    seq_split_note_at_qn(region, slot, step_key, note, hover.hovered_qn, step_qn, snap_split)
  end
end

function handle_seq_note_edit_mode_keys()
  if not sequencer_is_open() then
    return
  end
  if shortcut_pressed("pick_note_sample") then
    seq_toggle_note_sample_pick()
    seq_capture_shortcut_key()
    return
  end
  if imgui_any_popup_open() then
    return
  end
  if shortcut_pressed("preview_hover") then
    local now = r.time_precise()
    local is_double = (now - (state.seq_z_preview_last_t or 0)) < 0.45
    state.seq_z_preview_last_t = now
    if is_double and preview_proc then
      stop_preview()
      state.preview_paused = false
      state.preview_position = 0.0
      return
    end
    preview_seq_hovered_grid()
    return
  end
  if handle_seq_razor_keys() then
    return
  end
  if seq_ingest_busy() then
    return
  end
  if shortcut_pressed("enlarge_track") then
    if seq_toggle_enlarge_hovered_track() then
      seq_capture_shortcut_key()
    end
    return
  end
  if shortcut_pressed("cancel") then
    if state.seq_vary_filter_edit then
      seq_cancel_vary_filter_edit()
      return
    end
    if state.seq_note_edit_mode then
      seq_set_note_edit_mode(nil)
      return
    end
  end
  for _, def in ipairs(seq_note_edit_mode_defs()) do
    if def.shortcut_id and shortcut_pressed(def.shortcut_id) then
      seq_toggle_note_edit_mode(def.key)
      return
    end
  end
end

SEQ_RAZOR_FILL = 0x3DCEFF55
SEQ_RAZOR_EDGE = 0x3DCEFFFF
SEQ_RAZOR_PREVIEW_FILL = 0x3DCEFF88
SEQ_RAZOR_PREVIEW_EDGE = 0x9AEEFFFF
SEQ_RAZOR_HOVER_FILL = 0x3DCEFF99
SEQ_RAZOR_HOVER_EDGE = 0xB8F0FFFF

function seq_razor_right_down()
  if not ctx or not r.ImGui_IsMouseDown then
    return false
  end
  return r.ImGui_IsMouseDown(ctx, 1)
end

function seq_razor_right_clicked()
  if not ctx or not r.ImGui_IsMouseClicked then
    return false
  end
  return r.ImGui_IsMouseClicked(ctx, 1)
end

-- Alt + right-drag draws a razor. Alt+Ctrl/Cmd + right-drag adds another.
function seq_razor_gesture_active()
  if state.seq_razor_drag then
    return state.seq_razor_drag.mode ~= "move"
  end
  if not is_alt_down() then
    return false
  end
  return seq_razor_right_down() or seq_razor_right_clicked()
end

function seq_razor_copy_modifier()
  return is_ctrl_down() or is_cmd_down()
end

function seq_note_copy_modifier()
  return is_ctrl_down() or is_cmd_down()
end

function seq_note_slip_modifier()
  return is_shift_down()
end

function seq_razor_additive_gesture()
  return is_alt_down() and (is_ctrl_down() or is_cmd_down())
end

function seq_has_razors()
  return state.seq_razors and #state.seq_razors > 0
end

function seq_razor_blocks_grid_edit()
  return state.seq_razor_drag ~= nil or seq_razor_gesture_active()
end

function seq_clear_razors()
  local drag = state.seq_razor_drag
  if drag and drag.mode == "move" then
    if drag.patterns_backup then
      state.seq_patterns = clone_table_deep(drag.patterns_backup)
    end
    if drag.undo_open then
      end_seq_undo(drag.undo_label or (drag.copy and "Copy razor notes" or "Move razor notes"))
    end
  end
  local had = seq_has_razors() or state.seq_razor_drag ~= nil
  state.seq_razors = {}
  state.seq_razor_drag = nil
  return had
end

function seq_razor_has_track(razor, track_id)
  if not razor or not razor.track_ids then
    return false
  end
  for _, id in ipairs(razor.track_ids) do
    if id == track_id then
      return true
    end
  end
  return false
end

function seq_cell_in_any_razor(track_id, qn)
  if not seq_has_razors() then
    return false
  end
  for _, razor in ipairs(state.seq_razors) do
    if qn >= (razor.start_qn or 0) and qn < (razor.end_qn or 0) and seq_razor_has_track(razor, track_id) then
      return true
    end
  end
  return false
end

function seq_razor_hovered_at(track_id, qn)
  if not track_id or type(qn) ~= "number" or not seq_has_razors() then
    return false
  end
  for _, razor in ipairs(state.seq_razors) do
    if qn >= (razor.start_qn or 0) and qn < (razor.end_qn or 0) and seq_razor_has_track(razor, track_id) then
      return true
    end
  end
  return false
end

function seq_compute_razor_hover(mx, my, visual_rows, body_y0, body_y1, timeline_x0, timeline_w, view_start_qn, qn_span)
  if not seq_has_razors() or mx < timeline_x0 or mx > timeline_x0 + timeline_w
      or my < body_y0 or my > body_y1 then
    return false, nil, nil
  end
  local track_id = nil
  local cursor_y = body_y0
  for _, row in ipairs(visual_rows) do
    local row_y0 = cursor_y
    local row_y1 = row_y0 + row.h
    if my >= row_y0 and my <= row_y1 and row.slot then
      track_id = row.slot.id
      break
    end
    cursor_y = row_y1
  end
  if not track_id then
    return false, nil, nil
  end
  local qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  if seq_razor_hovered_at(track_id, qn) then
    return true, track_id, qn
  end
  return false, nil, nil
end

function seq_track_id_at_y(row_positions, my)
  if not row_positions or #row_positions == 0 then
    return nil
  end
  for _, row_pos in ipairs(row_positions) do
    if my >= row_pos.y0 and my <= row_pos.y1 and row_pos.row and row_pos.row.slot then
      return row_pos.row.slot.id
    end
  end
  local first = row_positions[1]
  if my < first.y0 and first.row and first.row.slot then
    return first.row.slot.id
  end
  for i = #row_positions, 1, -1 do
    local row_pos = row_positions[i]
    if row_pos.row and row_pos.row.slot then
      return row_pos.row.slot.id
    end
  end
  return nil
end

function seq_normalize_razor_area(start_qn, end_qn, track_id_a, track_id_b, step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  if type(start_qn) ~= "number" or type(end_qn) ~= "number" then
    return nil
  end
  local q0 = math.min(start_qn, end_qn)
  local q1 = math.max(start_qn, end_qn)
  q0 = math.max(0.0, math.floor(q0 / step_qn + 1e-9) * step_qn)
  q1 = math.ceil(q1 / step_qn - 1e-9) * step_qn
  if q1 <= q0 then
    q1 = q0 + step_qn
  end
  local _, ia = find_seq_track_by_id(track_id_a)
  local _, ib = find_seq_track_by_id(track_id_b)
  if not ia or not ib then
    return nil
  end
  if ia > ib then
    ia, ib = ib, ia
  end
  local track_ids = {}
  for i = ia, ib do
    local slot = state.seq_tracks[i]
    if slot then
      track_ids[#track_ids + 1] = slot.id
    end
  end
  if #track_ids == 0 then
    return nil
  end
  return { start_qn = q0, end_qn = q1, track_ids = track_ids }
end

function seq_begin_razor_drag(track_id, qn, additive)
  if not track_id or type(qn) ~= "number" then
    return
  end
  if not additive then
    state.seq_razors = {}
  end
  state.seq_razor_drag = {
    mode = "draw",
    additive = additive and true or false,
    start_qn = qn,
    start_track_id = track_id,
    current_qn = qn,
    current_track_id = track_id,
  }
end

function seq_razor_collect_notes(step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local items = {}
  local seen = {}
  for _, razor in ipairs(state.seq_razors or {}) do
    for _, track_id in ipairs(razor.track_ids or {}) do
      for _, region in ipairs(state.seq_regions) do
        local reg_start = region.start_qn or 0.0
        local reg_end = reg_start + get_seq_region_length_qn(region)
        if reg_end > (razor.start_qn or 0) and reg_start < (razor.end_qn or 0) then
          local notes = get_track_note_table(get_seq_pattern(region.pattern_id, false), track_id, false)
          if notes then
            for step_key, note in pairs(notes) do
              if type(note) == "table" then
                local abs_qn = seq_note_abs_qn(region, note, step_key, step_qn)
                if abs_qn >= (razor.start_qn or 0) and abs_qn < (razor.end_qn or 0) then
                    local uniq = tostring(region.id) .. ":" .. tostring(track_id) .. ":" .. tostring(step_key)
                    if not seen[uniq] then
                      seen[uniq] = true
                      local slot = seq_find_slot_by_id(track_id)
                      items[#items + 1] = {
                        region_id = region.id,
                        track_id = track_id,
                        step_key = tostring(step_key),
                        step_idx = tonumber(step_key) or tonumber(note.step) or 0,
                        abs_qn = abs_qn,
                        note = clone_table_deep(note),
                        length_qn = seq_note_length_qn_for_copy(region, slot, note, step_key, step_qn),
                      }
                    end
                end
              end
            end
          end
        end
      end
    end
  end
  return items
end

function seq_razor_track_index_bounds(track_ids)
  local min_idx, max_idx = nil, nil
  for _, track_id in ipairs(track_ids or {}) do
    local _, idx = find_seq_track_by_id(track_id)
    if idx then
      min_idx = min_idx and math.min(min_idx, idx) or idx
      max_idx = max_idx and math.max(max_idx, idx) or idx
    end
  end
  return min_idx, max_idx
end

function seq_shift_track_ids(track_ids, delta_tracks)
  if not track_ids or delta_tracks == 0 then
    return track_ids
  end
  local shifted = {}
  for _, track_id in ipairs(track_ids) do
    local _, idx = find_seq_track_by_id(track_id)
    local slot = idx and state.seq_tracks[idx + delta_tracks]
    if not slot then
      return nil
    end
    shifted[#shifted + 1] = slot.id
  end
  return shifted
end

function seq_razor_clear_notes_in_areas(razors, step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  for _, razor in ipairs(razors or {}) do
    for _, track_id in ipairs(razor.track_ids or {}) do
      for _, region in ipairs(state.seq_regions) do
        local reg_start = region.start_qn or 0.0
        local reg_end = reg_start + get_seq_region_length_qn(region)
        if reg_end > (razor.start_qn or 0) and reg_start < (razor.end_qn or 0) then
          local notes = get_track_note_table(get_seq_pattern(region.pattern_id, false), track_id, false)
          if notes then
            local to_delete = {}
            for step_key, note in pairs(notes) do
              if type(note) == "table" then
                local abs_qn = seq_note_abs_qn(region, note, step_key, step_qn)
                if abs_qn >= (razor.start_qn or 0) and abs_qn < (razor.end_qn or 0) then
                    to_delete[#to_delete + 1] = step_key
                end
              end
            end
            for _, step_key in ipairs(to_delete) do
              delete_seq_note(region, track_id, step_key)
            end
          end
        end
      end
    end
  end
end

function seq_begin_razor_move(track_id, qn, step_qn, copy)
  if not seq_has_razors() or not track_id or type(qn) ~= "number" then
    return
  end
  copy = copy and true or false
  local label = begin_seq_undo(copy and "Copy razor notes" or "Move razor notes")
  state.seq_razor_drag = {
    mode = "move",
    copy = copy,
    start_qn = qn,
    start_track_id = track_id,
    current_qn = qn,
    current_track_id = track_id,
    payload = seq_razor_collect_notes(step_qn),
    patterns_backup = clone_table_deep(state.seq_patterns),
    razors_orig = clone_table_deep(state.seq_razors),
    applied_delta_qn = 0,
    applied_delta_tracks = 0,
    undo_label = label,
    undo_open = true,
    dirty = false,
  }
end

function seq_razor_clamped_move_delta(drag, step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local raw_qn = (drag.current_qn or drag.start_qn) - (drag.start_qn or 0)
  local delta_qn = math.floor((raw_qn / step_qn) + 0.5) * step_qn
  local _, start_idx = find_seq_track_by_id(drag.start_track_id)
  local _, cur_idx = find_seq_track_by_id(drag.current_track_id)
  local delta_tracks = 0
  if start_idx and cur_idx then
    delta_tracks = cur_idx - start_idx
  end

  local min_qn = nil
  local min_idx, max_idx = nil, nil
  for _, razor in ipairs(drag.razors_orig or {}) do
    min_qn = min_qn and math.min(min_qn, razor.start_qn or 0) or (razor.start_qn or 0)
    local rmin, rmax = seq_razor_track_index_bounds(razor.track_ids)
    if rmin then
      min_idx = min_idx and math.min(min_idx, rmin) or rmin
      max_idx = max_idx and math.max(max_idx, rmax) or rmax
    end
  end
  for _, item in ipairs(drag.payload or {}) do
    min_qn = min_qn and math.min(min_qn, item.abs_qn) or item.abs_qn
    local _, idx = find_seq_track_by_id(item.track_id)
    if idx then
      min_idx = min_idx and math.min(min_idx, idx) or idx
      max_idx = max_idx and math.max(max_idx, idx) or idx
    end
  end
  if min_qn then
    delta_qn = math.max(delta_qn, -min_qn)
  end
  local track_count = #(state.seq_tracks or {})
  if min_idx and max_idx and track_count > 0 then
    delta_tracks = math.max(1 - min_idx, math.min(track_count - max_idx, delta_tracks))
  else
    delta_tracks = 0
  end
  return delta_qn, delta_tracks
end

function seq_razor_apply_move(drag, step_qn)
  if not drag or drag.mode ~= "move" then
    return
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local delta_qn, delta_tracks = seq_razor_clamped_move_delta(drag, step_qn)
  if drag.applied_delta_qn == delta_qn and drag.applied_delta_tracks == delta_tracks then
    return
  end

  state.seq_patterns = clone_table_deep(drag.patterns_backup)
  if delta_qn ~= 0 or delta_tracks ~= 0 then
    local dest_razors = {}
    for _, orig in ipairs(drag.razors_orig or {}) do
      dest_razors[#dest_razors + 1] = {
        start_qn = (orig.start_qn or 0) + delta_qn,
        end_qn = (orig.end_qn or 0) + delta_qn,
        track_ids = seq_shift_track_ids(orig.track_ids, delta_tracks) or orig.track_ids,
      }
    end
    if not drag.copy then
      for _, item in ipairs(drag.payload or {}) do
        local region = get_seq_region_by_id(item.region_id)
        delete_seq_note(region, item.track_id, item.step_key)
      end
    end
    seq_razor_clear_notes_in_areas(dest_razors, step_qn)
    for _, item in ipairs(drag.payload or {}) do
      local _, orig_idx = find_seq_track_by_id(item.track_id)
      local dest_slot = orig_idx and state.seq_tracks[orig_idx + delta_tracks]
      local dest_qn = item.abs_qn + delta_qn
      local dest_region = seq_region_at_qn(dest_qn)
      if dest_slot and dest_region and dest_qn >= 0 then
        local rel = dest_qn - (dest_region.start_qn or 0.0)
        if rel >= -1e-9 and rel < get_seq_region_length_qn(dest_region) - 1e-9 then
          local note = clone_table_deep(item.note)
          note.qn_offset = rel
          note.step = math.floor((rel / step_qn) + 1e-9)
          seq_keep_copied_note_over_region(note, item.length_qn, dest_region, rel)
          local key = seq_alloc_note_key(dest_region, dest_slot.id, rel)
          set_seq_note(dest_region, dest_slot.id, key, note)
        end
      end
    end
  end

  local moved_razors = {}
  for _, orig in ipairs(drag.razors_orig or {}) do
    local track_ids = seq_shift_track_ids(orig.track_ids, delta_tracks) or orig.track_ids
    moved_razors[#moved_razors + 1] = {
      start_qn = (orig.start_qn or 0) + delta_qn,
      end_qn = (orig.end_qn or 0) + delta_qn,
      track_ids = track_ids,
    }
  end
  state.seq_razors = moved_razors
  drag.applied_delta_qn = delta_qn
  drag.applied_delta_tracks = delta_tracks
  drag.dirty = (delta_qn ~= 0 or delta_tracks ~= 0)
end

function seq_razor_mark_pattern_ids_for_razors(razors, pattern_ids)
  for _, razor in ipairs(razors or {}) do
    for _, region in ipairs(state.seq_regions) do
      local rs = region.start_qn or 0.0
      local re = rs + get_seq_region_length_qn(region)
      if re > (razor.start_qn or 0) and rs < (razor.end_qn or 0) and region.pattern_id then
        pattern_ids[region.pattern_id] = true
      end
    end
  end
end

function seq_razor_sync_moved_items(drag, step_qn)
  local track_ids = {}
  local pattern_ids = {}

  local function mark_track(id)
    if id then
      track_ids[id] = true
    end
  end

  for _, item in ipairs(drag.payload or {}) do
    mark_track(item.track_id)
    local src_region = get_seq_region_by_id(item.region_id)
    if src_region and src_region.pattern_id then
      pattern_ids[src_region.pattern_id] = true
    end
    local _, orig_idx = find_seq_track_by_id(item.track_id)
    local dest_slot = orig_idx and state.seq_tracks[orig_idx + (drag.applied_delta_tracks or 0)]
    if dest_slot then
      mark_track(dest_slot.id)
    end
    local dest_qn = (item.abs_qn or 0) + (drag.applied_delta_qn or 0)
    local dest_region = seq_region_at_qn(dest_qn)
    if dest_region and dest_region.pattern_id then
      pattern_ids[dest_region.pattern_id] = true
    end
  end
  for _, razor in ipairs(drag.razors_orig or {}) do
    for _, tid in ipairs(razor.track_ids or {}) do
      mark_track(tid)
    end
  end
  for _, razor in ipairs(state.seq_razors or {}) do
    for _, tid in ipairs(razor.track_ids or {}) do
      mark_track(tid)
    end
  end
  seq_razor_mark_pattern_ids_for_razors(drag.razors_orig, pattern_ids)
  seq_razor_mark_pattern_ids_for_razors(state.seq_razors, pattern_ids)

  if r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  for _, region in ipairs(state.seq_regions) do
    if pattern_ids[region.pattern_id] then
      for _, slot in ipairs(state.seq_tracks) do
        if track_ids[slot.id] then
          sync_seq_region_track(region, slot, { skip_arrange = true })
        end
      end
    end
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  r.UpdateArrange()
end

function seq_update_razor_drag(track_id, qn, row_positions, my)
  local drag = state.seq_razor_drag
  if not drag then
    return
  end
  if type(qn) == "number" then
    drag.current_qn = qn
  end
  if track_id then
    drag.current_track_id = track_id
  elseif row_positions and my then
    local id = seq_track_id_at_y(row_positions, my)
    if id then
      drag.current_track_id = id
    end
  end
end

function seq_commit_razor_drag(step_qn)
  local drag = state.seq_razor_drag
  state.seq_razor_drag = nil
  if not drag then
    return
  end
  if drag.mode == "move" then
    if drag.dirty then
      seq_razor_sync_moved_items(drag, step_qn)
      save_config()
    end
    if drag.undo_open then
      end_seq_undo(drag.undo_label or (drag.copy and "Copy razor notes" or "Move razor notes"))
    end
    return
  end
  local area = seq_normalize_razor_area(
    drag.start_qn, drag.current_qn, drag.start_track_id, drag.current_track_id, step_qn
  )
  if not area then
    return
  end
  state.seq_razors = state.seq_razors or {}
  if not drag.additive then
    state.seq_razors = {}
  end
  state.seq_razors[#state.seq_razors + 1] = area
end

function seq_razor_y_bounds(razor, row_positions)
  if not razor or not row_positions then
    return nil, nil
  end
  local y0, y1 = nil, nil
  for _, row_pos in ipairs(row_positions) do
    local slot = row_pos.row and row_pos.row.slot
    if slot and seq_razor_has_track(razor, slot.id) then
      y0 = y0 and math.min(y0, row_pos.y0) or row_pos.y0
      y1 = y1 and math.max(y1, row_pos.y1) or row_pos.y1
    end
  end
  return y0, y1
end

function draw_seq_razor_area(dl, razor, row_positions, timeline_x0, timeline_x1, view_start_qn, qn_span, preview, hovered)
  if not razor or not dl then
    return
  end
  local y0, y1 = seq_razor_y_bounds(razor, row_positions)
  if not y0 or not y1 or y1 <= y0 then
    return
  end
  local timeline_w = math.max(1.0, timeline_x1 - timeline_x0)
  local function qn_to_x(qn)
    return timeline_x0 + ((qn - view_start_qn) / math.max(0.0001, qn_span)) * timeline_w
  end
  local rx0 = math.max(timeline_x0, qn_to_x(razor.start_qn or 0))
  local rx1 = math.min(timeline_x1, qn_to_x(razor.end_qn or 0))
  if rx1 <= rx0 then
    return
  end
  local fill = preview and SEQ_RAZOR_PREVIEW_FILL or (hovered and SEQ_RAZOR_HOVER_FILL or SEQ_RAZOR_FILL)
  local edge = preview and SEQ_RAZOR_PREVIEW_EDGE or (hovered and SEQ_RAZOR_HOVER_EDGE or SEQ_RAZOR_EDGE)
  local thickness = preview and 2.0 or (hovered and 2.4 or 1.6)
  r.ImGui_DrawList_AddRectFilled(dl, rx0, y0, rx1, y1, fill, 0)
  r.ImGui_DrawList_AddRect(dl, rx0, y0, rx1, y1, edge, 0, 0, thickness)
end

function draw_seq_razors(dl, row_positions, timeline_x0, timeline_x1, view_start_qn, qn_span, step_qn, hover_track_id, hover_qn)
  for _, razor in ipairs(state.seq_razors or {}) do
    local hovered = hover_track_id and hover_qn
      and seq_razor_has_track(razor, hover_track_id)
      and hover_qn >= (razor.start_qn or 0) and hover_qn < (razor.end_qn or 0)
    draw_seq_razor_area(dl, razor, row_positions, timeline_x0, timeline_x1, view_start_qn, qn_span, false, hovered)
  end
  local drag = state.seq_razor_drag
  if drag and drag.mode ~= "move" then
    local preview = seq_normalize_razor_area(
      drag.start_qn, drag.current_qn, drag.start_track_id, drag.current_track_id, step_qn
    )
    if preview then
      draw_seq_razor_area(dl, preview, row_positions, timeline_x0, timeline_x1, view_start_qn, qn_span, true)
    end
  end
end

function seq_delete_notes_in_razors()
  if not seq_has_razors() then
    return false
  end
  local step_qn = state.seq_grid_qn or 0.25
  local label = begin_seq_undo("Delete razor notes")
  local changed = false
  local synced = {}
  if r.PreventUIRefresh then r.PreventUIRefresh(1) end
  for _, razor in ipairs(state.seq_razors) do
    for _, track_id in ipairs(razor.track_ids or {}) do
      local slot = find_seq_track_by_id(track_id)
      if slot then
        for _, region in ipairs(state.seq_regions) do
          local reg_start = region.start_qn or 0.0
          local reg_end = reg_start + get_seq_region_length_qn(region)
          if reg_end > (razor.start_qn or 0) and reg_start < (razor.end_qn or 0) then
            local pattern = get_seq_pattern(region.pattern_id, false)
            local notes = get_track_note_table(pattern, track_id, false)
            if notes then
              local to_delete = {}
              for step_key, note in pairs(notes) do
                if type(note) == "table" then
                  local abs_qn = seq_note_abs_qn(region, note, step_key, step_qn)
                  if abs_qn >= (razor.start_qn or 0) and abs_qn < (razor.end_qn or 0) then
                    to_delete[#to_delete + 1] = { key = step_key, qn = seq_note_qn_offset(note, step_key, step_qn) }
                  end
                end
              end
              for _, rec in ipairs(to_delete) do
                if toggle_seq_note(region, slot, rec.key, rec.qn, "erase", {
                  defer_save = true,
                  defer_arrange = true,
                }) then
                  changed = true
                  synced[region.pattern_id] = true
                end
              end
            end
          end
        end
      end
    end
  end
  if r.PreventUIRefresh then r.PreventUIRefresh(-1) end
  if changed then
    for pattern_id in pairs(synced) do
      sync_seq_pattern_regions(pattern_id)
    end
    r.UpdateArrange()
    save_config()
  end
  end_seq_undo(label)
  return changed
end

function handle_seq_razor_keys()
  if shortcut_pressed("cancel") then
    if seq_clear_razors() then
      return true
    end
  end
  if seq_ingest_busy() then
    return false
  end
  local delete_pressed = shortcut_pressed("delete_razor") or shortcut_pressed("delete_razor_alt")
  if delete_pressed and seq_has_razors() then
    if r.ImGui_SetNextFrameWantCaptureKeyboard then
      r.ImGui_SetNextFrameWantCaptureKeyboard(ctx, true)
    end
    seq_delete_notes_in_razors()
    return true
  end
  return false
end

function find_seq_note_lane_bounds(row_positions, track_id)
  for _, row_pos in ipairs(row_positions) do
    local row = row_pos.row
    if row.type == "note" and row.slot and row.slot.id == track_id then
      return row_pos.y0 + 2, row_pos.y1 - 2, row_pos
    end
  end
  return nil, nil, nil
end

function seq_param_drag_button_down(drag, left_down, right_down)
  if not drag then
    return false
  end
  if drag.button == 1 then
    return right_down
  end
  return left_down
end

function apply_seq_param_reset_drag(drag, def, mx, step_qn, step_count, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, active_cells)
  drag.end_col = seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
  local col_min = math.min(drag.col, drag.end_col)
  local col_max = math.max(drag.col, drag.end_col)
  local mouse_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  if seq_is_lock_def(def) then
    if drag.lock_click_span then
      if drag.end_col == drag.col then
        return false, 0.0, col_min, col_max, drag.end_col
      end
      drag.lock_click_span = false
    end
    local region = get_seq_region_by_id(drag.region_id)
    local changed = seq_apply_lock_range(region, drag.track_id, col_min, col_max, start_qn, step_qn, false, active_cells)
    return changed, 0.0, col_min, col_max, drag.end_col
  end
  if seq_is_vary_filter_def(def) then
    if drag.filter_click_span then
      if drag.end_col == drag.col then
        return false, 0.0, col_min, col_max, drag.end_col
      end
      drag.filter_click_span = false
    end
    seq_cancel_vary_filter_edit()
    local region = get_seq_region_by_id(drag.region_id)
    local changed = seq_apply_vary_filter_range(region, drag.track_id, col_min, col_max, start_qn, step_qn, "")
    return changed, 0.0, col_min, col_max, drag.end_col
  end
  local changed = false
  for col = col_min, col_max do
    local active = active_cells[drag.track_id] and active_cells[drag.track_id][col]
    if active then
      local qn0 = start_qn + col * step_qn
      local qn1 = qn0 + step_qn
      seq_for_each_active_note(active, function(entry)
        if seq_apply_param_to_note(
          entry.note, entry.abs_qn, def, def.default, mouse_qn, step_qn, true, true, qn0, qn1
        ) then
          changed = true
        end
      end)
    end
  end
  return changed, def.default, col_min, col_max, drag.end_col
end

function seq_note_item_x_range(note, slot, region, pattern, step_idx, cell_qn, step_qn, qn_to_x, cell_x1)
  if not note or not qn_to_x then
    return nil, nil
  end
  local _, resolved_sample = seq_resolve_note_sample(note, slot, nil, region, slot and slot.id, step_idx)
  local note_qn = cell_qn
  if region then
    note_qn = seq_note_abs_qn(region, note, step_idx, step_qn)
  end
  local note_len = seq_note_draw_length_qn(
    region, pattern, slot, slot and slot.id, step_idx, note, resolved_sample, step_qn
  ) or step_qn
  local note_off = note.offset_qn or 0.0
  local draw_x0 = qn_to_x(note_qn + note_off) + 2
  local draw_x1 = math.max(draw_x0 + 6.0, qn_to_x(note_qn + note_off + note_len) - 2)
  local trigger_x1 = draw_x1
  if not seq_note_has_stutter_span(note, step_qn) then
    local head_x1 = seq_note_head_end_x(qn_to_x, note_qn, note, step_qn)
    if head_x1 and draw_x1 > head_x1 + 1.0 then
      trigger_x1 = math.max(draw_x0 + 6.0, head_x1)
    end
  end
  return draw_x0, trigger_x1
end

function draw_seq_param_value_bar(dl, x0, x1, lane_top, lane_bot, def, value, step_qn, accent, selected)
  if not def then
    return
  end
  if value == nil then
    value = def.default
  end
  value = seq_param_value_for_drag(def, value, step_qn)
  local bipolar = def.min < 0
  local py = seq_param_y_from_value(def, value, lane_top, lane_bot, step_qn)
  local base_y = lane_bot
  if bipolar then
    base_y = seq_param_y_from_value(def, 0.0, lane_top, lane_bot, step_qn)
  end
  local fill_x0 = x0
  local fill_x1 = x1
  if fill_x1 <= fill_x0 then
    fill_x1 = fill_x0 + 1
  end
  local top_y = math.min(py, base_y)
  local bot_y = math.max(py, base_y)
  if math.abs(bot_y - top_y) < 2 then
    top_y = math.min(top_y, bot_y - 2)
  end
  local fill_col, cap_col = seq_lane_param_fill_colors(accent, bipolar, value)
  if not selected then
    fill_col = seq_dim_color_rrgbbaa(fill_col, true)
    cap_col = seq_dim_color_rrgbbaa(cap_col, true)
  end
  r.ImGui_DrawList_AddRectFilled(dl, fill_x0, top_y, fill_x1, bot_y, fill_col, 2.0)
  local cap_y = (py <= base_y) and top_y or bot_y
  r.ImGui_DrawList_AddRectFilled(dl, fill_x0, cap_y - 1, fill_x1, cap_y + 1, cap_col, 1.0)
end

function seq_draw_stutter_param_slices(dl, note, note_qn, def, step_qn, qn_to_x, lane_top, lane_bot, accent, selected, hover_qn)
  local count = seq_stutter_count(note)
  if count <= 1 or not seq_stutter_hit_param_key(def.key) then
    return false
  end
  local note_off = (note and note.offset_qn) or 0.0
  local hover_idx = hover_qn and seq_stutter_hit_index_at_qn(note, note_qn, hover_qn, step_qn) or nil
  for hi = 1, count do
    local off0, off1 = seq_stutter_hit_span(note, hi, step_qn)
    local s0 = note_qn + note_off + off0
    local s1 = note_qn + note_off + off1
    local sx0 = qn_to_x(s0) + 1.0
    local sx1 = qn_to_x(s1) - 1.0
    if sx1 <= sx0 then
      sx1 = sx0 + 1.0
    end
    local value = seq_note_param_value(note, def.key, hi)
    if value == nil then
      value = def.default
    end
    draw_seq_param_value_bar(dl, sx0, sx1, lane_top, lane_bot, def, value, step_qn, accent, selected)
    if hover_idx == hi then
      r.ImGui_DrawList_AddRect(dl, sx0, lane_top, sx1, lane_bot, seq_lane_color_with_alpha(accent, 220), 1.0, 0, 1.2)
    end
    if hi > 1 then
      local dx = qn_to_x(s0)
      r.ImGui_DrawList_AddLine(dl, dx, lane_top, dx, lane_bot, 0xFFFFFF55, 1.0)
    end
  end
  return true
end

function seq_draw_param_lane_packed_notes(dl, ctx, slot, active, def, selected_region_id, start_qn, col, step_qn, qn_to_x, cx0, cx1, lane_top, lane_bot, base_y, bipolar, is_stutter_lane, lane_style, region)
  local pack = seq_active_cell_notes(active)
  if not pack then
    return
  end
  seq_pack_sort_later_on_top(pack)
  for pi = 1, #pack do
    local entry = pack[pi]
    local note = entry.note
    if type(note) == "table" then
      local cell_selected = entry.region_id == selected_region_id
      local value = note[def.key]
      if value == nil then value = def.default end
      if def.key == "length_qn" then
        value = snap_seq_length_qn(value, step_qn)
      elseif def.key == "stutter" then
        value = seq_param_value_for_drag(def, value, step_qn)
      end
      local note_qn = entry.abs_qn or (start_qn + col * step_qn)
      local cell_qn = start_qn + col * step_qn
      if note_qn < cell_qn - 1e-9 then
        -- Occupancy-only cell for a spanning stutter; draw from the start cell.
      else
      local cell_reg = get_seq_region_by_id(entry.region_id) or seq_region_at_qn(note_qn) or region
      local pattern = get_seq_pattern(cell_reg and cell_reg.pattern_id, false)
      local item_x0, item_x1 = seq_note_item_x_range(
        note, slot, cell_reg, pattern, entry.key, note_qn, step_qn, qn_to_x, qn_to_x(note_qn + step_qn)
      )
      if not item_x0 then
        item_x0, item_x1 = cx0 + 2, cx1 - 2
      end
      if item_x1 <= item_x0 then
        item_x1 = item_x0 + 1
      end
      if is_stutter_lane then
        local accent = cell_selected and lane_style.accent or seq_lane_color_with_alpha(lane_style.accent, 58)
        draw_seq_stutter_lane_cell(dl, ctx, item_x0, item_x1, lane_top, lane_bot, value, accent)
      else
        local accent = cell_selected and lane_style.accent or seq_lane_color_with_alpha(lane_style.accent, 58)
        if not seq_draw_stutter_param_slices(
          dl, note, note_qn, def, step_qn, qn_to_x, lane_top, lane_bot, accent, cell_selected, nil
        ) then
          draw_seq_param_value_bar(dl, item_x0, item_x1, lane_top, lane_bot, def, value, step_qn, accent, cell_selected)
        end
      end
      local note_fx = get_seq_note_anim(entry.region_id, slot.id, entry.key, r.time_precise())
      if note_fx and note_fx.kind == "sync" then
        draw_seq_note_sync_flash(dl, item_x0, lane_top, item_x1, lane_bot, note_fx.t)
      end
      end
    end
  end
end

function seq_visible_cell_is_locked(slot, col, start_qn, step_qn, active_cells)
  if not slot then
    return false
  end
  local active = active_cells and active_cells[slot.id] and active_cells[slot.id][col]
  if active then
    local locked = false
    seq_for_each_active_note(active, function(entry)
      if seq_note_is_locked(entry.note) then
        locked = true
      end
    end)
    if locked then
      return true
    end
  end
  local cell_qn = start_qn + col * step_qn
  local lock_reg = seq_region_at_qn(cell_qn)
  if not lock_reg then
    return false
  end
  return seq_cell_is_locked(
    get_seq_pattern(lock_reg.pattern_id, false),
    slot.id,
    seq_region_step_key(lock_reg, cell_qn, step_qn)
  )
end

function seq_lock_span_cols(slot, col, start_qn, step_qn, step_count, active_cells)
  col = math.max(0, math.min((step_count or 1) - 1, col or 0))
  if not seq_visible_cell_is_locked(slot, col, start_qn, step_qn, active_cells) then
    return col, col
  end
  local lo, hi = col, col
  while lo > 0 and seq_visible_cell_is_locked(slot, lo - 1, start_qn, step_qn, active_cells) do
    lo = lo - 1
  end
  while hi < step_count - 1 and seq_visible_cell_is_locked(slot, hi + 1, start_qn, step_qn, active_cells) do
    hi = hi + 1
  end
  return lo, hi
end

function draw_seq_lock_icon(dl, cx, cy, size)
  size = math.max(12.0, size or 18.0)
  local half = size * 0.5
  r.ImGui_DrawList_AddRectFilled(dl, cx - half, cy - half, cx + half, cy + half, 0x10141CF5, 4.0)
  r.ImGui_DrawList_AddRect(dl, cx - half, cy - half, cx + half, cy + half, 0xF7FBFFFF, 4.0, 0, 1.5)
  local body_w = size * 0.44
  local body_h = size * 0.34
  local body_y = cy + size * 0.02
  r.ImGui_DrawList_AddRectFilled(dl, cx - body_w * 0.5, body_y, cx + body_w * 0.5, body_y + body_h, 0xFFFFFFFF, 1.8)
  local shackle_r = size * 0.16
  r.ImGui_DrawList_AddCircle(dl, cx, body_y, shackle_r, 0xFFFFFFFF, 14, 2.0)
end

function draw_seq_lock_span(dl, x0, y0, x1, y1, edit_mode, hovered)
  local pad = 3.0
  local sx0 = x0 + 1.0
  local sx1 = x1 - 1.0
  local sy0 = y0 + pad
  local sy1 = y1 - pad
  if sx1 <= sx0 + 2.0 then
    return
  end
  local fill = edit_mode and 0x0B1220B8 or 0x0B122096
  local wash = 0xF4F8FF28
  local outline = 0xF7FBFFFF
  local outline_w = 1.7
  if hovered then
    fill = 0x1A2438E0
    wash = 0xFFFFFF58
    outline = 0xFFFFFFFF
    outline_w = 2.3
  end
  r.ImGui_DrawList_AddRectFilled(dl, sx0, sy0, sx1, sy1, fill, 5.0)
  r.ImGui_DrawList_AddRectFilled(dl, sx0, sy0, sx1, sy1, wash, 5.0)
  if hovered then
    r.ImGui_DrawList_AddRect(dl, sx0 - 1.0, sy0 - 1.0, sx1 + 1.0, sy1 + 1.0, 0xFFFFFFF0, 5.0, 0, 1.6)
  end
  r.ImGui_DrawList_AddRect(dl, sx0, sy0, sx1, sy1, outline, 5.0, 0, outline_w)
  local w = sx1 - sx0
  local h = sy1 - sy0
  local icon = math.min(28.0, math.max(16.0, h * 0.64))
  if w < icon + 6.0 then
    icon = math.max(12.0, w - 6.0)
  end
  draw_seq_lock_icon(dl, (sx0 + sx1) * 0.5, (sy0 + sy1) * 0.5, icon)
end

function draw_seq_lock_spans(dl, slot, row_y0, row_y1, start_qn, step_qn, step_count, col_x0, col_x1, timeline_x0, timeline_x1, active_cells, edit_mode, hover_col)
  local run_start = nil
  local function flush(run_end)
    if not run_start then
      return
    end
    local x0 = math.max(timeline_x0, col_x0(run_start))
    local x1 = math.min(timeline_x1, col_x1(run_end))
    if x1 > x0 + 1.0 then
      local hovered = hover_col ~= nil and hover_col >= run_start and hover_col <= run_end
      draw_seq_lock_span(dl, x0, row_y0, x1, row_y1, edit_mode, hovered)
    end
    run_start = nil
  end
  for col = 0, step_count - 1 do
    if seq_visible_cell_is_locked(slot, col, start_qn, step_qn, active_cells) then
      if not run_start then
        run_start = col
      end
    else
      flush(col - 1)
    end
  end
  flush(step_count - 1)
end

function seq_visible_cell_vary_filter(slot, col, start_qn, step_qn)
  if not slot then
    return nil
  end
  local cell_qn = (start_qn or 0.0) + (col or 0) * (step_qn or 0.25)
  local reg = seq_region_at_qn(cell_qn)
  if not reg then
    return nil
  end
  return seq_cell_vary_filter(reg, slot.id, seq_region_step_key(reg, cell_qn, step_qn))
end

function seq_vary_filter_cell_key(slot, col, start_qn, step_qn)
  local edit = state.seq_vary_filter_edit
  if edit and slot and tostring(edit.track_id) == tostring(slot.id)
      and type(edit.col_min) == "number" and type(edit.col_max) == "number"
      and col >= edit.col_min and col <= edit.col_max then
    return "\0e:" .. seq_trim_text(edit.text or ""), true, seq_trim_text(edit.text or "")
  end
  local text = seq_visible_cell_vary_filter(slot, col, start_qn, step_qn)
  if text and text ~= "" then
    return text, false, text
  end
  return nil, false, nil
end

function seq_vary_filter_span_cols(slot, col, start_qn, step_qn, step_count)
  col = math.max(0, math.min((step_count or 1) - 1, col or 0))
  local key = seq_vary_filter_cell_key(slot, col, start_qn, step_qn)
  if not key then
    return col, col
  end
  local lo, hi = col, col
  while lo > 0 and seq_vary_filter_cell_key(slot, lo - 1, start_qn, step_qn) == key do
    lo = lo - 1
  end
  while hi < step_count - 1 and seq_vary_filter_cell_key(slot, hi + 1, start_qn, step_qn) == key do
    hi = hi + 1
  end
  return lo, hi
end

function draw_seq_vary_filter_span(dl, ctx, x0, y0, x1, y1, text, edit_mode, hovered, editing)
  local pad = 3.0
  local sx0 = x0 + 1.0
  local sx1 = x1 - 1.0
  local sy0 = y0 + pad
  local sy1 = y1 - pad
  if sx1 <= sx0 + 2.0 then
    return sx0, sy0, sx1, sy1
  end
  local no_hits = seq_vary_filter_has_no_hits(text)
  local fill = editing and 0x10261CB8 or (edit_mode and 0x0E1C16A8 or 0x0C181496)
  local wash = editing and 0x8FD98F55 or 0x8FD98F2A
  local outline = editing and 0xB6F0C8FF or 0x8FD98F99
  local outline_w = editing and 1.9 or 1.4
  if hovered and not editing then
    fill = 0x163024D0
    wash = 0x8FD98F48
    outline = 0xC8F8D8FF
    outline_w = 2.0
  end
  if no_hits then
    fill = editing and 0x2A1810C8 or (hovered and 0x241610D0 or 0x1C141096)
    wash = editing and 0xE8A02055 or 0xE8A02030
    outline = editing and 0xF0B848FF or (hovered and 0xF0C060FF or 0xE8A020CC)
    outline_w = editing and 2.0 or 1.6
  end
  r.ImGui_DrawList_AddRectFilled(dl, sx0, sy0, sx1, sy1, fill, 5.0)
  r.ImGui_DrawList_AddRectFilled(dl, sx0, sy0, sx1, sy1, wash, 5.0)
  r.ImGui_DrawList_AddRect(dl, sx0, sy0, sx1, sy1, outline, 5.0, 0, outline_w)
  local warn_w = 0.0
  if no_hits then
    local mark = "!"
    local mw = select(1, r.ImGui_CalcTextSize(ctx, mark)) or 6.0
    warn_w = mw + 5.0
    local mx = sx1 - mw - 3.0
    local my = sy0 + 1.0
    r.ImGui_DrawList_AddText(dl, mx + 1, my + 1, 0x00000099, mark)
    r.ImGui_DrawList_AddText(dl, mx, my, 0xFFD080FF, mark)
  end
  if text and text ~= "" and not editing then
    local label = text
    local tw, th = r.ImGui_CalcTextSize(ctx, label)
    local max_w = (sx1 - sx0) - 8.0 - warn_w
    if tw > max_w and max_w > 12.0 then
      while #label > 1 and tw > max_w do
        label = label:sub(1, #label - 1)
        tw = select(1, r.ImGui_CalcTextSize(ctx, label .. "…")) or tw
      end
      label = label .. "…"
      tw = select(1, r.ImGui_CalcTextSize(ctx, label)) or tw
    end
    if tw <= (sx1 - sx0) - 4.0 - warn_w then
      local tx = sx0 + 4.0
      local ty = sy0 + 2.0
      r.ImGui_DrawList_AddText(dl, tx + 1, ty + 1, 0x00000099, label)
      r.ImGui_DrawList_AddText(dl, tx, ty, no_hits and 0xFFE8C0FF or 0xE8FFEEFF, label)
    end
  end
  return sx0, sy0, sx1, sy1
end

function draw_seq_vary_filter_spans(dl, ctx, slot, row_y0, row_y1, start_qn, step_qn, step_count, col_x0, col_x1, timeline_x0, timeline_x1, edit_mode, hover_col)
  local edit = state.seq_vary_filter_edit
  if edit and slot and tostring(edit.track_id) == tostring(slot.id) then
    edit.x0, edit.y0, edit.x1, edit.y1 = nil, nil, nil, nil
  end
  local run_start, run_key, run_text, run_editing = nil, nil, nil, false
  local function flush(run_end)
    if not run_start then
      return
    end
    local x0 = math.max(timeline_x0, col_x0(run_start))
    local x1 = math.min(timeline_x1, col_x1(run_end))
    if x1 > x0 + 1.0 then
      local hovered = hover_col ~= nil and hover_col >= run_start and hover_col <= run_end
      local sx0, sy0, sx1, sy1 = draw_seq_vary_filter_span(
        dl, ctx, x0, row_y0, x1, row_y1, run_text, edit_mode, hovered, run_editing
      )
      if hovered and not run_editing and seq_vary_filter_has_no_hits(run_text)
          and r.ImGui_SetTooltip then
        r.ImGui_SetTooltip(ctx, "No samples match this filter")
      end
      local edit = state.seq_vary_filter_edit
      if run_editing and edit and tostring(edit.track_id) == tostring(slot.id) then
        edit.x0, edit.y0, edit.x1, edit.y1 = sx0, sy0, sx1, sy1
      end
    end
    run_start, run_key, run_text, run_editing = nil, nil, nil, false
  end
  for col = 0, step_count - 1 do
    local key, editing, text = seq_vary_filter_cell_key(slot, col, start_qn, step_qn)
    if key then
      if run_start and key ~= run_key then
        flush(col - 1)
      end
      if not run_start then
        run_start = col
        run_key = key
        run_text = text
        run_editing = editing
      end
    else
      flush(col - 1)
    end
  end
  flush(step_count - 1)
end

function render_seq_vary_filter_input()
  local edit = state.seq_vary_filter_edit
  if not edit or not ctx then
    return
  end
  if state.seq_param_drag and state.seq_param_drag.param == "vary_filter" then
    return
  end
  if type(edit.x0) ~= "number" or type(edit.x1) ~= "number" then
    return
  end
  local x0, y0 = edit.x0, edit.y0 or 0
  local min_w = 108.0
  local w = math.max(min_w, math.min(220.0, (edit.x1 - x0)))
  if r.ImGui_SetNextFrameWantCaptureKeyboard then
    r.ImGui_SetNextFrameWantCaptureKeyboard(ctx, true)
  end
  local restore_x, restore_y = r.ImGui_GetCursorScreenPos(ctx)
  r.ImGui_SetCursorScreenPos(ctx, x0, y0 - 1.0)
  r.ImGui_SetNextItemWidth(ctx, w)
  local first_focus = edit.focus
  if first_focus and r.ImGui_SetKeyboardFocusHere then
    r.ImGui_SetKeyboardFocusHere(ctx)
    edit.focus = false
  end
  local flags = 0
  if r.ImGui_InputTextFlags_EnterReturnsTrue then
    flags = flags | r.ImGui_InputTextFlags_EnterReturnsTrue()
  end
  if first_focus and r.ImGui_InputTextFlags_AutoSelectAll and edit.orig and edit.orig ~= "" then
    flags = flags | r.ImGui_InputTextFlags_AutoSelectAll()
  end
  local no_hits = seq_vary_filter_has_no_hits(edit.text)
  local style_cols, style_vars = 0, 0
  if r.ImGui_Col_FrameBg then
    if no_hits then
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBg(), 0x2A1810EE)
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgHovered(), 0x321C12EE)
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgActive(), 0x3A2216EE)
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Text(), 0xFFE8C0FF)
    else
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBg(), 0x10261CEE)
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgHovered(), 0x163024EE)
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgActive(), 0x1C3A2CEE)
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Text(), 0xE8FFEEFF)
    end
    style_cols = 4
    if r.ImGui_Col_Border then
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Border(), no_hits and 0xE8A020FF or 0x8FD98F99)
      style_cols = style_cols + 1
    end
  end
  if r.ImGui_StyleVar_FramePadding then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FramePadding(), 4, 1)
    style_vars = style_vars + 1
  end
  if no_hits and r.ImGui_StyleVar_FrameBorderSize then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FrameBorderSize(), 1.0)
    style_vars = style_vars + 1
  end
  local submitted, txt
  if r.ImGui_InputTextWithHint then
    submitted, txt = r.ImGui_InputTextWithHint(ctx, "##seq_vary_filter", "type to filter", edit.text or "", flags)
  else
    submitted, txt = r.ImGui_InputText(ctx, "##seq_vary_filter", edit.text or "", flags)
  end
  seq_mark_text_input_item()
  edit.hovered = r.ImGui_IsItemHovered(ctx) and true or false
  if type(txt) == "string" then
    edit.text = txt
    no_hits = seq_vary_filter_has_no_hits(edit.text)
  end
  if no_hits then
    local ix0, iy0 = r.ImGui_GetItemRectMin(ctx)
    local ix1, iy1 = r.ImGui_GetItemRectMax(ctx)
    local idl = r.ImGui_GetWindowDrawList(ctx)
    if idl then
      r.ImGui_DrawList_AddText(idl, ix1 - 11, iy0 + 1, 0xFFD080FF, "!")
    end
    if edit.hovered and r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, "No samples match this filter")
    end
  end
  if style_vars > 0 then
    r.ImGui_PopStyleVar(ctx, style_vars)
  end
  if style_cols > 0 then
    r.ImGui_PopStyleColor(ctx, style_cols)
  end
  local escape = r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
    and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false)
  local enter = submitted or (r.ImGui_IsKeyPressed and r.ImGui_Key_Enter
    and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Enter(), false))
  if escape then
    seq_cancel_vary_filter_edit()
  elseif enter then
    seq_commit_vary_filter_edit()
  end
  r.ImGui_SetCursorScreenPos(ctx, restore_x, restore_y)
end

function draw_seq_note_param_mode_overlay(dl, ctx, def, value, cx0, cx1, y0, y1, step_qn, accent, selected)
  if not def then
    return
  end
  local lane_top = y0 + 2
  local lane_bot = y1 - 2
  if seq_is_span_overlay_def(def) then
    return
  end
  if def.key == "stutter" then
    if value == nil then
      value = def.default
    end
    draw_seq_stutter_lane_cell(dl, ctx, cx0, cx1, lane_top, lane_bot, value, accent)
    return
  end
  draw_seq_param_value_bar(dl, cx0, cx1, lane_top, lane_bot, def, value, step_qn, accent, selected)
end

function seq_edit_mode_accent(param_key)
  if not param_key then
    return UI_THEME.accent
  end
  local style = get_seq_row_lane_style({ type = "param", param = { key = param_key } })
  return (style and style.accent) or UI_THEME.accent
end

function seq_note_edit_mode_tooltip(def)
  if not def then
    return string.format(
      "Paint and erase notes (%s)\nAlt+LMB drag = stutter (horizontal = length, vertical = count)\nDrag the stutter number = hits (vertical) or skew (horizontal)\nCtrl/Cmd+LMB drag on a note = copy (keeps sample, including region variation)\nShift+empty grid = place off-grid (click inserts at the pointer)\nShift+LMB drag on a note = move off-grid\nDrag the border between tracks to set individual heights\n%s = enlarge hovered track (again to restore)\nAlt+RMB drag = razor edit\nAlt+Ctrl+RMB drag = add razor area\nLMB drag on razor = move notes\nCtrl/Cmd+LMB drag on razor = copy notes",
      shortcut_display("cancel"),
      shortcut_display("enlarge_track")
    )
  end
  local hotkey = (def.shortcut_id and shortcut_display(def.shortcut_id)) or def.hotkey or ""
  if seq_is_decay_def(def) then
    return "Decay mode (" .. hotkey .. ")\nDrag the last grid / end line to set note length (Shift = unsnap)\nDrag start/end circles for fade length (vertical = fade type)\nDrag the fade curve to change native curvature\nDragging a fade past the other fade pushes it out of the way\nRMB on a handle = reset"
  end
  if seq_is_stutter_def(def) then
    return "Stutter mode (" .. hotkey .. ")\nDrag vertically to change hit count (no click-to-jump)\nDrag horizontally to skew timing\nThe first move locks the axis\nRMB = reset count and skew"
  end
  if seq_is_lock_def(def) then
    return "Lock mode (" .. hotkey .. ")\nClick a note or empty cell to lock it\nDrag to lock a range of notes and empty grids\nRMB click a lock = unlock the whole area\nRMB drag = unlock only the cells you sweep"
  end
  if seq_is_vary_def(def) then
    return "Variation mode (" .. hotkey .. ")\nLMB drag on notes = set how far the sample can wander on the map\nRMB drag on notes = reset to the track sample\n" .. shortcut_display("pick_note_sample") .. " = open the mini map and click a sample to swap the hovered note\nWith a razor, that swap applies to every note inside it"
  end
  if seq_is_vary_filter_def(def) then
    return "Vary filter mode (" .. hotkey .. ")\nClick or drag a grid area, type a word (lofi, robot…), then Enter\nVariation on those grids prefers matching filenames and tags\nRMB click a filter = clear the whole area\nRMB drag = clear only the cells you sweep"
  end
  return string.format(
    "%s mode (%s)\nLMB drag on notes = set value\nRMB drag on notes = reset to default\nOn stutter notes, each slice can be edited separately",
    def.mode_name or def.label, hotkey
  )
end

function seq_segmented_bar_metrics(items, h)
  h = h or 26
  local rounding = 7.0
  local max_tw = 0
  for _, it in ipairs(items or {}) do
    local tw = select(1, r.ImGui_CalcTextSize(ctx, it.label or "")) or 0
    if tw > max_tw then
      max_tw = tw
    end
  end
  local cell_w = math.max(30, math.floor(max_tw + 12 + 0.5))
  local n = #(items or {})
  local side = math.max(math.floor(rounding + 0.5), 6)
  return side * 2 + cell_w * n, cell_w, side, h, rounding
end

function seq_draw_segmented_bar(bar_id, items, h, opts)
  opts = opts or {}
  items = items or {}
  h = h or 26
  local n = #items
  if n == 0 then
    return nil
  end
  local group_w, cell_w, side, _, rounding = seq_segmented_bar_metrics(items, h)
  if not opts.first then
    imgui_same_line_if_fits(group_w, opts.gap or 8)
  end

  local gx, gy = r.ImGui_GetCursorScreenPos(ctx)
  gx, gy = math.floor(gx + 0.5), math.floor(gy + 0.5)
  local x1, y1 = gx + group_w, gy + h
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local content_x0 = gx + side
  local inner_y0 = gy + 2
  local inner_y1 = y1 - 2

  r.ImGui_DrawList_AddRectFilled(dl, gx, gy, x1, y1, 0x0B0F0CFF, rounding)
  r.ImGui_DrawList_AddRectFilled(dl, gx + 1, gy + 1, x1 - 1, y1 - 1, 0x141A16FF, rounding - 1)
  r.ImGui_DrawList_AddLine(dl, gx + rounding, gy + 1.2, x1 - rounding, gy + 1.2, 0x00000077, 1.0)
  r.ImGui_DrawList_AddLine(dl, gx + rounding, y1 - 1.6, x1 - rounding, y1 - 1.6, 0xFFFFFF0C, 1.0)
  r.ImGui_DrawList_AddRect(dl, gx + 0.5, gy + 0.5, x1 - 0.5, y1 - 0.5, UI_THEME.border, rounding, 0, 1.0)

  local clicked_item = nil
  for i, it in ipairs(items) do
    local sx0 = content_x0 + (i - 1) * cell_w
    local sx1 = sx0 + cell_w
    r.ImGui_SetCursorScreenPos(ctx, sx0, inner_y0)
    r.ImGui_InvisibleButton(ctx, "##" .. tostring(bar_id) .. "_" .. tostring(it.id), cell_w, inner_y1 - inner_y0)
    local hovered = r.ImGui_IsItemHovered(ctx)
    local pressed = r.ImGui_IsItemActive(ctx)
    local clicked = r.ImGui_IsItemClicked(ctx, 0)
    local pill_round = 5.0
    local accent = it.accent or UI_THEME.accent
    local cr, cg, cb = extract_rgb_rrgbbaa(accent)
    local function tone(t, a)
      return build_color_rrgbbaa(
        math.max(0, math.min(255, math.floor(cr * t))),
        math.max(0, math.min(255, math.floor(cg * t))),
        math.max(0, math.min(255, math.floor(cb * t))),
        a or 255
      )
    end

    if it.selected then
      local fill = build_color_rrgbbaa(
        math.max(0, math.min(255, math.floor(18 + cr * 0.16))),
        math.max(0, math.min(255, math.floor(22 + cg * 0.20))),
        math.max(0, math.min(255, math.floor(18 + cb * 0.16))),
        255
      )
      r.ImGui_DrawList_AddRectFilled(dl, sx0 + 2, inner_y0 + 1, sx1 - 2, inner_y1 - 1, fill, pill_round)
      r.ImGui_DrawList_AddLine(dl, sx0 + 6, inner_y0 + 2.2, sx1 - 6, inner_y0 + 2.2, 0xFFFFFF2A, 1.0)
      r.ImGui_DrawList_AddRect(dl, sx0 + 2.5, inner_y0 + 1.5, sx1 - 2.5, inner_y1 - 1.5, tone(0.85, 150), pill_round, 0, 1.0)
      local dash_w = math.min(12.0, cell_w * 0.34)
      local dash_x = sx0 + (cell_w - dash_w) * 0.5
      r.ImGui_DrawList_AddRectFilled(dl, dash_x, inner_y1 - 3.4, dash_x + dash_w, inner_y1 - 2.0, accent, 1.2)
    elseif pressed then
      r.ImGui_DrawList_AddRectFilled(dl, sx0 + 2, inner_y0 + 1, sx1 - 2, inner_y1 - 1, 0xFFFFFF12, pill_round)
    elseif hovered then
      r.ImGui_DrawList_AddRectFilled(dl, sx0 + 2, inner_y0 + 1, sx1 - 2, inner_y1 - 1, 0xFFFFFF16, pill_round)
    end

    if i < n then
      local nxt = items[i + 1]
      if not it.selected and not (nxt and nxt.selected) then
        r.ImGui_DrawList_AddLine(dl, sx1, inner_y0 + 5, sx1, inner_y1 - 5, 0xFFFFFF14, 1.0)
      end
    end

    local label = it.label or ""
    local tw, th = r.ImGui_CalcTextSize(ctx, label)
    local text_col = it.selected and 0xF7FFF9FF or (hovered and UI_THEME.text or UI_THEME.text_dim)
    local press = (pressed and not it.selected) and 1.0 or 0.0
    r.ImGui_DrawList_AddText(
      dl,
      sx0 + (cell_w - tw) * 0.5,
      inner_y0 + ((inner_y1 - inner_y0) - th) * 0.5 + press,
      text_col,
      label
    )

    if hovered and it.tooltip then
      r.ImGui_SetTooltip(ctx, it.tooltip)
    end
    if clicked then
      clicked_item = it
    end
  end

  r.ImGui_SetCursorScreenPos(ctx, gx + group_w, gy)
  r.ImGui_Dummy(ctx, 1, h)
  return clicked_item
end

function seq_draw_razor_badge(btn_h)
  local count = state.seq_razors and #state.seq_razors or 0
  if state.seq_razor_drag and state.seq_razor_drag.mode ~= "move" then
    count = count + 1
  end
  local label = string.format("Razor ×%d", count)
  local tw, th = r.ImGui_CalcTextSize(ctx, label)
  local pad_x, pad_y = 8.0, 3.0
  local w = tw + pad_x * 2
  local h = math.min(btn_h or 26, th + pad_y * 2)
  if not imgui_same_line_if_fits(w, 8) then
    return
  end
  local cx, cy = r.ImGui_GetCursorScreenPos(ctx)
  r.ImGui_SetCursorScreenPos(ctx, cx, cy + ((btn_h or 26) - h) * 0.5)
  r.ImGui_InvisibleButton(ctx, "##seq_razor_badge", w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local x0, iy0 = r.ImGui_GetItemRectMin(ctx)
  local x1, iy1 = r.ImGui_GetItemRectMax(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local fill = hovered and 0x1A3A44FF or 0x122830FF
  r.ImGui_DrawList_AddRectFilled(dl, x0, iy0, x1, iy1, fill, 6.0)
  r.ImGui_DrawList_AddRect(dl, x0 + 0.5, iy0 + 0.5, x1 - 0.5, iy1 - 0.5, SEQ_RAZOR_EDGE, 6.0, 0, 1.2)
  r.ImGui_DrawList_AddText(dl, x0 + pad_x, iy0 + (h - th) * 0.5, SEQ_RAZOR_EDGE, label)
  if hovered then
    r.ImGui_SetTooltip(ctx, string.format(
      "LMB move  ·  Ctrl/Cmd+LMB copy  ·  %s erase  ·  %s clear  ·  %s pick sample",
      shortcut_display("delete_razor"),
      shortcut_display("cancel"),
      shortcut_display("pick_note_sample")
    ))
  end
end

function render_seq_note_edit_mode_bar(btn_h)
  btn_h = btn_h or 26
  local active_def = get_seq_note_edit_mode_def()
  local items = {
    {
      id = "notes",
      label = "Notes",
      selected = not active_def,
      accent = seq_edit_mode_accent(nil),
      tooltip = seq_note_edit_mode_tooltip(nil),
    },
  }
  for _, def in ipairs(seq_note_edit_mode_defs()) do
    items[#items + 1] = {
      id = def.key,
      key = def.key,
      label = def.label,
      selected = active_def and active_def.key == def.key,
      accent = seq_edit_mode_accent(def.key),
      tooltip = seq_note_edit_mode_tooltip(def),
    }
  end
  local clicked = seq_draw_segmented_bar("seq_edit_mode", items, btn_h, { gap = 6 })
  if clicked then
    if clicked.key then
      seq_toggle_note_edit_mode(clicked.key)
    else
      seq_set_note_edit_mode(nil)
    end
  end
  if seq_has_razors() or state.seq_razor_drag then
    seq_draw_razor_badge(btn_h)
  end
end

function render_seq_top_toolbar()
  local btn_h = 26
  local inner_h = btn_h - 6
  local pocket_pad = 4
  local inner_gap = 3
  local grids = {
    { "1/4", 1.0, "seq_grid_4" },
    { "1/8", 0.5, "seq_grid_8" },
    { "1/16", 0.25, "seq_grid_16" },
    { "1/32", 0.125, "seq_grid_32" },
    { "1/8T", 1.0 / 3.0, "seq_grid_8t" },
    { "1/16T", 1.0 / 6.0, "seq_grid_16t" },
  }

  local function toolbar_button(id, label, opts, tooltip)
    opts = opts or {}
    opts.compact = true
    local clicked = draw_ui_button(id, label, nil, btn_h, opts)
    if tooltip and r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, tooltip)
    end
    return clicked
  end

  local function toolbar_divider()
    if not imgui_same_line_if_fits(7, 8) then
      return
    end
    local x, y0 = r.ImGui_GetCursorScreenPos(ctx)
    r.ImGui_Dummy(ctx, 1, btn_h)
    local dl = r.ImGui_GetWindowDrawList(ctx)
    r.ImGui_DrawList_AddLine(dl, x, y0 + 5, x, y0 + btn_h - 5, UI_THEME.border, 1.0)
  end

  local grid_items = {}
  for _, grid in ipairs(grids) do
    grid_items[#grid_items + 1] = {
      id = grid[3],
      label = grid[1],
      selected = math.abs((state.seq_grid_qn or 0.25) - grid[2]) < 0.0001,
      accent = UI_THEME.accent,
      tooltip = "Grid " .. grid[1],
      qn = grid[2],
    }
  end
  local grid_clicked = seq_draw_segmented_bar("seq_grid", grid_items, btn_h, { first = true, gap = 8 })
  if grid_clicked then
    state.seq_grid_qn = grid_clicked.qn
    save_config()
  end

  toolbar_divider()
  local focus_region = get_selected_seq_region()
  if state.seq_region_rename and focus_region and state.seq_region_rename.region_id ~= focus_region.id then
    seq_commit_region_rename()
  end
  local renaming = state.seq_region_rename
    and focus_region
    and state.seq_region_rename.region_id == focus_region.id
  local region_name = get_seq_region_display_name(focus_region)
  local region_chip = seq_truncate_text_to_width(region_name, 96)
  state.seq_gen_style = normalize_seq_gen_style(state.seq_gen_style)
  local pattern_label = get_seq_region_pattern_label(focus_region)
  local groove_key = get_seq_region_groove(focus_region)
  local groove_active = groove_key ~= "off"
  local groove_label = get_seq_groove_chip_label(groove_key)
  local name_w = calc_compact_chip_width(region_chip) + 6
  if renaming then
    local typed = state.seq_region_rename.text or ""
    local measure = typed ~= "" and typed or "Intro 1"
    local tw = select(1, r.ImGui_CalcTextSize(ctx, measure)) or 0
    name_w = math.max(150, tw + 28)
  end
  local pat_w = calc_compact_chip_width(pattern_label)
  local grv_w = calc_compact_chip_width(groove_label)
  local pocket_w = pocket_pad + pat_w + inner_gap + grv_w + pocket_pad
  local group_w = name_w + pocket_w
  imgui_same_line_if_fits(group_w, 8)
  do
    local gx, gy = r.ImGui_GetCursorScreenPos(ctx)
    local dl = r.ImGui_GetWindowDrawList(ctx)
    local pool = seq_region_pool_color(focus_region and focus_region.pool_id, 255)
    local cr, cg, cb = extract_rgb_rrgbbaa(pool)
    local function tone(t, a)
      return build_color_rrgbbaa(
        math.max(0, math.min(255, math.floor(cr * t))),
        math.max(0, math.min(255, math.floor(cg * t))),
        math.max(0, math.min(255, math.floor(cb * t))),
        a or 255
      )
    end
    local rounding = 8.0
    r.ImGui_DrawList_AddRectFilled(dl, gx, gy, gx + group_w, gy + btn_h, tone(0.16), rounding)
    r.ImGui_DrawList_AddRectFilled(dl, gx, gy, gx + name_w + rounding, gy + btn_h, tone(0.38), rounding)
    r.ImGui_DrawList_AddRectFilled(dl, gx + name_w, gy, gx + name_w + rounding, gy + btn_h, tone(0.16), 0)
    r.ImGui_DrawList_AddRect(dl, gx + 0.5, gy + 0.5, gx + group_w - 0.5, gy + btn_h - 0.5, tone(0.95), rounding, 0, 1.6)
    r.ImGui_DrawList_AddLine(dl, gx + name_w, gy + 4, gx + name_w, gy + btn_h - 4, tone(0.75, 180), 1.0)

    if renaming then
      if r.ImGui_SetNextFrameWantCaptureKeyboard then
        r.ImGui_SetNextFrameWantCaptureKeyboard(ctx, true)
      end
      r.ImGui_SetCursorScreenPos(ctx, gx + 4, gy + 2)
      r.ImGui_SetNextItemWidth(ctx, name_w - 8)
      local first_focus = state.seq_region_rename.focus
      if first_focus then
        if r.ImGui_SetKeyboardFocusHere then
          r.ImGui_SetKeyboardFocusHere(ctx)
        end
        state.seq_region_rename.focus = false
      end
      local input_flags = 0
      if first_focus and r.ImGui_InputTextFlags_AutoSelectAll then
        input_flags = input_flags | r.ImGui_InputTextFlags_AutoSelectAll()
      end
      local input_value = state.seq_region_rename.typed_prefix
      if input_value == nil then
        input_value = state.seq_region_rename.text or ""
      end
      local completing = state.seq_region_rename.completed == true
      local style_cols, style_vars = 0, 0
      if r.ImGui_Col_FrameBg then
        r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBg(), 0x00000066)
        r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgHovered(), 0x00000088)
        r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgActive(), 0x00000099)
        r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Text(), completing and 0xFFFFFF00 or 0xFFFFFFFF)
        style_cols = 4
      end
      if r.ImGui_StyleVar_FramePadding then
        r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FramePadding(), 4, 2)
        style_vars = style_vars + 1
      end
      local _, txt = r.ImGui_InputText(ctx, "##seq_region_rename", input_value, input_flags)
      seq_mark_text_input_item()
      local edit_x, edit_y = r.ImGui_GetItemRectMin(ctx)
      local edit_x1, edit_y1 = r.ImGui_GetItemRectMax(ctx)
      local edit_hovered = r.ImGui_IsItemHovered(ctx)
      if style_vars > 0 then
        r.ImGui_PopStyleVar(ctx, style_vars)
      end
      if style_cols > 0 then
        r.ImGui_PopStyleColor(ctx, style_cols)
      end
      local arrow_down = r.ImGui_IsKeyPressed and r.ImGui_Key_DownArrow
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_DownArrow(), false)
      local arrow_up = r.ImGui_IsKeyPressed and r.ImGui_Key_UpArrow
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_UpArrow(), false)
      if arrow_down or arrow_up then
        seq_region_rename_move_candidate(state.seq_region_rename, focus_region, arrow_down and 1 or -1)
      elseif type(txt) == "string" then
        if first_focus and txt == (state.seq_region_rename.orig or "") then
          state.seq_region_rename.text = txt
        else
          seq_apply_region_rename_autocomplete(state.seq_region_rename, txt, focus_region)
        end
      end
      if state.seq_region_rename and state.seq_region_rename.completed then
        seq_draw_region_rename_completion(state.seq_region_rename, edit_x, edit_y, edit_x1, edit_y1)
        if r.ImGui_IsKeyPressed and r.ImGui_Key_Tab
            and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Tab(), false) then
          state.seq_region_rename.typed_prefix = state.seq_region_rename.text
          state.seq_region_rename.completed = false
          state.seq_region_rename.select_from = 0
        end
      end
      local edit_w = (edit_x1 or (gx + name_w)) - (edit_x or gx)
      local enter = r.ImGui_IsKeyPressed and r.ImGui_Key_Enter
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Enter(), false)
      local escape = r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false)
      local click_outside = r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 0)
        and not edit_hovered
        and not (state.seq_region_rename and state.seq_region_rename.over_suggest)
      if escape then
        seq_cancel_region_rename()
      elseif enter then
        seq_commit_region_rename()
      elseif click_outside then
        seq_commit_region_rename()
      end
      if state.seq_region_rename then
        render_seq_region_name_suggest_popup(edit_x or gx, edit_y or gy, edit_w)
      end
    else
      r.ImGui_InvisibleButton(ctx, "##ui_seq_focus_region_chip", name_w, btn_h)
      local cap_hovered = r.ImGui_IsItemHovered(ctx)
      local cap_clicked = r.ImGui_IsItemClicked(ctx, 0)
      local cap_dbl = cap_hovered and r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0)
      if cap_hovered then
        r.ImGui_DrawList_AddRectFilled(dl, gx, gy, gx + name_w + rounding, gy + btn_h, tone(0.50, 70), rounding)
        r.ImGui_SetTooltip(ctx, "Focused region — pattern and groove apply here only.\nClick to zoom. Double-click to rename.")
      end
      local tw, th = r.ImGui_CalcTextSize(ctx, region_chip)
      r.ImGui_DrawList_AddText(dl, gx + (name_w - tw) * 0.5, gy + (btn_h - th) * 0.5, 0xFFFFFFFF, region_chip)
      if cap_dbl then
        seq_begin_region_rename(focus_region)
      elseif cap_clicked then
        seq_zoom_to_region(focus_region)
      end
    end

    local inner_y = gy + (btn_h - inner_h) * 0.5
    r.ImGui_SetCursorScreenPos(ctx, gx + name_w + pocket_pad, inner_y)
    if draw_ui_button("seq_pattern_popup_open", pattern_label, nil, inner_h, {
      compact = true,
      style = "primary",
      selected = state.seq_pattern_window_open,
    }) then
      open_seq_pattern_popup()
    end
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, "Pattern for " .. region_name)
    end
    r.ImGui_SameLine(ctx, 0, inner_gap)
    if draw_ui_button("seq_groove_popup_open", groove_label, nil, inner_h, {
      compact = true,
      style = "primary",
      selected = groove_active,
    }) then
      r.ImGui_OpenPopup(ctx, "seq_groove_popup")
    end
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, "Groove for " .. region_name .. " — this region only")
    end

    r.ImGui_SetCursorScreenPos(ctx, gx + group_w, gy)
    r.ImGui_Dummy(ctx, 1, btn_h)
  end
  render_seq_groove_popup()

  toolbar_divider()
  imgui_same_line_if_fits(calc_compact_chip_width("Kit"), 4)
  if toolbar_button("seq_kit_random_popup_open", "Kit", { style = "primary" }, "Randomize Kit") then
    open_seq_kit_random_popup()
  end
  render_seq_kit_random_popup()

  imgui_same_line_if_fits(calc_compact_chip_width("Sync"), 4)
  local sync_on = state.seq_follow_arrange == true
  if toolbar_button("seq_sync", "Sync", { style = sync_on and "accent" or "default", selected = sync_on }, "Sync to Arrange") then
    state.seq_follow_arrange = not sync_on
    seq_timeline_scroll_stop()
    if state.seq_follow_arrange then
      local arrange_start, arrange_end = get_arrange_view_range()
      local arrange_start_qn = time_to_qn(arrange_start) or 0.0
      local arrange_end_qn = time_to_qn(arrange_end) or (arrange_start_qn + (state.seq_grid_qn or 0.25) * 16.0)
      state.seq_view_start_qn = arrange_start_qn
      state.seq_view_span_qn = math.max(state.seq_grid_qn or 0.25, arrange_end_qn - arrange_start_qn)
    end
    save_config()
  end

  imgui_same_line_if_fits(calc_compact_chip_width("Peek"), 4)
  local peek_on = state.seq_follow_hovered_item == true
  if toolbar_button("seq_peek_item", "Peek", { style = peek_on and "accent" or "default", selected = peek_on }, "Follow hovered notes in the arrange") then
    state.seq_follow_hovered_item = not peek_on
    save_config()
  end

  toolbar_divider()
  render_seq_note_edit_mode_bar(btn_h)
end

function seq_param_value_from_y(def, y, y0, y1, step_qn)
  if def.boolean or seq_is_lock_def(def) then
    return def.max or 1.0
  end
  local t = 1.0 - ((y - y0) / math.max(1.0, y1 - y0))
  t = math.max(0.0, math.min(1.0, t))
  local min_v = def.min
  local max_v = def.max
  if def.key == "length_qn" then
    min_v = math.min(step_qn or state.seq_grid_qn or 0.25, def.min)
    max_v = math.max(step_qn or state.seq_grid_qn or 0.25, def.max)
  elseif def.key == "stretch" then
    -- Log scale so 1.0x sits in the middle (0.25x .. 4.0x).
    return SEQ_STRETCH_MIN * ((SEQ_STRETCH_MAX / SEQ_STRETCH_MIN) ^ t)
  end
  return min_v + (max_v - min_v) * t
end

function seq_param_y_from_value(def, value, y0, y1, step_qn)
  local min_v = def.min
  local max_v = def.max
  if def.key == "length_qn" then
    min_v = math.min(step_qn or state.seq_grid_qn or 0.25, def.min)
    max_v = math.max(step_qn or state.seq_grid_qn or 0.25, def.max)
  elseif def.key == "stretch" then
    local v = tonumber(value) or 1.0
    if v < SEQ_STRETCH_MIN then v = SEQ_STRETCH_MIN end
    if v > SEQ_STRETCH_MAX then v = SEQ_STRETCH_MAX end
    local t = math.log(v / SEQ_STRETCH_MIN) / math.log(SEQ_STRETCH_MAX / SEQ_STRETCH_MIN)
    t = math.max(0.0, math.min(1.0, t))
    return y1 - t * (y1 - y0)
  end
  local t = ((value or def.default) - min_v) / math.max(0.000001, max_v - min_v)
  t = math.max(0.0, math.min(1.0, t))
  return y1 - t * (y1 - y0)
end

function seq_get_project_first_measure()
  -- Project Settings → "Project start measure". TimeMap measure 0 is always
  -- the first bar; the displayed number can be 1 (default), 0, -1, etc.
  if r.format_timestr_pos and r.TimeMap_GetMeasureInfo then
    local meas_time, qn_start = r.TimeMap_GetMeasureInfo(0, 0)
    if type(qn_start) == "number" then
      local nudged = qn_to_time(qn_start + 0.0001)
      if type(nudged) == "number" then
        meas_time = nudged
      end
    end
    if type(meas_time) == "number" then
      local formatted = r.format_timestr_pos(meas_time, "", 2)
      local n = tonumber((formatted or ""):match("^%s*(-?%d+)"))
      if n then
        return n
      end
    end
  end
  -- SWS: projmeasoffs is 0 when the first displayed measure is 1.
  if r.SNM_GetIntConfigVarEx then
    return (r.SNM_GetIntConfigVarEx(0, "projmeasoffs", 0) or 0) + 1
  end
  if r.SNM_GetIntConfigVar then
    return (r.SNM_GetIntConfigVar("projmeasoffs", 0) or 0) + 1
  end
  return 1
end

function collect_measure_guides_qn(start_qn, end_qn, max_guides)
  local guides = {}
  if not r.TimeMap_GetMeasureInfo or not r.TimeMap2_timeToBeats then
    return guides
  end

  local start_time = qn_to_time(start_qn)
  if not start_time then
    return guides
  end

  max_guides = max_guides or 1024
  local _, start_measure = r.TimeMap2_timeToBeats(0, start_time)
  if start_measure == nil then
    return guides
  end

  local first_measure = seq_get_project_first_measure()
  local measure = math.max(0, start_measure)
  local guard = 0
  while guard < max_guides do
    local meas_time, qn_start, qn_end, ts_num, ts_den = r.TimeMap_GetMeasureInfo(0, measure)
    if not meas_time or not qn_start then
      break
    end
    if qn_start > end_qn + 0.000001 then
      break
    end

    local out_num = (type(ts_num) == "number" and ts_num > 0) and ts_num or 4
    local out_den = (type(ts_den) == "number" and ts_den > 0) and ts_den or 4
    local out_qn_end = qn_end
    if type(out_qn_end) ~= "number" or out_qn_end <= qn_start then
      out_qn_end = qn_start + out_num * (4.0 / out_den)
    end

    if out_qn_end >= start_qn - 0.000001 then
      guides[#guides + 1] = {
        measure = measure,
        display_measure = measure + first_measure,
        qn_start = qn_start,
        qn_end = out_qn_end,
        time = meas_time,
        ts_num = out_num,
        ts_den = out_den,
      }
    end

    measure = measure + 1
    guard = guard + 1
  end

  return guides
end

function find_seq_param_lane_bounds(row_positions, track_id, param_key)
  for _, row_pos in ipairs(row_positions) do
    local row = row_pos.row
    if row.type == "param" and row.slot and row.slot.id == track_id and row.param and row.param.key == param_key then
      return row_pos.y0 + 2, row_pos.y1 - 2, row_pos
    end
  end
  return nil, nil, nil
end

function format_seq_param_value(def, value)
  if value == nil then
    value = def.default
  end
  if def.boolean or seq_is_lock_def(def) then
    local on = value == true or (tonumber(value) or 0) >= 0.5
    return string.format("%s %s", def.label, on and "On" or "Off")
  end
  if def.key == "start" then
    return string.format("%s %.0f%%", def.label, (tonumber(value) or 0.0) * 100.0)
  end
  if def.key == "stretch" then
    return string.format("%s %.2fx", def.label, tonumber(value) or 1.0)
  end
  return string.format("%s %s", def.label, string.format(def.fmt, value))
end

function draw_seq_stutter_count_badge(dl, ctx, x0, y0, x1, y1, count, accent, hover)
  count = seq_clamp_stutter_count(count)
  local text = tostring(count)
  local text_size = { r.ImGui_CalcTextSize(ctx, text) }
  local text_w = text_size[1] or 0
  local text_h = text_size[2] or 0
  local tx = (x0 + x1) * 0.5 - text_w * 0.5
  local ty = (y0 + y1) * 0.5 - text_h * 0.5
  local bx0, by0, bx1, by1 = tx - 3, ty - 1, tx + text_w + 3, ty + text_h + 1
  r.ImGui_DrawList_AddRectFilled(dl, bx0, by0, bx1, by1, hover and 0x000000EE or 0x000000BB, 2.0)
  if hover then
    r.ImGui_DrawList_AddRect(dl, bx0, by0, bx1, by1, seq_lane_color_with_alpha(accent or 0xC9A8FFFF, 255), 2.0, 0, 1.2)
  end
  r.ImGui_DrawList_AddText(dl, tx + 1, ty + 1, 0x000000AA, text)
  r.ImGui_DrawList_AddText(dl, tx, ty, seq_lane_color_with_alpha(accent or 0xC9A8FFFF, 255), text)
  return bx0, by0, bx1, by1
end

function draw_seq_stutter_lane_cell(dl, ctx, cx0, cx1, lane_top, lane_bot, count, accent)
  count = seq_clamp_stutter_count(count)
  local ar, ag, ab = extract_rgb_rrgbbaa(accent or 0xC9A8FFFF)
  local pad_x = 2.0
  local fill_x0 = cx0 + pad_x
  local fill_x1 = cx1 - pad_x
  if fill_x1 <= fill_x0 then
    fill_x1 = fill_x0 + 1.0
  end

  local lane_h = math.max(4.0, lane_bot - lane_top)
  local gap = 1.0
  local draw_n = math.max(1, math.min(count, SEQ_STUTTER_LANE_STACK_MAX))
  local box_h = math.max(2.0, (lane_h - gap * (draw_n - 1)) / draw_n)
  local stack_h = draw_n * box_h + math.max(0, draw_n - 1) * gap
  local stack_y0 = lane_bot - stack_h

  for i = 1, draw_n do
    local by1 = lane_bot - (i - 1) * (box_h + gap)
    local by0 = by1 - box_h
    if by0 < stack_y0 then
      by0 = stack_y0
    end
    local fade = 50 + math.floor((i / draw_n) * 120)
    local edge_fade = math.min(255, fade + 40)
    local fill_col = build_color_rrgbbaa(ar, ag, ab, fade)
    local edge_col = build_color_rrgbbaa(ar, ag, ab, edge_fade)
    r.ImGui_DrawList_AddRectFilled(dl, fill_x0, by0, fill_x1, by1, fill_col, 1.0)
    r.ImGui_DrawList_AddRect(dl, fill_x0, by0, fill_x1, by1, edge_col, 1.0, 0, 1.0)
  end

  draw_seq_stutter_count_badge(dl, ctx, fill_x0, lane_top, fill_x1, lane_bot, count, accent)
end

function seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
  local qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  return math.max(0, math.min(step_count - 1, math.floor((qn - start_qn) / step_qn + 1e-9)))
end

function seq_param_value_for_drag(def, value, step_qn)
  if def.key == "length_qn" then
    return snap_seq_length_qn(value, step_qn)
  end
  if def.key == "stutter" then
    return seq_clamp_stutter_count(value)
  end
  if def.key == "stretch" then
    value = tonumber(value) or 1.0
    if value < SEQ_STRETCH_MIN then return SEQ_STRETCH_MIN end
    if value > SEQ_STRETCH_MAX then return SEQ_STRETCH_MAX end
    return value
  end
  if def.key == "start" then
    value = tonumber(value) or 0.0
    if value < 0.0 then return 0.0 end
    if value > SEQ_START_MAX then return SEQ_START_MAX end
    return value
  end
  return value
end

function apply_seq_note_lane_drag(drag, region, step_qn, start_qn, step_count, mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  if not drag or not region then
    return false
  end

  local slot = nil
  for _, track_slot in ipairs(state.seq_tracks) do
    if track_slot.id == drag.track_id then
      slot = track_slot
      break
    end
  end
  if not slot then
    return false
  end

  drag.end_col = seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
  local col_min = math.min(drag.start_col, drag.end_col)
  local col_max = math.max(drag.start_col, drag.end_col)
  local prev_min = drag.applied_min or drag.start_col
  local prev_max = drag.applied_max or drag.start_col
  if col_min >= prev_min and col_max <= prev_max then
    return false
  end

  local region_start = region.start_qn or 0.0
  local region_end = region_start + get_seq_region_length_qn(region)
  local changed = false

  local function apply_col(col)
    local qn = start_qn + col * step_qn
    if qn < region_start or qn >= region_end then
      return
    end
    if drag.mode == "erase" then
      if seq_erase_notes_starting_in_span(region, slot, qn, qn + step_qn, {
        defer_save = true,
        defer_arrange = true,
      }) then
        changed = true
      end
      return
    end
    local step_idx = math.floor(((qn - region_start) / step_qn) + 1e-9)
    local step_key = tostring(step_idx)
    if toggle_seq_note(region, slot, step_key, step_idx * step_qn, drag.mode, {
      defer_save = true,
      defer_arrange = true,
    }) then
      changed = true
    end
  end

  -- Highest step first so gap-to-next-hit lengths are correct on first insert.
  if r.PreventUIRefresh then r.PreventUIRefresh(1) end
  if col_min < prev_min then
    for col = prev_min - 1, col_min, -1 do
      apply_col(col)
    end
  end
  if col_max > prev_max then
    for col = col_max, prev_max + 1, -1 do
      apply_col(col)
    end
  end
  if r.PreventUIRefresh then r.PreventUIRefresh(-1) end
  if changed then
    r.UpdateArrange()
  end

  drag.applied_min = col_min
  drag.applied_max = col_max
  return changed
end

function apply_seq_note_copy_drag(drag, step_qn, start_qn, step_count, mx, my, timeline_x0, timeline_w, view_start_qn, qn_span, row_positions)
  if not drag or not drag.src_note then
    return false
  end
  if drag.mode ~= "copy" and drag.mode ~= "move" then
    return false
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local mouse_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  local dest_abs
  if drag.mode == "copy" and drag.snap ~= false then
    dest_abs = math.floor((mouse_qn / step_qn) + 1e-9) * step_qn
  else
    dest_abs = (drag.src_abs_qn or 0.0) + (mouse_qn - (drag.grab_qn or mouse_qn))
    dest_abs = seq_quantize_free_qn(dest_abs)
  end
  if dest_abs < 0 then
    dest_abs = 0
  end
  local dest_track_id = seq_track_id_at_y(row_positions, my) or drag.track_id
  local dest_region = seq_region_at_qn(dest_abs)
  local dest_slot = seq_find_slot_by_id(dest_track_id)

  local function restore()
    if drag.patterns_backup then
      state.seq_patterns = clone_table_deep(drag.patterns_backup)
    end
  end

  local origin_qn = (drag.mode == "copy") and (drag.src_snap_qn or drag.src_abs_qn or 0) or (drag.src_abs_qn or 0)
  local same = dest_region and dest_region.id == drag.region_id
    and dest_track_id == drag.track_id
    and math.abs(dest_abs - origin_qn) < 1e-6

  if not dest_region or not dest_slot or (same and not drag.place_new) then
    if drag.dirty then
      restore()
      drag.dirty = false
      drag.dest_track_id = nil
      drag.dest_region_id = nil
      drag.dest_step_key = nil
    end
    drag.last_dest_qn = dest_abs
    drag.last_dest_track = dest_track_id
    drag.last_dest_region = dest_region and dest_region.id or nil
    return false
  end

  if drag.last_dest_qn == dest_abs and drag.last_dest_track == dest_track_id
     and drag.last_dest_region == dest_region.id then
    return drag.dirty and true or false
  end

  restore()
  local rel = dest_abs - (dest_region.start_qn or 0.0)
  local region_len = get_seq_region_length_qn(dest_region)
  if rel < -1e-9 then
    rel = 0.0
    dest_abs = dest_region.start_qn or 0.0
  elseif rel >= region_len - 1e-9 then
    rel = math.max(0.0, seq_quantize_free_qn(region_len - (1.0 / 192.0)))
    dest_abs = (dest_region.start_qn or 0.0) + rel
  end

  if drag.mode == "move" and not drag.place_new then
    local src_region = get_seq_region_by_id(drag.region_id)
    delete_seq_note(src_region, drag.track_id, drag.src_step_key)
  end

  local note = clone_table_deep(drag.src_note)
  note.qn_offset = rel
  note.step = math.floor((rel / step_qn) + 1e-9)
  seq_keep_copied_note_over_region(note, drag.src_length_qn, dest_region, rel)
  local n_start, n_end = seq_note_qn_range(note, "0", step_qn)
  local span_end = (n_end and n_end > n_start + 1e-9) and n_end or (rel + step_qn)
  local keep_key = nil
  if drag.mode == "copy" and dest_region.id == drag.region_id and dest_track_id == drag.track_id then
    keep_key = drag.src_step_key
  end
  seq_delete_notes_overlapping_span(
    dest_region, dest_slot, rel, span_end, keep_key, step_qn, {
      defer_arrange = true,
      -- Keep later hits; item lengths crop to the next start instead of deleting.
      same_start = true,
    }
  )
  local key = seq_alloc_note_key(dest_region, dest_slot.id, rel)
  set_seq_note(dest_region, dest_slot.id, key, note)
  state.selected_seq_note = { region_id = dest_region.id, track_id = dest_slot.id, step_key = key }
  drag.dest_region_id = dest_region.id
  drag.dest_track_id = dest_slot.id
  drag.dest_step_key = key
  drag.last_dest_qn = dest_abs
  drag.last_dest_track = dest_track_id
  drag.last_dest_region = dest_region.id
  drag.dirty = true
  return true
end

function apply_seq_stutter_lane_drag(drag, region, step_qn, start_qn, step_count, mx, my, timeline_x0, timeline_w, view_start_qn, qn_span)
  if not drag or not region then
    return false
  end
  local slot = seq_find_slot_by_id(drag.track_id)
  if not slot then
    return false
  end

  drag.end_col = seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
  local col_min = math.min(drag.start_col, drag.end_col)
  local col_max = math.max(drag.start_col, drag.end_col)
  local region_start = region.start_qn or 0.0
  local region_end = region_start + get_seq_region_length_qn(region)
  local abs_start = start_qn + col_min * step_qn
  local abs_end = start_qn + (col_max + 1) * step_qn
  if abs_start < region_start then abs_start = region_start end
  if abs_end > region_end then abs_end = region_end end
  if abs_end - abs_start < step_qn * 0.5 then
    abs_end = math.min(region_end, abs_start + step_qn)
    if abs_end - abs_start < step_qn * 0.5 then
      abs_start = math.max(region_start, abs_end - step_qn)
    end
  end
  local length_qn = snap_seq_length_qn(abs_end - abs_start, step_qn)
  if length_qn <= 0 then
    return false
  end
  local qn_offset = abs_start - region_start
  if qn_offset < -1e-9 or qn_offset >= (region_end - region_start) - 1e-9 then
    return false
  end
  local count = seq_stutter_count_from_drag_dy(drag.origin_y, my)

  if not drag.step_key then
    local existing_key, existing = seq_find_note_key_at_qn(region, slot.id, qn_offset)
    if existing then
      drag.step_key = existing_key
    else
      local key = seq_alloc_note_key(region, slot.id, qn_offset)
      local note = make_default_seq_note(slot, key, qn_offset)
      if not note then
        log("Sequencer slot has no assigned sample")
        return false
      end
      set_seq_note(region, slot.id, key, note)
      register_seq_note_anim(region.id, slot.id, key, note, "add")
      drag.step_key = key
    end
  end

  local note = get_seq_note(region, slot.id, drag.step_key)
  if not note then
    return false
  end

  local changed = not drag.initialized
  if math.abs((note.qn_offset or 0.0) - qn_offset) > 1e-9 then
    note.qn_offset = qn_offset
    note.step = math.floor((qn_offset / step_qn) + 1e-9)
    changed = true
  end
  if math.abs((note.length_qn or 0.0) - length_qn) > 1e-9 then
    note.length_qn = length_qn
    changed = true
  end
  if note.stutter ~= count then
    note.stutter = count
    seq_prune_stutter_hits(note)
    changed = true
  end

  drag.length_qn = length_qn
  drag.stutter = count
  drag.qn_offset = qn_offset

  if changed then
    seq_delete_notes_overlapping_span(
      region, slot, qn_offset, qn_offset + length_qn, drag.step_key, step_qn, { defer_arrange = true }
    )
    state.selected_seq_note = { region_id = region.id, track_id = slot.id, step_key = drag.step_key }
    drag.initialized = true
    drag.dirty = true
    return true
  end
  return false
end

function seq_begin_stutter_edit_drag(region, slot, step_key, note, mx, my, undo_label)
  if not region or not slot or not note then
    return false
  end
  local label = begin_seq_undo(undo_label or "Edit sequencer stutter")
  state.selected_seq_note = { region_id = region.id, track_id = slot.id, step_key = step_key }
  state.seq_note_drag = {
    mode = "stutter_edit",
    track_id = slot.id,
    region_id = region.id,
    step_key = tostring(step_key),
    origin_x = mx,
    origin_y = my,
    origin_count = seq_stutter_count(note),
    origin_skew = seq_stutter_skew(note),
    stutter = seq_stutter_count(note),
    skew = seq_stutter_skew(note),
    axis = nil,
    undo_label = label,
    undo_open = true,
    dirty = false,
  }
  return true
end

function apply_seq_stutter_edit_drag(drag, region, mx, my)
  if not drag or not region then
    return false
  end
  local note = get_seq_note(region, drag.track_id, drag.step_key)
  if not note then
    return false
  end
  if not drag.axis then
    local dx = (mx or drag.origin_x or 0) - (drag.origin_x or 0)
    local dy = (drag.origin_y or 0) - (my or drag.origin_y or 0)
    if math.abs(dx) < SEQ_STUTTER_AXIS_PX and math.abs(dy) < SEQ_STUTTER_AXIS_PX then
      return false
    end
    drag.axis = (math.abs(dx) > math.abs(dy)) and "skew" or "count"
  end
  local changed = false
  if drag.axis == "count" then
    local count = seq_stutter_count_from_relative_dy(drag.origin_count, drag.origin_y, my)
    if note.stutter ~= count then
      note.stutter = count
      seq_prune_stutter_hits(note)
      changed = true
    end
    drag.stutter = count
  else
    local skew = seq_stutter_skew_from_dx(drag.origin_skew, drag.origin_x, mx)
    if seq_set_stutter_skew(note, skew) then
      changed = true
    end
    drag.skew = seq_stutter_skew(note)
  end
  if changed then
    state.selected_seq_note = { region_id = region.id, track_id = drag.track_id, step_key = drag.step_key }
    drag.dirty = true
    local slot = seq_find_slot_by_id(drag.track_id)
    if slot then
      if r.PreventUIRefresh then r.PreventUIRefresh(1) end
      sync_seq_pattern_note(region.pattern_id, slot, drag.step_key, { skip_neighbor = true })
      if r.PreventUIRefresh then r.PreventUIRefresh(-1) end
      r.UpdateArrange()
    end
  end
  return changed
end

function seq_note_decay_max_qn(region, slot, note, step_key, step_qn)
  local resolved_path, resolved_sample = seq_resolve_note_sample(note, slot, nil, region, slot and slot.id, step_key)
  local cap = seq_sample_length_qn(resolved_path, resolved_sample)
  if cap and cap > 0 then
    return cap
  end
  local region_len = region and get_seq_region_length_qn(region) or 8.0
  return math.max(step_qn or 0.25, region_len)
end

function seq_note_current_decay_length_qn(region, slot, note, step_key, step_qn)
  if seq_note_has_stutter_span(note, step_qn) then
    return seq_stutter_span_qn(note, step_qn) or step_qn
  end
  local _, resolved_sample = seq_resolve_note_sample(note, slot, nil, region, slot and slot.id, step_key)
  local pattern = region and get_seq_pattern(region.pattern_id, false) or nil
  return seq_note_draw_length_qn(region, pattern, slot, slot and slot.id, step_key, note, resolved_sample, step_qn)
end

function apply_seq_decay_drag(drag, region, step_qn, mx, my, timeline_x0, timeline_w, view_start_qn, qn_span)
  if not drag or not region then
    return false
  end
  local slot = seq_find_slot_by_id(drag.track_id)
  local note = get_seq_note(region, drag.track_id, drag.step_key)
  if not slot or not note then
    return false
  end
  local note_start_qn = drag.note_start_qn
  if not note_start_qn then
    note_start_qn = seq_note_abs_qn(region, note, drag.step_key, step_qn) + (note.offset_qn or 0.0)
    drag.note_start_qn = note_start_qn
  end
  local min_qn = (step_qn or 0.25) * 0.25
  local max_qn = drag.max_length_qn or seq_note_decay_max_qn(region, slot, note, drag.step_key, step_qn)
  drag.max_length_qn = max_qn
  local mouse_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  local changed = false
  local dx = mx - (drag.origin_x or mx)
  local dy = (drag.origin_y or my) - my

  if drag.handle == "end" then
    local length_qn = mouse_qn - note_start_qn
    if not is_shift_down() then
      length_qn = snap_seq_length_qn(length_qn, step_qn)
    else
      length_qn = math.max(min_qn, length_qn)
    end
    if length_qn < min_qn then length_qn = min_qn end
    if length_qn > max_qn then length_qn = max_qn end
    if seq_note_has_stutter_span(note, step_qn) or seq_stutter_count(note) > 1 then
      if math.abs((note.length_qn or 0.0) - length_qn) > 1e-9 then
        note.length_qn = length_qn
        changed = true
        local qn_offset = seq_note_qn_offset(note, drag.step_key, step_qn)
        seq_delete_notes_overlapping_span(
          region, slot, qn_offset, qn_offset + length_qn, drag.step_key, step_qn, { defer_arrange = true }
        )
      end
    else
      if math.abs((tonumber(note.decay_qn) or 0.0) - length_qn) > 1e-9 then
        note.decay_qn = length_qn
        changed = true
      end
    end
    seq_clamp_note_fades(note, length_qn)
    drag.length_qn = length_qn
  elseif drag.handle == "curve_in" or drag.handle == "curve_out" then
    local which = (drag.handle == "curve_in") and "in" or "out"
    local base_curve = drag.origin_curve or 0.0
    local curve = seq_fade_curve_clamp(base_curve + dy / SEQ_FADE_CURVE_PX)
    if seq_note_set_fade_curve(note, which, curve) then
      changed = true
    end
    drag.fade_curve = seq_note_fade_curve(note, which)
    drag.fade_qn = seq_note_fade_qn(note, which)
    drag.fade_shape = seq_note_fade_shape(note, which)
  elseif drag.handle == "fade_out" or drag.handle == "fade_in" then
    local length_qn = seq_note_current_decay_length_qn(region, slot, note, drag.step_key, step_qn)
    local which = (drag.handle == "fade_in") and "in" or "out"
    if not drag.axis then
      if math.abs(dx) >= SEQ_FADE_AXIS_PX or math.abs(dy) >= SEQ_FADE_AXIS_PX then
        drag.axis = (math.abs(dy) > math.abs(dx)) and "type" or "length"
      end
    end
    if drag.axis == "type" and (drag.origin_fade_qn or 0) < 1e-6 then
      drag.axis = "length"
    end
    if drag.axis ~= "type" then
      local fade_qn
      if which == "in" then
        fade_qn = mouse_qn - note_start_qn
      else
        fade_qn = (note_start_qn + length_qn) - mouse_qn
      end
      if fade_qn < 0 then fade_qn = 0 end
      fade_qn = math.min(fade_qn, math.max(0.0, length_qn - min_qn * 0.1))
      if seq_note_set_fade(note, which, fade_qn, drag.origin_shape) then
        changed = true
      end
      seq_push_note_fades(note, length_qn, which)
    end
    if drag.axis == "type" then
      local base_shape = drag.origin_shape
      if base_shape == nil then
        base_shape = 1
      end
      local shape = seq_fade_shape_clamp(base_shape + math.floor(dy / SEQ_FADE_SHAPE_PX + 0.5))
      local fade_qn = seq_note_fade_qn(note, which)
      if fade_qn < 1e-6 then
        fade_qn = drag.origin_fade_qn or 0.0
      end
      if fade_qn > 1e-6 and seq_note_set_fade(note, which, fade_qn, shape) then
        changed = true
      end
    end
    drag.fade_qn = seq_note_fade_qn(note, which)
    drag.fade_shape = seq_note_fade_shape(note, which)
    drag.fade_curve = seq_note_fade_curve(note, which)
    drag.length_qn = length_qn
  end

  if changed then
    state.selected_seq_note = { region_id = region.id, track_id = slot.id, step_key = drag.step_key }
    drag.dirty = true
  end
  return changed
end

function apply_seq_param_lane_drag(drag, def, lane_y0, lane_y1, mx, my, step_qn, step_count, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, active_cells)
  drag.end_col = seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
  local mouse_col = drag.end_col
  local current_value
  if def.key == "stutter" then
    if drag.origin_count == nil then
      drag.origin_count = seq_clamp_stutter_count(drag.start_value or 1)
      drag.origin_y = drag.origin_y or my
    end
    current_value = seq_stutter_count_from_relative_dy(drag.origin_count, drag.origin_y, my)
  else
    current_value = seq_param_value_for_drag(def, seq_param_value_from_y(def, my, lane_y0, lane_y1, step_qn), step_qn)
  end
  local col_min = math.min(drag.col, drag.end_col)
  local col_max = math.max(drag.col, drag.end_col)
  local mouse_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  if seq_is_lock_def(def) then
    local region = get_seq_region_by_id(drag.region_id)
    local changed = seq_apply_lock_range(region, drag.track_id, col_min, col_max, start_qn, step_qn, true, active_cells)
    return changed, 1.0, col_min, col_max, mouse_col
  end
  if seq_is_vary_filter_def(def) then
    if drag.filter_click_span then
      if drag.end_col == drag.col then
        return false, 1.0, col_min, col_max, mouse_col
      end
      drag.filter_click_span = false
    end
    local region = get_seq_region_by_id(drag.region_id)
    local edit = state.seq_vary_filter_edit
    if not edit or edit.region_id ~= drag.region_id or tostring(edit.track_id) ~= tostring(drag.track_id) then
      seq_begin_vary_filter_edit(region, drag.track_id, col_min, col_max, start_qn, step_qn, "", nil)
    else
      edit.col_min = col_min
      edit.col_max = col_max
      edit.start_qn = start_qn
      edit.step_qn = step_qn
    end
    if state.seq_vary_filter_edit then
      state.seq_vary_filter_edit.focus = false
    end
    return false, 1.0, col_min, col_max, mouse_col
  end
  local changed = false

  local function apply_entry(entry, value, qn, all_hits, qn0, qn1)
    if seq_apply_param_to_note(entry.note, entry.abs_qn, def, value, qn, step_qn, false, all_hits, qn0, qn1) then
      changed = true
    end
  end

  if drag.ramp and drag.end_col ~= drag.col then
    local start_val = drag.start_value
    if start_val == nil then
      start_val = def.default
    end
    for col = col_min, col_max do
      local active = active_cells[drag.track_id] and active_cells[drag.track_id][col]
      if active then
        local t = (col - drag.col) / (drag.end_col - drag.col)
        local value = seq_param_value_for_drag(def, start_val + (current_value - start_val) * t, step_qn)
        local qn0 = start_qn + col * step_qn
        local qn1 = qn0 + step_qn
        seq_for_each_active_note(active, function(entry)
          apply_entry(entry, value, qn0 + step_qn * 0.5, true, qn0, qn1)
        end)
      end
    end
  elseif drag.unify then
    for col = col_min, col_max do
      local active = active_cells[drag.track_id] and active_cells[drag.track_id][col]
      if active then
        local qn0 = start_qn + col * step_qn
        local qn1 = qn0 + step_qn
        seq_for_each_active_note(active, function(entry)
          apply_entry(entry, current_value, qn0 + step_qn * 0.5, true, qn0, qn1)
        end)
      end
    end
  else
    local active = active_cells[drag.track_id] and active_cells[drag.track_id][mouse_col]
    if active then
      seq_for_each_active_note(active, function(entry)
        apply_entry(entry, current_value, mouse_qn, false)
      end)
      changed = true
      state.selected_seq_note = {
        region_id = drag.region_id,
        track_id = drag.track_id,
        step_key = active.key,
      }
      drag.hit_idx = seq_stutter_hit_index_at_qn(active.note, active.abs_qn, mouse_qn, step_qn)
    elseif def.key == "stutter" and drag.step_key then
      local region = get_seq_region_by_id(drag.region_id)
      local note = region and get_seq_note(region, drag.track_id, drag.step_key)
      if note then
        if seq_set_note_param_value(note, "stutter", current_value) then
          changed = true
        end
        state.selected_seq_note = {
          region_id = drag.region_id,
          track_id = drag.track_id,
          step_key = drag.step_key,
        }
      end
    end
  end

  local highlight_col_min = mouse_col
  local highlight_col_max = mouse_col
  if drag.ramp or drag.unify then
    highlight_col_min = col_min
    highlight_col_max = col_max
  end

  return changed, current_value, highlight_col_min, highlight_col_max, mouse_col
end

function sample_start_path_key(sample)
  if not sample or not sample.path or sample.path == "" then
    return nil
  end
  return normalize_path(sample.path)
end

function get_sample_start_offset(sample)
  if not sample then
    return 0.0
  end
  local path = sample_start_path_key(sample)
  local session = path and state.seq_sample_start_session and state.seq_sample_start_session[path]
  local t = nil
  if type(session) == "number" then
    t = session
  else
    t = tonumber(sample.start_pos)
  end
  t = tonumber(t) or 0.0
  if t < 0 then
    t = 0
  end
  local dur = tonumber(sample.duration) or 0.0
  if dur > 0.002 and t > dur - 0.001 then
    t = dur - 0.001
  end
  return t
end

function sample_start_has_session(sample)
  local path = sample_start_path_key(sample)
  return path and state.seq_sample_start_session and type(state.seq_sample_start_session[path]) == "number"
end

function sample_start_is_saved(sample)
  return sample ~= nil and sample.start_pos ~= nil
end

function set_sample_start_offset_session(sample, t)
  local path = sample_start_path_key(sample)
  if not path then
    return 0.0
  end
  state.seq_sample_start_session = state.seq_sample_start_session or {}
  t = tonumber(t) or 0.0
  if t < 0 then
    t = 0
  end
  local dur = tonumber(sample.duration) or 0.0
  if dur > 0.002 and t > dur - 0.001 then
    t = dur - 0.001
  end
  state.seq_sample_start_session[path] = t
  return t
end

function seq_rebuild_after_sample_start_change(sample)
  if not sample then
    return
  end
  local path = sample_start_path_key(sample)
  if not path then
    return
  end
  if seq_mark_self_arrange_write then
    seq_mark_self_arrange_write()
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  for _, slot in ipairs(state.seq_tracks or {}) do
    local match = slot.sample_path and normalize_path(slot.sample_path) == path
    if not match and slot.layers then
      local sides = { slot.layers.transient, slot.layers.sustain }
      for s = 1, #sides do
        local side = sides[s]
        local verts = side and side.verts
        if verts then
          for i = 1, #verts do
            local v = verts[i]
            if v and v.path and normalize_path(v.path) == path then
              match = true
              break
            end
          end
        end
        if match then
          break
        end
      end
    end
    if match then
      sync_seq_slot_all_regions(slot, { skip_arrange = true, force_rebuild = true })
    end
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  if r.UpdateArrange then
    r.UpdateArrange()
  end
end

function save_sample_start_offset(sample)
  if not sample then
    return
  end
  sample.start_pos = get_sample_start_offset(sample)
  save_samples()
  seq_rebuild_after_sample_start_change(sample)
end

function clear_sample_start_offset_session(sample)
  local path = sample_start_path_key(sample)
  if path and state.seq_sample_start_session then
    state.seq_sample_start_session[path] = nil
  end
  seq_rebuild_after_sample_start_change(sample)
end

function clear_sample_start_offset_saved(sample)
  if not sample then
    return
  end
  sample.start_pos = nil
  save_samples()
  seq_rebuild_after_sample_start_change(sample)
end

function sample_gain_has_session(sample)
  local path = sample_start_path_key(sample)
  return path and state.seq_sample_vol_session and type(state.seq_sample_vol_session[path]) == "number"
end

function sample_gain_is_saved(sample)
  return sample ~= nil and sample.gain ~= nil
end

function apply_sample_gain_to_preview(sample)
  if not cf_preview_obj or not r.CF_Preview_SetValue then
    return
  end
  if preview_sample_obj and sample and preview_sample_obj.path == sample.path then
    r.CF_Preview_SetValue(cf_preview_obj, "D_VOLUME", preview_output_volume(sample))
  end
end

function seq_apply_sample_gain_to_project_items(sample, old_gain, new_gain)
  local path = sample_start_path_key(sample)
  if not path then
    return
  end
  old_gain = tonumber(old_gain) or 1.0
  new_gain = tonumber(new_gain) or 1.0
  if math.abs(new_gain - old_gain) < 1e-6 then
    return
  end
  if old_gain < 1e-4 then
    old_gain = 1e-4
  end
  local mul = new_gain / old_gain
  if seq_mark_self_arrange_write then
    seq_mark_self_arrange_write()
  end
  local n = r.CountMediaItems(0)
  for i = 0, n - 1 do
    local item = r.GetMediaItem(0, i)
    if item and seq_item_source_path(item) == path then
      local take = r.GetActiveTake(item)
      if take then
        local vol = r.GetMediaItemTakeInfo_Value(take, "D_VOL") or 1.0
        r.SetMediaItemTakeInfo_Value(take, "D_VOL", vol * mul)
        if r.UpdateItemInProject then
          r.UpdateItemInProject(item)
        end
      end
    end
  end
  if r.UpdateArrange then
    r.UpdateArrange()
  end
end

function set_sample_gain_session(sample, gain)
  local path = sample_start_path_key(sample)
  if not path then
    return 1.0
  end
  local old = get_sample_gain(sample)
  gain = tonumber(gain) or 1.0
  if gain < 0.05 then
    gain = 0.05
  elseif gain > 4 then
    gain = 4
  end
  state.seq_sample_vol_session = state.seq_sample_vol_session or {}
  state.seq_sample_vol_session[path] = gain
  seq_apply_sample_gain_to_project_items(sample, old, gain)
  apply_sample_gain_to_preview(sample)
  return gain
end

function save_sample_gain(sample)
  if not sample then
    return
  end
  sample.gain = get_sample_gain(sample)
  local path = sample_start_path_key(sample)
  if path and state.seq_sample_vol_session then
    state.seq_sample_vol_session[path] = nil
  end
  save_samples()
end

function clear_sample_gain_session(sample)
  local old = get_sample_gain(sample)
  local path = sample_start_path_key(sample)
  if path and state.seq_sample_vol_session then
    state.seq_sample_vol_session[path] = nil
  end
  seq_apply_sample_gain_to_project_items(sample, old, get_sample_gain(sample))
  apply_sample_gain_to_preview(sample)
end

function clear_sample_gain_saved(sample)
  if not sample then
    return
  end
  local old = get_sample_gain(sample)
  sample.gain = nil
  save_samples()
  seq_apply_sample_gain_to_project_items(sample, old, get_sample_gain(sample))
  apply_sample_gain_to_preview(sample)
end

function save_sample_header_settings(sample)
  if not sample then
    return
  end
  sample.start_pos = get_sample_start_offset(sample)
  sample.gain = get_sample_gain(sample)
  local path = sample_start_path_key(sample)
  if path then
    if state.seq_sample_start_session then
      state.seq_sample_start_session[path] = nil
    end
    if state.seq_sample_vol_session then
      state.seq_sample_vol_session[path] = nil
    end
  end
  save_samples()
end

function wave_view_ensure(sample, duration)
  duration = tonumber(duration) or 0.0
  if duration <= 0.0001 then
    duration = 0.0001
  end
  local path = sample and sample.path
  if path and state.wave_view_path ~= path then
    state.wave_view_path = path
    state.wave_view_t0 = 0.0
    state.wave_view_t1 = duration
    state.wave_view_pan = nil
  end
  local t0 = tonumber(state.wave_view_t0) or 0.0
  local t1 = tonumber(state.wave_view_t1) or duration
  if t0 < 0 then t0 = 0 end
  if t1 > duration then t1 = duration end
  if t1 <= t0 then
    t1 = math.min(duration, t0 + math.max(0.04, duration * 0.02))
  end
  if t1 > duration then
    local span = t1 - t0
    t1 = duration
    t0 = math.max(0.0, t1 - span)
  end
  state.wave_view_t0 = t0
  state.wave_view_t1 = t1
  return t0, t1
end

function wave_time_to_x(t, x, w, t0, t1)
  local span = (t1 or 0) - (t0 or 0)
  if span <= 0 or w <= 0 then
    return x
  end
  return x + (((t or 0) - t0) / span) * w
end

function wave_x_to_time(px, x, w, t0, t1)
  if not w or w <= 0 then
    return t0 or 0
  end
  local u = (px - x) / w
  if u < 0 then u = 0 elseif u > 1 then u = 1 end
  return (t0 or 0) + u * ((t1 or 0) - (t0 or 0))
end

function wave_view_reset(sample, duration)
  duration = tonumber(duration) or 0.0
  state.wave_view_path = sample and sample.path
  state.wave_view_t0 = 0.0
  state.wave_view_t1 = duration
  state.wave_view_pan = nil
end

function wave_view_zoom(sample, duration, mx, x, w, wheel)
  duration = tonumber(duration) or 0.0
  if not wheel or wheel == 0 or duration <= 0.0001 or w <= 0 then
    return
  end
  local t0, t1 = wave_view_ensure(sample, duration)
  local focus = wave_x_to_time(mx, x, w, t0, t1)
  local span = t1 - t0
  local new_span = span * math.exp(-wheel * 0.18)
  local min_span = math.max(0.04, duration * 0.02)
  if new_span < min_span then new_span = min_span end
  if new_span > duration then new_span = duration end
  local u = (span > 0) and ((focus - t0) / span) or 0.5
  if u < 0 then u = 0 elseif u > 1 then u = 1 end
  local nt0 = focus - u * new_span
  local nt1 = nt0 + new_span
  if nt0 < 0 then
    nt1 = nt1 - nt0
    nt0 = 0
  end
  if nt1 > duration then
    nt0 = math.max(0.0, nt0 - (nt1 - duration))
    nt1 = duration
  end
  state.wave_view_t0 = nt0
  state.wave_view_t1 = nt1
end

function wave_view_pan(sample, duration, dx, w)
  duration = tonumber(duration) or 0.0
  if duration <= 0.0001 or not w or w <= 0 or not dx or dx == 0 then
    return
  end
  local t0, t1 = wave_view_ensure(sample, duration)
  local span = t1 - t0
  t0 = t0 - (dx / w) * span
  t1 = t0 + span
  if t0 < 0 then
    t1 = t1 - t0
    t0 = 0
  end
  if t1 > duration then
    t0 = math.max(0.0, t0 - (t1 - duration))
    t1 = duration
  end
  state.wave_view_t0 = t0
  state.wave_view_t1 = t1
end

function wave_view_is_zoomed(duration)
  duration = tonumber(duration) or 0.0
  local t0 = tonumber(state.wave_view_t0) or 0.0
  local t1 = tonumber(state.wave_view_t1) or duration
  return duration > 0 and (t1 - t0) < (duration - 0.0005)
end

-- Shared start-marker + volume knob + "..." menu for map and sequencer waveforms.
-- Returns { consumed, over_start, over_vol, over_menu }.
function draw_sample_wave_controls(dl, sample, x, y, w, h, duration, t0, t1, mx, my, left_down, left_clicked, id_suffix, opts)
  opts = opts or {}
  if not sample or w < 16 or h < 10 then
    return { consumed = false }
  end
  duration = tonumber(duration) or 0.0
  t0 = tonumber(t0) or 0.0
  t1 = tonumber(t1) or duration
  if t1 <= t0 then
    t1 = t0 + 0.001
  end
  id_suffix = id_suffix or "wave"

  local start_t = get_sample_start_offset(sample)
  local start_x = wave_time_to_x(start_t, x, w, t0, t1)
  if start_t > t0 then
    local dim_x1 = math.min(x + w, math.max(x, start_x))
    if dim_x1 > x then
      r.ImGui_DrawList_AddRectFilled(dl, x, y, dim_x1, y + h, 0x00000099)
    end
  end
  local start_visible = start_x >= x - 2 and start_x <= x + w + 2
  local start_col = sample_start_has_session(sample) and 0x5CE1FFFF
      or (sample_start_is_saved(sample) and 0x7CFFB0FF or 0x8EC8E8CC)
  local start_tri_half = 6.0
  local start_tri_h = 8.0
  if start_visible then
    r.ImGui_DrawList_AddLine(dl, start_x, y + 1, start_x, y + h - 1, start_col, 1.6)
    r.ImGui_DrawList_AddTriangleFilled(dl,
      start_x - start_tri_half, y + 1,
      start_x + start_tri_half, y + 1,
      start_x, y + 1 + start_tri_h,
      start_col)
    if start_t > 0.0005 then
      r.ImGui_DrawList_AddText(dl, math.min(start_x + 8, x + w - 48), y + 2, start_col,
        string.format("%.2fs", start_t))
    end
  end

  local btn_r = 7.5
  local btn_cx = x + w - 11
  local btn_cy = y + 11
  local vol_r = 8.0
  local vol_cx = btn_cx - 20
  local vol_cy = btn_cy
  local gain = get_sample_gain(sample)
  local over_vol = (mx - vol_cx) * (mx - vol_cx) + (my - vol_cy) * (my - vol_cy) <= (vol_r + 3) * (vol_r + 3)
  local vol_col = sample_gain_has_session(sample) and 0x5CE1FFFF
      or (sample_gain_is_saved(sample) and 0x7CFFB0FF or 0x8EC8E8CC)
  local vol_fill = (over_vol or state.seq_header_vol_drag) and 0x4A5A74FF or 0x2C384CFF
  r.ImGui_DrawList_AddCircleFilled(dl, vol_cx, vol_cy, vol_r, vol_fill, 18)
  r.ImGui_DrawList_AddCircle(dl, vol_cx, vol_cy, vol_r, vol_col, 18, 1.3)
  local ANGLE_MIN = math.pi * 0.75
  local ANGLE_MAX = math.pi * 2.25
  local vol_u = gain / 4.0
  if vol_u < 0 then vol_u = 0 elseif vol_u > 1 then vol_u = 1 end
  local angle = ANGLE_MIN + (ANGLE_MAX - ANGLE_MIN) * vol_u
  local arc_r = vol_r - 2.5
  local prev_ax, prev_ay
  for i = 0, 12 do
    local a = ANGLE_MIN + (angle - ANGLE_MIN) * (i / 12)
    local ax = vol_cx + math.cos(a) * arc_r
    local ay = vol_cy + math.sin(a) * arc_r
    if prev_ax then
      r.ImGui_DrawList_AddLine(dl, prev_ax, prev_ay, ax, ay, vol_col, 1.8)
    end
    prev_ax, prev_ay = ax, ay
  end
  r.ImGui_DrawList_AddLine(dl, vol_cx, vol_cy,
    vol_cx + math.cos(angle) * (vol_r - 3.5),
    vol_cy + math.sin(angle) * (vol_r - 3.5),
    0xFFFFFFFF, 1.4)
  r.ImGui_DrawList_AddCircleFilled(dl, vol_cx, vol_cy, 1.6, 0xFFFFFFFF, 8)

  local over_btn = (mx - btn_cx) * (mx - btn_cx) + (my - btn_cy) * (my - btn_cy) <= (btn_r + 2) * (btn_r + 2)
  r.ImGui_DrawList_AddCircleFilled(dl, btn_cx, btn_cy, btn_r, over_btn and 0x4A5A74FF or 0x2C384CFF, 16)
  r.ImGui_DrawList_AddCircle(dl, btn_cx, btn_cy, btn_r, over_btn and 0xC8D4E8FF or 0x8090A8FF, 16, 1.2)
  local dots = "..."
  local dots_w, dots_h = 10, 12
  if r.ImGui_CalcTextSize then
    dots_w, dots_h = r.ImGui_CalcTextSize(ctx, dots)
  end
  r.ImGui_DrawList_AddText(dl, btn_cx - dots_w * 0.5, btn_cy - dots_h * 0.5 - 1, 0xF4F7FCFF, dots)

  local restore_x, restore_y = r.ImGui_GetCursorScreenPos(ctx)
  r.ImGui_SetCursorScreenPos(ctx, vol_cx - vol_r, vol_cy - vol_r)
  r.ImGui_InvisibleButton(ctx, "##sample_wave_vol_" .. id_suffix, vol_r * 2 + 2, vol_r * 2 + 2)
  if r.ImGui_IsItemHovered(ctx) then
    over_vol = true
  end
  local vol_active = r.ImGui_IsItemActive(ctx)
  local vol_double = r.ImGui_IsItemClicked(ctx, 0) and r.ImGui_IsMouseDoubleClicked(ctx, 0)
  r.ImGui_SetCursorScreenPos(ctx, btn_cx - btn_r, btn_cy - btn_r)
  r.ImGui_InvisibleButton(ctx, "##sample_wave_dots_" .. id_suffix, btn_r * 2 + 2, btn_r * 2 + 2)
  if r.ImGui_IsItemHovered(ctx) then
    over_btn = true
  end
  local dots_clicked = r.ImGui_IsItemClicked and r.ImGui_IsItemClicked(ctx, 0)
  r.ImGui_SetCursorScreenPos(ctx, restore_x, restore_y)

  if vol_double or (over_vol and left_clicked and r.ImGui_IsMouseDoubleClicked
      and r.ImGui_IsMouseDoubleClicked(ctx, 0)) then
    set_sample_gain_session(sample, 1.0)
    gain = 1.0
    state.seq_header_vol_drag = nil
  elseif over_vol and left_clicked then
    state.seq_header_vol_drag = true
    state.waveform_drag_armed = nil
  end
  local vol_fine = seq_fine_drag_down()
  if (vol_active or state.seq_header_vol_drag) and left_down then
    local _, dy = r.ImGui_GetMouseDelta(ctx)
    if dy and dy ~= 0.0 then
      state.seq_header_vol_drag = true
      state.waveform_drag_armed = nil
      set_sample_gain_session(sample, gain + (-dy) * 0.02 * (vol_fine and SEQ_FINE_DRAG_SCALE or 1.0))
      gain = get_sample_gain(sample)
    end
  elseif state.seq_header_vol_drag and not left_down then
    state.seq_header_vol_drag = nil
  end
  if over_vol and not vol_active then
    local wheel = r.ImGui_GetMouseWheel and select(1, r.ImGui_GetMouseWheel(ctx)) or 0
    if wheel and wheel ~= 0 then
      set_sample_gain_session(sample, gain + wheel * 0.08)
      gain = get_sample_gain(sample)
    end
  end

  if opts.show_name then
    local name = sample.name or ""
    if name ~= "" then
      if r.ImGui_DrawList_PushClipRect then
        r.ImGui_DrawList_PushClipRect(dl, x + 4, y + 1, vol_cx - vol_r - 3, y + h - 1, true)
      end
      r.ImGui_DrawList_AddText(dl, x + 7, y + 4, 0x000000CC, name)
      r.ImGui_DrawList_AddText(dl, x + 6, y + 3, 0xF4F7FCFF, name)
      if r.ImGui_DrawList_PopClipRect then
        r.ImGui_DrawList_PopClipRect(dl)
      end
    end
  end

  local over_start = start_visible
      and mx >= start_x - (start_tri_half + 2)
      and mx <= start_x + (start_tri_half + 2)
      and my >= y
      and my <= y + start_tri_h + 3

  if (over_btn and left_clicked) or dots_clicked then
    state.seq_header_menu_sample = sample
    if r.ImGui_OpenPopup then
      r.ImGui_OpenPopup(ctx, "##seq_header_sample_menu")
    end
  end
  draw_seq_header_sample_menu(sample)

  if state.seq_header_start_drag and not left_down then
    state.seq_header_start_drag = nil
    seq_rebuild_after_sample_start_change(sample)
  end

  if over_btn then
    if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
  elseif over_vol or state.seq_header_vol_drag then
    if r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, string.format("Volume  %.0f%% (double-click reset)", gain * 100.0))
    end
  elseif over_start or state.seq_header_start_drag then
    if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeEW then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeEW())
    end
    if r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, string.format("Start  %.3fs", start_t))
    end
  end

  if duration > 0 and not over_btn and not over_vol and not state.seq_header_vol_drag
      and ((left_clicked and over_start) or (state.seq_header_start_drag and left_down)) then
    state.seq_header_start_drag = true
    state.seq_header_wave_press = nil
    state.seq_header_wave_press_t = nil
    local new_t = wave_x_to_time(mx, x, w, t0, t1)
    start_t = set_sample_start_offset_session(sample, new_t)
    if preview_proc and preview_sample_obj and preview_sample_obj.path == sample.path then
      seek_preview(start_t)
    end
  end

  local consumed = over_btn or over_vol or over_start
      or state.seq_header_start_drag or state.seq_header_vol_drag
  return {
    consumed = consumed,
    over_start = over_start,
    over_vol = over_vol,
    over_menu = over_btn,
    start_t = start_t,
  }
end

function seq_reveal_sample_in_explorer(sample)
  local path = sample and sample.path
  if not path or path == "" then
    return
  end
  if r.CF_LocateInExplorer then
    r.CF_LocateInExplorer(path)
  elseif r.CF_ShellExecute then
    r.CF_ShellExecute(path)
  else
    os.execute("open -R " .. shell_escape(path))
  end
end

function draw_seq_header_sample_menu(sample)
  if not r.ImGui_BeginPopup or not r.ImGui_BeginPopup(ctx, "##seq_header_sample_menu") then
    return
  end
  local menu_sample = state.seq_header_menu_sample or sample
  if not menu_sample then
    r.ImGui_EndPopup(ctx)
    return
  end
  local saved = sample_start_is_saved(menu_sample)
  local vol_saved = sample_gain_is_saved(menu_sample)
  if r.ImGui_MenuItem(ctx, "Save start to sample") then
    save_sample_start_offset(menu_sample)
  end
  if r.ImGui_MenuItem(ctx, "Clear saved start", nil, false, saved) then
    clear_sample_start_offset_saved(menu_sample)
  end
  r.ImGui_Separator(ctx)
  if r.ImGui_MenuItem(ctx, "Save volume to sample") then
    save_sample_gain(menu_sample)
  end
  if r.ImGui_MenuItem(ctx, "Clear saved volume", nil, false, vol_saved) then
    clear_sample_gain_saved(menu_sample)
  end
  r.ImGui_Separator(ctx)
  if r.ImGui_MenuItem(ctx, "Save all") then
    save_sample_header_settings(menu_sample)
  end
  r.ImGui_Separator(ctx)
  if r.ImGui_MenuItem(ctx, "Copy path") then
    if r.ImGui_SetClipboardText then
      r.ImGui_SetClipboardText(ctx, menu_sample.path or "")
    end
  end
  if r.ImGui_MenuItem(ctx, "Show in Finder") then
    seq_reveal_sample_in_explorer(menu_sample)
  end
  r.ImGui_EndPopup(ctx)
end

-- Mini preview waveform in the sequencer's "Track / Mix / Env" header corner.
-- Stays on the last hovered/previewed sample until a new note is hovered.
-- Click the waveform to play from the mouse position; click again while playing to stop.
-- Drag the start marker to set a project-only start; "..." saves it globally.
function draw_seq_header_preview_waveform(dl, x, y, w, h, mx, my, left_down, left_clicked)
  local playing = preview_proc ~= nil and preview_sample_obj ~= nil
  local hover_sample = resolve_seq_hovered_grid_sample()
  if hover_sample then
    state.seq_header_wave_sample = hover_sample
  elseif playing or (state.preview_paused and preview_sample_obj) then
    state.seq_header_wave_sample = preview_sample_obj
  end
  local sample = hover_sample or state.seq_header_wave_sample or preview_sample_obj
  if not sample or w < 16 or h < 10 then
    r.ImGui_DrawList_AddText(dl, x + 4, y + math.max(0, (h - 14) * 0.5), 0xE8E8E8FF, "Track / Mix / Env")
    state.seq_preview_wave_scrub = nil
    state.seq_header_start_drag = nil
    state.seq_header_vol_drag = nil
    state.seq_header_wave_press = nil
    state.seq_header_wave_press_t = nil
    return false
  end

  local is_live = playing and preview_sample_obj and preview_sample_obj.path == sample.path
  local hovered = mx >= x and mx <= x + w and my >= y and my <= y + h
  local bg = hovered and UI_THEME.surface_hvr or UI_THEME.bg_panel
  local edge = hovered and UI_THEME.border_hvr or UI_THEME.border
  r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, bg, 4.0)
  r.ImGui_DrawList_AddRect(dl, x, y, x + w, y + h, edge, 4.0, 0, 1.0)

  local inner_x = x + 3
  local inner_y = y + 2
  local inner_w = w - 6
  local inner_h = h - 4
  local peaks, duration = nil, nil
  if waveform_data and waveform_data.sample_path == sample.path
      and waveform_data.data and #waveform_data.data > 0 then
    peaks = seq_env_downsample_peaks(waveform_data.data, math.max(48, math.floor(inner_w)))
    duration = tonumber(waveform_data.duration) or tonumber(sample.duration)
  else
    peaks, duration = seq_env_get_wave_peaks(sample, math.floor(inner_w))
  end
  duration = duration or sample.duration or 0.0
  local view0, view1 = wave_view_ensure(sample, duration)
  if peaks then
    seq_draw_env_waveform(dl, inner_x, inner_y, inner_w, inner_h, peaks, view0, view1, duration)
  end

  if is_live then
    local pos = get_preview_position() or state.preview_position or 0.0
    if duration > 0 and pos >= view0 and pos <= view1 then
      local playhead_x = wave_time_to_x(pos, inner_x, inner_w, view0, view1)
      r.ImGui_DrawList_AddLine(dl, playhead_x, y + 1, playhead_x, y + h - 1, 0xFFFF88FF, 1.6)
      r.ImGui_DrawList_AddCircleFilled(dl, playhead_x, y + 3, 3.0, 0xFFFF88FF, 10)
    end
  end

  local ctl = draw_sample_wave_controls(
    dl, sample, x, y, w, h, duration, view0, view1,
    mx, my, left_down, left_clicked, "header", { show_name = true }
  )

  local alt = false
  if r.ImGui_IsKeyDown and r.ImGui_Key_LeftAlt then
    alt = r.ImGui_IsKeyDown(ctx, r.ImGui_Key_LeftAlt())
        or (r.ImGui_Key_RightAlt and r.ImGui_IsKeyDown(ctx, r.ImGui_Key_RightAlt()))
  end
  local mid_down = r.ImGui_IsMouseDown and r.ImGui_IsMouseDown(ctx, 2)
  if hovered and not (ctl and ctl.over_vol) then
    local wheel = r.ImGui_GetMouseWheel and select(1, r.ImGui_GetMouseWheel(ctx)) or 0
    if wheel and wheel ~= 0 then
      wave_view_zoom(sample, duration, mx, inner_x, inner_w, wheel)
    end
  end
  if hovered and (mid_down or (alt and left_down)) and not (ctl and ctl.consumed) then
    local dx = select(1, r.ImGui_GetMouseDelta(ctx)) or 0
    state.wave_view_pan = true
    wave_view_pan(sample, duration, dx, inner_w)
  elseif state.wave_view_pan and not mid_down and not (alt and left_down) then
    state.wave_view_pan = nil
  end
  if hovered and left_clicked and r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0)
      and not (ctl and ctl.consumed) then
    wave_view_reset(sample, duration)
  end

  local blocking = (ctl and ctl.consumed) or state.wave_view_pan
  if sample.path and not blocking and waveform_drag_should_start(hovered) then
    begin_waveform_sample_drag(sample)
    state.seq_header_wave_press = nil
    state.seq_header_wave_press_t = nil
  end
  if sample_is_waveform_drag_source(sample) then
    draw_waveform_drag_source_cue(dl, x, y, w, h)
  end

  local dbl = hovered and left_clicked and r.ImGui_IsMouseDoubleClicked
      and r.ImGui_IsMouseDoubleClicked(ctx, 0)
  local playing_now = preview_proc ~= nil and preview_sample_obj ~= nil
  if hovered and left_clicked and not blocking and not dbl then
    if playing_now then
      -- Click-to-stop while preview is already running.
      stop_preview()
      state.preview_paused = false
      state.seq_header_wave_press = nil
      state.seq_header_wave_press_t = nil
    else
      state.seq_header_wave_press = sample
      state.seq_header_wave_press_t = wave_x_to_time(mx, inner_x, inner_w, view0, view1)
    end
  end
  if state.seq_header_start_drag or state.seq_header_vol_drag or state.wave_view_pan
      or state.pending_waveform_drop then
    state.seq_header_wave_press = nil
    state.seq_header_wave_press_t = nil
  end
  if state.seq_header_wave_press and not left_down then
    local press_sample = state.seq_header_wave_press
    local press_t = state.seq_header_wave_press_t
    state.seq_header_wave_press = nil
    state.seq_header_wave_press_t = nil
    if press_sample and press_sample.path then
      preview_sample(press_sample, press_t)
    end
  end

  return hovered or (ctl and ctl.consumed)
end

SEQ_NOTE_LANE_H_BASE = 48.0
SEQ_PARAM_LANE_H_BASE = 22.0
SEQ_NOTE_LANE_H_MIN = 24.0
SEQ_NOTE_LANE_H_MAX = 480.0
SEQ_LANE_RESIZE_HIT = 5.0

function seq_lane_zoom_clamped()
  return math.max(0.5, math.min(3.0, state.seq_lane_zoom or 1.0))
end

function seq_default_note_lane_h()
  return SEQ_NOTE_LANE_H_BASE * seq_lane_zoom_clamped()
end

function seq_default_param_lane_h()
  return SEQ_PARAM_LANE_H_BASE * seq_lane_zoom_clamped()
end

function seq_clamp_note_lane_h(h)
  h = tonumber(h) or seq_default_note_lane_h()
  if h < SEQ_NOTE_LANE_H_MIN then
    h = SEQ_NOTE_LANE_H_MIN
  elseif h > SEQ_NOTE_LANE_H_MAX then
    h = SEQ_NOTE_LANE_H_MAX
  end
  return h
end

function seq_note_lane_h_for_slot(slot)
  if slot and type(slot.lane_h) == "number" and slot.lane_h > 0 then
    return seq_clamp_note_lane_h(slot.lane_h)
  end
  return seq_default_note_lane_h()
end

function seq_reset_track_lane_heights()
  for _, slot in ipairs(state.seq_tracks or {}) do
    slot.lane_h = nil
    slot.lane_h_enlarged = nil
  end
end

function seq_visible_param_lane_count()
  local n = 0
  for _, def in ipairs(SEQ_PARAM_LANES) do
    if def.key ~= "length_qn" and def.key ~= "decay" and def.key ~= "locked" and def.key ~= "vary_filter" then
      n = n + 1
    end
  end
  return n
end

function seq_enlarged_note_lane_h(slot)
  local default_h = seq_default_note_lane_h()
  local param_h = seq_default_param_lane_h()
  local param_n = seq_visible_param_lane_count()
  local others = 28.0
  for _, s in ipairs(state.seq_tracks or {}) do
    local expanded = state.seq_expanded_tracks and state.seq_expanded_tracks[tostring(s.id)]
    local extra = expanded and (param_n * param_h) or 0.0
    if slot and s.id == slot.id then
      others = others + extra
    else
      others = others + seq_note_lane_h_for_slot(s) + extra
    end
  end
  local viewport = 240.0
  local rect = state.seq_map_rect
  if rect and type(rect.h) == "number" then
    local header = 0.0
    if type(rect.header_y1) == "number" and type(rect.y) == "number" then
      header = math.max(0.0, rect.header_y1 - rect.y)
    end
    viewport = math.max(80.0, rect.h - header)
  end
  return math.max(default_h * 3.0, viewport - others)
end

function seq_toggle_enlarge_hovered_track()
  local slot = seq_hover_slot and seq_hover_slot() or nil
  if not slot then
    return false
  end
  if slot.lane_h_enlarged then
    slot.lane_h = nil
    slot.lane_h_enlarged = nil
  else
    slot.lane_h = seq_clamp_note_lane_h(seq_enlarged_note_lane_h(slot))
    slot.lane_h_enlarged = true
  end
  save_config()
  return true
end

function seq_update_track_lane_h_drag()
  local drag = state.seq_lane_h_drag
  if not drag or not ctx then
    return
  end
  local down = r.ImGui_IsMouseDown and r.ImGui_IsMouseDown(ctx, 0)
  if not down then
    state.seq_lane_h_drag = nil
    save_config()
    return
  end
  local _, my = r.ImGui_GetMousePos(ctx)
  local slot = seq_find_slot_by_id(drag.slot_id)
  if not slot then
    state.seq_lane_h_drag = nil
    return
  end
  local new_h = drag.start_h + (my - drag.start_my)
  if math.abs(my - drag.start_my) >= 1.0 then
    drag.moved = true
  end
  if drag.moved then
    slot.lane_h = seq_clamp_note_lane_h(new_h)
    slot.lane_h_enlarged = nil
  end
end

function seq_hit_track_lane_resize(row_positions, mx, my, x0, x1)
  if not row_positions or not mx or not my then
    return nil, nil, nil
  end
  if mx < x0 or mx > x1 then
    return nil, nil, nil
  end
  local best_slot, best_h, best_y, best_dist = nil, nil, nil, SEQ_LANE_RESIZE_HIT + 1.0
  local i = 1
  while i <= #row_positions do
    local pos = row_positions[i]
    local slot = pos.row and pos.row.slot
    if slot then
      local j = i
      local note_h = (pos.row.type == "note") and (pos.y1 - pos.y0) or nil
      while j + 1 <= #row_positions do
        local nxt = row_positions[j + 1]
        if not nxt.row or nxt.row.slot ~= slot then
          break
        end
        j = j + 1
        if nxt.row.type == "note" then
          note_h = nxt.y1 - nxt.y0
        end
      end
      local divider_y = row_positions[j].y1
      local dist = math.abs(my - divider_y)
      if note_h and dist <= SEQ_LANE_RESIZE_HIT and dist < best_dist then
        best_slot, best_h, best_y, best_dist = slot, note_h, divider_y, dist
      end
      i = j + 1
    else
      i = i + 1
    end
  end
  return best_slot, best_h, best_y
end

function seq_track_divider_y(row_positions, slot_id)
  local y = nil
  if not row_positions or not slot_id then
    return nil
  end
  for _, pos in ipairs(row_positions) do
    if pos.row and pos.row.slot and pos.row.slot.id == slot_id then
      y = pos.y1
    end
  end
  return y
end

function seq_track_reorder_hit_row(row_pos, mx, my, x0, timeline_x0)
  if not row_pos or not row_pos.row or row_pos.row.type ~= "note" or not row_pos.row.slot then
    return false
  end
  if my < row_pos.y0 or my > row_pos.y1 then
    return false
  end
  if mx < x0 or mx >= timeline_x0 then
    return false
  end
  local ctrl = row_pos.ctrl
  if seq_layout_hit(ctrl and ctrl.expand, mx, my) then
    return false
  end
  if seq_lane_mix_controls_hit(row_pos, mx, my, x0, timeline_x0) then
    return false
  end
  local nav_w = seq_track_nav_width(row_pos.y1 - row_pos.y0)
  if mx >= timeline_x0 - nav_w - 6.0 then
    return false
  end
  return true
end

-- Track control column minus mix knobs and sample nav (includes name/expand).
function seq_track_control_context_hit(row_pos, mx, my, x0, timeline_x0)
  if not row_pos or not row_pos.row or row_pos.row.type ~= "note" or not row_pos.row.slot then
    return false
  end
  if my < row_pos.y0 or my > row_pos.y1 then
    return false
  end
  if mx < x0 or mx >= timeline_x0 then
    return false
  end
  if seq_lane_mix_controls_hit(row_pos, mx, my, x0, timeline_x0) then
    return false
  end
  local nav_w = seq_track_nav_width(row_pos.y1 - row_pos.y0)
  if mx >= timeline_x0 - nav_w - 6.0 then
    return false
  end
  return true
end

function seq_open_track_context_menu(slot_id)
  if not slot_id then
    return false
  end
  local idx = nil
  for i, slot in ipairs(state.seq_tracks or {}) do
    if slot.id == slot_id then
      idx = i
      break
    end
  end
  if not idx then
    return false
  end
  state.seq_track_menu_id = slot_id
  state.seq_track_menu_want_open = true
  select_seq_track(idx, { preview = false })
  return true
end

function render_seq_track_context_menu()
  if state.seq_track_menu_want_open and r.ImGui_OpenPopup then
    state.seq_track_menu_want_open = nil
    r.ImGui_OpenPopup(ctx, "##seq_track_context_menu")
  end
  if not r.ImGui_BeginPopup or not r.ImGui_BeginPopup(ctx, "##seq_track_context_menu") then
    return false
  end
  local menu_id = state.seq_track_menu_id
  local slot, idx = nil, nil
  for i, s in ipairs(state.seq_tracks or {}) do
    if s.id == menu_id then
      slot, idx = s, i
      break
    end
  end
  if not slot then
    r.ImGui_EndPopup(ctx)
    return false
  end
  local label = "Delete track"
  if slot.name and slot.name ~= "" then
    label = 'Delete "' .. tostring(slot.name) .. '"'
  end
  if r.ImGui_MenuItem(ctx, label) then
    r.ImGui_CloseCurrentPopup(ctx)
    seq_delete_seq_track_at(idx)
  end
  r.ImGui_EndPopup(ctx)
  return true
end

function seq_track_index_at_lane_y(row_positions, my)
  local last_idx = nil
  for _, pos in ipairs(row_positions or {}) do
    if pos.row and pos.row.type == "note" and pos.row.slot then
      local _, idx = find_seq_track_by_id(pos.row.slot.id)
      if idx then
        last_idx = idx
        if my <= pos.y1 then
          return idx
        end
      end
    end
  end
  return last_idx
end

function seq_track_row_y_span(row_positions, slot_id)
  local y0, y1 = nil, nil
  for _, pos in ipairs(row_positions or {}) do
    if pos.row and pos.row.slot and pos.row.slot.id == slot_id then
      y0 = y0 and math.min(y0, pos.y0) or pos.y0
      y1 = y1 and math.max(y1, pos.y1) or pos.y1
    end
  end
  return y0, y1
end

function seq_finish_track_reorder_drag()
  local drag = state.seq_track_reorder_drag
  state.seq_track_reorder_drag = nil
  if not drag then
    return
  end
  if drag.moved then
    seq_apply_seq_order_to_arrange()
    save_config()
    if drag.undo_open then
      end_seq_undo("Reorder sequencer tracks")
    end
  elseif drag.undo_open then
    end_seq_undo("Reorder sequencer tracks")
  end
end

function seq_update_track_reorder_drag(row_positions, mx, my, left_down, left_clicked, x0, timeline_x0)
  local drag = state.seq_track_reorder_drag
  if drag then
    if not left_down then
      seq_finish_track_reorder_drag()
      return
    end
    if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
    if not drag.moved then
      if math.abs((my or 0) - (drag.start_my or 0)) >= 6.0 then
        drag.moved = true
        if not drag.undo_open then
          drag.undo_open = seq_undo_own_begin("Reorder sequencer tracks") and true or nil
        end
      else
        return
      end
    end
    local dest = seq_track_index_at_lane_y(row_positions, my)
    local _, src = find_seq_track_by_id(drag.slot_id)
    if dest and src and dest ~= src then
      seq_move_slot_index(src, dest)
    end
    return
  end
  local hover_row = nil
  for _, pos in ipairs(row_positions or {}) do
    if seq_track_reorder_hit_row(pos, mx, my, x0, timeline_x0) then
      hover_row = pos
      break
    end
  end
  if hover_row and not state.seq_over_lane_resize and #(state.seq_tracks or {}) >= 2 then
    if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
    if r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, "Drag to reorder tracks")
    end
  end
  if not left_clicked or state.seq_over_lane_resize or state.seq_lane_h_drag
      or state.seq_note_drag or state.seq_param_drag or state.seq_region_drag
      or state.seq_razor_drag or state.pending_waveform_drop then
    return
  end
  if #(state.seq_tracks or {}) < 2 then
    return
  end
  if hover_row then
    local slot = hover_row.row.slot
    local _, idx = find_seq_track_by_id(slot.id)
    if idx then
      state.seq_track_reorder_drag = {
        slot_id = slot.id,
        start_idx = idx,
        start_my = my,
        moved = false,
      }
      select_seq_track(idx, { preview = false })
    end
  end
end

function seq_draw_track_reorder_overlay(dl, row_positions, x0, x1)
  local drag = state.seq_track_reorder_drag
  if not drag or not drag.moved or not dl then
    return
  end
  local y0, y1 = seq_track_row_y_span(row_positions, drag.slot_id)
  if not y0 or not y1 then
    return
  end
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, 0x4DE8FF33, 0)
  r.ImGui_DrawList_AddRect(dl, x0 + 0.5, y0 + 0.5, x1 - 0.5, y1 - 0.5, 0x4DE8FFCC, 0, 0, 2.0)
end

function seq_apply_track_lane_resize_interaction(row_positions, mx, my, x0, width, left_clicked, dl)
  state.seq_over_lane_resize = false
  if state.seq_note_drag or state.seq_param_drag or state.seq_region_drag
      or state.seq_razor_drag or state.pending_waveform_drop or state.seq_track_reorder_drag then
    return
  end
  local slot, note_h, divider_y = seq_hit_track_lane_resize(row_positions, mx, my, x0, x0 + width)
  if state.seq_lane_h_drag then
    slot = seq_find_slot_by_id(state.seq_lane_h_drag.slot_id) or slot
    divider_y = seq_track_divider_y(row_positions, state.seq_lane_h_drag.slot_id) or divider_y
    note_h = note_h or state.seq_lane_h_drag.start_h
  end
  if not slot then
    return
  end
  state.seq_over_lane_resize = true
  if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeNS then
    r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeNS())
  end
  if dl and divider_y then
    r.ImGui_DrawList_AddLine(dl, x0, divider_y, x0 + width, divider_y, 0xFFE599FF, 3.0)
  end
  if left_clicked and not state.seq_lane_h_drag then
    state.seq_lane_h_drag = {
      slot_id = slot.id,
      start_my = my,
      start_h = note_h or seq_note_lane_h_for_slot(slot),
    }
  end
  if r.ImGui_SetTooltip and not state.seq_lane_h_drag then
    r.ImGui_SetTooltip(ctx, "Drag to resize track height")
  end
end

function render_sequencer_map()
  seq_sec_per_qn = nil
  seq_decay_clear_hits()
  local region = get_selected_seq_region()
  local avail_x, avail_y = r.ImGui_GetContentRegionAvail(ctx)
  local width = math.max(720.0, avail_x)
  seq_update_track_lane_h_drag()
  seq_sync_track_order_from_arrange()
  local lane_zoom = seq_lane_zoom_clamped()
  state.seq_lane_zoom = lane_zoom
  local note_lane_h = seq_default_note_lane_h()
  local param_lane_h = seq_default_param_lane_h()
  local region_lane_h = 22.0
  local ruler_lane_h = 30.0
  local header_h = region_lane_h + ruler_lane_h
  local visual_rows = {}
  for _, slot in ipairs(state.seq_tracks) do
    seq_normalize_slot_mix(slot)
    visual_rows[#visual_rows + 1] = { type = "note", slot = slot, h = seq_note_lane_h_for_slot(slot) }
    if state.seq_expanded_tracks[tostring(slot.id)] then
      for _, def in ipairs(SEQ_PARAM_LANES) do
        if def.key ~= "length_qn" and def.key ~= "decay" and def.key ~= "locked" and def.key ~= "vary_filter" then
          visual_rows[#visual_rows + 1] = { type = "param", slot = slot, param = def, h = param_lane_h }
        end
      end
    end
  end
  if #visual_rows == 0 then
    visual_rows[#visual_rows + 1] = { type = "empty", h = note_lane_h }
  end
  local rows_h = 0.0
  for _, row in ipairs(visual_rows) do
    rows_h = rows_h + row.h
  end
  local add_track_row_h = 28.0
  local map_body_h = rows_h + add_track_row_h

  local child_flags = 0
  if r.ImGui_ChildFlags_Border then child_flags = r.ImGui_ChildFlags_Border end
  local no_scroll_flags = r.ImGui_WindowFlags_NoScrollbar() | r.ImGui_WindowFlags_NoScrollWithMouse()
  if not r.ImGui_BeginChild(ctx, "sequencer_map_area", 0, math.max(0, avail_y), child_flags, no_scroll_flags) then
    state.seq_link_hover_region_id = nil
    return
  end

  local x0, y0 = r.ImGui_GetCursorScreenPos(ctx)
  local header_y1 = y0 + header_h
  -- Pin region lane + ruler at the top (outside the scrollable track list).
  -- Move the cursor without a Dummy so the header stays click-through for
  -- extras flyouts that draw into the ruler.
  r.ImGui_SetCursorScreenPos(ctx, x0, header_y1)

  local _, tracks_avail_y = r.ImGui_GetContentRegionAvail(ctx)
  local body_viewport_y1 = header_y1 + math.max(0, tracks_avail_y)

  -- Popup clicks must not fall through into sequencer geometry hit-testing.
  local popup_blocks_input = imgui_any_popup_open()
  local left_clicked = (not popup_blocks_input) and r.ImGui_IsMouseClicked(ctx, 0)
  local right_clicked = (not popup_blocks_input) and r.ImGui_IsMouseClicked(ctx, 1)
  local left_down = (not popup_blocks_input) and r.ImGui_IsMouseDown(ctx, 0)
  local right_down = (not popup_blocks_input) and r.ImGui_IsMouseDown(ctx, 1)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local mx, my = r.ImGui_GetMousePos(ctx)
  local header_hovered = (not popup_blocks_input) and mx >= x0 and mx <= x0 + width and my >= y0 and my <= header_y1
  local body_hovered = (not popup_blocks_input) and mx >= x0 and mx <= x0 + width and my >= header_y1 and my <= body_viewport_y1
  local over_random_flyout = seq_random_flyout_hit(mx, my) or (state.seq_random_knob_drag ~= nil)
  if over_random_flyout then
    header_hovered = false
    body_hovered = false
    right_clicked = false
  end
  local hovered = header_hovered or body_hovered
  local body_y0, body_y1

  local view_start, view_end = get_arrange_view_range()
  local arrange_start_qn = time_to_qn(view_start) or 0.0
  local arrange_end_qn = time_to_qn(view_end) or (arrange_start_qn + (state.seq_grid_qn or 0.25) * 16.0)
  local arrange_span_qn = math.max(state.seq_grid_qn or 0.25, arrange_end_qn - arrange_start_qn)
  if (state.seq_follow_arrange or not state.seq_view_start_qn) and not seq_view_is_driving_arrange() then
    state.seq_view_start_qn = arrange_start_qn
    state.seq_view_span_qn = arrange_span_qn
    seq_timeline_scroll_stop()
  elseif not state.seq_view_span_qn or state.seq_view_span_qn <= 0 then
    state.seq_view_span_qn = get_seq_region_length_qn(region)
  end

  local start_qn, end_qn, step_qn, step_count = get_visible_qn_grid_range(
    state.seq_view_start_qn,
    state.seq_view_start_qn + (state.seq_view_span_qn or get_seq_region_length_qn(region))
  )
  -- Continuous view window (smooth scroll). Grid-aligned start_qn/end_qn are only
  -- used for cell indexing; rendering and hit-testing use the raw view coords.
  local view_start_qn = state.seq_view_start_qn or start_qn
  local view_span_qn = state.seq_view_span_qn or math.max(step_qn, end_qn - start_qn)
  local qn_span = view_span_qn
  local scroll_now = r.time_precise()
  local scroll_dt = math.min(0.05, math.max(0.001, scroll_now - (state.seq_scroll_last_t or scroll_now)))
  state.seq_scroll_last_t = scroll_now
  local label_w = math.min(340.0, math.max(268.0, width * 0.34))
  local timeline_x0 = x0 + label_w
  local timeline_w = math.max(120.0, width - label_w)
  state.seq_map_rect = {
    x = x0,
    y = y0,
    w = width,
    h = math.max(0.0, (body_viewport_y1 or y0) - y0),
    timeline_x = timeline_x0,
    timeline_w = timeline_w,
    header_y1 = header_y1,
  }

  -- Floating "keep pattern?" confirmation bar geometry. Computed up-front so we
  -- can suppress grid interactions underneath it (otherwise clicking the tick
  -- would also toggle a note in the cell below).
  local show_confirm = state.seq_pattern_confirm and state.seq_pattern_confirm.active
  local cb_x0, cb_y0, cb_x1, cb_y1
  if show_confirm then
    local cb_h = 34.0
    local cb_w = 240.0
    local confirm_region = region
    if state.seq_pattern_confirm.region_id then
      confirm_region = get_seq_region_by_id(state.seq_pattern_confirm.region_id) or region
    end
    if confirm_region then
      local reg_start = confirm_region.start_qn or 0.0
      local reg_end = reg_start + get_seq_region_length_qn(confirm_region)
      local rx0 = math.max(timeline_x0, timeline_x0 + ((reg_start - view_start_qn) / qn_span) * timeline_w)
      local rx1 = math.min(timeline_x0 + timeline_w, timeline_x0 + ((reg_end - view_start_qn) / qn_span) * timeline_w)
      if rx1 > rx0 + 48.0 then
        cb_w = math.min(cb_w, rx1 - rx0 - 8.0)
        cb_x0 = rx0 + math.max(0.0, (rx1 - rx0 - cb_w) * 0.5)
      else
        cb_x0 = timeline_x0 + math.max(0.0, (timeline_w - cb_w) * 0.5)
      end
    else
      cb_x0 = timeline_x0 + math.max(0.0, (timeline_w - cb_w) * 0.5)
    end
    -- Sit just above the region's note grid (below the ruler), centered on the region span.
    cb_y0 = header_y1 - cb_h - 6.0
    cb_x1 = cb_x0 + cb_w
    cb_y1 = cb_y0 + cb_h
    if mx >= cb_x0 and mx <= cb_x1 and my >= cb_y0 and my <= cb_y1 then
      hovered = false
    end
  end

  local over_header_wave = mx >= (x0 + 4) and mx <= (timeline_x0 - 4)
      and my >= (y0 + 3) and my <= header_y1
  if hovered and not over_header_wave then
    -- ReaImGui returns vertical and horizontal wheel as two values from one call.
    local wheel, wheel_h = r.ImGui_GetMouseWheel(ctx)
    wheel_h = wheel_h or 0.0
    local natural_scroll = (state.seq_scroll_mode == "natural")
    -- In natural mode the vertical wheel is left for ImGui to scroll the track
    -- list vertically; the horizontal wheel (trackpad/Magic Mouse) pans the
    -- timeline. In legacy mode the vertical wheel pans the timeline.
    local pan_wheel = natural_scroll and wheel_h or wheel
    -- Zoom gestures keep using the vertical wheel together with their modifier.
    -- Shift + horizontal wheel/trackpad scroll zooms the timeline.
    local shift_hzoom = wheel_h ~= 0 and is_shift_down()
    if wheel ~= 0 and mod_active("lane_zoom") and (not shift_hzoom or math.abs(wheel) >= math.abs(wheel_h)) then
      local zoom = state.seq_lane_zoom or 1.0
      local new_zoom = math.max(0.5, math.min(3.0, zoom * math.exp(wheel * 0.15)))
      if math.abs(new_zoom - zoom) > 1e-4 then
        state.seq_lane_zoom = new_zoom
        seq_reset_track_lane_heights()
        state.seq_lane_h_drag = nil
        save_config()
      end
    elseif (wheel ~= 0 and mod_active("time_zoom")) or shift_hzoom then
      local zoom_delta = shift_hzoom and -wheel_h or wheel
      if seq_apply_time_zoom(zoom_delta, mx, timeline_x0, timeline_w, view_start_qn, qn_span, step_qn) then
        start_qn, end_qn, step_qn, step_count = get_visible_qn_grid_range(state.seq_view_start_qn, state.seq_view_start_qn + state.seq_view_span_qn)
        view_start_qn = state.seq_view_start_qn
        view_span_qn = state.seq_view_span_qn
        qn_span = view_span_qn
      end
    elseif pan_wheel ~= 0 then
      if state.seq_follow_arrange then
        state.seq_drive_arrange = true
      end
      seq_timeline_scroll_impulse(pan_wheel, view_span_qn)
    end
  end

  if seq_timeline_scroll_apply_inertia(view_span_qn, scroll_dt) then
    start_qn, end_qn, step_qn, step_count = get_visible_qn_grid_range(
      state.seq_view_start_qn,
      state.seq_view_start_qn + (state.seq_view_span_qn or view_span_qn)
    )
    view_start_qn = state.seq_view_start_qn
  end

  if seq_view_is_driving_arrange() then
    seq_push_view_to_arrange()
    if not seq_timeline_scroll_is_active() then
      state.seq_drive_arrange = false
    end
  end

  local measure_guides = collect_measure_guides_qn(start_qn, end_qn, 1024)
  local active_cells = seq_build_visible_active_cells(start_qn, end_qn, step_qn, step_count)
  local selected_region_id = region.id
  local pattern = get_seq_pattern(region.pattern_id, true)
  local random_edit_region = state.seq_random_edit_region_id and get_seq_region_by_id(state.seq_random_edit_region_id) or nil
  local random_edit_pattern = random_edit_region and get_seq_pattern(random_edit_region.pattern_id, true) or nil
  local random_focus_prev = state.seq_random_active_key
  local random_focus_effective = random_focus_prev
  local random_focus_next = nil
  local random_overlay_text = nil
  local random_overlay_y = nil
  local random_overlay_x = nil
  if state.seq_random_edit_region_id and not random_edit_region then
    state.seq_random_edit_region_id = nil
    state.seq_random_active_key = nil
  end
  local now_t = r.time_precise()
  prune_seq_note_anims(now_t)
  prune_seq_track_play_anims(now_t)

  local function qn_to_x(qn) return timeline_x0 + ((qn - view_start_qn) / qn_span) * timeline_w end
  -- Cell edges must use the same continuous QN mapping as grid/region lines.
  -- Using col*cell_w drifts whenever view_start_qn is not grid-aligned.
  local function col_x0(col) return qn_to_x(start_qn + col * step_qn) end
  local function col_x1(col) return qn_to_x(start_qn + (col + 1) * step_qn) end
  local timeline_x1 = timeline_x0 + timeline_w
  local function push_timeline_clip(clip_y0, clip_y1)
    if r.ImGui_DrawList_PushClipRect then
      r.ImGui_DrawList_PushClipRect(dl, timeline_x0, clip_y0, timeline_x1, clip_y1, true)
      return true
    end
    return false
  end
  local function pop_timeline_clip(pushed)
    if pushed and r.ImGui_DrawList_PopClipRect then
      r.ImGui_DrawList_PopClipRect(dl)
    end
  end
  local function label_for_step(step)
    local denom = math.floor((4.0 / step) + 0.5)
    if denom > 0 and math.abs(step - (4.0 / denom)) < 0.0001 then return "1/" .. tostring(denom) end
    return string.format("%.3f QN", step)
  end

  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x0 + width, header_y1, UI_THEME.bg, 6.0)
  r.ImGui_DrawList_AddRect(dl, x0, y0, x0 + width, header_y1, 0x40516AFF, 6.0, 0, 1.2)
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x0 + width, header_y1, UI_THEME.surface, 0)
  r.ImGui_DrawList_AddRectFilled(dl, timeline_x0, y0, timeline_x0 + timeline_w, y0 + region_lane_h, UI_THEME.bg_panel, 0)
  r.ImGui_DrawList_AddLine(dl, timeline_x0, y0 + region_lane_h, timeline_x0 + timeline_w, y0 + region_lane_h, 0x40516AFF, 1.0)
  r.ImGui_DrawList_AddLine(dl, timeline_x0, y0, timeline_x0, header_y1, 0x70829CFF, 1.5)
  r.ImGui_DrawList_AddLine(dl, timeline_x0, header_y1, timeline_x0 + timeline_w, header_y1, 0x607086FF, 2.0)
  draw_seq_header_preview_waveform(
    dl,
    x0 + 4,
    y0 + 3,
    math.max(16.0, timeline_x0 - x0 - 8),
    math.max(10.0, header_y1 - y0 - 6),
    mx, my, left_down, left_clicked
  )

  local measure_y0 = y0 + region_lane_h
  local measure_line_clr = 0x5A7A9840
  local measure_label_clr = 0x90A8C888
  local measure_header_clip = push_timeline_clip(measure_y0, header_y1)
  for i, guide in ipairs(measure_guides) do
    local px = qn_to_x(guide.qn_start)
    if px >= timeline_x0 and px <= timeline_x1 then
      local next_guide = measure_guides[i + 1]
      local measure_px = next_guide and math.abs(qn_to_x(next_guide.qn_start) - px) or (4.0 / qn_span) * timeline_w
      local show_every = 1
      if measure_px < 12 then
        show_every = 32
      elseif measure_px < 20 then
        show_every = 16
      elseif measure_px < 35 then
        show_every = 8
      elseif measure_px < 60 then
        show_every = 4
      elseif measure_px < 95 then
        show_every = 2
      end
      local measure_num = guide.display_measure or (guide.measure + 1)
      if (guide.measure % show_every) == 0 then
        r.ImGui_DrawList_AddLine(dl, px, measure_y0, px, header_y1, measure_line_clr, 1.0)
        r.ImGui_DrawList_AddText(dl, px + 4, measure_y0 + 7, measure_label_clr, tostring(measure_num))
      end
    end
  end
  pop_timeline_clip(measure_header_clip)

  local link_hover = seq_update_link_hover(mx, my, y0, region_lane_h, timeline_x0, timeline_w, view_start_qn, qn_span, qn_to_x)

  -- Region blocks live above the ruler and align to the sequencer timeline.
  for _, reg in ipairs(state.seq_regions) do
    local reg_start = reg.start_qn or 0.0
    local reg_end = reg_start + get_seq_region_length_qn(reg)
    if reg_end >= start_qn and reg_start <= end_qn then
      local rx0 = math.max(timeline_x0, qn_to_x(reg_start))
      local rx1 = math.min(timeline_x0 + timeline_w, qn_to_x(reg_end))
      local selected = region and reg.id == region.id
      local linked = seq_region_is_linked(reg)
      local link_hl = seq_region_in_link_group(reg, link_hover)
      local swap_target = state.seq_region_drag and state.seq_region_drag.swap_region_id == reg.id
      local fill = seq_region_pool_color(reg.pool_id, selected and 220 or (link_hl and 210 or 78))
      if swap_target then
        fill = seq_region_pool_color(reg.pool_id, 90)
      end
      local edge = selected and 0xFFFFFFFF or seq_region_pool_color(reg.pool_id, link_hl and 230 or 120)
      if swap_target or link_hl then
        edge = 0xFFE599FF
      end
      r.ImGui_DrawList_AddRectFilled(dl, rx0 + 1, y0 + 3, rx1 - 1, y0 + region_lane_h - 3, fill, 4.0)
      r.ImGui_DrawList_AddRect(dl, rx0 + 1, y0 + 3, rx1 - 1, y0 + region_lane_h - 3, edge, 4.0, 0, (selected or link_hl) and 1.6 or 1.0)
      if link_hl then
        r.ImGui_DrawList_AddRect(dl, rx0, y0 + 1, rx1, y0 + region_lane_h - 1, 0xFFE599AA, 4.0, 0, 1.2)
      end
      local link_fits = linked and (rx1 - rx0) >= (SEQ_LINK_ICON_SIZE + SEQ_LINK_HIT_PAD * 2 + 8)
      local label_x = rx0 + 6
      if link_fits then
        label_x = rx0 + 6 + SEQ_LINK_ICON_SIZE + SEQ_LINK_HIT_PAD
      end
      local _, has_prob, has_human, has_vel, has_vary, has_stut, has_ghost, has_grace, has_after = seq_collect_region_random_entries(reg)
      local chips_x0 = link_fits and (rx0 + SEQ_LINK_ICON_SIZE + SEQ_LINK_HIT_PAD + 8) or rx0
      local random_labels = seq_region_random_label_layout(chips_x0, rx1, y0, region_lane_h, has_prob, has_human, has_vel, has_vary, has_stut, has_ghost, has_grace, has_after)
      local name_right = rx1 - 6
      if #random_labels > 0 then
        name_right = random_labels[1].x0 - 4
      end
      local region_clipped = false
      if r.ImGui_DrawList_PushClipRect then
        r.ImGui_DrawList_PushClipRect(dl, rx0, y0, rx1, y0 + region_lane_h, true)
        region_clipped = true
      end
      if link_fits then
        local icon_x, icon_y = seq_region_link_icon_xy(rx0, y0, region_lane_h)
        local lx0, ly0, lx1, ly1 = seq_region_link_hit_rect(rx0, y0, region_lane_h)
        local link_hovered = mx >= lx0 and mx <= lx1 and my >= ly0 and my <= ly1
        seq_draw_link_icon(dl, icon_x, icon_y, selected and 0xFFFFFFFF or 0xFFFFFF96, link_hovered or link_hl)
      end
      if name_right - label_x > 16 then
        local label = reg.name or ("Region " .. reg.id)
        r.ImGui_DrawList_AddText(dl, label_x, y0 + 5, selected and 0xFFFFFFFF or 0xFFFFFF96, label)
      end
      seq_draw_region_random_labels(dl, random_labels, mx, my)
      if region_clipped then
        r.ImGui_DrawList_PopClipRect(dl)
      end
      r.ImGui_DrawList_AddLine(dl, rx0, y0, rx0, header_y1, edge, (selected or link_hl) and 2.5 or 1.5)
    end
  end

  if state.seq_region_drag and left_down then
    local drag = state.seq_region_drag
    local current_qn_raw = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
    local current_qn = seq_snap_qn_for_region_drag(current_qn_raw, step_qn)
    local function begin_region_drag_undo()
      if not drag.undo_started then
        begin_seq_undo(drag.undo_label or "Edit sequencer region")
        drag.undo_started = true
      end
    end
    if drag.mode == "move" then
      local reg = get_seq_region_by_id(drag.region_id)
      if reg then
        local anchor_qn_raw = drag.anchor_qn_raw or drag.anchor_qn or current_qn_raw
        local desired = drag.orig_start_qn + (current_qn_raw - anchor_qn_raw)
        desired = math.max(0.0, seq_snap_qn_for_region_move(desired, step_qn))
        drag.preview_start_qn = desired
        local over = seq_region_containing_qn(current_qn_raw, drag.region_id)
        drag.swap_region_id = over and over.id or nil
      end
    elseif drag.mode == "pool_copy" then
      local desired = math.max(0.0, seq_snap_qn_for_region_drag(current_qn_raw - (drag.anchor_offset_qn or 0.0), step_qn))
      local insert_qn, over = seq_region_insert_qn(current_qn_raw, drag.source_region_id)
      if over then
        drag.current_start_qn = insert_qn
        drag.insert_qn = insert_qn
        drag.insert_target_id = over.id
      else
        drag.current_start_qn = desired
        drag.insert_qn = desired
        drag.insert_target_id = nil
      end
    elseif drag.mode == "resize_left" then
      local reg = get_seq_region_by_id(drag.region_id)
      if reg then
        begin_region_drag_undo()
        if seq_resize_region_start(reg, current_qn, step_qn) then
          seq_select_region(reg)
          region = reg
        end
      end
    elseif drag.mode == "resize_right" then
      local reg = get_seq_region_by_id(drag.region_id)
      if reg then
        begin_region_drag_undo()
        if seq_resize_region_end(reg, current_qn, step_qn) then
          seq_select_region(reg)
          region = reg
        end
      end
    elseif drag.mode == "create" then
      drag.current_qn = current_qn
    end
  end

  if state.seq_region_drag then
    local drag = state.seq_region_drag
    if drag.mode == "move" then
      local reg = get_seq_region_by_id(drag.region_id)
      if reg then
        local swap = drag.swap_region_id and get_seq_region_by_id(drag.swap_region_id)
        local orig_start = drag.orig_start_qn or (reg.start_qn or 0.0)
        if swap then
          local swap_start = swap.start_qn or 0.0
          local swap_len = get_seq_region_length_qn(swap)
          local drag_len = get_seq_region_length_qn({ start_qn = swap_start, length_bars = reg.length_bars })
          seq_draw_region_ghost(dl, swap_start, swap_start + drag_len, y0, region_lane_h, timeline_x0, timeline_w, qn_to_x,
            seq_region_pool_color(reg.pool_id, 110), 0xFFE599FF, (reg.name or "Region") .. "  ·  swap")
          seq_draw_region_ghost(dl, orig_start, orig_start + swap_len, y0, region_lane_h, timeline_x0, timeline_w, qn_to_x,
            seq_region_pool_color(swap.pool_id, 80), seq_region_pool_color(swap.pool_id, 210), (swap.name or "Region") .. "  ·  swap")
        elseif drag.preview_start_qn then
          local ghost_start = drag.preview_start_qn
          local ghost_end = ghost_start + get_seq_region_length_qn({ start_qn = ghost_start, length_bars = reg.length_bars })
          seq_draw_region_ghost(dl, ghost_start, ghost_end, y0, region_lane_h, timeline_x0, timeline_w, qn_to_x,
            seq_region_pool_color(reg.pool_id, 100), seq_region_pool_color(reg.pool_id, 220), reg.name or "Region")
        end
        if r.ImGui_SetTooltip then
          if swap then
            r.ImGui_SetTooltip(ctx, "Release to swap region positions")
          else
            r.ImGui_SetTooltip(ctx, "Release to move region")
          end
        end
      end
    elseif drag.mode == "pool_copy" and drag.current_start_qn then
      local src = get_seq_region_by_id(drag.source_region_id)
      if src then
        local ghost_start = drag.current_start_qn
        local ghost_end = ghost_start + get_seq_region_length_qn({ start_qn = ghost_start, length_bars = src.length_bars })
        seq_draw_region_ghost(dl, ghost_start, ghost_end, y0, region_lane_h, timeline_x0, timeline_w, qn_to_x,
          seq_region_pool_color(src.pool_id, 90), seq_region_pool_color(src.pool_id, 200),
          (src.name or "Region") .. "  ·  insert")
        if r.ImGui_SetTooltip then
          r.ImGui_SetTooltip(ctx, "Release to insert a copy — later regions shift right")
        end
      end
    elseif drag.mode == "create" and drag.start_qn and drag.current_qn then
      local create_start = math.min(drag.start_qn, drag.current_qn)
      local create_end = math.max(drag.start_qn, drag.current_qn)
      if create_end - create_start < step_qn then
        create_end = create_start + (drag.default_length_qn or get_seq_region_length_qn({ start_qn = create_start, length_bars = 4 }))
      end
      seq_draw_region_ghost(dl, create_start, create_end, y0, region_lane_h, timeline_x0, timeline_w, qn_to_x,
        0x4A8BD688, 0x4A8BD6FF, nil)
    end
  end

  if hovered and not state.seq_region_drag and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w and my >= y0 and my <= y0 + region_lane_h then
    local hover_hit = seq_hit_test_region_at(mx, my, y0, region_lane_h, timeline_x0, timeline_w, view_start_qn, qn_span, qn_to_x)
    if hover_hit and hover_hit.part == "link" then
      if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
        r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
      end
      if r.ImGui_SetTooltip then
        local names = seq_linked_region_names(hover_hit.region)
        local tip = "Linked region — click to unlink"
        if #names > 0 then
          tip = tip .. "\nLinked with " .. table.concat(names, ", ")
        end
        r.ImGui_SetTooltip(ctx, tip)
      end
    elseif hover_hit and (hover_hit.part == "rand_all" or hover_hit.part == "rand_prob" or hover_hit.part == "rand_human" or hover_hit.part == "rand_vel" or hover_hit.part == "rand_vary" or hover_hit.part == "rand_stut" or hover_hit.part == "rand_ghost" or hover_hit.part == "rand_grace" or hover_hit.part == "rand_after") then
      if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
        r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
      end
      if r.ImGui_SetTooltip then
        local tip = "Humanize — click to edit, double-click to reset"
        if hover_hit.part == "rand_all" then
          tip = "Randomization — click to edit, double-click to reset all"
        elseif hover_hit.part == "rand_prob" then
          tip = "Probability — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_vel" then
          tip = "Velocity humanize — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_vary" then
          tip = "Sample variation — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_stut" then
          tip = "Stutter probability — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_ghost" then
          tip = "Ghost notes — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_grace" then
          tip = "Grace notes — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_after" then
          tip = "After notes — click to edit, double-click to reset"
        end
        r.ImGui_SetTooltip(ctx, tip)
      end
    elseif hover_hit and is_shift_down() and (hover_hit.part == "left_edge" or hover_hit.part == "right_edge") then
      local insert_qn = hover_hit.region.start_qn or 0.0
      if hover_hit.part == "right_edge" then
        insert_qn = insert_qn + get_seq_region_length_qn(hover_hit.region)
      end
      local insert_len = get_seq_region_length_qn({ start_qn = insert_qn, length_bars = 4 })
      seq_draw_region_ghost(dl, insert_qn, insert_qn + insert_len, y0, region_lane_h, timeline_x0, timeline_w, qn_to_x,
        0x4A8BD655, 0x4A8BD6DD, "Insert")
      if r.ImGui_SetTooltip then
        r.ImGui_SetTooltip(ctx, "Shift+click to insert an empty region — later regions shift right")
      end
    elseif hover_hit and is_shift_down() and hover_hit.part ~= "left_edge" and hover_hit.part ~= "right_edge" and hover_hit.part ~= "link" then
      local hover_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
      local split_qn = seq_split_qn_for_region(hover_hit.region, hover_qn, step_qn)
      if split_qn then
        local sx = qn_to_x(split_qn)
        if sx >= timeline_x0 and sx <= timeline_x0 + timeline_w then
          r.ImGui_DrawList_AddLine(dl, sx, y0 + 2, sx, y0 + region_lane_h - 2, 0xFFE599FF, 2.0)
          r.ImGui_DrawList_AddLine(dl, sx, y0 + region_lane_h, sx, header_y1, 0xFFE599AA, 1.2)
        end
        if r.ImGui_SetTooltip then
          r.ImGui_SetTooltip(ctx, "Shift+click to split region")
        end
      end
    elseif hover_hit and hover_hit.region and seq_region_is_linked(hover_hit.region) then
      if r.ImGui_SetTooltip then
        local names = seq_linked_region_names(hover_hit.region)
        if #names > 0 then
          r.ImGui_SetTooltip(ctx, "Linked with " .. table.concat(names, ", "))
        else
          r.ImGui_SetTooltip(ctx, "Linked region")
        end
      end
    elseif not hover_hit then
      local hover_qn = seq_snap_qn_for_region_drag(seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span), step_qn)
      if is_shift_down() then
        local insert_qn = seq_region_insert_qn(hover_qn, nil)
        local insert_len = get_seq_region_length_qn({ start_qn = insert_qn, length_bars = 4 })
        seq_draw_region_ghost(dl, insert_qn, insert_qn + insert_len, y0, region_lane_h, timeline_x0, timeline_w, qn_to_x,
          0x4A8BD655, 0x4A8BD6DD, "Insert")
        if r.ImGui_SetTooltip then
          r.ImGui_SetTooltip(ctx, "Shift+click to insert an empty region — later regions shift right")
        end
      else
        local preview_start_qn, preview_len_qn = seq_get_default_create_region_qn(hover_qn, step_qn)
        seq_draw_region_ghost(dl, preview_start_qn, preview_start_qn + preview_len_qn, y0, region_lane_h, timeline_x0, timeline_w, qn_to_x,
          0x4A8BD655, 0x4A8BD6DD, nil)
      end
    end
  end

  if left_clicked and not hovered then
    state.seq_random_popup_pending = nil
  end

  if hovered and left_clicked and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w and not over_random_flyout then
    local clicked_qn_raw = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
    local clicked_qn = seq_snap_qn_for_region_drag(clicked_qn_raw, step_qn)
    if my >= y0 and my <= y0 + region_lane_h then
      local hit = seq_hit_test_region_at(mx, my, y0, region_lane_h, timeline_x0, timeline_w, view_start_qn, qn_span, qn_to_x)
      if hit and (hit.part == "rand_all" or hit.part == "rand_prob" or hit.part == "rand_human" or hit.part == "rand_vel" or hit.part == "rand_vary" or hit.part == "rand_stut" or hit.part == "rand_ghost" or hit.part == "rand_grace" or hit.part == "rand_after") then
        local kind = "human"
        if hit.part == "rand_all" then
          kind = "all"
        elseif hit.part == "rand_prob" then
          kind = "prob"
        elseif hit.part == "rand_vel" then
          kind = "vel"
        elseif hit.part == "rand_vary" then
          kind = "vary"
        elseif hit.part == "rand_stut" then
          kind = "stut"
        elseif hit.part == "rand_grace" then
          kind = "grace"
        elseif hit.part == "rand_after" then
          kind = "after"
        elseif hit.part == "rand_ghost" then
          kind = "ghost"
        end
        seq_handle_region_random_label_click(hit.region, kind)
        region = hit.region
      else
        state.seq_random_popup_pending = nil
        if hit then
          if hit.part == "link" then
          local label = begin_seq_undo("Unlink sequencer region")
          seq_unpool_region(hit.region)
          end_seq_undo(label)
        elseif hit.part == "body" and is_alt_down() then
          local label = begin_seq_undo("Delete sequencer region")
          seq_delete_region_by_id(hit.region.id)
          end_seq_undo(label)
          region = get_selected_seq_region()
          if region then
            selected_region_id = region.id
            pattern = get_seq_pattern(region.pattern_id, true)
          end
          active_cells = seq_build_visible_active_cells(start_qn, end_qn, step_qn, step_count)
        elseif hit.part == "body" and is_shift_down() then
          seq_select_region(hit.region)
          region = hit.region
          if seq_split_qn_for_region(hit.region, clicked_qn_raw, step_qn) then
            local label = begin_seq_undo("Split sequencer region")
            local right = seq_split_region(hit.region, clicked_qn_raw, step_qn)
            if right then
              seq_select_region(right)
              region = right
            end
            end_seq_undo(label)
          end
        elseif (hit.part == "left_edge" or hit.part == "right_edge") and is_shift_down() then
          local insert_qn = hit.region.start_qn or 0.0
          if hit.part == "right_edge" then
            insert_qn = insert_qn + get_seq_region_length_qn(hit.region)
          end
          local label = begin_seq_undo("Insert sequencer region")
          create_seq_region(4, nil, false, insert_qn, true)
          region = get_selected_seq_region()
          end_seq_undo(label)
        elseif hit.part == "left_edge" then
          seq_select_region(hit.region)
          region = hit.region
          state.seq_region_drag = {
            mode = "resize_left",
            region_id = hit.region.id,
            undo_label = "Resize sequencer region",
            undo_started = false,
          }
        elseif hit.part == "right_edge" then
          seq_select_region(hit.region)
          region = hit.region
          state.seq_region_drag = {
            mode = "resize_right",
            region_id = hit.region.id,
            undo_label = "Resize sequencer region",
            undo_started = false,
          }
        elseif hit.part == "body" then
          if r.ImGui_IsMouseDoubleClicked(ctx, 0) then
            state.seq_region_drag = nil
            state.selected_seq_region_id = hit.region.id
            seq_zoom_to_region(hit.region)
            region = hit.region
          else
            seq_select_region(hit.region)
            region = hit.region
            if is_ctrl_down() then
              state.seq_region_drag = {
                mode = "pool_copy",
                source_region_id = hit.region.id,
                anchor_offset_qn = clicked_qn - (hit.region.start_qn or 0.0),
                current_start_qn = hit.region.start_qn,
                length_bars = hit.region.length_bars,
                undo_label = "Pool copy sequencer region",
                start_mx = mx,
                start_my = my,
              }
            else
              state.seq_region_drag = {
                mode = "move",
                region_id = hit.region.id,
                anchor_qn = clicked_qn,
                anchor_qn_raw = clicked_qn_raw,
                orig_start_qn = hit.region.start_qn or 0.0,
                undo_label = "Move sequencer region",
                undo_started = false,
              }
            end
          end
        end
      else
        if is_shift_down() then
          local insert_qn = seq_region_insert_qn(clicked_qn, nil)
          local label = begin_seq_undo("Insert sequencer region")
          create_seq_region(4, nil, false, insert_qn, true)
          region = get_selected_seq_region()
          end_seq_undo(label)
        else
          local create_start_qn, create_length_qn, create_insert = seq_get_default_create_region_qn(clicked_qn, step_qn)
          state.seq_region_drag = {
            mode = "create",
            start_qn = create_start_qn,
            current_qn = create_start_qn,
            default_length_qn = create_length_qn,
            insert = create_insert,
            undo_label = "Create sequencer region",
            start_mx = mx,
            start_my = my,
          }
        end
      end
      end
    elseif my > y0 + region_lane_h and my <= header_y1 then
      state.seq_random_popup_pending = nil
      seq_set_playhead_qn(clicked_qn)
    end
  end

  if hovered and right_clicked and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w and my >= y0 and my <= y0 + region_lane_h and not over_random_flyout then
    state.seq_random_popup_pending = nil
    local right_hit = seq_hit_test_region_at(mx, my, y0, region_lane_h, timeline_x0, timeline_w, start_qn, qn_span, qn_to_x)
    if right_hit and right_hit.region then
      if state.seq_random_edit_region_id == right_hit.region.id then
        state.seq_random_edit_region_id = nil
      else
        seq_select_region(right_hit.region)
        region = right_hit.region
        state.seq_random_edit_region_id = right_hit.region.id
      end
    end
  end

  render_seq_region_random_popup()

  local playhead_time = seq_get_playhead_time()
  if playhead_time then
    local playhead_qn = time_to_qn(playhead_time)
    if playhead_qn and playhead_qn >= start_qn and playhead_qn <= end_qn then
      local playhead_x = qn_to_x(playhead_qn)
      if playhead_x >= timeline_x0 - 1 and playhead_x <= timeline_x0 + timeline_w + 1 then
        local playing = r.GetPlayState and (r.GetPlayState() & 1) == 1
        local playhead_color = playing and 0xFFFF88EE or 0xFFFF8866
        local playhead_thickness = playing and 2.0 or 1.5
        r.ImGui_DrawList_AddLine(dl, playhead_x, y0, playhead_x, header_y1, playhead_color, playhead_thickness)
        r.ImGui_DrawList_AddCircleFilled(dl, playhead_x, y0 + region_lane_h + 6, 4.0, playhead_color, 12)
      end
    end
  end

  if show_confirm then
    render_seq_pattern_confirm_bar(dl, cb_x0, cb_y0, cb_x1, cb_y1)
  end

  if not r.ImGui_BeginChild(ctx, "sequencer_map_tracks", 0, math.max(0, tracks_avail_y), child_flags) then
    r.ImGui_EndChild(ctx)
    return
  end

  body_y0 = select(2, r.ImGui_GetCursorScreenPos(ctx))
  r.ImGui_Dummy(ctx, width, map_body_h)
  body_y1 = body_y0 + map_body_h

  local hover_on_razor, razor_hover_track_id, razor_hover_qn = seq_compute_razor_hover(
    mx, my, visual_rows, body_y0, body_y1, timeline_x0, timeline_w, view_start_qn, qn_span
  )

  r.ImGui_DrawList_AddRectFilled(dl, x0, body_y0, x0 + width, body_y1, UI_THEME.bg, 0)
  r.ImGui_DrawList_AddRect(dl, x0, body_y0, x0 + width, body_y1, 0x40516AFF, 0, 0, 1.2)
  r.ImGui_DrawList_AddLine(dl, timeline_x0, body_y0, timeline_x0, body_y1, 0x70829CFF, 1.5)

  for i, guide in ipairs(measure_guides) do
    local px = qn_to_x(guide.qn_start)
    if px >= timeline_x0 and px <= timeline_x1 then
      local next_guide = measure_guides[i + 1]
      local measure_px = next_guide and math.abs(qn_to_x(next_guide.qn_start) - px) or (4.0 / qn_span) * timeline_w
      local show_every = 1
      if measure_px < 12 then
        show_every = 32
      elseif measure_px < 20 then
        show_every = 16
      elseif measure_px < 35 then
        show_every = 8
      elseif measure_px < 60 then
        show_every = 4
      elseif measure_px < 95 then
        show_every = 2
      end
      if (guide.measure % show_every) == 0 then
        r.ImGui_DrawList_AddLine(dl, px, body_y0, px, body_y1, measure_line_clr, 1.0)
      end
    end
  end

  if playhead_time then
    local playhead_qn = time_to_qn(playhead_time)
    if playhead_qn and playhead_qn >= start_qn and playhead_qn <= end_qn then
      local playhead_x = qn_to_x(playhead_qn)
      if playhead_x >= timeline_x0 - 1 and playhead_x <= timeline_x0 + timeline_w + 1 then
        local playing = r.GetPlayState and (r.GetPlayState() & 1) == 1
        local playhead_color = playing and 0xFFFF88EE or 0xFFFF8866
        local playhead_thickness = playing and 2.0 or 1.5
        r.ImGui_DrawList_AddLine(dl, playhead_x, body_y0, playhead_x, body_y1, playhead_color, playhead_thickness)
        r.ImGui_DrawList_AddCircleFilled(dl, playhead_x, body_y1 - 6, 3.0, playhead_color, 10)
      end
    end
  end

  -- Region ownership cues in the sequencer grid.
  for _, reg in ipairs(state.seq_regions) do
    local reg_start = reg.start_qn or 0.0
    local reg_end = reg_start + get_seq_region_length_qn(reg)
    if reg_end >= start_qn and reg_start <= end_qn then
      local rx0 = math.max(timeline_x0, qn_to_x(reg_start))
      local rx1 = math.min(timeline_x0 + timeline_w, qn_to_x(reg_end))
      local selected = region and reg.id == region.id
      local link_hl = seq_region_in_link_group(reg, link_hover)
      local fill = seq_region_pool_color(reg.pool_id, selected and 42 or (link_hl and 52 or 10))
      local edge = link_hl and 0xFFE599FF or seq_region_pool_color(reg.pool_id, selected and 255 or 90)
      r.ImGui_DrawList_AddRectFilled(dl, rx0, body_y0, rx1, body_y1, fill, 0)
      r.ImGui_DrawList_AddLine(dl, rx0, body_y0, rx0, body_y1, edge, (selected or link_hl) and 2.5 or 1.5)
      r.ImGui_DrawList_AddLine(dl, rx1, body_y0, rx1, body_y1, edge, (selected or link_hl) and 2.0 or 1.0)
    end
  end

  local edit_def = get_seq_note_edit_mode_def()
  local edit_style = edit_def and get_seq_row_lane_style({ type = "param", param = edit_def }) or nil
  seq_clear_stutter_badge_hits()
  local row_positions = {}
  local cursor_y = body_y0
  for row_idx, row in ipairs(visual_rows) do
    local row_y0 = cursor_y
    local row_y1 = row_y0 + row.h
    row_positions[row_idx] = { y0 = row_y0, y1 = row_y1, row = row }
    cursor_y = row_y1

    local lane_style = get_seq_row_lane_style(row)
    if row.type == "note" and edit_style then
      lane_style = {
        bg = lane_style.bg,
        label_bg = edit_style.label_bg,
        timeline_bg = edit_style.timeline_bg,
        edge = edit_style.edge,
        accent = edit_style.accent,
      }
    end
    local track_boundary = row.type == "note" and row_idx > 1

    r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, x0 + width, row_y1, lane_style.bg, 0)
    r.ImGui_DrawList_AddRectFilled(dl, timeline_x0, row_y0, timeline_x0 + timeline_w, row_y1, lane_style.timeline_bg or lane_style.bg, 0)
    r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, timeline_x0 - 1, row_y1, lane_style.label_bg or lane_style.bg, 0)
    r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, x0 + 4, row_y1, lane_style.accent or UI_THEME.accent, 0)
    if row.type == "note" and row.slot then
      if row.slot.mute then
        r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, x0 + width, row_y1, 0x00000055, 0)
      elseif row.slot.solo then
        r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, x0 + 4, row_y1, 0xE8A020FF, 0)
      end
    end
    r.ImGui_DrawList_AddLine(dl, x0, row_y0, x0 + width, row_y0, lane_style.edge, 1.0)
    r.ImGui_DrawList_AddLine(dl, timeline_x0, row_y0, timeline_x0 + timeline_w, row_y0, lane_style.edge, 1.0)
    r.ImGui_DrawList_AddLine(dl, x0, row_y1, x0 + width, row_y1, lane_style.edge, 1.5)
    r.ImGui_DrawList_AddLine(dl, timeline_x0, row_y1, timeline_x0 + timeline_w, row_y1, lane_style.edge, 1.5)
    if track_boundary then
      r.ImGui_DrawList_AddLine(dl, x0, row_y0, x0 + width, row_y0, 0x8090A8FF, 2.5)
    end
    if row.type == "note" then
      local next_row = visual_rows[row_idx + 1]
      if next_row and next_row.type == "param" then
        r.ImGui_DrawList_AddLine(dl, x0, row_y1, x0 + width, row_y1, 0x607088FF, 2.0)
      end
    end

    local slot = row.slot
    if row.type == "note" and slot then
      local expanded = state.seq_expanded_tracks[tostring(slot.id)] == true
      local play_anim = get_seq_track_play_anim(slot.id, now_t)
      local cue_reg = random_edit_region or region
      local has_override = seq_slot_has_region_sample(slot, cue_reg)
      if has_override and cue_reg then
        local stripe = seq_region_pool_color(cue_reg.pool_id, 220)
        r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, x0 + 3.5, row_y1, stripe)
        local sr, sg, sb = extract_rgb_rrgbbaa(stripe)
        r.ImGui_DrawList_AddRectFilled(
          dl, x0, row_y0, timeline_x0 - 1, row_y1,
          build_color_rrgbbaa(sr, sg, sb, 26)
        )
      end
      if play_anim then
        local assigned_sample = seq_effective_slot_sample(slot, cue_reg)
          or (slot.sample_path and find_sample_by_path(slot.sample_path)) or nil
        draw_seq_track_play_row_fx(dl, x0, row_y0, timeline_x0 - 1, row_y1, play_anim.t, assigned_sample)
      end
      local name_alpha = play_anim and math.floor(180 + math.sin(play_anim.t * math.pi) * 75) or 255
      local ctrl = seq_get_track_control_layout(
        x0, row_y0, timeline_x0 - seq_track_nav_width(row.h) - 6.0, row_y1, slot
      )
      row_positions[row_idx].ctrl = ctrl
      seq_draw_track_name_and_expand(
        dl, slot, ctrl, expanded, name_alpha,
        (edit_style and edit_style.accent) or 0xFFDFAAFF,
        "Track " .. row_idx
      )

      local note_clip = push_timeline_clip(row_y0, row_y1)
      for col = 0, step_count - 1 do
        local cx0 = col_x0(col)
        local cx1 = col_x1(col)
        if cx1 > timeline_x0 and cx0 < timeline_x1 and col % 2 == 1 then
          r.ImGui_DrawList_AddRectFilled(dl, cx0, row_y0, cx1, row_y1, seq_lane_color_with_alpha(lane_style.accent, 16), 0)
        end
      end
      -- Shift insert preview is drawn under notes so a later hit stays on top.
      if seq_note_slip_modifier() and not edit_def
          and hovered and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w
          and my >= row_y0 and my <= row_y1
          and not hover_on_razor and not seq_razor_gesture_active() and not state.seq_razor_drag
          and not (seq_param_drag_button_down(state.seq_param_drag, left_down, right_down)
            and state.seq_param_drag and state.seq_param_drag.region_id == region.id)
          and not seq_lane_random_controls_hit({ y0 = row_y0, y1 = row_y1, row = row }, mx, my, timeline_x0, header_y1, body_viewport_y1) then
        local slip_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
        local slip_col = math.max(0, math.min(step_count - 1, math.floor((slip_qn - start_qn) / step_qn + 1e-9)))
        local region_end_qn = (region.start_qn or 0.0) + get_seq_region_length_qn(region)
        local slip_in_region = slip_qn >= (region.start_qn or 0.0) and slip_qn < region_end_qn
        local slip_on_note = seq_resolve_hover_note(
          active_cells[slot.id] and active_cells[slot.id][slip_col],
          slip_qn, start_qn, slip_col, step_qn
        )
        if slip_in_region and not slip_on_note
            and not seq_visible_cell_is_locked(slot, slip_col, start_qn, step_qn, active_cells) then
          local highlight_end = math.min(region_end_qn, slip_qn + step_qn, seq_next_note_vis_qn_after(region, slot.id, slip_qn, step_qn))
          local hx0 = math.max(timeline_x0, qn_to_x(slip_qn))
          local hx1 = math.min(timeline_x1, qn_to_x(highlight_end))
          if hx1 > hx0 then
            local hover_fill = (edit_style and seq_lane_color_with_alpha(edit_style.accent, 51)) or 0xFFE59933
            local hover_edge = (edit_style and seq_lane_color_with_alpha(edit_style.accent, 255)) or 0xFFE599FF
            r.ImGui_DrawList_AddRectFilled(dl, hx0, row_y0, hx1, row_y1, hover_fill, 0)
            r.ImGui_DrawList_AddRect(dl, hx0, row_y0, hx1, row_y1, hover_edge, 0, 0, 1.5)
          end
        end
      end
      for col = 0, step_count - 1 do
        local cx0 = col_x0(col)
        local cx1 = col_x1(col)
        -- Skip cells fully outside the visible timeline (continuous scroll pads extras).
        if cx1 > timeline_x0 and cx0 < timeline_x1 then
        local active = active_cells[slot.id] and active_cells[slot.id][col]
        if active then
          seq_draw_lane_packed_notes(
            dl, slot, active, row_y0, row_y1, cx0, cx1,
            selected_region_id, now_t, step_qn, qn_to_x,
            edit_def, edit_style, mx, my, hover_on_razor,
            seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span),
            start_qn, col
          )
        end
        end
      end
      seq_draw_lane_delete_anims(
        dl, slot, row_y0, row_y1, now_t, step_qn, qn_to_x,
        timeline_x0, timeline_x1, selected_region_id
      )
      local lock_hover_col = nil
      local filter_hover_col = nil
      if hovered and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w
          and my >= row_y0 and my <= row_y1 and not hover_on_razor then
        local lock_hover_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
        lock_hover_col = math.max(0, math.min(step_count - 1, math.floor((lock_hover_qn - start_qn) / step_qn + 1e-9)))
        filter_hover_col = lock_hover_col
        if not seq_visible_cell_is_locked(slot, lock_hover_col, start_qn, step_qn, active_cells) then
          lock_hover_col = nil
        end
        if not seq_vary_filter_cell_key(slot, filter_hover_col, start_qn, step_qn) then
          filter_hover_col = nil
        end
      end
      draw_seq_lock_spans(dl, slot, row_y0, row_y1, start_qn, step_qn, step_count, col_x0, col_x1, timeline_x0, timeline_x1, active_cells, seq_is_lock_def(edit_def), lock_hover_col)
      draw_seq_vary_filter_spans(dl, ctx, slot, row_y0, row_y1, start_qn, step_qn, step_count, col_x0, col_x1, timeline_x0, timeline_x1, seq_is_vary_filter_def(edit_def), filter_hover_col)
      pop_timeline_clip(note_clip)
    elseif row.type == "param" and slot and row.param then
      local def = row.param
      local lane_top = row_y0 + 2
      local lane_bot = row_y1 - 2
      local is_stutter_lane = def.key == "stutter"
      local bipolar = def.min < 0
      local lane_label = def.label
      local hotkey = def.shortcut_id and shortcut_display(def.shortcut_id)
      if hotkey and hotkey ~= "" and hotkey ~= "None" then
        lane_label = string.format("%s  %s", def.label, hotkey)
      end
      r.ImGui_DrawList_AddText(dl, x0 + 36, row_y0 + 3, lane_style.accent or UI_THEME.accent, lane_label)

      -- Baseline / zero reference for the lane.
      local base_y = lane_bot
      if not is_stutter_lane then
        if bipolar then
          base_y = seq_param_y_from_value(def, 0.0, lane_top, lane_bot, step_qn)
          r.ImGui_DrawList_AddLine(dl, timeline_x0, base_y, timeline_x0 + timeline_w, base_y, seq_lane_color_with_alpha(lane_style.accent, 90), 1.0)
        else
          r.ImGui_DrawList_AddLine(dl, timeline_x0, lane_bot, timeline_x0 + timeline_w, lane_bot, seq_lane_color_with_alpha(lane_style.accent, 90), 1.0)
        end
      end

      local param_clip = push_timeline_clip(row_y0, row_y1)
      for col = 0, step_count - 1 do
        local cx0 = col_x0(col)
        local cx1 = col_x1(col)
        if cx1 > timeline_x0 and cx0 < timeline_x1 then
        if col % 2 == 1 then
          r.ImGui_DrawList_AddRectFilled(dl, cx0, row_y0, cx1, row_y1, seq_lane_color_with_alpha(lane_style.accent, 16), 0)
        end
        local active = active_cells[slot.id] and active_cells[slot.id][col]
        if active then
          seq_draw_param_lane_packed_notes(
            dl, ctx, slot, active, def, selected_region_id, start_qn, col, step_qn,
            qn_to_x, cx0, cx1, lane_top, lane_bot, base_y, bipolar, is_stutter_lane, lane_style, region
          )
        end
        end
      end
      pop_timeline_clip(param_clip)
    else
      r.ImGui_DrawList_AddText(dl, x0 + 8, row_y0 + 8, UI_THEME.text_dim, "No sequencer tracks configured")
    end
  end

  render_seq_vary_filter_input()

  local slot_id_to_idx = {}
  for track_idx, track_slot in ipairs(state.seq_tracks) do
    slot_id_to_idx[track_slot.id] = track_idx
  end
  local map_icon_size = seq_icon_size_for_lane_h(note_lane_h)
  local map_ctrl_size = seq_ctrl_size_for_icon(map_icon_size)
  local map_nav_w = get_seq_track_sample_controls_width(map_ctrl_size, map_icon_size)
  local over_lane_mix_controls = false
  local mix_env_resync = false
  local env_resync_slot = nil

  local add_row_y0 = body_y0 + rows_h
  local add_row_y1 = add_row_y0 + add_track_row_h
  local label_col_w = timeline_x0 - x0
  r.ImGui_DrawList_AddRectFilled(dl, x0, add_row_y0, timeline_x0 - 1, add_row_y1, UI_THEME.bg_panel, 0)
  r.ImGui_DrawList_AddRectFilled(dl, timeline_x0, add_row_y0, timeline_x0 + timeline_w, add_row_y1, UI_THEME.bg, 0)
  r.ImGui_DrawList_AddLine(dl, x0, add_row_y0, x0 + width, add_row_y0, 0x607086FF, 1.5)
  r.ImGui_DrawList_AddLine(dl, x0, add_row_y1, x0 + width, add_row_y1, 0x40516AFF, 1.0)

  -- Draw visible region ownership again over row backgrounds so users can see which
  -- cells belong to each selected/copy/pooled region.
  local body_clip = push_timeline_clip(body_y0, body_y1)
  for _, reg in ipairs(state.seq_regions) do
    local reg_start = reg.start_qn or 0.0
    local reg_end = reg_start + get_seq_region_length_qn(reg)
    if reg_end >= start_qn and reg_start <= end_qn then
      local rx0 = math.max(timeline_x0, qn_to_x(reg_start))
      local rx1 = math.min(timeline_x1, qn_to_x(reg_end))
      local selected = region and reg.id == region.id
      local link_hl = seq_region_in_link_group(reg, link_hover)
      local fill = seq_region_pool_color(reg.pool_id, selected and 32 or (link_hl and 40 or 8))
      local edge = link_hl and 0xFFE599FF or seq_region_pool_color(reg.pool_id, selected and 255 or 100)
      r.ImGui_DrawList_AddRectFilled(dl, rx0, body_y0, rx1, body_y1, fill, 0)
      if not selected and not link_hl then
        r.ImGui_DrawList_AddRectFilled(dl, rx0, body_y0, rx1, body_y1, 0x00000048, 0)
      end
      r.ImGui_DrawList_AddLine(dl, rx0, body_y0, rx0, body_y1, edge, (selected or link_hl) and 2.5 or 1.5)
      r.ImGui_DrawList_AddLine(dl, rx1, body_y0, rx1, body_y1, edge, (selected or link_hl) and 2.0 or 1.0)
    end
  end

  for col = 0, step_count do
    local qn = start_qn + col * step_qn
    local px = qn_to_x(qn)
    if px >= timeline_x0 and px <= timeline_x1 then
      local clr = (math.abs(qn - math.floor(qn + 0.5)) < 0.0001) and 0x45505EFF or 0x2A303AFF
      r.ImGui_DrawList_AddLine(dl, px, body_y0, px, body_y1, clr, 1.0)
    end
  end
  pop_timeline_clip(body_clip)
  -- Keep a hard edge so timeline graphics never read as overlapping track controls.
  r.ImGui_DrawList_AddLine(dl, timeline_x0, body_y0, timeline_x0, body_y1, 0x70829CFF, 1.5)

  seq_apply_track_lane_resize_interaction(row_positions, mx, my, x0, width, left_clicked, dl)
  seq_update_track_reorder_drag(row_positions, mx, my, left_down, left_clicked, x0, timeline_x0)
  seq_draw_track_reorder_overlay(dl, row_positions, x0, x0 + width)

  local hovered_slot, hovered_col, hovered_qn, hovered_row = nil, nil, nil, nil
  local param_drag_active = seq_param_drag_button_down(state.seq_param_drag, left_down, right_down)
      and state.seq_param_drag.region_id == region.id
  if hovered and mx >= x0 and mx <= timeline_x0 + timeline_w and my >= body_y0 and my <= body_y1 then
    for _, row_pos in ipairs(row_positions) do
      if my >= row_pos.y0 and my <= row_pos.y1 then
        hovered_row = row_pos
        hovered_slot = row_pos.row.slot
        break
      end
    end
    if mx >= timeline_x0 then
      hovered_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
      hovered_col = math.max(0, math.min(step_count - 1, math.floor((hovered_qn - start_qn) / step_qn + 1e-9)))
    end
    local over_rand = random_edit_region
      and hovered_row and hovered_row.row and hovered_row.row.type == "note"
      and seq_lane_random_controls_hit(hovered_row, mx, my, timeline_x0, header_y1, body_viewport_y1)
    if hovered_slot and hovered_qn ~= nil and not over_rand then
      local hover_in_selected = hovered_qn >= region.start_qn and hovered_qn < region.start_qn + get_seq_region_length_qn(region)
      if not param_drag_active and hover_in_selected and not seq_razor_gesture_active() and not state.seq_razor_drag
          and not hover_on_razor then
        local hx0 = math.max(timeline_x0, col_x0(hovered_col))
        local hx1 = math.min(timeline_x1, col_x1(hovered_col))
        local hover_edge = (edit_style and seq_lane_color_with_alpha(edit_style.accent, 255)) or 0xFFE599FF
        local hover_active = seq_resolve_hover_note(
          active_cells[hovered_slot.id] and active_cells[hovered_slot.id][hovered_col],
          hovered_qn, start_qn, hovered_col, step_qn
        )
        local slip_empty = seq_note_slip_modifier() and not edit_def
          and hovered_row.row.type == "note" and not hover_active
        if slip_empty then
          local region_end_qn = (region.start_qn or 0.0) + get_seq_region_length_qn(region)
          hx0 = qn_to_x(hovered_qn)
          hx1 = qn_to_x(math.min(region_end_qn, hovered_qn + step_qn))
          hx0 = math.max(timeline_x0, hx0)
          hx1 = math.min(timeline_x1, hx1)
        end
        local hover_locked = hovered_row.row.type == "note"
          and seq_visible_cell_is_locked(hovered_slot, hovered_col, start_qn, step_qn, active_cells)
        local hover_filter = hovered_row.row.type == "note"
          and seq_vary_filter_cell_key(hovered_slot, hovered_col, start_qn, step_qn)
        if hx1 > hx0 and not (hover_active and hovered_row.row.type == "note") and not slip_empty and not hover_locked
            and not hover_filter
            and not state.seq_over_lane_resize then
          local hover_fill = (edit_style and seq_lane_color_with_alpha(edit_style.accent, 51)) or 0xFFE59933
          r.ImGui_DrawList_AddRectFilled(dl, hx0, hovered_row.y0, hx1, hovered_row.y1, hover_fill, 0)
          r.ImGui_DrawList_AddRect(dl, hx0, hovered_row.y0, hx1, hovered_row.y1, hover_edge, 0, 0, 1.5)
        end
        if edit_def and hovered_row.row.type == "note" and not seq_is_decay_def(edit_def)
            and not seq_is_span_overlay_def(edit_def) then
          if hover_active then
            local hit_idx = seq_stutter_hit_param_key(edit_def.key) and seq_stutter_hit_index_at_qn(hover_active.note, hover_active.abs_qn, hovered_qn, step_qn) or nil
            local hover_val = seq_note_param_value(hover_active.note, edit_def.key, hit_idx)
            local value_text = format_seq_param_value(edit_def, hover_val)
            if seq_is_stutter_def(edit_def) then
              local skew = seq_stutter_skew(hover_active.note)
              if math.abs(skew) > 0.001 then
                value_text = string.format("%s  ·  skew %+.2f", value_text, skew)
              end
            elseif hit_idx then
              value_text = string.format("%s  ·  %d/%d", value_text, hit_idx, seq_stutter_count(hover_active.note))
            end
            local text_size = { r.ImGui_CalcTextSize(ctx, value_text) }
            local text_w = text_size[1] or 0
            local text_h = text_size[2] or 0
            local text_x = hx0 + 4
            local text_y = hovered_row.y0 - 16
            r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0x000000CC, 3.0)
            r.ImGui_DrawList_AddRect(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, hover_edge, 3.0, 0, 1.0)
            r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, value_text)
          end
        end
      end
    end
  end

  local over_lane_random_controls = seq_random_flyout_hit(mx, my)
  if random_edit_region and hovered_row and hovered_row.row and hovered_row.row.type == "note" then
    over_lane_random_controls = over_lane_random_controls or seq_lane_random_controls_hit(hovered_row, mx, my, timeline_x0, header_y1, body_viewport_y1)
  end
  if state.seq_random_knob_drag then
    over_lane_random_controls = true
  end
  if hover_on_razor or over_lane_random_controls then
    state.seq_grid_hover = nil
  else
    seq_set_grid_hover(hovered_slot, hovered_col, active_cells, start_qn, step_qn, hovered_qn)
  end

  over_lane_mix_controls = false
  if hovered_row and hovered_row.row and hovered_row.row.type == "note" then
    over_lane_mix_controls = seq_lane_mix_controls_hit(hovered_row, mx, my, x0, timeline_x0, map_nav_w)
  end
  if not over_lane_mix_controls then
    for _, row_pos in ipairs(row_positions) do
      if seq_lane_mix_controls_hit(row_pos, mx, my, x0, timeline_x0, map_nav_w) then
        over_lane_mix_controls = true
        break
      end
    end
  end

  if state.seq_over_lane_resize then
    -- Cursor and divider highlight are handled by seq_apply_track_lane_resize_interaction.
  elseif state.seq_razor_drag and state.seq_razor_drag.mode == "move" then
    if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeAll then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeAll())
    end
  elseif state.seq_note_drag and state.seq_note_drag.mode == "stutter_edit"
      and r.ImGui_SetMouseCursor then
    local axis = state.seq_note_drag.axis
    if axis == "count" and r.ImGui_MouseCursor_ResizeNS then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeNS())
    elseif axis == "skew" and r.ImGui_MouseCursor_ResizeEW then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeEW())
    elseif r.ImGui_MouseCursor_ResizeAll then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeAll())
    end
  elseif (not edit_def) and seq_stutter_badge_at(mx, my) then
    local badge = seq_stutter_badge_at(mx, my)
    if badge and dl then
      r.ImGui_DrawList_AddRect(dl, badge.x0, badge.y0, badge.x1, badge.y1, 0xC9A8FFFF, 2.0, 0, 1.4)
    end
    if r.ImGui_SetMouseCursor then
      if r.ImGui_MouseCursor_ResizeAll then
        r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeAll())
      elseif r.ImGui_MouseCursor_Hand then
        r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
      end
    end
    if r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, "Drag vertically = hits\nDrag horizontally = skew")
    end
  elseif (state.seq_note_drag and (state.seq_note_drag.mode == "copy" or state.seq_note_drag.mode == "move"))
      and r.ImGui_SetMouseCursor then
    if state.seq_note_drag.mode == "move" and r.ImGui_MouseCursor_ResizeAll then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeAll())
    elseif r.ImGui_MouseCursor_Hand then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
  elseif seq_note_copy_modifier() and not edit_def and hovered_slot and hovered_qn ~= nil
      and mx >= timeline_x0 and hovered_row and hovered_row.row and hovered_row.row.type == "note"
      and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
    local hover_copy = seq_resolve_hover_note(
      active_cells[hovered_slot.id] and active_cells[hovered_slot.id][hovered_col],
      hovered_qn, start_qn, hovered_col, step_qn
    )
    if hover_copy then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
  elseif seq_note_slip_modifier() and not edit_def and hovered_slot and hovered_qn ~= nil
      and mx >= timeline_x0 and hovered_row and hovered_row.row and hovered_row.row.type == "note"
      and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeAll then
    local hover_move = seq_resolve_hover_note(
      active_cells[hovered_slot.id] and active_cells[hovered_slot.id][hovered_col],
      hovered_qn, start_qn, hovered_col, step_qn
    )
    if hover_move then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeAll())
    end
  elseif seq_razor_gesture_active() and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeNWSE then
    r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeNWSE())
  elseif hovered_slot and hovered_qn ~= nil and mx >= timeline_x0
      and seq_cell_in_any_razor(hovered_slot.id, hovered_qn)
      and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeAll then
    r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeAll())
  elseif seq_is_decay_def(edit_def) then
    local decay_kind = nil
    if state.seq_note_drag and state.seq_note_drag.mode == "decay" then
      decay_kind = state.seq_note_drag.handle
    else
      local decay_hit = seq_decay_hit_at(mx, my)
      decay_kind = decay_hit and decay_hit.kind
    end
    if decay_kind == "end" and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeEW then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeEW())
    elseif seq_decay_kind_is_curve(decay_kind) and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeNS then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeNS())
    elseif decay_kind and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
  end
  if seq_razor_gesture_active() and right_clicked and hovered_slot and hovered_qn ~= nil
      and mx >= timeline_x0 and not over_lane_mix_controls and not over_lane_random_controls
      and not state.seq_region_drag and not state.pending_waveform_drop then
    seq_begin_razor_drag(hovered_slot.id, hovered_qn, seq_razor_additive_gesture())
  elseif left_clicked and seq_has_razors() and hovered_slot and hovered_qn ~= nil
      and mx >= timeline_x0 and not over_lane_mix_controls and not over_lane_random_controls
      and not state.seq_over_lane_resize
      and not state.seq_region_drag and not state.pending_waveform_drop
      and not state.seq_razor_drag
      and seq_cell_in_any_razor(hovered_slot.id, hovered_qn) then
    seq_begin_razor_move(hovered_slot.id, hovered_qn, step_qn, seq_razor_copy_modifier())
  end
  if state.seq_razor_drag then
    seq_update_razor_drag(hovered_slot and hovered_slot.id, hovered_qn, row_positions, my)
    if state.seq_razor_drag.mode == "move" then
      seq_razor_apply_move(state.seq_razor_drag, step_qn)
    end
  end

  if hovered and left_clicked and not over_lane_mix_controls and not state.seq_over_lane_resize
      and not state.seq_track_reorder_drag then
    for _, row_pos in ipairs(row_positions) do
      local ctrl = row_pos.ctrl
      if row_pos.row.type == "note" and row_pos.row.slot and ctrl then
        if seq_layout_hit(ctrl.expand, mx, my) then
          local key = tostring(row_pos.row.slot.id)
          state.seq_expanded_tracks[key] = not state.seq_expanded_tracks[key] or nil
          save_config()
          break
        elseif (not state.pending_waveform_drop) and seq_layout_hit(ctrl.name, mx, my) then
          local track_idx = slot_id_to_idx[row_pos.row.slot.id]
          if track_idx then
            select_seq_track(track_idx)
          end
          break
        end
      end
    end
  end

  if hovered and right_clicked and not over_lane_mix_controls and not state.seq_over_lane_resize
      and not state.seq_track_reorder_drag and not state.pending_waveform_drop then
    for _, row_pos in ipairs(row_positions) do
      if seq_track_control_context_hit(row_pos, mx, my, x0, timeline_x0) then
        seq_open_track_context_menu(row_pos.row.slot.id)
        break
      end
    end
  end

  if hovered_slot and hovered_qn ~= nil and hovered_row and not state.seq_region_drag
      and not over_lane_random_controls and not over_lane_mix_controls
      and not state.seq_over_lane_resize and not state.seq_track_reorder_drag and not seq_razor_blocks_grid_edit() then
    local step_idx = math.floor(((hovered_qn - region.start_qn) / step_qn) + 1e-9)
    local in_region = hovered_qn >= region.start_qn and hovered_qn < region.start_qn + get_seq_region_length_qn(region)
    local step_key = tostring(step_idx)
    local cell_id = tostring(hovered_slot.id) .. ":" .. step_key
    local cell_active = active_cells[hovered_slot.id] and active_cells[hovered_slot.id][hovered_col]
    local active = seq_resolve_hover_note(cell_active, hovered_qn, start_qn, hovered_col, step_qn)

    local decay_hit = seq_is_decay_def(edit_def) and (left_clicked or right_clicked) and mx >= timeline_x0
      and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0))
      and seq_decay_hit_at(mx, my)
    if decay_hit and decay_hit.note then
      local hit_region = get_seq_region_by_id(decay_hit.region_id) or region
      local hit_note = get_seq_note(hit_region, decay_hit.track_id, decay_hit.step_key) or decay_hit.note
      if right_clicked then
        local label = begin_seq_undo("Reset sequencer decay")
        local changed = false
        if decay_hit.kind == "end" then
          if seq_note_has_stutter_span(hit_note, step_qn) or seq_stutter_count(hit_note) > 1 then
            if math.abs((hit_note.length_qn or 0.0) - step_qn) > 1e-9 then
              hit_note.length_qn = step_qn
              changed = true
            end
          elseif hit_note.decay_qn ~= nil then
            hit_note.decay_qn = nil
            changed = true
          end
          seq_clamp_note_fades(hit_note, seq_note_current_decay_length_qn(hit_region, seq_find_slot_by_id(decay_hit.track_id), hit_note, decay_hit.step_key, step_qn))
        elseif decay_hit.kind == "fade_in" then
          changed = seq_note_clear_fade_side(hit_note, "in")
        elseif decay_hit.kind == "fade_out" then
          changed = seq_note_clear_fade_side(hit_note, "out")
        elseif decay_hit.kind == "curve_in" then
          changed = seq_note_set_fade_curve(hit_note, "in", 0)
        elseif decay_hit.kind == "curve_out" then
          changed = seq_note_set_fade_curve(hit_note, "out", 0)
        end
        if changed then
          local hit_slot = seq_find_slot_by_id(decay_hit.track_id)
          if hit_region and hit_slot then
            sync_seq_pattern_track(hit_region.pattern_id, hit_slot, { force_rebuild = true })
          end
          save_config()
        end
        end_seq_undo(label)
        state.selected_seq_note = { region_id = hit_region.id, track_id = decay_hit.track_id, step_key = decay_hit.step_key }
      else
        local label = begin_seq_undo("Edit sequencer decay")
        local which = (decay_hit.kind == "fade_in" or decay_hit.kind == "curve_in") and "in"
          or ((decay_hit.kind == "fade_out" or decay_hit.kind == "curve_out") and "out" or nil)
        local origin_shape = 1
        local origin_curve = 0.0
        local origin_fade_qn = 0.0
        if which then
          origin_fade_qn = seq_note_fade_qn(hit_note, which)
          if origin_fade_qn > 1e-6 then
            origin_shape = seq_note_fade_shape(hit_note, which)
            origin_curve = seq_note_fade_curve(hit_note, which)
          end
        end
        state.seq_note_drag = {
          mode = "decay",
          handle = decay_hit.kind,
          track_id = decay_hit.track_id,
          region_id = hit_region.id,
          step_key = decay_hit.step_key,
          origin_x = mx,
          origin_y = my,
          origin_shape = origin_shape,
          origin_curve = origin_curve,
          origin_fade_qn = origin_fade_qn,
          note_start_qn = seq_note_abs_qn(hit_region, hit_note, decay_hit.step_key, step_qn) + (hit_note.offset_qn or 0.0),
          max_length_qn = seq_note_decay_max_qn(hit_region, seq_find_slot_by_id(decay_hit.track_id), hit_note, decay_hit.step_key, step_qn),
          undo_label = label,
          undo_open = true,
          dirty = false,
        }
        apply_seq_decay_drag(
          state.seq_note_drag, hit_region, step_qn,
          mx, my, timeline_x0, timeline_w, view_start_qn, qn_span
        )
      end
    elseif hovered_row.row.type == "param" and hovered_row.row.param and in_region and left_clicked and mx >= timeline_x0 then
      local def = hovered_row.row.param
      local start_value = def.default
      if active then
        start_value = seq_note_param_value(active.note, def.key, seq_stutter_hit_index_at_qn(active.note, active.abs_qn, hovered_qn, step_qn))
        if start_value == nil then
          start_value = def.default
        end
      else
        start_value = seq_param_value_for_drag(def, seq_param_value_from_y(def, my, hovered_row.y0 + 2, hovered_row.y1 - 2, step_qn), step_qn)
      end
      state.seq_param_drag = {
        track_id = hovered_slot.id,
        param = def.key,
        region_id = region.id,
        step_key = active and active.key or step_key,
        col = hovered_col,
        end_col = hovered_col,
        ramp = mod_active("velocity_ramp"),
        unify = mod_active("unify") and not mod_active("velocity_ramp"),
        start_value = start_value,
        origin_y = my,
        origin_count = (def.key == "stutter") and seq_clamp_stutter_count(start_value) or nil,
        button = 0,
      }
      if active then
        state.selected_seq_note = { region_id = region.id, track_id = hovered_slot.id, step_key = active.key }
      end
    elseif state.pending_waveform_drop then
      local track_idx = hovered_slot and slot_id_to_idx[hovered_slot.id]
      local drop_qn = (hovered_col ~= nil)
        and (start_qn + hovered_col * step_qn)
        or hovered_qn
      state.seq_timeline_drop_track_idx = track_idx
      state.seq_timeline_drop_time = qn_to_time(drop_qn)
      state.seq_drop_target_idx = nil
      -- Highlight the cell under the cursor and draw an insertion marker so the
      -- exact drop position on the timeline is obvious.
      local cell_x0 = col_x0(hovered_col)
      local cell_x1 = col_x1(hovered_col)
      draw_drop_target_highlight(dl, cell_x0, hovered_row.y0, cell_x1, hovered_row.y1, 2)
      local pulse = drag_pulse()
      local line_col = build_color_rrgbbaa(120, 200, 255, math.floor(170 + 85 * pulse))
      r.ImGui_DrawList_AddLine(dl, cell_x0, body_y0, cell_x0, body_y1, line_col, 2.0)
      r.ImGui_DrawList_AddTriangleFilled(dl, cell_x0 - 5, body_y0, cell_x0 + 5, body_y0, cell_x0, body_y0 + 7, line_col)
    elseif hovered_row.row.type == "note" and not in_region and left_clicked and mx >= timeline_x0 then
      local hover_reg = seq_region_at_qn(hovered_qn)
      if hover_reg then
        seq_select_region(hover_reg)
        region = hover_reg
        selected_region_id = region.id
      end
    elseif hovered_row.row.type == "note" and in_region and left_clicked and mx >= timeline_x0
        and is_alt_down() and not edit_def
        and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0)) then
      local label = begin_seq_undo("Create sequencer stutter")
      state.seq_note_drag = {
        mode = "stutter",
        track_id = hovered_slot.id,
        region_id = region.id,
        start_col = hovered_col,
        end_col = hovered_col,
        origin_y = my,
        undo_label = label,
        undo_open = true,
        dirty = false,
      }
      if apply_seq_stutter_lane_drag(
        state.seq_note_drag, region, step_qn, start_qn, step_count,
        mx, my, timeline_x0, timeline_w, view_start_qn, qn_span
      ) then
        state.seq_note_drag.dirty = true
      elseif not state.seq_note_drag.step_key then
        if state.seq_note_drag.undo_open then
          end_seq_undo(label)
        end
        state.seq_note_drag = nil
      end
    elseif hovered_row.row.type == "note" and in_region and left_clicked and mx >= timeline_x0
        and seq_note_copy_modifier() and not edit_def and not is_alt_down()
        and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0))
        and active and active.note then
      local picked = seq_pick_packed_note(active, hovered_qn, start_qn, hovered_col, step_qn) or active
      local src_region = get_seq_region_by_id(picked.region_id) or region
      local src_key = tostring(picked.key)
      local src_note = get_seq_note(src_region, hovered_slot.id, src_key) or picked.note
      local src_abs = seq_note_abs_qn(src_region, src_note, src_key, step_qn)
      local baked = seq_clone_note_keeping_sample(src_note, src_region, hovered_slot.id, src_key, hovered_slot)
      local label = begin_seq_undo("Copy sequencer note")
      state.selected_seq_note = { region_id = src_region.id, track_id = hovered_slot.id, step_key = src_key }
      state.seq_note_drag = {
        mode = "copy",
        track_id = hovered_slot.id,
        region_id = src_region.id,
        src_step_key = src_key,
        src_abs_qn = src_abs,
        src_snap_qn = math.floor((src_abs / step_qn) + 1e-9) * step_qn,
        src_note = baked,
        src_length_qn = seq_note_length_qn_for_copy(src_region, hovered_slot, src_note, src_key, step_qn),
        patterns_backup = clone_table_deep(state.seq_patterns),
        origin_x = mx,
        origin_y = my,
        undo_label = label,
        undo_open = true,
        dirty = false,
      }
    elseif hovered_row.row.type == "note" and in_region and left_clicked and mx >= timeline_x0
        and seq_note_slip_modifier() and not edit_def and not is_alt_down()
        and not seq_note_copy_modifier()
        and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0))
        and active and active.note then
      local picked = seq_pick_packed_note(active, hovered_qn, start_qn, hovered_col, step_qn) or active
      local src_region = get_seq_region_by_id(picked.region_id) or region
      local src_key = tostring(picked.key)
      local src_note = get_seq_note(src_region, hovered_slot.id, src_key) or picked.note
      local src_abs = seq_note_abs_qn(src_region, src_note, src_key, step_qn)
      local baked = seq_clone_note_keeping_sample(src_note, src_region, hovered_slot.id, src_key, hovered_slot)
      local label = begin_seq_undo("Move sequencer note")
      state.selected_seq_note = { region_id = src_region.id, track_id = hovered_slot.id, step_key = src_key }
      state.seq_note_drag = {
        mode = "move",
        snap = false,
        track_id = hovered_slot.id,
        region_id = src_region.id,
        src_step_key = src_key,
        src_abs_qn = src_abs,
        grab_qn = hovered_qn,
        src_note = baked,
        src_length_qn = seq_note_length_qn_for_copy(src_region, hovered_slot, src_note, src_key, step_qn),
        patterns_backup = clone_table_deep(state.seq_patterns),
        origin_x = mx,
        origin_y = my,
        undo_label = label,
        undo_open = true,
        dirty = false,
      }
    elseif hovered_row.row.type == "note" and in_region and left_clicked and mx >= timeline_x0
        and seq_note_slip_modifier() and not edit_def and not is_alt_down()
        and not seq_note_copy_modifier()
        and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0))
        and not active
        and not seq_visible_cell_is_locked(hovered_slot, hovered_col, start_qn, step_qn, active_cells) then
      local insert_rel = seq_quantize_free_qn(hovered_qn - (region.start_qn or 0.0))
      local insert_step = tostring(math.floor((insert_rel / step_qn) + 1e-9))
      local note = make_default_seq_note(hovered_slot, insert_step, insert_rel)
      if note then
        local label = begin_seq_undo("Insert sequencer note")
        state.seq_note_drag = {
          mode = "move",
          snap = false,
          place_new = true,
          track_id = hovered_slot.id,
          region_id = region.id,
          src_abs_qn = hovered_qn,
          grab_qn = hovered_qn,
          src_note = note,
          patterns_backup = clone_table_deep(state.seq_patterns),
          origin_x = mx,
          origin_y = my,
          undo_label = label,
          undo_open = true,
          dirty = false,
        }
        if apply_seq_note_copy_drag(
          state.seq_note_drag, step_qn, start_qn, step_count,
          mx, my, timeline_x0, timeline_w, view_start_qn, qn_span, row_positions
        ) then
          state.seq_note_drag.dirty = true
        end
      else
        log("Sequencer slot has no assigned sample")
      end
    elseif hovered_row.row.type == "note" and in_region and left_clicked and mx >= timeline_x0
        and not edit_def and not is_alt_down()
        and not seq_note_copy_modifier() and not seq_note_slip_modifier()
        and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0))
        and seq_stutter_badge_at(mx, my)
        and tostring(seq_stutter_badge_at(mx, my).track_id) == tostring(hovered_slot.id) then
      local badge = seq_stutter_badge_at(mx, my)
      local badge_region = get_seq_region_by_id(badge.region_id) or region
      local badge_note = get_seq_note(badge_region, badge.track_id, badge.step_key)
      if badge_note then
        seq_begin_stutter_edit_drag(badge_region, hovered_slot, badge.step_key, badge_note, mx, my, "Edit sequencer stutter")
      end
    elseif hovered_row.row.type == "note" and in_region and (left_clicked or right_clicked) and mx >= timeline_x0
        and not seq_vary_filter_edit_blocks_clicks() then
      if seq_is_decay_def(edit_def) then
        -- Clicks that miss decay handles do not paint or edit params.
      elseif seq_is_lock_def(edit_def) then
        local started_on_lock = seq_visible_cell_is_locked(
          hovered_slot, hovered_col, start_qn, step_qn, active_cells
        )
        local reset = right_clicked or (left_clicked and started_on_lock)
        local label = begin_seq_undo(reset and "Unlock sequencer cells" or "Lock sequencer cells")
        local changed = false
        if not reset then
          changed = seq_apply_lock_range(
            region, hovered_slot.id, hovered_col, hovered_col, start_qn, step_qn, true, active_cells
          )
        end
        state.seq_param_drag = {
          track_id = hovered_slot.id,
          param = edit_def.key,
          region_id = region.id,
          step_key = (active and active.key) or step_key,
          col = hovered_col,
          end_col = hovered_col,
          ramp = false,
          unify = true,
          start_value = reset and 0.0 or 1.0,
          source = "note",
          reset = reset,
          lock_click_span = reset and true or nil,
          button = right_clicked and 1 or 0,
          undo_label = label,
          undo_open = true,
          dirty = changed,
        }
        if active then
          state.selected_seq_note = { region_id = region.id, track_id = hovered_slot.id, step_key = active.key }
        end
      elseif seq_is_vary_filter_def(edit_def) then
        local started_on = seq_visible_cell_vary_filter(hovered_slot, hovered_col, start_qn, step_qn)
        local reset = right_clicked
        if reset then
          if started_on then
            seq_cancel_vary_filter_edit()
            local label = begin_seq_undo("Clear sequencer vary filter")
            state.seq_param_drag = {
              track_id = hovered_slot.id,
              param = edit_def.key,
              region_id = region.id,
              step_key = (active and active.key) or step_key,
              col = hovered_col,
              end_col = hovered_col,
              ramp = false,
              unify = true,
              start_value = 0.0,
              source = "note",
              reset = true,
              filter_click_span = true,
              button = 1,
              undo_label = label,
              undo_open = true,
              dirty = false,
            }
          end
        else
          local edit = state.seq_vary_filter_edit
          local in_current = edit and tostring(edit.track_id) == tostring(hovered_slot.id)
            and type(edit.col_min) == "number" and type(edit.col_max) == "number"
            and hovered_col >= edit.col_min and hovered_col <= edit.col_max
          if edit and not in_current then
            seq_commit_vary_filter_edit()
          end
          state.seq_param_drag = {
            track_id = hovered_slot.id,
            param = edit_def.key,
            region_id = region.id,
            step_key = (active and active.key) or step_key,
            col = hovered_col,
            end_col = hovered_col,
            ramp = false,
            unify = true,
            start_value = 1.0,
            source = "note",
            reset = false,
            filter_click_span = started_on and true or nil,
            button = 0,
            undo_open = false,
            dirty = false,
          }
          if not started_on and not in_current then
            seq_begin_vary_filter_edit(region, hovered_slot.id, hovered_col, hovered_col, start_qn, step_qn, "", nil)
            if state.seq_vary_filter_edit then
              state.seq_vary_filter_edit.focus = false
            end
          end
        end
        if active then
          state.selected_seq_note = { region_id = region.id, track_id = hovered_slot.id, step_key = active.key }
        end
      elseif seq_is_stutter_def(edit_def) then
        if active and active.note then
          if right_clicked then
            local label = begin_seq_undo("Reset sequencer stutter")
            local changed = seq_reset_note_param_value(active.note, "stutter", nil, 1)
            if changed then
              sync_seq_pattern_track(region.pattern_id, hovered_slot, { force_rebuild = true })
              if seq_schedule_ingest_save then
                seq_schedule_ingest_save()
              else
                save_config()
              end
            end
            end_seq_undo(label)
            state.selected_seq_note = { region_id = region.id, track_id = hovered_slot.id, step_key = active.key }
          elseif left_clicked and not is_alt_down() then
            seq_begin_stutter_edit_drag(
              region, hovered_slot, active.key, active.note, mx, my, "Edit sequencer stutter"
            )
          end
        end
      elseif edit_def then
        if active then
          local reset = right_clicked
          local ramp = (not reset) and mod_active("velocity_ramp")
          local label = begin_seq_undo(reset
            and ("Reset sequencer " .. (edit_def.mode_name or edit_def.label))
            or ("Edit sequencer " .. (edit_def.mode_name or edit_def.label)))
          local start_value = seq_note_param_value(active.note, edit_def.key, seq_stutter_hit_index_at_qn(active.note, active.abs_qn, hovered_qn, step_qn))
          if start_value == nil then
            start_value = edit_def.default
          end
          state.seq_param_drag = {
            track_id = hovered_slot.id,
            param = edit_def.key,
            region_id = region.id,
            step_key = active.key or step_key,
            col = hovered_col,
            end_col = hovered_col,
            ramp = ramp,
            unify = (not reset) and mod_active("unify") and not ramp,
            start_value = start_value,
            source = "note",
            reset = reset,
            button = right_clicked and 1 or 0,
            undo_label = label,
            undo_open = true,
          }
          state.selected_seq_note = { region_id = region.id, track_id = hovered_slot.id, step_key = active.key }
        end
      else
        local hover_locked = left_clicked and seq_visible_cell_is_locked(
          hovered_slot, hovered_col, start_qn, step_qn, active_cells
        )
        if hover_locked then
          local label = begin_seq_undo("Unlock sequencer cells")
          local lo, hi = seq_lock_span_cols(
            hovered_slot, hovered_col, start_qn, step_qn, step_count, active_cells
          )
          local changed = seq_apply_lock_range(
            region, hovered_slot.id, lo, hi, start_qn, step_qn, false, active_cells
          )
          if changed then
            sync_seq_pattern_track(region.pattern_id, hovered_slot, { force_rebuild = true })
            if seq_schedule_ingest_save then
              seq_schedule_ingest_save()
            else
              save_config()
            end
          end
          end_seq_undo(label)
        else
          local click_key = step_key
          local click_qn = step_idx * step_qn
          local picked = seq_pick_packed_note(active, hovered_qn, start_qn, hovered_col, step_qn)
          if picked and picked.note then
            click_key = picked.key
            click_qn = seq_note_qn_offset(picked.note, picked.key, step_qn)
          end
          local mode = right_clicked and "erase" or "paint"
          local label = begin_seq_undo(left_clicked and "Paint sequencer notes" or "Erase sequencer notes")
          local painted = toggle_seq_note(region, hovered_slot, click_key, click_qn, right_clicked and "erase" or nil, {
            defer_save = true,
          })
          state.seq_note_drag = {
            track_id = hovered_slot.id,
            region_id = region.id,
            start_col = hovered_col,
            end_col = hovered_col,
            applied_min = hovered_col,
            applied_max = hovered_col,
            mode = mode,
            undo_label = label,
            undo_open = true,
            dirty = painted,
          }
        end
      end
    end
  end

  local note_drag_active = state.seq_note_drag and state.seq_note_drag.region_id == region.id
  if note_drag_active and not state.seq_region_drag then
    local drag = state.seq_note_drag
    if drag.mode == "stutter" then
      if left_down then
        if apply_seq_stutter_lane_drag(
          drag, region, step_qn, start_qn, step_count,
          mx, my, timeline_x0, timeline_w, view_start_qn, qn_span
        ) then
          drag.dirty = true
        end
      end
    elseif drag.mode == "stutter_edit" then
      if left_down then
        local drag_region = get_seq_region_by_id(drag.region_id) or region
        if apply_seq_stutter_edit_drag(drag, drag_region, mx, my) then
          drag.dirty = true
        end
      end
    elseif drag.mode == "decay" then
      if left_down then
        local drag_region = get_seq_region_by_id(drag.region_id) or region
        if apply_seq_decay_drag(
          drag, drag_region, step_qn,
          mx, my, timeline_x0, timeline_w, view_start_qn, qn_span
        ) then
          drag.dirty = true
        end
      end
    elseif drag.mode == "copy" or drag.mode == "move" then
      if left_down and mx >= timeline_x0 then
        if apply_seq_note_copy_drag(
          drag, step_qn, start_qn, step_count,
          mx, my, timeline_x0, timeline_w, view_start_qn, qn_span, row_positions
        ) then
          drag.dirty = true
        end
      end
    else
      local drag_down = (drag.mode == "paint" and left_down) or (drag.mode == "erase" and right_down)
      if drag_down and mx >= timeline_x0 then
        local prev_min = drag.applied_min or drag.start_col
        local prev_max = drag.applied_max or drag.start_col
        local end_col = seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
        local col_min = math.min(drag.start_col, end_col)
        local col_max = math.max(drag.start_col, end_col)
        if col_min < prev_min or col_max > prev_max then
          if apply_seq_note_lane_drag(drag, region, step_qn, start_qn, step_count, mx, timeline_x0, timeline_w, view_start_qn, qn_span) then
            drag.dirty = true
          end
        else
          drag.end_col = end_col
        end
      end
    end
  end

  param_drag_active = seq_param_drag_button_down(state.seq_param_drag, left_down, right_down)
      and state.seq_param_drag.region_id == region.id
  if param_drag_active then
    local drag = state.seq_param_drag
    local def = get_param_lane_def(drag.param)
    local lane_y0, lane_y1, lane_row
    if drag.source == "note" then
      lane_y0, lane_y1, lane_row = find_seq_note_lane_bounds(row_positions, drag.track_id)
    else
      lane_y0, lane_y1, lane_row = find_seq_param_lane_bounds(row_positions, drag.track_id, drag.param)
    end
    if def and lane_y0 and lane_row and not seq_is_decay_def(def) then
      if not drag.reset then
        if mod_active("velocity_ramp") and not drag.ramp then
          drag.ramp = true
          drag.unify = false
          local anchor = active_cells[drag.track_id] and active_cells[drag.track_id][drag.col]
          if anchor then
            drag.start_value = seq_note_param_value(anchor.note, def.key, seq_stutter_hit_index_at_qn(anchor.note, anchor.abs_qn, start_qn + drag.col * step_qn + step_qn * 0.5, step_qn))
            if drag.start_value == nil then
              drag.start_value = def.default
            end
          end
        elseif mod_active("unify") and not drag.ramp and not drag.unify then
          drag.unify = true
        end
      end

      local changed, current_value, highlight_col_min, highlight_col_max, mouse_col
      if drag.reset then
        changed, current_value, highlight_col_min, highlight_col_max, mouse_col = apply_seq_param_reset_drag(
          drag, def, mx, step_qn, step_count, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, active_cells
        )
      else
        changed, current_value, highlight_col_min, highlight_col_max, mouse_col = apply_seq_param_lane_drag(
          drag, def, lane_y0, lane_y1, mx, my, step_qn, step_count, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, active_cells
        )
      end
      if changed then
        drag.dirty = true
      end

      if not seq_is_span_overlay_def(def) then
      local hx0 = math.max(timeline_x0, col_x0(highlight_col_min))
      local hx1 = math.min(timeline_x1, col_x1(highlight_col_max))
      if hx1 > hx0 then
        r.ImGui_DrawList_AddRectFilled(dl, hx0, lane_row.y0, hx1, lane_row.y1, 0xFFB84D44, 0)
        r.ImGui_DrawList_AddRect(dl, hx0, lane_row.y0, hx1, lane_row.y1, 0xFFB84DFF, 0, 0, 2.0)
      end

      if drag.ramp then
        local lane_top = lane_row.y0 + 2
        local lane_bot = lane_row.y1 - 2
        local start_val = drag.start_value or def.default
        local x0 = (col_x0(drag.col) + col_x1(drag.col)) * 0.5
        local x1 = (col_x0(drag.end_col) + col_x1(drag.end_col)) * 0.5
        local y0 = seq_param_y_from_value(def, start_val, lane_top, lane_bot, step_qn)
        local y1 = seq_param_y_from_value(def, current_value, lane_top, lane_bot, step_qn)
        r.ImGui_DrawList_AddLine(dl, x0, y0, x1, y1, 0xFFFFFFFF, 2.0)
        r.ImGui_DrawList_AddCircleFilled(dl, x0, y0, 3.0, 0xFFFFFFFF, 12)
        r.ImGui_DrawList_AddCircleFilled(dl, x1, y1, 3.0, 0xFFFFFFFF, 12)
      end

      local value_text
      if drag.reset then
        value_text = string.format("%s reset %s", def.label, string.format(def.fmt, def.default))
      elseif drag.ramp and drag.end_col ~= drag.col then
        value_text = string.format("%s ramp %s -> %s",
          def.label,
          string.format(def.fmt, drag.start_value or def.default),
          string.format(def.fmt, current_value))
      elseif drag.unify then
        value_text = string.format("%s unify %s", def.label, string.format(def.fmt, current_value))
      else
        local hover_active = active_cells[drag.track_id] and active_cells[drag.track_id][mouse_col]
        if hover_active then
          local hit_idx = seq_stutter_hit_index_at_qn(
            hover_active.note, hover_active.abs_qn,
            seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span),
            step_qn
          )
          local hover_val = seq_note_param_value(hover_active.note, def.key, hit_idx)
          value_text = format_seq_param_value(def, hover_val ~= nil and hover_val or current_value)
          if hit_idx then
            value_text = string.format("%s  ·  %d/%d", value_text, hit_idx, seq_stutter_count(hover_active.note))
          end
        else
          value_text = format_seq_param_value(def, current_value)
        end
      end
      local text_x = col_x0(mouse_col) + 4
      local text_y = lane_row.y0 - 16
      local text_size = { r.ImGui_CalcTextSize(ctx, value_text) }
      local text_w = text_size[1] or 0
      local text_h = text_size[2] or 0
      r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0x000000CC, 3.0)
      r.ImGui_DrawList_AddRect(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0xFFB84DFF, 3.0, 0, 1.0)
      r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, value_text)
      end
    end
  end

  if note_drag_active and state.seq_note_drag and state.seq_note_drag.mode == "stutter_edit" then
    local drag = state.seq_note_drag
    local value_text
    if drag.axis == "skew" then
      value_text = string.format("Skew %+.2f", drag.skew or 0.0)
    elseif drag.axis == "count" then
      value_text = string.format("Stutter ×%d", drag.stutter or 1)
    else
      value_text = "Stutter  ·  drag vertically or horizontally"
    end
    local text_size = { r.ImGui_CalcTextSize(ctx, value_text) }
    local text_w = text_size[1] or 0
    local text_h = text_size[2] or 0
    local text_x = mx + 12
    local text_y = my - 22
    r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0x000000CC, 3.0)
    r.ImGui_DrawList_AddRect(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0xC9A8FFFF, 3.0, 0, 1.0)
    r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, value_text)
  end

  if note_drag_active and state.seq_note_drag and state.seq_note_drag.mode == "stutter" then
    local drag = state.seq_note_drag
    local count = drag.stutter or SEQ_STUTTER_MIN
    local length_qn = drag.length_qn or step_qn
    local value_text = string.format("Stutter ×%d over %.3g beats", count, length_qn)
    local text_size = { r.ImGui_CalcTextSize(ctx, value_text) }
    local text_w = text_size[1] or 0
    local text_h = text_size[2] or 0
    local text_x = mx + 12
    local text_y = my - 22
    r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0x000000CC, 3.0)
    r.ImGui_DrawList_AddRect(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0xC9A8FFFF, 3.0, 0, 1.0)
    r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, value_text)
  end

  local decay_readout = nil
  if note_drag_active and state.seq_note_drag and state.seq_note_drag.mode == "decay" then
    local drag = state.seq_note_drag
    if drag.handle == "end" then
      decay_readout = string.format("Length %.3g beats%s", drag.length_qn or 0, is_shift_down() and "  ·  free" or "")
    elseif drag.handle == "curve_in" or drag.handle == "curve_out" then
      local side = (drag.handle == "curve_in") and "in" or "out"
      decay_readout = string.format("Fade %s curve %+.2f  ·  %s", side, drag.fade_curve or 0, seq_fade_shape_name(drag.fade_shape))
    elseif drag.handle == "fade_in" then
      decay_readout = string.format("Fade in %.3g beats  ·  %s", drag.fade_qn or 0, seq_fade_shape_name(drag.fade_shape))
    else
      decay_readout = string.format("Fade out %.3g beats  ·  %s", drag.fade_qn or 0, seq_fade_shape_name(drag.fade_shape))
    end
  elseif seq_is_decay_def(edit_def) and not note_drag_active then
    local hit = seq_decay_hit_at(mx, my)
    if hit and hit.note then
      if hit.kind == "end" then
        decay_readout = string.format("Length %.3g beats", hit.note_len or 0)
      elseif hit.kind == "curve_in" then
        decay_readout = string.format("Fade in curve %+.2f  ·  %s", seq_note_fade_curve(hit.note, "in"), seq_fade_shape_name(seq_note_fade_shape(hit.note, "in")))
      elseif hit.kind == "curve_out" then
        decay_readout = string.format("Fade out curve %+.2f  ·  %s", seq_note_fade_curve(hit.note, "out"), seq_fade_shape_name(seq_note_fade_shape(hit.note, "out")))
      elseif hit.kind == "fade_in" then
        decay_readout = string.format("Fade in %.3g beats  ·  %s", seq_note_fade_qn(hit.note, "in"), seq_fade_shape_name(seq_note_fade_shape(hit.note, "in")))
      else
        decay_readout = string.format("Fade out %.3g beats  ·  %s", seq_note_fade_qn(hit.note, "out"), seq_fade_shape_name(seq_note_fade_shape(hit.note, "out")))
      end
    end
  end
  if decay_readout then
    local text_size = { r.ImGui_CalcTextSize(ctx, decay_readout) }
    local text_w = text_size[1] or 0
    local text_h = text_size[2] or 0
    local text_x = mx + 12
    local text_y = my - 22
    r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0x000000CC, 3.0)
    r.ImGui_DrawList_AddRect(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0xFFD166FF, 3.0, 0, 1.0)
    r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, decay_readout)
  end

  draw_seq_razors(dl, row_positions, timeline_x0, timeline_x1, view_start_qn, qn_span, step_qn, razor_hover_track_id, razor_hover_qn)

  local mouse_released = r.ImGui_IsMouseReleased(ctx, 0) or r.ImGui_IsMouseReleased(ctx, 1)
  if r.ImGui_IsMouseReleased(ctx, 1) and state.seq_razor_drag and state.seq_razor_drag.mode ~= "move" then
    seq_commit_razor_drag(step_qn)
  end
  if r.ImGui_IsMouseReleased(ctx, 0) and state.seq_razor_drag and state.seq_razor_drag.mode == "move" then
    seq_commit_razor_drag(step_qn)
  end
  if r.ImGui_IsMouseReleased(ctx, 0) and state.seq_region_drag then
    local drag = state.seq_region_drag
    if drag.mode == "move" then
      local reg = get_seq_region_by_id(drag.region_id)
      local swap = drag.swap_region_id and get_seq_region_by_id(drag.swap_region_id)
      if reg and swap then
        local label = begin_seq_undo("Swap sequencer regions")
        if seq_swap_region_positions(reg, swap) then
          seq_select_region(reg)
          region = reg
        end
        end_seq_undo(label)
      elseif reg and drag.preview_start_qn then
        local moved = math.abs((drag.preview_start_qn or 0.0) - (drag.orig_start_qn or 0.0)) >= step_qn * 0.25
        if moved then
          local label = begin_seq_undo(drag.undo_label or "Move sequencer region")
          if seq_move_region_to(reg, drag.preview_start_qn) then
            seq_select_region(reg)
            region = reg
          end
          end_seq_undo(label)
        end
      end
    elseif drag.mode == "pool_copy" then
      local src = get_seq_region_by_id(drag.source_region_id)
      if src and drag.current_start_qn then
        local moved_qn = math.abs(drag.current_start_qn - (src.start_qn or 0.0)) >= step_qn * 0.25
        local moved_px = drag.start_mx and (math.abs(mx - drag.start_mx) > 4 or math.abs(my - drag.start_my) > 4)
        if moved_qn or moved_px then
          local label = begin_seq_undo(drag.undo_label or "Pool copy sequencer region")
          create_seq_region(drag.length_bars or src.length_bars, src, true, drag.insert_qn or drag.current_start_qn, true)
          region = get_selected_seq_region()
          end_seq_undo(label)
        end
      end
    elseif drag.mode == "create" and drag.start_qn and drag.current_qn then
      local create_start = seq_snap_qn_for_region_drag(math.min(drag.start_qn, drag.current_qn), step_qn)
      local create_end = seq_snap_qn_for_region_drag(math.max(drag.start_qn, drag.current_qn), step_qn)
      local moved_px = drag.start_mx and (math.abs(mx - drag.start_mx) > 4 or math.abs(my - drag.start_my) > 4)
      local label = begin_seq_undo(drag.undo_label or "Create sequencer region")
      if not moved_px then
        create_seq_region(4, nil, false, drag.start_qn, drag.insert)
      elseif create_end - create_start < step_qn * 2 then
        create_seq_region(4, nil, false, create_start, drag.insert)
      else
        local bars = seq_qn_length_to_bars(create_start, create_end - create_start)
        create_seq_region(bars, nil, false, create_start, drag.insert)
      end
      region = get_selected_seq_region()
      end_seq_undo(label)
    elseif drag.undo_label and (drag.undo_started or seq_undo_is_open()) then
      end_seq_undo(drag.undo_label)
    end
    state.seq_region_drag = nil
  end
  if mouse_released then
    local note_drag = state.seq_note_drag
    if note_drag then
      if note_drag.dirty then
        if note_drag.mode == "stutter" or note_drag.mode == "stutter_edit"
            or note_drag.mode == "decay" or note_drag.mode == "copy" or note_drag.mode == "move" then
          local seen = {}
          local function sync_one(region_id, track_id)
            local key = tostring(region_id or "") .. ":" .. tostring(track_id or "")
            if seen[key] then
              return
            end
            seen[key] = true
            local sync_region = get_seq_region_by_id(region_id) or region
            local sync_slot = seq_find_slot_by_id(track_id)
            if sync_region and sync_slot then
              sync_seq_pattern_track(sync_region.pattern_id, sync_slot, { force_rebuild = true })
            elseif sync_region then
              sync_seq_pattern_regions(sync_region.pattern_id)
            end
          end
          if note_drag.mode == "copy" or note_drag.mode == "move" then
            state.seq_force_item_crop = true
          end
          sync_one(note_drag.region_id, note_drag.track_id)
          if note_drag.mode == "copy" or note_drag.mode == "move" then
            sync_one(note_drag.dest_region_id, note_drag.dest_track_id)
            state.seq_force_item_crop = nil
          end
        end
        if seq_schedule_ingest_save then
          seq_schedule_ingest_save()
        else
          save_config()
        end
      end
      if note_drag.undo_open then
        local default_label = "Paint sequencer notes"
        if note_drag.mode == "erase" then
          default_label = "Erase sequencer notes"
        elseif note_drag.mode == "stutter" then
          default_label = "Create sequencer stutter"
        elseif note_drag.mode == "stutter_edit" then
          default_label = "Edit sequencer stutter"
        elseif note_drag.mode == "decay" then
          default_label = "Edit sequencer decay"
        elseif note_drag.mode == "copy" then
          default_label = "Copy sequencer note"
        elseif note_drag.mode == "move" then
          default_label = note_drag.place_new and "Insert sequencer note" or "Move sequencer note"
        end
        end_seq_undo(note_drag.undo_label or default_label)
      end
    end
    local param_drag = state.seq_param_drag
    if param_drag then
      if param_drag.lock_click_span and param_drag.reset then
        local param_region = get_seq_region_by_id(param_drag.region_id) or region
        local param_slot = seq_find_slot_by_id(param_drag.track_id)
        if param_region and param_slot then
          local lo, hi = seq_lock_span_cols(
            param_slot, param_drag.col, start_qn, step_qn, step_count, active_cells
          )
          if seq_apply_lock_range(param_region, param_drag.track_id, lo, hi, start_qn, step_qn, false, active_cells) then
            param_drag.dirty = true
          end
        end
      end
      if param_drag.param == "vary_filter" then
        local param_region = get_seq_region_by_id(param_drag.region_id) or region
        local param_slot = seq_find_slot_by_id(param_drag.track_id)
        if param_drag.reset then
          if param_drag.filter_click_span and param_region and param_slot then
            local lo, hi = seq_vary_filter_span_cols(
              param_slot, param_drag.col, start_qn, step_qn, step_count
            )
            if seq_apply_vary_filter_range(param_region, param_drag.track_id, lo, hi, start_qn, step_qn, "") then
              param_drag.dirty = true
            end
          end
        elseif param_slot and param_region then
          local col_min = math.min(param_drag.col or 0, param_drag.end_col or param_drag.col or 0)
          local col_max = math.max(param_drag.col or 0, param_drag.end_col or param_drag.col or 0)
          if param_drag.filter_click_span then
            local lo, hi = seq_vary_filter_span_cols(
              param_slot, param_drag.col, start_qn, step_qn, step_count
            )
            local text = seq_visible_cell_vary_filter(param_slot, param_drag.col, start_qn, step_qn) or ""
            seq_begin_vary_filter_edit(param_region, param_drag.track_id, lo, hi, start_qn, step_qn, text, text)
          elseif state.seq_vary_filter_edit then
            local edit = state.seq_vary_filter_edit
            edit.col_min = col_min
            edit.col_max = col_max
            edit.start_qn = start_qn
            edit.step_qn = step_qn
            edit.focus = true
          else
            seq_begin_vary_filter_edit(param_region, param_drag.track_id, col_min, col_max, start_qn, step_qn, "", nil)
          end
        end
      end
      if param_drag.dirty then
        local param_region = get_seq_region_by_id(param_drag.region_id) or region
        local param_slot = seq_find_slot_by_id(param_drag.track_id)
        if param_region and param_slot then
          sync_seq_pattern_track(param_region.pattern_id, param_slot, { force_rebuild = true })
        elseif param_region then
          sync_seq_pattern_regions(param_region.pattern_id)
        end
        if seq_schedule_ingest_save then
          seq_schedule_ingest_save()
        else
          save_config()
        end
      end
      if param_drag.undo_open then
        end_seq_undo(param_drag.undo_label or "Edit sequencer parameter")
      end
    end
    state.seq_note_drag = nil
    state.seq_param_drag = nil
  end

  for _, row_pos in ipairs(row_positions) do
    local row = row_pos.row
    if row.type == "note" and row.slot then
      local track_idx = slot_id_to_idx[row.slot.id]
      if track_idx and row_pos.ctrl then
        local mix_changed, overlap_changed, mix_hovered = render_seq_track_mix_controls(
          dl, row.slot, row_pos.ctrl
        )
        if mix_hovered then
          over_lane_mix_controls = true
        end
        if mix_changed then
          begin_seq_undo("Adjust sequencer mix")
          seq_undo_commit_on_release = true
          seq_on_slot_mix_changed(row.slot, { resync = overlap_changed })
        end
      end
    end
  end

  render_seq_track_context_menu()
  if render_seq_midi_assign_popup() then
    save_config()
    if save_seq_project_state then save_seq_project_state() end
  end

  seq_random_flyout_begin_frame("lane")
  if not random_edit_region and state.seq_random_flyout and state.seq_random_flyout.host == "lane" then
    state.seq_random_flyout = nil
  end
  for _, row_pos in ipairs(row_positions) do
    local row = row_pos.row
    if row.type == "note" and row.slot then
      local track_idx = slot_id_to_idx[row.slot.id]
      if track_idx then
        if random_edit_region and random_edit_pattern then
          local random_settings = get_seq_track_settings(random_edit_pattern, row.slot.id, true)
          if random_settings then
            local changed, active_key, overlay_text, panel_x1, reseeded = seq_render_lane_random_controls(dl, row_pos, row.slot.id, random_settings, random_focus_effective, timeline_x0, header_y1, body_viewport_y1)
            if active_key then
              random_focus_next = active_key
              random_focus_effective = active_key
              random_overlay_text = overlay_text
              random_overlay_y = row_pos.y0
              random_overlay_x = panel_x1
            end
            if reseeded or changed then
              seq_queue_random_sync(random_edit_region.pattern_id, row.slot.id)
            end
            if changed then
              begin_seq_undo("Edit sequencer random")
              seq_undo_commit_on_release = true
            end
          end
        end
        local lane_h = row_pos.y1 - row_pos.y0
        r.ImGui_SetCursorScreenPos(ctx, timeline_x0 - map_nav_w - 4, row_pos.y0)
        r.ImGui_PushID(ctx, "seq_lane_nav_" .. row.slot.id)
        local nav = render_seq_track_sample_controls(row.slot, track_idx, {
          id_suffix = "seq_map_" .. row.slot.id,
          ctrl_size = map_ctrl_size,
          icon_size = map_icon_size,
          container_h = lane_h,
          y0 = row_pos.y0,
          y1 = row_pos.y1,
        })
        r.ImGui_PopID(ctx)
        if state.pending_waveform_drop or sample_drag_active() then
          if not seq_candidate_drag_from_slot(row.slot) then
          local row_drop_hovered = nav.row_drop_hovered
          if not row_drop_hovered and hovered and mx >= x0 and mx < timeline_x0
              and my >= row_pos.y0 and my <= row_pos.y1 then
            row_drop_hovered = true
          end
          if row_drop_hovered and not state.seq_candidate_drop and not state.seq_drum_drop
              and not seq_drag_is_from_candidate() then
            state.seq_drop_target_idx = track_idx
            state.seq_timeline_drop_time = nil
            state.seq_timeline_drop_track_idx = nil
            draw_drop_target_highlight(dl, x0 + 1, row_pos.y0, timeline_x0 - 1, row_pos.y1, 3)
          end
          end
        end
      end
    end
  end

  if mix_env_resync then
    -- Rebuild take envelopes after the drag frame so we don't resync every pixel.
    if not (state.seq_env_graph_drag and state.seq_env_graph_drag.slot_id) then
      local slot = env_resync_slot
      if not slot and state.seq_env_pending_resync_slot_id then
        slot = seq_find_slot_by_id(state.seq_env_pending_resync_slot_id)
      end
      if slot then
        sync_seq_slot_all_regions(slot, { force_rebuild = true })
      else
        seq_resync_all_regions()
      end
      state.seq_env_pending_resync = nil
      state.seq_env_pending_resync_slot_id = nil
    else
      state.seq_env_pending_resync = true
    end
  elseif state.seq_env_pending_resync
      and not (state.seq_env_graph_drag and state.seq_env_graph_drag.slot_id) then
    local slot = nil
    if state.seq_env_pending_resync_slot_id then
      slot = seq_find_slot_by_id(state.seq_env_pending_resync_slot_id)
    end
    if slot then
      sync_seq_slot_all_regions(slot, { force_rebuild = true })
    else
      seq_resync_all_regions()
    end
    state.seq_env_pending_resync = nil
    state.seq_env_pending_resync_slot_id = nil
  end

  state.seq_random_active_key = random_focus_next
  if not random_edit_region then
    state.seq_random_active_key = nil
  end
  if random_overlay_text and random_overlay_y then
    local text_w, text_h = r.ImGui_CalcTextSize(ctx, random_overlay_text)
    local text_x = (random_overlay_x or (timeline_x0 + 8)) + 8
    local text_y = random_overlay_y + 2
    r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 4, text_y + text_h + 2, 0x000000CC, 3.0)
    r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFE7A6DD, random_overlay_text)
  end

  if mouse_released or (state.seq_random_sync_pending and not state.seq_random_knob_drag) then
    state.seq_random_sync_run = true
  end
  if mouse_released and seq_undo_commit_on_release then
    if seq_undo_is_open() then
      end_seq_undo()
    end
    seq_undo_commit_on_release = false
  end

  r.ImGui_SetCursorScreenPos(ctx, x0, add_row_y0)
  if draw_ui_button("seq_add_track_popup_open_sequencer", nil, label_col_w, add_track_row_h, { icon = "plus", style = "primary" }) then
    open_seq_add_track_popup()
  end

  r.ImGui_Dummy(ctx, width, 0)

  render_seq_add_track_popup()
  r.ImGui_EndChild(ctx)

  -- Envelope editor + extras flyouts must live in the parent map window.
  -- Opening them inside the tracks child made ImGui treat the screen-space
  -- anchor as child-relative, so the editor jumped to a random place.
  seq_render_env_editor_host()
  if seq_undo_commit_on_release and r.ImGui_IsMouseReleased and
      (r.ImGui_IsMouseReleased(ctx, 0) or r.ImGui_IsMouseReleased(ctx, 1)) then
    if seq_undo_is_open() then
      end_seq_undo()
    end
    seq_undo_commit_on_release = false
  end

  -- Flyout items must live in the parent map window. The tracks child clips
  -- mouse hits, so extras that overlap the pinned ruler would otherwise be inert.
  if random_edit_region and random_edit_pattern then
    local fly_slot = state.seq_random_flyout and state.seq_random_flyout.slot_id
    if seq_render_random_flyout(dl, random_edit_pattern, "lane") then
      begin_seq_undo("Edit sequencer random extras")
      seq_undo_commit_on_release = true
      seq_queue_random_sync(random_edit_region.pattern_id, fly_slot)
    end
    if r.ImGui_IsMouseReleased(ctx, 0) or r.ImGui_IsMouseReleased(ctx, 1) then
      if state.seq_random_sync_pending and not state.seq_random_knob_drag then
        state.seq_random_sync_run = true
      end
      if seq_undo_commit_on_release then
        if seq_undo_is_open() then
          end_seq_undo()
        end
        seq_undo_commit_on_release = false
      end
    end
  end

  render_seq_pattern_popup(region)
  r.ImGui_EndChild(ctx)
end


function apply_custom_tags_to_samples()
  if not state.custom_tags then
    return
  end
  local changed = false
  for path, tags in pairs(state.custom_tags) do
    if type(tags) == "table" and #tags > 0 then
      local sample = find_sample_by_path(path)
      if not sample then
        sample = find_sample_by_path(normalize_path(path))
      end
      if sample then
        local before = #(sample.tags or {})
        sample.tags = append_unique_tags(sample.tags or {}, tags)
        if #(sample.tags) > before then
          changed = true
        end
      end
    end
  end
  if changed then
    rebuild_tag_index()
  end
end

function explorer_normalize_tag(tag)
  tag = tostring(tag or ""):gsub("^%s+", ""):gsub("%s+$", "")
  tag = tag:gsub("%s+", " ")
  return tag
end

function explorer_is_audio_name(name)
  local ext = tostring(name or ""):match("%.([^%.]+)$")
  if not ext then
    return false
  end
  return AUDIO_EXTS["." .. ext:lower()] == true
end

EXPLORER_ROW_H = 22
EXPLORER_MAX_DEPTH = 20
EXPLORER_MAX_LIST = 4000
EXPLORER_MAX_ROWS = 12000
EXPLORER_SEED_SLICE_MS = 0.006
EXPLORER_MAX_ENUM = 400

function explorer_invalidate_rows()
  state.explorer_row_list = nil
end

function explorer_is_safe_child(parent, child)
  parent = normalize_path(parent or "")
  child = normalize_path(child or "")
  if parent == "" or child == "" or child == parent then
    return false
  end
  return child:sub(1, #parent + 1) == (parent .. "/")
end

function explorer_collect_scan_roots()
  local roots = {}
  for _, folder in ipairs(state.folders or {}) do
    local path = normalize_path(folder)
    if path ~= "" then
      roots[#roots + 1] = path
    end
  end
  return roots
end

function explorer_path_in_library(path, roots)
  roots = roots or state.explorer_seed_roots
  if not path or path == "" or not roots then
    return false
  end
  for i = 1, #roots do
    local root = roots[i]
    if path == root then
      return true
    end
    local n = #root
    if #path > n and path:sub(1, n) == root and path:sub(n + 1, n + 1) == "/" then
      return true
    end
  end
  return false
end

function explorer_ensure_sorted(entry)
  if not entry or entry.sorted then
    return
  end
  table.sort(entry.dirs, function(a, b) return string.lower(a) < string.lower(b) end)
  table.sort(entry.files, function(a, b) return string.lower(a) < string.lower(b) end)
  entry.sorted = true
end

function explorer_ensure_cache_entry(path)
  path = normalize_path(path or "")
  local entry = state.explorer_dir_cache[path]
  if not entry then
    entry = {
      dirs = {},
      files = {},
      dir_set = {},
      file_set = {},
      sorted = true,
      source = "index",
    }
    state.explorer_dir_cache[path] = entry
    return entry
  end
  if not entry.dir_set then
    entry.dir_set = {}
    for _, name in ipairs(entry.dirs) do
      entry.dir_set[name] = true
    end
  end
  if not entry.file_set then
    entry.file_set = {}
    for _, name in ipairs(entry.files) do
      entry.file_set[name] = true
    end
  end
  return entry
end

function explorer_cache_add_dir(parent, name)
  if not name or name == "" then
    return
  end
  local entry = explorer_ensure_cache_entry(parent)
  if entry.dir_set[name] then
    return
  end
  if #entry.dirs >= EXPLORER_MAX_LIST then
    return
  end
  entry.dir_set[name] = true
  entry.dirs[#entry.dirs + 1] = name
  entry.sorted = false
end

function explorer_cache_add_file(parent, name)
  if not name or name == "" then
    return
  end
  local entry = explorer_ensure_cache_entry(parent)
  if entry.file_set[name] then
    return
  end
  if #entry.files >= EXPLORER_MAX_LIST then
    return
  end
  entry.file_set[name] = true
  entry.files[#entry.files + 1] = name
  entry.sorted = false
end

function explorer_index_sample(sample)
  if not state.explorer_cache_seeded and not state.explorer_seed_index then
    return
  end
  local path = normalize_path((sample and sample.path) or "")
  local name = path:match("([^/]+)$")
  local dir = path:match("(.+)/[^/]+$")
  if not dir or not name or not explorer_is_audio_name(name) then
    return
  end
  local roots = state.explorer_seed_roots
  if not roots then
    roots = explorer_collect_scan_roots()
    state.explorer_seed_roots = roots
  end
  if not explorer_path_in_library(dir, roots) then
    return
  end
  explorer_cache_add_file(dir, name)
  local child = dir
  local guard = 0
  while child and guard < EXPLORER_MAX_DEPTH do
    guard = guard + 1
    local parent = child:match("(.+)/[^/]+$")
    local child_name = child:match("([^/]+)$")
    if not parent or not child_name then
      break
    end
    if not explorer_path_in_library(parent, roots) then
      explorer_ensure_cache_entry(child)
      break
    end
    explorer_cache_add_dir(parent, child_name)
    child = parent
  end
  if state.explorer_cache_seeded then
    state.explorer_index_dirty = true
  end
end

function explorer_reset_seed_state()
  state.explorer_cache_seeded = false
  state.explorer_seed_index = nil
  state.explorer_seed_roots = nil
  state.explorer_disk_queue = {}
  state.explorer_disk_queued = {}
end

function explorer_invalidate_cache(path)
  state.explorer_has_audio = {}
  state.explorer_has_audio_queue = {}
  state.explorer_has_audio_queued = {}
  state.explorer_has_audio_seeded = false
  explorer_reset_seed_state()
  explorer_invalidate_rows()
  if path and path ~= "" then
    state.explorer_dir_cache[normalize_path(path)] = nil
    return
  end
  state.explorer_dir_cache = {}
end

function explorer_pump_seed_from_samples()
  if state.explorer_cache_seeded then
    return
  end
  local samples = state.samples or {}
  if not state.explorer_seed_index then
    state.explorer_seed_index = 1
    state.explorer_seed_roots = explorer_collect_scan_roots()
    for i = 1, #state.explorer_seed_roots do
      explorer_ensure_cache_entry(state.explorer_seed_roots[i])
    end
  end
  local idx = state.explorer_seed_index
  local started = r.time_precise and r.time_precise() or 0
  while idx <= #samples do
    explorer_index_sample(samples[idx])
    idx = idx + 1
    if r.time_precise and (r.time_precise() - started) > EXPLORER_SEED_SLICE_MS then
      break
    end
  end
  if idx ~= state.explorer_seed_index then
    state.explorer_seed_index = idx
    explorer_invalidate_rows()
  else
    state.explorer_seed_index = idx
  end
  if idx > #samples then
    state.explorer_cache_seeded = true
    if state.explorer_want_disk_refresh then
      state.explorer_want_disk_refresh = false
      explorer_queue_expanded_disk_refresh()
    end
  end
end

function explorer_queue_disk_refresh(path)
  path = normalize_path(path or "")
  if path == "" then
    return
  end
  state.explorer_disk_queue = state.explorer_disk_queue or {}
  state.explorer_disk_queued = state.explorer_disk_queued or {}
  if state.explorer_disk_queued[path] then
    return
  end
  state.explorer_disk_queued[path] = true
  state.explorer_disk_queue[#state.explorer_disk_queue + 1] = path
end

function explorer_queue_expanded_disk_refresh()
  for path, open in pairs(state.explorer_open_dirs or {}) do
    if open then
      explorer_queue_disk_refresh(path)
    end
  end
end

function explorer_pump_disk_refresh()
  local queue = state.explorer_disk_queue
  if not queue or #queue == 0 then
    return
  end
  local path = table.remove(queue, 1)
  state.explorer_disk_queued[path] = nil
  explorer_list_dir_from_disk(path)
  explorer_invalidate_rows()
end

function explorer_shell_quote(path)
  return "'" .. tostring(path or ""):gsub("'", "'\\''") .. "'"
end

function explorer_list_dir_via_shell(path, dirs, files)
  local function read_popen(cmd, on_line)
    local ok, handle = pcall(io.popen, cmd)
    if not ok or not handle then
      return false
    end
    for line in handle:lines() do
      on_line(line)
    end
    handle:close()
    return true
  end

  local osname = (r.GetOS and r.GetOS()) or ""
  if osname:match("Win") then
    local win = path:gsub("/", "\\"):gsub('"', "")
    local quoted = '"' .. win .. '"'
    local ok_dirs = read_popen("cmd /c dir /b /ad " .. quoted .. " 2>nul", function(line)
      if line ~= "" and not line:match("^%.") and #dirs < EXPLORER_MAX_LIST then
        dirs[#dirs + 1] = line
      end
    end)
    local ok_files = read_popen("cmd /c dir /b /a-d " .. quoted .. " 2>nul", function(line)
      if line ~= "" and explorer_is_audio_name(line) and #files < EXPLORER_MAX_LIST then
        files[#files + 1] = line
      end
    end)
    return ok_dirs or ok_files
  end

  return read_popen("/bin/ls -1p " .. explorer_shell_quote(path) .. " 2>/dev/null", function(name)
    if name == "" then
      return
    end
    local is_dir = name:sub(-1) == "/"
    if is_dir then
      name = name:sub(1, -2)
    end
    if name == "" or name:match("^%.") then
      return
    end
    if is_dir then
      if #dirs < EXPLORER_MAX_LIST then
        dirs[#dirs + 1] = name
      end
    elseif explorer_is_audio_name(name) and #files < EXPLORER_MAX_LIST then
      files[#files + 1] = name
    end
  end)
end

function explorer_list_dir_via_enumerate(path, dirs, files)
  local i = 0
  local subdir = r.EnumerateSubdirectories(path, i)
  while subdir do
    if subdir ~= "." and subdir ~= ".." and not subdir:match("^%.") then
      local child = explorer_join_path(path, subdir)
      if explorer_is_safe_child(path, child) then
        dirs[#dirs + 1] = subdir
      end
    end
    i = i + 1
    if i >= EXPLORER_MAX_ENUM or #dirs >= EXPLORER_MAX_LIST then
      break
    end
    subdir = r.EnumerateSubdirectories(path, i)
  end

  i = 0
  local file = r.EnumerateFiles(path, i)
  local seen = 0
  while file do
    seen = seen + 1
    if explorer_is_audio_name(file) then
      files[#files + 1] = file
    end
    i = i + 1
    if seen >= EXPLORER_MAX_ENUM or #files >= EXPLORER_MAX_LIST then
      break
    end
    file = r.EnumerateFiles(path, i)
  end
  return true
end

function explorer_list_dir_from_disk(path)
  path = normalize_path(path or "")
  if path == "" then
    return nil, nil
  end
  local vol = volume_root_from_path(path)
  if vol and state.missing_volumes[vol] then
    return nil, nil
  end

  local dirs, files = {}, {}
  local ok = explorer_list_dir_via_shell(path, dirs, files)
  if not ok then
    dirs, files = {}, {}
    ok = explorer_list_dir_via_enumerate(path, dirs, files)
  end
  if not ok then
    return nil, nil
  end

  table.sort(dirs, function(a, b) return string.lower(a) < string.lower(b) end)
  table.sort(files, function(a, b) return string.lower(a) < string.lower(b) end)
  local dir_set, file_set = {}, {}
  for _, name in ipairs(dirs) do
    dir_set[name] = true
  end
  for _, name in ipairs(files) do
    file_set[name] = true
  end
  state.explorer_dir_cache[path] = {
    dirs = dirs,
    files = files,
    dir_set = dir_set,
    file_set = file_set,
    sorted = true,
    source = "disk",
  }
  return dirs, files
end

function explorer_seed_has_audio_from_samples()
  if state.explorer_has_audio_seeded then
    return
  end
  state.explorer_has_audio_seeded = true
  state.explorer_has_audio = state.explorer_has_audio or {}
  for _, sample in ipairs(state.samples or {}) do
    local dir = normalize_path(sample.path or ""):match("(.+)/[^/]+$")
    local guard = 0
    while dir and dir ~= "" and guard < EXPLORER_MAX_DEPTH do
      guard = guard + 1
      if state.explorer_has_audio[dir] == true then
        break
      end
      state.explorer_has_audio[dir] = true
      local parent = dir:match("(.+)/[^/]+$")
      if not parent or parent == dir then
        break
      end
      dir = parent
    end
  end
end

function explorer_mark_has_audio(path)
  local dir = normalize_path(path or "")
  local guard = 0
  local changed = false
  while dir and dir ~= "" and guard < EXPLORER_MAX_DEPTH do
    guard = guard + 1
    if state.explorer_has_audio[dir] ~= true then
      state.explorer_has_audio[dir] = true
      changed = true
    end
    local parent = dir:match("(.+)/[^/]+$")
    if not parent or parent == dir then
      break
    end
    dir = parent
  end
  if changed then
    explorer_invalidate_rows()
  end
end

function explorer_queue_has_audio(path)
  path = normalize_path(path or "")
  if path == "" then
    return
  end
  local slashes = 0
  path:gsub("/", function()
    slashes = slashes + 1
  end)
  if slashes > 40 then
    state.explorer_has_audio = state.explorer_has_audio or {}
    state.explorer_has_audio[path] = false
    return
  end
  state.explorer_has_audio = state.explorer_has_audio or {}
  state.explorer_has_audio_queue = state.explorer_has_audio_queue or {}
  state.explorer_has_audio_queued = state.explorer_has_audio_queued or {}
  if state.explorer_has_audio[path] ~= nil or state.explorer_has_audio_queued[path] then
    return
  end
  state.explorer_has_audio_queued[path] = true
  state.explorer_has_audio_queue[#state.explorer_has_audio_queue + 1] = path
end

function explorer_pump_has_audio()
  if not state.explorer_hide_empty then
    return
  end
  explorer_seed_has_audio_from_samples()
  local queue = state.explorer_has_audio_queue or {}
  if #queue == 0 then
    return
  end
  local budget = 10
  local started = r.time_precise and r.time_precise() or 0
  while budget > 0 and #queue > 0 do
    local path = table.remove(queue, 1)
    state.explorer_has_audio_queued[path] = nil
    if state.explorer_has_audio[path] == nil then
      local dirs, files = explorer_list_dir(path)
      budget = budget - 1
      if files and #files > 0 then
        explorer_mark_has_audio(path)
      elseif not dirs then
        state.explorer_has_audio[path] = false
        explorer_invalidate_rows()
      else
        local unknown, any_true = 0, false
        for _, name in ipairs(dirs) do
          local child = explorer_join_path(path, name)
          if explorer_is_safe_child(path, child) then
            local cached = state.explorer_has_audio[child]
            if cached == true then
              any_true = true
              break
            elseif cached == nil then
              unknown = unknown + 1
              explorer_queue_has_audio(child)
            end
          end
        end
        if any_true then
          explorer_mark_has_audio(path)
        elseif unknown == 0 then
          state.explorer_has_audio[path] = false
          explorer_invalidate_rows()
        else
          explorer_queue_has_audio(path)
        end
      end
    end
    if r.time_precise and (r.time_precise() - started) > 0.006 then
      break
    end
  end
end

function explorer_dir_has_audio(path)
  path = normalize_path(path or "")
  if path == "" then
    return false
  end
  explorer_seed_has_audio_from_samples()
  local cached = state.explorer_has_audio[path]
  if cached ~= nil then
    return cached
  end
  explorer_queue_has_audio(path)
  return true
end

function explorer_dir_should_show(path)
  if not state.explorer_hide_empty then
    return true
  end
  return explorer_dir_has_audio(path)
end

function folder_filter_list()
  return state.folder_filter_paths or {}
end

function folder_filter_key()
  local paths = {}
  for _, path in ipairs(folder_filter_list()) do
    paths[#paths + 1] = path
  end
  table.sort(paths)
  return table.concat(paths, "\n")
end

function folder_filter_has(path)
  path = normalize_path(path or "")
  if path == "" then
    return false
  end
  for _, existing in ipairs(folder_filter_list()) do
    if existing == path then
      return true
    end
  end
  return false
end

function folder_filter_add(path)
  path = normalize_path(path or "")
  if path == "" or folder_filter_has(path) then
    return
  end
  state.folder_filter_paths = state.folder_filter_paths or {}
  state.folder_filter_paths[#state.folder_filter_paths + 1] = path
end

function folder_filter_remove(path)
  path = normalize_path(path or "")
  local kept = {}
  for _, existing in ipairs(folder_filter_list()) do
    if existing ~= path then
      kept[#kept + 1] = existing
    end
  end
  state.folder_filter_paths = kept
end

function folder_filter_toggle(path)
  if folder_filter_has(path) then
    folder_filter_remove(path)
  else
    folder_filter_add(path)
  end
end

function folder_filter_matches_sample(sample_path)
  local filters = folder_filter_list()
  if #filters == 0 then
    return true
  end
  sample_path = normalize_path(sample_path or "")
  if sample_path == "" then
    return false
  end
  for _, filter_path in ipairs(filters) do
    if sample_path == filter_path then
      return true
    end
    if #sample_path > #filter_path and sample_path:sub(1, #filter_path) == filter_path then
      if sample_path:sub(#filter_path + 1, #filter_path + 1) == "/" then
        return true
      end
    end
  end
  return false
end

function folder_filter_chip_label(path)
  path = normalize_path(path or "")
  local name = path:match("([^/]+)$") or path
  local dup = 0
  for _, existing in ipairs(folder_filter_list()) do
    local other = existing:match("([^/]+)$") or existing
    if string.lower(other) == string.lower(name) then
      dup = dup + 1
    end
  end
  if dup > 1 then
    local parent = path:match("([^/]+)/[^/]+$")
    if parent then
      return parent .. " / " .. name
    end
  end
  return name
end

function render_folder_filter_chips(opts)
  opts = opts or {}
  local filters = folder_filter_list()
  if #filters == 0 then
    return false
  end
  for i, path in ipairs(filters) do
    local label = folder_filter_chip_label(path)
    local chip_w = calc_tag_chip_width(label)
    if i > 1 or not opts.new_line then
      imgui_same_line_if_fits(chip_w, i == 1 and 8 or 4)
    end
    if draw_ui_button("folder_filter_chip_" .. path, label, nil, 22, {
      compact = true,
      selected = true,
    }) then
      folder_filter_remove(path)
    end
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, path .. "\nClick to remove this folder filter")
    end
  end
  return true
end

function explorer_folder_filter_active(path)
  return folder_filter_has(path)
end

function explorer_toggle_folder_filter(path)
  folder_filter_toggle(path)
end

function explorer_list_dir(path)
  path = normalize_path(path or "")
  if path == "" then
    return nil, nil
  end
  explorer_pump_seed_from_samples()
  local cache = state.explorer_dir_cache[path]
  if cache then
    explorer_ensure_sorted(cache)
    return cache.dirs, cache.files
  end
  if not state.explorer_cache_seeded then
    return {}, {}
  end
  -- Stay off the disk while browsing. Missing folders show empty until Refresh.
  cache = explorer_ensure_cache_entry(path)
  return cache.dirs, cache.files
end

function explorer_name_matches(name, filter)
  if not filter or filter == "" then
    return true
  end
  return string.find(string.lower(tostring(name or "")), filter, 1, true) ~= nil
end

function explorer_dir_has_visible_match(path, filter, depth, seen)
  if not filter or filter == "" then
    return true
  end
  depth = depth or 0
  if depth > EXPLORER_MAX_DEPTH then
    return false
  end
  path = normalize_path(path or "")
  seen = seen or {}
  if path == "" or seen[path] then
    return false
  end
  seen[path] = true
  local cache = state.explorer_dir_cache[path]
  if not cache then
    return false
  end
  for _, name in ipairs(cache.dirs) do
    if explorer_name_matches(name, filter) then
      return true
    end
    local child = explorer_join_path(path, name)
    if explorer_is_safe_child(path, child) and explorer_dir_has_visible_match(child, filter, depth + 1, seen) then
      return true
    end
  end
  for _, name in ipairs(cache.files) do
    if explorer_name_matches(name, filter) then
      return true
    end
  end
  return false
end

function explorer_join_path(dir, name)
  return normalize_path((dir or "") .. "/" .. (name or ""))
end

function explorer_custom_tags_for(path)
  path = normalize_path(path or "")
  if path == "" or not state.custom_tags then
    return nil, path
  end
  local tags = state.custom_tags[path]
  if tags then
    return tags, path
  end
  local key = path_index_key(path)
  for stored, stored_tags in pairs(state.custom_tags) do
    if path_index_key(stored) == key then
      return stored_tags, stored
    end
  end
  return nil, path
end

function explorer_get_tags(path)
  path = normalize_path(path or "")
  local sample = find_sample_by_path(path)
  if sample and type(sample.tags) == "table" then
    return sample.tags
  end
  local custom = explorer_custom_tags_for(path)
  return custom or {}
end

function explorer_known_tags()
  local seen, out = {}, {}
  for _, entry in ipairs(TAG_KEYWORDS) do
    if entry.tag and not seen[entry.tag] then
      seen[entry.tag] = true
      out[#out + 1] = entry.tag
    end
  end
  for _, item in ipairs(state.tag_list or {}) do
    if item.tag and not seen[item.tag] then
      seen[item.tag] = true
      out[#out + 1] = item.tag
    end
  end
  for child, _ in pairs(state.tag_parent_map or {}) do
    if child and child ~= "" and not seen[child] then
      seen[child] = true
      out[#out + 1] = child
    end
  end
  table.sort(out, function(a, b) return string.lower(a) < string.lower(b) end)
  return out
end

function explorer_add_tag(path, tag)
  path = normalize_path(path or "")
  tag = explorer_normalize_tag(tag)
  if path == "" or tag == "" then
    return false
  end
  if state.deleted_tags then
    state.deleted_tags[string.lower(tag)] = nil
  end

  local sample = find_sample_by_path(path)
  local store_path = (sample and sample.path) or path
  state.custom_tags = state.custom_tags or {}
  local custom = select(1, explorer_custom_tags_for(store_path)) or state.custom_tags[store_path] or {}
  local already = false
  for _, existing in ipairs(custom) do
    if existing == tag then
      already = true
      break
    end
  end
  if not already then
    custom[#custom + 1] = tag
    state.custom_tags[store_path] = custom
  end

  if sample then
    sample.tags = append_unique_tags(sample.tags or {}, { tag })
    if preview_sample_obj and preview_sample_obj.path and path_index_key(preview_sample_obj.path) == path_index_key(store_path) then
      preview_sample_obj.tags = sample.tags
    end
    rebuild_tag_index()
    save_samples()
  end
  save_config()
  return true
end

function explorer_remove_tag(path, tag)
  path = normalize_path(path or "")
  if path == "" or not tag then
    return false
  end

  local custom, store_path = explorer_custom_tags_for(path)
  if custom and store_path then
    local kept = {}
    for _, existing in ipairs(custom) do
      if existing ~= tag then
        kept[#kept + 1] = existing
      end
    end
    if #kept > 0 then
      state.custom_tags[store_path] = kept
    else
      state.custom_tags[store_path] = nil
    end
  end

  local sample = find_sample_by_path(path)
  if sample and type(sample.tags) == "table" then
    local kept = {}
    for _, existing in ipairs(sample.tags) do
      if existing ~= tag then
        kept[#kept + 1] = existing
      end
    end
    sample.tags = kept
    if preview_sample_obj and preview_sample_obj.path and path_index_key(preview_sample_obj.path) == path_index_key(sample.path or path) then
      preview_sample_obj.tags = kept
    end
    rebuild_tag_index()
    save_samples()
  end
  save_config()
  return true
end

function explorer_sample_for_path(path)
  path = normalize_path(path or "")
  local sample = find_sample_by_path(path)
  if sample then
    return sample
  end
  return {
    path = path,
    name = path:match("([^/]+)$") or path,
    folder = path:match("(.+)/[^/]+$") or "",
    tags = explorer_get_tags(path),
    duration = 0,
  }
end

function explorer_select_file(path, play)
  path = normalize_path(path or "")
  if path == "" then
    return
  end
  state.explorer_selected_path = path
  local sample = explorer_sample_for_path(path)
  if play then
    preview_sample(sample)
  end
  if not preview_sample_obj or preview_sample_obj.path ~= path then
    preview_sample_obj = sample
  end
end

function explorer_match_tags(query, exclude_set)
  query = string.lower(explorer_normalize_tag(query))
  if query == "" then
    return {}
  end
  local out = {}
  for _, tag in ipairs(explorer_known_tags()) do
    if not (exclude_set and exclude_set[tag]) then
      if string.find(string.lower(tag), query, 1, true) then
        out[#out + 1] = tag
        if #out >= 8 then
          break
        end
      end
    end
  end
  return out
end

function explorer_open_tag_popup(path)
  path = normalize_path(path or "")
  if path == "" then
    return
  end
  state.explorer_tag_target = path
  state.explorer_tag_input = ""
  state.explorer_selected_path = path
  local mx, my = r.ImGui_GetMousePos(ctx)
  state.explorer_tag_popup_pos = { x = mx, y = my }
  state.explorer_tag_popup_open = true
end

function explorer_draw_wrapped_tags(tags, id_prefix, active_lookup, on_click, after_item)
  if not tags or #tags == 0 then
    return
  end
  for i, tag in ipairs(tags) do
    local chip_w = calc_tag_chip_width(tag)
    if i > 1 or after_item then
      imgui_same_line_if_fits(chip_w, 4)
    end
    local active = active_lookup and active_lookup[tag] or false
    if draw_tag_button(ctx, tag, active, tag, id_prefix) then
      on_click(tag)
    end
  end
end

function explorer_render_tag_editor(path, id_prefix)
  path = normalize_path(path or "")
  if path == "" then
    return
  end
  local current = explorer_get_tags(path)
  local current_set = {}
  for _, tag in ipairs(current) do
    current_set[tag] = true
  end

  if draw_ui_button(id_prefix .. "add_tag", "+", 22, 22, { compact = true, pill = true }) then
    tag_add_open_for(path)
    r.ImGui_OpenPopup(ctx, "##tag_add_popup")
  end
  if r.ImGui_IsItemHovered(ctx) then
    r.ImGui_SetTooltip(ctx, "Add a tag")
  end
  explorer_draw_wrapped_tags(current, id_prefix .. "cur_", current_set, function(tag)
    explorer_remove_tag(path, tag)
  end, true)
  render_tag_add_popup()
end

function explorer_render_row(kind, path, name, depth, offline)
  local row_h = 22
  local indent = depth * 16
  local avail_w = r.ImGui_GetContentRegionAvail(ctx)
  local selected = state.explorer_selected_path == path
  local open = kind == "dir" and state.explorer_open_dirs[path] == true
  local filtering = kind == "dir" and explorer_folder_filter_active(path)

  r.ImGui_InvisibleButton(ctx, "##exp_" .. kind .. "_" .. path, math.max(40, avail_w), row_h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local right_clicked = r.ImGui_IsItemClicked(ctx, 1)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local mx, my = r.ImGui_GetMousePos(ctx)

  if selected or filtering then
    r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, UI_THEME.accent_fill, 4.0)
  elseif hovered then
    r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, UI_THEME.surface_hvr, 4.0)
  end

  local cx = x0 + indent + 10
  local cy = (y0 + y1) * 0.5
  local icon_hovered = false
  if kind == "dir" then
    ui_button_draw_icon(dl, open and "chev_down" or "chev_right", cx, cy, 12, hovered and UI_THEME.text or UI_THEME.text_mute)
    cx = cx + 14
    icon_hovered = hovered and mx >= (cx - 9) and mx <= (cx + 9) and my >= y0 and my <= y1
    local show_filter = filtering or icon_hovered
    local icon_col
    if offline then
      icon_col = UI_THEME.text_mute
    elseif show_filter then
      icon_col = UI_THEME.accent_hvr
    elseif hovered then
      icon_col = UI_THEME.folder_hvr
    else
      icon_col = UI_THEME.folder
    end
    ui_button_draw_icon(dl, show_filter and "filter" or "folder", cx, cy, 14, icon_col)
    cx = cx + 14
    if icon_hovered then
      r.ImGui_SetTooltip(ctx, filtering and "Remove this folder from the filter" or "Add this folder to the sample map filter")
    end
  else
    cx = cx + 14
    ui_button_draw_icon(dl, "audio", cx, cy, 14, selected and UI_THEME.accent_hvr or UI_THEME.text_dim)
    cx = cx + 14
  end

  local label = name
  if offline then
    label = name .. "  (offline)"
  end
  local _, th = r.ImGui_CalcTextSize(ctx, label)
  local text_col = offline and UI_THEME.text_mute or ((selected or hovered) and UI_THEME.text or UI_THEME.text_dim)
  r.ImGui_DrawList_AddText(dl, cx + 4, cy - th * 0.5, text_col, label)

  if kind == "file" then
    local tags = explorer_get_tags(path)
    if #tags > 0 then
      local chip_x = cx + 8 + r.ImGui_CalcTextSize(ctx, label)
      local shown = 0
      for _, tag in ipairs(tags) do
        if shown >= 3 then
          local extra = string.format("+%d", #tags - shown)
          r.ImGui_DrawList_AddText(dl, chip_x + 4, cy - th * 0.5, UI_THEME.text_mute, extra)
          break
        end
        local tw = r.ImGui_CalcTextSize(ctx, tag)
        local chip_w = tw + 10
        if chip_x + chip_w > x1 - 8 then
          break
        end
        local tag_color = state.tag_colors[tag] or 0x336699
        local cr, cg, cb = extract_rgb(tag_color)
        local fill = build_color_rrgbbaa(cr, cg, cb, 90)
        r.ImGui_DrawList_AddRectFilled(dl, chip_x, y0 + 4, chip_x + chip_w, y1 - 4, fill, 6.0)
        r.ImGui_DrawList_AddText(dl, chip_x + 5, cy - th * 0.5, 0xF0F0F0FF, tag)
        chip_x = chip_x + chip_w + 4
        shown = shown + 1
      end
    end
  end

  if kind == "dir" and clicked then
    if icon_hovered then
      explorer_toggle_folder_filter(path)
    else
      state.explorer_open_dirs[path] = not open
      explorer_invalidate_rows()
      save_config()
    end
  elseif kind == "file" and clicked then
    explorer_select_file(path, true)
  end
  if kind == "file" and right_clicked then
    explorer_open_tag_popup(path)
  end
end

function explorer_collect_rows()
  local rows = {}
  local filter = string.lower(state.explorer_filter or "")
  local seen = {}

  local function consider_dir(path, name, depth, offline)
    if #rows >= EXPLORER_MAX_ROWS or depth > EXPLORER_MAX_DEPTH then
      return
    end
    path = normalize_path(path or "")
    if path == "" or seen[path] then
      return
    end
    seen[path] = true
    if not offline and not explorer_dir_should_show(path) then
      return
    end
    if filter ~= ""
        and not explorer_name_matches(name, filter)
        and not state.explorer_open_dirs[path]
        and not explorer_dir_has_visible_match(path, filter) then
      return
    end
    rows[#rows + 1] = {
      kind = "dir",
      path = path,
      name = name,
      depth = depth,
      offline = offline and true or false,
    }
    if not state.explorer_open_dirs[path] then
      return
    end
    if offline then
      rows[#rows + 1] = { kind = "msg", text = "Folder is offline", depth = depth + 1 }
      return
    end
    local dirs, files = explorer_list_dir(path)
    if not dirs then
      rows[#rows + 1] = { kind = "msg", text = "Folder unavailable", depth = depth + 1 }
      return
    end
    for _, child_name in ipairs(dirs) do
      local child = explorer_join_path(path, child_name)
      if explorer_is_safe_child(path, child) then
        consider_dir(child, child_name, depth + 1, false)
      end
    end
    for _, file_name in ipairs(files) do
      if #rows >= EXPLORER_MAX_ROWS then
        break
      end
      if explorer_name_matches(file_name, filter) then
        rows[#rows + 1] = {
          kind = "file",
          path = explorer_join_path(path, file_name),
          name = file_name,
          depth = depth + 1,
          offline = false,
        }
      end
    end
  end

  for _, folder in ipairs(state.folders) do
    local root = normalize_path(folder)
    local root_name = root:match("([^/]+)$") or root
    local vol = volume_root_from_path(root)
    local offline = (vol and state.missing_volumes[vol]) or state.missing_scan_folders[root]
    consider_dir(root, root_name, 0, offline)
  end
  return rows
end

function explorer_get_rows()
  if not state.explorer_row_list then
    state.explorer_row_list = explorer_collect_rows()
  end
  return state.explorer_row_list
end

function explorer_render_clipped_rows(rows)
  local row_h = EXPLORER_ROW_H
  local scroll_y = 0
  if r.ImGui_GetScrollY then
    scroll_y = r.ImGui_GetScrollY(ctx) or 0
  end
  local avail_h = select(2, r.ImGui_GetContentRegionAvail(ctx)) or 400
  local pad = 6
  local first = math.max(1, math.floor(scroll_y / row_h) - pad + 1)
  local last = math.min(#rows, math.ceil((scroll_y + avail_h) / row_h) + pad)
  if first > 1 then
    r.ImGui_Dummy(ctx, 1, (first - 1) * row_h)
  end
  for i = first, last do
    local row = rows[i]
    if row.kind == "msg" then
      r.ImGui_Dummy(ctx, 1, row_h)
      local x0, y0 = r.ImGui_GetItemRectMin(ctx)
      r.ImGui_DrawList_AddText(
        r.ImGui_GetWindowDrawList(ctx),
        x0 + (row.depth or 0) * 16 + 24,
        y0 + 4,
        UI_THEME.text_mute,
        row.text or ""
      )
    else
      explorer_render_row(row.kind, row.path, row.name, row.depth, row.offline)
    end
  end
  if last < #rows then
    r.ImGui_Dummy(ctx, 1, (#rows - last) * row_h)
  end
end

function explorer_render_tag_popup()
  local pos = state.explorer_tag_popup_pos
  if state.explorer_tag_popup_open then
    state.explorer_tag_popup_open = false
    if pos and r.ImGui_SetNextWindowPos then
      r.ImGui_SetNextWindowPos(ctx, pos.x, pos.y, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
    end
    r.ImGui_OpenPopup(ctx, "##explorer_tag_popup")
  elseif pos and r.ImGui_SetNextWindowPos then
    r.ImGui_SetNextWindowPos(
      ctx,
      pos.x,
      pos.y,
      r.ImGui_Cond_Appearing and r.ImGui_Cond_Appearing() or 0
    )
  end
  if not r.ImGui_BeginPopup(ctx, "##explorer_tag_popup") then
    if not state.explorer_tag_popup_open then
      state.explorer_tag_popup_pos = nil
    end
    return
  end
  local path = state.explorer_tag_target
  if not path or path == "" then
    r.ImGui_EndPopup(ctx)
    return
  end

  r.ImGui_Text(ctx, path:match("([^/]+)$") or path)
  r.ImGui_TextColored(ctx, UI_THEME.text_mute, "Assigned tags")
  r.ImGui_Separator(ctx)
  r.ImGui_PushItemWidth(ctx, 260)
  explorer_render_tag_editor(path, "popup_")
  r.ImGui_PopItemWidth(ctx)
  r.ImGui_Separator(ctx)
  if r.ImGui_Selectable(ctx, "Reveal in Finder / Explorer") then
    seq_reveal_sample_in_explorer(explorer_sample_for_path(path))
  end
  r.ImGui_EndPopup(ctx)
end

EXPLORER_SPLIT_W = 6
EXPLORER_DOCK_MIN_W = 220
EXPLORER_DOCK_MAX_W = 900

function explorer_dock_host()
  local d = state.explorer_docked
  if d == true then
    return "sample_map"
  end
  if d == "sample_map" or d == "sequencer" then
    return d
  end
  return nil
end

function explorer_is_docked_in(host)
  return state.explorer_open and explorer_dock_host() == host
end

function explorer_host_is_open(host)
  if host == "sample_map" then
    return sample_map_is_open()
  end
  if host == "sequencer" then
    return sequencer_is_open()
  end
  return false
end

function explorer_dock_width()
  return math.max(EXPLORER_DOCK_MIN_W, math.min(EXPLORER_DOCK_MAX_W, state.explorer_width or 320))
end

function explorer_draw_dock_splitter(host, height, avail_x)
  local split_w = EXPLORER_SPLIT_W
  r.ImGui_InvisibleButton(ctx, "##explorer_split_" .. tostring(host), split_w, math.max(1, height or 0))
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  local dragging = state.explorer_split_drag and state.explorer_split_drag.host == host
  if hovered or active or dragging then
    if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeEW then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeEW())
    end
  end
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local col = (active or dragging) and UI_THEME.accent or (hovered and UI_THEME.border_hvr or UI_THEME.border)
  local mid = (x0 + x1) * 0.5
  r.ImGui_DrawList_AddRectFilled(dl, mid - 1.0, y0 + 10, mid + 1.0, y1 - 10, col, 1.0)

  local mx = r.ImGui_GetMousePos(ctx)
  if active then
    if not dragging then
      state.explorer_split_drag = {
        host = host,
        start_x = mx,
        width0 = explorer_dock_width(),
        avail_x = avail_x or 0,
      }
    else
      local drag = state.explorer_split_drag
      local max_w = math.max(EXPLORER_DOCK_MIN_W, (drag.avail_x or 0) - 180 - split_w)
      max_w = math.min(EXPLORER_DOCK_MAX_W, max_w)
      local new_w = drag.width0 + (drag.start_x - mx)
      state.explorer_width = math.max(EXPLORER_DOCK_MIN_W, math.min(max_w, new_w))
    end
  elseif dragging then
    state.explorer_split_drag = nil
    save_config()
  end
end

function explorer_render_toolbar()
  if render_folder_filter_chips({ new_line = true }) then
    r.ImGui_Spacing(ctx)
  end
  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 6, 4)
  if r.ImGui_InputTextWithHint then
    local changed, text = r.ImGui_InputTextWithHint(ctx, "##explorer_filter", "Filter folders and files…", state.explorer_filter or "")
    seq_mark_text_input_item()
    if changed then
      state.explorer_filter = text
      explorer_invalidate_rows()
    end
  else
    local changed, text = r.ImGui_InputText(ctx, "##explorer_filter", state.explorer_filter or "", 256)
    seq_mark_text_input_item()
    if changed then
      state.explorer_filter = text
      explorer_invalidate_rows()
    end
  end
  r.ImGui_SameLine(ctx)
  if draw_ui_button("explorer_hide_empty", "", 22, 22, {
    icon = "hide",
    compact = true,
    selected = state.explorer_hide_empty,
  }) then
    state.explorer_hide_empty = not state.explorer_hide_empty
    explorer_invalidate_rows()
    save_config()
  end
  if r.ImGui_IsItemHovered(ctx) then
    r.ImGui_SetTooltip(ctx, state.explorer_hide_empty
      and "Showing only folders that contain audio"
      or "Hide folders that contain no audio files")
  end
  r.ImGui_SameLine(ctx)
  if draw_ui_button("explorer_refresh", "Refresh", nil, nil, { compact = true }) then
    state.explorer_want_disk_refresh = true
    explorer_invalidate_cache()
  end
  if r.ImGui_IsItemHovered(ctx) then
    r.ImGui_SetTooltip(ctx, "Reload folder contents from disk")
  end
  r.ImGui_SameLine(ctx)
  if explorer_dock_host() then
    if draw_ui_button("explorer_undock", "Undock", nil, nil, { compact = true }) then
      state.explorer_docked = false
      save_config()
    end
  else
    if sample_map_is_open() then
      if draw_ui_button("explorer_dock_map", "Dock to Map", nil, nil, { compact = true }) then
        state.explorer_docked = "sample_map"
        save_config()
      end
    end
    if sequencer_is_open() then
      if sample_map_is_open() then
        r.ImGui_SameLine(ctx)
      end
      if draw_ui_button("explorer_dock_seq", "Dock to Sequencer", nil, nil, { compact = true }) then
        state.explorer_docked = "sequencer"
        save_config()
      end
    end
  end
  r.ImGui_PopStyleVar(ctx)
end

function explorer_render_tree()
  local child_flags = 0
  if r.ImGui_ChildFlags_Border then
    child_flags = r.ImGui_ChildFlags_Border
  end
  local _, after_toolbar = r.ImGui_GetContentRegionAvail(ctx)
  local tree_h = math.max(80, after_toolbar - 6)

  if r.ImGui_BeginChild(ctx, "explorer_tree", 0, tree_h, child_flags) then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 0, 0)
    local rows = explorer_get_rows()
    if #rows == 0 then
      r.ImGui_TextColored(ctx, UI_THEME.text_mute, "No folders to show")
    else
      explorer_render_clipped_rows(rows)
    end
    r.ImGui_PopStyleVar(ctx)
  end
  r.ImGui_EndChild(ctx)
end

function render_explorer_content()
  if #state.folders == 0 then
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, "No scan folders yet.")
    r.ImGui_TextColored(ctx, UI_THEME.text_mute, "Add a folder in Settings, then browse it here and right-click files to tag them.")
    if draw_ui_button("explorer_open_settings", "Open Settings", nil, nil, { style = "primary" }) then
      state.settings_open = true
    end
    return
  end

  if not next(state.explorer_open_dirs) then
    for _, folder in ipairs(state.folders) do
      state.explorer_open_dirs[normalize_path(folder)] = true
    end
  end

  explorer_pump_seed_from_samples()
  if state.explorer_index_dirty then
    state.explorer_index_dirty = false
    explorer_invalidate_rows()
  end
  explorer_pump_disk_refresh()
  explorer_pump_has_audio()
  explorer_render_toolbar()
  if not state.explorer_cache_seeded then
    local n = #(state.samples or {})
    local i = math.max(0, (state.explorer_seed_index or 1) - 1)
    r.ImGui_TextColored(ctx, UI_THEME.text_mute, string.format("Indexing folders… %d / %d", i, n))
  elseif (state.explorer_disk_queue and #state.explorer_disk_queue > 0) then
    r.ImGui_TextColored(ctx, UI_THEME.text_mute, "Refreshing folders from disk…")
  else
    r.ImGui_TextColored(ctx, UI_THEME.text_mute, "Right-click a file to set custom tags")
  end
  explorer_render_tree()
  explorer_render_tag_popup()
end

function render_explorer_window()
  if not state.explorer_open then
    return
  end
  local host = explorer_dock_host()
  if host and explorer_host_is_open(host) then
    return
  end

  -- Recover from a leftover 0-width native dock node, then keep this window floating.
  if not state.explorer_window_recovered then
    state.explorer_window_recovered = true
    if r.ImGui_SetNextWindowDockID then
      r.ImGui_SetNextWindowDockID(ctx, 0, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
    end
    r.ImGui_SetNextWindowSize(ctx, 380, 640, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
    if r.ImGui_SetNextWindowCollapsed then
      r.ImGui_SetNextWindowCollapsed(ctx, false, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
    end
  elseif r.ImGui_SetNextWindowDockID then
    r.ImGui_SetNextWindowDockID(ctx, 0, r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0)
  else
    r.ImGui_SetNextWindowSize(ctx, 380, 640, r.ImGui_Cond_FirstUseEver())
  end
  if r.ImGui_SetNextWindowSizeConstraints then
    r.ImGui_SetNextWindowSizeConstraints(ctx, 260, 220, 1600, 1600)
  end

  local flags = r.ImGui_WindowFlags_None and r.ImGui_WindowFlags_None() or 0
  if r.ImGui_WindowFlags_NoDocking then
    flags = flags | r.ImGui_WindowFlags_NoDocking()
  end
  if r.ImGui_WindowFlags_NoCollapse then
    flags = flags | r.ImGui_WindowFlags_NoCollapse()
  end

  -- ReaImGui can fail Begin during docker attach/detach without pushing a window.
  -- Calling End() in that state poisons the context and prevents the script from restarting.
  local began_ok, visible, open = pcall(r.ImGui_Begin, ctx, "Library Explorer", true, flags)
  if not began_ok then
    return
  end
  if visible then
    render_explorer_content()
    pcall(r.ImGui_End, ctx)
  end
  if open == false then
    state.explorer_open = false
    save_config()
  end
end

function render_explorer_docked_panel(height)
  if not (state.explorer_open and explorer_dock_host()) then
    return
  end
  local child_flags = 0
  if r.ImGui_ChildFlags_Border then
    child_flags = r.ImGui_ChildFlags_Border
  end
  local w = explorer_dock_width()
  if r.ImGui_BeginChild(ctx, "explorer_dock", w, math.max(0, height or 0), child_flags) then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 6, 4)
    r.ImGui_AlignTextToFramePadding(ctx)
    r.ImGui_Text(ctx, "Library Explorer")
    r.ImGui_SameLine(ctx)
    local remain = r.ImGui_GetContentRegionAvail(ctx)
    if remain > 86 then
      r.ImGui_Dummy(ctx, remain - 86, 1)
      r.ImGui_SameLine(ctx, 0, 0)
    end
    if draw_ui_button("explorer_dock_close", "Close", nil, nil, { compact = true, style = "danger" }) then
      state.explorer_open = false
      save_config()
    end
    r.ImGui_PopStyleVar(ctx)
    render_explorer_content()
  end
  r.ImGui_EndChild(ctx)
end

function render_view_tab_switcher()
  local icon_size = 15
  local btn_h = 28
  local pad_x = 10
  local icon_text_gap = 6
  local tab_gap = 3
  local track_pad = 3

  local function draw_sample_map_icon(dl, x0, y0, sz, color, accent)
    local pad = sz * 0.16
    local ix0 = x0 + pad
    local iy0 = y0 + pad
    local ix1 = x0 + sz - pad
    local iy1 = y0 + sz - pad
    local w = ix1 - ix0
    local h = iy1 - iy0
    r.ImGui_DrawList_AddRect(dl, ix0, iy0, ix1, iy1, color, 3.0, 0, 1.2)
    local mid_x = ix0 + w * 0.5
    local mid_y = iy0 + h * 0.5
    local cr, cg, cb = extract_rgb_rrgbbaa(color)
    local axis_color = build_color_rrgbbaa(cr, cg, cb, 70)
    r.ImGui_DrawList_AddLine(dl, mid_x, iy0 + 2, mid_x, iy1 - 2, axis_color, 1.0)
    r.ImGui_DrawList_AddLine(dl, ix0 + 2, mid_y, ix1 - 2, mid_y, axis_color, 1.0)
    local dots = {
      {0.20, 0.24, 2.2, accent},
      {0.58, 0.18, 1.6, color},
      {0.34, 0.56, 2.4, accent},
      {0.76, 0.58, 1.5, color},
      {0.16, 0.70, 1.8, color},
      {0.52, 0.80, 2.0, accent},
    }
    for _, dot in ipairs(dots) do
      r.ImGui_DrawList_AddCircleFilled(dl, ix0 + w * dot[1], iy0 + h * dot[2], dot[3], dot[4], 12)
    end
  end

  local function draw_sequencer_icon(dl, x0, y0, sz, color, accent)
    local pad = sz * 0.14
    local ix0 = x0 + pad
    local iy0 = y0 + pad
    local ix1 = x0 + sz - pad
    local iy1 = y0 + sz - pad
    local w = ix1 - ix0
    local h = iy1 - iy0
    local cols, rows, gap = 4, 3, 1.6
    local cell_w = (w - gap * (cols - 1)) / cols
    local cell_h = (h - gap * (rows - 1)) / rows
    local cr, cg, cb = extract_rgb_rrgbbaa(color)
    local inactive_color = build_color_rrgbbaa(cr, cg, cb, 90)
    local active_steps = { {1, 3}, {2, 1, 4}, {2, 3} }
    for row = 1, rows do
      for col = 1, cols do
        local cx0 = ix0 + (col - 1) * (cell_w + gap)
        local cy0 = iy0 + (row - 1) * (cell_h + gap)
        local is_active = false
        for _, active_col in ipairs(active_steps[row] or {}) do
          if active_col == col then is_active = true break end
        end
        if is_active then
          r.ImGui_DrawList_AddRectFilled(dl, cx0, cy0, cx0 + cell_w, cy0 + cell_h, accent, 2.0)
        else
          r.ImGui_DrawList_AddRect(dl, cx0, cy0, cx0 + cell_w, cy0 + cell_h, inactive_color, 2.0, 0, 1.0)
        end
      end
    end
  end

  local tabs = {
    { id = "sample_map", label = "Sample Map", icon = draw_sample_map_icon },
    { id = "sequencer", label = "Sequencer", icon = draw_sequencer_icon },
  }
  local widths = {}
  local total_w = track_pad * 2 + tab_gap * (#tabs - 1)
  for i, tab in ipairs(tabs) do
    local text_w = r.ImGui_CalcTextSize(ctx, tab.label)
    widths[i] = pad_x + icon_size + icon_text_gap + text_w + pad_x
    local floating = (tab.id == "sample_map" and state.sample_map_floating)
      or (tab.id == "sequencer" and state.sequencer_floating)
    if floating then
      widths[i] = widths[i] + 12
    end
    total_w = total_w + widths[i]
  end

  local track_x, track_y = r.ImGui_GetCursorScreenPos(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  ui_draw_panel(dl, track_x, track_y, track_x + total_w, track_y + btn_h, 9.0, UI_THEME.bg_panel, UI_THEME.border, false, false)
  local inner_h = btn_h
  r.ImGui_SetCursorScreenPos(ctx, track_x + track_pad, track_y)

  for i, tab in ipairs(tabs) do
    if i > 1 then
      r.ImGui_SameLine(ctx, 0, tab_gap)
    end
    local floating = (tab.id == "sample_map" and state.sample_map_floating)
      or (tab.id == "sequencer" and state.sequencer_floating)
    local active = state.active_view == tab.id and not floating
    local clicked = r.ImGui_InvisibleButton(ctx, "##view_tab_" .. tab.id, widths[i], inner_h)
    local x0, y0 = r.ImGui_GetItemRectMin(ctx)
    local x1, y1 = r.ImGui_GetItemRectMax(ctx)
    local hovered = r.ImGui_IsItemHovered(ctx)
    local pressed = r.ImGui_IsItemActive(ctx)
    if clicked then
      if floating then
        dock_floating_view(tab.id)
      elseif state.active_view ~= tab.id then
        state.active_view = tab.id
        save_config()
      end
    end
    if hovered and floating then
      r.ImGui_SetTooltip(ctx, "Dock " .. tab.label .. " back into this window")
    end

    local bg, border, icon_color, accent_color, text_color
    if active then
      bg = UI_THEME.accent_fill
      border = UI_THEME.accent
      icon_color = 0xF2F6FAFF
      accent_color = UI_THEME.accent_hvr
      text_color = 0xF2F6FAFF
    elseif hovered then
      bg = UI_THEME.surface_hvr
      border = UI_THEME.border_hvr
      icon_color = UI_THEME.text
      accent_color = UI_THEME.accent
      text_color = UI_THEME.text
    else
      bg = 0x00000000
      border = 0x00000000
      icon_color = UI_THEME.text_mute
      accent_color = 0x148A3AFF
      text_color = UI_THEME.text_dim
    end

    if active or hovered then
      ui_draw_panel(dl, x0, y0, x1, y1, inner_h * 0.5, bg, border, hovered, pressed)
    end

    local icon_x0 = x0 + pad_x
    local icon_y0 = y0 + (inner_h - icon_size) * 0.5 + (pressed and 1.0 or 0.0)
    tab.icon(dl, icon_x0, icon_y0, icon_size, icon_color, accent_color)
    local text_w, text_h = r.ImGui_CalcTextSize(ctx, tab.label)
    local text_x = icon_x0 + icon_size + icon_text_gap
    local text_y = y0 + (inner_h - text_h) * 0.5 + (pressed and 1.0 or 0.0)
    r.ImGui_DrawList_AddText(dl, text_x, text_y, text_color, tab.label)
    if floating then
      ui_button_draw_icon(dl, "popout", x1 - 11, y0 + inner_h * 0.5 + (pressed and 1.0 or 0.0), 11, text_color)
    end
  end

  r.ImGui_SameLine(ctx, 0, 6)
  local float_view = state.active_view
  local already_floating = (float_view == "sample_map" and state.sample_map_floating)
    or (float_view == "sequencer" and state.sequencer_floating)
  local both_floating = state.sample_map_floating and state.sequencer_floating
  if not both_floating and not already_floating then
    if draw_ui_button("view_popout", nil, inner_h, inner_h, { icon = "popout", compact = true }) then
      pop_out_active_view()
    end
    if r.ImGui_IsItemHovered(ctx) then
      local name = float_view == "sequencer" and "Sequencer" or "Sample Map"
      r.ImGui_SetTooltip(ctx, "Open " .. name .. " in a separate window")
    end
  end
end

function render_sample_map_tab_bar()
  ensure_map_tabs()
  local btn_h = 22
  local plus_w = 22
  local close_w = 14
  local pad_x = 8
  local gap = 3

  for i, tab in ipairs(state.map_tabs or {}) do
    local active = tab.id == state.map_tab_active_id
    local label = map_tab_display_label(tab)
    local text_w = select(1, r.ImGui_CalcTextSize(ctx, label)) or 0
    local can_close = #(state.map_tabs) > 1
    local tab_w = pad_x + text_w + (can_close and (4 + close_w) or 0) + pad_x
    if i > 1 then
      imgui_same_line_if_fits(tab_w, gap)
    end
    local clicked = r.ImGui_InvisibleButton(ctx, "##map_tab_" .. tostring(tab.id), tab_w, btn_h)
    local hovered = r.ImGui_IsItemHovered(ctx)
    local pressed = r.ImGui_IsItemActive(ctx)
    local x0, y0 = r.ImGui_GetItemRectMin(ctx)
    local x1, y1 = r.ImGui_GetItemRectMax(ctx)
    local dl = r.ImGui_GetWindowDrawList(ctx)
    local bg, border, text_col
    if active then
      bg = UI_THEME.accent_fill
      border = UI_THEME.accent
      text_col = 0xF2F6FAFF
    elseif hovered then
      bg = UI_THEME.surface_hvr
      border = UI_THEME.border_hvr
      text_col = UI_THEME.text
    else
      bg = UI_THEME.surface
      border = UI_THEME.border
      text_col = UI_THEME.text_dim
    end
    ui_draw_panel(dl, x0, y0, x1, y1, btn_h * 0.5, bg, border, hovered, pressed)
    local text_y = y0 + (btn_h - select(2, r.ImGui_CalcTextSize(ctx, label))) * 0.5 + (pressed and 1.0 or 0.0)
    r.ImGui_DrawList_AddText(dl, x0 + pad_x, text_y, text_col, label)
    if can_close then
      local cx = x1 - pad_x - close_w * 0.5
      local cy = y0 + btn_h * 0.5 + (pressed and 1.0 or 0.0)
      if hovered or active then
        ui_button_draw_icon(dl, "close", cx, cy, 11, text_col)
      end
    end
    if clicked then
      local mx = select(1, r.ImGui_GetMousePos(ctx))
      if can_close and mx and mx >= (x1 - pad_x - close_w - 2) then
        close_map_tab(tab.id)
      else
        switch_map_tab(tab.id)
      end
    end
    if hovered then
      r.ImGui_SetTooltip(ctx, "Stores this tab's filter, tags, folders, zoom, and pan")
    end
  end

  if #(state.map_tabs or {}) < MAP_TAB_MAX then
    imgui_same_line_if_fits(plus_w, gap)
    if draw_ui_button("map_tab_add", nil, plus_w, btn_h, { icon = "plus", compact = true }) then
      add_map_tab()
    end
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, "New Sample Map tab")
    end
  end
end

function render_sample_map_toolbar()
  if draw_ui_button("map_layout_edit", "Layout", nil, 28, {
    compact = true,
    selected = state.map_ui_edit == true,
    style = state.map_ui_edit and "primary" or "default",
  }) then
    state.map_ui_edit = not state.map_ui_edit
    state.map_ui_drag = nil
    state.map_ui_drop = nil
    state.map_ui_split_drag = nil
  end
  if r.ImGui_IsItemHovered(ctx) then
    if state.map_ui_edit then
      r.ImGui_SetTooltip(ctx, "Layout edit mode is on.\nDrag a module to move it, drag its edges to resize.\nDouble-click a module to reset the layout.")
    else
      r.ImGui_SetTooltip(ctx, "Edit Sample Map layout.\nMove modules and resize their edges.")
    end
  end
  r.ImGui_SameLine(ctx, 0, 10)
  render_map_y_axis_combo()
  r.ImGui_SameLine(ctx, 0, 10)
  render_filter_input()
  render_folder_filter_chips()
  render_tag_filters()
  render_tag_delete_popup()
  render_library_tag_path_menu()
end

MAP_UI_GAP = 4
MAP_UI_EDGE = 7
MAP_UI_IDS = { "tracks", "tabs", "path", "wave", "map" }
MAP_UI_SPEC = {
  tracks = { flex_h = true, min_w = 140, min_h = 80, scroll = true },
  tabs = { flex_h = false, h = 28, min_w = 80, min_h = 24, scroll = false },
  path = { flex_h = false, h = 30, min_w = 80, min_h = 24, scroll = false },
  wave = { flex_h = false, h = 80, min_w = 160, min_h = 70, scroll = false },
  map = { flex_h = true, min_w = 120, min_h = 80, scroll = false },
}

function default_map_ui_layout()
  return {
    type = "row",
    children = {
      { type = "leaf", id = "tracks", w = state.seq_panel_width or 240 },
      { type = "col", children = {
        { type = "leaf", id = "tabs" },
        { type = "leaf", id = "path" },
        { type = "leaf", id = "wave" },
        { type = "leaf", id = "map" },
      } },
    },
  }
end

function map_ui_consider_drag(id)
  if not state.map_ui_edit or not id then
    return
  end
  if sample_drag_active() or state.pending_waveform_drop or state.map_ui_split_drag then
    return
  end
  if r.ImGui_IsItemHovered(ctx) and r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0) then
    state.map_ui_layout = default_map_ui_layout()
    state.map_ui_drag = nil
    state.map_ui_drop = nil
    save_config()
    return
  end
  if state.map_ui_drag then
    return
  end
  local dragging = r.ImGui_IsMouseDragging and r.ImGui_IsMouseDragging(ctx, 0, 6.0)
  if dragging and (r.ImGui_IsItemActive(ctx) or r.ImGui_IsItemHovered(ctx)) then
    state.map_ui_drag = { id = id }
  end
end

function map_ui_clone(node)
  if type(node) ~= "table" then
    return nil
  end
  local copy = { type = node.type, id = node.id, w = node.w, h = node.h, size = node.size }
  if type(node.children) == "table" then
    copy.children = {}
    for i, child in ipairs(node.children) do
      copy.children[i] = map_ui_clone(child)
    end
  end
  return copy
end

function map_ui_collect_ids(node, into)
  if type(node) ~= "table" then
    return
  end
  if node.type == "leaf" then
    if node.id then
      into[node.id] = (into[node.id] or 0) + 1
    end
    return
  end
  for _, child in ipairs(node.children or {}) do
    map_ui_collect_ids(child, into)
  end
end

function map_ui_validate(node)
  if type(node) ~= "table" then
    return false
  end
  local counts = {}
  map_ui_collect_ids(node, counts)
  for _, id in ipairs(MAP_UI_IDS) do
    if counts[id] ~= 1 then
      return false
    end
  end
  for id, n in pairs(counts) do
    if n ~= 1 or not MAP_UI_SPEC[id] then
      return false
    end
  end
  return true
end

function map_ui_flatten(node)
  if type(node) ~= "table" then
    return nil
  end
  if node.type == "leaf" then
    return node
  end
  local kids = {}
  for _, child in ipairs(node.children or {}) do
    local flat = map_ui_flatten(child)
    if flat then
      if flat.type == node.type and type(flat.children) == "table" then
        for _, grand in ipairs(flat.children) do
          kids[#kids + 1] = grand
        end
      else
        kids[#kids + 1] = flat
      end
    end
  end
  if #kids == 0 then
    return nil
  end
  if #kids == 1 then
    local only = kids[1]
    if node.w and not only.w then
      only.w = node.w
    end
    if node.h and not only.h then
      only.h = node.h
    end
    if node.size and not only.size and not only.w then
      only.size = node.size
    end
    return only
  end
  node.children = kids
  return node
end

function map_ui_detach(node, id)
  if type(node) ~= "table" then
    return nil, nil
  end
  if node.type == "leaf" then
    if node.id == id then
      return nil, node
    end
    return node, nil
  end
  local found = nil
  local kids = {}
  for _, child in ipairs(node.children or {}) do
    local kept, detached = map_ui_detach(child, id)
    if detached then
      found = detached
    end
    if kept then
      kids[#kids + 1] = kept
    end
  end
  node.children = kids
  return node, found
end

function map_ui_wrap_pair(kind, a, b, src)
  local wrap = { type = kind, children = { a, b } }
  if kind == "row" then
    wrap.w = src and (src.w or src.size) or nil
  else
    wrap.h = src and src.h or nil
  end
  return wrap
end

function map_ui_insert(node, target_id, incoming, edge)
  if type(node) ~= "table" then
    return node, false
  end
  local want = (edge == "left" or edge == "right") and "row" or "col"
  if node.type == "leaf" then
    if node.id ~= target_id then
      return node, false
    end
    local a, b = incoming, node
    if edge == "right" or edge == "bottom" then
      a, b = node, incoming
    end
    return map_ui_wrap_pair(want, a, b, node), true
  end
  for i, child in ipairs(node.children or {}) do
    if child.type == "leaf" and child.id == target_id then
      if node.type == want then
        local idx = i
        if edge == "right" or edge == "bottom" then
          idx = i + 1
        end
        table.insert(node.children, idx, incoming)
        return node, true
      end
      local a, b = incoming, child
      if edge == "right" or edge == "bottom" then
        a, b = child, incoming
      end
      node.children[i] = map_ui_wrap_pair(want, a, b, child)
      return node, true
    end
    local updated, done = map_ui_insert(child, target_id, incoming, edge)
    node.children[i] = updated
    if done then
      return node, true
    end
  end
  return node, false
end

function map_ui_sync_tracks_width(node)
  if type(node) ~= "table" then
    return
  end
  if node.type == "leaf" and node.id == "tracks" then
    local w = tonumber(node.w) or tonumber(node.size)
    if type(w) == "number" then
      state.seq_panel_width = w
    end
    return
  end
  for _, child in ipairs(node.children or {}) do
    map_ui_sync_tracks_width(child)
  end
end

function map_ui_dock(source_id, target_id, edge)
  if not source_id or not target_id or source_id == target_id then
    return
  end
  local root = map_ui_clone(state.map_ui_layout)
  local kept, detached = map_ui_detach(root, source_id)
  if not detached then
    return
  end
  kept = map_ui_flatten(kept)
  if detached.id == "tracks" and not detached.w and not detached.size then
    detached.w = state.seq_panel_width or 240
  end
  local inserted, ok = map_ui_insert(kept, target_id, detached, edge)
  if not ok then
    return
  end
  inserted = map_ui_flatten(inserted)
  if map_ui_validate(inserted) then
    state.map_ui_layout = inserted
    map_ui_sync_tracks_width(inserted)
  end
end

function map_ui_ensure_layout()
  if not map_ui_validate(state.map_ui_layout) then
    state.map_ui_layout = default_map_ui_layout()
    state.map_ui_layout_sanitized = true
  elseif not state.map_ui_layout_sanitized then
    map_ui_sanitize_sizes(state.map_ui_layout)
    state.map_ui_layout_sanitized = true
  end
  return state.map_ui_layout
end

function map_ui_sanitize_sizes(node)
  if type(node) ~= "table" then
    return
  end
  node._alloc_w = nil
  node._alloc_h = nil
  if type(node.w) == "number" then
    if node.w > 4000 then node.w = 4000 end
    if node.w < 1 then node.w = nil end
  end
  if type(node.size) == "number" then
    if node.size > 4000 then node.size = 4000 end
    if node.size < 1 then node.size = nil end
  end
  if type(node.h) == "number" then
    if node.h > 3000 then node.h = 3000 end
    if node.h < 1 then node.h = nil end
  end
  for _, child in ipairs(node.children or {}) do
    map_ui_sanitize_sizes(child)
  end
end

function map_ui_get_w(node)
  if type(node) ~= "table" then
    return nil
  end
  return tonumber(node.w) or tonumber(node.size)
end

function map_ui_get_h(node)
  if type(node) ~= "table" then
    return nil
  end
  return tonumber(node.h)
end

function map_ui_min_w(node)
  if type(node) == "table" and node.type == "leaf" and MAP_UI_SPEC[node.id] then
    return MAP_UI_SPEC[node.id].min_w or 80
  end
  return 80
end

function map_ui_min_h(node)
  if type(node) == "table" and node.type == "leaf" and MAP_UI_SPEC[node.id] then
    return MAP_UI_SPEC[node.id].min_h or 24
  end
  return 24
end

function map_ui_pref_h(node)
  if type(node) ~= "table" then
    return 40
  end
  local fixed = map_ui_get_h(node)
  if type(fixed) == "number" and fixed > 0 then
    return fixed
  end
  if node.type == "leaf" then
    local spec = MAP_UI_SPEC[node.id]
    if not spec then
      return 40
    end
    if spec.flex_h then
      return spec.min_h
    end
    return spec.h
  end
  if node.type == "col" then
    local h = 0
    for i, child in ipairs(node.children or {}) do
      if i > 1 then
        h = h + MAP_UI_GAP
      end
      h = h + map_ui_pref_h(child)
    end
    return h
  end
  local h = 0
  for _, child in ipairs(node.children or {}) do
    h = math.max(h, map_ui_pref_h(child))
  end
  return h
end

function map_ui_is_flex_h(node)
  if type(node) ~= "table" then
    return false
  end
  if node.type == "leaf" then
    local spec = MAP_UI_SPEC[node.id]
    return spec and spec.flex_h or false
  end
  for _, child in ipairs(node.children or {}) do
    if map_ui_is_flex_h(child) then
      return true
    end
  end
  return false
end

function map_ui_fit_sizes(sizes, mins, inner)
  local n = #sizes
  local sum = 0
  for i = 1, n do
    local minv = mins[i] or 0
    sizes[i] = math.max(minv, sizes[i] or 0)
    sum = sum + sizes[i]
  end
  if sum <= inner or sum <= 0 then
    return sizes
  end
  local extra = 0
  for i = 1, n do
    extra = extra + math.max(0, sizes[i] - (mins[i] or 0))
  end
  if extra <= 0 or (sum - inner) > extra then
    local scale = inner / sum
    for i = 1, n do
      sizes[i] = sizes[i] * scale
    end
    return sizes
  end
  local frac = (sum - inner) / extra
  for i = 1, n do
    local room = sizes[i] - (mins[i] or 0)
    if room > 0 then
      sizes[i] = sizes[i] - room * frac
    end
  end
  return sizes
end

function map_ui_col_heights(children, total)
  local n = #children
  local inner = math.max(0, total - MAP_UI_GAP * math.max(0, n - 1))
  local heights = {}
  local flex = {}
  local used = 0
  for i, child in ipairs(children) do
    local fixed = map_ui_get_h(child)
    if type(fixed) == "number" and fixed > 0 then
      heights[i] = math.max(map_ui_min_h(child), fixed)
      used = used + heights[i]
    elseif map_ui_is_flex_h(child) then
      flex[#flex + 1] = i
      heights[i] = 0
    else
      heights[i] = map_ui_pref_h(child)
      used = used + heights[i]
    end
  end
  local leftover = inner - used
  if #flex == 0 then
    local mins = {}
    for i, child in ipairs(children) do
      mins[i] = map_ui_min_h(child)
    end
    return map_ui_fit_sizes(heights, mins, inner)
  end
  local each = leftover / #flex
  for _, i in ipairs(flex) do
    heights[i] = math.max(map_ui_min_h(children[i]), each)
  end
  local mins = {}
  for i, child in ipairs(children) do
    mins[i] = map_ui_min_h(child)
  end
  return map_ui_fit_sizes(heights, mins, inner)
end

function map_ui_row_widths(children, total)
  local n = #children
  local inner = math.max(0, total - MAP_UI_GAP * math.max(0, n - 1))
  local widths = {}
  local flex = {}
  local used = 0
  for i, child in ipairs(children) do
    local sized = map_ui_get_w(child)
    if (not sized or sized <= 0) and child.type == "leaf" and child.id == "tracks" then
      child.w = state.seq_panel_width or 240
      sized = child.w
    end
    if type(sized) == "number" and sized > 0 then
      widths[i] = sized
      used = used + sized
    else
      flex[#flex + 1] = i
      widths[i] = 0
    end
  end
  if #flex == 0 then
    local mins = {}
    for i, child in ipairs(children) do
      mins[i] = map_ui_min_w(child)
    end
    return map_ui_fit_sizes(widths, mins, inner)
  end
  local leftover = math.max(0, inner - used)
  local each = leftover / #flex
  for _, i in ipairs(flex) do
    widths[i] = math.max(map_ui_min_w(children[i]), each)
  end
  local mins = {}
  for i, child in ipairs(children) do
    mins[i] = map_ui_min_w(child)
  end
  return map_ui_fit_sizes(widths, mins, inner)
end

function map_ui_leaf_flags(spec)
  local win_flags = 0
  if r.ImGui_WindowFlags_NoNav then
    win_flags = r.ImGui_WindowFlags_NoNav()
  end
  if not spec.scroll then
    win_flags = win_flags | r.ImGui_WindowFlags_NoScrollbar() | r.ImGui_WindowFlags_NoScrollWithMouse()
  end
  return win_flags
end

function map_ui_commit_rect(x, y, w, h)
  r.ImGui_SetCursorScreenPos(ctx, x + math.max(0, w), y + math.max(0, h))
  r.ImGui_Dummy(ctx, 0, 0)
end

MAP_UI_LABELS = {
  tracks = "Tracks",
  tabs = "Tabs",
  path = "Path",
  wave = "Waveform",
  map = "Sample Map",
}

function map_ui_edge_target(id, edge)
  local info = state.map_ui_leaf_info and state.map_ui_leaf_info[id]
  if not info then
    return nil
  end
  if edge == "left" or edge == "right" then
    local row = info.row
    if not row or type(row.node) ~= "table" then
      return nil
    end
    local node = row.node
    local i = row.index
    if edge == "right" then
      local child = node.children[i]
      return { node = node, index = i, axis = "w", sign = 1, size0 = child._alloc_w or map_ui_get_w(child) or info.w }
    end
    if i > 1 then
      local child = node.children[i - 1]
      return { node = node, index = i - 1, axis = "w", sign = 1, size0 = child._alloc_w or map_ui_get_w(child) or 0 }
    end
    local child = node.children[i]
    return { node = node, index = i, axis = "w", sign = -1, size0 = child._alloc_w or info.w }
  end
  local col = info.col
  if not col or type(col.node) ~= "table" then
    return nil
  end
  local node = col.node
  local i = col.index
  if edge == "bottom" then
    local child = node.children[i]
    return { node = node, index = i, axis = "h", sign = 1, size0 = child._alloc_h or map_ui_get_h(child) or info.h }
  end
  if i > 1 then
    local child = node.children[i - 1]
    return { node = node, index = i - 1, axis = "h", sign = 1, size0 = child._alloc_h or map_ui_get_h(child) or 0 }
  end
  local child = node.children[i]
  return { node = node, index = i, axis = "h", sign = -1, size0 = child._alloc_h or info.h }
end

function map_ui_handle_edge(id, edge)
  if not state.map_ui_edit or state.map_ui_drag then
    return
  end
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  if (hovered or active) and r.ImGui_SetMouseCursor then
    if edge == "left" or edge == "right" then
      if r.ImGui_MouseCursor_ResizeEW then
        r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeEW())
      end
    elseif r.ImGui_MouseCursor_ResizeNS then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeNS())
    end
  end
  local key = tostring(id) .. "_" .. edge
  local mx, my = r.ImGui_GetMousePos(ctx)
  if active then
    if not state.map_ui_split_drag or state.map_ui_split_drag.key ~= key then
      local target = map_ui_edge_target(id, edge)
      if not target then
        return
      end
      state.map_ui_split_drag = {
        key = key,
        node = target.node,
        index = target.index,
        axis = target.axis,
        sign = target.sign,
        start = target.axis == "w" and mx or my,
        size0 = target.size0,
      }
    else
      local drag = state.map_ui_split_drag
      local child = drag.node.children[drag.index]
      if not child then
        return
      end
      local pos = drag.axis == "w" and mx or my
      local minv = drag.axis == "w" and map_ui_min_w(child) or map_ui_min_h(child)
      local newv = math.max(minv, drag.size0 + drag.sign * (pos - drag.start))
      local host = state.sample_map_window_rect or state.main_window_rect
      if drag.axis == "w" then
        local maxv = math.max(minv + 40, ((host and host.w) or 900) - 120)
        newv = math.min(maxv, newv)
        child.w = newv
        child.size = nil
        if child.type == "leaf" and child.id == "tracks" then
          state.seq_panel_width = newv
        end
      else
        local maxv = math.max(minv + 24, ((host and host.h) or 700) - 80)
        newv = math.min(maxv, newv)
        child.h = newv
      end
    end
  elseif state.map_ui_split_drag and state.map_ui_split_drag.key == key
      and r.ImGui_IsMouseReleased and r.ImGui_IsMouseReleased(ctx, 0) then
    state.map_ui_split_drag = nil
    save_config()
  end
end

function map_ui_edit_overlay(id, w, h)
  if not state.map_ui_edit then
    return
  end
  local wx, wy = r.ImGui_GetWindowPos(ctx)
  local ww = math.max(1, w or select(1, r.ImGui_GetWindowSize(ctx)) or 1)
  local wh = math.max(1, h or select(2, r.ImGui_GetWindowSize(ctx)) or 1)
  local flags = map_ui_leaf_flags({ scroll = false })
  r.ImGui_SetCursorScreenPos(ctx, wx, wy)
  local open = r.ImGui_BeginChild(ctx, "map_ui_edit_" .. id, ww, wh, 0, flags)
  if open then
    local dl = r.ImGui_GetWindowDrawList(ctx)
    r.ImGui_DrawList_AddRectFilled(dl, wx, wy, wx + ww, wy + wh, 0x1EFF5E22, 4)
    r.ImGui_DrawList_AddRect(dl, wx + 0.5, wy + 0.5, wx + ww - 0.5, wy + wh - 0.5, UI_THEME.accent, 4, 0, 1.6)
    local label = MAP_UI_LABELS[id] or id
    r.ImGui_DrawList_AddText(dl, wx + 8, wy + 6, 0xF2F6FAFF, label)

    local t = MAP_UI_EDGE
    r.ImGui_SetCursorScreenPos(ctx, wx, wy)
    r.ImGui_InvisibleButton(ctx, "##map_ui_e_l_" .. id, t, wh)
    map_ui_handle_edge(id, "left")
    r.ImGui_SetCursorScreenPos(ctx, wx + ww - t, wy)
    r.ImGui_InvisibleButton(ctx, "##map_ui_e_r_" .. id, t, wh)
    map_ui_handle_edge(id, "right")
    r.ImGui_SetCursorScreenPos(ctx, wx, wy)
    r.ImGui_InvisibleButton(ctx, "##map_ui_e_t_" .. id, ww, t)
    map_ui_handle_edge(id, "top")
    r.ImGui_SetCursorScreenPos(ctx, wx, wy + wh - t)
    r.ImGui_InvisibleButton(ctx, "##map_ui_e_b_" .. id, ww, t)
    map_ui_handle_edge(id, "bottom")

    r.ImGui_SetCursorScreenPos(ctx, wx + t, wy + t)
    r.ImGui_InvisibleButton(ctx, "##map_ui_move_" .. id, math.max(1, ww - t * 2), math.max(1, wh - t * 2))
    map_ui_consider_drag(id)
    if r.ImGui_IsItemHovered(ctx) and not state.map_ui_split_drag and r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, "Drag to move. Drag edges to resize.\nDouble-click to reset layout.")
    end
    r.ImGui_Dummy(ctx, 0, 0)
  end
  imgui_end_child(open)
end

function map_ui_render_leaf(id, w, h)
  local spec = MAP_UI_SPEC[id]
  if not spec then
    return
  end
  local win_flags = map_ui_leaf_flags(spec)
  local open = r.ImGui_BeginChild(ctx, "map_ui_" .. id, math.max(1, w), math.max(1, h), 0, win_flags)
  if open then
    if id == "tracks" then
      render_seq_tracks_panel()
    elseif id == "tabs" then
      render_sample_map_tab_bar()
    elseif id == "path" then
      render_sample_path_line()
    elseif id == "wave" then
      render_waveform()
    elseif id == "map" then
      render_swap_mode_bar()
      local _, remain_y = r.ImGui_GetContentRegionAvail(ctx)
      local map_flags = map_ui_leaf_flags({ scroll = false })
      if r.ImGui_BeginChild(ctx, "sample_map_area", 0, math.max(0, remain_y), 0, map_flags) then
        render_map()
        r.ImGui_EndChild(ctx)
      end
    end
    local wx, wy = r.ImGui_GetWindowPos(ctx)
    local ww, wh = r.ImGui_GetWindowSize(ctx)
    state.map_ui_rects[id] = { x0 = wx, y0 = wy, x1 = wx + ww, y1 = wy + wh }
    map_ui_edit_overlay(id, ww, wh)
    r.ImGui_Dummy(ctx, 0, 0)
  end
  imgui_end_child(open)
end

function map_ui_render_node(node, w, h, path, row_ctx, col_ctx)
  if type(node) ~= "table" or w < 1 or h < 1 then
    return
  end
  local x, y = r.ImGui_GetCursorScreenPos(ctx)
  if node.type == "leaf" then
    state.map_ui_leaf_info[node.id] = {
      row = row_ctx,
      col = col_ctx,
      w = w,
      h = h,
    }
    map_ui_render_leaf(node.id, w, h)
    map_ui_commit_rect(x, y, w, h)
    return
  end
  if node.type == "row" then
    local widths = map_ui_row_widths(node.children or {}, w)
    local cx = x
    for i, child in ipairs(node.children or {}) do
      child._alloc_w = widths[i]
      child._alloc_h = h
      r.ImGui_SetCursorScreenPos(ctx, cx, y)
      map_ui_render_node(child, widths[i], h, path .. "r" .. i, { node = node, index = i, alloc = widths[i] }, col_ctx)
      cx = cx + widths[i]
      if i < #node.children then
        cx = cx + MAP_UI_GAP
      end
    end
  else
    local heights = map_ui_col_heights(node.children or {}, h)
    local cy = y
    for i, child in ipairs(node.children or {}) do
      child._alloc_w = w
      child._alloc_h = heights[i]
      r.ImGui_SetCursorScreenPos(ctx, x, cy)
      map_ui_render_node(child, w, heights[i], path .. "c" .. i, row_ctx, { node = node, index = i, alloc = heights[i] })
      cy = cy + heights[i]
      if i < #node.children then
        cy = cy + MAP_UI_GAP
      end
    end
  end
  map_ui_commit_rect(x, y, w, h)
end

function map_ui_update_drop()
  state.map_ui_drop = nil
  local drag = state.map_ui_drag
  if not drag then
    return
  end
  local mx, my = r.ImGui_GetMousePos(ctx)
  for id, rect in pairs(state.map_ui_rects) do
    if id ~= drag.id and mx >= rect.x0 and mx <= rect.x1 and my >= rect.y0 and my <= rect.y1 then
      local rw = math.max(1, rect.x1 - rect.x0)
      local rh = math.max(1, rect.y1 - rect.y0)
      local rel_x = (mx - rect.x0) / rw
      local rel_y = (my - rect.y0) / rh
      local edge
      if math.min(rel_x, 1 - rel_x) < math.min(rel_y, 1 - rel_y) then
        edge = rel_x < 0.5 and "left" or "right"
      else
        edge = rel_y < 0.5 and "top" or "bottom"
      end
      state.map_ui_drop = { id = id, edge = edge }
    end
  end
end

function map_ui_draw_drop_preview()
  local drop = state.map_ui_drop
  if not drop then
    return
  end
  local rect = state.map_ui_rects[drop.id]
  if not rect then
    return
  end
  local dl = r.ImGui_GetWindowDrawList(ctx)
  if r.ImGui_GetForegroundDrawList then
    dl = r.ImGui_GetForegroundDrawList(ctx)
  end
  local x0, y0, x1, y1 = rect.x0, rect.y0, rect.x1, rect.y1
  local t = 0.38
  local hx0, hy0, hx1, hy1 = x0, y0, x1, y1
  if drop.edge == "left" then
    hx1 = x0 + (x1 - x0) * t
  elseif drop.edge == "right" then
    hx0 = x1 - (x1 - x0) * t
  elseif drop.edge == "top" then
    hy1 = y0 + (y1 - y0) * t
  else
    hy0 = y1 - (y1 - y0) * t
  end
  r.ImGui_DrawList_AddRectFilled(dl, hx0, hy0, hx1, hy1, 0x1EFF5E55, 4)
  r.ImGui_DrawList_AddRect(dl, hx0, hy0, hx1, hy1, UI_THEME.accent, 4, 0, 2)
end

function map_ui_finish_drag()
  if not state.map_ui_drag then
    return
  end
  if r.ImGui_SetMouseCursor then
    local cursor = r.ImGui_MouseCursor_ResizeAll and r.ImGui_MouseCursor_ResizeAll() or r.ImGui_MouseCursor_Hand()
    r.ImGui_SetMouseCursor(ctx, cursor)
  end
  if r.ImGui_IsMouseReleased and r.ImGui_IsMouseReleased(ctx, 0) then
    if state.map_ui_drop then
      map_ui_dock(state.map_ui_drag.id, state.map_ui_drop.id, state.map_ui_drop.edge)
      save_config()
    end
    state.map_ui_drag = nil
    state.map_ui_drop = nil
  end
end

function render_sample_map_body()
  state.map_ui_rects = {}
  state.map_ui_leaf_info = {}
  map_ui_ensure_layout()

  local origin_x, origin_y = r.ImGui_GetCursorScreenPos(ctx)
  local avail_x, tab_avail_y = r.ImGui_GetContentRegionAvail(ctx)
  tab_avail_y = math.max(0, tab_avail_y)
  local dock_explorer = explorer_is_docked_in("sample_map")
  local split_w = dock_explorer and EXPLORER_SPLIT_W or 0
  local explorer_w = dock_explorer and explorer_dock_width() or 0
  local layout_w = avail_x
  if dock_explorer then
    layout_w = math.max(180, avail_x - explorer_w - split_w)
  end
  map_ui_render_node(state.map_ui_layout, layout_w, tab_avail_y, "root")
  if state.map_ui_edit then
    map_ui_update_drop()
    map_ui_draw_drop_preview()
    map_ui_finish_drag()
  else
    state.map_ui_drag = nil
    state.map_ui_drop = nil
    state.map_ui_split_drag = nil
  end
  local total_w = layout_w
  if dock_explorer then
    r.ImGui_SetCursorScreenPos(ctx, origin_x + layout_w, origin_y)
    explorer_draw_dock_splitter("sample_map", tab_avail_y, avail_x)
    r.ImGui_SetCursorScreenPos(ctx, origin_x + layout_w + split_w, origin_y)
    render_explorer_docked_panel(tab_avail_y)
    total_w = layout_w + split_w + explorer_w
  end
  map_ui_commit_rect(origin_x, origin_y, total_w, tab_avail_y)
  seq_render_env_editor_host()
end

function begin_view_float_window(title, id, default_w, default_h, ox, oy)
  local wr = state.main_window_rect
  r.ImGui_SetNextWindowSize(ctx, default_w, default_h, r.ImGui_Cond_FirstUseEver())
  if wr and r.ImGui_SetNextWindowPos then
    r.ImGui_SetNextWindowPos(ctx, (wr.x or 0) + (ox or 48), (wr.y or 0) + (oy or 64), r.ImGui_Cond_FirstUseEver())
  end
  if r.ImGui_SetNextWindowSizeConstraints then
    r.ImGui_SetNextWindowSizeConstraints(ctx, 520, 360, 4000, 3000)
  end
  local flags = 0
  if r.ImGui_WindowFlags_NoCollapse then
    flags = flags | r.ImGui_WindowFlags_NoCollapse()
  end
  if r.ImGui_WindowFlags_NoDocking then
    flags = flags | r.ImGui_WindowFlags_NoDocking()
  end
  if r.ImGui_WindowFlags_NoScrollbar then
    flags = flags | r.ImGui_WindowFlags_NoScrollbar()
  end
  if r.ImGui_WindowFlags_NoScrollWithMouse then
    flags = flags | r.ImGui_WindowFlags_NoScrollWithMouse()
  end
  if r.ImGui_WindowFlags_NoNav then
    flags = flags | r.ImGui_WindowFlags_NoNav()
  end
  local ok, visible, open = pcall(r.ImGui_Begin, ctx, title .. "###" .. id, true, flags)
  if not ok then
    return false, true, false
  end
  if open == nil then
    open = true
  end
  return visible and true or false, open, true
end

