function render_filter_input()
  local function draw_search_icon(dl, x, y, height, color)
    local size = math.min(height - 4, 16)
    local lens_r = size * 0.32
    local cx = x + size * 0.45
    local cy = y + height * 0.5
    r.ImGui_DrawList_AddCircle(dl, cx, cy, lens_r, color, 16, 1.4)
    local hx = cx + lens_r * 0.62
    local hy = cy + lens_r * 0.62
    r.ImGui_DrawList_AddLine(dl, hx, hy, hx + size * 0.30, hy + size * 0.30, color, 1.6)
  end

  local function collect_active_tags_in_display_order()
    local ordered = {}
    if not state.active_tags or next(state.active_tags) == nil then
      return ordered
    end

    for tag, active in pairs(state.active_tags) do
      if active then
        ordered[#ordered + 1] = tag
      end
    end

    table.sort(ordered, function(a, b)
      return string.lower(a) < string.lower(b)
    end)

    return ordered
  end

  local function calc_tag_button_width(label)
    local text_w = r.ImGui_CalcTextSize(ctx, label)
    local frame_padding = {r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())}
    return text_w + (frame_padding[1] or 4) * 2
  end

  local function calc_compact_button_width(label)
    local text_w = r.ImGui_CalcTextSize(ctx, label)
    local frame_padding = {r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())}
    return text_w + ((frame_padding[1] or 4) * 0.65) * 2
  end

  local avail_x = r.ImGui_GetContentRegionAvail(ctx)
  local loop_reserve = 132
  local filter_height = 26
  local icon_pad = 22
  local right_pad = 6
  local min_input_width = 72
  local spacing = 4
  local input_target
  if avail_x > 300 then
    input_target = math.max(180, math.min(280, avail_x - loop_reserve))
  else
    input_target = math.max(140, math.min(280, avail_x - 8))
  end
  local max_bar = avail_x > 300 and math.max(140, avail_x - loop_reserve) or math.max(140, avail_x - 8)
  local all_active_tags = collect_active_tags_in_display_order()
  local has_active_tags = #all_active_tags > 0
  local active_tags = {}
  for _, tag in ipairs(all_active_tags) do
    if not should_hide_active_tag_in_search_bar(tag) then
      active_tags[#active_tags + 1] = tag
    end
  end
  local clear_label = "Clear"
  local clear_width = has_active_tags and calc_compact_button_width(clear_label) or 0

  local function tags_block_width(tags)
    local w = 0
    for i, tag in ipairs(tags) do
      if i > 1 then
        w = w + spacing
      end
      w = w + calc_tag_button_width(tag)
    end
    return w
  end

  local function trailing_width(tags_w)
    local w = 0
    if tags_w > 0 then
      w = w + spacing + tags_w
    end
    if has_active_tags then
      w = w + spacing + clear_width
    end
    return w
  end

  local desired_tags_w = tags_block_width(active_tags)
  local desired = icon_pad + input_target + trailing_width(desired_tags_w) + right_pad
  local filter_width = math.min(desired, max_bar)
  local tag_budget = filter_width - icon_pad - min_input_width - right_pad
  if has_active_tags then
    tag_budget = tag_budget - spacing - clear_width
  end
  tag_budget = math.max(0, tag_budget)

  local visible_tags = {}
  local used_width = 0
  for _, tag in ipairs(active_tags) do
    local tag_width = calc_tag_button_width(tag)
    local extra_spacing = (#visible_tags > 0) and spacing or 0
    if used_width + extra_spacing + tag_width <= tag_budget then
      visible_tags[#visible_tags + 1] = tag
      used_width = used_width + extra_spacing + tag_width
    else
      break
    end
  end

  local hidden_count = #active_tags - #visible_tags
  if hidden_count > 0 then
    local hidden_label = "+" .. tostring(hidden_count)
    local hidden_width = calc_tag_button_width(hidden_label)
    local extra_spacing = (#visible_tags > 0) and spacing or 0
    while #visible_tags > 0 and used_width + extra_spacing + hidden_width > tag_budget do
      local removed = table.remove(visible_tags)
      used_width = used_width - calc_tag_button_width(removed)
      if #visible_tags > 0 then
        used_width = used_width - spacing
      end
      hidden_count = hidden_count + 1
      hidden_label = "+" .. tostring(hidden_count)
      hidden_width = calc_tag_button_width(hidden_label)
      extra_spacing = (#visible_tags > 0) and spacing or 0
    end
    if used_width + extra_spacing + hidden_width <= tag_budget then
      visible_tags[#visible_tags + 1] = hidden_label
      used_width = used_width + extra_spacing + hidden_width
    end
  end

  filter_width = math.min(max_bar, icon_pad + math.max(min_input_width, input_target) + trailing_width(used_width) + right_pad)
  local input_width = math.max(min_input_width, filter_width - icon_pad - trailing_width(used_width) - right_pad)

  local child_flags = 0
  if r.ImGui_ChildFlags_Border then
    child_flags = r.ImGui_ChildFlags_Border
  end
  local child_window_flags = r.ImGui_WindowFlags_NoScrollbar() | r.ImGui_WindowFlags_NoScrollWithMouse()

  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), 0, 0)
  if r.ImGui_BeginChild(ctx, "sample_filter_field", filter_width, filter_height, 0, child_window_flags) then
    local dl = r.ImGui_GetWindowDrawList(ctx)
    local x0, y0 = r.ImGui_GetWindowPos(ctx)
    local hovered_field = r.ImGui_IsWindowHovered(ctx)
    ui_draw_panel(
      dl, x0, y0, x0 + filter_width, y0 + filter_height, filter_height * 0.5,
      hovered_field and UI_THEME.surface_hvr or UI_THEME.surface,
      hovered_field and UI_THEME.border_hvr or UI_THEME.border,
      hovered_field, false
    )
    draw_search_icon(dl, x0 + 6, y0 + 3, filter_height - 6, hovered_field and UI_THEME.text_dim or UI_THEME.text_mute)

    r.ImGui_SetCursorPosX(ctx, icon_pad)
    r.ImGui_SetCursorPosY(ctx, 3)
    r.ImGui_SetNextItemWidth(ctx, input_width)
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBg(), 0x00000000)
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgHovered(), 0x00000000)
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgActive(), 0x00000000)
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Border(), 0x00000000)

    local ret, input
    if r.ImGui_InputTextWithHint then
      ret, input = r.ImGui_InputTextWithHint(
        ctx, "##sample_filter",
        has_active_tags and "Type to refine..." or "Search samples...",
        state.filter or ""
      )
    else
      ret, input = r.ImGui_InputText(ctx, "##sample_filter", state.filter or "", 256)
    end
    seq_mark_text_input_item()
    r.ImGui_PopStyleColor(ctx, 4)

    if ret or input ~= nil then
      state.filter = input or ""
    end
    local input_active = (r.ImGui_IsItemActive and r.ImGui_IsItemActive(ctx))
      or (r.ImGui_IsItemDeactivated and r.ImGui_IsItemDeactivated(ctx))
      or (r.ImGui_IsItemFocused and r.ImGui_IsItemFocused(ctx))
    local input_hovered = r.ImGui_IsItemHovered(ctx)

    for _, tag in ipairs(visible_tags) do
      r.ImGui_SameLine(ctx, 0, spacing)
      if tag:sub(1, 1) == "+" then
        draw_tag_button(ctx, tag, false, "__hidden_tags__", "filter_active_", { allow_delete = false })
      else
        if draw_tag_button(ctx, tag, true, tag, "filter_active_") then
          state.active_tags[tag] = nil
        end
      end
    end

    if has_active_tags then
      r.ImGui_SameLine(ctx, 0, spacing)
      if draw_ui_button("filter_clear_active_tags", clear_label, nil, nil, { compact = true, style = "danger" }) then
        state.active_tags = {}
        state.selected_tag_parents = {}
      end
    end

    local enter_pressed = false
    if r.ImGui_IsKeyPressed and r.ImGui_Key_Enter
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Enter(), false) then
      enter_pressed = true
    elseif r.ImGui_IsKeyPressed and r.ImGui_Key_KeypadEnter
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_KeypadEnter(), false) then
      enter_pressed = true
    end
    if enter_pressed and input_active then
      preview_random_filtered_sample()
    end
    if input_hovered then
      r.ImGui_SetTooltip(ctx, "Matches file names and folder paths.\nPress Enter to play a random result.")
    end

    r.ImGui_EndChild(ctx)
  end
  r.ImGui_PopStyleVar(ctx)
end

function render_header()
  if not r.ImGui_BeginMenuBar(ctx) then
    return
  end

  if r.ImGui_BeginMenu(ctx, "Library") then
    if state.scan_running then
      if r.ImGui_MenuItem(ctx, "Stop Scan") then
        stop_scan()
      end
      if r.ImGui_IsItemHovered(ctx) then
        r.ImGui_SetTooltip(ctx, "Stop scanning and save progress.\nThe next scan will continue from here — you won't start over.")
      end
    else
      if r.ImGui_MenuItem(ctx, "Rescan") then
        start_scan()
      end
      if r.ImGui_IsItemHovered(ctx) then
        if #state.scan_queue > 0 then
          r.ImGui_SetTooltip(ctx, string.format(
            "Continue the unfinished scan (%d file(s) left).\nAlready indexed samples are kept.",
            #state.scan_queue
          ))
        else
          r.ImGui_SetTooltip(ctx, "Scan folders for new files.\nAlready indexed samples are skipped.")
        end
      end
    end
    if r.ImGui_MenuItem(ctx, "Scan for Incomplete") then
      enqueue_incomplete_analysis()
    end
    if r.ImGui_MenuItem(ctx, "Scan for Effective Range") then
      enqueue_effective_range_analysis()
    end
    if r.ImGui_MenuItem(ctx, "Scan for Transient/Sustain") then
      enqueue_transient_sustain_analysis()
    end
    if r.ImGui_MenuItem(ctx, "Scan for Loop / One-shot") then
      enqueue_playback_type_analysis()
    end
    if r.ImGui_MenuItem(ctx, "Scan for Weight") then
      enqueue_weight_analysis()
    end
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, "Recompute weight only (skips crop, loop/one-shot, and transients).\nUse this after the weight formula changes.")
    end
    r.ImGui_Separator(ctx)
    if r.ImGui_MenuItem(ctx, "File Explorer", nil, state.explorer_open) then
      state.explorer_open = not state.explorer_open
      save_config()
    end
    r.ImGui_Separator(ctx)
    if r.ImGui_MenuItem(ctx, "Clear All Folders and Samples") then
      state.folders = {}
      filter_samples_by_folders()  -- This will clear samples and tag data
      state.scan_queue = {}
      state.scan_running = false
      state.scan_started = 0
      clear_sample_cache()
      save_config()
      log("Cleared folders and samples")
    end
    r.ImGui_EndMenu(ctx)
  end

  if r.ImGui_BeginMenu(ctx, "Tools") then
    if r.ImGui_MenuItem(ctx, "Copy Scan Logs") then
      local logs_text = get_scan_logs_text()
      if logs_text and logs_text ~= "" then
        r.ImGui_SetClipboardText(ctx, logs_text)
        log("Scan logs copied to clipboard (" .. tostring(#state.scan_logs) .. " entries)")
      else
        log("No scan logs to copy")
      end
    end
    if r.ImGui_MenuItem(ctx, "Debug Sample Coordinates") then
      log("=== DEBUG: Sample Coordinates ===")
      log("Total samples: " .. #state.samples)
      if #state.samples > 0 then
        local x_min, x_max = state.samples[1].x or 0.5, state.samples[1].x or 0.5
        local y_min, y_max = state.samples[1].y or 0.5, state.samples[1].y or 0.5
        local freq_min, freq_max = state.samples[1].dominant_freq or 440.0, state.samples[1].dominant_freq or 440.0
        local rms_min, rms_max = state.samples[1].rms_energy or 0.0, state.samples[1].rms_energy or 0.0
        local size_min, size_max = state.samples[1].file_size or 0, state.samples[1].file_size or 0
        for i, s in ipairs(state.samples) do
          local x = s.x or 0.5
          local y = s.y or 0.5
          local freq = s.dominant_freq or 440.0
          local rms = s.rms_energy or 0.0
          local size = s.file_size or 0
          log(string.format("Sample %d: name='%s', freq=%.1f Hz, bright=%.1f, weight=%.2f, rms=%.6f, size=%d bytes, x=%.6f, y=%.6f",
              i, s.name or "unknown", freq, s.brightness or 0, s.sub_weight or 0, rms, size, x, y))
          x_min = math.min(x_min, x)
          x_max = math.max(x_max, x)
          y_min = math.min(y_min, y)
          y_max = math.max(y_max, y)
          freq_min = math.min(freq_min, freq)
          freq_max = math.max(freq_max, freq)
          rms_min = math.min(rms_min, rms)
          rms_max = math.max(rms_max, rms)
          size_min = math.min(size_min, size)
          size_max = math.max(size_max, size)
        end
        log("--- Summary ---")
        log(string.format("X range: %.6f to %.6f (span: %.6f)", x_min, x_max, x_max - x_min))
        log(string.format("Y range: %.6f to %.6f (span: %.6f)", y_min, y_max, y_max - y_min))
        log(string.format("Frequency range: %.1f Hz to %.1f Hz", freq_min, freq_max))
        log(string.format("RMS range: %.6f to %.6f", rms_min, rms_max))
        log(string.format("File size range: %d to %d bytes", size_min, size_max))
      else
        log("No samples to debug")
      end
      log("=== End Debug ===")
    end
    r.ImGui_EndMenu(ctx)
  end

  if r.ImGui_BeginMenu(ctx, "View") then
    if r.ImGui_BeginMenu(ctx, "Collapse Children Tags") then
      local mode = state.collapse_children_tags or "off"
      if r.ImGui_MenuItem(ctx, "Off", nil, mode == "off") then
        set_collapse_children_tags_mode("off")
      end
      if r.ImGui_MenuItem(ctx, "On", nil, mode == "on") then
        set_collapse_children_tags_mode("on")
      end
      if r.ImGui_MenuItem(ctx, "Dynamic", nil, mode == "dynamic") then
        set_collapse_children_tags_mode("dynamic")
      end
      if r.ImGui_IsItemHovered(ctx) then
        local threshold = state.collapse_children_tags_width or 1100
        r.ImGui_SetTooltip(ctx, string.format(
          "On when the window is %.0f px wide or narrower.\nChange this width in Settings.",
          threshold
        ))
      end
      r.ImGui_EndMenu(ctx)
    end
    r.ImGui_EndMenu(ctx)
  end

  if r.ImGui_MenuItem(ctx, "Settings", nil, state.settings_open) then
    state.settings_open = not state.settings_open
  end

  if SampleMapUpdateState and SampleMapUpdateState.show_update_icon then
    r.ImGui_SameLine(ctx)
    local update_img = get_vfx_icon and get_vfx_icon("Update")
    local clicked = false
    if update_img and r.ImGui_ImageButton then
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Button(), 0x00000000)
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_ButtonHovered(), 0xFFFFFF22)
      r.ImGui_PushStyleColor(ctx, r.ImGui_Col_ButtonActive(), 0xFFFFFF18)
      local ok_img, img_clicked = pcall(r.ImGui_ImageButton, ctx, "##sample_map_update_icon", update_img, 16, 16)
      r.ImGui_PopStyleColor(ctx, 3)
      clicked = ok_img and img_clicked
    elseif r.ImGui_MenuItem(ctx, "Update") then
      clicked = true
    end
    if r.ImGui_IsItemHovered(ctx) then
      local latest = SampleMapUpdateState.latest_release_tag or "new version"
      r.ImGui_SetTooltip(ctx, "Update available: " .. tostring(latest) .. "\nOpen Settings → Updates")
    end
    if clicked and SampleMapOpenUpdateSettings then
      SampleMapOpenUpdateSettings()
    end
  end

  local midi_h = 18
  local midi_w = seq_midi_arm_button_width(midi_h)
  local knob_sz = 16
  local knob_gap = 8
  local right_w = knob_sz + knob_gap + midi_w
  local remain = r.ImGui_GetContentRegionAvail(ctx)
  if type(remain) == "number" and remain > right_w + 16 then
    r.ImGui_SameLine(ctx)
    r.ImGui_Dummy(ctx, remain - right_w - 10, 1)
  end
  r.ImGui_SameLine(ctx)
  draw_preview_volume_knob(knob_sz)
  r.ImGui_SameLine(ctx, 0, knob_gap)
  render_seq_midi_arm_icon_button("seq_midi_arm_menubar", midi_h)

  r.ImGui_EndMenuBar(ctx)
end


function settings_search_query()
  local q = tostring(state.settings_search or "")
  q = string.lower((string.match(q, "^%s*(.-)%s*$")) or "")
  return q
end

function settings_search_active()
  return settings_search_query() ~= ""
end

function settings_matches(...)
  local q = settings_search_query()
  if q == "" then
    return true
  end
  local n = select("#", ...)
  local i
  for i = 1, n do
    local s = select(i, ...)
    if type(s) == "string" and s ~= "" then
      if string.find(string.lower(s), q, 1, true) then
        return true
      end
    end
  end
  return false
end

function settings_show(...)
  if not settings_search_active() then
    return true
  end
  if state.settings_filter_section_title_hit then
    return true
  end
  return settings_matches(...)
end

function settings_section_should_show(label)
  if not settings_search_active() then
    return true
  end
  if settings_matches(label) then
    return true
  end
  if label == "Scan Folders" then
    if settings_matches("Add Folder", "Rescan", "Browse", "Remove", "scan", "offline") then
      return true
    end
    local i
    for i = 1, #(state.folders or {}) do
      if settings_matches(state.folders[i]) then
        return true
      end
    end
    return false
  end
  if label == "Map" then
    return settings_matches(
      "Y axis", "Brightness", "Dominant frequency", "Weight",
      "Spectral centroid", "audible length", "pitch", "subby", "heavy"
    )
  end
  if label == "Dot Appearance" then
    return settings_matches(
      "Dot Radius", "Outline Size", "Outline Thickness",
      "Detection Size Multiplier", "Dot Color", "Outline Color", "Hover Color"
    )
  end
  if label == "Tag Layout" then
    return settings_matches(
      "Collapse children tags", "Drum", "Melodic", "Genre", "Library",
      "Off", "On", "Dynamic", "Window width", "threshold"
    )
  end
  if label == "Tag Colors" then
    if settings_matches("Presets", "Load Preset", "Save as Preset", "preset") then
      return true
    end
    local tag
    for tag in pairs(state.tag_colors or {}) do
      if settings_matches(tag) then
        return true
      end
    end
    return false
  end
  if label == "Sequencer Controls" then
    if settings_matches(
      "Track folder", "Group sequencer tracks in a folder",
      "Follow hovered notes in the arrange",
      "Show numbers on sample candidate slots",
      "Region item image", "Mouse wheel scrolling",
      "Mouse modifiers", "Reset to defaults", "TCP"
    ) then
      return true
    end
    local i
    for i = 1, #(SEQ_PARENT_IMAGE_STYLES or {}) do
      local style = SEQ_PARENT_IMAGE_STYLES[i]
      if style and settings_matches(style.label, style.id) then
        return true
      end
    end
    if settings_matches(
      "Vertical wheel scrolls the timeline",
      "Vertical wheel scrolls tracks", "classic", "natural", "trackpad"
    ) then
      return true
    end
    for i = 1, #(MOUSE_MOD_ACTIONS or {}) do
      local action = MOUSE_MOD_ACTIONS[i]
      if action and settings_matches(action.label, action.hint, action.id) then
        return true
      end
    end
    return settings_matches("Shift", "Alt", "Ctrl", "Cmd", "None")
  end
  if label == "Keyboard Shortcuts" then
    if settings_matches("Reset to defaults", "shortcut", "hotkey") then
      return true
    end
    local i
    for i = 1, #(KEYBOARD_SHORTCUT_ACTIONS or {}) do
      local action = KEYBOARD_SHORTCUT_ACTIONS[i]
      if action and settings_matches(
        action.label, action.hint, action.group, action.id,
        shortcut_display(action.id)
      ) then
        return true
      end
    end
    return false
  end
  if label == "Updates" then
    return settings_matches(
      "Update", "GitHub", "Download", "version", "Check for updates", "install"
    )
  end
  return false
end

function settings_render_search()
  local avail = r.ImGui_GetContentRegionAvail(ctx)
  local query = state.settings_search or ""
  local show_clear = query ~= ""
  local clear_w = 24
  local input_w = avail
  if show_clear then
    input_w = math.max(80, avail - clear_w - 8)
  end
  if r.ImGui_IsWindowAppearing and r.ImGui_IsWindowAppearing(ctx) and r.ImGui_SetKeyboardFocusHere then
    r.ImGui_SetKeyboardFocusHere(ctx)
  end
  r.ImGui_SetNextItemWidth(ctx, input_w)
  local changed, text
  if r.ImGui_InputTextWithHint then
    changed, text = r.ImGui_InputTextWithHint(ctx, "##settings_search", "Search settings…", query)
  else
    changed, text = r.ImGui_InputText(ctx, "##settings_search", query, 256)
  end
  seq_mark_text_input_item()
  if changed then
    state.settings_search = text or ""
  end
  local active = r.ImGui_IsItemActive and r.ImGui_IsItemActive(ctx)
  if active and query ~= "" and r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
      and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false) then
    state.settings_search = ""
  end
  if show_clear then
    r.ImGui_SameLine(ctx, 0, 6)
    if draw_ui_button("settings_search_clear", nil, clear_w, 24, { icon = "close", compact = true }) then
      state.settings_search = ""
    end
  end
end

function settings_section(label, default_open)
  state.settings_section_open = state.settings_section_open or {}
  if state.settings_section_open[label] == nil then
    state.settings_section_open[label] = default_open and true or false
  end
  local searching = settings_search_active()
  local open = searching or (state.settings_section_open[label] and true or false)
  local w = r.ImGui_GetContentRegionAvail(ctx)
  local h = 28
  r.ImGui_InvisibleButton(ctx, "##sec_" .. label, w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  if (not searching) and r.ImGui_IsItemClicked(ctx, 0) then
    open = not open
    state.settings_section_open[label] = open
  end
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local bg = open and UI_THEME.accent_fill or (hovered and UI_THEME.surface_hvr or UI_THEME.surface)
  local border = open and UI_THEME.accent or (hovered and UI_THEME.border_hvr or UI_THEME.border)
  ui_draw_panel(dl, x0, y0, x1, y1, 7.0, bg, border, hovered, active)
  local cy = (y0 + y1) * 0.5 + (active and 1.0 or 0.0)
  ui_button_draw_icon(dl, open and "chev_down" or "chev_right", x0 + 14, cy, 14, open and UI_THEME.accent_hvr or UI_THEME.text_dim)
  local tw, th = r.ImGui_CalcTextSize(ctx, label)
  r.ImGui_DrawList_AddText(dl, x0 + 28, cy - th * 0.5, open and UI_THEME.text or UI_THEME.text_dim, label)
  state.settings_filter_section_title_hit = searching and settings_matches(label)
  return open
end

function settings_render_scan_folders()
  if settings_show("Add Folder", "scan", "folder") then
    if draw_ui_button("settings_add_folder", "Add Folder", nil, nil, { style = "primary" }) then
    local new_folder = ""

    -- Try JS_Dialog_BrowseForFolder first (from JS_ReaScriptAPI extension)
    if r.APIExists("JS_Dialog_BrowseForFolder") then
      local retval, selectedFolder = r.JS_Dialog_BrowseForFolder("Choose folder to scan", "")
      if retval == 1 and selectedFolder and selectedFolder ~= "" then
        new_folder = selectedFolder
        log("JS_Dialog_BrowseForFolder returned: " .. tostring(selectedFolder))
      else
        log("JS_Dialog_BrowseForFolder cancelled or failed. retval=" .. tostring(retval))
      end
    else
      log("JS_Dialog_BrowseForFolder not available - JS_ReaScriptAPI extension may not be installed")
    end

    -- Only show fallback dialog if JS dialog didn't work
    if new_folder == "" and not r.APIExists("JS_Dialog_BrowseForFolder") then
      r.ShowMessageBox("JS_ReaScriptAPI extension is required for folder browsing.\n\nPlease install it via ReaPack:\nExtensions > ReaPack > Browse Packages > Search for 'js_ReaScriptAPI'", "Extension Required", 0)
    end

    -- Normalize and validate folder path before adding
    if new_folder and new_folder ~= "" then
      new_folder = normalize_path(new_folder)
      if string.len(new_folder) < 2 or new_folder:match("^%d+$") then
        r.ShowMessageBox("Invalid folder path: " .. new_folder .. "\n\nPlease select a valid folder.", "Error", 0)
        log("Rejected invalid folder path: " .. new_folder)
      else
        local exists = false
        for _, f in ipairs(state.folders) do
          if f == new_folder then exists = true break end
        end
        if not exists then
          table.insert(state.folders, new_folder)
          refresh_scan_folder_availability()
          explorer_invalidate_cache(new_folder)
          save_config()
          log("Added folder: " .. new_folder)
        else
          log("Folder already in list: " .. new_folder)
        end
      end
    end
  end
  end

  if #state.folders > 0 then
    if settings_show("Add Folder", "scan", "folder") then
      r.ImGui_SameLine(ctx)
      r.ImGui_TextColored(ctx, UI_THEME.text_dim, string.format("%d folder%s", #state.folders, #state.folders == 1 and "" or "s"))
    end

    local child_flags = 0
    if r.ImGui_ChildFlags_Border then child_flags = r.ImGui_ChildFlags_Border end

    -- Size the list to its contents (capped) so there is no large empty area.
    local row_h = r.ImGui_GetTextLineHeightWithSpacing(ctx)
    local visible_rows = math.min(#state.folders, 8)
    local list_h = visible_rows * row_h + 10
    if r.ImGui_BeginChild(ctx, "folder_list", 0, list_h, child_flags) then
      for idx, folder in ipairs(state.folders) do
        local norm_folder = normalize_path(folder)
        local offline = false
        local vol = volume_root_from_path(norm_folder)
        if (vol and state.missing_volumes[vol]) or state.missing_scan_folders[norm_folder] then
          offline = true
        end
        if settings_show(folder, offline and "offline" or nil, "Remove", "Rescan", "Browse") then
          if draw_ui_button("settings_remove_folder_" .. idx, "Remove", nil, nil, { style = "danger", compact = true }) then
            table.remove(state.folders, idx)
            filter_samples_by_folders()
            refresh_scan_folder_availability()
            explorer_invalidate_cache()
            save_config()
            break
          end
          r.ImGui_SameLine(ctx)
          if draw_ui_button("settings_rescan_folder_" .. idx, "Rescan", nil, nil, { style = "primary", compact = true }) then
            enqueue_scan(folder)
          end
          r.ImGui_SameLine(ctx)
          if draw_ui_button("settings_browse_folder_" .. idx, "Browse", nil, nil, { compact = true }) then
            state.explorer_open = true
            state.explorer_open_dirs[norm_folder] = true
            explorer_invalidate_cache(norm_folder)
            save_config()
          end
          r.ImGui_SameLine(ctx)
          r.ImGui_AlignTextToFramePadding(ctx)
          if offline then
            r.ImGui_TextColored(ctx, UI_THEME.text_dim, folder .. "  (offline)")
          else
            r.ImGui_Text(ctx, folder)
          end
        end
      end
      r.ImGui_EndChild(ctx)
    end
  elseif settings_show("Add Folder", "scan", "folder") then
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, "No folders yet. Click Add Folder to add scan folders.")
  end
end

function settings_render_map()
  if settings_show("Y axis", "Brightness", "Dominant frequency", "Weight", "audible length") then
    r.ImGui_Text(ctx, "Y axis")
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, "How samples are spread vertically. X stays audible length.")
    r.ImGui_Spacing(ctx)
  end

  local axis = map_y_axis_id()
  if settings_show("Brightness", "Spectral centroid") then
    if draw_ui_radio("map_y_brightness", "Brightness", axis == "brightness") then
      apply_map_y_axis("brightness")
    end
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, "Spectral centroid. Dark / thud at the bottom, clicky / bright at the top.")
    end
  end
  if settings_show("Dominant frequency", "pitch") then
    if draw_ui_radio("map_y_freq", "Dominant frequency", axis == "dominant_freq") then
      apply_map_y_axis("dominant_freq")
    end
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, "Strongest pitch. Better for 808s, bass, and tonal samples.")
    end
  end
  if settings_show("Weight", "subby", "heavy") then
    if draw_ui_radio("map_y_weight", "Weight", axis == "weight") then
      apply_map_y_axis("weight")
    end
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, "How subby / heavy the sample is. Heavy at the top, light at the bottom.")
    end
  end
end

